-- ============================================================
-- Content Seed — HİSSƏ 9/13: DB kontentinin ru/tr tərcümələri
-- COALESCE + guarded UPDATE — mövcud/əl tərcümələri qorunur (idempotent).
-- Hissələri istənilən ardıcıllıqla, istənilən qədər təkrar işlətmək təhlükəsizdir.
-- Cəmi: 12258 UPDATE, 13 hissə
-- ============================================================

UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğiniz artık "hayır" kelimesinin anlamını tam kavrıyor. Tehlikeli bir şey yaparken "hayır" dediğinizde durup size bakabilir, hatta itiraz olarak ağlayabilir de. Bu, sınırları öğrenmesinin başlangıcıdır. Ama evin her yeri "hayırlarla" dolu olmasın. Tehlikeli eşyaları kaldırın ki özgürce "evet" diyebileceği oyunlarla uğraşsın. Sınırları yalnızca gerçekten önemli noktalarda koyun.') WHERE id = 'a85e4f35-e664-455a-b825-3e51d17e5f0d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Nesne kalıcılığı" oyunu: Bebeğiniz artık oyuncağı battaniyenin altına saklasanız da onun yok olmadığını biliyor. Oyuncağı yarım saklayın ve bulmasına izin verin. Bu oyun hafızasını ve mantıksal düşünmesini güçlendirir. Aynı zamanda saklambaç oyunu ayrılık korkusunu azaltmaya yardımcı olur; gözden kaybolsanız da mutlaka geri döneceğinizi anlıyor.') WHERE id = '0a1f58ae-f05c-4b6b-aa75-6ff0b27beddc';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Tutunarak ayağa kalkma ustalığı: Bebeğiniz artık her yerde ayağa kalkıyor; koltuk kenarından, sandalye ayağından, hatta sizin dizlerinizden tutunarak. Bu sırada inmeyi henüz bilmeyebilir ve dik durup yardım için ağlayabilir. Ona nasıl oturması gerektiğini gösterin; dizlerini bükerek yavaşça yere indirin. Bu, beden yönetimini ve denge duygusunu şekillendirecek.') WHERE id = 'd5785d23-fd09-4663-8877-2740ab81ecbc';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Gece uykusunda "motor uyanışlar": Bebeğiniz gece uykusunda aniden emekleyebilir ya da uykulu hâlde ayağa kalkmaya çalışabilir. Beyni, gündüz öğrendiği hareketleri gece tekrarlıyor. Ağlamıyorsa ona dokunmayın; bırakın pozisyonunu kendisi bulup yeniden uyusun. Ağlıyorsa sessizce yanına gidin, ışığı açmadan yerine yatırın ve sakinleştirici sözler söyleyin. Bu dönem geçicidir.') WHERE id = '3ee50fc0-987b-4449-9a9a-aeac43eacebb';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Diş çıkarma ve beslenme: 9. ayda genellikle üst veya alt yan kesici dişler çıkar. Bu dönemde damakları ağrıdığı için bebek katı yiyecekleri reddedebilir. Onu zorlamayın; birkaç gün daha yumuşak ve serin yiyecekler (örneğin soğuk meyve püresi veya yoğurt) verin. Diş çıkarma süreci biter bitmez iştahı geri gelecek. Sabrınız ve şefkatiniz onun için en büyük ilaçtır.') WHERE id = '5c734779-7b9a-4eb8-a3df-dadd22df3bb2';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Tebrikler, 250 günlük büyük bir yolu geride bıraktık! Bebeğiniz artık yüz ifadelerinizi çok isabetli okuyor. Siz sevinince o da gülüyor; ciddi bir tonla konuştuğunuzda durup gözlemliyor. Bugün onunla yerde "kitap bakma" saati geçirin. Büyük resimli bir kitapta hayvanları gösterin ve seslerini çıkarın. Sizi taklit etmeye çalışacak. Siz onun dünyayı keşfetmesi için en güvenilir rehbersiniz, anne!') WHERE id = '4168c3b6-34fd-49a6-b076-88e5415caa27';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Artık 9. ayın tam ortasındasınız! Bebeğiniz nesnelere tutunarak ayağa kalkmakta ustalaşıyor. Ama en önemli beceri henüz önde: ayakta durduğu yerden güvenli şekilde yere oturmak. Ona dizlerini bükerek yavaşça oturmayı gösterin. Sırtüstü düşerse bağırıp onu korkutmayın; sadece yanına gidin ve doğru hareketi yeniden gösterin. Bu, beden koordinasyonunu güçlendirir.') WHERE id = '8802254f-c7f7-4ff6-9b20-d9c01f14b494';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğin jestlerle iletişimi artık anlam kazanıyor. İstediği oyuncağa parmağıyla işaret edebilir (pointing). Bu, bilişsel gelişimde büyük bir sıçramadır! Dikkatini sizinle paylaşmak istiyor. Bir şeyi gösterdiğinde hemen adını söyleyin: "Evet, bu top! Topu mu istiyorsun?". Bu, kelimelerle nesneler arasındaki bağı beyninde pekiştirmesine yardımcı olur.') WHERE id = '425f3229-dceb-43c5-a7c7-021a098be008';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Beslenmede çeşitlilik ve yeni dokular: Artık püreyi tamamen unutabilirsiniz. Yemekleri sadece çatalla ezerek bebeğe sunun. Damakları, yumuşak pişmiş et parçalarını veya sebzeleri ezecek kadar güçlü. Çiğneme hareketi yalnızca sindirim için değil, konuşma kaslarının gelişimi için de gereklidir. Bazı parçaları tükürürse endişelenmeyin; yeni hislere alışıyor.') WHERE id = '04975f3b-94a9-41da-8a0a-2994a09d6287';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bardaktan su içme alışkanlığını pekiştirin. Bebeğiniz artık bardağı iki eliyle tutmaya çalışabilir. Ona plastik veya silikon küçük bir bardakta su verin. İlk zamanlar suyun yarısı üstüne dökülecek; bu çok normal. Açık bardaktan içmek, dilin ve çenenin doğru gelişimi için biberondan daha faydalıdır. Bu, bağımsızlığına doğru atılan bir sonraki adımdır.') WHERE id = '2fd76c93-94cc-41aa-af0c-928b17fbd06d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal oyunlar: "Ver-al" oyunu artık en sevdiği uğraşa dönüşüyor. Ondan oyuncağı istediğinizde size uzatabilir (bazen geri çekse de!). Bu oyun, sıra alma ve paylaşma kavramının temelidir. Ona "çok teşekkürler" demeyi unutmayın. Olumlu tepkinizi gördükçe bu tür sosyal davranışları daha sık tekrarlamaya heveslenecek.') WHERE id = '7c3fd582-3962-47a8-9de8-b81ab68183e7';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Cımbız tutuşu" (pincer grasp) artık mükemmelleşti. Bebek, yerdeki en küçük toz zerresini bile tutabiliyor. Bu beceriyi geliştirmek için ona iyi pişmiş baklagiller (örneğin nohut veya mercimek) sunabilirsiniz. Bu aynı zamanda dikkatini toplamasına da yardımcı olur. Ama unutmayın: bulduğu her ufak şeyi ağzına götürecek; bu yüzden yerde tehlikeli küçük nesnelerin olmamasına sürekli dikkat edin.') WHERE id = 'fda4720c-d3a0-4bf6-82ad-06eddb719108';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğin hafızası artık birkaç gün önce yaşanan olayları saklayacak kadar güçlendi. Sevdiği oyuncağın nereye saklandığını hatırlayabilir. Onunla daha karmaşık saklambaç oyunları oynayın. Örneğin oyuncağı bir örtünün altına saklayın ve bulmasını izleyin. Bu, hem mantıksal düşünmesini hem de nesnelerin kaybolmadığını, sadece saklandığını anlamasını (nesne kalıcılığını) geliştirir.') WHERE id = '2c349583-ad28-47b1-aaec-34168c563082';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Tutunarak yürüme (cruising) giderek hızlanıyor. Bebeğiniz koltuk boyunca bir uçtan diğerine koşarcasına gidebilir. Bu aşamada ona ayakkabı giydirmeyin. Çıplak ayakla veya kaydırmaz çorapla hareket etmek, ayak tabanının ve parmakların doğru şekillenmesi için idealdir. Zeminin dokusunu hissettikçe dengesini daha iyi koruyacak.') WHERE id = 'e21e8596-3f21-4200-9b5c-b7f1ca90251a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Diş çıkarma sırasında damakların kaşınması ve ağrısı bebeğin gece uykusunu etkileyebilir. Bebeğiniz uykuda huzursuzsa damaklarına temiz, nemli ve serin bir bezle hafifçe masaj yapın. Diş çıkarma döneminde iştahın azalması da normaldir; onu zorlamayın, daha çok sıvı ve anne sütü/mama sunun. Şefkatiniz onun en büyük ağrı kesicisidir.') WHERE id = 'c0bb1b1a-709a-4043-a236-fe5cfd9ea7eb';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Tebrikler, 260 gün doldu! Bebeğiniz artık adını her zaman tanıyor ve seslendiğinizde hemen size dönüyor. Aile üyelerini diğerlerinden net biçimde ayırt ediyor ve size özel bir bağlılık gösteriyor. Bugün onunla yerde "kitap okuma" saati geçirin; o resimleri göstersin, siz adlarını söyleyin. Siz onun en güvenilir öğretmeni ve kahramanısınız, anne!') WHERE id = '122b28c9-a9e8-422e-9381-d9406e97f79b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Artık 9. ayın son on gününe giriyoruz. Bebeğiniz ayakta dururken bir elini koltuktan kesip diğer eliyle oyuncağa uzanabiliyor. Bu, denge duyusunun ne kadar geliştiğini gösterir. Bu dönemde çevresinde tutunabileceği sağlam mobilyaların olduğundan emin olun. Artık kendi gücünü sınıyor ve yakında ilk bağımsız adımı için cesaret toplayacak.') WHERE id = '4ac0d7bc-e3ee-464a-a0d8-d71c88bce550';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde yeni başarı: Bebeğiniz artık iki nesneyi aynı anda birbirine vurarak ses çıkarmayı çok seviyor. Bu, iki elin koordineli çalışmasıdır. Ona iki tahta küp ya da plastik kap verin ve nasıl takırdattığını izleyin. Bu basit hareket hem işitme duyusunu hem de hareket planlamasını (motor planning) güçlendirir. Müzik ritimleriyle bu oyunu daha da ilginç hâle getirebilirsiniz.') WHERE id = 'fddb995c-a311-44d6-a424-3f063a465828';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Beslenmede çeşitlilik: Henüz denemediyseniz, beslenmeye lor veya yoğurtla birlikte küçük yumuşak meyve parçaları eklemenin tam zamanı. Bebeğin çiğneme hareketleri artık daha düzenli. Yemeği tamamen ezilmiş değil, küçük parçalar hâlinde vermek damaklarının güçlenmesine ve ileride aile sofrasına tam uyum sağlamasına yardımcı olur. Kendi kendine yemesine imkân tanıyın; bu, özgüvenini artırır.') WHERE id = 'b230cf28-523f-407d-9888-06b6c53bb3a6';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal iletişimde "taklit" dönemi: Bebeğiniz artık yüz ifadelerinizi, çıkardığınız sesleri ve hatta hapşırmanızı bile taklit edebilir. Sizi dikkatle gözlemliyor ve öğreniyor. Karşısında çeşitli hareketler yapın (örneğin dilinizi çıkarın ya da göz kırpın); bakalım sizi tekrarlayacak mı? Bu taklit becerisi, sosyal uyumunun ve öğrenme yeteneğinin en güçlü aracıdır.') WHERE id = '671adb79-58b3-4617-94e4-bb4071a9a5ba';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Nesne kalıcılığı" artık tamamen oluştu. Bebek, oyuncağı cebinizde sakladıysanız onun yok olmadığını, sadece cebinizde olduğunu biliyor. Sizi arayacak, cebinizi çekiştirecek. Bu hafıza egzersizi mantıksal düşünmesini geliştirir. Onunla saklambacı daha karmaşık biçimlerde oynayın; bu aynı zamanda ayrılık kaygısını (separation anxiety) azaltmaya da yardımcı olacak.') WHERE id = '6997dc99-18bc-4bdc-bae3-c34fc9c367dc';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bardaktan su içme alışkanlığını pekiştirin. Bebeğiniz bardağı tutup ağzına götürmeye çalışırken artık suyun miktarını ayarlamayı öğreniyor. İlk zamanlar suyun yarısı kıyafetine dökülebilir, endişelenmeyin. Açık bardaktan içmek, dil ve dudak kaslarının doğru gelişimi için çok önemlidir. Bu beceri, ileride konuşmasının daha net olmasına zemin hazırlar. Sabırlı olun; bu bir öğrenme sürecidir.') WHERE id = '85d33873-230f-4ec2-aeb2-c03aab1bc8c9';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Tutunarak yürüme (cruising) artık çok hızlandı. Bebek, koltuk boyunca koşuyormuş gibi hareket ediyor. Bu aşamada evdeki güvenlik önlemlerini bir kez daha gözden geçirin. Mobilyaların keskin köşeleri, sarkan masa örtüleri ya da yerdeki elektrik kabloları artık daha büyük risk taşıyor. Bebek her şeyi çekip kendine doğru almak istiyor. Güvenli ortam, keşif hevesini bastırmadan gelişmesine imkân verecek.') WHERE id = '6cb85c30-34e6-4f9c-a6d7-47b0e62b9c27';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Dil gelişiminde "jargon" dönemi: Bebeğiniz artık kendi dilinde upuzun "hikâyeler" anlatıyor. Kelimeleri anlamasanız da büyüklerin konuşma tonlamasını kusursuz taklit ediyor. Onu dikkatle dinleyin, sorular sorun ve "Öyle mi? Sonra ne oldu?" diye karşılık verin. Bu "diyalog", kendini ifade etme isteğini güçlendirir ve beynindeki kelime dağarcığını zenginleştirir.') WHERE id = '56798677-523b-4029-94dd-1e80eef243c7';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Diş çıkarma sırasında damakların kaşınması ve ağrısı bebeğin gece uykusunu etkileyebilir. Bebeğiniz uykuda huzursuzsa damaklarına temiz, nemli ve serin bir bezle hafifçe masaj yapın. Diş çıkarma döneminde iştahın azalması da normaldir; onu zorlamayın, daha fazla sıvı ve anne sütü/mama önerin. Şefkatiniz onun en büyük ağrı kesicisidir.') WHERE id = '953f792e-f8bd-44cc-a2d0-c3b8471c1a51';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Tebrikler, 9 ayı tamamladık! Bebeğiniz artık adını her zaman tanıyor ve seslendiğinizde hemen size dönüyor. Aile üyelerini diğerlerinden net biçimde ayırt ediyor ve size özel bir bağlılık gösteriyor. Bugün onunla yerde "kitap okuma" saati geçirin; o resimleri göstersin, siz adlarını söyleyin. Siz onun en güvenilir öğretmeni ve kahramanısınız, anne!') WHERE id = 'b5fee624-3a8a-4073-bf22-e9bf23545a25';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '10. aya hoş geldiniz! Bu ay bebeğin "bağımsızlık bildirgesi" ayı sayılabilir. Artık nesnelerden tutunarak ayakta daha güvenle duruyor ve hatta birkaç saniyeliğine desteksiz kalmayı deniyor. Bu küçük denge anları ilk adımların müjdecisidir. Onun için geniş ve güvenli bir alan yaratın. Unutmayın; her düşüş ona yer çekimini ve bedenini nasıl yöneteceğini öğretir. Sadece yanında olun ve cesaretlendirin.') WHERE id = '162ad9af-c711-43da-b203-5c312cf418b0';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğin konuşmasında "ma-ma", "ba-ba" ya da "da-da" gibi kelimeler artık tamamen anlam kazanıyor. Bu kelimeleri söylerken size veya babasına bakıyorsa, nesneyle kelimeyi ilişkilendirmiş demektir. Siz de ona cevap verirken basit ve net cümleler kurun. Örneğin o "top" dediğinde "Evet, bu kırmızı top" diyerek kelime dağarcığını zenginleştirin. Her cevabınız beyninde yeni dil bağlantıları kurar.') WHERE id = 'be8f3e1a-5335-4ace-960c-562783ff9dcb';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Beslenmede yeni bir aşama: "Cımbız tutuşu" (pincer grasp) o kadar gelişti ki bebek, küçük bir bezelye tanesini veya yumuşak pişmiş havuç dilimini rahatça tutup ağzına götürebiliyor. Ona kendi başına yemesi için daha çok fırsat verin. Bu hem motor becerilerini hem de doyma hissini kendisinin yönetmesini güçlendirir. Ortalığın batmasından korkmayın; bu "yaratıcı dağınıklık" gelişimi için önemlidir.') WHERE id = '58ffad0f-55f8-47af-b047-3975e8528016';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğiniz sizi taklit etmekte artık ustalaştı. Siz telefonla konuşurken o da eline bir şey alıp kulağına tutuyor; siz saçınızı tararken o da benzer hareket yapıyor. Bu, "işlevsel taklit" dönemidir. Ona güvenli ev eşyaları (plastik tarak, oyuncak telefon, tahta kaşık) vererek bu becerisini destekleyin. Dünyayı sizi izleyerek öğreniyor; bu yüzden davranışlarınızda örnek olmaya çalışın.') WHERE id = 'a6c8ab18-10f6-4956-855e-8fca749308ef';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Nesne kalıcılığı" oyunu: Bebeğiniz artık oyuncağı bir kabın içine koyup üstünü örtseniz de yok olmadığını biliyor. Onunla daha karmaşık saklambaç oyunları oynayın. Örneğin oyuncağı iki farklı örtüden birinin altına saklayın ve bulmasını izleyin. Bu, hem hafızasını hem de dikkatini toplama becerisini artırır. Sorunu çözdüğünde onu coşkuyla övün.') WHERE id = '535f32b7-37dd-475b-9f52-55c5a1160920';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Tutunarak yürüme (cruising) artık tamamen otomatikleşti. Bebek koltuğa tutunarak odanın bir ucundan diğerine koşarcasına gidebiliyor. Bu aşamada evdeki güvenliği bir kez daha kontrol edin: sarkan masa örtüleri, yerdeki elektrik kabloları ve keskin köşeler artık daha büyük risk. Her şeyi çekmek ve tırmanmak istiyor. Güvenli ortam ona özgür keşif şansı verir.') WHERE id = 'd10583a3-e400-4339-b85b-3d395175b72a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal iletişimde yeni jestler: Bebeğiniz artık istediği şeyi parmağıyla gösteriyor (pointing). Bu, bilişsel gelişimde büyük bir sıçramadır. Dikkatini sizinle paylaşmak istiyor. Bir şeyi gösterdiğinde hemen adını söyleyin: "Evet, bu kuş! Bak, kuş uçuyor". Bu hem kelime dağarcığını artırır hem de sizinle olan duygusal bağını güçlendirir. Merakına kayıtsız kalmamanız çok önemlidir.') WHERE id = '1c394285-7074-4a0d-ac82-eab79473970a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bardaktan su içme becerisini geliştirin. Bebeğiniz artık bardağı iki eliyle tutup dengelemeye çok yakın. Ona plastik veya silikon küçük bir bardakta az miktarda su verin. Suyun dökülmesi öğrenmenin bir parçasıdır. Açık bardaktan içmek, dil ve dudak kaslarının doğru gelişimi için biberondan daha faydalıdır ve ileride konuşmasının daha net olmasına yardımcı olur.') WHERE id = '863feabb-ad16-4aad-8a94-087f99977902';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Diş çıkarma süreci devam ediyorsa bebeğin uykusu ve iştahı yeniden bozulabilir. 10. ayda genellikle üst veya alt yan kesici dişler çıkar. Damakları çok kaşınıyorsa ona soğutulmuş (ama buzlu olmayan) diş kaşıyıcılar veya serin sebze dilimleri (gözetim altında) verin. Bu dönemde daha çok sıvı ve anne sütü sunmak onu hem hidratlar hem de sakinleştirir. Şefkatiniz en iyi ağrı kesicidir.') WHERE id = '22dd56cb-e699-4f81-b502-66f9d54e2b23';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Tebrikler, 280 günü tamamladık! Bebeğiniz artık adını her seslenişinizde tanıyor ve kararlılıkla tepki veriyor. Sevdiği oyuncağı ya da kişiyi seçebiliyor, kendi "karakterini" göstermeye başlıyor. Bugün onunla yerde uzanın ve sadece "taklit" oyunu oynayın; o ses çıkarsın siz tekrarlayın, siz el çırpın o tekrarlasın. Siz onun dünyayı keşfettiği en güvenilir limansınız, anne!') WHERE id = '71654afe-3791-4e59-a41c-7da09d0ef29c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Artık 10. ayın tam ortasındasınız! Bebeğiniz nesnelere tutunarak ayağa kalkmakta ustalaştı ve hatta birkaç saniyeliğine ellerini bırakıp serbest durmayı deniyor. Bu, denge merkezinin ve bacak kaslarının ne kadar güçlendiğini gösterir. Serbest durması için baskı yapmayın; kendini hazır hissettiğinde bu adımı atsın. Onun için çevresi yumuşak yastıklarla çevrili, güvenli bir "oyun alanı" oluşturun ki düşmekten korkmasın.') WHERE id = '03d76f01-bcab-4644-9f10-2526c187201c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğin konuşmasında yeni aşama: "Jargon" konuşmaları! Sanki size bir şey anlatıyormuş gibi upuzun, tonlamalı ve duygusal "cümleler" kuruyor. Henüz hiçbir kelimeyi anlamasanız da bu, gelecekteki konuşmasının temelidir. Onu dikkatle dinleyin, "Öyle mi? Çok ilginç, sonra ne oldu?" diye karşılık verin. Bu tür diyaloglar kendini ifade etme isteğini artırır ve beynindeki kelime dağarcığını hızla zenginleştirir.') WHERE id = 'e6d2e0ec-fef4-4fdf-bd36-60be17d3ab5e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Beslenmede doku geçişini tamamlayın. Püre dönemi artık tamamen geride kalmalı. Yemekleri sadece çatalla ezerek ya da küçük yumuşak parçalar hâlinde (finger foods) sunun. Damakları, yumuşak pişmiş eti veya sebzeyi ezecek kadar güçlü. Bu, çiğneme alışkanlığını güçlendirir ve ileride "yemek seçme" sorunlarını önler. Sabırlı olun; her yeni doku bir öğrenme deneyimidir.') WHERE id = '25d3da74-5500-488e-93bc-4e022b9fdf57';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal oyunlarda "sıra alma" alışkanlığı: Bebeğiniz artık "bana ver", "sana vereyim" oyununu daha iyi anlıyor. Ona bir oyuncak uzatın, sonra "şimdi topu sen bana ver" diyerek geri isteyin. Veriyorsa onu coşkuyla övün. Bu oyun, paylaşma kavramının ve karşılıklı iletişim kurallarının temelidir. Aynı zamanda el-göz koordinasyonunu ve bırakma (release) becerisini mükemmelleştirir.') WHERE id = '639df12e-60c1-4322-9712-2375f1060042';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "kategoriler": Bebeğiniz artık benzer nesneleri ayırt etmeye başlıyor. Örneğin farklı biçimlerdeki topların hepsinin "top" olduğunu kavramaya çok yakın. Ona farklı renk ve boyutlarda toplar veya küpler gösterin. Bu, soyut düşüncesinin ilk adımlarıdır. Oyun oynarken nesnelerin rengini ve şeklini seslendirin: "Bu büyük araba, bu ise küçük araba".') WHERE id = '4207275f-8c9b-455a-be42-c07fcdc66c91';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Cımbız tutuşu" (pincer grasp) artık tam ustalık seviyesinde. Bebek, yerde gördüğü en küçük kırıntıyı bile başparmağı ve işaret parmağıyla tutuyor. Bu beceriyi daha da geliştirmek için ona iyi pişmiş mercimek taneleri veya küçük yumuşak lor parçaları verin. Dikkat: bu beceri, bulduğu her tehlikeli küçük nesneyi (düğme, boncuk) aynı çeviklikle ağzına götürebileceği anlamına da gelir. Evin temizliği şimdi her zamankinden daha önemli.') WHERE id = 'd9053aab-2643-4a33-bd40-377294e7163f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Tutunarak yürüme (cruising) o kadar hızlandı ki bebek, koltuk kenarında neredeyse koşuyor. Bu aşamada evdeki mobilyaların sağlamlığına bir kez daha dikkat edin. Çekerek her şeye tırmanmak istiyor. Sarkan masa örtülerini kaldırın; çünkü onlardan tutunup kalkmaya çalışırsa her şeyi üzerine devirebilir. Güvenli ortam özgüvenini artırır ve korkusuzca keşfetmesine imkân tanır.') WHERE id = '22ae7b1e-0f5e-4f2c-a0b9-f363eec03221';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Kendini tanıma: Bebeğiniz artık aynadaki yansımanın kendisi olduğunu anlamaya başlıyor. Burnuna küçük renkli bir leke koyup aynaya baktırırsanız, kendi yüzündeki lekeyi silmeye çalışacak (buna "ruj testi" denir). Bu, benlik bilincinin (self-awareness) gelişimidir. Onunla aynanın karşısında durup "bu senin burnun, bu ise annenin burnu" diyerek farkları gösterin. Bu, beden şemasını oluşturmak için de harika bir egzersizdir.') WHERE id = 'aee72c71-4ab2-40ae-a72a-f441c99bcf9d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Gece uykularında "ayrılık kaygısı" yeniden kendini gösterebilir. Bebek uyandığında sizi göremeyince hemen ağlayabilir. Ona güven vermek için yanına gidin, ışığı açmadan sessizce okşayın ve "anne burada, uyu" diye fısıldayın. Onu hemen kucağa alıp odadan çıkarmak için acele etmeyin; bırakın varlığınızı hissedip kendisi yeniden uykuya dalmaya çalışsın. Sabrınız bu dönemin daha rahat geçmesine yardımcı olacak.') WHERE id = '807f6974-949a-4673-9e12-ca050a097e4d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Tebrikler, 290 günü tamamladık! Bebeğiniz artık bir kişilik olarak karakterini gösteriyor: neyi sevdiği, neyden korktuğu, hangi yemeği tercih ettiği... Bugün onunla yerde uzanın ve sadece onun yönettiği bir oyun oynayın. Bırakın o sizi "yönlendirsin"; oyuncağı size versin ya da sizi taklit etsin. Onunla geçirdiğiniz her dakika, gelecekteki mutluluğunun temelidir. Muhteşem bir yol katettiniz, anne!') WHERE id = '2489cf6a-6c9a-4826-ac80-afae063dcb86';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '10. ayın son on gününe hoş geldiniz! Bebeğiniz artık bir elinden tuttuğunuzda güvenle adımlıyor mu, yoksa hâlâ desteksiz durmaya cesaret mi edemiyor? İki durum da normaldir. Bazı bebekler 10. ayda yürür, bazıları 15-16 aya kadar bekler. Bacak kaslarını güçlendirmek için yerde daha çok vakit geçirmesine izin verin. Kendi gücüne güvendiği an ilk bağımsız adımıyla size sürpriz yapacak!') WHERE id = '96dedeae-65fd-4082-8b02-077d47cad21d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğin "nesne kalıcılığı" o kadar gelişti ki bir nesneyi kutunun içine koyup sonra çıkarmaktan hiç yorulmuyor. Bu "koyma ve çıkarma" oyunu hem mekân algısını hem de ince motor becerilerini güçlendirir. Ona farklı boyutlarda kaplar ve içlerine koyabileceği güvenli nesneler verin. Bu basit egzersiz, ileride karmaşık görevleri çözme becerisinin temelidir.') WHERE id = 'a8043f3c-dcb0-41ac-858a-58401aab3cc0';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada yeni bir sıçrama: Bebeğiniz artık bazı kelimeleri veya sesleri belirli olaylarla ilişkilendiriyor. Örneğin kapı zili çaldığında "baba" diyebilir ya da acıktığında özel bir ses çıkarabilir. Bu, bilinçli konuşmanın başlangıcıdır. Her sesli seslenişine dikkatle cevap verin: "Evet, kapı çaldı, gelen baba!". Bu "çevirileriniz" beynindeki kelimelerin anlamını tam pekiştirir.') WHERE id = '7f7f52b6-f75a-4125-9bb5-a72c5365ce29';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Beslenmede çeşitlilik: Artık bebeğin beslenmesine çok az miktarda (ve iyi pişmiş) tam tahıllar, yumuşak makarna veya ekmek içi ekleyebilirsiniz. Bu, farklı dokuları hissetmesine ve çiğneme alışkanlığını geliştirmesine yardımcı olur. Unutmayın; yemeklere hâlâ tuz ve şeker eklemiyoruz. Doğal tatlar, tat alma reseptörlerinin doğru şekillenmesi için en iyisidir.') WHERE id = 'b9f43156-8bbe-4d46-a470-47337a11cf3a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Ben kendim!" dönemi başlıyor. Yemek sırasında bebeğiniz kaşığı elinizden almaya ya da yemeği doğrudan elleriyle yemeye daha çok can atıyor. Bu bağımsızlık hevesini bastırmayın. Bırakın elleri bulansın, yüzü gözü püre olsun. Bu süreç özgüvenini artırır ve yemekle olumlu ilişki kurmasına yardımcı olur. Sabrınız, ileride iştahlı ve özgür bir çocuk olmasına zemin hazırlar.') WHERE id = 'b31abab7-200d-4d55-b197-62b606e68100';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal beceriler: Bebeğiniz artık "bay bay" (el sallamak) ya da "öpücük göndermek" (havadan öpücük) gibi jestleri taklit edebilir. Bu jestler, konuşma öncesi iletişim biçimleridir. Siz el salladığınızda o da sizi tekrarlıyorsa bu, size olan bağlılığını ve dikkatini gösterir. Bu hareketleri şarkılarla birleştirerek daha eğlenceli hâle getirin. Her jestine sevinçle karşılık verin ki iletişim kurma hevesi artsın.') WHERE id = 'db90e8f1-9d73-4d53-8169-2122571f4a13';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Güvenlikte yeni bir seviye: Bebek artık yükseğe tırmanmaya meyilli. Alçak sehpalar, koltuk kenarları onun için birer "zirve". Evdeki tüm ağır eşyaların ve mobilyaların sağlamlığını kontrol edin. Özellikle elektrik kablolarını gizleyin; çünkü onları çekmek en büyük merakı olabilir. Evin güvenliği size huzur, ona ise geniş bir keşif alanı sağlayacak.') WHERE id = 'cd4b7de4-c97d-44b4-ae4b-d87984914859';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Gece uykusu ve bilişsel gelişim: Bebeğiniz gece uyandığında sizi göremeyince yüksek sesle ağlayabilir. Bu dönemde ona güven vermek önemlidir. Yanına gittiğinizde ışığı açmadan, sakin bir sesle "anne burada, uyu" diyerek okşayın. Onu hemen kucağa alıp odadan çıkarmak için acele etmeyin. Sadece orada olmanız ve sesiniz, yeniden uykuya dalması için yeterli güveni verecektir. Bu, "ayrılık kaygısının" geçici bir evresidir.') WHERE id = 'd5f8c50f-64e6-4aba-ad9f-5604b24fb65b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Yarın bebeğinizin tam 300 günü doluyor! Bu 10 ayda inanılmaz bir yol katetti: çaresiz bir bebekten kendi karakteri, istekleri ve becerileri olan küçük bir insana dönüştü. Siz de bu sürede büyük bir deneyim kazandınız. Bugün onunla yerde uzanın ve sadece gülüşünü izleyin. Sevginiz, gelişiminin en büyük motorudur.') WHERE id = '2638511c-740a-477b-ab58-1fbe5fd5c94a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Tebrikler! Bebeğinizin 300 günü doldu! Bu, bir yılın tamamlanmasına doğru son büyük durak. Bebeğiniz artık adını her seslenişte tanıyor, duygularını net gösteriyor ve belki de ilk adımlarını atmaya hazırlanıyor. Bugünü onunla özel bir oyunla ya da sevdiği bir meyveyle kutlayın. Muhteşem bir iş başardınız, anne! 300 günlük emeğin karşılığı, her gün size bakan o mutlu gözlerde.') WHERE id = '4dbc6d6a-ae47-4867-ba96-b66058f91a2f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '11. aya hoş geldiniz! İlk doğum gününe sadece iki ay kaldı. Bu dönemde bebeğiniz "ben" ve "sen" arasındaki farkı daha iyi anlıyor. Yüz ifadelerinizi taklit ederek duygusal zekâsını geliştiriyor. Siz üzgünken o da ciddi görünebilir; siz gülünce kahkaha atar. Onunla duygular hakkında konuşun; bu, ileride kendi duygularını yönetmesi için büyük bir temeldir.') WHERE id = '9a834d06-30b3-4c6c-92b2-859a3c7000f4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğiniz bir elinden tuttuğunuzda artık çok mu güvenli yürüyor, yoksa hâlâ sadece koltuk kenarında mı ilerliyor? Bu günlerde dengesini korumak için ellerini yana açarak bir iki serbest adım atabilir. Bu "denge" hareketleri, beynindeki denge merkezini (vestibüler sistem) çalıştırır. Onu aceleye getirmeyin; bırakın güvenini tam bulsun.') WHERE id = 'a31576c9-38ba-4027-9aca-cbc63e6f334a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "isteklerin ifadesi": Bebeğiniz artık sadece ağlayarak değil; parmağıyla göstererek ve özel sesler çıkararak ne istediğini size anlatabiliyor. Oyuncağına doğru işaret ettiğinde "Evet, bu ayıcığı mı istiyorsun?" diyerek isteğini kelimelerle doğrulayın. Bu, onda "beni anlıyorlar" duygusunu yaratır ve ileride saldırgan davranışların (anlaşılmamaktan doğan ağlamaların) önüne geçer.') WHERE id = 'aa86788c-ff14-4450-8f10-2208ffcc316b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Beslenmede bağımsızlık: Bebeğiniz artık kaşığı tamamen kendisi tutup ağzına götürmek istiyor. Evet, yemeğin çoğu yerde ve önlükte olacak; ama bu, ince motor becerilerin ve el-göz koordinasyonunun en önemli egzersizidir. Ona kendine uygun, silikon veya kalın saplı bir kaşık verin. Siz de aynı anda başka bir kaşıkla yardım edebilirsiniz. Bu bir "takım çalışması" gibidir!') WHERE id = '3159f58c-c8a2-418a-a8bd-3b961ca0266e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "hayvan sesleri" dönemi! Bebeğiniz artık "köpek nasıl havlar?", "kedi nasıl ses çıkarır?" gibi sorulara kendi dilinde cevap vermeye başlayabilir. Bu, ses taklidi becerisinin zirvesidir. Hayvan resimleri olan kitaplara bakarak bu oyunları sürdürün. Sesleri taklit etmek, konuşma organlarını (dil, dudak kaslarını) gelecekteki karmaşık kelimelere hazırlar.') WHERE id = '43246706-501b-4546-a51a-8e59351b53c5';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Cımbız tutuşu" (pincer grasp) o kadar gelişti ki yerdeki en ince ipliği veya küçücük bir kırıntıyı bile kolayca tutuyor. Bu beceriyi sınamak için ona iyi pişmiş baklagiller (nohut, mercimek) sunabilirsiniz. Ama unutmayın: bulduğu her ufak şeyi ağzına götürme alışkanlığı da zirvede. Evin zemininin temizliği ve küçük nesnelerin olmaması en önemli güvenlik kuralınız olmaya devam ediyor.') WHERE id = '1053192f-a2a7-43d0-8335-34db00482590';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal oyunlarda karmaşıklaşma: Bebeğiniz "ver-al" oyununu artık başka bir seviyeye taşıyor. Oyuncağı size verip hemen geri isteyebilir ya da siz "ver" dediğinizde bilerek saklayabilir. Bunlar onun ilk "şakalarıdır". Bu mizah duygusuna gülüşle karşılık verin. Gülmek ve birlikte eğlenmek, aranızdaki duygusal bağı inanılmaz derecede güçlendirir.') WHERE id = '3451f734-1652-4c0f-97a4-7d508b0bb860';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Uyku düzeni ve uyanık kalma süresi: 11. ayda bebekler gündüz 2 uykudan 1 uykuya geçiş (nap transition) belirtileri gösterebilir; ama henüz acele etmeyin. Çoğu bebek 14-15 aya kadar 2 gündüz uykusuna ihtiyaç duyar. Sabah uykusuna zor dalıyorsa uyanık kalma süresini biraz uzatmayı deneyin (yaklaşık 3-3,5 saat). İyi dinlenmiş bebek, yeni becerileri daha hevesle öğrenir.') WHERE id = '852db72f-d9a2-475c-b994-d1ab8a6b4f97';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Mekân algısı": Bebeğiniz artık kutuların içine bakmayı, kapakları açıp kapatmayı ve nesneleri iç içe dizmeyi seviyor. Ona farklı boyutlarda plastik kaplar verin. Küçük kabın büyük kabın içine sığdığını keşfettiğinde beyninde karmaşık matematiksel ve mantıksal bağlantılar kurulur. Basit görünse de bu aslında büyük bir keşiftir.') WHERE id = '114fd473-c44c-4c3b-b5d0-19ac5cbf17e6';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Tebrikler, 310 günü tamamladık! Bebeğiniz artık iradesini gösteriyor: giyinmek istemediğinde ayaklarını diretiyor, sevdiği yemeği görünce ellerini çırpıyor. Bu "kişilik" belirtileri sizi bazen yorsa da aslında sağlıklı psikolojik gelişiminin göstergesidir. Bugün onunla yerde sadece onun istediği oyunu oynayın. İlginiz onun için dünyanın en büyük ödülüdür.') WHERE id = '2a98f756-8ee8-4fcc-b117-1adb344f61bd';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğiniz artık birkaç saniyeliğine ellerini bırakıp serbest durabiliyor mu? Bu, özgüveninin zirve noktasıdır. Henüz yürümese de bu denge anları, beynindeki denge merkezini (vestibüler sistem) mükemmelleştirir. Onu övün ve kucağınızı açarak size doğru bir adım atması için cesaretlendirin. Her küçük deneme, büyük bir adımın müjdecisidir!') WHERE id = '94901ac5-33b9-4db0-bb43-734602fe969c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Hayır" kelimesinin kavranması ve sınanması! Bebeğiniz artık "hayır" dediğinizde durup size bakıyor; ama bazen aynı hareketi bilerek tekrarlıyor. Bu, sınırları ve sizin tepkinizi test etmesidir. Sabırlı olun ve kararlılığınızı koruyun. Tehlikeli durumlarda ciddi ama sakin bir tonla nedenini açıklayın. O, yüz ifadenizden ve ses tonunuzdan sosyal kuralları öğrenmeye devam ediyor.') WHERE id = '996a8930-2fe4-4558-a5f9-55c594d11cb6';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "jargon" (kendi dilinde konuşma) artık daha karmaşık bir hâl alıyor. Sanki soru soruyormuş gibi sesini yükseltiyor ya da bir şey anlatıyormuş gibi el kol hareketleri yapıyor. Bu, konuşma tonlamasını (prozodi) öğrendiğini gösterir. Onu dikkatle dinleyin ve "Öyle mi? Çok ilginç!" diyerek diyaloğu sürdürün. Bu ilginiz, iletişim kurma hevesini inanılmaz derecede artıracak.') WHERE id = '79994c5e-b38e-4456-bddc-86c51746ecdb';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Beslenmede aile sofrasına entegrasyon: Bebeğiniz artık neredeyse her şeyi (tuzsuz ve baharatsız olmak şartıyla) sizinle birlikte yiyebilir. Ona kendi kaşığını ve rahatça içebileceği bardağını verin. Kendi kendine yemesine imkân tanımak hem motor becerilerini güçlendirir hem de yemek yemeyi olumlu bir sosyal etkinliğe dönüştürür. Sofrada birlikte oturmak, gelecekteki yemek alışkanlıkları için en iyi örnektir.') WHERE id = '4a48790e-7f13-40fe-9b6e-dd306e1f2a08';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Mekân hafızası" ve arama: Bebeğiniz artık sevdiği oyuncağın nereye saklandığını birkaç dakika sonra bile hatırlayabiliyor. Onunla daha karmaşık saklambaç oyunları oynayın. Örneğin oyuncağı bir örtünün altına saklayın ve bulmasını izleyin. Bu, hem hafızasını hem de dikkatini toplama becerisini artırır. Sorunu çözdüğünde onu coşkuyla övün.') WHERE id = 'f29f91f0-dc1e-44f0-842d-ac8ae1283e19';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal becerilerde "paylaşma" denemeleri: Bebeğiniz elindeki oyuncağı size uzatıp "veriyormuş gibi" yapıp sonra geri çekebilir. Bunlar onun ilk şakaları ve sosyal deneme girişimleridir! Bu "oyununa" gülüşle ve sevinçle karşılık verin. Gülmek ve birlikte eğlenmek, aranızdaki duygusal bağı inanılmaz derecede güçlendirir ve onda mizah duygusunun temelini atar.') WHERE id = 'ffe2c8a7-1840-4df7-a9fa-47dc0268105b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Cımbız tutuşu" (pincer grasp) artık tamamen mükemmelleşti. Yerdeki en ince ipliği veya küçücük bir kırıntıyı bile kolayca tutuyor. Bu beceriyi geliştirmek için ona iyi pişmiş baklagiller veya küçük lor parçaları sunun. Ama dikkatli olun: bu çeviklik, her tehlikeli küçük nesneyi aynı hızla ağzına götürebileceği anlamına da gelir. Güvenlik sürekli kontrol altında olmalı!') WHERE id = 'c1101eea-3caa-455b-a661-c216864cdeb4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Müzik ve ritim: Bebeğiniz müzik sesi duyunca bedenini sallıyor ya da ellerini mi çırpıyor? Müzik ritmini hissetmek; işitme yeteneğinin ve beden koordinasyonunun gelişimidir. Onunla birlikte dans edin, el çırpın. Bu hem fiziksel aktivitesini artırır hem de estetik zevkin ve ritim duygusunun oluşmasına yardımcı olur. Şarkıların sözlerini birlikte tekrarlamaya çalışın.') WHERE id = '3a1cdf9f-7bc8-427f-b1e3-a23a8f78241b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Gece uykusunda "motor uyanışlar": Bebeğiniz uykuda aniden ayağa kalkabilir ya da uykulu hâlde emeklemeye çalışabilir. Beyni, gündüz öğrendiği hareketleri gece tekrarlıyor. Ağlamıyorsa ona dokunmayın; bırakın pozisyonunu kendisi bulup yeniden uyusun. Ağlıyorsa sessizce yanına gidin, ışığı açmadan yerine yatırın ve sakinleştirici sözler söyleyin. Varlığınız, yeniden uykuya dalması için yeterlidir.') WHERE id = '8706f5e6-ca0d-4a1d-8941-e5de02cc1dad';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Tebrikler, 320 günü tamamladık! İlk doğum gününe sadece 45 gün kaldı. Bebeğiniz artık karakterini, tercihlerini ve isteklerini kararlılıkla gösteriyor. Bugün onunla yerde uzanın ve sadece "taklit" oyunu oynayın; o ses çıkarsın siz tekrarlayın, siz el çırpın o tekrarlasın. Siz onun dünyayı keşfettiği en güvenilir liman ve en yakın dostusunuz, anne!') WHERE id = '6671dafc-f72e-46f2-8504-39bf2769162e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Artık 11. ayın son on gününe giriyoruz. Bebeğiniz bir elinden tuttuğunuzda artık çok mu güvenli yürüyor, yoksa hâlâ sadece koltuk kenarında mı ilerliyor? Bu günlerde dengesini korumak için ellerini yana açarak bir iki serbest adım atabilir. Bu "denge" hareketleri, beynindeki denge merkezini (vestibüler sistem) çalıştırır. Onu aceleye getirmeyin; bırakın güvenini tam bulsun.') WHERE id = '223de2de-87c5-4289-96a9-08ae91456aa1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğiniz artık nesnelerin ne için kullanıldığını anlamaya başlıyor (işlevsel oyun). Örneğin tarağı başına götürüyor, telefonu kulağına tutuyor ya da fincanı ağzına götürüp "içiyormuş gibi" yapıyor. Bu, bilişsel gelişimde büyük bir sıçramadır! Ona güvenli ev eşyaları vererek bu taklit becerisini destekleyin. Dünyayı sizi izleyerek öğreniyor; bu yüzden davranışlarınızda örnek olmaya çalışın.') WHERE id = '1023ea09-5e35-4d01-b1e5-ee2d0049110b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Nesne kalıcılığı" oyunu: Bebeğiniz artık oyuncağı bir kabın içine koyup üstünü örtseniz de yok olmadığını biliyor. Onunla daha karmaşık saklambaç oyunları oynayın. Örneğin oyuncağı iki farklı örtüden birinin altına saklayın ve bulmasını izleyin. Bu, hem hafızasını hem de dikkatini toplama becerisini artırır. Sorunu çözdüğünde onu coşkuyla övün.') WHERE id = '8ef86f1c-b50a-4f76-b6a2-1deccffcaf49';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Beslenmede bağımsızlık: Bebeğiniz artık kaşığı tamamen kendisi tutup ağzına götürmek istiyor. Evet, yemeğin çoğu yerde ve önlükte olacak; ama bu, ince motor becerilerin ve el-göz koordinasyonunun en önemli egzersizidir. Ona kendine uygun, silikon veya kalın saplı bir kaşık verin. Siz de aynı anda başka bir kaşıkla yardım edebilirsiniz. Bu bir "takım çalışması" gibidir!') WHERE id = '7871caf2-41cf-4c3f-b2a8-4d60c9c5acd7';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "hayvan sesleri" dönemi! Bebeğiniz artık "köpek nasıl havlar?", "kedi nasıl ses çıkarır?" gibi sorulara kendi dilinde cevap vermeye başlayabilir. Bu, ses taklidi becerisinin zirvesidir. Hayvan resimleri olan kitaplara bakarak bu oyunları sürdürün. Sesleri taklit etmek, konuşma organlarını (dil, dudak kaslarını) gelecekteki karmaşık kelimelere hazırlar.') WHERE id = 'cdc84d0d-886f-4a27-bf41-fd9c5be5503c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Cımbız tutuşu" (pincer grasp) o kadar gelişti ki yerdeki en ince ipliği veya küçücük bir kırıntıyı bile kolayca tutuyor. Bu beceriyi sınamak için ona iyi pişmiş baklagiller (nohut, mercimek) sunabilirsiniz. Ama unutmayın: bulduğu her ufak şeyi ağzına götürme alışkanlığı da zirvede. Evin zemininin temizliği ve küçük nesnelerin olmaması en önemli güvenlik kuralınız olmaya devam ediyor.') WHERE id = '03beae21-c620-431a-a745-a2cb5663e55d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal oyunlarda karmaşıklaşma: Bebeğiniz "ver-al" oyununu artık başka bir seviyeye taşıyor. Oyuncağı size verip hemen geri isteyebilir ya da siz "ver" dediğinizde bilerek saklayabilir. Bunlar onun ilk "şakalarıdır". Bu mizah duygusuna gülüşle karşılık verin. Gülmek ve birlikte eğlenmek, aranızdaki duygusal bağı inanılmaz derecede güçlendirir.') WHERE id = '3339985d-3305-4eb1-9ee4-eac876362604';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Uyku düzeni ve uyanık kalma süresi: 11. ayda bebekler gündüz 2 uykudan 1 uykuya geçiş (nap transition) belirtileri gösterebilir; ama henüz acele etmeyin. Çoğu bebek 14-15 aya kadar 2 gündüz uykusuna ihtiyaç duyar. Sabah uykusuna zor dalıyorsa uyanık kalma süresini biraz uzatmayı deneyin (yaklaşık 3-3,5 saat). İyi dinlenmiş bebek, yeni becerileri daha hevesle öğrenir.') WHERE id = 'db42c776-feed-4c94-906a-857e9999bca9';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Mekân algısı": Bebeğiniz artık kutuların içine bakmayı, kapakları açıp kapatmayı ve nesneleri iç içe dizmeyi seviyor. Ona farklı boyutlarda plastik kaplar verin. Küçük kabın büyük kabın içine sığdığını keşfettiğinde beyninde karmaşık matematiksel ve mantıksal bağlantılar kurulur. Basit görünse de bu aslında büyük bir keşiftir.') WHERE id = 'c317d6dc-6305-468b-bef4-37407eacbfe2';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Tebrikler, 330 günü tamamladık! İlk doğum gününe sadece bir ay kaldı. Bebeğiniz artık iradesini gösteriyor: giyinmek istemediğinde ayaklarını diretiyor, sevdiği yemeği görünce ellerini çırpıyor. Bu "kişilik" belirtileri sizi bazen yorsa da aslında sağlıklı psikolojik gelişiminin göstergesidir. Muhteşem bir yol katettiniz, anne!') WHERE id = 'c209d7a9-28c5-4bcf-a9ab-ed5e68cd5e38';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '12. aya hoş geldiniz! İlk doğum gününe sadece 30 gün kaldı. Bebeğiniz artık bambaşka bir insan. Hareketlerinizi sadece taklit etmiyor; anlamlarını da kavrıyor. Bu ay özgüvenini artırmak için ona basit seçimler sunun. Örneğin "bu gömleği mi giymek istersin, yoksa bunu mu?". Bu, karar verme becerisinin ilk tohumlarını eker.') WHERE id = 'fd9ad5fc-02c4-489e-8c2f-e2ab1ee56a7e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğiniz desteksiz yürümeye başladıysa evdeki güvenlik kurallarını "ekstrem" seviyeye çıkarın. Henüz yürümüyorsa endişelenmeyin; birçok sağlıklı bebek 15 aya kadar yürümez. Yürüme hızı zekâ göstergesi değildir. Önemli olan ayakta durabilmesi ve çevreyi keşfetmek için motivasyonunun olmasıdır.') WHERE id = 'e0fb9df8-7033-4ff7-a1b1-5c3d3e6afa83';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "bilinçli kelimeler": Bebeğiniz artık "su", "ver", "gel" gibi basit kelimeleri yerinde mi kullanıyor? İstediğini yalnızca bir kelimeyle ya da işaretle size anlatabiliyor. Siz onun bu denemelerini genişletin: "Evet, su mu içmek istiyorsun? Al, bu senin mavi bardağın". Bu, beyninde kelimelerin dil bilgisi bağlantılarını kurmasına yardımcı olur.') WHERE id = 'c5cc511f-2fea-4b22-b8e8-1b77f482261c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Beslenmede aile sofrasına tam entegrasyon. Bebeğiniz artık sizinle aynı anda sofraya oturup neredeyse aynı yemekleri yiyebilir. Bu, sosyalleşmesi için çok önemlidir. Ona kendi tabağını kaşığını verin ve kendi kendine yemesine imkân tanıyın. Yemek yemek onun için bir zorunluluk değil; ilginç ve lezzetli bir etkinlik olmalı.') WHERE id = '8b39909f-51d2-4504-9985-513b605dc042';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Cımbız tutuşu" (pincer grasp) mükemmelleşti ve ince motor beceriler artık daha karmaşık oyunlara izin veriyor. Ona küpleri üst üste dizmeyi, büyük boncukları ipe geçirmeyi (gözetim altında!) veya basit yapbozları gösterin. Bu oyunlar hem dikkati toplamayı hem de el-göz koordinasyonunu inanılmaz derecede geliştirir.') WHERE id = 'e3225412-1384-48a0-aa55-7ca8a5ef8659';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal iletişimde "empatinin" ilk kıvılcımları. Bebeğiniz siz üzgünken ya da ağlarken gelip size dokunabilir, oyuncağını size verebilir. Bu, başkalarının duygularını anlamaya başladığını gösterir. Bu şefkatli hareketlerine sevgiyle karşılık verin. Bu, ileride duygusal açıdan sağlıklı bir birey olmasına yardımcı olacak.') WHERE id = '31745949-5ef4-444a-8a69-ec5929c0332b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bardaktan su içme alışkanlığı artık tamamen oturmalı. Biberondan yavaş yavaş uzaklaşmanın zamanı geldi. Uzun süreli biberon kullanımı diş dizilimini ve konuşma gelişimini olumsuz etkileyebilir. Ona ilginç, renkli suluklar ya da doğrudan açık bardak sunun. Kendi başına içmek ona büyük bir bağımsızlık duygusu verecek.') WHERE id = '38eafb23-62e2-4538-a93f-213f32e35986';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Mekân hafızası" ve düzen: Bebeğiniz artık oyuncaklarının yerini biliyor. Oyun bittikten sonra onları birlikte toplayın. "Hadi, ayıcığı evine (kutuya) koyalım" diyerek onu teşvik edin. Bu hem sorumluluk duygusunu oluşturur hem de eşyaların belirli bir yeri olduğunu anlamasına yardımcı olur. Düzen alışkanlıkları tam da bu aylarda başlar.') WHERE id = 'c880f2e4-5f85-403c-b1f7-b1634ed3e06b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Gece uykusu ve uyanık kalma süresi: Bebeğiniz artık gündüz uykularını kısaltabilir ya da bir uykuyu iptal edebilir. Gündüz tek uykuyla kendini iyi hissediyorsa düzeni buna göre ayarlayın. Ancak çoğu 1 yaşındaki çocuk hâlâ iki uykuya ihtiyaç duyar. Yorgunluk belirtilerini izlemeye devam edin; iyi dinlenmiş çocuk daha mutlu ve öğrenmeye daha açıktır.') WHERE id = '9898d949-3ccb-4708-a982-1de8127dfcfd';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Tebrikler, 340 günü tamamladık! İlk doğum gününe sadece 25 gün kaldı. Bebeğiniz artık bir kişilik; kendi zevki, karakteri ve en sevdiği oyunları var. Bugün onunla yerde uzanın ve sadece onun seçtiği bir oyunu oynayın. Onun dünyasına girmeniz, onun için en büyük hediyedir. Muhteşem bir yıl geçirdiniz, anne!') WHERE id = 'c4c0444c-fad1-4344-8a31-c99f7a9878d9';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Doğum gününe sadece 25 gün kaldı! Bebeğiniz artık birkaç adımı serbestçe atıyorsa, denge merkezinin tam oluştuğunu gösteriyor. Henüz adım atmıyorsa ellerinden tutup onu yürütmeye zorlamayın. Bu, omurgasına gereksiz yük bindirebilir. En iyisi, karşısında durup kucağınızı açarak size doğru gelmesi için yüreklendirmektir. Güven dolu bakışlarınız ona en büyük cesareti verir.') WHERE id = '8681364a-206a-4e87-acfa-4a44f4404ec8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "alıcı dil" (anlama yeteneği) gelişimi: Bebeğiniz artık basit komutları anlıyor. "Topu bana ver", "Buraya gel", "Şapkanı al" dediğinizde bunu yapabiliyor mu? Henüz tüm kelimeleri söyleyemese de beyninde büyük bir kelime deposu kurdu. Onunla her hareketinizi seslendirerek konuşmaya devam edin. Bu, gelecekteki konuşmasının sağlam temelidir.') WHERE id = 'b0d73932-0d82-458c-b55b-ddc718662495';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal becerilerde "şakalar": Bebeğiniz oyuncağı bilerek size verip hemen geri çekiyor ve buna mı gülüyor? Bu, mizah duygusunun ve sosyal oyun becerisinin oluştuğunu gösterir. Bu "oyununa" coşkuyla katılın. Birlikte gülmek aranızdaki duygusal bağı güçlendirir ve onda olumlu bir özgüven oluşturur.') WHERE id = 'f977f0c6-061a-4189-bf33-4e6656c97984';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Beslenmede "seçicilik" başlayabilir. Bebeğiniz dün yediği yemeği bugün kararlılıkla reddedebilir. Bu, artık kendi iradesini göstermesidir. Onu zorlamayın; ama sevmediği besini bir süre sonra farklı biçimde yeniden sunun. Önemli olan sofrada gerginlik oluşmamasıdır. Yemek zamanı onun için hoş bir ritüel olarak kalmalı.') WHERE id = 'eb15bd6a-93d6-4986-92eb-7294c9a935c2';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerde "tasarım" yeteneği: Bebeğiniz artık küpleri üst üste koyup küçük "kuleler" yapmaya çalışıyor. Kule şimdilik çabuk yıkılabilir; ama bu, el-göz koordinasyonu ve dikkatini toplaması için harika bir egzersizdir. Ona farklı boyut ve renklerde küpler verin. Yıkılan kuleye birlikte gülüp "Hadi, bir daha yapalım!" diyerek onu motive edin.') WHERE id = '7a4a5884-cfbe-4717-937f-7483274cf1dd';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Mekân algısı" ve hafıza: Bebeğiniz artık sevdiği oyuncağın nereye saklandığını biliyor ve onu bulmak için engelleri (örneğin yastığı) kenara çekiyor. Bu, problem çözme becerisinin gelişimidir. Onunla daha karmaşık saklambaç oyunları oynayın. Engelleri aşmak, beynindeki mantıksal bağlantıları güçlendirir.') WHERE id = '87a69c40-9317-47d9-89ca-fad250ba27cf';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Kendini tanıma ve bağımsızlık: Bebeğiniz giyinirken artık size "yardım" etmeye mi çalışıyor? Örneğin ayağını çoraba uzatıyor ya da kolunu gömleğin koluna sokuyor. Bu denemeleri destekleyin ve onu övün. "Ne güzel giyindin!" demeniz, kendini bir birey olarak algılamasına ve bağımsız olma isteğine büyük katkı sağlar.') WHERE id = '82ceaad9-caa0-45d0-ae94-6fb25e59d3dc';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Diş çıkarma döneminin (ilk yıl için) son aşamaları: 1 yaşına yaklaşan bebeklerin çoğunda artık 4-8 diş olur. Damakları yeniden şişebilir ya da ağrıyabilir. Ona çiğnemesi için serin sebze dilimleri (havuç, salatalık; gözetim altında!) verin. Çiğnemek hem diş etlerine masaj yapar hem de çene kaslarını güçlendirir.') WHERE id = '3fe62d47-f929-4c62-b0de-6bc80e34943b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Hayır" kelimesinin gücü: Bebeğiniz artık sizin "hayır" demenize itiraz edebilir, hatta yere yatıp ağlayabilir (ilk öfke nöbetleri). Bu, duygularını yönetmeyi henüz bilmemesinden kaynaklanır. Sakin kalın, yanına eğilin ve duygularını adlandırın: "Şu an kızgınsın çünkü oyuncağı vermedim, anlıyorum". Sizin bu sakinliğiniz, ona duygusal dengeyi öğreten en iyi derstir.') WHERE id = '627b69c9-1a97-4379-b790-7b2e4d39bfb2';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Tebrikler, 350 günü geride bıraktık! İlk doğum gününe sadece 15 gün kaldı! Bugün ilk aylardaki fotoğraflarına bakın ve ne kadar yol katettiğinizi düşünün. O çaresiz bebek şimdi kendi karakteri olan bir bireye dönüştü. Bu 15 günü stressiz, sadece onunla vakit geçirerek yaşayın. Muhteşem bir yıl geçirdiniz, anne!') WHERE id = '8417d81b-7389-4675-845a-7c49bcb07801';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İlk doğum gününe sadece 10 gün kaldı! Bebeğiniz artık kitap sayfalarını (şimdilik birkaçını birden) çevirebiliyor mu? Bu hem ince motor becerilerinin hem de kitaba olan ilgisinin göstergesidir. Ona büyük ve renkli resimli kitaplar okumaya devam edin. Resimdeki köpeğe bakıp "Hav hav nerede?" dediğinizde parmağıyla göstermesi, kavrama yeteneğinin zirvesidir.') WHERE id = '3e342e5d-4541-4b82-ae58-b2cc792f784b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğiniz artık müzik sesi duyunca bedenini sallıyor, dizlerini büküp açarak "dans" mı ediyor? Müzik ritmini hissetmek, hem işitmesinin hem de beden koordinasyonunun mükemmelleştiğini gösterir. Onunla birlikte el çırpın, ritim tutun. Bu neşeli anlar beynindeki mutluluk hormonlarını artırır ve sizinle olan bağını daha da tatlandırır.') WHERE id = '824b4580-ab45-4cbc-9104-e999a9e050cb';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Nesne işlevselliği" artık tamamen kavranıyor. Bebeğiniz tarağı görünce başına götürüyor, ayakkabısını görünce ayağına uzatıyor. Nesnelerin sadece oyuncak olmadığını, her birinin bir işe yaradığını artık anlıyor. Ona güvenli ev eşyalarıyla (plastik kaplar, temiz fırçalar) oynama izni verin. Bu, günlük hayata uyumunu hızlandırır.') WHERE id = '40fb0a95-63d4-4ada-888b-1faf14ddd19d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "tekrarlama" dönemi. Söylediğiniz kelimelerin son hecelerini tekrarlamaya çalışabilir. Örneğin siz "elma" dediğinizde o "ma" diyebilir. Bu, konuşma organlarının aktif egzersizidir. Onunla her zaman net ve doğru telaffuzla konuşun. "Bebek dilinde" (mama dili) konuşmak yerine nesnelerin gerçek adlarını söylemek, kelime dağarcığını doğru şekillendirir.') WHERE id = '40321163-794d-42e6-bcde-127caef60c13';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bağımsız yeme alışkanlıkları artık oturmalı. Evet, kaşığı hâlâ ters tutuyor ya da yemeğin yarısını yere döküyor; ama kendi kendine yemeye çalışması, özgüveni için her şeyden önemlidir. Ona kendine uygun derin bir tabak ve kauçuk saplı kaşık verin. Sabırlı olun; yakında aile sofrasının en aktif ve "özgür" üyesi olacak.') WHERE id = 'd42878d7-1b6d-456a-b198-9e59777aacf0';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Ayrılık kaygısı" (separation anxiety) 1 yaş arifesinde yeniden zirveye çıkabilir. Siz odadan çıkınca kopardığı feryat, size olan derin bağlılığının ve hâlâ "annem gider de dönmez" korkusunun işaretidir. Ona her zaman nereye gittiğinizi ve ne zaman döneceğinizi söyleyin (başka odaya bile gitseniz). Dürüstlüğünüz, güven duygusunu yeniden inşa edecek.') WHERE id = 'bf1abd20-6eb2-41e7-85ec-e1c3f46808a3';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerde yeni başarı: "Kapak açma ve kapama". Bebeğiniz artık kutuların kapağını açmaktan, şişelerin kapağını çevirmekten (denemekten) keyif alıyor. Bu, bilek ve parmak kaslarının yüksek koordinasyonudur. Ona farklı boyutlarda plastik kaplar verin ve bırakın onları iç içe yerleştirsin. Bu, aynı zamanda ilk matematiksel/mantıksal düşünme egzersizidir.') WHERE id = '4e49e60c-de35-4a74-ac4f-e95ac56a3410';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal kuralların öğrenilmesi: Bebeğiniz artık "bay bay" (el sallamak), "öpücük göndermek" ya da "el vermek" gibi jestleri bilinçli yapıyor. Bunlar, topluma katılması için ilk "vizeleridir". Bu olumlu davranışlarını her zaman sevinçle karşılayın. Tepkiniz, hangi davranışın "iyi" olduğunu anlamasına yardımcı olur.') WHERE id = '21db9180-06af-489e-83b0-28bdcc1730d0';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Yarın bebeğiniz tam 1 yaşını dolduruyor! Bugün son 12 ayın macerasını hatırlayın. İlk gülümseme, ilk diş, ilk emekleme... Ne kadar zor olsa da başardınız! Bebeğiniz artık çaresiz bir bebek değil; kendi karakteri ve istekleri olan küçük bir insan. Bu gece uyumadan önce kendinize de bir "aferin" deyin. Muhteşem bir annesiniz!') WHERE id = '74f434ee-a5bf-498f-af06-34cc0939c106';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'TEBRİKLER! İLK DOĞUM GÜNÜNÜZ KUTLU OLSUN! 🎂 Bebeğiniz artık resmen 1 yaşında. Bu bir yıl hem onun hem de sizin hayatınızdaki en büyük değişimlerin yılıydı. O artık yürümeye, konuşmaya ve dünyayı fethetmeye hazır bir "toddler" (yeni yürüyen çocuk). Bugünü stressiz, sadece onun gülüşü ve sevginizle kutlayın. Yolunuz açık, ömrünüz bereketli olsun!') WHERE id = '56917d9b-b358-4310-b651-30aecbaf8560';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '2. yıla hoş geldiniz! İlk doğum gününün heyecanı geride kaldı ama asıl macera şimdi başlıyor. Bebeğiniz artık resmen "yeni yürüyen çocuk" (toddler) statüsünde. Bu aydan itibaren dünyayı daha çok "dik" pozisyonda keşfetmek isteyecek. Hareketliliği arttıkça enerji ihtiyacı da değişiyor. Ama unutmayın; anne sütü veya mama hâlâ beslenmesinin önemli bir parçası olarak kalabilir.') WHERE id = '165b6f1d-3374-4097-b9a4-8e514ea4fdd0';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Yürüme becerisi pekişiyor! Bebeğiniz artık serbestçe adımlıyorsa, adımlarının hâlâ biraz "sarhoşvari" ve geniş olduğunu görürsünüz. Bu, dengeyi korumak için doğal bir mekanizmadır. Onu evde olabildiğince çıplak ayak bırakın. Bu, ayak tabanının doğru şekillenmesi ve beynine zeminin dokusu hakkında daha çok bilgi gitmesi için en iyi yöntemdir.') WHERE id = 'c278e801-c9bd-49de-b0fb-e7e23f4f7d75';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '1 yaştan sonra çocukların iştahında ani bir azalma görülebilir. Buna "fizyolojik anoreksiya" denir. Nedeni basit: büyüme hızı ilk yıla göre yavaşlıyor ve eskisi kadar çok kaloriye ihtiyacı yok. Onu zorla yedirmeye çalışmayın. Önemli olan, sunduğunuz besinlerin kaliteli ve çeşitli olmasıdır. Ne kadar yemesi gerektiğini kendisi ayarlamayı öğrenmeli.') WHERE id = 'dd5c13fb-e41c-4d49-a21d-c17c38691c1f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "tek kelimelik cümleler" dönemi. Bebeğiniz artık tek bir kelimeyle koca bir düşünceyi ifade ediyor. Örneğin "atta" demek hem "dışarı gidelim" hem de "ayakkabımı giydir" anlamına gelebilir. Siz bu tek kelimelerini genişleterek cevap verin: "Evet, şimdi ayakkabılarını giyip dışarı (attaya) gideceğiz". Bu, cümle kurma becerisini hızlandırır.') WHERE id = '4f614506-d560-4d40-bad9-c0ba7ee808d8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Ben kendim!" dalgası güçleniyor. Bebeğiniz elini yıkamaya çalışırken, merdiven çıkarken ya da giyinirken artık yardımınızı reddedebilir. Bu inatçılık değil, bağımsızlık girişimidir. Tehlikeli olmayan her yerde ona "izin verilmiş özgürlük" tanıyın. Kendi başarabildiğini görmek, öz saygısını (self-esteem) şekillendiren en büyük etkendir.') WHERE id = '884b93ff-cafb-4926-88b8-45e9267f348c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal becerilerde "paralel oyun" aşaması. Bebeğinizi yaşıtlarının yanına götürürseniz, diğer çocuklarla değil, onların yanında kendi başına oynadığını göreceksiniz. Bu, 1-2 yaş arası çocuklar için tamamen normaldir. Henüz paylaşmayı ve birlikte oynamayı bilmiyorlar; ama birbirlerini gözlemleyerek çok şey öğreniyorlar. Sosyalleşmesi için onu parklara, oyun gruplarına götürmeye devam edin.') WHERE id = 'e23b48b6-63ac-4bcc-9b95-51974a62ac74';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerde ustalık: Bebeğiniz artık kalemi veya boya fırçasını (şimdilik avucuyla) tutup kâğıt üzerinde "karalamalar" yapabiliyor. Bu, el-göz koordinasyonunun yeni seviyesidir. Ona büyük kâğıtlar ve çocuklar için güvenli boya kalemleri verin. Bu etkinlik, yaratıcı hayal gücünün ilk tohumlarını da eker. Duvarlar "sanat eserine" dönüşmesin diye her zaman gözetim altında tutun!') WHERE id = '0b6473c4-31af-4b7f-87fd-2d01229d5be8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Uyku düzeninde değişiklik: 13. ayda birçok çocuk gündüz iki uykudan tek uykuya geçmek ister. Sabah uykusuna dalmakta zorlanıyorsa ya da öğle uykusu çok gecikiyorsa düzeni ayarlamanın zamanı gelmiştir. Tek uykuya geçiş birkaç hafta sürebilir ve bu geçiş döneminde akşamlar biraz daha "huzursuz" olabilir. Sabırlı olun; yeni düzen ikiniz için de daha rahat olacak.') WHERE id = '04380a78-48ac-47f1-b32c-6d6f9bfeb4d4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Güvenlikte "yükseklik" faktörü. Bebeğiniz artık sandalyelere tırmanıyor, masanın üstüne çıkmaya çalışıyor. Yükseklik korkusunu ve riskleri henüz tam kavramıyor. Pencere kilitlerini kontrol edin, yüksek mobilyaları duvara sabitleyin. Hareket özgürlüğünü kısıtlamadan ortamı "düşmeye dayanıklı" hâle getirmek sizin temel görevinizdir.') WHERE id = '6948a89f-6493-4c6e-9adb-708a1f0063cb';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '13. ayın ilk on gününü tamamladınız! Bebeğiniz artık basit komutları ("Oyuncağını kutuya koy", "Buraya gel") tamamen bilinçli yerine getiriyor. Bu, hem dil hem de sosyal gelişiminin büyük bir göstergesidir. Bugün onunla birlikte kitap okuyun ve resimdeki nesneleri bulmasını isteyin. Sizinle geçirdiği her kaliteli dakika, onun için en büyük gelişim desteğidir.') WHERE id = '702b1e33-f64a-46f4-9e5d-44efebebe748';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık "hayır" kelimesinin gücünü keşfetti! Bu dönemde her şeye itiraz ederek kendi sınırlarını test ediyor. Bu inatçılık değil; bağımsız bir kişilik olarak şekillenmesidir. Siz "hayır" dediğinizde o hareketi kasıtlı yapıp tepkinizi izleyebilir. Sakin kalmaya çalışın; duygusal dengeniz, ona kuralları öğreten en iyi rehberdir.') WHERE id = 'e0c32222-756f-4ca9-8533-fb5e6a6bf334';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Yürüme becerisi mükemmelleştikçe artık geri geri gitmeyi ya da yürürken elinde oyuncak taşımayı deniyor. Bu, hem fiziksel gücün hem de beynin koordinasyon yeteneğinin arttığını gösterir. Ona çekip götürebileceği tekerlekli oyuncaklar verin. Bu tür oyunlar bacak kaslarını daha da güçlendirir.') WHERE id = '49b402b9-bb72-400d-ac9d-7af091029dd1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Beslenmede "seçicilik" dönemi sürüyor. Çocuk dün sevdiği yemeği bugün yere atabilir. Bu aşamada "ne kadar yiyeceğini" çocuğa bırakın; siz ise "ne zaman ve neyi" yiyeceğini belirleyin. Sofrada zorlama değil, hoş bir ortam yaratın. Unutmayın; midesi hâlâ küçük ve birkaç lokma bile onun için yeterli olabilir.') WHERE id = '853086ca-90b3-4556-bd83-70b66fd42f49';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada ilk "ikili kavramlar". Artık "büyük-küçük", "sıcak-soğuk" gibi farkları görerek ve dokunarak anlamaya başlıyor. Oyun oynarken "Bak, bu büyük top, bu ise küçük" diyerek karşılaştırın. Bu basit diyaloglar, soyut düşünme yeteneğini ve kelime hazinesini hızla genişletir.') WHERE id = '8381dd6a-9188-4a53-b0c0-fe9e5722bee4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Ayrılık korkusu" (separation anxiety) bu aylarda dalgalar hâlinde geri dönebilir. Siz odadan çıkınca ağlaması, size olan ihtiyacının işaretidir. Gitmeden önce her zaman "Hoşça kal, birazdan döneceğim" deyin ve gizlice kaçmayın. Dürüstlüğünüz, onda "annem kaybolsa da mutlaka geri döner" inancını pekiştirir.') WHERE id = 'd51eadcf-ced3-43a7-a954-d65ad8f07d93';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerde yeni adım: Kapakları açmak ve kapatmak. Boş plastik kaplar ve kapakları çocuk için en ilginç "bulmaca" olabilir. Kapağı doğru yerine oturtmak için parmaklarını ve dikkatini koordine etmesi, beyninde yeni nöron bağlantıları oluşturur. Bu basit mutfak eşyalarıyla oynamasına izin verin.') WHERE id = '6e7fc713-da58-436a-956b-2725c7ebe15b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık duygularını fiziksel olarak gösterebiliyor: çığlık atmak, kendini yere atmak ya da size sarılmak. Bu, duygusal düzenlemenin henüz zayıf olduğunu gösterir. Sinirlendiğinde yanına eğilin, aynı seviyede durun ve "Şu an kızgınsın, anlıyorum" diyerek duygularını adlandırın. Bu, ileride kendi duygularını yönetmesi için temel oluşturur.') WHERE id = '49f6d0be-6454-4212-a7b3-56294a93638b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Diş çıkarma sürecinde (bu dönemde genellikle azı dişleri gelebilir) salyanın artması ve damakların ağrıması görülebilir. Bu, uyku ve yemek düzenini etkileyebilir. Ona diş kaşıyıcılar veya çiğneyebileceği serin meyve dilimleri verin. Şefkatiniz ve sabrınız, bu ağrılı dönemi daha rahat geçirmesine yardımcı olacak.') WHERE id = '48e458f5-c261-485d-bb67-d4e81e9a6931';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Gece uykularında "aktif hareketler" olabilir. Çocuk uykuda dönebilir, yer değiştirebilir ya da aniden oturabilir. Beyni, gündüz öğrendiği tüm o yeni hareketleri uykuda "prova ediyor". Ağlamıyorsa müdahale etmeyin. Bırakın kendine rahat bir pozisyon bulup uykusuna devam etsin.') WHERE id = '5ccc44b7-6be9-42e8-9051-5aba385dfbb3';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Tebrikler, 13. ayın ortasındasınız! Çocuğunuz artık basit ricaları tamamen anlıyor ve hatta size "yardım" etmek istiyor (örneğin oyuncağı kutuya koymak). Bu hevesini bastırmayın; her küçük yardımını coşkuyla övün. Desteğiniz, onu ileride daha sorumlu ve özgüvenli bir birey yapacak. Muhteşem bir annesiniz!') WHERE id = '2f2ae51c-beef-4df3-9d10-cb7325ea4331';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz kaşık kullanmada artık daha becerikli. Evet, yemeğin bir kısmı hâlâ yere dökülüyor; ama bilek hareketlerini artık daha iyi yönetiyor. Ona kendi başına yemesi için daha çok fırsat verin. Doyduğunu anlayıp yemeği kenara itmesi, içindeki açlık-tokluk sinyallerini dinlediğini gösterir. Bu, ileride sağlıklı beslenme alışkanlıkları için çok önemlidir.') WHERE id = '45554d06-2e09-4223-93a8-104614df2f0c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık bilinçli olarak "yardım" etmeye çalışıyor. Örneğin oyuncaklarını kutuya diziyor ya da size bir şey uzatıyor. Bu, sosyal sorumluluk duygusunun ilk kıvılcımlarıdır. Her bir şey getirdiğinde "Çok teşekkürler, bana çok yardım ettin" deyin. Bu tür övgüler, kendini gerekli ve becerikli hissetmesini sağlar.') WHERE id = '5614d8e1-6798-45a7-8bfd-239e88293a49';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Yeni korkuların ortaya çıkması: 13-14 aylık çocuklar aniden elektrikli süpürge sesinden, karanlıktan ya da yabancılardan korkmaya başlayabilir. Bu, hayal gücünün ve çevresini algılamasının gelişimiyle ilgilidir. Korkusuna gülmeyin, "burada korkacak ne var ki?" demeyin. Sadece yanında olun, sarılın ve güvende olduğunu hissettirin. Bu korkular zamanla geçecek.') WHERE id = '320f797a-413e-4747-8432-a77c70f8f1ae';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Cımbız tutuşu" o kadar gelişti ki çocuğunuz kitap sayfalarını (şimdilik kalın sayfaları) tek tek çevirebiliyor. Bu, hem ince motor becerilerini hem de kitaba olan ilgisini artırıyor. Ona renkli ve büyük resimli kitaplar okumaya devam edin. Resimde gördüğü nesneyi adlandırmasını isteyerek konuşmasını teşvik edin.') WHERE id = '3f0fc8bf-420a-4d0f-acf7-ab2d58fa2a4b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık müzik duyunca bedenini ritmik şekilde sallıyor ya da ellerini çırpıyor. Ritim duygusu; beynin matematik ve dil merkezleriyle sıkı sıkıya bağlıdır. Onunla birlikte dans edin, el çırpın, farklı ritimler tutun. Bu hem fiziksel bir aktivitedir hem de aranızdaki duygusal bağı güçlendiren eğlenceli bir etkinliktir.') WHERE id = '22fc8a33-8e0b-4e79-86f9-460a94db933b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal iletişimde "empatinin" ilk izleri: Siz üzgün göründüğünüzde ya da ayağınızı bir yere çarptığınızda çocuğunuz gelip size dokunabilir, sarılabilir ya da kendi oyuncağını size verebilir. Bu, başkalarının duygularını hissetmeye başladığını gösterir. Bu şefkatli hareketine "Çok teşekkürler, sen çok merhametlisin" diyerek karşılık verin. Şefkat duygusu tam da bu yaşlarda filizlenir.') WHERE id = '993a5a5e-046b-489d-bd9d-9580428e1cdc';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Mekân hafızası" ve arama: Çocuğunuz artık sevdiği oyuncağın nereye saklandığını biliyor. Onunla daha karmaşık saklambaç oyunları oynayın. Örneğin oyuncağı bir kutunun içine koyun ve üstünü havluyla örtün. Engelleri aşıp oyuncağı bulması, problem çözme becerisini geliştirir. Bu küçük "zaferler" özgüvenini artırır.') WHERE id = '63dfa4ff-f8c9-4a30-bd0e-f8d086dd0898';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Güvenlik hatırlatması: Çocuğunuz artık her şeye tırmanmak istiyor; koltuklar, sandalyeler, raflar... Yükseklik ve tehlike riskini henüz tam kavramıyor. Ağır mobilyaları duvara sabitlediğinizden ve merdivenlerde koruyucu bariyerlerin olduğundan emin olun. Keşif hevesini bastırmadan güvenli bir ortam yaratmak önemlidir.') WHERE id = 'cc4b37ce-4e2e-4d58-a313-414b2395c5eb';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "tekrarlama" dönemi. Söylediğiniz kelimelerin son hecelerini tekrarlamaya çalışabilir. Örneğin siz "su" dediğinizde o "u" ya da "su" diyebilir. Onunla her zaman doğru ve net bir dille konuşun. "Cici", "mama" gibi bebek kelimeleri yerine nesnelerin gerçek adlarını söylemek, kelime dağarcığının doğru şekillenmesine yardımcı olur.') WHERE id = 'd1034aae-153e-40ef-b35f-875a226037db';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Tebrikler, 13 ayı tamamladık! Çocuğunuz artık bir "toddler" (yeni yürüyen çocuk) olarak iradesini, karakterini ve sevgisini tam anlamıyla gösteriyor. Bugün onunla yerde uzanın ve sadece onun seçtiği bir oyunla vakit geçirin. Onunla geçirdiğiniz her kaliteli an, gelecekteki mutluluğunun temelidir. Muhteşem bir annesiniz!') WHERE id = '4d58b019-ad51-4763-b775-1cff7a5c244e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '14. aya hoş geldiniz! Bu ay çocuğunuz hem fiziksel hem de duygusal olarak daha fazla "bağımsızlık" talep edecek. Artık nereye gitmek istediğini ve neyi yemek istemediğini kararlılıkla gösteriyor. Bu, kişiliğinin gelişimi için önemli bir aşamadır. Ona gün içinde küçük seçimler sunun (örneğin "elma mı yersin, armut mu?"). Seçme imkânı, itiraz dalgasını azaltacak ve özgüvenini artıracak.') WHERE id = '05712130-29d6-4028-9cd7-1eeae1f8b5f6';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık nesneleri üst üste dizmekte (bloklarla kule yapmakta) daha titiz. Bu sadece oyun değil; yer çekimini, dengeyi ve mekân ilişkilerini öğreniyor. Kule yıkıldığında "sebep-sonuç" ilişkisini kavrıyor. Ona farklı boyut ve renklerde küpler vererek bu önemli bilişsel süreci destekleyin.') WHERE id = '0c30df46-8b8a-4974-a5d4-fa643bc0045f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "kelime patlamasına" hazır olun! Çocuğunuz artık her gün yeni sesler ya da kelimeler öğreniyor. Çevresindeki nesneleri parmağıyla gösterip sizin onları adlandırmanızı bekliyor. Siz her şeyi adlandırdıkça pasif kelime hazinesi (anladığı kelimeler), aktif hazinesinden (söylediği kelimeler) daha hızlı büyüyor. Onunla sürekli konuşun; bu, konuşmasını hızlandıran en iyi yöntemdir.') WHERE id = '462a5499-02c0-46d8-9b87-781f37471081';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Benim!" dönemi başlıyor. Çocuk kendi oyuncaklarını ya da eşyalarını başkalarına vermeyi reddedebilir. Bu, "mülkiyet" kavramının ilk kıvılcımlarıdır. Ona "paylaşmalısın" diye baskı yapmayın; çünkü paylaşmanın ne olduğunu henüz tam anlamıyor. Bunun yerine sırayla oynamayı ("şimdi senin sıran, sonra babanın") göstererek sosyal kuralları öğretin.') WHERE id = 'bf0454b9-f968-4795-a96d-a48966050e5d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel aktivite: Çocuğunuz artık merdivenleri tırmanmaya çalışıyor (çoğu zaman emekleyerek ya da elinizden tutarak). Bu, hem bacak kaslarını hem de koordinasyonunu güçlendirir. Merdivenlerde her zaman yanında olun ve güvenlik bariyerleri kullanmayı unutmayın. Çıktığı her basamak onun için büyük bir "fetih" demektir!') WHERE id = '6d0b9b84-0a2e-4b5d-941c-44ac3c78711f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Kendi kendine beslenmede sıradaki adım: Çocuğunuz artık bardaktan suyu neredeyse hiç dökmeden içebiliyor. Açık bardaktan içmek, dudak ve dil kaslarını konuşmaya hazırlar. Hâlâ biberon kullanıyorsanız artık ondan tamamen uzaklaşmanın zamanı geldi. Bu, dişlerin doğru şekillenmesi ve damak sağlığı için çok önemlidir.') WHERE id = '59bb00a9-cd0f-4293-859e-3a1c2a23e167';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerde "karalama" sanatı! Çocuk artık kalemi tutup kâğıt üzerinde kararlı çizgiler çiziyor. Bu, el-göz koordinasyonunun ve yazıya hazırlık becerilerinin en erken aşamasıdır. Ona kalın, çocuklar için güvenli boya kalemleri ve büyük kâğıtlar verin. Bu ilk "yaratıcı çalışmalarını" övün; bu, sanata olan ilgisini artıracak.') WHERE id = '32044af7-f666-4ab4-a029-c8309f8e7a1b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "taklit" artık karmaşıklaşıyor. Sadece sizi değil; gördüğü diğer çocukları, hatta televizyondaki karakterleri de taklit edebiliyor. Siz evi temizlerken o da bir şeyler silmek, siz yemek yaparken o da karıştırmak istiyor. Ona oyuncak süpürge ya da plastik kaplar vererek onu "ev işlerine" dâhil edin. Bu, onda sorumluluk duygusunu geliştirir.') WHERE id = '0d48495d-8dfc-4d4f-a65f-4e2b54b5955c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Gece uykusunda "uyku gerilemesi" (bozulma) yaşanabilir. Bunun nedeni çoğu zaman yeni fiziksel beceriler (yürümenin hızlanması, tırmanma) ya da artan ayrılık kaygısıdır. Çocuğunuz gece uyanıp sizi çağırıyorsa sessizce yanına gidin, kucağa almadan onu sakinleştirin ve yeniden uykuya dalmasına yardımcı olun. Düzeni sabit tutmak bu geçici dönemi kolaylaştıracak.') WHERE id = '15f626ab-5c76-4c8c-ba7f-675666d5bc7d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Tebrikler, 400 günü tamamladık! Bu inanılmaz bir rakam. Çocuğunuz artık sadece bir "bebek" değil; kendi fikirleri, karakteri ve gülüşüyle ailenizin eşit haklara sahip, en aktif üyesi. Bugün onunla sevdiği parkta yürüyüşe çıkın ve dünyayı nasıl büyük bir merakla keşfettiğini izleyin. Siz bu yolda onun en güçlü dayanağı ve en sevecen öğretmenisiniz. Aferin size, anne!') WHERE id = 'cc5a3ed7-bfca-476b-b299-2377ba4200f3';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Taklit" artık daha bilinçlidir. Siz telefonla konuşurken o da eline bir şey alıp kulağına götürür; siz saçınızı tararken benzer bir hareket yapar. Bu, çocuğun günlük yaşam rutinlerini öğrenme yöntemidir. Güvenli ev eşyalarıyla (plastik tarak, oyuncak telefon) oynamasına izin vererek dünyayı tanımasına yardımcı olun.') WHERE id = 'ffb2b034-66cc-4cea-967c-b8e6e4f363c4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Kitap okumak artık etkileşimli bir etkinliğe dönüştü. Çocuk sayfaları kendi çevirmek ister ve resimlerde gördüğü tanıdık nesnelere sevinçle tepki verir. Ona "Araba nerede?" diye sorduğunuzda parmağıyla göstermesi, görsel hafızasının ve dikkatinin ne kadar güçlendiğini gösterir. Her akşam birkaç dakikayı kitap okumaya ayırmayı alışkanlık hâline getirin.') WHERE id = 'c199a72c-c2fe-4afe-b5cc-41415b0a5808';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Güvenlik hatırlatması: Çocuk artık tırmanmaya oldukça heveslidir. Sandalyeleri basamak gibi kullanarak masanın üzerine çıkabilir. Evdeki tüm ağır mobilyaların duvara sabitlendiğinden ve keskin köşelerin koruyucularla kaplandığından emin olun. Siz de onu rahatça uzaktan izleyebilmek için güvenli bir ortamda özgürce hareket etmesini sağlayın.') WHERE id = '4ee9c2b3-c8ac-4ff5-98d9-426713c0d86e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal gelişimde "İrade sınaması": Çocuk, istediği olmadığında ağlayarak veya kendini yere atarak itiraz edebilir. Bu dönemde onunla tartışmak yerine dikkatini başka, ilgi çekici bir şeye yönlendirmek daha etkilidir. Sakin bir ses tonuyla "Şu anda kızgınsın ama oyuncağı geri vermemiz gerekiyor" diyerek duygularını adlandırın. Sizin sakinliğiniz onun için en iyi örnektir.') WHERE id = '3cd65486-2777-46ac-9963-b43596b260f8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğun hafızası artık yaşananları daha uzun süre saklar. Birkaç saat, hatta gün önce sakladığınız oyuncağın yerini hatırlayıp bulabilir. Onunla "kayıp eşyayı bul" oyunu oynayın. Bu oyun hem hafızasını hem de görsel arama becerisini geliştirir. Bulduğunda onu coşkuyla övün ki başarmanın keyfini yaşasın.') WHERE id = '41a34496-6a48-46a1-9bab-58d653fd4147';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Kendi başına giyinme girişimleri artar. Çocuk artık ayakkabısını giymeye, şapkasını başına takmaya veya pantolonunun paçalarını çekmeye çalışır. Bu girişimlerine engel olmayın ve onu acele ettirmeyin. Ters giyse bile "Kendin yaptın, aferin!" deyin. Bunlar, bağımsızlığının ilk temelleridir.') WHERE id = '114533c6-2065-42b8-8349-baf02171f30b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Sözcük birleşimleri"nin ilk aşaması: Çocuk artık iki sözcüğü yan yana getirmeyi deneyebilir (örneğin, "Baba, bay bay" veya "Ver, su"). Henüz sözcükleri birleştirmiyorsa ona örnek olun. O "Araba" dediğinde siz "Evet, büyük araba" diyerek cümleyi tamamlayın. Bu, beyninde dil bilgisi yapılarının oluşmasına yardımcı olur.') WHERE id = '66c20a78-018b-46e0-a413-b9d7d652fd0b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: Çocuk artık elinde bir şey tutarak daha güvenli yürür. Aynı anda hem yürüyüp hem de oyuncağını size gösterebilir. Onun için bir "engelli parkur" hazırlayın: Yerdeki yastıkların etrafından dolaşmasını veya alçak bir kutunun üzerinden adım atmasını sağlayın. Bu, hem dengesini hem de bedenini kontrol etme duyusunu (propriyosepsiyon) güçlendirir.') WHERE id = '9f5b4f9d-6c12-455d-adaa-8991ef34a4ef';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Artık 400 günlük büyük dönüm noktasını geride bıraktık! Bu günlerde çocuğunuz kendi giysilerini (örneğin şapkasını veya çorabını) çıkarmaya çalışabilir. Bu, öz bakım becerilerinin ilk adımıdır. Bir şeyi giymek veya çıkarmak istiyorsa ona zaman tanıyın, acele ettirmeyin. Bir şeyi kendi başına yapabildiğini görmek, öz güvenini (self-esteem) her şeyden daha fazla artırır.') WHERE id = 'c405a38b-5463-4f2f-a8fe-555b36296982';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık "işlevsel oyun" döneminden "sembolik oyun"un ilk belirtilerine geçiyor. Oyuncak ayısını "besleyebilir" veya bebeğini uyutabilir. Bu, hayal gücünün ve empati duygusunun geliştiğini gösterir. Siz de bu oyunlara katılın: "Ayı acıkmış mı? Haydi ona biraz püre verelim." Bu tür oyunlar, sosyal ve bilişsel gelişimini hızlandırır.') WHERE id = 'a392702d-a437-4a73-9212-0aa4a4ef5685';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Heceleri birleştirme": Çocuğunuz artık farklı heceleri birleştirerek kendi dilinde uzun "cümleler" kuruyor. Söylediklerini tam olarak anlamasanız da yetişkinlerin konuşma tonlamasını mükemmel şekilde taklit ediyor. Onu dikkatle dinleyin ve "Öyle mi? Sonra ne oldu?" diye yanıt verin. Bu "diyalog", kendini ifade etme isteğini güçlendirir ve zihnindeki kelime hazinesini zenginleştirir.') WHERE id = '71d396d7-4d37-40f4-a3f7-9c1e6ac427ba';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Beslenmede bağımsızlık: Çocuğunuz artık çocuklar için güvenli bir çatal kullanmaya heveslidir. Yumuşak meyve veya sebze parçalarını çatala geçirmeye çalışmak, el-göz koordinasyonunu olağanüstü ölçüde geliştirir. Sofrada biraz dağınıklık olsa bile ona bu fırsatı tanıyın. Bu deneyim hem motor becerilerine hem de yemekle olumlu bir ilişki kurmasına katkı sağlar.') WHERE id = '333db3d2-14f1-4e63-a2dd-abc9df47ccf2';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Kategoriler": Çocuğunuz artık aynı renkteki veya aynı türdeki nesneleri ayırt etmeye başlıyor. Ona farklı topları veya arabaları gösterip "Diğer top nerede?" diye sorun. Benzerlikleri bulmaya başlayacaktır. Bu, mantıksal düşünme becerisinin temelidir. Onunla evdeki eşyaları renklerine veya boyutlarına göre gruplandırma oyunu oynayın.') WHERE id = 'e2b8df1f-c1e3-4ba1-a168-83dfc3901148';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal becerilerde "Yardımseverlik": Çocuğunuz sizi taklit ederek bir yeri silmek veya bir şey getirmek istiyorsa ona küçük "görevler" verin. Örneğin, "Lütfen bu bezi bana verir misin?" diyebilirsiniz. Size yardım ettiğini hissettiğinde kendini büyümüş ve ihtiyaç duyulan bir birey gibi hisseder. Bu, gelecekte sorumluluk duygusunun ve iş birliği ruhunun gelişmesi açısından çok önemlidir.') WHERE id = 'dec6a9fe-e431-4948-b5e9-cde4811493c1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel gelişim: Çocuğunuz artık olduğu yerde zıplamaya veya müzik eşliğinde dizlerini bükerek dans etmeye çalışıyor. Bu hareketler hem denge duyusunu hem de kaba motor becerilerinde görev alan kaslarını güçlendirir. Onunla birlikte dans edin ve hareketlerini tekrarlayın. Bu, hem fiziksel bir egzersiz hem de aranızdaki duygusal bağı güçlendiren en neşeli etkinliklerden biridir.') WHERE id = 'f2ba7880-c8a0-44c4-9683-adcae62249c7';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Mekân algısı" ve Yapı Blokları: Çocuğunuz artık küpleri yalnızca üst üste dizmekle kalmıyor, onlarla "duvarlar" veya basit şekiller yapmaya çalışıyor. Ona farklı boyutlarda yapı blokları verin. Bu oyunlar hem yaratıcılığını hem de problem çözme becerisini geliştirir. Kule yıkıldığında gülerek "Haydi, bir daha deneyelim!" demeniz, ona başarısızlıktan korkmamayı öğretir.') WHERE id = '3bcda1a7-5185-49d5-9cff-a4657ec214ad';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Gece uykusunda "Regresyon" veya korkular: 14. ayda bazı çocuklar karanlıktan veya yalnız kalmaktan korkmaya başlayabilir. Bu, bilişsel gelişiminin ve çevresini daha derinlemesine anlamasının bir sonucudur. Uyku öncesi rutininizi (masal okumak, ninni söylemek) düzenli şekilde sürdürün. Sizin sakin ve güven veren sesiniz ona "her şey yolunda, güvendesin" mesajını verecektir.') WHERE id = 'eff64bbb-3777-4339-9e6a-476beebba20d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Tebrikler, 410 günü geride bıraktık! Çocuğunuz artık her gün size yeni bir sürpriz yapıyor; ya yeni bir kelime söylüyor ya da yeni bir hareket öğreniyor. Bugün onunla yere uzanın ve yalnızca onun seçtiği bir oyunla vakit geçirin. Sizin onun dünyasına katılmanız, onun için en büyük mutluluktur. Siz bu yolda sabır ve sevgiyle ilerleyen harika bir annesiniz!') WHERE id = '21628582-4016-4734-a5cc-d731fc576c16';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık "Hayvan sesleri" dünyasına tamamen girdi. Ona "Köpek nasıl ses çıkarır?" veya "Kedi ne der?" gibi sorular sorun. Bu sesleri taklit etmek, konuşma organlarını (dil ve dudak kaslarını) gelecekte söyleyeceği karmaşık kelimelere hazırlar. Hayvan resimli kitaplar üzerinden bu diyalogları artırın; resimdeki hayvanı bulmasını ve sesini çıkarmasını isteyin.') WHERE id = '1ba32438-5f06-49eb-a326-d4e6c5037f1b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bağımsız yürüme artık daha güvenli hâle geldi. Çocuğunuz şimdi olduğu yerde dönmeyi, geri adım atmayı veya yürürken eğilip yerden oyuncak almayı öğreniyor. Bu, karmaşık bir denge egzersizidir. Ona engelleri (yastıklar, küçük kutular) aşma görevi verin. Bu tür fiziksel engeller hem kaba motor becerilerini hem de problem çözme yeteneğini güçlendirir.') WHERE id = '67533bf8-42c4-4684-8990-79465e5ffca9';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Adlandırma" aşaması: Çocuğunuz artık vücut bölümlerini (burun, göz, ağız) gösterebilir. Banyo yaptırırken veya giydirirken "Şimdi sağ kolunu giydiriyoruz", "Bu senin küçük burnun" diyerek her şeyi adlandırın. Bu, onun beden algısını geliştirmesine ve kelime dağarcığındaki sözcükleri görsel karşılıklarıyla eşleştirmesine yardımcı olur.') WHERE id = '616b6164-3d66-4e8e-8eaa-1c418d285de7';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Neden-Sonuç" ilişkisini gösteren oyunları tercih edin. Örneğin, düğmesine basıldığında ses çıkaran oyuncaklar veya kapağı açıldığında içinden bir şey çıkan kutular kullanabilirsiniz. Çocuğunuz, yaptığı bir hareketin çevresinde bir değişikliğe yol açtığını anlar. Bu keşif, onda "dünyayı etkileyebilme" duygusunu ve özgüveni geliştirir.') WHERE id = '8d3ed7f3-9547-466c-ba26-2f33141101eb';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Beslenme konusunda çocuğunuz artık aile sofrasındaki hemen hemen her şeyi (az tuzlu ve katkısız olmak şartıyla) yiyebilir. Kendi küçük çatal ve kaşığını kullanmasına izin verin. Yiyeceğe doğrudan elleriyle dokunması (dokusunu anlaması), yemek seçme eğilimini azaltır. Etrafın kirlenmesi normaldir; önemli olan, bağımsız yemek yeme alışkanlığı kazanmasıdır.') WHERE id = '724fdd08-1982-44c9-81ad-e2e9e494133c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Dizme" yeteneği: Çocuğunuz artık büyük boncukları ipe dizmeye (gözetiminiz altında!) veya halkaları piramit oyuncağına geçirmeye çalışır. Bu hareketler, parmak kaslarının koordinasyonunu en üst düzeye çıkarır. Ona farklı renk ve şekillerde halkalar vererek renkleri ve boyutları da (büyük-küçük) sesli olarak söyleyin.') WHERE id = '9a5df16b-402c-4293-a449-95f97975e102';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Merdivenleri tırmanmak artık onun en büyük ilgi alanlarından biri. Merdivenleri emekleyerek veya elinizden tutup ayakta çıkabilir. Bu hareket hem kaba motor becerilerini güçlendirir hem de yükseklik algısını geliştirir. Merdivenlerin başındayken daima yanında olun ve evdeki güvenlik kapılarının kapalı olduğundan emin olun.') WHERE id = '74e3ddee-b891-4ccd-91d8-7ed95452703e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık kağıt üzerinde "karalama" yaparken daha belirgin çizgiler çiziyor. Dairesel hareketler yapmayı veya düz çizgiler çizmeyi deneyebilir. Ona büyük kağıtlar ve avucuna rahatça sığan, kalın, toksik olmayan boya kalemleri verin. Bu, gelecekteki yazma becerilerinin ve el-göz koordinasyonunun en önemli temelidir.') WHERE id = '4d091261-3f36-4fe5-bf63-cb391c17abb5';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Ben kendim!" dönemi: Çocuğunuz artık ellerini yıkamaya, dişlerini fırçalamaya (şimdilik yalnızca fırçayı çiğneyerek) veya masayı silmeye hevesli. Hijyen alışkanlıklarına olan bu ilgisini destekleyin. Ulaşabilmesi için küçük bir basamak (step stool) yerleştirin ve hareketlerinizi taklit etmesine izin verin. Bu, öz bakım becerilerinin gelişmesini sağlar.') WHERE id = '1d418a62-b096-44ed-98d7-1fbf38ca6e83';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal oyunlarda "Taklit" daha karmaşık hale geliyor. Siz evi süpürürken o da bir şey alıp süpürmek istiyor. Ona çocuk boyutunda küçük "temizlik araçları" verin. Ev işlerine bu şekilde "yardım" etmesi, kendisini ailenin değerli bir üyesi gibi hissetmesini sağlar ve sorumluluk duygusunu geliştirir.') WHERE id = '9c0e73ce-723f-4070-afbc-322de1ae0633';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Yapı Blokları": Çocuğunuz artık 3-4 küpü (bloğu) üst üste koyarak bir "kule" yapabilir. Bu, hem dikkatini toplamasını hem de hassas hareket etmesini gerektirir. Kule yıkıldığında neşeyle tepki verin ki başarısızlığı oyunun bir parçası olarak görsün. Bu, problem çözme becerisini ve yeniden deneme isteğini güçlendirir.') WHERE id = '80068b19-aaa1-4996-ba9d-5b3777ebce0c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Müzik ve Ritim: Çocuğunuz artık farklı ritimlere farklı hareketlerle tepki veriyor. Hızlı müzikte daha aktif hareket ederken sakin müzikte sallanıyor. Onunla birlikte "ritim tutma" oyunları oynayın; ellerinizi çırpın, ayaklarınızı yere vurun. Bu, hem işitme becerisini hem de vücut koordinasyonunu büyük ölçüde geliştirir.') WHERE id = '83fcfed7-5b83-4a68-8d79-7654a496f70e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz beslenirken artık daha fazla bağımsızlık istiyor ve kaşığıyla kabından yiyecek alma konusunda daha başarılı. Ona çatalını batırabileceği (fork-friendly) küçük lokmalar sunun. Kendi kendine yemek yemesi, doyduğunu fark etmesine ve farklı dokulardaki yiyeceklere daha fazla ilgi duymasına yardımcı olur.') WHERE id = '369e5ef8-dd84-4005-92a0-3547d1d81f03';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal sınırlar: Çocuğunuz artık "hayır" dediğinizde tepkinizi ölçmek için o davranışı bilinçli olarak tekrarlayabilir. Bu dönemde sakin ve kararlı kalmak en önemli adımdır. Bir şeye "olmaz" dediyseniz bunu her seferinde aynı tonla ve aynı şekilde tekrarlayın. Kuralların tutarlı olması, çocukta güven ve düzen duygusu oluşturur.') WHERE id = '3b03f902-43dc-4352-9de9-99e2a04d004c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuzun yürümesi artık o kadar hızlandı ki bazen koşmaya çalışabilir. Ancak denge merkezi henüz tam gelişmediği için sık sık düşebilir. Keşfetmesi için ona daha fazla düz ve yumuşak alan (halı, çimenlik) oluşturun. Koşarken kollarını iki yana açarak dengesini korumaya çalışması, fiziksel gelişiminin doğal bir parçasıdır.') WHERE id = 'd5bd999f-15a8-4225-95dc-a3e29ec9bb65';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Hafıza gelişimi: Çocuğunuz artık eşyaların ait olduğu yerleri hatırlar. Örneğin ayakkabıların koridorda, oyuncakların ise kutuda olduğunu bilir. Ona "Ayakkabıların nerede?" dediğinizde o tarafa bakması veya orayı göstermesi, bilişsel gelişiminin ilerlediğini gösterir. Oyun bittikten sonra oyuncakları birlikte yerlerine koyarak düzen alışkanlığı kazanmasına yardımcı olun.') WHERE id = '821949a4-99c0-456c-ba4e-1768b6ba56ba';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Hayvanları ve seslerini ayırt etme". Çocuğunuz artık resimde gördüğü hayvanı yalnızca tanımakla kalmaz, siz sormadan onun sesini de çıkarabilir. Kitap okurken "Bak, bu bir inek. İnek nasıl ses çıkarır?" diyerek diyaloğu sürdürün. Bu, hem işitsel hafızasını hem de kelime dağarcığını hızla geliştirir.') WHERE id = 'ca9adb43-fa2c-4743-a4c9-e39c4eb29777';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Dizme ve Yerleştirme". Çocuğunuz artık 5-6 küpü üst üste koyarak daha yüksek kuleler yapabilir. Ayrıca halkaları büyükten küçüğe doğru dizme çabaları, mekânsal algısını geliştirir. Kuleyi yıkmaktan ne kadar keyif aldığını görüyor musunuz? Bu, "Ben dünyayı değiştirebilirim" (neden-sonuç) duygusunun en neşeli göstergesidir.') WHERE id = 'c50f5774-0c5b-40a4-8f99-e817382c1b20';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Beslenmede "Benim bardağım". Çocuğunuz artık açık bardaktan suyu neredeyse hiç dökmeden içebilir. Ona çocuklara uygun boyutta, kolay devrilmeyen (ağır tabanlı) plastik bardaklar verin. Kendi başına su içmesi, çene kaslarını konuşmaya hazırlar ve bağımsızlık duygusunu destekler.') WHERE id = 'cdcb59ac-ce34-4644-9101-dd165efadbd4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Ben" ve "Sen" arasındaki farkı kavrama. Çocuğunuz artık aynada kendini gördüğünde, yansımasına "başka bir çocuk" gibi değil, kendisi olarak tepki verir. Burnuna küçük bir renkli işaret koyup aynaya bakmasını sağlarsanız kendi burnundaki lekeyi silmeye çalışacaktır. Bu, benlik farkındalığının (self-awareness) geliştiğini gösteren en önemli testlerden biridir.') WHERE id = 'e44171a6-fe71-458b-9f01-6422077e41b3';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "İş birliği": Çocuğunuz artık size bir şey getirmekten, mutfakta yanınızda durup "yardım etmekten" keyif alır. Ona küçük ve güvenli görevler verin: "Bu kâğıdı çöp kutusuna atabilir misin?". Size yardım ettiğini hissettiğinde kendisini daha önemli ve değerli bir birey olarak görür.') WHERE id = 'd9f30f7c-bdc1-4054-b9fc-312496a93a19';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel cesaret: Çocuğunuz artık koltuktan yere kendi başına inmeyi (arkasını dönüp geriye doğru kayarak) öğrenebilir. Bunu güvenli bir şekilde nasıl yapacağını ona gösterin. Yüksek bir yerden kendi başına inmeyi öğrenmesi, beden kontrolünü ve riskleri değerlendirme becerisini geliştirir. Her zaman yakınında durarak güvenliğini sağlayın.') WHERE id = '594432bd-57c7-413f-839d-cbac2143ecbe';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Ben kendim seçerim!" dönemi. Giyinme veya beslenme konusunda çocuğunuza iki güvenli seçenek sunun. Örneğin: "Mavi çoraplarını mı giymek istersin, yoksa kırmızıları mı?". Bu yöntem, çocukta kontrol duygusu oluşturur ve ileride yaşanabilecek "inat krizleri"ni önlemeye yardımcı olur. Seçim yapmak, karar verme becerisinin temelidir.') WHERE id = '3e2f13ff-1204-4de3-91f9-ba0a61eced52';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor beceriler için "Sınıflandırma" oyunları. Çocuğunuz artık küpleri renklerine veya boyutlarına göre ayırmaya başlayabilir. Ona farklı renklerde kaplar verin ve aynı renkteki oyuncakları ilgili kaplara koymayı gösterin. Bu oyun hem mantıksal düşünme becerisini hem de renk algısını hızla geliştirir.') WHERE id = '1833bec9-62a3-4273-aaa3-6cb2d5b43918';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışlarda "Empati" gelişiyor. Çocuğunuz başka bir çocuğun ağladığını gördüğünde endişelenebilir veya yanınıza gelip size sarılabilir. Bu, artık başkalarının duygularını hissedebildiğini gösterir. "Evet, arkadaşın şu anda biraz üzgün" gibi cümlelerle bu duyguları adlandırın. Duyguları tanımak, duygusal zekânın ilk basamağıdır.') WHERE id = 'da7ee871-54fe-4caf-9b11-def1fe5482db';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Beslenmede "Araç gereç kullanımı". Çocuğunuz artık çocuk çatalını (plastik/yumuşak) yiyeceklere batırma konusunda daha beceriklidir. Ona çatalını batırabileceği yumuşak muz veya pişmiş havuç parçaları verin. Bu etkinlik hem el koordinasyonunu güçlendirir hem de yemek sürecini onun için eğlenceli bir "beceri denemesi"ne dönüştürür.') WHERE id = '451ba512-8b9d-44f7-915a-a7f1ea152f7c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Hayal gücünün gelişimi: "Pretend play" (mış gibi oyun). Çocuğunuz artık boş bir fincandan "su içiyormuş" gibi yapabilir veya oyuncak arabasıyla "vın-vın" sesi çıkarabilir. Bu oyunlara siz de katılın: "Araba nereye gidiyor? Markete mi?". Bu, hem yaratıcılığını hem de olaylar arasındaki mantıksal bağlantıyı güçlendirir.') WHERE id = '58538226-5b39-4731-8bc6-1e9881002e44';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İrade ve Sınırlar: Çocuğunuz artık "Olmaz" sözüne tepki verir, ancak bazen o davranışı bilerek yapıp size bakar. Bu, sabrınızı ve kuralların değişmezliğini sınama biçimidir. Sakin ama kararlı olun. "Olmaz" dediğiniz bir şeye başka bir zaman izin vermeyin; böylece kurallar onun zihninde tamamen netleşir.') WHERE id = 'ccb50bdf-5e11-4253-a1c0-79b7eb2fe4d0';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık geri geri yürümeyi veya olduğu yerde dönmeyi keşfetti. Bu hareketler, denge duyusunu ve vücut koordinasyonunu yeni bir seviyeye taşır. Engelsiz ve geniş bir alanda bu yeni becerilerini denemesine fırsat tanıyın. Vücudunu kontrol etme becerisi arttıkça özgüveni de aynı ölçüde güçlenir.') WHERE id = '527b5771-2c14-44f3-9a1f-7d0335d59d5a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Niyet" bildiren sözcükler: Çocuğunuz artık yalnızca nesneleri adlandırmakla kalmaz, isteklerini de tek sözcüklerle ifade eder. Örneğin, size bakarak "Kapı" demesi, "Dışarı çıkmak istiyorum" anlamına gelebilir. Siz de bu ifadeleri genişleterek yanıt verin: "Evet, kapıyı mı gösteriyorsun? Hadi, bahçeye (atta) gidelim". Bu, iletişim kurma isteğini artırır.') WHERE id = '1b9f532e-6857-454f-9361-0a20bbd28a5f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal krizler ve "Tantrum"lar. Çocuğunuz her şeyi kendi başına yapmak istediğinde ve başaramadığında aniden öfkelenebilir. Bu, istekleri ile fiziksel becerilerinin henüz tam olarak örtüşmemesinden kaynaklanan bir gerginliktir. Böyle anlarda ona sarılın ve sakince "Oyuncağı düzeltemediğin için öfkelendin, seni anlıyorum" diyerek duygusunu adlandırın.') WHERE id = '52ab2a35-efc6-4dfa-ae8e-dd8d45265cbf';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Sözcük tekrarı". Çocuğunuz artık söylediğiniz her sözün ardından kendi dilinde bir şeyler söylemeye çalışır. Bu, dil öğreniminin en aktif dönemidir. Onunla konuşurken basit, kısa ve anlaşılır cümleler kurun. Siz onun en temel konuşma modelisiniz. Bugün onunla sevdiği masalı okuyun ve resimdeki gizli ayrıntıları birlikte bulmaya çalışın.') WHERE id = '36237c33-88c9-45f0-bb2f-74a99cfea0e7';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık nesneleri yalnızca toplamakla kalmayıp renklerine göre gruplandırmaya da başlayabilir. Ona iki farklı renkte kap verin ve aynı renkteki küpleri uygun kaplara nasıl koyacağını gösterin. Bu oyun, görsel algısını ve mantıksal düşünme becerisini hızla geliştirir. Her doğru seçiminde onu teşvik edin.') WHERE id = 'c99fbd76-3509-452c-bb85-8931e45ac6e6';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Kendi başına giyinme girişimleri daha amaçlı hâle gelir. Çocuğunuz çorabını çekip çıkarabilir veya şapkasını başına takmaya çalışabilir. Bu "öz bakım" alıştırmaları için ona zaman tanıyın. Acele ettirmeden bir şeyleri kendi başına yapabilmesine fırsat vermek, öz güvenini (self-esteem) her şeyden daha fazla artırır.') WHERE id = '2ee741f0-6ac8-462c-a88b-0f41a8cfe7f1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Hayal gücünün gelişimi: "-mış gibi yapma" (Pretend play) oyunları başlar. Çocuğunuz boş oyuncak fincandan su içiyormuş gibi yapabilir veya bebeğini "uyutabilir". Bunlar, soyut düşünme becerisinin ilk işaretleridir. Bu oyunlarına katılın ve yeni sorularla (örneğin, "Ayıcık acıkmış mı?") hayal gücünü destekleyin.') WHERE id = 'b84b66d1-b1ba-4c15-8fdd-579e274e0daa';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel çeviklik: Çocuğunuz artık olduğu yerde zıplamayı deniyor. Henüz iki ayağı aynı anda yerden kesilmeyebilir ancak dizlerini büküp açarak bu hareketi taklit eder. Bu, kaba motor kaslarının ve denge duyusunun güçlenmesi için harika bir egzersizdir. Onunla birlikte ritmik müzik eşliğinde dans edin.') WHERE id = 'd53255ec-c9a7-49ab-9a79-7b2313a09598';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Soru-Cevap" dönemi. Çocuğunuz artık "Bu nedir?" (veya kendi dilinde buna benzer bir ses) diyerek nesneleri gösterir. Siz de sabırla her şeyin adını söyleyin: "Bu kırmızı bir araba", "Bu büyük bir ağaç". Merakını yanıtsız bırakmamak, kelime dağarcığının aktif olarak zenginleşmesine yardımcı olur.') WHERE id = 'd7ddb1ff-3688-4df3-8111-1494d13b6470';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Kalem tutuşu". Çocuğunuz artık kalemi avucuyla değil, parmaklarıyla tutmaya yaklaşır. Kâğıt üzerinde daha belirgin daireler veya çizgiler çizer. Ona çocuklar için güvenli, kalın renkli kalemler verin ve "yaratıcılık" alanını genişletin. Bu, gelecekteki yazma becerilerinin temelidir.') WHERE id = '785f6c05-389d-4b59-bf24-09d238f78a91';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Paylaşma güçlüğü". Bu yaşta "benim" kavramı çok güçlüdür. Çocuğunuz oyuncağını başka bir çocuğa vermek istemediğinde bu, bencillik değil, gelişimin doğal bir aşamasıdır. Onu paylaşmaya zorlamayın; bunun yerine "sırayla oynama" kuralını gösterin. Zamanla bu sosyal kuralı benimseyecektir.') WHERE id = '634d745d-5157-4467-b6ab-326f97a6818e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Beslenmede "Araç gereç kullanımı". Çocuğunuz artık çocuk çatalını yemeğe (örneğin pişmiş havuca veya patatese) batırıp ağzına götürürken daha isabetlidir. Bu beceri hem el-göz koordinasyonunu güçlendirir hem de kendisini bağımsız bir birey olarak hissetmesine yardımcı olur.') WHERE id = '3cb1db52-5d88-4edb-a3ab-0984a9450809';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Mekânsal farkındalık": Çocuğunuz artık dar yerlerden geçmeyi, engellerin altından emeklemeyi veya üzerinden adım atmayı öğreniyor. Evde yastıklar ve kutularla küçük bir "engel parkuru" hazırlayın. Bu, bedeninin boyutlarını algılamasına (propriyoseptif duyular) ve hareketlerini planlamasına yardımcı olur.') WHERE id = '2b1c5f94-7b82-40ce-9f0d-d663053b5141';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal bağ: Çocuğunuz artık size olan sevgisini daha belirgin davranışlarla gösterir; aniden gelip size sarılabilir veya saçınızı okşayabilir. Siz de ona aynı şefkatle karşılık verin. Bu duygusal paylaşım, kendisini güvende ve değerli hissetmesi için en önemli besindir.') WHERE id = 'de41f735-eeb7-4ab7-ab3c-cfc2d80548ba';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '16. aya adım atıyoruz! Çocuğunuz artık bilinçli olarak "Baba" ve "Anne" dışında 5-10 farklı sözcük söyleyebilir. Sözcükleri henüz tam doğru telaffuz edemese de her birinin belirli bir anlamı vardır. Her denemesini destekleyin ve söylediği eksik sözcüğü tam bir cümleyle doğrulayın. Örneğin, "Ara" dediğinde siz de "Evet, bu bir arabadır" diye karşılık verin.') WHERE id = 'd807a9a4-6329-44cd-97d5-dae1bf4a8ff6';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte yeni bir aşama: Çocuğunuz artık elinden tuttuğunuzda merdivenleri ayakta çıkarabilir. Bu hareket, uyluk ve kalça kaslarını güçlendirir. Merdivenlerde her zaman yanında olun ve ona destek verin. Evinizdeki merdiven girişlerinde bulunan güvenlik kapılarının (gate) kapalı olduğundan emin olmayı unutmayın.') WHERE id = '22600f5c-8f2a-4f8d-9f3c-76e5a5fcda2c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık basit yönergeleri yerine getirmekten keyif alır. "Lütfen topu bana getir" veya "Şapkanı al" dediğinizde bunları yapabilir. Bu, alıcı dilinin (anlama becerisinin) ne kadar geliştiğini gösterir. Ona küçük ve keyifli görevler vererek hem dil gelişimini hem de sorumluluk duygusunu destekleyin.') WHERE id = '44a68c23-5478-40d4-a83c-2dc9f09d429d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Benim!" kavramı daha da belirginleşir. Çocuğunuz en sevdiği oyuncağını başkasına vermek istemediğinde kararlı davranabilir. Bu, kişisel sınırlarını tanımaya başladığını gösterir. Onu paylaşmaya zorlamayın; bunun yerine oyuncakları sırayla kullanmayı ("şimdi sıra sende, sonra babanda") göstererek sosyal adalet duygusunu geliştirin.') WHERE id = '3dc015ff-56bb-4a43-b76e-ffb3ffd6a8c8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde ustalaşma: Çocuğunuz artık yapı bloklarını (küpleri) yalnızca üst üste dizmekle kalmıyor, onları yan yana getirerek "tren" veya "yol" yapmaya çalışıyor. Bu, mekânsal algısının daha karmaşık bir düzeye geçtiğini gösterir. Ona farklı şekillerde yapı blokları vererek yaratıcılığını teşvik edin.') WHERE id = '05f48dd1-b441-4a53-83ad-213693a97b1c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Beslenmede "Seçici iştah" dönemi. Çocuğunuz aniden bazı yiyecekleri reddedebilir. Bu, tat alma duyusunun gelişmesinden ve kendi iradesini ortaya koyma isteğinden kaynaklanır. Onu zorlamayın; ancak reddettiği yiyeceği birkaç gün sonra farklı bir biçimde (örneğin püre yerine dilimler hâlinde) yeniden sunun. Sofrada olumlu bir atmosferi koruyun.') WHERE id = '01373d24-e28a-437e-998d-4ae78f2851c2';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık kâğıda "karalamalar" yaparken daha geniş hareketler kullanıyor. Kalemi daha güvenli tutuyor ve bazen renkleri ayırt etmeye çalışıyor. Ona çocuklar için güvenli, kalın boya kalemleri ve büyük resim kâğıtları verin. Bu ilk "sanat eserleri", hem el-göz koordinasyonu hem de kendini ifade etme becerisi açısından çok değerlidir.') WHERE id = '10f5c993-c3c9-44f8-a870-3ed80a4cfbed';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Taklit" artık günlük işlere de yansıyor. Siz evi temizlerken o da bir yerleri silmek, siz yemek yaparken o da karıştırmak istiyor. Ona küçük bir temizlik bezi veya oyuncak süpürge verin. Bu, çocuğun kendini ailenin faydalı bir üyesi olarak hissetmesine ve yararlı alışkanlıklar kazanmasına yardımcı olur.') WHERE id = 'd75c2f77-0a11-4bee-830a-88006d025c3c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Denge ve koordinasyon: Çocuğunuz artık olduğu yerde zıplamaya çalışıyor. Henüz iki ayağı aynı anda yerden kesilmeyebilir; ancak dizlerini büküp yukarı doğru yaylanması, kaba motor becerilerinin geliştiğini gösterir. Onunla birlikte ritmik müzik eşliğinde dans edin. Bu, hem eğlenceli hem de fiziksel açıdan çok yararlı bir egzersizdir.') WHERE id = '47585bf0-21b2-4948-bcc0-cc0d44631bdd';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal gelişimde "İstek ve Olanak" çatışması. Çocuğunuz bir şey yapmak istediğinde başaramazsa bağırabilir veya öfkelenebilir. Böyle anlarda sakin kalın ve duygularını adlandırın: "Küpler devrildiği için öfkelendin, seni anlıyorum". Sizin bu anlayışınız, ona duygularını yönetmeyi ve zorluklar karşısında cesaretini kaybetmemeyi öğretir.') WHERE id = 'a0a20bce-4839-4117-9368-c41ef5150778';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık vücut bölümlerini (el, ayak, karın) yalnızca göstermekle kalmıyor, adlarını söylemeye de çalışıyor. Onu giydirirken "Senin karnın nerede?" diye sorun ve yanıt vermesi için ona zaman tanıyın. Bu, beden algısını geliştirmesi ve kelime dağarcığını aktif biçimde kullanması için mükemmel bir egzersizdir.') WHERE id = '9f429553-7b9f-4533-9a8c-fa277c16a3ea';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bağımsızlık isteği giyinme konusunda kendini göstermeye başlıyor. Çocuğunuz çorabını çekerek çıkarabilir veya şapkasını başına takmaya çalışabilir. Bu "öz bakım" girişimlerine engel olmayın. Onu acele ettirmeden kendi başına bir şeyler yapabilmesine fırsat vermek, öz güvenini (self-esteem) her şeyden daha fazla artırır.') WHERE id = 'eb7b56da-4f69-416f-ae1f-039fef91ef94';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Sözcük öbekleri"nin ilk işaretleri: Çocuğunuz artık iki sözcüğü yan yana getirebilir (örneğin, "Baba, gel" veya "Ver, su"). Henüz sözcükleri birleştirmiyorsa ona örnek olun. O, "Top" dediğinde siz de "Evet, büyük top" diyerek cümleyi tamamlayın. Bu, beyninde dil bilgisi yapılarının oluşmasına yardımcı olur.') WHERE id = '6753f0e0-f84e-40f2-a42e-a2fc56030ffe';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Kitap sayfaları": Çocuğunuz artık kalın karton sayfaları tek tek çevirmede daha beceriklidir. Ona etkileşimli, dokun-hisset öğeleri içeren kitaplar sunun. Sayfayı kendisinin çevirmesi hem bağımsızlık duygusunu geliştirir hem de küçük parmak kaslarını yazmaya hazırlık için çalıştırır.') WHERE id = 'ed122971-473f-43f3-a24c-a44303a6f746';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Beslenmede "Çatal kullanma": Çocuğunuz artık çocuk çatalını yiyeceğe (örneğin, yumuşak pişmiş bir sebzeye) batırıp ağzına götürmede daha başarılıdır. Bu beceri hem el-göz koordinasyonunu güçlendirir hem de kendisini bağımsız bir birey olarak hissetmesine yardımcı olur. Sofra biraz dağılsa da ona bu fırsatı verin.') WHERE id = '28156e7f-7e18-4b94-927c-a444469bee3e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Mekânsal bellek" ve arama: Çocuğunuz artık birkaç saat önce nereye koyduğunuz oyuncağı hatırlayıp bulabilir. Onunla "kayıp eşyayı bul" oyunu oynayın. Bu oyun hem görsel belleğini hem de dikkatini toplama becerisini geliştirir. Bulduğu her eşya onun için küçük bir "keşif" zaferidir.') WHERE id = '15ff0052-98cf-4d44-8277-9931b5bbd7bd';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışlarda "Empati" gelişir. Çocuğunuz başka birinin (veya oyuncağının) "canının yandığını" gördüğünde ona sarılabilir ya da onu okşayabilir. Bu, başkalarının duygularını anlamaya başladığını gösterir. Bu duyguları "Evet, arkadaşın şu anda biraz üzgün" gibi cümlelerle adlandırarak duygusal zekâsını destekleyin.') WHERE id = '6c93684c-6781-4a11-bb15-1580d5f66d36';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: Çocuğunuz artık olduğu yerde dönmeyi ve geriye doğru adım atmayı öğrenir. Bu, karmaşık bir denge egzersizidir. Geniş ve engelsiz bir alanda bu yeni becerilerini denemesine olanak tanıyın. Vücudunu kontrol etme becerisi arttıkça düşme korkusu azalır ve hareket alanı genişler.') WHERE id = '33b5778f-3fe2-440a-8f22-62f63b5a956d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Hayal gücünün gelişimi: "-mış gibi yapma" (Pretend play) oyunları daha karmaşık hâle gelir. Çocuğunuz oyuncak arabasıyla "vın-vın" sesi çıkarabilir veya boş bir tabaktan "yemek yiyormuş" gibi yapabilir. Bu oyunlara katılın ve yeni sorularla hayal gücünü harekete geçirin. Bu, hem yaratıcılığını hem de mantıksal bağlantılar kurma becerisini güçlendirir.') WHERE id = 'd2fca029-5edb-4176-b69f-5a506afd4a61';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İrade ve Sınırlar: Çocuğunuz artık "Olmaz" sözüne tepki verir, ancak bazen aynı davranışı bilerek yapıp size bakar. Böylece sabrınızı ve kuralların değişmezliğini sınar. Sakin ama kararlı olun. Kuralların tutarlı olması, çocukta güven ve düzen duygusu oluşturur.') WHERE id = '3e76b053-c97c-4476-b999-951be493bb64';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık nesneleri yalnızca bir araya toplamakla kalmıyor, renklerine göre gruplandırmaya da çalışıyor. Ona iki farklı renkte kap verin ve aynı renkteki oyuncakları uygun kaplara nasıl koyacağını gösterin. Bu oyun, görsel algısını ve mantıksal düşünme becerisini hızla geliştirir. Öğrenmeye olan ilgisinin artması için her doğru seçiminde onu teşvik edin.') WHERE id = '7aebe8cd-a4e5-44f9-8f57-fc363b89129a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Geri adım". Çocuğunuz artık geriye doğru yürümeyi keşfetti. Bu, karmaşık bir denge egzersizidir ve vücut koordinasyonunun ne kadar geliştiğini gösterir. Engelsiz ve yumuşak bir alanda bu yeni becerisini denemesine olanak tanıyın. Vücudunu kontrol etme becerisi arttıkça öz güveni de aynı ölçüde güçlenir.') WHERE id = '23d55f43-944e-41ff-a1f0-31e749c5ea5d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Soru ve Merak". Çocuğunuz artık "Bu nedir?" (veya kendi dilinde buna benzer bir ses) diyerek nesneleri gösteriyor. Siz de sabırla her şeyin adını söyleyin: "Bu kırmızı bir arabadır", "Bu büyük bir ağaçtır". Merakını karşılıksız bırakmamak, hem pasif hem de aktif kelime dağarcığının zenginleşmesine yardımcı olur.') WHERE id = '741cbef2-ffcd-4b10-9cdf-8e41aa164e28';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Şakalar". Çocuğunuz oyuncağı bilerek size uzatıp hemen geri çekiyor ve buna gülüyor mu? Bu, mizah anlayışının ve sosyal etkileşim becerisinin gelişmeye başladığını gösterir. Siz de bu "oyununa" coşkuyla katılın. Birlikte gülmek aranızdaki duygusal bağı güçlendirir ve olumlu bir öz güven geliştirmesine yardımcı olur.') WHERE id = '5a726b9c-27a1-4456-85ed-e5c0d76d2484';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Piramit ve Halkalar". Çocuğunuz artık halkaları büyükten küçüğe (veya tam tersine) sıralama konusunda daha becerikli. Bu hareket hem boyut kavramını (büyük-küçük) anlamasını hem de el-göz koordinasyonunu geliştirir. Halkaları dizerken renklerin adlarını da söyleyin.') WHERE id = '51378f6a-c746-490d-b2e3-d4da3d093685';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Suyumu kendim içiyorum". Çocuğunuz artık açık bir bardaktan suyu neredeyse hiç dökmeden içebilecek düzeye geldi. Ona çocuklara uygun boyutta, kolayca devrilmeyen (ağır tabanlı) plastik bardaklar verin. Suyunu kendisinin içmesi, dudak ve dil kaslarını konuşmaya hazırlar ve bağımsızlık duygusunu destekler.') WHERE id = '44c70121-397f-4987-8f6a-6aae583c01e5';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Hayal gücünün gelişimi: "Yemek pişirme" oyunu. Çocuğunuz oyuncak kaplarıyla bir şeyler "pişiriyormuş" gibi yapabilir. Siz de bu oyunlara katılın: "Bana da biraz yemek verir misin?". Bu, günlük yaşam rutinlerini ne kadar dikkatle gözlemlediğini ve hayal gücünün nasıl geliştiğini gösterir.') WHERE id = '0303ebf1-df3e-4e81-bd4e-6f1dea97c188';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel cesaret: Çocuğunuz artık alçak basamaklara veya koltuğun kenarına tek başına tırmanmaya çalışıyor. Yükseklik algısı gelişse de riskleri henüz tam olarak kavrayamaz. Her zaman yakınında durarak güvenliğini sağlayın ve ona güvenli şekilde inme yollarını (örneğin geriye doğru inmek) gösterin.') WHERE id = '4a36804a-6409-441e-bfa1-5d47aa7ddf64';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Hayvanları ve seslerini ayırt etme". Çocuk, resimde gördüğü inek ile kediyi artık birbirinden ayırabilir ve sorulmadan seslerini taklit edebilir. Kitap okurken "Burada kedi nerede?" diye sorduğunuzda parmağıyla göstermesi, görsel hafızasının ve dikkatinin ne kadar güçlendiğini gösterir.') WHERE id = '48266b98-24f4-486a-8c86-5edb343f6455';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal sınırlar ve "Hayır". Çocuk her şeyi kendi başına yapmak istediğinde ve başaramadığında birden öfkelenebilir. Böyle anlarda ona sarılın ve sakince "Ayakkabını giyemediğin için öfkelendin, seni anlıyorum" diyerek duygusunu adlandırın. Sizin bu sakinliğiniz, ona duygularını yönetmeyi öğreten en iyi örnektir.') WHERE id = 'bd6e2ef7-be9f-49e8-9f5a-73c5aca2c6c7';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuk artık kendi zevkini ortaya koyar. Giymek istediği tişörtü veya okumak istediği kitabı kararlılıkla seçebilir. Bu dönemde ona "sınırlı seçim" fırsatı sunun: "Bugün kırmızı tişörtü mü, yoksa mavi tişörtü mü giymek istersin?". Bu, onda kontrol duygusu oluşturur ve ileride yaşanabilecek inatlaşma krizlerini önlemeye yardımcı olur.') WHERE id = 'e2f29ee5-abb0-4ec5-8bfb-7fca6b238c4f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel gelişimde "Koşma becerisi". Çocuk artık koşarken dengesini daha iyi koruyabilir ve aniden durabilir. Bu, kas gücünün ve beyin-kas koordinasyonunun ne kadar geliştiğini gösterir. Parkta veya bahçede engelsiz koşabileceği alanlar bularak enerjisini atmasına fırsat verin.') WHERE id = '85cc1293-16e0-49cd-904b-171804ae1853';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Sözcük öbekleri". Çocuk artık iki sözcüğü yan yana getirerek basit cümleler kurar: "Baba, gel", "Ver, elma". Henüz sözcükleri birleştirmiyorsa söylediği tek sözcüğü siz genişletin: "Evet, sen elma mı istiyorsun? Al, sana lezzetli bir elma". Bu, beynindeki dil bilgisi yapılarını güçlendirir.') WHERE id = '3ec1877f-e8dc-4ba3-893d-678bde1927b1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor gelişiminde "Puzzle" (yapboz) dönemi. Çocuk artık 2-3 parçalı basit puzzle''ları tamamlamayı veya şekilleri uygun deliklere yerleştirmeyi öğrenir. Bu oyun hem görsel algısını hem de problem çözme becerisini önemli ölçüde geliştirir. Başaramadığında ona sakince yardım edin ve cesaretlendirin.') WHERE id = 'b4b1a4bc-e49d-4497-b688-464c24f79875';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Paralel oyun". Çocuğunuz başka çocuklarla bir aradayken onlarla değil, onların yanında kendi başına oynar. Bu, 17. ay için tamamen normaldir. Diğer çocukları gözlemleyerek pek çok şey öğrenir. Sosyal ortama uyum sağlaması için onu yaşıtlarıyla bir araya getirmeye devam edin.') WHERE id = '0d8b6018-4d34-41fe-ad70-9143e9c2615f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Kendi kendime yıkanıyorum". Çocuk banyo yaparken veya ellerini yıkarken sabunu ya da süngeri alıp kendi vücudunu temizlemeye çalışır. Hijyen alışkanlıklarına duyduğu bu ilgiyi destekleyin. Kendisini "temizlemesi", vücudunun bölümlerini daha iyi tanımasına ve bağımsızlık duygusunun gelişmesine yardımcı olur.') WHERE id = '3c2bb527-c368-4b69-94c1-76665087b2b9';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Hafızanın güçlenmesi: "Kayıp eşyalar". Çocuğunuz, sakladığınız oyuncağı bulmak için daha karmaşık yöntemler kullanır; örtüyü kaldırır, kutunun içine bakar. Bu, "nesne sürekliliği" kavramının zihninde tamamen yerleştiğini gösterir. Evde onunla küçük "hazine avı" oyunları oynayarak dikkatini geliştirebilirsiniz.') WHERE id = 'd0afa5e2-c732-43e9-af9d-2f3d19c36c4e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Hayal gücü ve "Ev işleri". Çocuğunuz oyuncak telefonuyla "konuşur" veya oyuncak süpürgesiyle yerleri süpürür. Sizin her hareketinizi taklit eder. Bu taklit, onun dünyayı öğrenme yöntemidir. Kendine ait küçük "iş aletleri" vererek kendini önemli hissetmesini sağlayabilirsiniz.') WHERE id = '9dfb3516-1999-4989-989e-9e6fdb3fb9e5';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel cesaret: "Tırmanma becerisi". Çocuğunuz artık merdivenleri kendi başına çıkmaya (şimdilik emekleyerek veya elinizden tutarak) oldukça heveslidir. Yükseklik algısı geliştikçe ona inmeyi de öğretmek gerekir. Merdivenlerden geriye doğru inmenin daha güvenli olduğunu her zaman gösterin.') WHERE id = '15095e09-193b-4e26-bc2e-4f81de7c413d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Tebrikler, 500 günü tamamladık! Çocuğunuz artık bebeklik dönemini tamamen geride bırakarak kendi karakteri ve iradesi olan küçük bir çocuğa dönüştü. Bugün onunla sevdiği bir etkinliği yaparak (örneğin resim çizerek veya parkta yürüyüşe çıkarak) vakit geçirin. Sabrınız ve sevginiz, onu bu noktaya getiren en büyük güç. Aferin size, Anne!') WHERE id = '3427ae53-cf26-4b28-928a-b9787dc9cf32';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık "Ben" kavramını davranışlarıyla ortaya koyuyor. Kıyafetini seçmek veya yemeğini kendi başına yemek istemesi, bağımsızlık belirtisidir. Ona bu fırsatı tanıyın: "Hangi tişörtü giymek istersin?". Küçük seçenekler sunmak hem karar verme becerisini geliştirir hem de inatlaşma krizlerini azaltır.') WHERE id = '1f190c82-9146-4726-b79a-d4e22c530f6d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Engelleri aşma". Çocuğunuz artık yerdeki oyuncakların ve yastıkların üzerinden adım atarak ya da etraflarından dolaşarak geçmeyi öğreniyor. Bu, gelişmiş bir mekânsal algı becerisidir. Evde güvenli engeller oluşturarak hem dengesini hem de bedenini kontrol etme becerisini geliştirebilirsiniz.') WHERE id = '0762347b-3e67-4f92-a1cc-28fc730be874';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Kelimelerin anlamı". Çocuğunuz artık yalnızca tekrar etmiyor, kelimeleri belirli durumlara uygun biçimde kullanıyor. Örneğin, siz ayakkabılarınızı giyerken "Atta" (dışarı) diyebilir. Bu ifadelerini genişletin: "Evet, şimdi ayakkabılarımızı giyip parka gidiyoruz". Bu, zihninde olaylarla kelimeler arasındaki bağı güçlendirir.') WHERE id = '32725b0c-885a-420b-8b00-82ddb5c437d8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Tasarım ve İnşa". Çocuğunuz artık küpleri yalnızca üst üste dizmekle kalmıyor, onlarla "tren" veya "çit" gibi yatay şekiller oluşturmaya çalışıyor. Bu, mekânsal düşünme becerisinin yeni bir aşamaya geçtiğini gösterir. Ona farklı şekillerde yapı oyuncakları vererek hayal gücünü destekleyin.') WHERE id = 'd22bf585-b849-4796-8341-19d360ee9434';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Empati" belirtileri. Çocuğunuz üzgün olduğunuzu veya bir yerinizi incittiğinizi gördüğünde yanınıza gelip size dokunabilir, hatta size sarılabilir. Bu, artık başkalarının duygularını anlayabildiğini gösterir. "Bana destek olduğun için teşekkür ederim" diyerek bu duygusunu adlandırın. Bu, duygusal zekânın temelidir.') WHERE id = '3a9d7d72-ab6c-4777-b054-a56b8986ee74';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Kendi kendine temizlik". Çocuğunuz sizi taklit ederek ellerini yıkamaya, yüzünü silmeye veya dişlerini fırçalamaya (şimdilik sadece fırçayı çiğneyerek) heves eder. Bu bağımsızlık isteğini engellemeyin. Ulaşabilmesi için önüne bir basamak (step stool) koyun ve hareketlerinizi tekrarlamasına izin verin. Bu, öz bakım becerilerinin gelişmesini sağlar.') WHERE id = '090f40d7-6abc-46b1-8914-c34325dbcaa0';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Hafıza ve "Mekânsal hafıza". Çocuğunuz artık oyuncağının nereye saklandığını uzun süre hatırlayabilir. Onunla evde küçük "hazine avı" oyunları oynayın. Bir nesneyi örtünün altına saklayın ve onu bulmasını izleyin. Bu oyunlar hem dikkatini toplamayı hem de sorunlara çözüm bulmayı öğretir.') WHERE id = '0bfe8ad5-dcd4-46e4-af49-e5c2a87c763e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Hayal gücünün gelişimi: "-mış gibi yapma" (Pretend play). Çocuğunuz artık boş bir fincandan "çay içiyormuş" gibi yapabilir veya bebeğine "yemek yedirebilir". Siz de bu oyunlara katılın. Bu tür oyunlar, çocuğun hem yaratıcılığının gelişmesini hem de günlük yaşam rutinlerini anlamasını hızlandırır.') WHERE id = '9a097c94-eb06-4b23-b839-a6859f4ee3f2';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel cesaret: "Tırmanma ve İnme". Çocuğunuz artık alçak basamaklara veya kanepenin kenarına tek başına tırmanmaya çalışır. Yükseklik algısı gelişse de henüz riskleri tam olarak kavrayamaz. Ona geri geri inmenin her zaman daha güvenli olduğunu gösterin. Bu hareketleri sizin gözetiminizde yapması, beden kontrolünü güçlendirir.') WHERE id = '0f9b9189-8ffa-4276-919f-031f8673dbe8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal sınırlar ve "Hayır". Çocuğunuz artık "Olmaz" sözüne tepki verir, ancak bazen aynı davranışı bilerek yapıp size bakar. Bu, sabrınızı ve kuralların değişmezliğini sınama biçimidir. Sakin ama kararlı olun. Kuralların tutarlı olması, çocukta güven ve düzen duygusu oluşturur.') WHERE id = '3fbc8bef-6814-4548-b448-0883b201e56d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık nesneleri yalnızca toplamakla kalmaz, aynı zamanda renklerine göre gruplandırmaya da çalışır. Ona iki farklı renkte kap verin ve aynı renkteki oyuncakları uygun kaplara koymasını gösterin. Bu oyun, görsel algısını ve mantıksal düşünme becerisini hızla geliştirir. Her doğru seçiminde onu teşvik edin.') WHERE id = 'be0ade15-5544-47ec-9b0f-c9482045c9e8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Geri adım". Çocuğunuz artık geri geri yürümeyi keşfetti. Bu, karmaşık bir denge egzersizidir ve beden koordinasyonunun ne kadar geliştiğini gösterir. Bu yeni becerisini engelsiz ve yumuşak bir alanda denemesine olanak tanıyın. Bedenini kontrol etme becerisi arttıkça kendine güveni de güçlenir.') WHERE id = '4090fd14-b660-4e63-9f79-fd22a575576f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Soru ve Merak". Çocuk artık "Bu nedir?" (veya kendi dilinde benzer bir ses) diyerek nesneleri gösterir. Siz de sabırla her şeyin adını söyleyin: "Bu kırmızı bir araba", "Bu büyük bir ağaç". Merakını yanıtsız bırakmamak, hem pasif hem de aktif kelime dağarcığının zenginleşmesine yardımcı olur.') WHERE id = '4d85c160-6a89-4bf6-8f45-da46fe9e61c0';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Şakalar". Çocuk oyuncağı bilerek size verip hemen geri çekiyor ve buna gülüyor mu? Bu, mizah duygusunun ve sosyal etkileşim becerisinin gelişmeye başladığını gösterir. Siz de onun bu "oyununa" coşkuyla katılın. Birlikte gülmek, aranızdaki duygusal bağı güçlendirir ve olumlu bir öz güven geliştirmesine yardımcı olur.') WHERE id = '843dc844-89cf-4311-8b84-968a8aaa47d1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Piramit ve Halkalar". Çocuk artık halkaları büyükten küçüğe (veya tam tersi) sıralamakta daha beceriklidir. Bu hareket hem boyut kavramını (büyük-küçük) hem de el-göz koordinasyonunu geliştirir. Halkaları dizerken renklerini de söyleyin.') WHERE id = 'da06e49e-5a35-41bf-9d03-b1f30db1e3f3';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Kendim içiyorum". Çocuk artık açık bardaktan suyu neredeyse hiç dökmeden içmeye çok yakındır. Ona çocuk boyutunda, kolayca devrilmeyen (ağır tabanlı) plastik bardaklar verin. Suyu kendi başına içmesi, dudak ve dil kaslarını konuşmaya hazırlar ve bağımsızlık duygusunu destekler.') WHERE id = '7672591f-bef4-411a-94a3-365d4ae118a3';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Hayal gücünün gelişimi: "Yemek yapma" oyunu. Çocuk, oyuncak kaplarıyla bir şeyler "pişiriyormuş" gibi yapabilir. Siz de bu oyunlara katılın: "Bana da biraz yemek verir misin?". Bu, günlük yaşam rutinlerini ne kadar dikkatle gözlemlediğini ve hayal gücünün nasıl geliştiğini gösterir.') WHERE id = '54cd9ab8-e1d5-4a0e-ab3a-58d28bf66df0';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel cesaret: Çocuk artık alçak basamaklara veya kanepenin kenarına tek başına tırmanmaya çalışır. Yükseklik algısı gelişse de henüz riskleri tam olarak anlayamaz. Her zaman yakınında durarak güvenliğini sağlayın ve ona güvenli iniş yollarını (örneğin, geriye doğru inmeyi) gösterin.') WHERE id = 'b93116ed-f9b5-4701-8c1f-2fc127b8352c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Hayvanları ve seslerini ayırt etme". Çocuk artık resimde gördüğü inekle kediyi birbirinden ayırt edebilir ve sorulmadan seslerini çıkarabilir. Kitap okurken "Buradaki kedi nerede?" diye sorduğunuzda parmağıyla göstermesi, görsel hafızasının güçlendiğini gösterir.') WHERE id = 'dcd3b6fa-3aa2-4a2f-98c6-4125a36e33d1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal sınırlar ve "Hayır". Çocuk her şeyi kendi başına yapmak istediğinde ve başaramadığında aniden öfkelenebilir. Böyle anlarda ona sarılabilir ve sakince "Ayakkabını giyemediğin için öfkelendin, seni anlıyorum" diyerek duygusunu adlandırabilirsiniz. Sizin bu sakinliğiniz, ona duygularını yönetmeyi öğreten en iyi örnektir.') WHERE id = '352efc53-2735-4313-8ef5-1cd93238bca8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Hayvanları ve seslerini ayırt etme". Çocuğunuz artık resimde gördüğü inek ile kediyi birbirinden tamamen ayırabiliyor ve sorulmadan seslerini taklit edebiliyor. Kitap okurken "Buradaki kedi nerede?" diye sorduğunuzda parmağıyla göstermesi, görsel hafızasının ve dikkatinin ne kadar güçlendiğini gösterir.') WHERE id = 'c66b2427-57b0-459e-a0a3-0cf6bedf7007';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal sınırlar ve "Hayır". Çocuğunuz her şeyi kendi başına yapmak istediğinde ve başaramadığında birden öfkelenebilir. Böyle anlarda ona sarılın ve sakince "Küpler devrildiği için öfkelendin, seni anlıyorum" diyerek duygusunu adlandırın. Bu anlayışınız, ona duygularını yönetmeyi ve zorluklar karşısında yılmamayı öğretir.') WHERE id = 'a52afb36-cf2f-4e94-8f57-7e002290fbaf';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık nesneleri renklerine göre gruplandırmaya çalışıyor. Ona iki farklı renkte kap verin ve aynı renkteki oyuncakları uygun kaplara nasıl koyacağını gösterin. Bu oyun, görsel algısını ve mantıksal düşünme becerisini hızla geliştirir. Öğrenmeye olan ilgisinin artması için her doğru seçiminde onu teşvik edin.') WHERE id = '59526637-405e-4f57-afc2-14b281d0bec6';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Geri adım". Çocuğunuz artık geriye doğru yürümeyi keşfetti. Bu, karmaşık bir denge egzersizidir ve vücut koordinasyonunun ne kadar geliştiğini gösterir. Bu yeni becerisini engelsiz ve yumuşak bir alanda denemesine olanak tanıyın. Vücudunu kontrol etme becerisi arttıkça öz güveni de güçlenir.') WHERE id = '75475781-7679-4745-947b-4230a1dabd3f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Soru ve Merak". Çocuğunuz artık "Bu nedir?" (veya kendi dilinde buna benzer bir ses) diyerek nesneleri gösteriyor. Siz de sabırla her şeyin adını söyleyin: "Bu kırmızı bir araba", "Bu büyük bir ağaç". Merakını yanıtsız bırakmamak, hem pasif hem de aktif kelime dağarcığının zenginleşmesine yardımcı olur.') WHERE id = '428ddabc-76ae-4dd9-8955-566bc3b0021c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Şakalar". Çocuğunuz oyuncağı bilerek size uzatıp hemen geri çekiyor ve buna gülüyor mu? Bu, mizah anlayışının ve sosyal etkileşim becerisinin gelişmeye başladığını gösterir. Onun bu "oyununa" coşkuyla katılın. Birlikte gülmek, aranızdaki duygusal bağı güçlendirir ve çocuğunuzun olumlu bir öz güven geliştirmesine yardımcı olur.') WHERE id = '6f7f5c96-a971-4edb-9629-1420d3e51d5d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Piramit ve Halkalar". Çocuğunuz artık halkaları büyükten küçüğe (veya tam tersine) dizme konusunda daha becerikli. Bu hareket hem boyut kavramını (büyük-küçük) anlamasını hem de el-göz koordinasyonunu geliştirir. Halkaları dizerken renklerin adlarını da söyleyin.') WHERE id = '90eaad7f-688e-4fd5-ac4b-58ae26fd12fd';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Kendim içiyorum". Çocuğunuz artık açık bir bardaktan suyu neredeyse hiç dökmeden içebilecek düzeye çok yaklaştı. Ona çocuklara uygun boyutta, kolayca devrilmeyen (ağır tabanlı) plastik bardaklar verin. Suyu kendi başına içmesi, dudak ve dil kaslarını konuşmaya hazırlar ve bağımsızlık duygusunu destekler.') WHERE id = 'ee6a42af-cce1-4d37-af51-df5adf60a403';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '18. aya, yani bir buçuk yaşa doğru ilk adımı atıyoruz! Çocuğunuz artık koşarken dengesini daha iyi koruyor ve istediği anda durabiliyor. Bu, hem fiziksel gücünün hem de beyin-kas koordinasyonunun büyük ölçüde geliştiğini gösterir. Parkta veya bahçede engelsiz koşabileceği alanlar bularak enerjisini sağlıklı bir şekilde atmasına fırsat verin.') WHERE id = '20741f1b-1447-4efb-94f4-6f3a4844a16e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Sözcük grupları" hız kazanıyor. Çocuğunuz artık iki sözcüğü yan yana getirerek daha karmaşık isteklerini ifade ediyor: "Baba, gel", "Ver, elma", "Top, nerede?". Henüz sözcükleri birleştirmiyorsa endişelenmeyin; söylediği tek sözcükleri cümleye dönüştürerek ona yanıt verin: "Evet, topu mu istiyorsun? Al, bu senin kırmızı topun".') WHERE id = '81c4a684-a911-49c4-a9d7-1699f6fa7902';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Puzzle" (yapboz) dönemi. Çocuğunuz artık 2-3 parçalı basit puzzle''ları tamamlamayı veya geometrik şekilleri uygun boşluklara yerleştirmeyi öğreniyor. Bu oyun hem görsel algısını hem de problem çözme becerisini ileri düzeyde geliştirir. Yapamadığında sakince ipucu verin ve onu cesaretlendirin.') WHERE id = 'f29daf62-95a9-439b-9639-5474aad5c6b0';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışlarda "Paralel oyun" hâlâ baskındır. Çocuğunuz başka çocuklarla aynı ortamdayken onlarla birlikte değil, onların yanında kendi başına oynar. Bu, 18 aya kadar olan çocuklar için tamamen normaldir. Diğer çocukları gözlemleyerek pek çok şey öğrenir. Sosyal ortama uyum sağlaması için onu akranlarıyla bir araya getirmeye devam edin.') WHERE id = 'b30c9be9-ec87-4316-9f1a-0e4dee84bd75';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Kendi kendime yıkanıyorum". Çocuğunuz banyo yaparken veya ellerini yıkarken sabunu ya da süngeri alıp kendini temizlemeye ve sizi taklit etmeye çalışır. Hijyen alışkanlıklarına duyduğu bu ilgiyi destekleyin. Kendisini "temizlemesi", hem vücut bölümlerini daha iyi tanımasına hem de bağımsızlık duygusunun gelişmesine büyük katkı sağlar.') WHERE id = '4e8730af-51d2-460d-ac2a-1e5c1f18dbf2';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Hafızanın güçlenmesi: "Mekânsal hafıza". Çocuğunuz sakladığınız oyuncağı bulmak için farklı yollar dener; örtüyü kaldırır, kutunun içine bakar, hatta yastığın altına elini uzatır. Bu, "nesne sürekliliği" kavramının tam olarak yerleştiğini gösterir. Evde onunla küçük "hazine avı" oyunları oynayarak dikkatini geliştirin.') WHERE id = '88dfd514-9103-49dd-80b3-7233dd30fb8c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Hayal gücü ve "Ev işleri". Çocuğunuz oyuncak telefonuyla "konuşur" veya oyuncak süpürgesiyle yerleri süpürür. Günlük hayatta yaptığınız her hareketi kopyalar. Bu taklit, onun dünyayı öğrenme yöntemidir. Kendisine ait küçük "iş araçları" vererek kendini önemli hissetmesine fırsat tanıyın.') WHERE id = '86806a6e-92ce-48bc-8348-5f82c21f79d1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel cesaret: "Tırmanma becerisi". Çocuğunuz artık merdivenleri kendi başına tırmanmaya (şimdilik elinden tutarak veya emekleyerek) oldukça isteklidir. Yükseklik algısı geliştikçe ona merdivenlerden inmeyi de öğretmek gerekir. Geri geri inmenin daha güvenli olduğunu her zaman gösterin ve güvenliğini sağlamak için daima yakınında durun.') WHERE id = 'bdb8a9e0-fbd7-4c99-b8e8-bdcb234283e8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Hayal gücünün gelişimi: "Yemek yapma" oyunu. Çocuk, oyuncak kaplarıyla bir şeyler "pişiriyormuş" gibi yapabilir. Siz de bu oyunlara katılın: "Bana da biraz yemek verir misin?". Bu, onun günlük yaşam rutinlerini ne kadar dikkatle gözlemlediğini ve hayal gücünün nasıl geliştiğini gösterir.') WHERE id = 'f1803978-8c6d-4ba6-919b-9d07f71e4f23';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel cesaret: Çocuk artık alçak basamaklara veya koltuğun kenarına tek başına tırmanmaya çalışır. Yükseklik algısı gelişse de riskleri henüz tam olarak kavrayamaz. Her zaman yakınında durarak güvenliğini sağlayın ve ona güvenli inme yöntemlerini (örneğin, geri geri inmeyi) gösterin.') WHERE id = '992522f4-e329-4100-a785-ed11e118cc9d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Hayvanları ve seslerini ayırt etme". Çocuk artık resimde gördüğü inek ile kediyi birbirinden ayırabilir ve sorulmadan seslerini taklit edebilir. Kitap okurken "Buradaki kedi nerede?" diye sorduğunuzda parmağıyla göstermesi, görsel hafızasının güçlendiğini gösterir.') WHERE id = 'a6dfa03f-81ed-42c6-9520-9c6097e0b191';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal sınırlar ve "Hayır". Çocuk her şeyi kendi yapmak istediğinde ve başaramadığında birden öfkelenebilir. Böyle anlarda ona sarılın ve sakince "Ayakkabını giyemediğin için öfkelendin, seni anlıyorum" diyerek duygusunu adlandırın. Sizin bu sakinliğiniz, ona duygularını yönetmeyi öğreten en iyi örnektir.') WHERE id = 'fe5d769a-36f6-497a-abae-90604ca433b9';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuk artık olduğu yerde zıplamayı deniyor. Henüz iki ayağı aynı anda yerden kesilmeyebilir ancak dizlerini büküp yaylanması, kaba motor becerilerinin geliştiğini gösterir. Onunla birlikte ritmik müzik eşliğinde dans edin. Bu, hem eğlenceli hem de bacak kaslarını fiziksel olarak güçlendiren çok faydalı bir egzersizdir.') WHERE id = '11679c4b-f0ae-4e4b-8e36-e62ed51385bb';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Benim" sözcüğünün keşfi. Çocuk artık kendi eşyalarını tanır ve "benim" diyerek (veya kendi dilinde bir işaretle) onları korumaya çalışır. Bu, bencillik değil, bireysel sınırlarını kavramaya başlamasıdır. Kendi eşyalarını sahiplenmesine izin verin; bu, özgüveninin ve mülkiyet kavramının gelişmesine yardımcı olur.') WHERE id = '76f2d8e6-3dab-4534-8a50-e8454558158c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Sıralama ve Mantık". Çocuk artık nesneleri yalnızca renklerine göre değil, boyutlarına göre de (büyük-küçük) ayırt etmeye başlar. Ona farklı boyutlarda kaplar verin ve bunları iç içe yerleştirmesini isteyin. Bu, gelecekteki matematiksel düşünme becerisinin en erken temelidir.') WHERE id = 'c34d1f9d-7805-4ebe-a5ef-2eba5d6e613a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bağımsızlık: "Kendim giyiniyorum". Çocuk artık pantolonunu yukarı çekmeye, çorabını çıkarmaya veya kolay giyilen ayakkabılarını ayağına geçirmeye çalışır. Bu süreçte ona engel olmayın ve acele ettirmeyin. Bir şeyi kendi başına başarabildiğini görmek, onun için en büyük ödüldür. Küçük başarılarında onu her zaman övün.') WHERE id = 'e8325a98-332b-4719-b50a-32bc427f8a46';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Sırasını beklemek". Çocuğunuz artık oyuncakla oynamak için biraz beklemesi gerektiğini anlıyor. "Şimdi sıra bende, sonra sende" oyunlarıyla ona sabretmeyi öğretin. Bu, kreşe veya diğer sosyal ortamlara uyum sağlaması için en önemli becerilerden biridir.') WHERE id = 'fb3f5f38-3ad4-4db7-9933-796ef621c2db';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Beslenmede "Bağımsız kaşık kullanma becerisi". Çocuğunuz artık kaşığı yemekle doldurup neredeyse hiç dökmeden ağzına götürmeyi öğreniyor. Yoğurt veya püre gibi kıvamlı yiyeceklerle pratik yapması daha kolaydır. Masanın kirlenmesinden korkmayın; kendi başına yemek yemesi hem el-göz koordinasyonunu hem de tokluk hissini geliştirir.') WHERE id = 'eb358b29-c8ba-43ce-9ec4-901370abee63';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Hayal gücünün gelişimi: "Oyuncaklarla Diyalog". Çocuğunuz artık bebeği veya oyuncak ayısıyla "konuşuyor", onları "uyutuyor" ya da "muayene ediyor". Bu, duygusal zekâsının geliştiğini ve günlük rutinleri ne kadar derinden benimsediğini gösterir. Siz de bu rol yapma oyunlarına katılın.') WHERE id = '966e6ab8-7afb-4514-ac61-ac17ed1b3363';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel gelişim: "Topa vurmak". Çocuğunuz artık ayakta durup dengesini kaybetmeden topa ayağıyla vurmaya çalışıyor. Bu, karmaşık koordinasyon gerektiren bir harekettir. Onunla evde veya bahçede hafif bir topla oynayın. Topu size atmasını isteyerek karşılıklı oyun becerisini de geliştirin.') WHERE id = '074c6e28-5574-4dba-9c17-b0a8532eb39d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Neden?" döneminin ilk işaretleri. Çocuğunuz artık her şeyi parmağıyla gösterip "Bu?" diyerek açıklamanızı bekliyor. Her nesnenin adını ve ne işe yaradığını basit cümlelerle açıklayın. Açıklamalarınız onun zihninde dünyanın haritasını oluşturur. Merakını her zaman canlı tutun.') WHERE id = '8bf76af3-3dd5-49ef-bbdd-da6f06260256';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Tebrikler, 550 günü tamamladık! Çocuğunuz artık resmen 1.5 yaşında. Bu dönem, çocuğun gelişimindeki en kritik ve ilgi çekici dönemlerden biridir. Artık basit komutları tamamen anlıyor, duygularını açıkça gösteriyor ve dünyayı keşfetmeye hazır küçük bir "araştırmacı". Bu günü, onunla birlikte en sevdiği oyunu oynayarak kutlayın!') WHERE id = 'f706bcc8-1266-48d0-82ad-7920a5e14e37';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '19. aya hoş geldiniz! Çocuğunuz artık aynada kendisini tamamen tanıyor ve yansımasını "başka bir çocuk" olarak değil, doğrudan kendisi olarak algılıyor. Bu, benlik farkındalığının (self-awareness) gelişiminde büyük bir adımdır. Onunla aynanın karşısında durup "Bak, bunlar senin gözlerin, bunlar da annenin gözleri" diyerek vücut bölümlerini daha ayrıntılı öğretmeye devam edin.') WHERE id = '696f3d72-602f-4dc5-8009-bf57000cd9a2';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Yana adım". Çocuğunuz artık yalnızca ileri ve geri değil, yana doğru da (crab walk) yürüyebiliyor. Bu, karmaşık bir denge ve koordinasyon egzersizidir. Ona müzik eşliğinde farklı yönlere hareket etmeyi gösterin. Bu hem eğlenceli bir danstır hem de bacak kaslarının farklı gruplarını güçlendirir.') WHERE id = '29558e25-5ccf-4193-9fb7-c0eb732293d0';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Komutları yerine getirme": Çocuk artık art arda iki adımdan oluşan yönergeleri anlayabilir. Örneğin: "Topu al ve kutuya koy". Bu, hem dili anlama becerisini hem de çalışma belleğini geliştirir. Ona bu tür basit, iki aşamalı "görevler" vererek dikkatini geliştirin.') WHERE id = 'b9afb514-aca9-4563-b096-907e76f4594a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Kitap sevgisi". Çocuk artık ince kâğıt sayfaları gözetiminiz altında yırtmadan çevirmeye çalışır. Sevdiği masalları defalarca dinlemek isteyebilir. Her okuyuşunuzda resimdeki farklı ayrıntıları gösterin: "Bak, burada küçük bir kelebek de var". Bu, hem görsel dikkatini hem de sabrını artırır.') WHERE id = 'dd8c337a-acae-4f9f-a64d-1a2e2dbf15fb';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız hijyen". Çocuk artık ellerini kurulamaya, yüzünü silmeye veya süngerle kendi kendini "yıkamaya" çalışır. Hijyen alışkanlıklarına olan ilgisini destekleyin. Ona kendine ait küçük bir havlu verin. Kendi bakımını yapabilme hissi, özgüvenini ve bedenine duyduğu saygıyı geliştirir.') WHERE id = '31f5c493-87d9-45d8-950b-ce108414919b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Sembolik paylaşım". Çocuk artık size oyuncağının bir parçasını veya yemeğinden bir lokmayı "ikram" edebilir. Gerçekten vermese bile bu jest, paylaşma anlayışının temelini oluşturur. Bu davranışını mutlaka "Teşekkür ederim, çok naziksin" diyerek takdir edin.') WHERE id = '10acade6-6a92-4cf8-b728-f33648cdd314';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Geometrik şekiller". Çocuk artık daire, kare ve üçgeni yapbozlarda veya şekil yerleştirme oyuncaklarında birbirinden ayırt etmeye başlar. Ona bu şekillerin adlarını söyleyin. Henüz adlarını söyleyemese de görsel olarak birbirinden ayırabilmesi, geometrik düşünme becerisinin temelidir.') WHERE id = '36dfa91f-6b4c-45f4-8057-bfc8dec4de87';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel cesaret: "Aşağı atlama". Çocuk artık alçak bir basamaktan, yalnızca birkaç santimetre yükseklikten yere atlamayı deneyebilir. Elinden tutarak ona destek olun. Bu hareket hem ayak bileklerini güçlendirir hem de yükseklik ve mesafe algısını uygulamalı olarak öğrenmesini sağlar.') WHERE id = '20c66b93-4f9a-4106-b0f1-86263f239cfe';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Duyguları ifade etme". Çocuk artık acıktığını, yorulduğunu veya bir şeyden korktuğunu özel seslerle ya da basit sözcüklerle ifade eder. Siz de onun bu sinyallerini sözcüklerle doğrulayın: "Evet, yorulmuşsun; gel biraz dinlenelim". Bu, ileride duygularını sözcüklerle ifade edip yönetebilmesi için sağlayabileceğiniz en büyük destektir.') WHERE id = '402a1eb2-6224-49f3-92d8-6ebdc1c68d75';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Hayal gücünün gelişmesi: "Oyuncaklar canlanıyor". Çocuk artık oyuncak arabalarıyla yarış yapar veya bebeklerini birbirleriyle "konuşturur". Bu, hem yaratıcılığını hem de karmaşık düşünme becerisini gösterir. Bu rol yapma oyunlarına siz de katılın ve senaryoyu biraz daha genişletin: "Araba yakıt almaya mı gidiyor?".') WHERE id = '50b52b0c-f730-4500-a2ea-7d50f4678b25';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık "Kendim yapacağım!" döneminin zirvesinde. Kapıyı kendi açmak, düğmeye kendi basmak veya merdivenleri tek başına çıkmak istiyor. Bu inatçılık değil; kendi becerilerini sınama çabasıdır. Güvenli olan her durumda denemesi için ona birkaç saniye daha tanıyın. Bir şeyi kendi başına başarabildiğini görmek, özgüvenini geliştiren en önemli etkendir.') WHERE id = '0424ded1-f254-419a-bacc-912b20a6465b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel gelişimde "Topu hedefe atma". Çocuğunuz artık topu yalnızca yere atmıyor, belirli bir yöne veya size doğru atmaya çalışıyor. Bu, omuz kaslarının ve el-göz koordinasyonunun önemli ölçüde geliştiğini gösterir. Onunla "topu sepete at" oyunu oynayarak isabet becerisini geliştirin.') WHERE id = 'd62bdbf3-d7fd-43c8-9cef-8ef0c95e0352';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Dil gelişiminde "Sıfatları keşfetme". Çocuğunuz artık yalnızca nesnelerin adını söylemekle kalmıyor, onların özelliklerini de anlıyor: "sıcak", "soğuk", "büyük", "küçük". Yemek yerken veya banyo yaparken bu sözcükleri sık sık kullanın: "Bak, bu su ılık". Bu, dünyayı daha ayrıntılı şekilde ifade etmesine ve soyut düşünme becerisinin gelişmesine yardımcı olur.') WHERE id = 'f549d4ea-b5e9-4a79-81eb-61a06771145c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Sıralama ve Geçirme". Çocuğunuz artık boncukları ipe dizmeyi (büyük boncuklarla ve gözetim altında) veya anahtarı kilide sokmayı deneyebilir. Bu hareketler, parmak kaslarının çok hassas bir şekilde koordine edilmesini gerektirir. Bu tür alıştırmalar, gelecekte kalem tutma ve yazma becerileri için önemli bir temel oluşturur.') WHERE id = '499eb64f-17b7-4928-a28f-32d77bae69bd';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Beslenmede "Seçicilik" ve "Kontrol". Çocuğunuz bazen yalnızca "kontrol kendisinde olsun" diye yemek yemeyi reddedebilir. Onu zorlamayın. Bunun yerine sofraya iki sağlıklı seçenek koyun: "Brokoli mi istersin, yoksa havuç mu?". Seçim yapabilmek, itirazını azaltır ve kendi kararlarına saygı duyulduğunu hissetmesini sağlar.') WHERE id = '597fce8a-7564-428a-aa97-6b8b166f2f7c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Mekânsal algı" ve "Yükseklik". Çocuğunuz artık yüksekliğin riskli olduğunu daha iyi anlıyor ve alçak yerlerden inerken dikkatli davranıyor. Ona koltuktan veya basamaktan geri geri inmeyi hatırlatın. Bu, bedensel güvenlik kurallarını öğrenmesi açısından önemlidir.') WHERE id = '42d59296-b192-45dd-b455-11502c8aeaec';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Taklit" artık duyguları da kapsıyor. Siz güldüğünüzde o da gülüyor, siz ciddi olduğunuzda o da susuyor. Siz çocuğunuzun duygusal aynasısınız. Onunla oyun oynarken farklı yüz ifadeleri yapın ve bunları tekrar etmesini isteyin. Bu, duygusal zekâsının ve başkalarını anlama becerisinin gelişmesine yardımcı olur.') WHERE id = 'c03e79b5-c416-4e9a-8cda-23ab824d2ea7';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Kendi kendine toplama" alışkanlığı: Çocuğunuz artık oyuncaklarını kutuya koymayı bir "görev" olarak kabul edebilir. Oyun bittikten sonra "Haydi, arabaları evlerine koyalım" diyerek onu teşvik edin. Bu, hem düzen alışkanlığı kazanmasına hem de başladığı işi bitirme sorumluluğunun gelişmesine yardımcı olur. Ona her zaman yardım edin ve onu övün.') WHERE id = '4be37208-93a9-4898-b72a-811ae2d7a051';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Soru-Cevap" diyaloğu giderek karmaşıklaşır. Çocuğunuz artık "Bu nedir?" sorusunu yalnızca cevabını bilmediği için değil, sizinle iletişimde kalmak için de sorar. Cevap verirken cümleyi biraz uzatın: "Bu kırmızı bir elma, sen onu seviyorsun". Bu, çocuğun kelime dağarcığını hızla zenginleştirir.') WHERE id = '59968193-d8d9-46a6-bcc6-77f1e1c44a81';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topa vurma ustalığı". Çocuğunuz artık koşarken önündeki topa vurabilir. Bu, hareketin ve dengenin aynı anda kontrol edilmesini gerektirir. Onunla evde veya bahçede "futbol" oynayarak bu dinamik denge becerisini güçlendirin. Sizinle birlikte hareket etmek, onun için en büyük eğlencedir.') WHERE id = '591884a7-b1fd-4edf-bb0d-3dca04af2ea4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık renkleri yalnızca ayırt etmekle kalmaz, adlarını söylemeye de çalışır. Ona "Mavi arabayı bana ver" dediğinizde doğru rengi seçiyorsa bu, görsel hafızası ve söylenenleri anlama becerisi açısından büyük bir başarıdır. Bu bilginin pekişmesi için günlük kıyafetlerinde ve oyuncaklarında renkleri sık sık vurgulayın.') WHERE id = '1ab53f62-49d6-486d-9a52-ff092cc01b9c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel cesaret: Çocuğunuz artık olduğu yerde zıplamaya (iki ayağını aynı anda yerden kesmeye) daha çok heves eder. Bu, bacak kasları ile denge duyusunun güçlü bir koordinasyonunu gerektirir. Yumuşak bir halının üzerinde onunla "kim daha çok zıplar" oyunu oynayarak enerjisini atmasına fırsat tanıyın.') WHERE id = 'fac02d76-edc4-45d2-ac23-faa60bad4132';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Konum bildiren sözcükler". Çocuğunuz artık "üstünde", "altında" ve "içinde" gibi sözcüklerin anlamını uygulamalı olarak kavrar. Ona "Topu sandalyenin altına koy" diyerek bunu deneyebilirsiniz. Bu tür yönergeler hem dil hem de mekânsal yönelim becerisini geliştirir. Bu kavramları oyunlara dahil ederek mantık yürütme becerisini güçlendirin.') WHERE id = '30c8f80f-c5ad-42c7-a784-1930afcd9e96';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız seçim" ve irade. Çocuğunuz artık ne giyeceği veya hangi tabaktan yemek yiyeceği konusunda net bir fikre sahiptir. Ona "Bugün mavi tabaktan mı, yoksa yeşil tabaktan mı yemek istersin?" gibi seçenekler sunmanız, kendisini bağımsız bir birey olarak hissetmesine yardımcı olur ve gereksiz inatlaşmaları önler.') WHERE id = '6f9d4056-a417-4319-83b2-043809df814a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Tasarım ve İnşa". Çocuğunuz artık 6-8 küpü (bloğu) üst üste dizerek yüksek bir kule yapabilir. Bu, hem dikkatini toplamayı hem de el hareketlerinde hassasiyeti gerektirir. Kule yıkıldığında bunu neşeyle karşılayın ki çocuğunuz başarısızlıktan korkmasın ve yeniden denemeye istekli olsun.') WHERE id = '17f5c5df-ea05-4d59-8a28-32ffc0cbb3e8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Şefkat". Çocuğunuz artık oyuncak ayısını "besleyebilir", "yatağına yatırabilir" veya ağladığında onu "teselli edebilir". Bu, sembolik oyun becerisinin geliştiğini gösterir. Çocuğunuza gösterdiğiniz şefkat artık onun oyunlarına yansır.') WHERE id = 'bc61e4f6-e294-4033-b040-474d57e5f13b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Beslenmede "Bağımsız su içme". Çocuğunuz artık açık bardaktan suyu neredeyse hiç dökmeden, güvenle içebiliyor. Bu, dudak ve çene kaslarının konuşmaya ne kadar hazır olduğunun bir göstergesidir. Bu beceride tamamen ustalaşabilmesi için ona çocuk boyutunda, rahatça tutabileceği bardaklar vermeye devam edin.') WHERE id = 'f0007c08-4f82-470d-976e-b690d945c125';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Yeni korkular: Çocuğunuz aniden karanlıktan, yüksek seslerden veya maskeli karakterlerden korkmaya başlayabilir. Bu, hayal gücünün ve çevresini algılama becerisinin gelişmesiyle ilgilidir. Korkusuyla alay etmeyin; yalnızca yanında olun, ona sarılın ve güvende olduğunu hissettirin. Zamanla bu korkular yerini meraka bırakacaktır.') WHERE id = 'c56b4f54-c6b4-4285-a227-6cdf7c49e75e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "İlk karmaşık cümleler". Çocuğunuz artık "Baba geldi", "Ben su içtim" gibi geçmiş zaman içeren basit cümleler kurabilir. Bu çabalarını doğru dil bilgisiyle tekrarlayarak destekleyin. Sizin konuşma biçiminiz onun için en temel modeldir. Onunla her zaman açık ve içten bir dille iletişim kurun.') WHERE id = 'ec0cb279-7627-42fd-8c4b-82e97e640420';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Geri geri yürüme becerisi". Çocuğunuz artık arkasına bakmadan geriye doğru birkaç adım atabiliyor. Bu, vücudunun uzaydaki konumunu algılaması (propriyoseptif duyu) açısından önemlidir. Ona "Yengeç gibi yürüyelim" diyerek bu hareketi bir oyuna dönüştürün. Sizinle birlikte hareket etmek onun için dünyanın en büyük eğlencesidir.') WHERE id = '891890ba-7797-463a-90b9-18dda87b2142';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '20. aya adım atıyoruz! Çocuğunuzun artık kendine özgü bir "zevki" oluşuyor. Giymek istediği ayakkabıyı veya yemek istediği yiyeceği ısrarla seçebilir. Bu, iradesinin güçlendiğini gösterir. Ona iki güvenli seçenek arasında karar verme fırsatı sunun: "Bugün elma mı yemek istersin, armut mu?". Bu, hem öz güvenini artırır hem de inatlaşma krizlerini azaltır.') WHERE id = '9857fafb-dba1-41f5-bd34-455d5b939f6f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyonda "Dinamik denge". Çocuğunuz artık eğilip yerden bir şey alırken düşmeden yeniden ayağa kalkabiliyor. Bu, hem bel hem de bacak kaslarının belirgin şekilde güçlendiğini gösterir. Onun için yere farklı yüksekliklerde oyuncaklar yerleştirin ve bunları bir kutuya toplamasını isteyin. Bu hareket, beden kontrolünü geliştirir.') WHERE id = '21286f36-7532-41d3-a58d-4d4ecfb6df25';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Sözcük öbekleri" hızla gelişiyor. Çocuğunuz artık isteklerini iki-üç sözcükle ifade ediyor: "Baba, topu ver", "Anne, su iç". Konuşurken her sözcüğünü dikkatle dinleyin ve göz teması kurun. Sözcük dağarcığının daha da zenginleşmesi için cümlelerini biraz genişleterek yanıt verin.') WHERE id = '4a36674f-0b66-41a0-beba-daa82b8d9f0b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Yapbozlar ve Bulmacalar". Çocuğunuz artık 3-4 parçalı basit yapbozları tamamlamakta veya şekilleri uygun deliklere yerleştirmekte daha hızlıdır. Bu, hem mekânsal algısını hem de görsel analiz becerisini geliştirir. Görev zorlaştığında hevesini kaybetmemesi için ona küçük ipuçları verin.') WHERE id = 'cce26ca5-c2df-4a63-a452-8753ade9a3fe';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Sembolik paylaşım". Çocuğunuz artık oyuncağından bir parçayı size "ikram" edebilir (ya da hemen geri alabilir). Bu, paylaşma kavramının ilk belirtileridir. Bu davranışını mutlaka takdir edin: "Oyuncağını bana gösterdiğin için çok teşekkür ederim". Bu yaklaşım, olumlu sosyal alışkanlıkların temelini atar.') WHERE id = '35b68ddd-9074-4a9a-97b7-0fddbf831df1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Kendim temizliyorum". Çocuğunuz sizi taklit ederek ellerini kurulamaya, yüzünü silmeye veya oyuncak bir bezle masayı silmeye heveslenir. Bu bağımsızlık isteğini engellemeyin. Ona kendisine ait küçük bir havlu veya fırça vererek "ev işlerine" dahil edin. Bu, sorumluluk duygusunun gelişmesine yardımcı olur.') WHERE id = '37a69b03-aa17-4bad-982a-11091970591b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Hafıza ve "Mekânsal hafıza" zirvede. Çocuğunuz artık sakladığınız oyuncağın yerini birkaç saat sonra bile hatırlayabilir. Onunla evde "hazine avı" oynayın. Bir oyuncağı yastığın altına koyun ve onu bulmasını izleyin. Bu oyun hem dikkatini toplamasına hem de problem çözme becerisine olumlu katkı sağlar.') WHERE id = '105285fc-eb7a-4111-ad71-74ef8c1d89b9';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Hayal gücünün gelişimi: "Oyuncaklarla Diyalog". Çocuğunuz bebeği veya oyuncak ayısıyla "konuşur", onları besler ya da uyutur. Bu, duygusal zekânın geliştiğinin ve günlük rutinlerin benimsendiğinin bir göstergesidir. Bu rol oyunlarına siz de katılın: "Ayı şimdi nereye gidiyor?". Bu, yaratıcı düşünme becerisini hızla geliştirir.') WHERE id = '1d1a3072-a955-4f0c-b97e-45be9ab5c292';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel cesaret: "Tırmanma ve İnme". Çocuğunuz artık merdivenleri daha hızlı ve her basamağa bir adım atarak (elinden tuttuğunuzda) çıkabilir. Yükseklik algısı geliştikçe, güvenli inme yöntemlerini ona tekrar tekrar gösterin (geri geri inmek). Güvenlik kapılarının hâlâ yerinde ve kapalı olduğundan emin olun.') WHERE id = '3dfce46e-871b-4ff0-b52c-ef4021fb63e3';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal sınırlar: Çocuğunuz artık "Olmaz" sözüne tepki verir, ancak bazen tepkinizi ölçmek için kuralları çiğnemeye devam edebilir. Sakin ama kararlı kalmanız çok önemlidir. Bir şeye "hayır" dediyseniz, bunu her seferinde aynı şekilde tekrarlayın. Kuralların tutarlı olması, çocukta iç düzen ve güvenlik hissi oluşturur.') WHERE id = '3d5db953-53d5-41ac-96c7-0de1abf8d13a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık renkleri yalnızca ayırt etmekle kalmaz, aynı zamanda eşleştirebilir. Ona "Mavi topu mavi kutuya koy" dediğinizde bunu doğru yapıyorsa, bu görsel mantık becerisi açısından büyük bir başarıdır. Günlük yaşamda "kırmızı elma", "yeşil yaprak" gibi renkleri vurgulayan cümleler kurarak bu bilgileri pekiştirin.') WHERE id = '7bf7487b-3d3e-49a7-9bc5-a3a917c3fbbf';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Olduğu yerde zıplama". Çocuğunuz artık iki ayağını aynı anda yerden kaldırmaya (zıplamaya) çalışır. Bu hareket, bacak kaslarının güçlü olmasını ve denge için karmaşık bir koordinasyonu gerektirir. Onunla birlikte "Tavşan gibi zıplayalım" oyunu oynayın. Bu oyun hem eğlenceli hem de fiziksel gelişim için çok faydalıdır.') WHERE id = '37a6e358-9a9e-40cc-aab7-74b540fd0681';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '20. ayın son on günlük dönemine başlıyoruz. Çocuğunuz artık vücut bölümlerini yalnızca göstermekle kalmıyor, ne işe yaradıklarını da anlamaya başlıyor. "Ayaklarınla ne yaparsın?" diye sorduğunuzda koşmayı veya yere vurmayı gösterebilir. Onunla "Bu ne işe yarar?" oyununu oynayın. Bu oyun hem kelime dağarcığını hem de işlevsel düşünme becerisini geliştirir.') WHERE id = 'dee4db38-d5ad-4ab8-80a6-e91df1c6234f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Engellerin altından geçme". Çocuğunuz artık dik durmanın yanı sıra eğilip masa veya sandalyenin altından geçmeyi ve bulunduğu alanda kendi vücut ölçülerini değerlendirmeyi öğreniyor. Bu, beden farkındalığını (body awareness) artırır. Evde yastıklar ve sandalyelerle "tüneller" oluşturarak bu beceriyi geliştirmesine yardımcı olun.') WHERE id = '4db05b48-52f1-4673-a7b9-28436103d6d9';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Zamirlerin ilk işaretleri". Çocuğunuz artık kendisi için "Ben", sizin içinse "Sen" demeye veya bunları kendi dilinde farklı seslerle ifade etmeye çalışıyor. Bu, kendisini çevresindeki dünyadan ayrı bir birey olarak algılamaya başladığının göstergesidir. Kendi adını söylediğinde "Evet, sen (adını söyleyin) buradasın" diyerek benlik duygusunu güçlendirin.') WHERE id = '15ef8b0a-68af-41c5-881d-ef1aaddc31ca';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerde "Vidalı kapakları açma". Çocuğunuz artık şişe kapaklarını çevirerek açmaya veya kapatmaya çalışıyor. Bu hareket, el bileği kaslarının dönme hareketi için mükemmel bir egzersizdir. Ona farklı boyutlarda güvenli kaplar vererek bu yeni "becerisini" denemesine izin verin.') WHERE id = 'eca36160-9ece-4da0-80c8-687ec7c51745';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Yardım etme isteği". Çocuğunuz artık alışveriş poşetinden bir şey çıkarmak veya size bir şey getirmek için hevesleniyor. Ona "Lütfen bu bezi bana verir misin?" gibi küçük görevler verin. Görevi tamamladığında "Bana çok yardım ettin, çok teşekkür ederim" deyin. Bu, sosyal sorumluluk duygusunun gelişmesine ve kendisini faydalı hissetmesine yardımcı olur.') WHERE id = 'ee7370f4-6eb2-48da-aebb-00ccc3c2ad1b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Kendi kendine diş fırçalama". Çocuğunuz artık sizi taklit ederek diş fırçasını ağzına götürüyor ve hareket ettiriyor. Şimdilik bu yalnızca bir oyundur ve dişlerini sizin fırçalamanız gerekir; ancak bu alışkanlığa gösterdiği ilgiyi destekleyin. Kendine ait bir diş fırçasının olması ve fırçalamayı kendisinin denemesi, hijyen alışkanlıkları için olumlu bir temel oluşturur.') WHERE id = '183dc3b9-e225-46b4-b630-b164f5414528';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Eşleştirme" (Matching). Çocuğunuz artık aynı hayvanın veya nesnenin iki farklı resmini birbiriyle eşleştirebilir. Onunla basit kartlar kullanarak "Aynısını bul" oyununu oynayın. Bu oyun, görsel dikkatini ve hafızasını önemli ölçüde güçlendirir. Doğru eşleştirdiğinde sevincinizi gösterin ki hevesi kırılmasın.') WHERE id = '45e380ad-6559-467d-84f4-eced81427f7d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Merdivenleri tek tek adımlarla inme". Elinden tuttuğunuzda çocuğunuz artık merdivenleri daha güvenli bir şekilde, basamakları tek tek inmek için çabalıyor. İnmek, çıkmaktan daha zordur ve daha fazla denge gerektirir. Güvenliği için her zaman yanında olun ve merdiven korkuluklarından tutmasına izin verin.') WHERE id = '9b3b0e2c-c4cd-4d64-a63f-e74713052b56';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Sıfatların artması". Çocuğunuz artık nesnelerin yalnızca adlarını değil, özelliklerini de (sıcak, soğuk, büyük, küçük, yumuşak, sert) anlıyor. Yemek yerken "Bu püre sıcak" veya oyuncağına dokunurken "Bu ayı yumuşak" diyerek duyularla ilgili kelime dağarcığını zenginleştirin. Bu, dünyayı daha ayrıntılı şekilde tarif etmesine yardımcı olur.') WHERE id = 'e5f3d411-7714-4b52-b440-c00913f921c9';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Kalem tutuşu" gelişiyor. Çocuğunuz artık boya kalemini avucuyla değil, parmaklarına daha yakın bir şekilde tutmaya çalışıyor. Kâğıt üzerinde daha belirgin daireler veya gelişigüzel ama güçlü çizgiler çiziyor. Ona renkli boya kalemleri ve büyük kâğıtlar vererek "yaratıcılık" alanını genişletin.') WHERE id = '286d8a77-5c51-4a8f-96ae-733178c15fb0';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bağımsızlık: "Kendim giyiniyorum". Çocuğunuz artık çoraplarını çıkarma, şapkasını başına takma veya kolay giyilen ayakkabılarını ayağına geçirme konusunda daha ısrarcı. Bu süreç için ona birkaç dakika daha fazla zaman tanıyın. Acele ettirmeden kendi başına bir şeyler yapabilmesine fırsat vermek, özgüvenini ve kişisel bağımsızlık duygusunu geliştirir.') WHERE id = '947a00f0-f695-4c17-b833-1f7ad19529e3';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Sıra beklemek". Çocuğunuz artık parkta salıncağa binmek veya bir oyuncakla oynamak için biraz beklemesi gerektiğini anlıyor. "Şimdi sıra bende, sonra sende" oyunlarıyla ona sabretmeyi öğretin. Bu beceri, gelecekte kreş ve okul ortamına uyum sağlaması için en önemli sosyal temellerden biridir.') WHERE id = 'f555abb8-3ed3-4f14-968a-d2f98f543e71';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Beslenmede "Çatal ve kaşık ustalığı". Çocuğunuz artık kaşığını yemekle doldurup neredeyse hiç dökmeden ağzına götürmeyi öğreniyor. Ona çatalını batırabileceği (çatal kullanımına uygun) küçük sebze ve meyve parçaları sunun. Kendi kendine yemek yemesi, doyduğunu fark etmesine ve farklı dokulardaki yiyeceklere daha fazla ilgi duymasına yardımcı olur.') WHERE id = 'a925547f-11ed-45ce-9474-cab706a5ddda';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Hayal gücünün gelişimi: "Oyuncaklarla Diyalog". Çocuğunuz artık bebeği veya oyuncak ayısıyla "konuşuyor", onları "besliyor" ya da "uyutuyor". Bu, duygusal zekâsının ve günlük rutinleri ne kadar derinlemesine benimsediğinin bir göstergesidir. Bu rol yapma oyunlarına siz de katılın ve senaryoyu biraz daha genişletin.') WHERE id = 'a151a89a-61af-4831-b10f-8a215a565721';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel gelişim: "Topa tekme atmak". Çocuğunuz artık ayakta durup dengesini kaybetmeden önündeki topa tekme atmaya çalışıyor. Bu, karmaşık koordinasyon ve tek ayak üzerinde kısa süreli denge gerektiren bir harekettir. Evde veya bahçede hafif bir topla birlikte oynayarak hem hareket hızını hem de isabetini geliştirin.') WHERE id = 'deb4ac24-b3c7-4d6b-a7be-c36edea03c4e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Tebrikler, 600 günü tamamladınız! Çocuğunuz artık 20. ayının yarısına geldi. Basit yönergeleri tamamen anlıyor, duygularını açıkça gösteriyor ve dünyayı keşfetmeye hazır küçük bir "araştırmacı". Bu günü, onunla birlikte en sevdiği parkta veya oyun odasında vakit geçirerek kutlayın. Siz harika bir annesiniz!') WHERE id = '1f1a3784-4c01-4fba-825d-ca3fcac15f79';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Duyguların adlandırılması". Çocuğunuz öfkelendiğinde, sevindiğinde veya utandığında bu duyguları kelimelerle ifade edin: "Şu anda çok seviniyorsun!", "Oyuncağın düştüğü için biraz üzgün müsün?". Duyguların adlandırılması, çocuğunuzun gelecekte "tantrum" (öfke krizleri) sırasında kendini daha kolay kontrol etmesine yardımcı olur.') WHERE id = 'da0fa9b2-9fec-47fb-a56d-5e0c384540ea';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Hayal gücünün gelişmesi: "Kurmaca oyunlar". Çocuğunuz artık bir nesneyi başka bir nesnenin yerine kullanabilir. Örneğin bir küpü "telefon" gibi kulağına tutabilir. Bu, çocuğunuzun soyut düşünme becerisinin ve yaratıcılığının zirvesidir. Bu oyunlara siz de katılın ve hayal gücünü destekleyin.') WHERE id = 'f71a9e64-80ca-4672-869a-4b4e2012c4b5';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık "Ben" ve "Benim" ifadelerini daha sık kullanıyor. Bu, kişisel sınırlarının ve kimliğinin farkına vardığının bir işaretidir. Sevdiği oyuncağa "Benim!" diyerek sarılması normaldir. Ona kendi eşyalarını sahiplenme fırsatı verin; bu, gelecekte başkalarının sınırlarına da saygı göstermesi için önemli bir temel oluşturur.') WHERE id = 'b7d51937-c7a2-4d6d-b732-4b494fc952b3';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel gelişimde "Geri geri yürüme becerisi". Çocuğunuz artık arkasına bakmadan ve dengesini kaybetmeden birkaç adım geriye doğru yürüyebilir. Bu, vücudunun uzaydaki konumunu algılaması (propriyoseptif duyu) için harika bir egzersizdir. Onunla "Yengeç gibi yürüyelim" oyunu oynayın. Bu hem eğlenceli bir etkinliktir hem de bacak kaslarını farklı şekilde çalıştırır.') WHERE id = '513f1229-f55a-4c5d-a40b-fc0fd9f8ae37';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Sıfatların kullanılması". Çocuğunuz artık nesneleri yalnızca adlandırmakla kalmıyor, renk veya boyut da ekliyor: "Büyük top", "Kırmızı araba". Bu çabalarını teşvik edin ve cümlesini biraz daha genişletin: "Evet, bu senin büyük ve yumuşak topun".') WHERE id = 'b2c7d131-58dd-486b-9609-a0affe8ae4df';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor gelişiminde "Dikey ve yatay çizgiler". Çocuğunuz artık kalemi daha güvenli tutuyor ve kâğıt üzerinde bilinçli olarak düz çizgiler çizmeye çalışıyor. Ona kalın renkli kalemler ve büyük resim kâğıtları verin. Çizdiği her çizgi, el-göz koordinasyonunun ve gelecekteki yazma becerilerinin güçlenmesi anlamına gelir.') WHERE id = 'cc6fb892-8f1f-42d8-95a3-eba0a72b0349';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız seçim" ve giyinme. Çocuğunuz artık hangi çorabı veya şapkayı giymek istediği konusunda net bir fikre sahip. Ona iki güvenli seçenek sunun: "Bugün yeşil şapkanı mı, yoksa mavi şapkanı mı giyeceksin?". Bu tür küçük kararlar, çocuğunuzun kendini önemli hissetmesine yardımcı olur ve inatlaşma krizlerini en aza indirir.') WHERE id = '38af9059-ae27-4644-b4e5-977b53c68250';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "İş birliği": Çocuğunuz artık oyuncaklarını birlikte toplamaktan keyif alıyor. "Haydi, arabaları birlikte evlerine koyalım" dediğinizde size yardım edecektir. Bu hem düzen alışkanlığı kazandırır hem de birlikte hareket etmenin mutluluğunu yaşatır. Her yardımından sonra onu övmeyi unutmayın.') WHERE id = '49ba697d-2e60-439d-966b-ca621530805d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Parçaları birleştirme". Çocuğunuz artık iki veya üç parçalı basit yapbozları tek başına tamamlayabilir. Parçaları birleştirip bütünü görmek, görsel-uzamsal düşünme becerisini geliştirir. Yapamadığında ona sakince ipucu verin: "Bak, köpeğin kuyruğu burada". Bu, problem çözme konusundaki azmini artırır.') WHERE id = '1bcc9149-af08-4bbd-bac4-e8848b1380ea';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topa vurma ve koşma". Çocuğunuz artık koşarken önündeki topa vurabilir. Bu, hem hareket hızının hem de dinamik dengenin aynı anda kontrol edilmesini gerektirir. Onunla evde veya parkta "futbol" oynayarak hareketlerindeki isabeti geliştirin.') WHERE id = '56be9450-be4f-4da2-bbc6-79d6b2c42f94';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Neden?" sorusunun öncüleri. Çocuğunuz her şeyi gösterip "Bu?" diyerek açıklamanızı bekler. Her nesnenin adını ve ne işe yaradığını basit cümlelerle açıklayın. Örneğin: "Bu bir fırça, dişlerimizi temizlemek için kullanılır". Verdiğiniz yanıtlar, dünyayı zihninde daha sistemli bir şekilde sınıflandırmasına yardımcı olur.') WHERE id = 'cd8ca16e-d97a-4620-91cf-5f294687b3b5';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal gelişimde "Kendini kontrol etme çabaları". Çocuğunuz öfkelendiğinde size bakıp tepkinizi bekleyebilir. Bu anlarda sakin kalın ve "Oyuncak düzelmediği için şimdi öfkelendin" diyerek hissettiği duyguyu adlandırın. Sizin sakinliğiniz, onun için en iyi duygu düzenleme dersidir. Siz harika bir annesiniz!') WHERE id = '10a65a4a-b905-4a99-8c90-141b7917fa27';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık kaşık ve çatal kullanma konusunda daha becerikli. Yemeğinin büyük bölümünü dökmeden ağzına götürebilir. Bu, hem ince motor becerilerinin hem de el-göz koordinasyonunun ileri düzeyde olduğunu gösterir. Farklı dokulardaki yiyecekleri kendi başına yiyebilmesi için ona fırsat tanıyın. Bu bağımsızlık, doyduğunu daha iyi anlamasına yardımcı olur.') WHERE id = 'cd235f0e-55bc-496a-a89f-89523cd7e8fe';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel gelişimde "Tırmanma ve İnme". Çocuğunuz artık kanepeye veya alçak basamaklara tek başına çıkabilir. Yüksek bir yerden her zaman arkasını dönerek, ayakları önde olacak şekilde inmesini hatırlatın. Bu, beden güvenliği kurallarını öğrenmesi ve riskleri görsel olarak değerlendirmesi açısından önemli bir beceridir.') WHERE id = 'b1b72a87-fa8e-4ffe-811e-9806f2ea1d7c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Hareket bildiren sözcükler". Çocuğunuz artık "git", "gel", "yat", "ye" gibi fiilleri doğru durumlarda kullanır. Siz de kullandığı fiilleri genişleterek yanıt verin: "Evet, şimdi biz parka gidiyoruz". Bu, konuşmasındaki dil bilgisi yapılarının oluşmasını hızlandırır.') WHERE id = '275f2048-2ec2-445d-b693-5c34e41e7b83';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Dizme ve İnşa Etme". Çocuğunuz artık 8-10 küpü üst üste koyarak devrilmeyen kuleler yapabilir. Bu, hem dikkatini yoğunlaştırmasını hem de parmak uçlarını hassas bir şekilde kullanmasını gerektirir. Kule devrildiğinde neşeli bir tepki verin ki çocuğunuz yeniden denemeye istekli olsun. Bu, problem çözme konusundaki azmini güçlendirir.') WHERE id = '97370ca6-2fbc-4894-81aa-9ab979d2d27e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Sembolik bakım". Çocuğunuz oyuncak ayısına "su içirebilir", üzerini battaniyeyle örtebilir veya ağladığında onu okşayabilir. Bu, duygusal zekâsının ve başkalarının duygularını anlama becerisinin geliştiğini gösterir. Bu şefkatli davranışlarını övmeyi unutmayın.') WHERE id = '4c44b890-83ea-41cb-99e6-72cdc0b1bf1f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Kendi kendine toplama" alışkanlığı: Çocuğunuz artık oyuncaklarını kutuya koymayı oyunun son aşaması olarak görmeye başlar. "Haydi, arabaları yataklarına koyalım" diyerek bu süreci eğlenceli hâle getirin. Bu, hem düzen alışkanlığı hem de sorumluluk duygusu kazanmasına yardımcı olur. Size yardım ettiğinde kendini büyümüş ve faydalı bir birey gibi hisseder.') WHERE id = 'a363f89b-584e-494b-8c74-513903336560';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Aynı ve Farklı". Çocuğunuz artık aynı renk veya türdeki nesneleri gruplandırabilir. "Bütün kırmızıları buraya toplayalım" diyerek bunu deneyin. Bu oyunlar, mantıksal düşünme ve görsel analiz becerilerinin temelini oluşturur.') WHERE id = 'f0afc0a3-b89f-4803-b20f-1fd14e1c84af';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Yokuş aşağı yürüme". Eğimli yüzeylerde (küçük tepelerde) yürümek, çocuğunuzun yeni bir denge biçimi geliştirmesini gerektirir. Bu, ayak bileklerini ve vücudunun ağırlık merkezini kontrol etme becerisini güçlendirir. Parkta yürürken bu tür küçük fiziksel zorlukları deneyimlemesine fırsat tanıyın.') WHERE id = 'c7f6bf36-ec3f-4dad-b529-a2a1c67afd8f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "İsim-Zamir ilişkisi". Çocuğunuz artık kendisinden adıyla söz etmek yerine "Ben" demeye geçebilir. Ona bir şey sorduğunuzda "Ben" veya "Benim" diyorsa bu, benlik farkındalığının yerleştiğini gösterir. Onunla bu konuda diyaloglar kurun: "Bu kimin topu? Benim!".') WHERE id = 'da725a7e-8a5a-4880-b76d-f59275696659';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Hayal gücünün gelişimi: "Karmaşık taklit". Çocuğunuz artık birkaç adımdan oluşan eylemleri taklit eder. Örneğin, "pazara gider", "alışveriş yapar" ve "yemek pişirir". Bu, hem hafızasının gelişimini hem de olaylar arasındaki mantıksal bağlantıları ne kadar dikkatle gözlemlediğini gösterir.') WHERE id = '385dd8e9-365e-4aee-b063-18466c68a303';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık 22. ayın ortasında ve kelime dağarcığındaki "sözcük patlaması" devam ediyor. Artık yalnızca nesneleri değil, karmaşık duyguları ve eylemleri de adlandırmaya çalışıyor. Onunla konuşurken cümlelerinizi biraz daha karmaşık hâle getirin: "Haydi, kırmızı şapkanı takalım ve dışarı çıkalım". Bu, işitsel hafızasını ve dil bilgisi kavrayışını güçlendirir.') WHERE id = '9ec78a78-6722-4c40-af92-d0238d028cd3';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel gelişimde "Olduğu yerde zıplama ustalığı". Çocuğunuz artık iki ayağını aynı anda yerden keserken kendine daha çok güveniyor. Bu hareket, baldır kaslarını güçlendirir ve denge becerisini geliştirir. Onunla birlikte müzik eşliğinde zıplama yarışı yapın. Bu, enerjisini atmanın en eğlenceli yollarından biridir.') WHERE id = '43c73105-af4e-4d3a-b15d-a50b903d4d3e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Sıfat çeşitliliği". Çocuğunuz artık nesnelerin özelliklerini (renk, şekil, tat) daha iyi ayırt ediyor. "Ekşi limon", "tatlı elma", "soğuk su" gibi ifadeleri günlük yaşamına dahil edin. Bu, duyusal algılarını sözcüklerle ilişkilendirmesine ve dünyayı daha renkli bir şekilde anlatmasına yardımcı olur.') WHERE id = '39e55b53-a529-49e6-9321-ad14c32b7c7c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Çevirerek kapak açma". Çocuğunuz artık farklı boyutlardaki şişe kapaklarını veya kutuları çevirerek açmaya ilgi gösteriyor. Bu hareket, el bileği kaslarının dönme hareketi için mükemmel bir egzersizdir. Ona güvenli, boş plastik kaplar vererek bu "mekanik" merakını destekleyin.') WHERE id = 'be39779f-3011-4da7-aa56-861a48e906e9';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Ben kendim giyineceğim" ısrarı zirvede. Çocuğunuz artık kolay giyilen pantolonları yukarı çekmeye veya ayakkabılarını ayağına geçirmeye çalışıyor. Bu süreçte ona birkaç dakika daha fazla zaman tanıyın. Acele ettirmeden kendi başına bir şeyler yapabilmesine fırsat vermek, öz güvenini (self-esteem) her şeyden çok artırır. Sabrınız, onun bağımsızlığına sunabileceğiniz en büyük katkıdır.') WHERE id = 'f0ed327b-3dc6-4a59-97ba-d4b77cc256ae';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Paylaşmanın ilk dersleri". Çocuğunuz artık bir oyuncağı bir süreliğine başkasına vermenin onu sonsuza kadar kaybetmek anlamına gelmediğini anlıyor. Ancak "benim" duygusu hâlâ çok güçlü. Onu paylaşmaya zorlamayın; bunun yerine "sırayla oynama" kavramını uygulayarak gösterin. Bu, sosyal uyumunu kolaylaştırır.') WHERE id = 'ea8bf74e-874e-47bc-9e0f-7dc3094dfe1c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Yapboz ve Mantık". Çocuğunuz artık 4-5 parçalı basit yapbozları tek başına çözmeye heves ediyor. Görselleri zihninde birleştirmek hem dikkatini toplamasını hem de problem çözme becerisini geliştirir. Yapamadığında ona sakince yol gösterin, ancak onun yerine siz yapmayın. Bu küçük "zaferler" bilişsel gelişimini destekler.') WHERE id = '39e90e4b-782c-46d9-9e9f-4cff4dfc1e98';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Geri geri yürüme". Çocuğunuz artık birkaç adım geriye doğru güvenle yürüyebiliyor. Bu, karmaşık bir denge becerisidir ve vücudun mekânsal koordinasyonunu gerektirir. Onunla "Yengeç gibi yürüyelim" oyunu oynayın. Bu oyun farklı kas gruplarını çalıştırırken kahkaha dolu anlar da yaratır.') WHERE id = 'f9c866fa-1063-46f8-bd49-769efa10ff9a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Soru-Cevap" diyaloğu daha karmaşık hâle geliyor. Çocuğunuz "Bu nedir?" sorusunu yalnızca bir şeyin adını öğrenmek için değil, sizinle sohbeti sürdürmek için de sorabilir. Cevap verirken nesnenin işlevini de söyleyin: "Bu bir tarak, saçımızı taramak için kullanılır". Ayrıntılı açıklamalarınız onun dünyaya dair bilgisini hızla genişletir.') WHERE id = 'b9cee91c-b40d-4bad-a4d5-c04129fdcf20';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal sınırlar ve "Hayır". Çocuğunuz her şeyi kendi başına yapmak istediğinde veya isteği hemen gerçekleşmediğinde öfkelenebilir. Böyle anlarda sakin kalın ve "Şu anda çok öfkelisin ama (kuralı söyleyin) yapmak yasak" diyerek duygusunu adlandırın. Tutarlı olmanız ve sakin bir ses tonuyla açıklama yapmanız, ona duygularını yönetmeyi öğreten en iyi derstir.') WHERE id = '4c29e86c-55c8-4844-9903-13a58d0c9468';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık iki aşamalı yönergeleri kolaylıkla yerine getirebilir. Örneğin: "Oyuncağı al ve rafa koy". Bu, hem çalışma belleğinin hem de dili anlama becerisinin yeni bir düzeye ulaştığını gösterir. Gün içinde ona bu tür küçük "görevler" vererek hem sorumluluk duygusunu hem de dikkatini geliştirebilirsiniz.') WHERE id = '63b64ef1-0e7a-45db-8f97-702657621c76';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Merdiven çıkma ustalığı". Çocuğunuz artık tek elinden tuttuğunuzda merdivenleri adım adım (her basamağa tek ayakla basarak) çıkmayı deneyebilir. Bu, uyluk ve kalça kaslarının güçlendiği anlamına gelir. Her zaman yakınında olup güvenliğini sağlayın ve başarılarını alkışlayın.') WHERE id = '4d704d6f-6be2-478b-b2bb-0363d0dde71b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Neden-sonuç" ifadeleri. Çocuğunuz artık "Çünkü" (veya buna benzer bir ses) demeyi deneyerek bir şeyi neden istediğini açıklayabilir. Siz de ona nedenleri açıklayın: "Şimdi dondurma yemiyoruz, çünkü hava soğuk". Bu, mantıksal düşünme ve gerekçe sunma becerisinin temelini oluşturur.') WHERE id = 'f2f8883c-9f63-473e-95a0-d34bd2a07048';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerde "Vidalama ve çevirme". Çocuğunuz artık şişe kapaklarını ve oyuncak vidalarını güvenle çevirerek açıp kapatabilir. Bu, el bileği kaslarının dönme hareketi için en iyi egzersizlerden biridir. Ona farklı boyutlarda plastik kaplar vererek bu mekanik merakını destekleyin. Bu beceri, gelecekte kalem tutmak gibi daha karmaşık işler için önemlidir.') WHERE id = '691bb5ce-e086-4aaa-85cf-679930593155';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Ben kendim yıkanıyorum". Çocuğunuz banyo yaparken sabunu veya süngeri alıp vücudunu ovalayarak sizi taklit etmeye çalışır. Hijyen alışkanlıklarına duyduğu bu ilgiyi engellemeyin. Kendi kendini "temizlemesi", hem vücudunun bölümlerini daha iyi tanımasına hem de kişisel hijyen sorumluluğunu erken yaşta kazanmasına yardımcı olur.') WHERE id = 'd4a78241-9e41-44ca-8bb9-8ed66f07c05f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Paylaşmanın zorluğu". Bu yaşta "Benim!" diye bağırması son derece normaldir. Çocuğunuz kendisine ait olan şeyleri korumayı öğrenir. Onu paylaşmaya zorlamayın; bunun yerine "Sırayla oynayalım" ilkesini uygulayın. Bu, çocuğunuza güven duygusu verir: Oyuncağını geri alacağını bilir. Gösterdiğiniz bu sabır, onun sosyal zekâsını şekillendirir.') WHERE id = '6ff62ac3-5f68-4753-ac59-118eb1c39c2b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Eşleştirme" (Matching). Çocuğunuz artık aynı hayvanın farklı resimlerini veya aynı renkteki nesneleri birbiriyle eşleştirebilir. Onunla basit kartlar kullanarak "Aynısını bul" oyunu oynayın. Bu, hem görsel dikkatini hem de kategorilere göre düşünme becerisini hızla geliştirir.') WHERE id = '63ba4843-04a1-423b-8338-e5d3a90cedb9';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topu uzağa atma". Çocuğunuz artık topu yalnızca yere bırakmakla kalmaz, omuz üzerinden (overhand) ileriye doğru atmaya çalışır. Bu hareket tüm vücudun koordinasyonunu gerektirir. Onunla parkta veya geniş bir alanda "Topu kim daha uzağa atacak?" oyunu oynayın. Bu, hem kollarını güçlendirir hem de mesafe algısını geliştirir.') WHERE id = '972bc93a-ef8b-4efd-af66-730802aaa073';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Yükseklik ve Mesafe". Çocuğunuz artık merdivenden veya koltuktan inerken mesafeyi daha iyi hesaplıyor. Ona her zaman dikkatli olmasını ve güvenli şekilde (arkası dönük olarak) inmeyi hatırlatın. Bu, beden güvenliği kurallarını öğrenmesi açısından önemli bir aşamadır.') WHERE id = '6dd30633-3c9b-4455-9878-c9a89b329928';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyonda "Zıplarken yön değiştirme". Çocuğunuz artık yalnızca olduğu yerde zıplamıyor, zıplarken yönünü de değiştirmeye çalışıyor. Bu, kaba motor becerilerinde yüksek düzeyde koordinasyonun göstergesidir. Onunla birlikte yumuşak bir halının üzerinde hareketli oyunlar oynayın. Bu, hem enerjisini atmasına hem de bedenini daha iyi kontrol etmesine yardımcı olur.') WHERE id = '85fd0d24-866e-4847-be35-912d99da58df';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Dil gelişiminde "Hayvanlar ve yavruları". Çocuğunuz artık hayvanların adlarını biliyor; şimdi de hayvanlarla yavrularını (örneğin, kedi ve yavrusu) ayırt etmeye ilgi gösterebilir. Kitap okurken bu ayrıntılardan söz edin. Bu, hem kategorilere göre düşünme becerisini hem de doğaya olan ilgisini geliştirir.') WHERE id = 'ce938ec0-b1a1-418d-9c79-f5996a2ee822';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal gelişimde "İrade ve Sınırlar". Çocuğunuz artık "Hayır" kelimesinin gücünü tamamen anlıyor ve onu sık sık kullanıyor. Böyle anlarda sakin kalın ve ona seçenekler sunarak "hayır"ı "evet"e dönüştürmeye çalışın. Kararlılığınız ve aynı zamanda şefkatli yaklaşımınız, ona kurallar çerçevesinde özgür olmayı öğreten en iyi derstir.') WHERE id = '699f4641-31b9-4174-a887-f0cb838a43e4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '23. ayın son on gününe başlıyoruz! Çocuğunuz artık "Ben" zamirini tam olarak kavrayarak kullanıyor. "Ben geldim", "Ben yedim" gibi cümleler, kendisini çevresinden ayrı bir birey olarak gördüğünü gösterir. Bu bağımsız ifadelerini destekleyin ve konuşmalarını genişletin: "Evet, sen lezzetli yemeğini yedin, aferin sana!".') WHERE id = '7aacd700-e4fe-464f-89ef-4b8e3945aa5a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Koşarken yön değiştirme". Çocuğunuz artık hızla koşarken aniden yönünü değiştirebilir veya engellerin etrafından dolaşabilir. Bu, hem kas gücünün hem de hızlı karar verme becerisinin göstergesidir. Parkta onunla "beni yakala" oyunu oynayarak çevikliğini geliştirin.') WHERE id = 'a492f1d5-4125-4356-ab32-a3a06c3ae006';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Dil gelişiminde "Çokluk kavramı". Çocuğunuz artık "bir" ile "çok" arasındaki farkı anlamaya başlıyor. Oyuncaklarını gösterip "Burada çok sayıda araba var" diyerek sayma becerisinin ilk temellerini atın. Henüz sayıları sırayla söylemese de miktar farkını görsel olarak algılaması, matematiksel düşünme becerisinin başlangıcıdır.') WHERE id = '6541c63d-d78c-444c-93ac-32836d55b462';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor gelişiminde "Sanat eserleri". Çocuğunuz artık kalemi daha kontrollü tutarak "kapalı çizgiler" (daireye benzeyen şekiller) çizmeye çalışıyor. Ona farklı renklerde kalemler verin ve çizdiği her şekli bir nesneye benzeterek onu teşvik edin: "Bak, bu topa benziyor!".') WHERE id = 'de8e6a20-ca58-4eb3-bdc2-7db3ed5bcda2';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Rica etme". Çocuğunuz artık bir şey istediğinde yalnızca parmağıyla göstermiyor, "Ver" veya "Lütfen" (ya da buna benzer bir ifade) diyebiliyor. Ona her zaman nazik ifadeler kullanarak örnek olun. Sizden "Teşekkür ederim" veya "Lütfen" sözlerini duyması, gelecekteki iletişim kültürünün temelini oluşturur.') WHERE id = '0ffa5444-e49f-4507-b5e7-cc95f08b1d36';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Hayal gücünün gelişmesi: "Rol oyunları karmaşıklaşıyor". Çocuğunuz artık yalnızca yemek pişirmiyor; oyuncaklarını misafirliğe çağırıyor, onları "tedavi ediyor" veya "arabaya bindirip işe götürüyor". Bu, hafızasındaki olayları nasıl birleştirdiğini gösterir. Bu rol oyunlarına onunla birlikte katılın; böylece yaratıcılığının gelişimini en üst düzeye taşıyabilirsiniz.') WHERE id = '24d4307d-0d0c-428b-a2fb-db25c78400d8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık renkleri yalnızca tanımakla kalmıyor, aynı renkleri eşleştirme konusunda da ustalaşıyor. Ona "Kırmızı çorabının eşini bul" dediğinizde bunu doğru yapıyorsa, bu görsel mantığının geliştiğini gösterir. Günlük kıyafetlerinde renkleri sık sık vurgulayın: "Bugün yeşil tişörtünü giyelim mi?". Bu, kelime dağarcığındaki sıfatları pekiştirir.') WHERE id = '179a1147-4671-4989-8a35-24a67964487b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Tek ayak üzerinde denge". Çocuğunuz artık birkaç saniyeliğine de olsa bir ayağını yerden kaldırıp dengesini korumaya çalışıyor. Bu, vücudun ağırlık merkezini yönetmeyi gerektiren karmaşık bir koordinasyon becerisidir. Onunla "Leylek oyunu" oynayın. Bu oyun hem eğlenceli hem de fiziksel gelişim için çok faydalıdır.') WHERE id = '6a2ac5db-ce06-4c8b-b0f1-21122d14d9a3';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Zaman kavramının ilk izleri". Çocuğunuz "şimdi" ve "sonra" gibi kelimeler arasındaki farkı anlamaya başlıyor. Ona "Önce yemek yiyelim, sonra parka gidelim" dediğinizde bekleyebiliyorsa, bu büyük bir ilerlemedir. Sabretme alışkanlığının gelişmesi için zaman sıralamasını davranışlarınızla açıklamaya devam edin.') WHERE id = '91b2f1d2-b8e0-4586-beb2-1ed7668e668d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Yapboz ustalığı". Çocuğunuz artık 5-6 parçalı basit yapbozları tek başına tamamlayabilir. Resimleri görsel olarak birleştirmek hem dikkatini toplamasını hem de problem çözme becerisini geliştirir. Yapamadığında ona sakince yol gösterin, ancak onun yerine siz yapmayın. Bu küçük "zaferler" bilişsel gelişimini destekler.') WHERE id = 'feada4a3-1665-4491-8ec1-8dc39ef9224c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Kendim içiyorum". Çocuğunuz artık açık bardaktan suyu neredeyse hiç dökmeden, güvenle içiyor. Bu, dudak ve çene kaslarının konuşmaya ne kadar hazır olduğunun bir göstergesidir. Bu beceride tamamen ustalaşması için ona çocuk boyutunda, rahatça tutabileceği bardaklar vermeye devam edin.') WHERE id = '20e5b03d-5d16-4142-97b2-3cffec7b0034';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Mizah duygusu". Çocuğunuz bilerek bir şeyi "yanlış" yapıp (örneğin şapkasını ayağına takıp) size bakabilir ve gülebilir. Bu, şaka anlayışının ve sosyal etkileşim becerisinin geliştiğini gösterir. Onun bu "oyununa" coşkuyla katılın. Birlikte gülmek, aranızdaki duygusal bağı daha da güçlendirir.') WHERE id = '0f7fea0c-bb47-4b7d-9391-ab4589f33670';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Üç kelimeli cümleler". Çocuğunuz artık "Anne, su ver", "Baba, parka git" gibi daha karmaşık cümleler kuruyor. Artık ihtiyaçlarını tam olarak ifade edebiliyor. Siz de onun cümlelerini onaylayarak biraz daha genişletin: "Evet, şimdi gel su içelim, sonra parka gideriz". Bu, onun dil bilgisi kavrayışını geliştirir.') WHERE id = '8ba75ebe-7968-4c36-9120-369b2e5d0ec2';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Puzzle ustalığı" gelişiyor. Çocuğunuz artık 6-8 parçalı basit puzzle''ları tek başına tamamlayabiliyor. Bu, hem görsel analiz becerisi hem de parmak kaslarının hassas kullanımı açısından önemlidir. Resmi her tamamladığında sevincini paylaşın ki daha karmaşık görevlere olan ilgisi artsın.') WHERE id = '527f78da-7fbc-42ab-a36c-6bee3afe966e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Ben kendim topluyorum". Oyuncakları yerine koymak artık onun için yalnızca bir görev değil, aynı zamanda bir sorumluluktur. Ona "Hadi, arabaları yataklarına koyalım" dediğinizde size yardım ediyorsa bu, düzen ve disiplinin temelidir. Bu alışkanlık, gelecekte kişisel düzenini sağlaması açısından çok önemlidir.') WHERE id = '4cae5197-2921-4caa-b98c-16f64a7694c8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Paylaşma ve Sıra Bekleme". Çocuğunuz artık "Şimdi sıra sende" dendiğinde biraz beklemesi gerektiğini anlıyor. Sabretmeyi öğrenmek bu yaş için büyük bir başarıdır. Sırayla oynanan oyunlarda (örneğin, topu birbirinize atmak) onu destekleyin. Sizin bu sabırlı yaklaşımınız, onun sosyal uyumunu kolaylaştırır.') WHERE id = 'e3e7be7f-e682-47f1-bdf9-05213d301d28';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Aynı ve Farklı". Çocuğunuz artık aynı türdeki nesneleri (örneğin, tüm hayvanları bir yere, tüm arabaları başka bir yere) gruplayabiliyor. Ona "Burada hangi oyuncak farklı?" gibi sorular sorarak görsel mantık becerisini değerlendirin. Kategoriler hâlinde düşünmek, bilişsel gelişimini yeni bir düzeye taşır.') WHERE id = '9960803a-4e47-4edd-b50d-dc62d848c875';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Olduğu yerde zıplama ve dönme". Çocuğunuz artık yalnızca zıplamıyor, zıplarken vücudunu döndürmeye de çalışıyor. Bu, kaba motor kaslarının ileri düzeyde koordinasyonunu gösterir. Onunla birlikte müzik eşliğinde hareketli "dans" saatleri düzenleyin. Bu, hem eğlenceli hem de vücut esnekliği için harika bir egzersizdir.') WHERE id = 'b8a638df-098e-4767-9ebb-0f4df5304a5e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Hafıza ve Olaylar". Çocuğunuz gün içinde yaşanan basit bir olayı (örneğin, "Parkta köpek gördüm") hatırlayıp size anlatabilir. Onun bu hikâyelerini dikkatle dinleyin ve "Sonra ne oldu?" diye sorarak olayları sıraya koymasına yardımcı olun. Bu, hem hafızasını hem de kendini ifade etme becerisini güçlendirir.') WHERE id = '9fdcc45e-2b1e-4d3c-95a7-d7f5adca9ccb';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal hazırlık: 2 yaşına yalnızca 50 gün kaldı! Çocuğunuz artık duygularını daha derin biçimde gösteriyor. Size olan sevgisini aniden sarılarak veya öperek gösterebilir. Siz de ona aynı şefkatle karşılık verin. Bu duygusal paylaşım, kendini güvende ve en önemlisi "sevilen bir birey" olarak hissetmesi için en büyük besindir.') WHERE id = '78317024-ad5b-4a00-86b5-ab43a417337b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Kendim yardım ediyorum." Çocuğunuz, ev işlerinde size yardım etmekten büyük keyif alır. Ona "Çamaşırları sepete koymama yardım et" gibi gerçek görevler verin. Bu, hem motor becerilerini hem de aile içindeki sorumluluk duygusunu geliştirir. Yardım ettikten sonra ona "Sen benim en büyük yardımcimsin" deyin.') WHERE id = 'f2819b1a-b1cb-4ed8-b546-aae23641438e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Nezaket kuralları". Çocuğunuz artık "Teşekkür ederim" ve "Lütfen" ifadelerini doğru yerlerde kullanmaya başlayabilir. Elbette bu, sizin ona örnek olmanıza bağlıdır. Ona her bir şey verdiğinizde veya ondan bir şey aldığınızda bu ifadeleri kullanarak örnek olun. Bunlar, gelecekteki sağlıklı iletişim becerilerinin en sağlam temelini oluşturur.') WHERE id = 'eb0307cc-cb5a-49a5-b989-e572cad76794';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Mevsimler ve Hava Durumu". Çocuğunuz artık dışarıdaki hava değişikliklerini (yağmur, güneş, rüzgâr) fark eder ve bunlara tepki verir. Pencereden bakıp "Yağmur yağıyor" diyerek olayları adlandırın. Bu, çevresiyle kurduğu bağı güçlendirir ve kelime dağarcığına doğayla ilgili yeni kavramlar ekler.') WHERE id = 'e5dc7560-975f-4493-9ff3-ea6744e46ec0';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topu hedefe atma". Çocuğunuz artık önündeki topa yalnızca tekme atmakla kalmaz, onu belirli bir yöne (örneğin kaleye) göndermeye çalışır. Bu, görsel dikkat ile hareket koordinasyonunun birleşimidir. Evde onunla yumuşak bir top kullanarak küçük bir "futbol" maçı yapın.') WHERE id = 'f701f5d4-0488-45fc-bf57-a9b74d61b0af';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşma gelişiminde "Hafıza ve masallar". Çocuğunuz en sevdiği masalı artık o kadar iyi bilir ki siz cümleyi yarım bıraktığınızda tamamlayabilir. Masal okurken duraklayın ve onun devam etmesini bekleyin. Bu, hem hafızasını hem de olayların sırasını kavrama becerisini olağanüstü ölçüde geliştirir.') WHERE id = 'c61438a5-bdff-4ed0-b914-6e977fdb2bc1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal hazırlık: 2 yaşına sayılı günler kaldı! Çocuğunuz artık duygularını daha karmaşık biçimlerde ifade eder. Aniden sarılmak isteyebilir veya bağımsızlığını kanıtlamak için koşup saklanabilir. Bu dönemde onunla sabırla iletişim kurmanız ve her adımında yanında olduğunuzu hissettirmeniz, duygusal güvenliği için atılabilecek en önemli adımdır.') WHERE id = 'bcd3ac04-2293-413d-8bfd-ba0e21e03fe2';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık zevklerini ve tercihlerini kararlılıkla ortaya koyar. Hangi kitabı okuyacağınıza veya hangi oyuncakla oynayacağınıza kendisi karar vermek ister. Ona bu küçük liderlik fırsatlarını tanıyın. Bu, hem karar verme becerisini geliştirir hem de kendisini değerli bir birey olarak hissetmesine yardımcı olur.') WHERE id = 'b41a09b6-e8fc-4b09-b81c-400b678af920';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel gelişimde "Dinamik Denge". Çocuğunuz artık bir çizgi üzerinde yürümeye veya elinden tuttuğunuzda alçak bir kaldırım kenarında adım atmaya çalışır. Bu, vücudun ağırlık merkezini kontrol etmeyi öğrenmesi için mükemmel bir egzersizdir. Parkta yürürken yere çizilmiş çizgilerin üzerinde yürüme oyunu oynayarak koordinasyonunu güçlendirin.') WHERE id = '5d42a805-244d-4112-9107-40ebc50ef785';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık renkleri yalnızca ayırt etmekle kalmıyor, birçoğunun adını doğru telaffuz ediyor. Ona "Mavi arabayı getir" dediğinizde hata yapmıyorsa bu, görsel ve sözel hafızasının birlikte çalıştığını gösterir. Günlük gezintilerinizde "Yeşil yaprak", "Sarı güneş" gibi betimlemelerle onun dünyasını renklendirmeye devam edin.') WHERE id = '85496aa4-c911-4bb2-8f2e-3e5a32779858';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Merdiven özgürlüğü". Çocuğunuz artık tek elinden tuttuğunuzda merdivenleri, ayaklarını sırayla kullanarak her basamağa bir ayağını koyup çıkmaya çalışıyor. Bu, kaba motor gelişimi açısından önemli bir başarıdır. Her zaman yakınında olup güvenliğini sağlayın, ancak kendi başına adım atabilmesi için ona güven verin.') WHERE id = 'e1b72aca-8d9f-4f33-aedd-ed905b733dbf';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Konum bildiren sözcükler". Çocuğunuz artık "üstünde", "altında", "arkasında" gibi kavramları hareketleriyle gösterebiliyor. Ona "Topu sandalyenin altına koy" diyerek küçük bir oyun oynayın. Bu görevler hem dili anlama hem de mekânsal yönelim becerisini hızla geliştirir.') WHERE id = '455a2119-ac1e-44e4-8b8c-20b0405c50d6';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Vida ve çevirme ustalığı". Çocuğunuz şişe kapaklarını ve oyuncak vidalarını rahatlıkla açıp kapatabiliyor. Bu, el bileği kaslarının esnekliği için harika bir egzersizdir. Ona farklı boyutlarda güvenli kaplar vererek bu "mekanik" keşif merakını destekleyin.') WHERE id = '61305052-b44e-493c-a6f8-ffe876e0e01e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Kendim giyiniyorum" aşaması giderek daha karmaşık hâle geliyor. Çocuğunuz artık fermuarı çekmeye (siz başlattıktan sonra) veya büyük düğmeleri açmaya çalışıyor. Bu süreçte ona engel olmayın ve onu acele ettirmeyin. Bir şeyi kendi başına başarabildiğini görmek, onun için en büyük özgüven kaynağıdır. Küçük başarılarında onu mutlaka teşvik edin.') WHERE id = 'f6d69242-03a3-4cc8-a444-aac7bbd07185';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışlarda "Empati" artıyor. Çocuğunuz sizin veya başka bir çocuğun üzüldüğünü gördüğünde yanınıza gelip oyuncağını uzatabilir ya da size sarılabilir. Bu, duygusal zekâsının (EQ) güzel bir göstergesidir. Bu duyarlı davranışını "Bana destek olduğun için çok teşekkür ederim" diyerek takdir edin.') WHERE id = '98c8accf-ca7d-4901-b417-a3bce7f325f2';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Şekil ve Boyut". Çocuğunuz artık aynı şeklin (örneğin dairenin) büyük ve küçük hâllerini ayırt edebiliyor. Ona farklı boyutlardaki kapları iç içe yerleştirmeyi gösterin. Bu, gelecekteki matematiksel düşünme becerisinin temeli olan "sıralama" yeteneğini geliştirir.') WHERE id = 'bfdb17de-cc0d-437c-870c-13801051e507';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topa vurma ve hedef". Çocuğunuz artık topa yalnızca vurmakla kalmıyor, onu belirli bir yöne göndermeye çalışıyor. Bu, görsel dikkat ile hareket koordinasyonunun birleşimidir. Evde veya parkta onunla "küçük bir kale" oluşturup topu kaleye gönderme oyunu oynayın. Bu, bacak kaslarını güçlendirir ve isabetliliğini artırır.') WHERE id = 'a17dc9b7-c84f-4802-8431-7aad7b966067';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Parçalardan bütünü oluşturma". Çocuğunuz artık 3-4 parçalı basit yapbozları görsel ipuçlarından yararlanarak birleştirebilir. Bu, hem dikkatini toplamasını hem de problem çözme becerisini geliştirir. Yapamadığında ona sakin bir ses tonuyla yardımcı olun: "Bak, bu köpeğin kuyruğu, sence nerede olabilir?". Bu küçük başarılar onun bilişsel gelişimini destekler.') WHERE id = '6ae9f735-9ae2-46e6-8771-fa1ead2cea34';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topa vurma ve koşma". Çocuğunuz artık koşarken önündeki topa dengesini kaybetmeden vurabilir. Bu, hareket hızını ve dinamik dengeyi aynı anda kontrol edebildiğini gösterir. Onunla bahçede veya parkta "futbol" oynayarak hareketlerinin isabetini geliştirin. Sizinle birlikte hareket etmek onun için en büyük eğlencedir.') WHERE id = '17868f49-652d-4efe-940b-fac27063768e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Anıları ifade etme". Çocuğunuz dün gördüğü veya yaşadığı bir olayı (örneğin, "Parkta kuş gördüm") hatırlayıp size anlatabilir. Anlattıklarını dikkatle dinleyin ve "Kuş ne yapıyordu?" diyerek sohbeti genişletin. Bu, hem hafızasını hem de kendini ifade etme becerisini önemli ölçüde geliştirir.') WHERE id = 'd99ef035-085a-4da0-b18e-ddf8dda326d1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Tebrikler, 700 günü tamamladık! 2 yaşına yalnızca bir ay (30 gün) kaldı. Çocuğunuz artık bebeklik dönemini tamamen geride bırakarak kendi karakteri, istekleri ve becerileri olan küçük bir "insan"a dönüştü. Bugün onunla en sevdiği oyunu oynayarak katettiğiniz bu uzun yolu kutlayın. Harika bir yol katettiniz, Anne!') WHERE id = '0e3a52c6-9f66-42e2-994a-692b5b642618';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '24. aya, yani çocuğunuzun 2 yaşını doldurmasına doğru son adımları atmaya başlıyoruz! Çocuğunuz artık kendi eşyalarını ve kıyafetlerini çok iyi tanıyor. Ona "Dolaptan kendi tişörtünü getir" dediğinizde bunu yapıyorsa, bu durum hem hafızasının hem de aidiyet duygusunun güçlendiğini gösterir. Bu tür küçük görevler özgüvenini artırır.') WHERE id = 'f1337afd-8cd4-4800-85b9-83874ec33ec8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel gelişimde "Kaldırım kenarında denge". Çocuğunuz artık elinden tuttuğunuzda alçak kaldırım kenarlarının (bordürlerin) üzerinde yürümeye ilgi gösterir. Bu, gelişmiş denge becerisini destekler. Güvenli yerlerde bu ilgisini teşvik edin; çünkü bu beceri, gelecekte daha karmaşık fiziksel hareketler için temel oluşturur.') WHERE id = '48e8258d-7e1b-417f-861b-84e4a830fb92';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Zamirleri doğru kullanma". Çocuğunuz artık "Ben", "Sen", "O" gibi zamirleri cümle içinde daha doğru kullanır. Örneğin: "Ben acıktım" veya "Sen gel". Bu gelişimini desteklemek için siz de onunla konuşurken zamirleri vurgulayın. Bu, sosyal iletişim kurma becerisinin hızla gelişmesine yardımcı olur.') WHERE id = '6c0e87a6-05f9-4b6b-826c-adb939561dc2';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor gelişiminde "Yapı ustalığı". Çocuğunuz artık küpleri yalnızca üst üste dizmekle kalmaz, onlarla "ev", "tren" veya "çit" gibi yapılar oluşturur. Bu, görsel-uzamsal düşünme becerisinin yeni bir aşamaya geçtiğini gösterir. Yaptığı "yapıları" ilgiyle karşılayın ve "Buraya kim gelecek?" gibi sorular sorun.') WHERE id = 'd0a7b08b-aa7f-465e-8cfb-7b1cbe914d24';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Hikâye anlatma girişimleri". Çocuğunuz gün içinde gördüğü ilginç bir şeyi (örneğin, "Büyük bir köpek gördüm") size anlatmak için can atar. Hikâyesini sonuna kadar dinleyin ve sorularla ayrıntılandırmasına yardımcı olun: "Köpek ne renkti?". Bu, hem hafızasını hem de kendini ifade etme becerisini güçlendirir.') WHERE id = 'daff24e3-d7cd-46e0-9c7d-75e6a3417d53';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal sınırlar: Çocuğunuz artık "İstemiyorum" diyerek kendi iradesini kararlı bir şekilde ortaya koyabilir. Böyle anlarda inatlaşmak yerine ona seçenekler sunarak dikkatini başka yöne çekin. Sabrınız ve tutarlı kurallarınız, çocuğunuzda güven duygusu oluşturur. 2 yaşına yalnızca 40 gün kaldı – harika bir iş çıkarıyorsunuz!') WHERE id = '30c55932-1036-4bc0-a31f-1b927f46a841';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık 23. ayın sonuna yaklaşıyor. Artık kendisinden yalnızca "Ben" diye söz edildiğini değil, adıyla hitap edildiğini de tamamen anlıyor. Onunla konuşurken "Bunu sen mi yaptın?" diye sorduğunuzda gururla "Evet" diyorsa, bu, benlik farkındalığının geliştiğini gösterir. Başarılarını adını söyleyerek övün: "Aferin (çocuğun adı), sen bunu başardın!".') WHERE id = '9459dc0c-afe8-45b3-b94d-dd65b48126f2';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Serbestçe koşma ve durma". Çocuğunuz artık koşarken aniden ve düşmeden durabilir. Bu, frenleme (inhibitory control) sisteminin ve kaslarının ne kadar geliştiğini gösterir. Onunla parkta "Koş ve dur!" oyunu oynayın; bu oyun hem eğlencelidir hem de koordinasyon gelişimi için faydalıdır.') WHERE id = 'ecf7ae38-688c-4cbe-90a0-7112da130536';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Soru sorma dönemi". Çocuğunuz artık birçok şeyin adını bildiği için bunların ne işe yaradığını sormaya eğilimlidir. Bir nesneyi gösterip "Bu?" dediğinde yalnızca adını söylemekle kalmayın, işlevini de açıklayın: "Bu bir şemsiye, yağmurdan korunmak içindir". Ayrıntılı yanıtlarınız, dünyaya dair bilgisini hızla genişletir.') WHERE id = 'cb8ab97b-604a-4728-ac40-ae0675a2ce85';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Dikey ve yatay çizgiler". Çocuğunuz artık kalemi daha güvenli bir şekilde tutuyor ve kâğıt üzerinde bilinçli olarak düz çizgiler çiziyor. Ona farklı renklerde kalemler ve büyük kâğıtlar vererek "ressamlık" becerisini destekleyin. Bu, gelecekteki yazma becerileri için önemli bir temeldir.') WHERE id = 'b5be883e-3ec9-4583-905f-d5eaa6d996f3';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız seçim" dönemi zirvede. Çocuğunuz artık ne yiyeceğine, hangi oyuncakla oynayacağına ve hatta hangi yolu seçeceğine kendisi karar vermek istiyor. Ona sınırlı seçenekler sunun: "Bugün elma mı yemek istersin, yoksa muz mu?". Bu, hem karar verme becerisini geliştirir hem de kendisini yönetilen değil, kontrol sahibi bir birey gibi hissetmesini sağlar.') WHERE id = 'd071c76a-b155-43af-a2a1-de9194ca4c11';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Sembolik taklit". Çocuğunuz artık evdeki rollerinizi taklit ediyor: "yemek yapıyor", "telefonla konuşuyor", "evi temizliyor". Bu taklit, onun dünyayı öğrenme yöntemidir. Ona küçük bir oyuncak süpürge veya kaplar vererek sizin "yardımcınız" olmasına fırsat tanıyın.') WHERE id = 'ee398ccc-6f29-41df-b0a4-1bb95b88b1a5';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Rol yapma oyunlarının karmaşıklaşması". Çocuk artık art arda birkaç hareketten oluşan oyunlar kurar: Örneğin oyuncak ayısını "yıkar", "kurular" ve ardından "uyutur". Bu, hafızasında yer alan günlük yaşam senaryolarını nasıl sistemli bir şekilde birleştirdiğini gösterir.') WHERE id = '290cdbcc-b930-4c04-ac8f-c9e9a99f2bd8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız yemek yeme becerisi". Çocuk artık yiyecekleri çatalına batırıp ağzına götürme konusunda oldukça beceriklidir. Kendi başına yemek yemesi için ona daha fazla fırsat verin. Masanın biraz kirlenmesi, hem ince motor becerilerini hem de öz bakım sorumluluğunu geliştirmesi için ödenmesi gereken küçük bir bedeldir.') WHERE id = 'a907e23d-d22f-4f12-8eba-ed2e00af2852';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Büyük-Küçük-Orta". Çocuk artık yalnızca iki değil, üç farklı boyutu ayırt etmeye başlayabilir. Ona aynı oyuncağın üç farklı boyutunu verin ve "En büyüğünü bana ver" diyerek deneyin. Bu, matematiksel karşılaştırma becerisinin temelidir. Her doğru seçiminde onu teşvik edin.') WHERE id = '228f5557-8af1-45e0-8eea-dab6d6ab319d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyonda "İki ayakla ileri atlama". Çocuk artık yalnızca olduğu yerde değil, biraz ileriye doğru da atlayabilir. Bu hareket, bacak kaslarının patlayıcı gücünü ve vücut koordinasyonunu gerektirir. Onunla parkta "Tavşanlar çayırda zıplıyor" oyunu oynayın. Bu, hem eğlenceli hem de kaba motor becerileri için harika bir egzersizdir.') WHERE id = 'fed4cb8e-d23c-4ef3-9fb0-62697ac89488';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Dil gelişiminde "Çıkarım yapma". Çocuk artık bazı olayların sonucunu önceden söyleyebilir. Örneğin siz ayakkabılarınızı aldığınızda "Dışarı mı gidiyoruz?" diye sorar. Bu, mantıksal bağlantıları ne kadar güçlü kurduğunu gösterir. Bu tür sorularını doğrulayın ve ek bilgi verin: "Evet, gidip kuşlara ekmek vereceğiz".') WHERE id = '0aaeb1eb-0155-44f3-b404-be39c9061780';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal hazırlık: 2 yaşına yalnızca 20 gün kaldı! Çocuk artık duygularını daha açık ifade ediyor ve size olan bağlılığını "Seni seviyorum" sözleriyle (veya kendi dilinde benzer anlam taşıyan ifadelerle) ve davranışlarıyla gösteriyor. Bu günlerde onunla geçirdiğiniz her an, duygusal dünyasında silinmez izler bırakır. Siz harika bir anne ve rehbersiniz!') WHERE id = 'f640772a-39c6-4d33-9c3f-64bd16ad5ed0';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuk artık "Kendim giyineceğim" döneminin en ısrarcı aşamasındadır. Pantolonunu giymek veya ayakkabılarını (zor olsa da) ayağına geçirmek istemesi, bağımsızlık ilanıdır. Denemesi için ona birkaç dakika daha fazla zaman tanıyın. Bu sabrınız, gelecekteki öz güvenine yapacağınız en büyük yatırımdır.') WHERE id = 'e264db36-ff8b-4ffc-8d0c-2a9a86b8e80e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Olduğu yerde dönme". Çocuk artık kendi etrafında dönüyor ve bunun sonucunda ortaya çıkan "baş dönmesi" hissini merakla karşılıyor. Bu, vestibüler (denge) sisteminin geliştiğini gösterir. Güvenli ve yumuşak bir alanda onunla birlikte dans ederek bu yeni hissi keşfetmesine fırsat verin.') WHERE id = 'c1b5ac77-3624-4a68-8f84-6255305e6a71';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '2 yaşını doldurmasına son 10 gün! Çocuğunuz artık kendi benliğinin tamamen farkında. Aynada kendine bakıp adını söylüyor veya "Bu benim!" diye işaret ediyor. Bu benlik bilinci, gelecekteki öz güveninin temelidir. Onunla aynanın karşısına geçip ne kadar büyüdüğünü ve neler yapabildiğini birlikte kutlayın.') WHERE id = '391d8114-3346-495b-b8f3-45861173d919';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel gelişimde "Engelleri aşarak koşma". Çocuğunuz artık koşarken önündeki engelleri hızlı manevralarla aşabiliyor. Bu, hem fiziksel gücün hem de hızlı karar verme becerisinin birleşimidir. Evde veya bahçede onun için küçük bir "engel parkuru" oluşturarak çevikliğini denemesine fırsat verin.') WHERE id = '23f145d6-39f1-4e1e-84f1-49d36b707443';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Hikâye anlatıcısı" aşaması. Çocuğunuz artık gün içinde yaşanan basit bir olayı (örneğin, "Kuş uçtu", "Dondurma yedim") hatırlayıp size anlatıyor. Bu küçük hikâyelerini dikkatle dinleyin ve sorularla ayrıntılandırmasına yardımcı olun. Bu, hem hafızasını hem de olaylar arasında mantıksal bir sıralama kurma becerisini güçlendirir.') WHERE id = 'c8794b59-4f44-4d01-9dfd-9f86547c80bb';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor gelişiminde "Kitap sevgisi". Çocuğunuz artık ince kâğıt sayfaları yırtmadan, tek tek çevirebiliyor. Sevdiği masal kitabını getirip ona okumanız için dizinizin üzerine koyuyor. Bu ritüel, hem dil gelişimi hem de sizinle arasındaki duygusal bağ açısından çok değerlidir. Okurken resimler hakkında sorular sorun.') WHERE id = '25aab72e-4248-42bb-9009-a3467dd34bf8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "İlk arkadaşlıklar". Çocuğunuz artık diğer çocuklarla yalnızca yan yana oynamıyor; onlara oyuncak teklif ediyor veya onlarla birlikte koşuyor. Bunlar, sosyal iş birliğinin ilk gerçek adımlarıdır. Bu olumlu sosyal etkileşimlerini teşvik edin ve paylaşmaya istekli olduğu için onu övün.') WHERE id = 'fbc5e912-7941-46bd-9137-7aea112e7d13';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız kişisel bakım". Çocuğunuz artık ellerini sabunla yıkamaya ve havluyla kurulamaya heves ediyor. Bu öz bakım alışkanlıkları, bağımsızlık duygusunu besler. Bu kişisel bakım ritüellerini günlük yaşamının doğal bir parçasına dönüştürebilmesi için boyuna uygun bir ortam hazırlayın.') WHERE id = 'e689f8a3-742e-457c-849e-63c06d7af7c0';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Sıralama ve Mantık". Çocuğunuz artık 4-5 nesneyi boyutlarına göre (büyükten küçüğe) sıralayabiliyor. Bu, matematiksel düşünmenin en erken temelidir. Ona farklı boyutlarda küpler veya kaplar vererek bu sıralama becerisini geliştirmesini sağlayın. Başarıyla tamamladığı her bir "sıralama", beyninde yeni nöral bağlantılar oluşturur.') WHERE id = 'd3ed6715-8284-423a-bbce-cfe0156fda68';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "İki ayakla ileriye atlama". Çocuğunuz artık yalnızca olduğu yerde değil, birkaç santimetre ileriye de atlayabiliyor. Bu hareket, bacak kaslarının patlayıcı gücünü ve kusursuz bir dengeyi gerektirir. Parkta onunla "Çukurdan atlama" oyunu oynayın. Bu hem eğlenceli bir etkinlik hem de bedenini kontrol etme alıştırmasıdır.') WHERE id = '710d761b-996a-4661-a9e2-1515ed31c7a0';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Renkleri gruplandırma". Çocuğunuz artık 4-5 farklı rengi birbirinden tamamen ayırt edebilir ve çoğunun adını bilir. Ona "Bütün mavi oyuncakları bana ver" diyerek küçük bir test yapın. Bu oyunlar görsel analiz ve hafıza becerilerini güçlendirir.') WHERE id = '6aeca11f-b490-4362-b41c-539703e28816';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topa vurma". Çocuğunuz artık koşarken önündeki topa dengesini kaybetmeden, hedefe doğru vurabilir. Bu beceri, hem hareket etmeyi hem de dikkati tek bir noktaya odaklamayı gerektirir. Onunla bahçede küçük bir "futbol" maçı yaparak çevikliğini geliştirin.') WHERE id = 'da17a594-1250-4f85-98b1-50f0b6588294';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Neden?" sorusunun başlangıcı. Çocuğunuz çevresindeki her şeyin nedenini merak etmeye başlar. "Bu neden böyle?" sorusuna basit ve dürüst cevaplar verin. Açıklamalarınız, zihninde dünyanın mantıklı bir haritasını oluşturur. Merakını asla cevapsız bırakmayın; bu, öğrenme isteğini artırır.') WHERE id = 'f3d92e61-3d30-4ede-90d4-27478dd2115f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal gelişim: "Bağımsızlık ve Sınırlar". Çocuğunuz bazen her şeyi kendisi yapmak istediğinde ve başaramadığında sert tepki verebilir. Böyle anlarda sakin kalın ve "Anlıyorum, sen bunu kendin yapmak istiyorsun" diyerek duygusunu adlandırın. Sizin anlayışınız, onun duygularını düzenleme becerisini şekillendirir.') WHERE id = '1f37d9cd-995a-4d88-97e4-8b7fdb37e3d8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık "Ben" zamirini tam olarak kavrayarak kullanır. "Ben geldim", "Ben yedim" gibi cümleler, kendisini çevresinden ayrı bir birey olarak gördüğünü gösterir. Bu bağımsız ifadelerini destekleyin ve konuşmalarını genişletin: "Evet, sen lezzetli yemeğini yedin, aferin sana!".') WHERE id = 'bf78ea68-2a1f-4194-9ef3-62146ea4799d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "İki ayakla ileriye zıplama". Çocuğunuz artık yalnızca olduğu yerde değil, biraz ileriye doğru da zıplayabilir. Bu, vücut koordinasyonunun ileri düzeyde olduğunu gösterir. Onunla parkta "Tavşanlar çayırda zıplıyor" oyunu oynayın. Bu, kaba motor becerileri için harika bir egzersizdir.') WHERE id = 'ce99df1c-1b81-4d41-b95d-9180c49c6d9f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Neden-sonuç" ilişkileri. Çocuğunuz artık olaylar arasındaki bağlantıyı anlar: "Yağmur yağıyor, ıslandım" veya "Yemek sıcak, üfle". Bu mantıklı çıkarımlarını övün. Bu, hem dil hem de soyut düşünme becerisinin ne kadar geliştiğini gösterir.') WHERE id = 'bcee9d16-cb48-4f63-9295-23b44110e7d6';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Vida ve çevirme ustalığı". Çocuğunuz şişe kapaklarını ve oyuncak vidalarını rahatlıkla açıp kapatabilir. Bu, el bileği kaslarının esnekliği için harika bir egzersizdir. Ona farklı boyutlarda güvenli kaplar vererek keşfetme merakını destekleyin.') WHERE id = 'bff29c40-0fa8-45dd-982c-f35a2f18ac52';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Rol yapma oyunlarının karmaşıklaşması". Çocuğunuz artık art arda birkaç hareketten oluşan oyunlar kuruyor: Örneğin oyuncak ayısını "yıkıyor", "kuruluyor" ve sonra "uyutuyor". Bu, hafızasındaki günlük yaşam senaryolarını nasıl sistemli bir şekilde birleştirdiğini gösterir.') WHERE id = 'd343f65f-f46a-44dd-a5fc-a51c1510c094';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız beslenme". Çocuğunuz artık çatal ve kaşık kullanma konusunda o kadar becerikli ki neredeyse hiçbir şeyi dökmüyor. Yemeğini kendi başına yemesi için ona tam anlamıyla fırsat tanıyın. Bu, doyduğunu fark etmesi ve öz güveni açısından çok önemlidir.') WHERE id = '61ba4f1e-aa7b-426a-97ad-a9a4240347af';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Parçalardan bütünü oluşturma". Çocuğunuz artık 4-6 parçalı basit yapbozları görsel olarak birleştirebiliyor. Bu, hem dikkatini toplama hem de problem çözme becerisini geliştirir. Yapamadığında ona sakin bir ses tonuyla yardımcı olun: "Bak, bu köpeğin kuyruğu, sence nerede olabilir?".') WHERE id = 'd008eb87-e4b7-4791-98e4-80774b7e5fc4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topu omuz üzerinden atma". Çocuğunuz artık topu yalnızca yere bırakmıyor, omuz üzerinden (overhand) ileri doğru atmaya çalışıyor. Bu hareket tüm vücudun koordinasyonunu gerektirir. Onunla parkta "Kim topu daha uzağa atacak?" oyunu oynayın.') WHERE id = '018d47a4-b94c-4bab-a923-24c091f9e302';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Rica ve Nezaket". Çocuğunuz artık bir şey istediğinde yalnızca parmağıyla göstermiyor, "Ver" veya "Lütfen" (kendi dilinde olsa bile) demeye çalışıyor. Sizin nazik tutumunuz onun iletişim tarzını şekillendirir. Her "teşekkür ederim" dediğinizde o da bu davranışı doğal bir şekilde benimser.') WHERE id = '11cb7320-ce82-47a0-a231-8d9923b30f4a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal hazırlık: "Korku ve Hayal Gücü". Bu yaştaki çocuklar bazen karanlıktan veya belirli seslerden korkmaya başlayabilir. Bu, hayal gücünün geliştiğinin bir işaretidir. Korkusuyla alay etmeyin; sadece yanında olun, ona sarılın ve güvende olduğunu hissettirin. Sizin desteğiniz onun duygusal dayanıklılığını artırır.') WHERE id = '4edde2f0-76ee-4d3a-a2af-2d7d71d87764';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık renkleri yalnızca tanımakla kalmıyor, onları eşleştirme konusunda da ustalaşıyor. Ona "Kırmızı çorabının eşini bul" dediğinizde bunu doğru yapıyorsa bu, görsel mantığının geliştiğini gösterir. Günlük kıyafetlerinde renkleri sık sık vurgulayın: "Bugün yeşil tişörtünü giyelim mi?". Bu, kelime dağarcığındaki sıfatları pekiştirir.') WHERE id = 'f4611a68-9983-4caf-808b-4616cf4c60d5';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Tek ayak üzerinde denge". Çocuğunuz artık birkaç saniyeliğine de olsa bir ayağını yerden kaldırıp dengesini korumaya çalışıyor. Bu, vücudun ağırlık merkezini yönetmek için gereken karmaşık bir koordinasyondur. Onunla "Leylek oyunu" oynayın. Bu oyun hem eğlenceli hem de fiziksel gelişim açısından çok faydalıdır.') WHERE id = 'c7634c82-b4b5-450c-9811-7e5cbdc218af';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Zaman kavramının ilk izleri". Çocuğunuz "şimdi" ve "sonra" gibi sözcükler arasındaki farkı anlamaya başlar. Ona "Önce yemeğimizi yiyelim, sonra parka gidelim" dediğinizde bekleyebiliyorsa bu büyük bir ilerlemedir. Sabretme alışkanlığının gelişmesi için zaman sıralamasını eylemlerinizle açıklamaya devam edin.') WHERE id = '2c927604-0f3e-4615-94c5-86dc48b7896a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Hassas birleştirme". Çocuğunuz artık küçük yapı oyuncaklarının parçalarını veya küpleri birbirine daha özenli bir şekilde takar. Bu, hem dikkatini yoğunlaştırmasını hem de parmak uçlarını hassas biçimde kullanmasını gerektirir. Onun "mühendislik" çabalarını alkışlayın ve "Bu neyin evi?" diye sorun.') WHERE id = '92d8aec4-818c-4b3a-abd3-dd724c129df5';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız su içme". Çocuğunuz artık açık bardaktan suyu neredeyse hiç dökmeden, kendinden emin bir şekilde içer. Bu, dudak ve çene kaslarının konuşmaya ne kadar hazır olduğunun bir göstergesidir. Bu beceride tamamen ustalaşabilmesi için ona çocuklara uygun boyutta, rahatça tutabileceği bardaklar vermeye devam edin.') WHERE id = '659e2094-8141-4a5a-bed6-c6f715c75799';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışlarda "Mizah ve Şakalar". Çocuğunuz bilerek "yanlış" bir şey yapıp (örneğin şapkasını eline takıp) size bakabilir ve gülebilir. Bu, şaka anlayışının ve sosyal etkileşim becerisinin geliştiğini gösterir. Onun bu "oyununa" coşkuyla katılın. Birlikte gülmek aranızdaki duygusal bağı daha da güçlendirir.') WHERE id = 'c1045492-8f8e-491f-a86f-8a5ceb126f15';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Yükseklik ve Mesafe". Çocuğunuz artık merdivenden veya koltuktan inerken mesafeyi daha iyi hesaplar. Ona her zaman dikkatli olmasını ve güvenli inme yöntemlerini (geri geri inmeyi) hatırlatın. Bu, beden güvenliği kurallarını öğrenmesi açısından önemli bir aşamadır.') WHERE id = 'c7630ee3-1695-4062-9e13-7540975aa465';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Geri geri yürüme ustalığı". Çocuğunuz artık arkasına bakmadan geriye doğru birkaç adım atabilir. Bu, bedeninin uzaydaki konumunu hissetmesi (propriyoseptif duyu) açısından önemlidir. Ona "Yengeç gibi yürüyelim" diyerek bu hareketi bir oyuna dönüştürün. Sizinle birlikte hareket etmek onun için dünyanın en büyük eğlencesidir.') WHERE id = 'e1577858-a1db-40b1-bd39-0ce8d678ff7a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "İsim-Zamir ilişkisi". Çocuğunuz artık kendisinden adıyla söz etmek yerine "Ben" demeye tamamen geçer. Ona bir şey sorduğunuzda "Ben" veya "Benim" diyorsa bu, benlik bilincinin iyice yerleştiğinin bir göstergesidir. Onunla bu konuda diyaloglar kurun: "Bu kimin topu? Benim!".') WHERE id = 'a37651fe-7cc3-4f59-bbce-f7763c1637a8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal sınırlar: Çocuğunuz artık "Olmaz" sözüne tepki verir, ancak bazen hâlâ tepkinizi sınamak için kuralları ihlal eder. Sakin ama kararlı kalmak en önemli koşuldur. Bir şeye "hayır" dediyseniz bunu her seferinde aynı şekilde tekrarlayın. Kuralların tutarlı olması, çocukta iç düzen ve güvenlik duygusu oluşturur.') WHERE id = '8f5c35ba-05d9-40e2-a687-7bfe8146f1ee';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '26. aya adım atıyoruz! Çocuğunuz artık birbirinden farklı iki görevi art arda yerine getirmekte ustadır. Örneğin: "Oyuncağı al ve rafa koy". Bu, hem hafızasının hem de dili anlama becerisinin yeni bir düzeye ulaştığını gösterir. Gün içinde ona bu tür küçük "görevler" vererek kendisini faydalı hissetmesini sağlayın.') WHERE id = '86c6ccb4-326d-41d5-81c5-ea4c8d0faf13';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Hızlı manevra". Çocuğunuz artık koşarken aniden yön değiştirebilir veya engellerin etrafından çevik bir şekilde dolaşabilir. Bu, hem kas gücünün hem de hızlı karar verme becerisinin göstergesidir. Parkta onunla "kovalamaca" oynayarak beden kontrolünü geliştirin.') WHERE id = 'eb8969ec-bb8d-48c5-8dfb-f818249bf8e8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Neden arayışı". Çocuğunuz henüz tam olarak "Neden?" demese de olayların nedenini davranışlarıyla sorgular. Ona şöyle açıklayın: "Montumuzu giyiyoruz, çünkü dışarıda rüzgâr var". Olaylar arasındaki mantıksal bağlantıyı ona göstermek, gelecekte mantık yürütebilmesi için en güçlü temellerden biridir.') WHERE id = 'f63d183c-6b97-43da-8c82-1a87c629cc0d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Kapak ve vida çevirme ustalığı". Çocuğunuz artık şişe kapaklarını veya oyuncak vidalarını güvenle açıp kapatabilir. Bu hareket, el bileği kaslarının esnekliği için mükemmel bir egzersizdir. Ona farklı boyutlarda güvenli kaplar vererek mekanik keşif merakını destekleyin.') WHERE id = '583cd090-6bc1-4438-afd7-8703fd352e08';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız seçim" ve irade. Çocuğunuz artık ne giyeceği veya hangi kaptan yemek yiyeceği konusunda net bir fikre sahiptir. Ona "Bugün mavi gömleği mi, yoksa yeşil olanı mı giymek istersin?" gibi seçenekler sunmak, kendisini bağımsız bir birey olarak hissetmesine yardımcı olur ve inatlaşma krizlerini en aza indirir.') WHERE id = '5377658a-72e7-437d-b697-abdb7c76bfcd';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "İş birliği". Çocuğunuz artık size yardım etmekten büyük keyif alır. "Gel, alışveriş poşetinden ekmeği çıkaralım" dediğinizde size katılması, aile içindeki rolünü kavradığını gösterir. Bu, hem sorumluluk duygusunu geliştirir hem de aranızdaki bağı güçlendirir.') WHERE id = '57201085-ec92-4795-8598-90d9a04fb33a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Kategoriler". Çocuğunuz artık aynı türdeki nesneleri (örneğin, tüm hayvanları bir yere, tüm arabaları başka bir yere) gruplayabilir. Ona "Burada hangi oyuncak farklı?" gibi sorular sorarak görsel mantık becerisini değerlendirin. Kategorilerle düşünmek, bilişsel gelişimini yeni bir düzeye taşır.') WHERE id = 'ffdc805c-2aad-4971-afc7-9cb3c0053b5c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "İki ayakla zıplama ustalığı". Çocuğunuz artık bulunduğu yerde daha yükseğe veya biraz ileriye doğru güvenle zıplayabilir. Bu hareket, bacak kaslarının güçlendiğini gösterir. Onunla "Çayırdaki tavşanlar" oyununu oynayın; bu oyun hem eğlenceli hem de kaba motor becerileri için faydalıdır.') WHERE id = 'dcd7700f-4c1a-40e7-9469-0739827e396d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Hikâye anlatma girişimleri". Çocuğunuz gün içinde gördüğü ilginç bir şeyi (örneğin, "Parkta büyük bir köpek gördüm") size anlatmak için can atar. Hikâyesini sonuna kadar dinleyin ve sorularla genişletin: "Köpek ne yapıyordu?". Bu, hem hafızasını hem de kendini ifade etme becerisini güçlendirir.') WHERE id = 'e7fba00d-ba92-45d4-9c39-8a2e6decdc8c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal gelişimde "Öz denetim". Çocuğunuz öfkelendiğinde size bakıp tepkinizi bekleyebilir. Böyle anlarda sakin kalın ve "Şu anda kızgınsın, çünkü küpler devrildi, seni anlıyorum" diyerek duygusunu adlandırın. Sizin sakinliğiniz, onun için en iyi duygu düzenleme dersidir. Siz harika bir annesiniz!') WHERE id = '4a2f0d04-3378-4296-a224-feb8d41e9254';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık renkleri yalnızca ayırt etmekle kalmaz, birçoğunun adını da doğru telaffuz eder. Ona "Mavi arabayı getir" dediğinizde hata yapmıyorsa bu, görsel ve sözel hafızasının birlikte çalıştığını gösterir. Günlük yürüyüşlerinizde "Yeşil yaprak", "Sarı güneş" gibi betimlemelerle onun dünyasını renklendirmeye devam edin.') WHERE id = '57505a63-7f8c-48f6-bce2-90daca2c8189';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel gelişimde "Merdiven bağımsızlığı". Çocuğunuz artık tek elinden tutulduğunda, ayaklarını sırayla değiştirerek her basamağa bir ayağını koyup merdiven çıkmaya çalışır. Bu, kaba motor gelişiminde önemli bir başarıdır. Her zaman yakınında olup güvenliğini sağlayın, ancak kendi başına adım atabilmesi için ona güven verin.') WHERE id = 'e9641593-3c91-4cf3-a6cc-b86c93ef50be';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Konum bildiren sözcükler". Çocuğunuz "üstünde", "altında", "arkasında" gibi kavramları artık hareketleriyle gösterebilir. Ona "Topu sandalyenin altına koy" diyerek küçük bir oyun oynayın. Bu görevler hem dili anlama hem de mekânsal yönelim becerisini hızla geliştirir.') WHERE id = '2ff11d89-9e65-4caa-b39f-98e5298d4503';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Sıralama ve Mantık". Çocuğunuz artık nesneleri yalnızca renklerine göre değil, boyutlarına göre de (büyük-küçük) ayırt etmeye başlar. Ona farklı boyutlarda kaplar verin ve bunları iç içe yerleştirmesini isteyin. Bu, gelecekteki matematiksel düşünme becerisinin temelidir.') WHERE id = 'cd04a6bc-1fab-4d68-920a-3fa77ebf8503';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Kendim giyiniyorum" aşaması daha da gelişiyor. Çocuğunuz artık fermuarı çekmeye (siz başlattıktan sonra) veya büyük düğmeleri açmaya çalışır. Bu süreçte ona engel olmayın ve onu acele ettirmeyin. Bir şeyi kendi başına yapabildiğini görmek, onun için en büyük özgüven kaynağıdır. Küçük başarılarında onu mutlaka teşvik edin.') WHERE id = '701a4eec-68f9-49ca-9e96-f1cb4b81484e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışlarında "Empati" artar. Çocuğunuz sizin veya başka bir çocuğun üzüldüğünü gördüğünde yanınıza gelip oyuncağını verebilir ya da size sarılabilir. Bu, duygusal zekâsının (EQ) güzel bir göstergesidir. Bu duyarlı davranışını "Bana destek olduğun için çok teşekkür ederim" diyerek takdir edin.') WHERE id = 'db3deaea-d927-47d7-b65e-09bbf47b377f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Şekil ve Boyut". Çocuğunuz artık aynı şeklin (örneğin dairenin) büyük ve küçük çeşitlerini ayırt edebilir. Ona farklı boyutlardaki kapları iç içe yerleştirmeyi gösterin. Bu etkinlik, gelecekteki matematiksel düşünme becerisinin temelini oluşturan "sıralama" becerisini geliştirir.') WHERE id = '1317ee1d-1c19-4d58-ab70-d9a1fa691c6f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topa vurma ve hedef". Çocuğunuz artık topa rastgele vurmakla kalmaz, onu belirli bir yöne göndermeye çalışır. Bu, görsel dikkat ile hareket koordinasyonunun birleşimidir. Evde veya parkta onunla "küçük bir kale" oluşturup topu kaleye gönderme oyunu oynayın. Bu oyun, bacak kaslarını güçlendirir ve isabetli hareket etme becerisini artırır.') WHERE id = 'c1e87167-2300-4b17-9def-ab985555b55e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Hikâye anlatma girişimleri". Çocuğunuz gün içinde gördüğü ilginç bir şeyi (örneğin, "Büyük bir köpek gördüm") size anlatmak için sabırsızlanır. Hikâyesini sonuna kadar dinleyin ve sorularla genişletin: "Köpek ne yapıyordu?". Bu, hem hafızasını hem de kendini ifade etme becerisini güçlendirir.') WHERE id = '404203bc-920b-47d3-b584-2989b01e93ee';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal sınırlar: Çocuğunuz artık "Ben istemiyorum" diyerek iradesini güçlü bir şekilde ortaya koyabilir. Böyle anlarda onunla inatlaşmak yerine seçenekler sunarak dikkatini başka yöne çekin. Sabrınız ve tutarlı kurallarınız, çocuğunuzda güven duygusu oluşturur. Harika bir iş çıkarıyorsunuz!') WHERE id = '17f5e755-5dec-4458-9be1-0d08e0586eaf';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık "Ben" zamirini anlamını tam olarak kavrayarak kullanır. "Ben geldim", "Ben yedim" gibi cümleler, kendisini çevresinden ayrı bir birey olarak gördüğünü gösterir. Bu bağımsız ifadelerini destekleyin ve konuşmalarını genişletin: "Evet, lezzetli yemeğini yedin, aferin sana!".') WHERE id = '12f036fb-3726-4e17-bff9-217ad09dba7b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Kaldırım kenarında yürüme". Çocuğunuz artık elinden tuttuğunuzda alçak kaldırım kenarlarında yürümeye ilgi gösterir. Bu, gelişmiş denge duyusunu destekler. Güvenli yerlerde bu ilgisini teşvik edin; çünkü bu beceri, gelecekte daha karmaşık fiziksel hareketler yapabilmesinin temelini oluşturur.') WHERE id = '292c2a9d-2b19-4e22-9095-add20bbbeaf5';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Üç kelimeli cümlelerin artması". Çocuğunuz artık "Anne, su ver", "Baba, parka git" gibi daha karmaşık cümleler kurar. Artık ihtiyaçlarını eksiksiz bir şekilde ifade edebilir. Cümlelerini onaylayıp biraz daha genişletin: "Evet, şimdi gel su içelim, sonra parka gideriz". Bu, dil bilgisi algısını geliştirir.') WHERE id = '7132fa94-7590-4b27-b006-e5936aaf0907';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Yapboz ustalığı" gelişir. Çocuğunuz artık 6-8 parçalı basit yapbozları tek başına tamamlayabilir. Bu, hem görsel analiz hem de parmak kaslarının hassas kullanımı açısından önemlidir. Karmaşık görevlere ilgisinin artması için resmi her tamamladığında sevincini paylaşın.') WHERE id = 'd4e00b50-79ce-485c-9a88-f514c156f1f6';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Ben kendim topluyorum." Oyuncakları yerine kaldırmak artık onun için yalnızca bir görev değil, bir sorumluluktur. Ona "Haydi, arabaları yatağına koyalım" dediğinizde size yardım ediyorsa bu, disiplinin temelidir. Bu alışkanlık, gelecekte kendi düzenini sağlaması açısından çok önemlidir.') WHERE id = '03327c5a-8698-4e34-8b71-2d0914f0f88b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Sıra beklemek". Çocuk artık parkta salıncağa binmek veya bir oyuncakla oynamak için biraz beklemesi gerektiğini anlar. "Şimdi sıra bende, sonra sende" oyunlarıyla ona sabretmeyi öğretin. Bu beceri, gelecekte anaokulu ve okul ortamına uyum sağlaması için en önemli sosyal temellerden biridir.') WHERE id = '3ea5aca0-7734-4b06-864f-00aa21361675';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Aynı ve Farklı". Çocuk artık aynı tür nesneleri (örneğin tüm hayvanları bir yere, tüm arabaları başka bir yere) gruplayabilir. Ona "Burada hangi oyuncak farklı?" gibi sorular sorarak görsel mantığını değerlendirin. Kategorilerle düşünmek, bilişsel gelişimini yeni bir düzeye taşır.') WHERE id = '09d14134-1ab9-423c-86bd-46c0a52d2f86';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topa vurma ve koşma". Çocuk artık koşarken önündeki topa dengesini kaybetmeden vurabilir. Bu hem eğlenceli hem de fiziksel gelişim için çok faydalıdır. Onunla evde veya bahçede hafif bir topla oynayarak hem hareket hızını hem de isabet yeteneğini geliştirin.') WHERE id = '39fb4064-3e7d-4aa6-b4d5-c75b564c92cc';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Anıları ifade etme". Çocuk, gün içinde yaşanan basit bir olayı (örneğin, "Parkta köpek gördüm") hatırlayıp size anlatabilir. Anlattıklarını dikkatle dinleyin ve "Sonra ne oldu?" diye sorarak olayları sırasıyla aktarmasına yardımcı olun. Bu, hem hafızasını hem de kendini ifade etme becerisini güçlendirir.') WHERE id = '109cbe57-dd82-4d85-b381-3ebd329772ab';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal gelişim: "Kendini kontrol etme çabaları". Çocuk öfkelendiğinde size bakabilir ve tepkinizi bekleyebilir. Böyle anlarda sakin kalın ve "Oyuncak düzelmediği için şimdi öfkelendin" diyerek hissettiği duyguyu adlandırın. Sizin sakinliğiniz, onun için en iyi duygu düzenleme dersidir. Siz harika bir annesiniz!') WHERE id = 'cbb6c494-b75d-458c-b798-2ddf1bf9e334';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '27. aya hoş geldiniz! Çocuk artık "iki aşamalı" yönergeleri hatırlama becerisini tamamen kazanır. "Oyuncağını al ve kutuya koy" dediğinizde her iki hareketi de sırayla yapar. Bu, beynin prefrontal korteksinin geliştiğini gösterir. Gün boyunca ona küçük ve mantıklı görevler vererek bu becerisini geliştirin.') WHERE id = '0b872b3f-49b7-446a-bc7c-dfae010fe461';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Merdiven inme ustalığı". Çocuk artık elinden tuttuğunuzda merdivenleri daha güvenli ve her basamağa tek tek basarak inmeye çalışır. Merdiven inmek, çıkmaktan daha zordur çünkü daha fazla denge gerektirir. Her zaman yakınında durarak güvenliğini sağlayın ve başarısını alkışlayın.') WHERE id = '912ef746-569e-455d-af72-84d6cc3f170e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Sıfat ve Zarfların birlikte kullanımı". Çocuğunuz artık yalnızca "araba" değil, "hızlı kırmızı araba" diyebiliyor. Dünyayı anlatmak için daha fazla ayrıntı kullanıyor. Onunla konuşurken nesnelerin özelliklerini vurgulayın: "Bu ağır bir taş", "Bu yumuşak bir yastık". Bu, kelime dağarcığını nitelik açısından zenginleştirir.') WHERE id = 'c940fb90-c1d6-4fa5-8baf-334e41b324f8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Sanat ve koordinasyon". Çocuğunuz artık kağıt üzerinde daha amaçlı daireler ya da gelişigüzel ama belirgin çizgiler çizebiliyor. Ona renkli kalemler ve büyük kağıtlar vererek özgürce üretebileceği bir alan oluşturun. Bu, gelecekte yazı yazmak için gerekli olan kas hafızasını geliştirir.') WHERE id = 'c40de8f9-d507-4cfb-810d-f904e8901ddd';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız giyinme denemeleri". Çocuğunuz artık çorabını çıkarmanın yanı sıra şapkasını takmak veya ayakkabılarını giymek için de ısrar ediyor. Bu süreçte ona birkaç dakika daha fazla zaman tanıyın. Acele ettirmeden kendi başına bir şeyler yapabilmesine fırsat vermeniz, öz güvenini ve bağımsızlık duygusunu güçlendirir.') WHERE id = 'c38e076c-fc5e-4ef7-ba82-49913f3b0c34';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Sembolik bakım". Çocuğunuz oyuncak ayısına "su içirebilir", üstünü battaniyeyle örtebilir veya ağladığında onu okşayabilir. Bu, duygusal zekasının ve başkalarının hislerini anlama becerisinin geliştiğini gösterir. Bu şefkatli davranışlarını övmeyi unutmayın.') WHERE id = 'cbccdb44-553a-4ef8-8729-9f35675d89bf';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Saymanın temelleri". Çocuğunuz henüz sayıları sırayla sayamasa da "bir" ile "iki" arasındaki miktar farkını görsel olarak anlamaya başlar. Ona iki elma verip "Biri senin, biri benim" diyerek paylaşmayı ve saymayı birlikte gösterin. Bu, matematiksel düşünme becerisinin en erken temelidir.') WHERE id = '1953c2df-b74a-440f-aeda-02c40c3b1d9f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "İki ayakla ileri atlama". Çocuğunuz artık yalnızca olduğu yerde değil, biraz ileriye doğru da atlayabiliyor. Bu, bacak kaslarının gücünü ve vücut koordinasyonunu gerektirir. Onunla "Tavşanlar çayırda zıplıyor" oyunu oynayın. Bu hem eğlenceli hem de kaba motor becerileri için harika bir egzersizdir.') WHERE id = '9999afba-b8a0-474d-b26c-6136ec804e12';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Soru-cevap diyaloğu". Çocuğunuz artık size basit sorular sorabilir: "Baba nerede?", "Bu nedir?". Cevap verirken daha uzun cümleler kurun: "Baba işe gitti, akşam gelecek". Ayrıntılı açıklamalarınız, çocuğunuzun zihninde olaylar arasındaki mantıksal bağlantıları güçlendirir.') WHERE id = 'e0d072d6-3ce1-4139-b80e-a94b53d2fc54';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Tebrikler, 800 günü tamamladık! Çocuğunuz 2 yaşını çoktan geride bıraktı ve her gün yeni bir şey keşfediyor. Artık basit kuralları anlıyor, duygularını açıkça gösteriyor ve sizinle tam anlamıyla iletişim kuruyor. Bu günü onunla birlikte en sevdiği parkta geçirerek kutlayın. Siz harika bir annesiniz!') WHERE id = '1df3c116-f7da-4df5-8d7e-4570b51bb9eb';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '27. ayın ortalarına doğru ilerliyoruz. Çocuk artık "önce" ve "sonra" sıralamasını daha iyi kavrıyor. "Kıyafetlerini giy, sonra dışarı çıkalım" dediğinizde, ikinci eylemin bir ödül olduğunu anlıyor. Bunlar, çocukta sabır ve planlama becerisinin ilk tohumlarıdır. Günlük rutinler sırasında bu sıralamaları ona sık sık hatırlatın.') WHERE id = 'bf2725f4-a91c-46df-b906-cbe0eca9ab09';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel gelişimde "Tırmanma becerisi". Çocuk artık parktaki küçük merdivenlere veya evdeki güvenli yüksekliklere daha emin bir şekilde tırmanıyor. Bu, hem kol hem de bacak kaslarının eş zamanlı çalışmasını gerektirir. Her zaman yakınında olun, ancak kendi gücünü denemesine de fırsat verin.') WHERE id = '03ce58c6-bf39-4cb2-86c0-fb921289cb85';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Mantıksal bağlantılar". Çocuk artık iki durumu tek bir cümlede birleştiriyor: "Hava soğuk, montunu giy". Bu, onun sadece taklit etmediğini, aynı zamanda düşündüğünü de gösterir. Bu mantıklı çıkarımlarını "Evet, haklısın" diyerek onaylayın ki kendi düşüncelerini ifade etmeye daha çok heveslensin.') WHERE id = '70d20b90-08cb-4a3d-b635-39b5e961b0df';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Kağıtla çalışma". Çocuk artık kağıdı katlamaya veya basit şekilde kesmeye (çocuklar için büyük makaslarla ve gözetim altında) ilgi gösterebilir. Bu hareketler, parmak kaslarının kontrolünü yeni bir seviyeye taşır. Renkli kağıtlarla çalışabilmesi için ona uygun bir ortam hazırlayın.') WHERE id = '1867a29d-cdef-4c25-9fb4-31fe661ffbe5';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Rol yapma oyunlarının gelişmesi". Çocuk artık "doktor", "aşçı" veya "şoför" rolüne giriyor. Bu oyunlar sayesinde çevresindeki insanların görevlerini öğreniyor ve empati kuruyor. Oyunlarına katılın ve size verdiği "role" uygun davranın.') WHERE id = '09d954dd-f762-40e1-8030-11d38ef87b47';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız temizlik" alışkanlığı. Çocuk artık ellerini yıkarken sabunlama ve durulama işlemlerini neredeyse tek başına yapabiliyor. Hijyen alışkanlıklarının bu yaşta pekişmesi çok önemlidir. Bu süreçten keyif alması için ona boyuna uygun bir basamaklı tabure (step stool) sağlayın.') WHERE id = '8f3c97e4-28e2-4575-994c-03b54f2a86ed';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Farklı olanı bul". Çocuk artık bir grup nesne arasından farklı olanı (örneğin, arabaların arasındaki elmayı) görsel olarak ayırt edebiliyor. Bu, analiz yeteneğini geliştirir. Evde onun için basit "Hangisi farklı?" oyunları hazırlayın. Bu, gelecekteki matematiksel ve mantıksal görevler için harika bir hazırlıktır.') WHERE id = '0c2d9534-6a6b-4045-844a-9433e0a69d75';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Tek ayak üzerinde durma denemeleri". Çocuk artık birkaç saniyeliğine de olsa bir ayağını yerden kaldırıp dengesini korumaya çalışıyor. Bu, vücudun ağırlık merkezini tanıması açısından önemlidir. Onunla "Leylek oyunu" oynayın ve kimin daha uzun süre durabildiğine bakın.') WHERE id = '5d944b43-095b-4d92-b030-b834a56949f2';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Duygu ifadeleri". Çocuk artık üzgün, neşeli veya korkmuş olduğunu sözcüklerle ifade edebiliyor: "Korktum" veya "Neşeliyim". Duyguları adlandırmak, çocukta duygusal zekânın temelini oluşturur. Duygusunu dile getirdiğinde onu dinleyin ve "Evet, seni anlıyorum" diyerek hislerini onaylayın.') WHERE id = 'cb48e516-3844-4090-848b-2afd50d005de';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Hayal gücünün etkisi: "Görünmez arkadaşlar ve nesneler". Çocuk bir sopayı "at" olarak hayal edip dörtnala koşturabilir. Bu, sembolik düşüncenin zirvesidir – bir nesnenin başka bir şeyi temsil ettiğini anlamaktır. Bu beceri, ileride okuma ve matematik (sembolleri anlama) için çok önemlidir.') WHERE id = '76d9591a-d7e3-4913-96a8-5d2c420ccc81';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '27. ayın son on günlük dönemine başlıyoruz! Çocuk artık renkleri yalnızca tanımakla kalmıyor, onları eşleştirme konusunda da ustalaşıyor. Ona "Kırmızı çorabının eşini bul" dediğinizde bunu doğru yapıyorsa, bu görsel mantığının geliştiğini gösterir. Günlük kıyafetlerinde renkleri sık sık vurgulayın.') WHERE id = '5063e9dc-6139-4c88-93fd-950678f58bde';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Merdiven bağımsızlığı". Çocuk artık yalnızca bir elinden tutulduğunda, her basamağa sırayla bir ayağını koyarak merdivenleri çıkmayı deniyor. Bu, kaba motor gelişiminde önemli bir başarıdır. Her zaman yakınında durarak güvenliğini sağlayın, ancak bağımsız adım atabilmesi için ona güven verin.') WHERE id = 'd4f943d2-bf71-4b16-b7d0-f1be4b723a37';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Zaman zarflarının ilk izleri". Çocuk "şimdi", "sonra", "birazdan" gibi sözcükler arasındaki farkı daha iyi anlamaya başlıyor. Ona "Önce yemeğimizi yiyelim, sonra parka gidelim" dediğinizde bekleyebiliyorsa, bu iradesinin güçlendiğini gösterir. Zaman sıralamasını davranışlarınızla açıklamaya devam edin.') WHERE id = 'ad12a2ff-a0f6-446e-a287-18ac0e3ed236';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Yapboz ustalığı". Çocuk artık 6-9 parçalı basit yapbozları tek başına tamamlayabiliyor. Resimleri görsel olarak birleştirmek hem dikkatini toplamasına hem de problem çözme becerisinin gelişmesine yardımcı olur. Yapamadığında ona sakin bir ses tonuyla ipuçları verin.') WHERE id = 'ca532b10-de2c-4db5-9614-e001b1908ea1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız seçim" zirvede. Çocuk artık ne giyeceği veya hangi oyuncakla oynayacağı konusunda net bir fikre sahip. Ona "Bugün mavi şapkanı mı, yoksa yeşil şapkanı mı takacaksın?" gibi seçenekler sunmak, kendisini bağımsız bir birey olarak hissetmesine yardımcı olur ve inatlaşma krizlerini en aza indirir.') WHERE id = 'fb9fc561-26c7-41b4-bbe1-31eada18c85f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Sırasını beklemek". Çocuk artık parkta salıncağa binmek için biraz beklemesi gerektiğini anlıyor. "Şimdi onun sırası, sonra senin" oyunlarıyla ona sabretmeyi öğretin. Bu beceri, sosyal uyumun en önemli temellerinden biridir.') WHERE id = '9df47b2e-3d86-40c8-a4bd-0d995655814b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Yükseklik ve Mesafe". Çocuk artık merdivenden veya koltuktan inerken mesafeyi daha iyi hesaplıyor. Ona her zaman dikkatli olmasını ve güvenli iniş yöntemlerini (geri geri) hatırlatın. Bu, beden güvenliği kurallarını öğrenmesi açısından önemli bir aşamadır.') WHERE id = '0f7477b8-a1ff-4761-b386-ffe1e44a9a7a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topa vurma ve hedef". Çocuk artık topa sadece vurmuyor, onu belirli bir yöne göndermeye çalışıyor. Bu, görsel dikkat ile hareket koordinasyonunun birleşimidir. Evde veya parkta birlikte "küçük bir kale" oluşturup topu kaleye atma oyunu oynayın.') WHERE id = '050cfb5f-db53-4311-8b9f-fbb09f54e915';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Hikâye anlatma girişimleri". Çocuk, gün içinde gördüğü ilginç bir şeyi (örneğin, "Büyük bir köpek gördüm") size anlatmak için can atıyor. Hikâyesini sonuna kadar dinleyin ve sorularla genişletin: "Köpek ne renkti?". Bu, hem hafızasını hem de kendini ifade etme becerisini güçlendirir.') WHERE id = 'd7af8a5b-1016-4dc8-921f-52af71c3d954';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal sınırlar: Çocuk artık "Ben istemiyorum" diyerek iradesini güçlü bir şekilde ortaya koyabilir. Böyle anlarda onunla inatlaşmak yerine seçenekler sunarak dikkatini başka yöne çekin. Sabrınız ve tutarlı kurallarınız, çocukta güven duygusu oluşturur. Harika bir iş çıkarıyorsunuz!') WHERE id = '80c062ac-b271-45ec-b67c-016fb884ca5b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '28. aya adım atıyoruz! Çocuk artık "iki aşamalı" yönergeleri kolaylıkla yerine getiriyor. Örneğin: "Oyuncağını al ve rafa koy". Bu, hem hafızasının hem de dili anlama becerisinin yeni bir düzeye ulaştığını gösterir. Gün içinde ona küçük ve mantıklı "görevler" vererek sorumluluk duygusunun gelişmesini destekleyin.') WHERE id = 'a1060bb5-066a-438b-aafd-d9c5d706c7bc';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Merdiven inme becerisi". Çocuk artık elinden tuttuğunuzda, her basamağa bir ayağını koyarak merdivenleri daha güvenli bir şekilde inmeye çalışıyor. İnmek, çıkmaktan daha zordur çünkü daha fazla denge gerektirir. Her zaman yakınında olup güvenliğini sağlayın ve başarısını alkışlayın.') WHERE id = '05b34d22-95f5-4000-aee3-08f747372e4d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Sıfat ve Zarfların birlikte kullanımı". Çocuk artık yalnızca "araba" değil, "hızlı kırmızı araba" diyebiliyor. Dünyayı anlatmak için daha fazla ayrıntı kullanıyor. Onunla konuşurken nesnelerin özelliklerini vurgulayın: "Bu ağır bir taş", "Bu yumuşak bir yastık". Bu, kelime dağarcığını nitelik bakımından zenginleştirir.') WHERE id = '5838f818-d4e0-42c7-ba01-7e6420078ed2';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Dizme ve İnşa Etme". Çocuk artık küplerden yalnızca kule değil, "çit", "tren" veya "ev" gibi amaca yönelik şekiller yapıyor. Bu, görsel-mekânsal düşünme becerisi ile hayal gücünün birleşimidir. Yaptıkları hakkında sorular sorun: "Burada kim yaşıyor?".') WHERE id = '46a64e62-d979-410f-9a15-a2c7bbeb1ba9';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız seçim" ve irade. Çocuğunuz artık ne giyeceği veya hangi tabaktan yemek yiyeceği konusunda net bir fikre sahiptir. Ona "Bugün mavi tişörtü mü, yoksa yeşil olanı mı giymek istersin?" gibi seçenekler sunmanız, kendisini bağımsız bir birey olarak hissetmesine yardımcı olur ve inatlaşma krizlerini en aza indirir.') WHERE id = 'f2f6cbfc-bdac-4534-9233-ecd8a693e212';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Sembolik bakım". Çocuğunuz oyuncak ayısına "su içirebilir", üzerini battaniyeyle örtebilir veya onu "tedavi edebilir". Bu, duygusal zekâsının ve başkalarının duygularını anlama becerisinin geliştiğini gösterir. Bu şefkatli davranışlarını mutlaka övün.') WHERE id = '8ddc104a-ab8a-4e5a-943d-543dc807df66';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Farklı olanı bul". Çocuğunuz artık bir grup nesnenin arasından farklı olanı (örneğin, arabaların arasındaki elmayı) görsel olarak ayırt edebilir. Bu, analiz becerisini geliştirir. Evde onun için basit "Hangisi farklı?" oyunları hazırlayın. Bu, gelecekteki mantık soruları için harika bir hazırlıktır.') WHERE id = 'a2b9980c-2bf2-401b-8655-ae5a31b2d842';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "İki ayakla ileri zıplama". Çocuğunuz artık yalnızca olduğu yerde değil, biraz ileriye doğru da zıplayabilir. Bu hareket, bacak kaslarının güçlü olmasını ve vücut koordinasyonunu gerektirir. Onunla "Tavşanlar çayırda zıplıyor" oyunu oynayın. Bu, hem eğlenceli hem de kaba motor becerileri için harika bir egzersizdir.') WHERE id = '3b71e4fe-1f75-478c-bb70-76e4d5347b3d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Soru-cevap diyaloğu". Çocuğunuz artık size "Baba nerede?", "Bu nedir?" gibi basit sorular sorabilir. Yanıt verirken daha uzun cümleler kurun: "Baba işe gitti, akşam gelecek". Ayrıntılı açıklamalarınız, olaylar arasındaki mantıksal bağlantıların zihninde güçlenmesini sağlar.') WHERE id = '12f65b1a-8cde-4d4d-842d-5197bc6d6352';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Hayal gücünün gücü: "Rollerin değişmesi". Çocuğunuz sizi taklit ederek "anne" olabilir veya oyuncaklarını "işe götürebilir". Bu, hem hafızasının gücünü hem de olaylar arasındaki mantıksal bağlantıları ne kadar dikkatle gözlemlediğini gösterir. Siz harika bir annesiniz!') WHERE id = '1d0c6c5d-a275-43bf-bb3b-a961c2f6805e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık renkleri yalnızca tanımakla kalmaz, en az 3-4 temel rengin (kırmızı, mavi, yeşil, sarı) adını da söylemeye başlar. Ona "Bu ne renk?" diye sorduğunuzda doğru yanıt alma olasılığınız yüksektir. Gezerken arabaların veya çiçeklerin renklerini sorarak bu bilgisini pekiştirin.') WHERE id = '44e5c106-bbab-44d6-a4ac-bc4a1418e1eb';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Tek ayak üzerinde denge". Çocuğunuz artık birkaç saniyeliğine de olsa bir ayağını yerden kaldırarak dengesini korumaya çalışır. Bu, vücudun ağırlık merkezini kontrol etmeyi gerektiren karmaşık bir koordinasyon becerisidir. Onunla "Leylek oyunu" oynayın. Bu oyun hem eğlenceli hem de fiziksel gelişim için çok faydalıdır.') WHERE id = 'fbfbb0b9-9b09-4a23-9066-c80337eab4d6';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Zaman kavramının ilk izleri". Çocuk, "dün" ve "yarın" kelimelerini henüz tam olarak anlamasa da "şimdi", "sonra", "birazdan" gibi kelimeler arasındaki farkı kavrar. Ona "Önce ellerimizi yıkayalım, sonra yemek yiyelim" dediğinizde bekleyebiliyorsa bu, iradesinin güçlendiğini gösterir. Zaman sıralamasını davranışlarınızla açıklamaya devam edin.') WHERE id = 'a4ffacc2-0d5e-4231-a5d0-f90a33b4d6f5';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Daire ve Çizgi ustalığı". Çocuk artık kâğıt üzerinde daha bilinçli daireler veya gelişigüzel ama kararlı düz çizgiler çizer. Ona renkli kalemler ve büyük kâğıtlar vererek "ilk resimlerini" çizmesine fırsat tanıyın. Bu, gelecekteki yazma becerileri için en önemli egzersizdir.') WHERE id = 'efd8c509-5660-43d7-a555-e496a390e478';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız giyinme" ısrarı. Çocuk artık çorabını çıkarmanın yanı sıra şapkasını başına takmak veya kolay giyilen ayakkabılarını ayağına geçirmek için de ısrar eder. Bu süreçte ona birkaç dakika daha fazla zaman tanıyın. Acele ettirmeden kendi başına bir şeyler yapmasına fırsat vermek, özgüvenini ve bireysel bağımsızlık duygusunu geliştirir.') WHERE id = 'ea6058fd-22cb-454f-b6df-36b6c6f564fd';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışlarda "Mizah ve Şaka". Çocuk bilerek bir şeyi "yanlış" yapıp (örneğin şapkasını eline takıp) size bakabilir ve gülebilir. Bu, şaka anlayışının ve sosyal etkileşim becerisinin geliştiğini gösterir. Onun bu "oyununa" coşkuyla katılın. Birlikte gülmek, aranızdaki duygusal bağı daha da güçlendirir.') WHERE id = '90539d1c-30bc-43ec-8cb5-e89edef1568e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Yükseklik ve Mesafe". Çocuk artık merdivenden veya koltuktan inerken mesafeyi daha iyi hesaplar. Ona her zaman dikkatli olmasını ve güvenli inme yöntemlerini (geri geri) hatırlatın. Bu, beden güvenliği kurallarını öğrenmesi ve riskleri görsel olarak değerlendirmesi açısından önemli bir aşamadır.') WHERE id = '00eb14eb-16c9-4d20-9af4-97c177dc49f5';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Geri geri yürüme". Çocuk artık arkasına bakmadan geriye doğru birkaç adım atabilir. Bu, bedeninin uzaydaki konumunu hissetmesi (propriyoseptif duyu) açısından önemlidir. Ona "Yengeç gibi yürüyelim" diyerek bu hareketi oyuna dönüştürün. Bu hareket, bacak kaslarını farklı şekilde çalıştırır.') WHERE id = '2b4f1496-5d34-4f25-9ad5-91b67ba2967b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "İsim-Zamir ilişkisi". Çocuk artık kendisinden adıyla söz etmek yerine "Ben" demeye tamamen geçer. Siz ona bir şey sorduğunuzda "Ben" veya "Benim" diyorsa bu, benlik bilincinin tam olarak yerleştiğini gösterir. Onunla bu konuda diyaloglar kurun: "Bu kimin topu? Benim!". Siz harika bir yol göstericisiniz!') WHERE id = '61b67af6-b8e7-43c0-aeec-e2ba32964d5a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal sınırlar: Çocuk artık "Ben istemiyorum" diyerek iradesini güçlü bir şekilde ortaya koyabilir. Böyle anlarda onunla inatlaşmak yerine seçenekler sunarak dikkatini başka yöne çekin. Sabrınız ve tutarlı kurallarınız, çocukta güven duygusu oluşturur. 840 günü başarıyla tamamladık – siz her şeyin en iyisini hak ediyorsunuz!') WHERE id = 'f92d1e9f-889d-441d-90aa-ab2a51e762a4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '28. ayın son on gününe başlıyoruz! Çocuğunuz artık iki aşamalı yönergeleri kolaylıkla yerine getiriyor. Örneğin: "Oyuncağı al ve rafa koy". Bu, hem çalışma belleğinin hem de dili anlama becerisinin yeni bir düzeye ulaştığını gösterir. Gün içinde ona bu tür küçük "görevler" vererek hem sorumluluk duygusunu hem de dikkatini geliştirebilirsiniz.') WHERE id = '1fed649f-83be-432e-bf3b-958f939d1d57';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Merdiven çıkma ustalığı". Çocuğunuz artık tek elinden tutulduğunda merdivenleri her basamağa bir ayağını koyarak çıkmayı deneyebilir. Bu, uyluk ve kalça kaslarının güçlendiği anlamına gelir. Her zaman yakınında durarak güvenliğini sağlayın ve başarılarını alkışlayın.') WHERE id = '2104ca19-971d-4ad2-bad2-4fb0d5fce478';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Neden-sonuç" ifadeleri. Çocuğunuz artık "Çünkü" (veya buna benzer bir ses) demeye çalışarak bir şeyi neden istediğini açıklayabilir. Siz de ona nedenleri açıklayın: "Şimdi dondurma yemiyoruz, çünkü hava soğuk". Bu, mantıksal düşünme ve gerekçe sunma becerisinin temelini oluşturur.') WHERE id = '9a1ea5be-b73b-4171-a8a3-6f9f06ff6d11';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Vidalama ve çevirme". Çocuğunuz artık şişe kapaklarını ve oyuncak vidalarını güvenle çevirerek açıp kapatabilir. Bu hareket, bilek kaslarının dönme hareketi için mükemmel bir egzersizdir. Ona farklı boyutlarda güvenli kaplar vererek mekanik merakını destekleyin.') WHERE id = '326af733-89d5-4b18-a86d-69d50b560d32';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Kendi kendime yıkanıyorum". Çocuğunuz banyo yaparken sabunu veya süngeri alıp vücudunu ovalamaya ve sizi taklit etmeye çalışır. Hijyen alışkanlıklarına duyduğu bu ilgiyi engellemeyin. Kendisini "temizlemesi", hem vücudunun bölümlerini daha iyi tanımasına hem de kişisel hijyen sorumluluğunu erken yaşta kazanmasına yardımcı olur.') WHERE id = '059ef4bc-ae23-4023-aa71-ac7bfd7a180d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Paylaşmanın zorluğu". Bu yaşta "Benim!" diye bağırması son derece normaldir. Çocuğunuz kendisine ait olan şeyleri korumayı öğreniyor. Onu paylaşmaya zorlamayın; bunun yerine "Sırayla oynayalım" ilkesini uygulayın. Gösterdiğiniz bu sabır, onun sosyal zekâsının gelişmesine katkı sağlar.') WHERE id = '89f6ed5e-1781-4f77-8a89-eea339ecb1d6';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Eşleştirme" (Matching). Çocuğunuz artık aynı hayvanın farklı resimlerini veya aynı renkteki nesneleri birbiriyle eşleştirebilir. Basit kartlarla onunla "Aynısını bul" oyunu oynayın. Bu oyun, hem görsel dikkatini hem de kategorilere göre düşünme becerisini hızla geliştirir.') WHERE id = '1b1a5af3-541e-4a8b-826b-94504ae0251e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topu uzağa atma". Çocuğunuz artık topu yalnızca yere bırakmıyor, omuz hizasının üzerinden (overhand) ileriye doğru atmaya çalışıyor. Bu hareket tüm vücudun koordinasyonunu gerektirir. Onunla parkta "Topu kim daha uzağa atar?" oyunu oynayın. Bu oyun hem kollarını güçlendirir hem de mesafe algısını geliştirir.') WHERE id = '985bce91-74bc-40ac-bdc4-be9aa7dbfeab';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Rica etmek". Çocuk artık bir şey istediğinde yalnızca parmağıyla göstermiyor, "Ver" veya "Lütfen" (ya da buna benzer bir ifade) diyebiliyor. Ona her zaman nazik ifadeler kullanarak örnek olun. Sizden "Teşekkür ederim" veya "Lütfen" sözlerini duyması, gelecekteki iletişim kültürünün temelini oluşturur.') WHERE id = 'edefb696-9b37-48b2-bf5d-42c196545bf4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Hayal gücünün gelişmesi: "Rol yapma oyunları karmaşıklaşıyor". Çocuk artık yalnızca yemek pişirmekle kalmıyor; oyuncaklarını misafirliğe çağırıyor, onları "tedavi ediyor" veya "arabaya bindirip işe götürüyor". Bu, hafızasındaki olayları nasıl bir araya getirdiğini gösterir. Bu rol yapma oyunlarına siz de katılın; bu, onun yaratıcılığını zirveye taşıyacaktır.') WHERE id = '22acecd0-67df-4601-b0d7-23a57c3444c3';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '29. aya hoş geldiniz! Çocuk artık "evet" ve "hayır"dan daha karmaşık yanıtlar vermeye başlıyor. "Bunu neden istiyorsun?" sorusuna "Çünkü lezzetli" veya "Çünkü kırmızı" gibi yanıtlar verebilir. Bu, içsel motivasyonunu sözcüklerle ifade etme becerisinin başlangıcıdır. Söylediği her "çünkü"yü dikkatle dinleyin.') WHERE id = '0e94d08f-2dfb-49bd-b8dc-5b547bbc54de';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Dinamik denge". Çocuk artık alçak bir çizginin veya yere serilmiş bir ipin üzerinde "cambaz" gibi yürümeye ilgi gösterir. Bu, beden farkındalığını (propriyosepsiyon) geliştirir. Evde renkli bantlarla yollar oluşturarak bu becerisini destekleyin.') WHERE id = '82c3b72a-274b-4062-9adf-7e5cce134bd3';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Çoğul ekleri". Çocuk artık "elma" ile "elmalar" arasındaki farkı hem anlıyor hem de konuşurken kullanmaya çalışıyor. Oyuncaklarını gösterip "Bak, burada birçok araba var" diyerek çoğul kavramını pekiştirin. Bu, dil bilgisi yapısının giderek daha karmaşık hâle geldiğini gösterir.') WHERE id = '64529c1d-caa7-4ac1-a772-2e82ed067453';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Parmak gücü". Çocuk artık mandalları (çamaşır mandallarını) sıkıp açabilir veya oyun hamuruyla oynarken daha küçük parçalar koparabilir. Bu hareketler parmaklardaki küçük kasları güçlendirir ve onu ileride kalemi doğru tutmaya hazırlar.') WHERE id = 'e1008078-204c-4a5c-bac1-d07adf97ca32';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Sembolik paylaşma". Çocuk artık başka bir çocuğun elindeki oyuncağı hemen almak yerine "ver" diyerek beklemeye çalışır. Bunlar öz düzenleme (self-regulation) becerisinin ilk tohumlarıdır. Bu sabırlı davranışını gördüğünüzde mutlaka "Sıranı beklediğin için teşekkür ederim" diyerek onu övün.') WHERE id = '7f709f10-5a18-4150-b7b4-fa822721b9c8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Kendim hazırlıyorum". Çocuk mutfakta size yardım etmekten büyük keyif alır: hamuru sıkmak, sebzeleri (güvenli bir bıçakla) kesmek veya sofraya kaşık koymak. Bu, hem motor becerilerini geliştirir hem de yiyeceklere olan ilgisini artırır.') WHERE id = '53d5b167-fe89-4403-8e4d-0684f94ae9c5';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Sıralama ve Hafıza". Çocuğunuz artık en sevdiği masalın veya çizgi filmin olay sırasını biliyor. Siz olayı yanlış anlattığınızda "Hayır, ayı geldi!" diyerek sizi düzeltebilir. Bu, uzun süreli hafızasının ve olay örgüsünü kavrama becerisinin gelişmiş olduğunu gösterir.') WHERE id = '51d45576-0732-4e17-9d1f-994a457d540c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Olduğu yerde zıplama ve dönme". Çocuğunuz artık yalnızca yukarı doğru zıplamakla kalmıyor, zıplarken havada vücudunu döndürmeye de çalışıyor. Bu hareket, karmaşık bir vestibüler koordinasyon gerektirir. Onunla yumuşak bir halının üzerinde "akrobasi" oyunları oynayın.') WHERE id = '9536e69d-203e-4017-ae80-dbe2f9eab99b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Dil gelişiminde "Kendini tanımlama". Çocuğunuz artık size "Ben büyüğüm", "Ben koşuyorum" gibi ifadelerle kendi durumu hakkında bilgi veriyor. Onunla aynanın karşısına geçip "Gözlerin ne renk?", "Burnun nerede?" gibi sorular sorarak kendini tanıma sürecini eğlenceli hâle getirin.') WHERE id = 'eca2c14e-98c5-475b-94e6-e55601d2febb';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal gelişim: "Bağımsızlık krizleri". Çocuğunuz her şeyi kendi yapmak istediğinde ve başaramadığında yoğun bir öfke yaşayabilir. Böyle anlarda sakin kalın ve "Şu anda öfkelisin, çünkü bu zor. Haydi birlikte yapalım" diyerek ona destek olun. Sizin sakinliğiniz, onun duygusal fırtınalarını dindiren en güçlü limandır.') WHERE id = '9fa6b04b-2e13-4b5c-ba62-6d1e0398948e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık renkleri yalnızca "kırmızı" veya "mavi" olarak değil, birbirine yakın tonlarıyla da görsel olarak ayırt edebiliyor. Ona yeşilin farklı tonlarındaki yaprakları gösterin ve "Hangisi daha koyu?" diye sorun. Bu, görsel analiz becerisini geliştirir.') WHERE id = '1d89cf33-54f4-473a-9dbf-869b4e96ac30';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Tek ayak üzerinde zıplama denemeleri". Çocuğunuz artık tek ayağı üzerinde küçük bir sıçrama yapmaya çalışıyor. Bu, ayak bileği gücü ve denge açısından oldukça karmaşık bir harekettir. Bu cesur denemelerini alkışlayın ve düşse bile cesaretini kaybetmemesi için ona destek olun.') WHERE id = 'c09edac9-8b37-4347-a8dd-3e14699e7139';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Dil gelişiminde "Geçmiş zamanın ilk işaretleri". Çocuğunuz artık "gittim", "gördüm", "yedim" gibi fiilleri geçmişte yaşanan olaylar için kullanıyor. Akşamları onunla "Bugün ne yaptık?" sohbetleri yapın. Bu, hem hafızasını hem de zaman kavramını güçlendirir.') WHERE id = '5e30771f-35e9-43cb-9e6c-1bfc3d0ea335';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Amaca yönelik boyama". Çocuğunuz artık kâğıttaki büyük bir şeklin (örneğin bir dairenin) içini boyamaya ve sınırların çok dışına taşmamaya çalışıyor. Bu, el kaslarının kontrolünde büyük bir ilerlemedir. Ona basit ve kalın hatlı boyama sayfaları sunun.') WHERE id = '30b62203-ae1a-48ab-82d9-d252856f8bcb';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Ben yardımcıyım". Çocuk artık evdeki küçük temizlik işlerini (toz almak, oyuncaklarını kutuya yerleştirmek) bir oyun olarak değil, bir görev olarak görmeye başlar. Ona kendisine ait küçük bir temizlik bezi verin. Bu, aile içindeki sorumluluk ve aidiyet duygusunu inanılmaz ölçüde güçlendirir.') WHERE id = '75e40c4f-895e-4725-bab2-0bb5ec9f1edc';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "İlk arkadaşlık belirtileri". Çocuk artık parkta tanıdığı bir çocuğu gördüğünde sevinir ve ona oyuncağını teklif eder. Bu, yalnızca yan yana oynamaktan birlikte oynamaya (etkileşimli oyun) geçiş aşamasıdır. Onun bu sosyal adımlarını olumlu sözlerle destekleyin.') WHERE id = '73a7095e-32dd-413f-b911-0ace0be7e88d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Yükseklik ve Hacim". Çocuk artık hangi bardağın daha fazla su aldığını veya hangi kulenin daha yüksek olduğunu görsel olarak karşılaştırır. Banyo sırasında farklı boyutlardaki kaplarla su oyunu oynayın. "Hangi kap daha çabuk dolacak?" sorusu, fiziksel dünyaya ilişkin bilgisini artırır.') WHERE id = '3cf32da0-166e-4863-bf9c-f4ea80d66e98';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Koşarken topu kontrol etmek". Çocuk artık koşarken topu ayağıyla ileri doğru sürmeye (dripling) çalışır. Bu, hareket hızı ile ayak hareketlerindeki isabetin eş zamanlı hâle gelmesidir. Onunla açık havada hareketli futbol oyunları oynayarak enerjisini yararlı bir şekilde atmasına yardımcı olun.') WHERE id = 'c300bf1e-a81a-4d08-9bfb-583735c02aab';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Soyut sorular". Çocuk artık yalnızca "Bu nedir?" değil, "Kuş nereye uçtu?" veya "Güneş nereye gitti?" gibi gözle görülmeyen olaylar hakkında da sorular sorar. Yanıtlarınıza hayal gücünü de katın: "Güneş uyumaya gitti". Bu, onun hayal gücünün ve olayları kavrama derinliğinin bir göstergesidir.') WHERE id = '5d13e772-b0dc-414e-be1a-eb306de1058d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal dayanıklılık: Çocuk artık "Hayır" yanıtını duyduğunda eskisi gibi hemen ağlamaz, nedenini anlamaya çalışır. Ona kuralları sakin bir ses tonuyla açıklayın: "Şimdi şeker yemiyoruz, çünkü akşam yemeği zamanı". Sizin tutarlı ve mantıklı davranmanız, çocukta öz denetim ve sabır becerilerinin gelişmesini sağlar.') WHERE id = 'd426c7f4-84e8-442d-bd5f-c6c23fc0839f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '29. ayın son on günlük dönemine başlıyoruz! Çocuk artık "ben" ve "sen" zamirlerini neredeyse hiç karıştırmadan kullanır. Konuşma sırasında isteklerini "Ben bunu istiyorum" diyerek kararlı bir şekilde ifade eder. Onun bu benlik bilincini destekleyin ve kararlarına saygı duyduğunuzu gösterin; bu, sağlıklı öz güvenin temelidir.') WHERE id = '4a584dfd-3b1f-4ba7-b2c3-765c25e1ca50';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Sıçrama ve Yere İnme". Çocuk artık alçak bir basamaktan (örneğin kaldırım kenarından) iki ayağıyla aynı anda yere atlamaya cesaret eder. Bu, hem bacak kaslarının gücü hem de mekânsal denge hissi açısından büyük bir başarıdır. Her zaman yakınında bulunarak güvenliğini sağlayın.') WHERE id = '55d65f2d-a7aa-455b-9e97-2b3375627fc7';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Bağlaç kullanımı". Çocuğunuz artık "ve", "ama", "çünkü" gibi sözcüklerle iki düşünceyi birleştiriyor: "Koştum ve düştüm". Bu, düşüncelerinin daha sistemli ve bağlantılı hâle geldiğini gösterir. Onunla konuşurken siz de bu bağlaçları kullanarak cümlelerinizi biraz daha karmaşık hâle getirin.') WHERE id = 'a1740f48-0bf0-4597-985c-859e4a235e6b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Düğüm ve bağlama merakı". Çocuğunuz artık ayakkabı bağcıklarını çekmeye, düğmeleri açmaya veya büyük boncukları ipe dizmeye çalışıyor. Bu hareketler parmak koordinasyonunu ileri bir düzeye taşır. Ona farklı dokularda ipler ve delikli oyuncaklar vererek bu ilgisini destekleyin.') WHERE id = '17adcdf9-4e22-4431-92cb-4bcd0b67e350';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız giyinme" becerisi. Çocuğunuz artık pantolonunu yukarı çekmekte veya basit bir tişörtü (başından geçirdikten sonra) giymekte oldukça becerikli. Onu "Hadi, şimdi çoraplarını giymeyi dene" diyerek teşvik edin. Bu küçük bağımsızlık adımları, günlük yaşamda kendisini becerikli bir birey olarak hissetmesine yardımcı olur.') WHERE id = '306f738c-086a-4ef8-9272-59796c9176d7';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Kuralları anlama". Çocuğunuz artık evdeki veya parktaki bazı kuralları ("yemekten önce ellerini yıkamak", "kaydırakta sırasını beklemek") anlıyor. Bazen bu kurallara uymak istemese de sizin tutarlı yaklaşımınız, sosyal kuralları iç disipline dönüştürmeyi öğrenmesine yardımcı olur.') WHERE id = '4a18c5ac-a958-4970-b854-89448eb42394';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Sıralama ve karşılaştırma". Çocuğunuz artık 3-4 nesneyi büyüklüklerine göre sıralayabiliyor. Ona farklı boyutlarda küpler verin ve "En küçüğünü en üste koy" deyin. Bu, hem görsel analiz becerisinin hem de erken matematiksel düşünmenin geliştiğini gösterir. Her doğru adımında ona "Ne kadar da dikkatlisin!" diyerek motivasyonunu artırın.') WHERE id = '4204844b-c0b2-424d-bc6a-7ddffcbc310c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topu uzaktaki bir hedefe atmak". Çocuğunuz artık topu yalnızca atmıyor, belirli bir noktaya (örneğin sepete veya size doğru) daha isabetli şekilde yönlendiriyor. Bu, el-göz koordinasyonu ile derinlik algısının (mesafe algısı) birlikte çalışmasıdır.') WHERE id = '2d64c34e-bf0d-4efe-9c0e-d67a9a461b59';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Soru-cevap zinciri". Çocuğunuz artık sorularınıza yalnızca "evet/hayır" diye değil, tam cümlelerle yanıt veriyor. "Bugün ne gördün?" sorusuna "Büyük bir ağaç gördüm" diyebilir. Onunla sohbet ederken "Ne renkti?", "Neredeydi?" gibi devam soruları sorarak konuşma gelişimini destekleyin.') WHERE id = 'e8d19883-dd1e-49e0-bcde-510b73e5bdc1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '880 günü tamamladık! Çocuğunuz artık 2 buçuk yaşına (30 aylık olmaya) yaklaşıyor. Artık hem fiziksel hem de duygusal olarak daha güçlü. Kendi duygularını adlandırabiliyor ("mutluyum", "sinirlendim"). Bugün onunla birlikte geçirdiğiniz her an, hafızasında silinmez ve olumlu izler bırakıyor. Siz harika bir annesiniz!') WHERE id = '6218d94c-c601-40e6-8296-e74639caa069';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '30. aya, yani çocuğunuzun 2,5 yaşına hoş geldiniz! Bu dönemde çocuğunuz artık kendini bağımsız bir birey olarak ortaya koyar. "Bu benim" veya "Ben kendim yapacağım" diyerek kendi sınırlarını çizer. Bu bağımsızlık girişimlerini sabırla karşılayın; bu, karakterinin şekillenmesi açısından çok önemlidir.') WHERE id = '8c2026bd-7655-4fc6-8c90-c09af022e3d7';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel gelişimde "Dinamik Denge". Çocuğunuz artık tek ayağının üzerinde birkaç saniye (3-5 saniye) desteksiz durabilir. Bu, beyincik gelişiminin ve kas koordinasyonunun bir göstergesidir. Onunla "Leylek oyunu" oynayın ve kimin daha uzun süre durabildiğine bakın.') WHERE id = '59136234-e72e-461f-a081-2d86fdd6b1f1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Soyut kavramlar". Çocuğunuz artık "sevgi", "mutluluk" veya "korku" gibi duyguları adlandırmaya başlar. "Seni seviyorum" demesi veya "Korktum" diyerek kucağınıza gelmesi, duygusal zekâsının (EQ) hızla geliştiğini gösterir. Duygularını her zaman kabul edin ve onaylayın.') WHERE id = '2c9c993e-8ed6-4bde-970b-e837e161f321';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Dikey ve Yatay Çizgiler". Çocuğunuz artık kalemi daha güvenli tutar ve kâğıda üst üste binen karmaşık çizgiler yerine daha amaçlı düz çizgiler çizer. Ona farklı renklerde boyalar vererek "yollar" veya "merdivenler" çizmesini önerin.') WHERE id = '2e6c20d2-ff7f-4e05-b377-0a03f81606ea';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız Hijyen". Çocuğunuz artık dişlerini fırçalamaya (sizin gözetiminizde), ellerini sabunlayıp iyice durulamaya heves eder. Bu alışkanlıkların bu yaşta oyun yoluyla pekiştirilmesi, gelecekte kişisel temizliği konusunda sorumluluk sahibi olmasına yardımcı olacaktır.') WHERE id = '9f592616-f0c7-4018-8751-de7b0540a2d9';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Rol Yapma Oyunları". Çocuğunuz artık bir "senaryo" kurar: oyuncaklarını misafirliğe çağırır, onlara "çay ikram eder" veya onları "uyutur". Bu oyunlar aracılığıyla yetişkinlerin dünyasını taklit ederek sosyal rolleri ve kuralları derinlemesine öğrenir.') WHERE id = 'b497facf-4e33-44ce-bb8d-95b34db2194a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Farklı Şekilleri Tanıma". Çocuğunuz artık daire, kare ve üçgen arasındaki farkı bilir ve bunları uygun boşluklara yerleştirir. Ona "Bana kareyi ver" dediğinizde hata yapmıyorsa bu, görsel-uzamsal düşünme becerisinin geliştiğini gösterir.') WHERE id = 'e423f075-63ff-4c05-92b5-4ab5ac29b6be';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Geri geri yürüme". Çocuğunuz artık arkasına bakmadan birkaç adım geri gidebilir. Bu hareket, vücudunun uzaydaki konumunu algılaması (propriosepsiyon) açısından önemlidir. Ona "Yengeç gibi yürüyelim" diyerek bu hareketi oyuna dönüştürün; bu, bacak kaslarını farklı şekillerde çalıştırır.') WHERE id = '4e7bdd0e-7517-4dbe-a3fb-4614d6b6754f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Çok Sözcüklü Cümleler". Çocuğunuz artık 4-5 sözcükten oluşan karmaşık cümleler kuruyor: "Anne, parka gitmek ve oynamak istiyorum". Cümlelerinde bağlaçlar ve zaman ekleri artık daha sık görülüyor. Onunla sohbet ederken daha fazla konuşmasını teşvik etmek için açık uçlu sorular sorun.') WHERE id = 'd51c61a3-3310-47cc-be33-4e2fc01a2f12';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal Sınırlar: Çocuğunuz artık bazı davranışlarının sizi nasıl etkilediğini anlamaya başlıyor. Yüzünüzdeki üzüntüyü veya sevinci okuyabiliyor. Ona "Sen paylaşınca ben çok mutlu oluyorum" diyerek duygusal neden-sonuç ilişkilerini açıklayın. Bu, onun şefkatli ve duyarlı bir birey olarak büyümesine yardımcı olur.') WHERE id = '00079201-58ca-47e2-bd9f-428f9b22aea3';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '900 günlük büyük dönüm noktasına yalnızca son 10 gün kaldı! Çocuğunuz artık "ben" merkezli düşünceden biraz uzaklaşıp başkalarının ihtiyaçlarını da anlamaya başlıyor. Örneğin size "Su ister misin?" diye sorabilir. Onun bu düşünceli girişimlerini mutlaka takdir edin; bu, sosyal zekâsının (EQ) olgunlaşmaya başladığını gösterir.') WHERE id = '54cacacb-5f6d-4f6a-b6ea-082797db1faf';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Dönüşümlü adımlarla merdiven inme". Çocuğunuz artık merdivenleri her basamakta ayağını değiştirerek inmeye çalışıyor. Bu hareket, merdiven çıkmaktan daha zordur ve iyi bir denge gerektirir. Sabırla bekleyin ve ona güvendiğinizi hissettirin.') WHERE id = 'ce4fa5fc-7dc5-4de0-b4e5-b9c6bb215fb4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Karmaşık sorular dönemi". Çocuğunuz artık yalnızca "Bu nedir?" değil, "Bu neden böyle?", "Nereye gidiyoruz?" gibi sorular da soruyor. Yanıtlarınız dürüst ve basit olsun. Açıklamalarınız, zihninde dünyanın mantıksal haritasını oluşturur. Merakını her zaman teşvik edin: "Sence neden böyle?".') WHERE id = 'b47ac63c-a31b-4cfe-b3d9-64f08edba2f8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Daire ve Çarpı çizme". Çocuğunuz artık kalemi daha çok "yetişkinler gibi" (üç parmağıyla) tutmaya ve kâğıt üzerinde daire, çarpı gibi şekilleri taklit etmeye başlıyor. Bu, gelecekteki yazma becerileri açısından en kritik motor becerilerden biridir. Ona renkli tebeşirler verin.') WHERE id = '4c756f1e-f764-4f55-8535-6552dafc167f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız beslenme ve seçim". Çocuğunuz artık sofrada ne kadar yiyeceğine kendisi karar vermek istiyor. Onu zorla yedirmekten kaçının. Öz bakım becerileri geliştikçe kendi tabağını (güvenliyse) mutfağa götürmesini teklif edin. Bu, aile içinde sorumluluk duygusu geliştirmesine yardımcı olur.') WHERE id = '04c3f7db-69bb-44ed-8348-5d4d92cb8c92';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Hayali oyun arkadaşları". Çocuğunuz artık oyuncaklarıyla konuşuyor, onlara görevler veriyor ve sanki canlıymış gibi davranıyor. Bu, hayal gücünün ve olaylar arasındaki soyut bağlantıları ne kadar güçlü kurabildiğinin bir göstergesidir.') WHERE id = '2c67e108-3cf8-4072-89be-1ff519eaddcc';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Renk tonlarını ayırt etme". Çocuğunuz artık yalnızca "yeşili" değil, açık ve koyu yeşili de görsel olarak ayırt edebiliyor. Ona farklı renk tonlarındaki yaprakları veya boya kalemlerini göstererek "Hangisi daha koyu?" oyunu oynayın. Bu, görsel analiz becerisini geliştirir.') WHERE id = 'dcddf5f8-faa5-4048-a797-208e9715f0bf';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Üç tekerlekli bisiklete ilgi". Çocuğunuz artık pedalları çevirmeye veya ayaklarını yere dayayıp kendini ileri doğru itmeye çalışıyor. Bu hareket hem bacak kaslarını güçlendirir hem de bulunduğu alanda yönünü kontrol etme becerisini geliştirir.') WHERE id = 'a4633b77-b5aa-45ed-9da1-475ae9482abc';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Geçmiş ve gelecek zaman". Çocuğunuz artık "Yarın gideriz" veya "Dün gittik" gibi zaman farklarını, henüz tam olarak doğru kullanamasa da, konuşmasına yansıtmaya çalışıyor. Günün sonunda onunla "Bugün ne yaptık?" ve "Yarın ne yapacağız?" üzerine konuşun. Bu, hafızasını ve planlama becerisini güçlendirir.') WHERE id = '3e7a62e8-608e-4fd7-88f9-177ba74dcb48';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Tebrikler, 900 günü tamamladık! Çocuğunuz artık 2 buçuk yaşın (30 ay) dönüm noktasında. Artık hem fiziksel hem de duygusal açıdan daha güçlü, bağımsız ve yaratıcı. Bu 900 gün boyunca gösterdiğiniz sevgi ve özveri, onun gelecekteki tüm yaşamının temelini oluşturdu. İnanılmaz bir iş başardınız, Anne!') WHERE id = '3d5a9ac6-ec3e-4630-b503-91b84d5fef32';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '900 günlük büyük dönüm noktasını geride bıraktık ve yeni bir aşamaya başlıyoruz! Çocuğunuz artık 31. aya giriyor. Artık hem kendi adını hem de aile üyelerinin adlarını eksiksiz ve doğru bir şekilde söyleyebiliyor. Onunla birlikte aile albümüne bakarak "Bu kim?" oyunu oynayın. Bu, hem aidiyet duygusunu hem de sözel hafızasını güçlendirir.') WHERE id = '5482dfbc-7126-4e7c-8510-4a2cfbf55aee';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Tek ayak üzerinde zıplama". Çocuğunuz artık tek ayağı üzerinde çok küçük de olsa zıplamaya çalışıyor. Bu, ayak bileğinin ve baldır kaslarının önemli ölçüde geliştiğini gösterir. Parkta onunla "tavşan zıplaması" yarışı yaparak bu becerisini destekleyin.') WHERE id = '2840aa13-bbb5-476f-ad1f-11685bbcd555';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Gerekçe sunma". Çocuğunuz artık isteklerini yalnızca dile getirmiyor, aynı zamanda gerekçelendiriyor: "Ben bu oyuncak bebeği istiyorum, çünkü o çok güzel". Kullandığı "çünkü" ifadelerini dikkatle dinleyin. Bu, mantıksal düşünme ve kendini ifade etme becerilerinin ne kadar geliştiğini gösterir.') WHERE id = 'dd18fee0-7070-455b-a654-1c5450138cd5';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Amaca yönelik boyama". Çocuğunuz artık kâğıttaki büyük şekillerin (örneğin, büyük bir elma resmi) sınırlarını algılıyor ve boyama yaparken çizgilerin dışına çıkmamaya çalışıyor. Bu, el kaslarını kontrol etme becerisinde büyük bir adımdır. Ona kalın konturlu boyama sayfaları verin.') WHERE id = '25d06f6c-6efb-491d-ac80-8bbd8fa74917';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız giyinme" ve düğmeler. Çocuğunuz artık büyük düğmeleri açmaya veya fermuarı (siz başlattıktan sonra) yukarı çekmeye ilgi gösterir. Ona "Haydi, kendin dene" diyerek bu fırsatı verin. Kendi kendine giyinebilmesi, çocuğunuzun "Ben yapabilirim" hissini ve öz güvenini inanılmaz ölçüde artırır.') WHERE id = 'e6e7a26c-5b45-4894-8a1d-19ed6e362c71';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "İş birliği ve paylaşma". Çocuğunuz artık oyuncağını paylaştığında bunun geçici olduğunu anlar. "Biraz sen oyna, sonra ben" ilkesiyle tanışmasının zamanı geldi. Bu, hem sabrını hem de sosyal empati becerisini geliştirir.') WHERE id = '79abc2a4-51b0-4f9f-8334-d1eb1d4ea6eb';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Hacim algısı". Çocuğunuz artık küçük kutunun büyük kutuya sığacağını, ancak tersinin mümkün olmadığını görsel olarak anlar. Ona farklı boyutlarda kaplar verip "Hangisi bunun içine sığar?" diye sorun. Bu, gelecekteki matematiksel ve geometrik düşünmenin temelini oluşturan mekânsal algıdır.') WHERE id = '615744e3-fb18-42f6-8110-3e9a2d54709c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topu hedefe atma". Çocuğunuz artık topu yalnızca atmakla kalmaz, size doğru veya belirli bir kutuyu (sepeti) hedefleyerek isabetli biçimde atabilir. Bu, el-göz koordinasyonu ile derinlik algısının birleşimidir. Onunla "mini basketbol" oynayın.') WHERE id = '8fa193ab-3d15-4b10-9608-9e3d2bd116d1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Soyut kavramlar". Çocuğunuz artık "sevgi", "incinmek", "özlemek" gibi sözcükleri doğru bağlamda kullanır. "Seni özledim" demesi, duygusal zekâsının ulaştığı önemli bir noktadır. Bu duygularına mutlaka karşılık verin ve siz de kendi hislerinizi adlandırın: "Ben de seni görünce çok mutlu oluyorum".') WHERE id = '13cc3bef-f498-4191-9d8c-212c97c4c3e8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Hayal gücünün gücü: "Görünmez misafirler". Çocuğunuz artık oyuncaklarını misafirliğe çağırır ve onlara hayalî yemekler ikram eder. Bu "-mış gibi" oyunları, hafızasındaki sosyal senaryoları canlandırma yöntemidir. Siz de onun bu hayal dünyasına bir misafir gibi katılın!') WHERE id = 'a44149c1-0e64-49a3-936a-9d1d3a595e97';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık renkleri yalnızca "kırmızı" veya "mavi" olarak değil, koyu ve açık tonlarıyla da görsel olarak ayırt etmeye başlar. Ona farklı renklerde kalemler verip "Bana en koyu olanı ver" diyerek görsel analiz becerisini gözlemleyin. Bu, hem dikkatini hem de estetik algısını geliştirir.') WHERE id = '5bd4135a-236e-4d8e-8be3-3ebc28e05d9e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Geri geri yürüme". Çocuğunuz artık dengesini kaybetmeden geriye doğru birkaç adım atabilir. Bu hareket, beden farkındalığını (propriyosepsiyon) ve mekânsal yönelim becerisini güçlendirir. Onunla "Yengeç gibi yürüyelim" oyunu oynayın.') WHERE id = '54996f87-c947-4849-9084-027fb47fcd81';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Kafiyeli Kelimeler ve Şarkılar". Çocuk artık daha önce duyduğu şarkıların son sözlerini kafiyeli şekilde tamamlamayı çok seviyor. Bu, fonetik işitme becerisinin geliştiğini gösterir. Onunla birlikte şiirler okuyun ve sonunu onun tamamlaması için duraklayın. Bu etkinlik hem hafızasını güçlendirir hem de konuşma temposunu düzenler.') WHERE id = 'acf4d772-adf5-4683-b12b-56ef67f21202';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Boncukları ipe dizme". Çocuk artık büyük delikli boncukları veya makarnaları ipe dizme konusunda oldukça beceriklidir. Bu hareket hem sabır hem de parmakların hassas koordinasyonunu gerektirir. Böylece gelecekteki yazma becerileri için kas hafızası geliştirir.') WHERE id = 'acfd54f8-89c0-45e8-b646-d1e1362647ed';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız Hijyen" gelişimi. Çocuk artık ellerini yıkadıktan sonra kendi başına havluyla kurulanabiliyor ve havluyu yerine asabiliyor. Bu küçük "tamamlama" davranışları, öz bakım sorumluluğunu artırır. Bu düzenli davranışını "Ne kadar da düzenlisin!" diyerek takdir edin.') WHERE id = 'd2072154-6990-473d-aae5-34ace20cbb48';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Başkalarının duygularını anlama". Çocuk artık yüzünüzdeki üzüntüyü veya yorgunluğu fark edip "Ne oldu?" diye sorabilir. Bu, empatinin en saf hâlidir. Duygularınızı ona basit bir dille açıklayın: "Biraz yoruldum, gel birlikte dinlenelim". Bu, onun duygusal zekâsını (EQ) besler.') WHERE id = '146ce216-737a-480c-9a11-95c561e541a4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Sıralama ve Karşılaştırma". Çocuk artık 3-4 oyuncağını boyutlarına göre (küçükten büyüğe) sıralayabilir. Bu, erken matematiksel düşünmenin temelidir. Ona "En büyük ayıyı en başa koy" gibi yönergeler verin. Bu etkinlik hem görsel analiz yapmayı hem de dikkatini toplamayı öğretir.') WHERE id = 'a0704d4b-bb47-4a9f-8d8c-90add9dfed0e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Dinamik denge". Çocuk artık yere yakın bir ipin veya zemine çizilmiş bir çizginin üzerinde "cambaz" gibi yürümeye ilgi gösterir. Bu, vestibüler sisteminin (denge merkezi) olgunlaştığını gösterir. Parkta kaldırım kenarlarının üzerinde yürürken elinden tutarak bu cesaretini destekleyin.') WHERE id = '536458a4-4f3e-423b-9a13-cba42297d147';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Zaman kavramı: Dün ve Yarın". Çocuk bu kelimeleri henüz tam olarak doğru zamanları ifade etmek için kullanmasa da geçmiş ve gelecekteki olayları birbirinden ayırt etmeye çalışır. Günün sonunda onunla "Yarın nereye gideceğiz?" gibi sohbetler yapın. Bu, planlama becerisini ve olaylar arasındaki zaman ilişkisini güçlendirir.') WHERE id = '6849680a-6227-4b9c-ad36-2d8926dfdf15';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal Dayanıklılık: Çocuk artık bir şeyi başaramadığında (örneğin küpler devrildiğinde) hemen ağlamak yerine yeniden denemeye başlayabilir. Bu "mücadele ruhu", gelecekteki öğrenme başarısı için çok önemlidir. Ona "Çok çabaladığını görüyorum" diyerek sonucu değil, gösterdiği çabayı övün.') WHERE id = '86a0403c-8de6-429b-885d-6a2141aa02c8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '31. ayın son on günlük dönemine başlıyoruz! Çocuğunuz artık "ben" ve "benim" kelimelerini güçlü bir sahiplenme duygusuyla kullanıyor. Bu dönemde onun mülkiyet duygusuna saygı göstermek önemlidir. Ona "Bu senin oyuncağın, ama gel arkadaşınla sırayla oynamayı deneyelim" diyerek paylaşmanın bir seçenek olduğunu gösterin.') WHERE id = '84330770-7540-4b55-849d-a1cc950ead4d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "İki ayakla ileri atlama becerisi". Çocuğunuz artık yalnızca olduğu yerde değil, biraz ileriye doğru da (yaklaşık 10-20 sm) atlayabiliyor. Bu, bacak kaslarının patlayıcı gücünün arttığını gösterir. Yere küçük "engeller" (örneğin renkli şeritler) yerleştirerek onunla atlama oyunu oynayın.') WHERE id = '5741e7d1-1ed4-44c7-a88a-391b61cdae5d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Karmaşık cümle yapıları". Çocuğunuz artık iki farklı düşünceyi bağlaçlarla birleştiriyor: "Parka gitmek ve salıncakta sallanmak istiyorum". Cümlelerinde amaç ve niyet artık daha net görülüyor. Onunla konuşurken "Neden?" diye sorarak daha uzun açıklamalar yapması için onu teşvik edin.') WHERE id = '1e35c889-6f4c-4fd3-ae21-e3389ec8548d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Düzgün katlama". Çocuğunuz artık sizi taklit ederek kâğıdı veya küçük bir mendili katlamaya çalışıyor. Bu hareket hem el-göz koordinasyonunu hem de görsel simetri algısını geliştirir. Çamaşırları toplarken küçük mendillerini katlama görevini ona verin.') WHERE id = '3690ca7a-82f5-4004-93ab-5126e1011625';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız beslenme ve sofra adabı". Çocuğunuz artık kaşık ve çatal kullanırken neredeyse hiçbir şeyi dökmüyor. "Afiyet olsun" veya "Teşekkür ederim" gibi sofra ifadelerini de uygun yerlerde kullanmaya başlıyor. Bu sosyal nezaketini her zaman takdir edin; bu, gelecekteki iletişim kültürünün temelidir.') WHERE id = '43e9a2b0-67bf-44dc-b37a-1d4a9e1b3e86';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Rol yapma oyunlarının karmaşıklaşması". Çocuğunuz artık öğretmen, doktor veya ebeveyn gibi davranarak size "talimatlar" verebilir. Bu oyunlar aracılığıyla sosyal rolleri içselleştirir. Onun "derslerine" katılın; bu, liderlik becerilerini geliştirir.') WHERE id = 'd218ecc4-3eae-4f6a-ba4c-e1f3fc1576d0';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Sayı ile miktar arasındaki ilk bağ". Çocuğunuz 1''den 5''e kadar ezbere sayabilse de artık "iki elma" dendiğinde miktarı da anlamaya başlıyor. Ona "Bana iki tane kalem ver" diyerek sayı ile miktarı eşleştirmesini isteyin. Bu, matematiksel düşünmenin en önemli aşamalarından biridir.') WHERE id = 'e77c9dc0-0ffc-4afa-af6f-98372ac9412c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topa vurma manevraları". Çocuğunuz artık koşarken önündeki topa dengesini kaybetmeden vurabiliyor ve yönünü değiştirebiliyor. Bu, dinamik dengenin mükemmelleştiğini gösterir. Onunla açık havada "futbol" oynamak için en güzel zamandır.') WHERE id = 'f27d93f9-9b8c-4331-9608-1f9403361289';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Çok sözcüklü cümleler". Çocuğunuz artık 3-4 sözcüğü yan yana getirerek karmaşık düşüncelerini ifade eder: "Anne, ben büyük araba istiyorum". Cümlelerini düzeltmeyin, yalnızca doğru hâlini tekrarlayarak yanıt verin: "Evet, sen o büyük kırmızı arabayla oynamak mı istiyorsun?". Bu, dil yapısını farkında olmadan öğrenmesine yardımcı olur.') WHERE id = '4ada0942-f71a-4215-a9a2-e770a9dcbe42';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Ben kimim?". Çocuk artık kendi adını, yaşını (parmaklarıyla da olsa) ve cinsiyetini söyleyebilir. Bu, onun kimlik bilincinin zirvesidir. Yarınki büyük gün hakkında onunla konuşun: "Yarın artık 2 yaşında büyük bir çocuk olacaksın!".') WHERE id = 'ee27a56e-6e80-46b6-8a93-8ee183712978';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Yeni kelimeler: Sıfatların artması". Çocuğunuz artık nesneleri tanımlarken "yumuşak", "sert", "sıcak", "soğuk", "ağır" gibi kelimeler kullanıyor. Ona farklı dokulara sahip nesneler verin ve "Bu nasıl hissettiriyor?" diye sorun. Sıfat dağarcığının genişlemesi, dünyayı daha ayrıntılı algılamasına yardımcı olur.') WHERE id = '2a117057-8af9-4f1a-8e6e-3d0291275ec5';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal Olgunluk: Çocuğunuz artık bazen öfkesinin farkına varıyor ve "Ben sinirlendim" diyebiliyor. Bu, duygusal öz farkındalık açısından büyük bir sıçramadır. Böyle anlarda ona sarılın ve "Seni anlıyorum, gel birlikte sakinleşelim" deyin. 930 günlük yolculuğu başarıyla tamamladık – siz harika bir yol arkadaşısınız!') WHERE id = '9e7e7732-10aa-4ec3-9e8d-653645d590eb';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık "önce" ve "sonra" sıralamasını daha iyi kavrıyor. "Üstünü giy, sonra dışarı çıkalım" dediğinizde, ikinci eylemin bir ödül olduğunu anlıyor. Bunlar, çocukta sabır ve planlama becerisinin ilk tohumlarıdır. Günlük rutinlerde bu sıralamaları ona sık sık hatırlatın.') WHERE id = '97310562-0cc9-4922-aab5-bb0de93781d6';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel gelişimde "Tırmanma becerisi". Çocuğunuz artık parktaki merdivenlere veya evdeki güvenli yüksek yerlere daha özgüvenli bir şekilde tırmanıyor. Bu, hem kol hem de bacak kaslarının eş zamanlı çalışmasını sağlar. Her zaman yakınında olun, ancak kendi gücünü denemesine de izin verin.') WHERE id = '5e669269-1aa2-4602-9a6d-be602f929f7a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Mantıksal bağlantılar". Çocuğunuz artık iki olayı tek bir cümlede birleştiriyor: "Hava soğuk, ceketini giy". Bu, yalnızca taklit etmediğini, aynı zamanda düşündüğünü de gösterir. Kendi düşüncelerini ifade etmeye daha çok heveslenmesi için bu mantıklı çıkarımlarını "Evet, haklısın" diyerek onaylayın.') WHERE id = 'c578b6d7-6027-41d3-bcb5-015328604f79';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Kâğıt kullanımı". Çocuğunuz artık kâğıt katlamaya veya basit şekillerde (büyük çocuk makasıyla gözetim altında) kesmeye ilgi gösterebilir. Bu hareketler, parmak kaslarının kontrolünü yeni bir seviyeye taşır. Renkli kâğıtlarla çalışabileceği bir ortam hazırlayın.') WHERE id = '369aa3fa-b6a2-4869-aff0-584c7cb30be3';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Rol oyunlarının gelişmesi". Çocuğunuz artık "doktor", "aşçı" veya "şoför" rolüne giriyor. Bu oyunlar aracılığıyla çevresindeki insanların görevlerini öğreniyor ve empati kuruyor. Bu oyunlara katılın ve size verdiği "role" uygun davranın.') WHERE id = '71802808-c37b-439f-8b0c-227ce432a07a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Kendi başına temizlenme" alışkanlığı. Çocuğunuz artık ellerini yıkarken sabunlama ve durulama işlemlerini neredeyse tek başına yapabiliyor. Hijyen alışkanlıklarının bu yaşta pekişmesi çok önemlidir. Bu süreçten keyif alması için ona boyuna uygun basamaklı bir tabure (step stool) sağlayın.') WHERE id = '916356ea-060f-4a2e-8be7-98dcab3ad0ee';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Tebrikler! Bugün çocuğunuz tam 2 yaşına giriyor! 730 gün boyunca inanılmaz bir sabır, sevgi ve emek gösterdiniz. Çocuğunuz artık bebeklik dönemini geride bıraktı ve dünyayı keşfetmeye hazır, kendine özgü küçük bir birey oldu. Bu özel günü, onun en sevdiği oyunları birlikte oynayarak kutlayın. Aferin size, Anne!') WHERE id = '493d8af7-6247-4790-9dba-5fe6ecd538f7';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerde "Sanatsal yaratıcılık". Çocuğunuz artık kalemi daha güvenli bir şekilde tutuyor ve kağıda dairesel çizgiler çizmeye çalışıyor. Bu, gelecekte yazı yazmak için gerekli olan kas koordinasyonunun temelidir. Ona farklı renklerde boyalar ve büyük kağıtlar vererek hayal gücünü özgür bırakın.') WHERE id = 'c206267a-2d42-4d2c-8a75-f79f89a1455a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '3. yaşın ilk gününe hoş geldiniz! Çocuğunuz artık 2 yaşını doldurdu ve kendini "büyük" hissediyor. Bu dönemde eşyalarını ve oyuncaklarını daha fazla sahiplenmeye başlar. Kendi odasında veya oyun köşesinde küçük kurallar koymasına izin verin. Bu, sorumluluk duygusunun gelişmesine yardımcı olur.') WHERE id = 'e1193c8b-9caf-42cc-b0d1-380bfd68848e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Paylaşma ve Sınırlar". Çocuk artık bazı eşyaların kendisine, bazılarının ise başkalarına ait olduğunu anlar. Oyuncağını paylaşmakta hâlâ zorlanabilir. Ona "Bu şimdi senin, birazdan arkadaşın oynayacak" diyerek sıra kavramını öğretebilirsiniz. Bu, sosyal uyum için en önemli adımdır.') WHERE id = '0337bbc8-021f-48c3-b2d6-9d07615b2eb6';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Merdiven özgürlüğü". Çocuğunuz artık merdivenleri tek tek adımlarla (her basamakta ayağını değiştirerek) ve yalnızca bir elinden tutularak çıkabilir. Bu, kalça kaslarının ve denge merkezinin ne kadar güçlendiğini gösterir. Güvenlik kurallarını hatırlatarak ona güven verin.') WHERE id = '23cbdeb8-6ec7-49eb-b8f0-c4ae1a3cb46c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Ben yardım ediyorum". Çocuğunuz ev işlerinde size yardım etmekten büyük keyif alır. Çamaşırları sepete atmak veya sofraya ekmek koymak gibi küçük görevler, kendisini ailenin "önemli bir üyesi" gibi hissetmesini sağlar. Bu hevesini takdir edin: "Sen olmasaydın bunu daha geç bitirirdim!".') WHERE id = '176cc57c-d49b-4d93-9ce5-5829f43afd94';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Kelime dağarcığı patlaması". Çocuğunuz artık her gün birkaç yeni kelime öğreniyor ve 3-4 kelimeden oluşan anlamlı cümleler kuruyor. Örneğin: "Ben parka gitmek istiyorum". Onunla konuşurken açık uçlu sorular sorun: "Parkta ne yapmak istiyorsun?". Bu, hem hayal gücünü hem de kendini ifade etme becerisini geliştirir.') WHERE id = 'c49d7f6c-cef1-458f-99cb-da68585b7ac5';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Renklerin adı". Çocuğunuz artık renkleri yalnızca ayırt etmekle kalmıyor, birçoğunun adını doğru telaffuz ediyor. Parkta gezerken "Buradaki yeşil yaprak nerede?" veya "Bana sarı çiçeği göster" diyerek bilgilerini uygulamasını sağlayın. Bu, görsel ve sözel hafızası arasında bağlantı kurmasına yardımcı olur.') WHERE id = 'b1599687-8b9b-4b36-972d-e646da9ca057';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Daire çizme". Çocuğunuz artık kalemi daha güvenli bir şekilde tutuyor ve kağıda yaklaşık daireler çizmeye çalışıyor. Bu, el-göz koordinasyonunda yeni bir seviyeye ulaştığını gösterir. Ona renkli kalemler ve büyük kağıtlar vererek "ilk resimlerini" çizmesi için fırsat yaratın.') WHERE id = '448009d5-07ef-4006-89f4-993bbe989179';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topu omuz üzerinden atma". Çocuğunuz artık topu yalnızca yere atmıyor, bilinçli bir şekilde ileriye veya size doğru atmaya çalışıyor. Bu, kol kaslarının ve hedef algısının geliştiğini gösterir. Onunla "Topu sepete kim atabilir?" oyunu oynayarak isabet becerisini geliştirebilirsiniz.') WHERE id = 'a5dba3a5-d849-43ef-ab12-3acff84027fc';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Farklı olanı bulma". Çocuğunuz artık bir grup nesnenin içinden farklı olanı (örneğin, arabaların arasındaki elmayı) görsel olarak seçebilir. Bu, analiz becerisini geliştirir. Evde onun için basit "Hangisi fazla?" oyunları hazırlayın. Bu oyunlar, gelecekteki matematik ve mantık görevleri için harika bir hazırlıktır.') WHERE id = '9c6d24fc-1a56-41e1-93ca-e94c8c830e4f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Tek ayak üzerinde durma denemeleri". Çocuğunuz artık birkaç saniyeliğine de olsa bir ayağını yerden kaldırıp dengesini korumaya çalışır. Bu, vücudunun ağırlık merkezini tanıması açısından önemlidir. Onunla "Leylek oyunu" oynayın ve kimin daha uzun süre ayakta kalabildiğine bakın.') WHERE id = '1769bf32-48e2-40a7-b480-c6f396b19e4b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Duygu ifadeleri". Çocuğunuz artık üzgün, neşeli veya korkmuş olduğunu kelimelerle ifade edebilir: "Ben korktum" veya "Ben neşeliyim". Duyguları adlandırmak, çocuklarda duygusal zekânın temelini oluşturur. Duygusunu dile getirdiğinde onu dinleyin ve "Evet, seni anlıyorum" diyerek hislerini kabul edin.') WHERE id = '7f6f2c0c-ef35-4291-8d3c-3c98cbe7cfa1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Hayal gücünün gücü: "Sembolik düşünme". Çocuğunuz bir sopayı "at" olarak hayal edip dörtnala koşar gibi gezebilir. Bu, bir nesnenin başka bir şeyi temsil ettiğini anlama becerisidir. Bu beceri, gelecekte okuma ve matematik (sembolleri anlama) açısından çok önemlidir. Siz harika bir rehbersiniz!') WHERE id = 'b4910186-9bb2-4fc8-898b-364f4deeed97';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '32. ayın son on günlük dönemine başlıyoruz! Çocuğunuz artık "biz" kavramını anlamaya başlar. "Biz parka gidiyor muyuz?" diyerek kendisini ailenin ayrılmaz bir parçası olarak görür. Onunla konuşurken aile planlarınızı paylaşın: "Bugün biz anneanneye gideceğiz". Bu, çocuğunuzun aidiyet ve güven duygusunu güçlendirir.') WHERE id = '1b278c24-eef1-4629-acd4-d211ef0e2e61';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Merdiven bağımsızlığı". Çocuğunuz artık ayaklarını sırayla kullanarak her basamağa bir adım atıp yalnızca bir elinizden tutarak merdivenleri güvenle çıkar. Bu, kaba motor becerilerinin iyice olgunlaştığını gösterir. Siz yalnızca yanında bulunarak ona manevi destek verin.') WHERE id = '275df927-814f-46e6-87b1-244d3e43ae78';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Hikâye oluşturma". Çocuğunuz artık resimlere bakarak basit hikâyeler uydurur. "Kedi geldi, süt içti, uyudu" gibi birbirini takip eden cümleler, hafızası ile hayal gücünün birleşimidir. Ona ilgi çekici resimleri olan kitaplar verin ve "Burada ne oluyor?" diye sorun. Bu, yaratıcı düşüncesini harekete geçirir.') WHERE id = '904512e9-992f-4497-b856-79751b10de80';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Hassas yerleştirme". Çocuğunuz artık küçük oyuncak figürlerini yerleştirmeyi veya boncukları ipe dizmeyi daha az hata yaparak başarır. Bu dönemde parmak uçlarının hassasiyeti artar. Ona farklı dokulara sahip küçük nesnelerle gözetiminiz altında oynayabileceği oyunlar sunun.') WHERE id = 'd9171a51-69d8-4d0a-829c-7db5c26a601f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bağımsızlık: "Ben kendim giyiniyorum". Çocuğunuz artık çoraplarını çıkarmanın yanı sıra onları giymeye veya kolay giyilen pantolonunu yukarı çekmeye çalışıyor. Bu süreç uzun sürse de onu acele ettirmeyin. Bir şeyi kendi başına başarabilmek, onun için en büyük "ödüldür". Sabrınız, çocuğunuzun özgüvenini güçlendirir.') WHERE id = 'ae5217ae-ff5f-4178-a4dd-001e8d391224';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Rica ve Nezaket". Çocuk artık bir şey istediğinde sadece parmağıyla göstermek yerine, "Ver" veya "Lütfen" (kendi dilinde olsa bile) demeye çalışır. Sizin nazik tutumunuz onun iletişim tarzını şekillendirir. Her "teşekkür ederim" dediğinizde, o da bu nezaketi doğal bir şekilde benimser.') WHERE id = 'd8b07d2d-d5ae-44e4-8e83-13117a3ef758';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Sıra kavramı". Çocuk artık salıncakta veya kaydırakta sırasını beklemesi gerektiğini anlıyor. "Şimdi sıra sende, sonra arkadaşında" cümlesi onun için artık daha anlaşılır bir anlam taşıyor. Bu, sosyal uyumun ve sabretmeyi öğrenmenin en önemli aşamalarından biridir.') WHERE id = 'fd888eb3-7169-4c50-bc0d-f0696ed103ff';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal hazırlık: 2 yaşını doldurmasına yalnızca 10 gün kaldı! Çocuğunuz artık duygularını (sevinç, öfke, utanç) çok açık bir şekilde belli ediyor. Bu duyguları sabırla karşılayın ve adlandırın: "Şu anda seviniyorsun, çünkü parka gidiyoruz". Duyguları adlandırmak, çocuğun kendi iç dünyasını anlamasına ve gelecekte öz denetim geliştirmesine yardımcı olur.') WHERE id = '5b177d90-0a27-4e2b-8501-6cbcb2351fef';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Kendi başına giyinme" ısrarı. Çocuğunuz artık düğmesiz tişörtlerini veya pantolonunu kendi başına giymekte ısrar ediyor. "Ben kendim yapacağım!" dediği anlarda ona zaman tanıyın. Bu bağımsızlık çabaları, gelecekteki özgüveninin ve kişisel sorumluluk duygusunun en güçlü temelidir. Küçük başarılarını "Bak, tek başına başardın!" diyerek kutlayın.') WHERE id = 'b1c5306b-77bb-4136-8d44-3c944e44a9e3';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Nezaket kuralları". Çocuğunuz artık "Lütfen", "Teşekkür ederim", "Rica ederim" gibi ifadeleri yalnızca tekrarlamıyor, amacına uygun şekilde kullanıyor. Sizin nazik davranışlarınız onun için en önemli örnektir. Bu davranışlarını överek iletişim becerilerini pekiştirin.') WHERE id = '9e1b06c8-d4a2-4b28-b3bc-ad2c39ab7cb0';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Zaman zarfları". Çocuğunuz "sonra", "birazdan", "şimdi" sözcüklerini doğru yerde kullanmaya başlıyor. "Birazdan geleceğim" dediğinizde zamanın geçeceğini anlıyor. Bu, çocuğun bekleme ve kendini düzenleme becerisini geliştirir. Günlük rutinlerinizde bu sözcükleri sık sık kullanın.') WHERE id = '6f964b8f-02b2-4bed-adce-f35ba0656a6a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topa vurma ve hedef". Çocuğunuz artık topa gelişigüzel vurmakla kalmıyor, onu belirli bir yöne, örneğin iki oyuncağın arasından geçirmeye çalışıyor. Bu, el-göz ve ayak-göz koordinasyonunun eş zamanlı çalıştığını gösterir. Onunla evde bir "mini futbol" turnuvası düzenleyin.') WHERE id = '61ba305a-b8ae-4528-9ce2-bd394666ba9a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Soyut sorular". Çocuğunuz "Bulut nereden geliyor?", "Ay nereye gitti?" gibi sorular sorabilir. Yanıt verirken hayal gücüyle gerçek bilgileri dengeleyin: "Bulutlar uzaklardan gelip bize yağmur getiriyor". Bu tür sohbetler onun dünya görüşünü ve öğrenme hevesini inanılmaz ölçüde geliştirir.') WHERE id = 'a8a1120b-b774-4f04-89b0-c124a8cbf647';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal dayanıklılık: Çocuğunuz artık başarısızlık karşısında daha dirençli. Küpleri devrildiğinde hemen ağlamıyor, "Yeniden yapacağım" diyebiliyor. Bu mücadeleci ruhunu destekleyin. 950 günlük yolu geride bıraktık, 1000 güne çok az kaldı! Siz bu yolculukta hem öğretmen hem de onun en yakın dostusunuz!') WHERE id = 'c5fe4618-aa8a-4004-b14e-8472a1232fc2';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık nesneleri yalnızca türlerine göre değil, renk tonlarına göre de gruplandırabiliyor. Ona yeşilin farklı tonlarındaki oyuncakları verip "Açık renkten koyu renge doğru sıralayalım" diyerek görsel analiz becerisini geliştirin. Bu, onun estetik algısını ve dikkatini güçlendirir.') WHERE id = '4cccdb9f-0090-4953-be45-4aac0e3ecdc0';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Tek ayak üzerinde zıplama". Çocuğunuz artık tek ayağı üzerinde küçük bir sıçrama yapmayı deniyor. Bu, ayak bileği gücünün ve vestibüler sisteminin (denge sisteminin) oldukça geliştiğini gösterir. Onunla "Tavşan yavrusu" oyunu oynayın. Düşme korkusu yaşamadan özgürce hareket edebilmesi için her zaman yakınında olun.') WHERE id = '611c7f89-d565-4c80-b60a-401386c94dd3';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Zıt anlamlı kelimeler". Çocuk artık "büyük-küçük", "sıcak-soğuk", "ağır-hafif" gibi karşıtlıkları tamamen anlıyor ve konuşurken kullanıyor. Ona "Bu taş ağır, peki bu pamuk nasıl?" gibi sorular sorun. Bu, kelime dağarcığını nitelik bakımından zenginleştirir ve karşılaştırmalı düşünme becerisini güçlendirir.') WHERE id = '8c5fde41-64b4-4f6a-8c4b-9b0a4470f2ce';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Daha karmaşık yapılar". Çocuk artık küplerden yalnızca kule değil, "merdiven", "çit" veya "kapı" gibi boşluklu şekiller de yapıyor. Bu, onun mekânsal düşünme becerisinin ve mühendislik sezgisinin ilk gerçek işaretleridir.') WHERE id = '8323ecc8-fdd4-4a47-acab-de738c3b3b74';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız seçim: Hava ve Giyim". Çocuk artık dışarıda hava soğuksa kalın giyinmesi gerektiğini anlıyor. Ona "Bugün dışarısı soğuk, hangi montu giymek istersin?" diyerek iki seçenek sunun. Kendi seçtiği kıyafeti giymek, çocukta sorumluluk duygusunu ve karar verme becerisini geliştirir.') WHERE id = 'b6331bb4-9640-46b8-a4de-673e4569b48f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Sembolik paylaşım". Çocuk artık kendisi için çok değerli olmayan bir oyuncağı gönüllü olarak arkadaşına verebilir. Bu, benmerkezci dönemden (her şey benim) çıkışın ve sosyal iş birliğinin başlangıcıdır. Bu cömertliğini mutlaka "Ne kadar da düşüncelisin!" diyerek takdir edin.') WHERE id = '7a5cc16d-c4e3-465c-94b4-27327272c867';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Sıralama ve Sayma". Çocuk, 1''den 10''a kadar ezbere saymanın yanı sıra nesneleri parmağıyla göstererek "bir, iki, üç" diye saymaya başlıyor. Ona "Burada kaç araba var?" diye sorun. Bu, soyut sayıların gerçek dünyayla ilk kez güçlü bir bağ kurduğu aşamadır.') WHERE id = '27d58f54-7d91-4fc1-9abe-0e7741238b0e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Geri geri yürüme ve koşma". Çocuk artık arkasına bakmadan güvenle geri geri yürüyebiliyor, hatta birkaç adım koşabiliyor. Bu hareket, vücut koordinasyonunun ne kadar geliştiğini gösterir. Onunla "Yengeç yarışı" oynayarak hem eğlenin hem de kaslarını farklı şekillerde çalıştırın.') WHERE id = '5835a9f7-31b7-47bc-af3b-fbaf1eae167a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Bağlaçların kullanımı". Çocuk "ve", "ama", "çünkü" kelimelerini cümlelerine ekleyerek düşüncelerini daha kapsamlı biçimde açıklıyor: "Acıktım ama yemek istemiyorum". Cümlelerini dinleyin ve siz de benzer karmaşık cümlelerle yanıt verin. Bu, dil bilgisi algısının iyice gelişmesini sağlar.') WHERE id = 'e679f00c-7a2a-4673-af5d-88a6f4d8128e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal Dayanıklılık: Çocuk artık bir şeyi başaramadığında sizden hemen yardım istemiyor, önce birkaç kez kendi başına deniyor. Bu azmini destekleyin. "Çok çabaladığını görüyorum" demeniz, sonuçtan çok süreci sevmesini sağlar. 1000 güne yalnızca 40 gün kaldı!') WHERE id = '73811b23-1334-47b6-aa32-fe16ca9f7dfe';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuk artık "ben", "sen" ve "biz" zamirlerini doğru yerlerde kullanıyor. "Biz şimdi yemek mi yiyoruz?" diyerek kendisini ailenin aktif bir üyesi olarak hissediyor. Onunla konuşurken planlarınıza onu da dahil edin: "Gel, sofrayı birlikte kuralım". Bu, onun aidiyet ve sorumluluk duygusunu güçlendirir.') WHERE id = '0088ee7c-73a0-42ed-a073-c3d4d5a577af';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Merdiven özgürlüğü". Çocuk artık her basamağa bir adım atarak, ayaklarını sırayla değiştirerek ve yalnızca bir elinden tutulduğunda merdivenleri güvenle çıkıyor. Bu, kaba motor becerilerinin oldukça geliştiğini gösterir. Siz yalnızca yanında bulunarak ona manevi destek verin.') WHERE id = 'bf415e92-93fc-4c0c-8e41-d0e69018f7ba';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Hikâye oluşturma". Çocuk artık resimlere bakarak basit hikâyeler uyduruyor. "Kedi geldi, süt içti, uyudu" gibi ardışık cümleler, hafızası ile hayal gücünün birlikte çalıştığını gösterir. Ona ilgi çekici resimleri olan kitaplar verin ve "Burada neler oluyor?" diye sorun. Bu, onun yaratıcı düşünme becerisini harekete geçirir.') WHERE id = 'e900e935-8ccc-4908-bf87-10603eb74cda';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Hassas yerleştirme". Çocuk artık küçük oyuncak figürlerini yerleştirmeyi veya boncukları ipe dizmeyi daha az hata yaparak başarabiliyor. Bu dönemde parmak uçlarının hassasiyeti artar. Ona farklı dokulara sahip küçük nesnelerle, gözetiminiz altında oynayabileceği oyunlar sunun.') WHERE id = '6c732ec0-7e78-45c4-a464-029d46e20701';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız giyinme" ısrarı. Çocuk artık düğmesiz üstlerini veya pantolonunu kendi başına giymekte ısrar ediyor. "Ben kendim yapacağım!" dediği anlarda ona zaman tanıyın. Bu bağımsızlık girişimleri, gelecekteki öz güveninin ve kişisel sorumluluk duygusunun en güçlü temelidir. Küçük başarılarını "Bak, tek başına başardın!" diyerek kutlayın.') WHERE id = '3fe4a18c-cebd-45f6-88ed-6acbe7109fd0';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Nezaket kuralları". Çocuk artık "Lütfen", "Teşekkür ederim", "Rica ederim" gibi ifadeleri yalnızca tekrarlamıyor, amacına uygun şekilde kullanıyor. Sizin nazik davranışlarınız onun için en güçlü örnektir. Bu davranışlarını överek iletişim becerilerini pekiştirin.') WHERE id = 'e6b8bd35-5e9c-4328-a121-a6fecf7c7d62';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Zaman zarfları". Çocuk "sonra", "birazdan", "şimdi" sözcüklerini doğru yerlerde kullanmaya başlıyor. "Birazdan geleceğim" dediğinizde, zamanın geçeceğini anlıyor. Bu, çocuğun bekleme ve kendini düzenleme becerilerini geliştirir. Günlük rutinlerinizde bu sözcükleri sık sık kullanın.') WHERE id = 'eac1461c-042b-436c-8d00-465739e12f49';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topa vurma ve hedef". Çocuk artık topa yalnızca vurmakla kalmıyor, onu belirli bir yöne, örneğin iki oyuncağın arasından geçirmeye çalışıyor. Bu, el-göz ve ayak-göz koordinasyonunun eş zamanlı çalıştığını gösterir. Onunla evde bir "mini futbol" turnuvası düzenleyin.') WHERE id = '3ddf5bfb-d5a6-4b94-8ee2-f4ce76892d43';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Soyut sorular". Çocuk "Bulut nereden geliyor?", "Ay nereye gitti?" gibi sorular sorabilir. Yanıt verirken hayalî ve gerçek bilgileri dengeleyin: "Bulutlar uzaklardan gelip bize yağmur getiriyor". Bu tür sohbetler onun dünya görüşünü ve öğrenme isteğini inanılmaz ölçüde geliştirir.') WHERE id = '1a341992-7717-4fca-abe1-d703ab6a7a2f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal Dayanıklılık: Çocuk artık başarısızlığa karşı daha dayanıklıdır. Blokları devrildiğinde hemen ağlamaz, "Yeniden yapacağım" diyebilir. Bu mücadeleci ruhunu destekleyin. 970 günlük yolu geride bıraktık, 1000 güne yalnızca 30 gün kaldı! Siz bu yolculukta hem öğretmen hem de en yakın dostsunuz!') WHERE id = 'e1da111f-ccec-436b-a492-b6e924de37bf';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuk artık renkleri yalnızca "kırmızı" veya "mavi" olarak değil, koyu ve açık tonlarıyla da görsel olarak ayırt etmeye başlar. Ona farklı renklerde boya kalemleri verip "En koyu olanı bana ver" diyerek görsel analiz becerisini değerlendirin. Bu, hem dikkatini hem de estetik algısını geliştirir.') WHERE id = '1fa9d3d6-a970-457d-af04-c009e72b5e1b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Geri geri yürüme". Çocuk artık dengesini kaybetmeden geriye doğru birkaç adım atabilir. Bu hareket, beden farkındalığını ve mekânsal yön bulma becerisini güçlendirir. Onunla "Yengeç gibi yürüyelim" oyunu oynayın.') WHERE id = '21db9a7e-7c35-47c7-9f2e-7e03f72a88a3';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Kafiyeli sözcükler ve Şarkılar". Çocuk artık dinlediği şarkıların son sözcüklerini kafiyeli biçimde tamamlamayı çok sever. Bu, fonetik işitme becerisinin geliştiğini gösterir. Onunla birlikte şiirler okuyun ve sonunu tamamlaması için duraklayın. Bu, hem hafızasını güçlendirir hem de konuşma hızını düzenler.') WHERE id = '6ee138fb-22b9-41f6-a232-d405003097d3';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Boncukları ipe dizme". Çocuk artık büyük delikli boncukları veya makarnaları ipe dizmekte ustadır. Bu hareket hem sabır hem de parmakların ince koordinasyonunu gerektirir. Böylece gelecekteki yazma becerileri için kas hafızası geliştirir.') WHERE id = 'e27670af-3f91-498b-a727-68765b4a34c6';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız Hijyen" gelişimi. Çocuk artık ellerini yıkadıktan sonra kendi başına havluyla kurulayıp havluyu yerine asabilir. Bu küçük "tamamlama" davranışları, öz bakım sorumluluğunu artırır. Bu düzenli davranışını "Ne kadar da düzenlisin!" diyerek takdir edin.') WHERE id = '41467e61-a2ce-4e56-9659-81bc3b54b05e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Başkalarının duygularını anlama". Çocuk artık yüzünüzdeki üzüntüyü veya yorgunluğu fark edip "Ne oldu?" diye sorabilir. Bu, empatinin en saf hâlidir. Duygularınızı ona basit bir dille açıklayın: "Biraz yoruldum, gel birlikte dinlenelim". Bu, onun duygusal zekâsını besler.') WHERE id = '639f97f3-6003-448b-9622-c5dde4b5cec4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Sıralama ve Karşılaştırma". Çocuk artık 3-4 oyuncağını boyutlarına göre (küçükten büyüğe) sıralayabilir. Bu, erken matematiksel düşünmenin temelidir. Ona "En büyük ayıyı en başa koy" gibi görevler verin. Bu, hem görsel analiz yapmayı hem de dikkatini toplamayı öğretir.') WHERE id = '370bff62-25e0-4406-b269-39b56f69516b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyonda "Dinamik denge". Çocuk artık alçak bir ipin veya yere çizilmiş bir çizginin üzerinde "cambaz" gibi yürümeye ilgi gösterir. Bu, vestibüler sisteminin olgunlaştığını gösterir. Parkta bordürlerin üzerinde yürürken elinden tutarak bu cesaretini destekleyin.') WHERE id = '7d0f18e8-75ea-46a5-ae28-0011a1c178d0';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Zaman kavramı: Dün ve Yarın". Çocuk bu sözcükleri henüz tam olarak doğru zaman için kullanmasa da geçmişteki ve gelecekteki olayları ayırt etmeye çalışır. Günün sonunda onunla "Yarın nereye gideceğiz?" gibi sohbetler edin. Bu, planlama becerisini ve olaylar arasındaki zaman ilişkisini güçlendirir.') WHERE id = 'a8b25b83-9fde-45e1-b976-1cd3459165f2';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal dayanıklılık: Çocuk artık bir şeyi başaramadığında (örneğin, küpler devrildiğinde) hemen ağlamak yerine yeniden denemeye başlayabilir. Bu "mücadele ruhu", gelecekteki öğrenme başarısı için çok önemlidir. Ona "Çok çabaladığını görüyorum" diyerek sonucu değil, çabasını övün.') WHERE id = '0db561dc-233c-4544-804a-8f5b95ba51b9';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuk artık "Biz" kavramını anlamaya başlar. "Biz şimdi parka mı gidiyoruz?" diyerek kendisini ailenin ayrılmaz bir parçası olarak görür. Onunla konuşurken aile planlarınızı paylaşın: "Bugün biz anneanneye gideceğiz". Bu, çocukta aidiyet ve güven duygusunu güçlendirir.') WHERE id = 'cb75068e-4a47-4582-8cce-0e1abcdf18e0';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Merdiven bağımsızlığı". Çocuk artık her basamakta ayak değiştirerek ve yalnızca bir elinden tutulduğunda merdivenleri güvenle çıkabilir. Bu, kaba motor becerilerinin tamamen olgunlaştığını gösterir. Siz yalnızca yanında bulunarak ona manevi destek verin.') WHERE id = 'c4f997be-e1af-4807-8fcf-d6afc3087197';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Hikâye oluşturma". Çocuk artık resimlere bakarak basit hikâyeler uydurur. "Kedi geldi, süt içti, uyudu" gibi birbiriyle bağlantılı cümleler, hafızası ile hayal gücünün birleşimidir. Ona ilgi çekici resimleri olan kitaplar verin ve "Burada ne oluyor?" diye sorun. Bu, yaratıcı düşünme becerisini harekete geçirir.') WHERE id = '8a750939-d6ea-4327-ae01-fe2febf3e561';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Hassas yerleştirme". Çocuk artık küçük oyuncak figürlerini yerlerine koymayı veya boncukları ipe dizmeyi daha az hata yaparak başarabilir. Bu dönemde parmak uçlarının hassasiyeti artar. Ona farklı dokulara sahip küçük nesnelerle (gözetiminiz altında) oynayabileceği oyunlar sunun.') WHERE id = 'b81dacf6-43a1-47b5-b976-b04cc72c15b8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız giyinme" ısrarı. Çocuğunuz artık düğmesiz gömleklerini veya pantolonunu kendi başına giymekte ısrar ediyor. "Ben kendim!" dediği anlarda ona zaman tanıyın. Bu bağımsızlık girişimleri, gelecekteki özgüveninin ve kişisel sorumluluk duygusunun en güçlü temelidir. Küçük başarılarını "Bak, tek başına başardın!" diyerek kutlayın.') WHERE id = '5b370f66-ddd3-45df-8b72-80322e3b54c6';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Nezaket kuralları". Çocuğunuz artık "Lütfen", "Çok teşekkür ederim", "Rica ederim" gibi ifadeleri yalnızca tekrarlamıyor, amacına uygun şekilde kullanıyor. Sizin nazik davranışlarınız onun için en güçlü örnektir. Bu davranışlarını takdir ederek iletişim becerilerini pekiştirin.') WHERE id = 'fb257145-0061-4b1c-8bd6-415874362912';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Zaman zarfları". Çocuğunuz "sonra", "birazdan", "şimdi" sözcüklerini doğru yerlerde kullanmaya başlıyor. "Birazdan geleceğim" dediğinizde zamanın geçeceğini anlıyor. Bu, çocuğun bekleme ve kendini düzenleme becerisini geliştirir. Günlük rutinlerinizde bu sözcükleri sık sık kullanın.') WHERE id = '2d2fd92a-c54e-421a-b575-674a4add6e64';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topa vurma ve hedef". Çocuğunuz artık topa gelişigüzel vurmuyor, onu belirli bir yöne, örneğin iki oyuncağın arasından geçirmeye çalışıyor. Bu, el-göz ve ayak-göz koordinasyonunun eş zamanlı çalışmasıdır. Onunla evde bir "mini futbol" turnuvası düzenleyin.') WHERE id = '4639b4f7-f878-413c-9ed9-f5c72fb301e3';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Soyut sorular". Çocuğunuz "Bulut nereden geliyor?", "Ay nereye gitti?" gibi sorular sorabilir. Yanıt verirken hayal gücü ile gerçek bilgileri dengeleyin: "Bulutlar uzaklardan gelip bize yağmur getiriyor". Bu tür sohbetler onun dünya görüşünü ve öğrenme isteğini inanılmaz ölçüde geliştirir.') WHERE id = 'bc37e242-95d7-44a8-8a20-2eacd0325914';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal Dayanıklılık: Çocuğunuz artık başarısızlık karşısında daha dayanıklı. Küpleri devrildiğinde hemen ağlamıyor, "Yeniden yapacağım" diyebiliyor. Bu mücadeleci ruhunu destekleyin. 1000 güne yalnızca 10 gün kaldı! Siz bu muhteşem yolu çocuğunuzla el ele yürüdünüz. Aferin size!') WHERE id = 'a124273d-b639-4f61-aa7d-a589a92dd962';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '1000 günlük büyük maratonun son on gününe hoş geldiniz! Çocuğunuz artık benliğinin tamamen farkında ve "Ben büyüdüm" duygusuyla hareket ediyor. Onunla geçirdiğiniz 991 günü gözünüzün önünden geçirin; ilk adımı, ilk sözü... O artık hem fiziksel hem de zihinsel olarak başlı başına bir birey. Sizin sevginiz bu yapının en sağlam temelidir.') WHERE id = 'b5b8d286-f3be-458e-9da0-f739ba54a527';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel gelişimde "Karmaşık manevralar". Çocuğunuz artık koşarken aniden durabiliyor, yön değiştirebiliyor veya bir engelin üzerinden atlayabiliyor. Bu, sinir sisteminin ve kas koordinasyonunun olgunlaştığını gösterir. Onunla açık havada hareketli oyunlar oynamaya devam edin.') WHERE id = '40ef129f-5b1b-4e7a-8bf0-78a6953a2417';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Mantıksal diyalog". Çocuğunuz artık sizinle tartışabiliyor: "Uyumak istemiyorum, çünkü oyunum bitmedi". Bu yalnızca inatçılık değil, kendi düşüncesini gerekçelendirme becerisidir. Ona "Haklısın, ama birazdan hava kararacak" gibi mantıklı açıklamalar yaparak karşılıklı saygıyı aşılayın.') WHERE id = 'b9aae384-2df5-41c3-b46c-488d1b02a6ae';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Yaratıcı resimler". Çocuğunuz artık yalnızca çizgiler değil, "insan" (genellikle bir daire ve çizgilerden oluşan çöp adam), "ev" veya "güneş" çizmeye çalışıyor. Bu resimler, zihnindeki sembollerin kâğıda aktarılmış hâlidir. Bu "sanat eserlerini" mutlaka saklayın.') WHERE id = '28f47857-a1db-40ef-a9e2-553a55c8a841';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışlarda "Şefkat". Çocuğunuz artık sizin yorgun olduğunuzu veya bir arkadaşının ağladığını fark ettiğinde yanına yaklaşıp onu teselli etmeye çalışıyor. Bu, duygusal zekânın (EQ) en ileri göstergelerinden biridir. Onun bu tertemiz kalbi, sizin ona gösterdiğiniz şefkatin bir yansımasıdır.') WHERE id = 'ad204761-7be7-4b3d-9813-46b7f3ddfbf5';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Sayı ve sembol sentezi". Çocuğunuz artık rakam sembollerini (1, 2, 3) görsel olarak tanıyabilir ve bunları miktarlarla eşleştirebilir. Ona "Burada 3 tane elma var, bana ''3'' rakamını göster" gibi küçük görevler verin. Bu, okul öncesi hazırlığın en eğlenceli ve önemli aşamalarından biridir.') WHERE id = '277f876e-8768-4106-82f9-f67a9aa287de';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Bağımsızlık zirvede". Çocuğunuz artık bisiklete binmek, salıncakta kendi başına sallanmak veya yüksek kaydıraklardan kaymak için yeterince cesur. Güvenliğini sağlayın, ancak ona engel olmayın. Kendi gücüne güvenmesi, karakterini güçlendirir.') WHERE id = '27b9a0e5-6b83-4460-8a15-0df9cab1dff0';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Zamanın derinliği". Çocuğunuz artık "Ben bebekken..." veya "Büyüyünce..." gibi cümleler kurarak zaman çizgisindeki yerini anlamaya başlıyor. Ona bebeklik fotoğraflarını gösterin ve ne kadar yol katettiğini anlatın. Bu, çocuğun kişisel geçmişinin ve benlik bilincinin (self-identity) tam olarak şekillenmesini sağlar.') WHERE id = '3439184d-c674-4353-b4d8-24d477730a8a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Büyük finale 1 gün kaldı! Bugün geriye bakın ve kendinizle gurur duyun. Çocuğunuzun beyin gelişiminin 80%-i bu ilk 1000 günde tamamlandı. Siz ona konuşmayı, sevmeyi, güvenmeyi ve dünyayı keşfetmeyi öğrettiniz. Yarın çocuğunuzun hayatında yeni ve parlak bir sayfa açılıyor. Siz muhteşem bir ANNESİNİZ!') WHERE id = '6f7bcab0-f835-4b32-baa1-c34bfb4bf5a9';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'TEBRİKLER! İlk 1000 günü başarıyla tamamladınız! 🌟 Bu, bir insanın hayatındaki en önemli gelişim dönemidir. Çocuğunuz artık bebeklikten çıktı ve dünyayı fethetmeye hazır küçük bir kahraman oldu. Anacan ailesi olarak her adımda yanınızdaydık ve bu başarıyı sizinle paylaşıyoruz. Bugün büyük bir bayram – çocuğunuzun ve sizin zafer bayramınız!') WHERE id = 'df76a0b6-eddc-484e-b6f0-24845f214e66';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Yer zarfları". Çocuk "yanında", "arkasında", "altında", "üstünde" kavramlarını artık tam olarak anlar ve kullanır. "Top kanepenin altında" diyorsa, mekânsal yönelim becerisi tamamen gelişmiş demektir. Onunla "Sakla-bul" oynayarak bu kavramları daha da pekiştirin.') WHERE id = '64ca65c7-1a28-48d4-beca-77b3f217471c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal dayanıklılık: "Sabır testi". Çocuk artık istediği bir şey için birkaç dakika beklemesi gerektiğini anlar ve hemen ağlamaya başlamaz. Böyle anlarda ona "Beklediğin için çok teşekkür ederim, bu büyüdüğünün bir göstergesi" deyin. Siz harika bir yol arkadaşısınız!') WHERE id = 'd29729c2-dd1d-4552-9d6e-3a6745ad9680';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuk artık renkleri ve şekilleri birleştirerek dünyayı tanımlar. "Bana şu sarı kare bloğu ver" diyorsa, bu, beyninin aynı anda birden fazla özelliği işlediğini gösterir. Bu becerisini günlük hayatta küçük görevlerle (örneğin, "mavi çoraplarını bul") destekleyin.') WHERE id = '6e9a3917-235a-4638-821e-7544b6f6fd44';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel gelişimde "Dinamik denge". Çocuk artık tek ayağının üzerinde 5 saniyeye kadar durabilir. Bu, vestibüler sistemin (denge merkezi) ve bacak kaslarının güçlendiğini gösterir. Onunla "Leylek" oyunu oynayarak kimin daha uzun süre ayakta kalabildiğini görün.') WHERE id = 'bf8d8f80-94a0-4e9e-beaa-a9027d0e8ae4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Neden-sonuç ilişkileri". Çocuk artık "Eğer... o zaman..." türündeki cümleleri anlamaya başlar. "Eğer oyuncaklarını toplarsan çizgi film izleyebiliriz" dediğinizde koşulu anlar. Bu, hem mantıksal düşünmenin hem de öz disiplinin (self-discipline) gelişmesi için önemli bir adımdır.') WHERE id = 'b1f57847-eeec-4119-b2fc-2905b91fb26b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Makasla ilk deneyimler". Çocuk artık kâğıdı (güvenli çocuk makasıyla) düz bir çizgi boyunca kesmeye ilgi gösterir. Bu hareket hem el-göz koordinasyonunu hem de parmakların ince motor becerilerini en üst düzeye taşır. Onu gözetimsiz bırakmayın, ancak özgürce denemesine de engel olmayın.') WHERE id = 'bc3bff7e-368e-485f-8abd-ee144e6a6477';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Hayalî oyun arkadaşları". Çocuk artık tek başına oynarken de yüksek sesle konuşur ve oyuncaklarına roller verir. Bu, "Benmerkezci konuşma"dır ve çocuğun kendi davranışlarını sözcüklerle düzenlemesine yardımcı olur. Bu "monologlarını" dinleyerek iç dünyasında neler olup bittiğini anlayabilirsiniz.') WHERE id = '9f4b387f-964e-4bb9-856d-1ac035b357f4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız seçim: Karar verme". Çocuk artık ne yemek istediğini veya hangi oyunu oynayacağını kesin olarak bilir. Ona her gün iki alternatif sunun: "Elma mı istersin, yoksa muz mu?". Bu, ona kendi hayatı üzerinde kontrol sahibi olduğu hissini verir ve öz güvenini artırır.') WHERE id = '7022c99f-3026-41d3-8d24-5d2da8ff257d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '1000 günlük büyük maratonun ardından ilk günümüz! Çocuğunuz artık 4. yaşına adım atıyor. Bu dönemde "Neden?" soruları yeni bir boyut kazanır. Çocuğunuz yalnızca bilgi edinmekle kalmaz, olaylar arasındaki mantıksal bağlantıyı da anlamaya çalışır. Sabırla yanıt verin; çünkü bu sorular onun zihinsel gelişiminin temelini oluşturur.') WHERE id = '458401f2-485d-418a-8b89-143f552eb250';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel gelişimde "Dinamik manevralar". Çocuğunuz artık koşarken keskin dönüşler yapabilir veya engellerin çevresinden hızla geçebilir. Bu, beden kontrolünün ileri düzeyde olduğunun bir göstergesidir. Onun için bahçede küçük engel yarışları düzenleyin.') WHERE id = '1242feeb-5e2f-4d55-aa93-952aedfbe568';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Karmaşık zamanlar". Çocuğunuz artık "yapmıştım", "yapacağım" gibi karmaşık zaman yapılarını konuşmasına dahil eder. Onunla geçmişte yaşanan olaylar hakkında konuşun: "Dün anneanneye gittiğimizde ne oldu?". Bu, hem hafızasını hem de konuşmasındaki dil bilgisi doğruluğunu güçlendirir.') WHERE id = '5e199122-f8a1-4104-82fd-2c91af60c12f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Simetri denemeleri". Çocuğunuz kâğıdı tam ortadan katlamaya veya çizdiği resimdeki ayrıntıları (örneğin insanın iki gözü ve iki kolu) daha doğru yerleştirmeye çalışır. "Bak, iki kolunu da çizmişsin!" diyerek onun bu görsel dikkatini vurgulayın.') WHERE id = '9dfe80c5-1c6a-4ec4-852c-1433440d5b52';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Kuralların içselleştirilmesi". Çocuğunuz artık siz söylemeden bazı kuralları hatırlar: "Yemekten önce ellerimi yıkayayım mı?". Bu, dış disiplinin öz disipline dönüşmeye başlamasıdır. Bu bağımsız sorumluluk davranışını mutlaka takdir edin; karakter gelişimi açısından büyük bir adımdır.') WHERE id = '5760ce33-81a1-4f8c-a7a0-f30c320a688a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Ben ve arkadaşım". Çocuğunuz artık diğer çocuklarla yalnızca yan yana değil, ortak bir senaryo üzerinden oynamaya başlar (örneğin, "Sen anne ol, ben çocuk olayım"). Bunlar, sosyal iş birliği ve rol paylaşımına ilişkin ilk ciddi deneyimlerdir.') WHERE id = 'e6c24a0b-d760-47b5-90b8-f6d05b42625b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Sınıflandırma becerisi". Çocuğunuz nesneleri aynı anda iki özelliğe göre gruplandırabilir: "hem kırmızı hem de küçük olanlar". Ona karışık oyuncaklar verin ve "Bütün küçük arabaları buraya topla" deyin. Bu, beynindeki mantıksal filtreleme sistemini geliştirir.') WHERE id = '083c5f31-3fe0-44d9-b65b-c4b92bb36ae4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Üç tekerlekli bisiklette bağımsızlık". Çocuğunuz artık gidonu kontrol ederken aynı anda pedalları da ritmik biçimde çevirebilir. Bu, alt ve üst beden koordinasyonunun kusursuz uyumudur. Park gezilerini daha hareketli hâle getirmenin zamanı geldi.') WHERE id = 'e81ab935-f108-46cd-a88f-e53e09ed924f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Zıt anlamlı kelimelerin çeşitlenmesi". Çocuğunuz artık "hızlı-yavaş", "karanlık-aydınlık", "boş-dolu" gibi soyut karşıtlıkları anlıyor. Ona boş ve dolu birer bardak gösterip aralarındaki farkı sorun. Bu, çevresindeki dünyayı karşılaştırmalı olarak analiz etme becerisini güçlendirir.') WHERE id = 'a89f9de3-ed84-4cfa-95a8-cf4c5d345de7';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Yapboz ustalığı". Çocuğunuz artık 10-12 parçalı karmaşık yapbozları, resmin kenar ve orta kısımlarını ayırt ederek tamamlayabiliyor. Bu, hem görsel hafızasını hem de parmaklarının hassas hareket kabiliyetini geliştirir. Yapamadığında ona sakin bir ses tonuyla ipuçları verin.') WHERE id = '81c4bfcb-e5df-4929-b621-91e622f18ac6';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız temizlik ve yardım". Çocuğunuz artık sofrayı toplarken kendi tabağını götürmek ve kırıntıları silmek gibi işleri büyük bir hevesle yapıyor. Ona boyuna uygun temizlik malzemeleri verin. Bu, aile içinde sorumluluk ve aidiyet duygusunu güçlendirir. Kendi emeğinin sonucunu görmek onu çok mutlu eder.') WHERE id = '9ef3f34d-a63f-4f49-9005-c854d4303909';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Kurallar ve Sınırlar". Çocuğunuz artık "hayır" sözünün ardındaki mantığı biraz daha iyi anlıyor, ancak yine de sınırları test etmeyi seviyor. Sabırlı ve tutarlı olmanız ona güven duygusu verir. Kuralları her zaman aynı şekilde uygulamaya çalışın.') WHERE id = 'c4d24c3e-4601-4235-8cdc-f39b3aa35149';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Sıra sayıları". Çocuğunuz artık "birinci", "ikinci", "sonuncu" kavramlarını anlıyor. Arabaları arka arkaya dizip "Hangi araba birinci?" diye sorun. Bu, sıralama becerisini ve matematiksel düşünme yeteneğini geliştirir. Yarışlarda "Birinci sen geldin!" demeniz onun için büyük bir motivasyon kaynağıdır.') WHERE id = 'b0d3eed0-e639-4528-9c81-8601b70e54bd';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Geriye ve yana doğru yürüme". Çocuğunuz artık farklı yönlerde çevik bir şekilde hareket edebiliyor. Onunla "Ayna oyunu" oynayın: Siz yana doğru bir adım atın, o da sizi taklit etsin. Bu hem eğlencelidir hem de vücut koordinasyonunu yeni bir düzeye taşır.') WHERE id = 'da0e2216-17ef-49f2-83ad-1599f6a6e332';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Soyut soruların derinleşmesi". Çocuğunuz "Bulutlar nereye gidiyor?", "Yıldızlar neden geceleri çıkıyor?" gibi sorularla sizi şaşırtabilir. Cevap verirken onun hayal gücünü de harekete geçirin: "Sence yıldızlar şimdi ne yapıyor?". Bu, yaratıcı düşünme becerisini besler.') WHERE id = '1f153d5c-5da7-4c69-b731-2dc34e06cb4f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal Dayanıklılık: "Paylaşmanın sevinci". Çocuğunuz artık oyuncağını veya şekerlemesini gönüllü olarak paylaştığında sizin sevincinizi görüyor ve bunu tekrarlamak istiyor. Onun bu cömertliğini "Arkadaşını mutlu ettiğin için çok teşekkür ederim" diyerek özellikle vurgulayın. 1040 günü başarıyla tamamladık – siz harika bir annesiniz!') WHERE id = '3c9e08eb-1969-4283-90ec-97d2de26fd19';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız giyinme: Fermuar ve Düğme". Çocuğunuz artık büyük düğmeleri açmakta ve fermuarı (başlattıktan sonra) yukarı çekmekte ustalaştı. Ona "Haydi, kendin dene" diyerek sabırla bekleyin. Kendi başına giyinebilmesi, çocuğunuzun "Ben yapabilirim" hissini ve özgüvenini inanılmaz ölçüde artırır.') WHERE id = '9893a146-5d99-48e6-ae6a-1f46520795f5';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Paylaşmanın mantığı". Çocuğunuz artık başka bir çocuğun elindeki oyuncağı hemen almak yerine "ver" diyerek beklemeye çalışır. Bu, öz düzenleme (self-regulation) becerisinin güçlendiğini gösterir. Bu sabırlı davranışını gördüğünüzde onu mutlaka "Sıranı beklediğin için çok teşekkür ederim" diyerek övün.') WHERE id = '71a96327-cfe2-4ab5-bb79-d332a1ff5de4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Genel ve Özel". Çocuğunuz artık elma, armut ve muzun hepsinin "meyve" olduğunu anlar. Ona farklı nesneler gösterin ve "Bunların hepsine birlikte ne diyoruz?" diye sorun. Kategorilerle düşünmek, beynindeki bilgi depolama sisteminin daha düzenli hâle gelmesini sağlar.') WHERE id = 'f440da85-66a5-444d-9191-5dceb0b51d20';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topu omuz üzerinden atma". Çocuğunuz artık topu yalnızca yere bırakmakla kalmaz, omzunun üzerinden ileriye, belirli bir hedefe doğru atabilir. Bu, tüm vücudun koordinasyonunu gerektirir. Onunla parkta "hedefe atma" oyunları oynayın.') WHERE id = '5a9ea9e5-b06c-4aa9-b965-a6664f7442e8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Konum ve Yön". Çocuğunuz "sağ" ve "sol" kavramlarını henüz tam olarak ayırt edemese de "ileri", "geri", "yukarı" ve "aşağı" komutlarını doğru şekilde yerine getirir. Onunla "Robot oyunu" oynayın: "İki adım ileri, bir adım geri!". Bu oyun hem eğlencelidir hem de mekânsal yönelim becerisini güçlendirir.') WHERE id = '6ef1e101-45d4-451a-8710-b32b9878cd2e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal Dayanıklılık: "Başarısızlıkla başa çıkma". Çocuğunuz artık yaptığı küpler devrildiğinde hemen ağlamaz, "Yeniden yapacağım" diyebilir. Bu mücadeleci ruhunu destekleyin. 1030 günü geride bıraktık – çocuğunuz artık küçük bir kahraman!') WHERE id = '1293c75f-beda-4513-88cc-b7951ec10777';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık nesneleri aynı anda iki özelliğe göre (örneğin hem rengine hem de şekline göre) ayırabilir. Ona "Bana bütün küçük kırmızı arabaları ver" dediğinizde bunu yapabiliyorsa, bu bilişsel gelişiminde yeni bir aşamaya ulaştığını gösterir. Günlük ev işlerinde ona buna benzer küçük "seçme" görevleri verin.') WHERE id = 'fa3d103a-9bc8-44ef-b8d5-cab5337e7b60';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Hedefe atlama". Çocuğunuz artık yere çizilmiş bir dairenin veya renkli bir hedefin ortasına atlamaya çalışır. Bu, hem denge hem de mekânsal mesafeyi hesaplama becerisini geliştirir. Parkta onunla "taştan taşa atlama" oyunu oynayın.') WHERE id = '4bbc0ebb-e4d4-4fb1-9a60-923e8fae76b3';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Hacim ve miktarın korunumu". Çocuk henüz uzun ve dar kaptaki suyun geniş kaptaki sudan daha fazla olduğunu düşünebilir. Bu, "Piaget" evresine uygun, normal bir durumdur. Onunla su oyunları oynayarak suyu farklı kaplara boşaltın. Bu, mantığı deneyim yoluyla kavramasını hızlandırır.') WHERE id = '63894550-7c88-4d80-827d-abe697cce597';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "İki ayakla ileri sıçrama". Çocuk artık engellerin (örneğin, yerdeki bir ipin) üzerinden iki ayağıyla aynı anda atlayabilir. Bu hareket, tüm vücudun koordinasyonunu ve patlayıcı gücü gerektirir. Onun için güvenli alanlarda küçük engur parkurları oluşturun.') WHERE id = 'cab49b1b-46a8-46fe-9575-6cef46f13add';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Dil gelişiminde "Soyut zaman kavramı". Çocuk artık "Sabah", "Öğle" ve "Akşam" arasındaki farkları rutinler aracılığıyla kavrar. "Akşam baban geldiğinde..." dediğinizde, günün o zaman dilimini zihninde canlandırır. Günlük rutininize bağlı kalmanız, bu zaman algısını güven duygusuyla ilişkilendirmesine yardımcı olur.') WHERE id = '50a38f0a-e830-42a7-9b23-0d529496ee7f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal olgunluk: "Özür dilerim" sözünün anlamı. Çocuk artık bilerek veya istemeden birini incittiğinde "Özür dilerim" demenin sosyal önemini anlar. Ona her zaman örnek olun; hata yaptığınızda ondan özür dileyin ki o da bu davranışı bir zayıflık değil, güç göstergesi olarak görsün.') WHERE id = 'f7b6ee04-7015-4382-abaa-03462e452408';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuk artık resimlere bakarak basit hikâyeler uydurur. "Ayı ormana gitti, acıktı ve bal yedi" gibi birbiriyle bağlantılı cümleler kurması, mantıksal sıralamayı kavradığını gösterir. Ona ilgi çekici resimler içeren kitaplar verin ve "Sence bundan sonra ne olacak?" diye sorun. Bu, yaratıcı hayal gücünü en üst düzeye çıkarır.') WHERE id = '5b5539ed-db72-44da-bf5f-8b147bfb9b43';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Merdiven bağımsızlığı". Çocuk artık merdivenleri her basamağa sırayla bir ayağını koyarak ve yalnızca bir elinizden tutarak (ya da hiç tutunmadan) güvenle inebilir. Bu, kaba motor becerilerinin iyice olgunlaştığını gösterir. Siz yalnızca yanında bulunarak ona manevi destek verin.') WHERE id = 'e1ab27cc-4713-481c-b52f-32935f62d3d2';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Dil gelişiminde "Soru-cevap zinciri". Çocuk artık sorularınıza yalnızca "evet/hayır" diye değil, tam cümlelerle yanıt verir. "Bugün parkta kiminle oynadın?" sorusuna ayrıntılı cevap verebilir. Onunla konuşurken "O ne renkti?", "Neler yaptınız?" gibi devam soruları sorarak dil gelişimini destekleyin.') WHERE id = '7d186d1a-0812-440c-b07e-ee9ed0da127d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Daha hassas boyama". Çocuk artık küçük şekillerin sınırlarını da fark eder ve boyarken çizgilerin dışına fazla çıkmamaya çalışır. Bu, el kaslarını kontrol etme becerisinde büyük bir ilerlemedir. Ona farklı kalınlıklarda boya kalemleri vererek denemeler yapmasına olanak tanıyın.') WHERE id = 'a7b0a891-2fdb-4521-b60b-98a992dcf545';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Soyut soruların zirvesi". Çocuğunuz artık "Rüzgâr neden esiyor?", "Güneş uyumaya nereye gidiyor?" gibi varoluş ve doğa olayları hakkında sorular soruyor. Yanıt verirken hayal gücünüzü de kullanın: "Güneş yoruldu, yarın bizi yeniden uyandırmak için dinlenmeye gidiyor". Bu, onun dünyaya bakışını ve öğrenme isteğini besler.') WHERE id = 'fdfb7732-94cf-4e6c-8519-4e6877b4ad89';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal Olgunluk: "Başkasının duygularını kabul etmek". Çocuğunuz artık sizin yorgun olduğunuzu veya başka bir çocuğun incindiğini fark ettiğinde "Ne oldu?" diye soruyor ve teselli etmeye çalışıyor. Bu, onun şefkatli bir birey olarak geliştiğini gösterir. Siz harika bir annesiniz!') WHERE id = '9721a15c-607b-4236-9999-231bdd0b4e99';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık "önce" ve "sonra" sıralamasını daha iyi kavrıyor. "Kıyafetlerini giy, sonra dışarı çıkalım" dediğinizde, ikinci eylemin bir ödül olduğunu anlıyor. Bunlar, çocukta sabır ve planlama becerisinin ilk tohumlarıdır. Günlük rutinler sırasında bu sıralamaları ona sık sık hatırlatın.') WHERE id = '2add65f7-d33c-4b48-a1e7-f388a5549421';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel gelişimde "Tırmanma ustalığı". Çocuğunuz artık parktaki merdivenlere veya evdeki güvenli yüksekliklere daha özgüvenli bir şekilde tırmanıyor. Bu, hem kol hem de bacak kaslarının eş zamanlı çalışmasını sağlar. Her zaman yakınında olun, ancak kendi gücünü sınamasına da fırsat verin.') WHERE id = '25d5eedf-59a2-4e4e-8131-39a811d36fe6';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Mantıksal bağlantılar". Çocuğunuz artık iki durumu tek bir cümlede birleştiriyor: "Hava soğuk, ceketini giy". Bu, onun yalnızca taklit etmediğini, aynı zamanda düşündüğünü de gösterir. Bu mantıklı çıkarımlarını "Evet, haklısın" diyerek onaylayın ki kendi düşüncelerini ifade etmeye daha fazla heveslensin.') WHERE id = '90469c76-8fc0-41db-a7e9-3862f12f4d6b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Kâğıdı şekillendirme". Çocuğunuz artık kâğıt katlamaya veya basit şekillerde kesmeye (çocuklara uygun büyük makaslarla ve gözetim altında) ilgi gösterebilir. Bu hareketler, parmak kaslarının kontrolünü yeni bir seviyeye taşır. Renkli kâğıtlarla çalışabilmesi için ona uygun bir ortam hazırlayın.') WHERE id = '8f149cc4-a06e-4928-a8cb-2b953480c3af';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Rol oyunlarının karmaşıklaşması". Çocuğunuz artık "doktor", "aşçı" veya "şoför" rolüne giriyor. Bu oyunlar sayesinde çevresindeki insanların görevlerini öğreniyor ve empati kuruyor. Oyunlarına katılın ve size verdiği "role" uygun davranın.') WHERE id = 'c9bd395e-c3c2-46e2-abf3-1f924d619000';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız temizlik" alışkanlığı. Çocuğunuz artık ellerini yıkarken sabunlama ve durulama işlemlerini neredeyse tek başına yapabiliyor. Hijyen alışkanlıklarının bu yaşta pekişmesi çok önemlidir. Bu süreçten keyif alabilmesi için ona boyuna uygun basamaklı bir tabure (step stool) sağlayın.') WHERE id = 'dd1b7d3a-2552-45df-81c5-cf8e1914b882';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '35. aya adım atıyoruz! Çocuğunuz artık "iki aşamalı" düşünceden "üç aşamalı" görevlere geçiyor. "Oyuncağı al, kutuya koy ve kapağını kapat" dediğinizde sıralamayı bozmadan yapabiliyorsa bu, çalışma belleği (working memory) açısından büyük bir başarıdır. Gün içinde ona küçük ve mantıklı, birbirini takip eden görevler vererek bu becerisini geliştirin.') WHERE id = 'b4ed41fc-fc60-439e-82df-81e0242123d3';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Hızlı koşma ve manevra". Çocuğunuz artık koşarken önündeki engeli gördüğünde hızını azaltmadan etrafından dolaşabiliyor. Bu, beden farkındalığının (proprioception) tam olarak geliştiğini gösterir. Parkta "engelli koşu" yarışları düzenleyerek enerjisini faydalı bir yöne kanalize edin.') WHERE id = '140764ec-2a00-4bc6-b514-5e093357430f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Karşılaştırma dereceleri". Çocuğunuz artık "daha büyük", "en küçük", "çok lezzetli" gibi ifadeleri doğru yerlerde kullanıyor. Nesneleri karşılaştırarak onunla sohbet edin: "Bu elma mı daha tatlı, yoksa diğeri mi?". Sıfatların karşılaştırma derecelerini öğrenmesi, betimleyici dilini zenginleştirir ve düşüncelerini daha net ifade etmesini sağlar.') WHERE id = '5868f762-ea68-431f-855d-54c5a04efe50';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Heykel yapma". Çocuğunuz artık oyun hamuru veya kinetik kumla oynarken bunları yalnızca sıkmakla kalmıyor, "top", "yılan" veya "ekmek" gibi tanınabilir şekiller yapıyor. Bu, hem yaratıcı düşünme becerisini geliştirmek hem de parmak uçlarındaki küçük kasları güçlendirmek için harika bir egzersizdir.') WHERE id = '060a9ae6-7e66-446f-800a-a74eb2d502d9';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız giyinme: Ters-yüz ayrımı". Çocuğunuz artık gömlek veya pantolonun tersini ve yüzünü, ayakkabıların sağını ve solunu (bazen hata yapsa da) ayırt etmeye çalışıyor. Ona küçük ipuçları verin: "Bak, resimli taraf öne geliyor". Bu, ayrıntılara odaklanmasını ve öz bakım becerilerini geliştirmesini sağlar.') WHERE id = 'a1a89564-b6bb-483a-bd10-bb44b24484a4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Takım ruhu". Çocuğunuz artık diğer çocuklarla ortak bir hedef için (örneğin büyük bir kale yapmak için) birlikte oynayabiliyor. Bu, "Paralel oyun"dan "İş birliğine dayalı oyun"a geçiştir. Diğer çocuklarla nasıl iletişim kurduğunu gözlemleyin ve zorlandığı anlarda sosyal bir "köprü" kurmasına yardımcı olun.') WHERE id = '999ddf88-03eb-4dd0-856d-79ce3e7385df';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Sayı ve miktar eşleştirmesi". Çocuğunuz 1''den 5''e kadar sayabiliyor ve artık "3" rakamını gördüğünde 3 tane oyuncağı ayırıp koyabiliyor. Bu, matematiksel düşünmenin en önemli aşamalarından biridir. Günlük hayatta "Bana 2 tane kaşık ver" gibi görevlerle bu bağlantıyı güçlendirin.') WHERE id = '8193ed91-5f04-4955-a4b1-522d5a941870';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Yukarıdan atılan topu yakalama". Çocuğunuz artık kendisine doğru yavaşça atılan büyük bir topu iki eliyle yakalamaya çalışıyor. Bu hareket hem el-göz koordinasyonu hem de tepki hızı gerektirir. Onunla yakın mesafeden "topu yakala" oyunu oynayın.') WHERE id = '575cf871-23de-446e-8398-4dd4c0ff6773';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Farklı olanı bulma". Çocuk artık bir grup nesnenin içinden farklı olanı (örneğin, arabaların arasındaki elmayı) görsel olarak seçebilir. Bu, analiz becerisini geliştirir. Evde onun için basit "Hangisi farklı?" oyunları hazırlayın. Bu oyunlar, gelecekteki matematik ve mantık çalışmalarına harika bir hazırlıktır.') WHERE id = 'f8163db2-8f81-44fa-bc05-1057d8b42f15';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Tek ayak üzerinde durma denemeleri". Çocuk artık birkaç saniyeliğine de olsa bir ayağını yerden kaldırıp dengesini korumaya çalışır. Bu, vücudunun ağırlık merkezini tanıması açısından önemlidir. Onunla "Leylek oyunu" oynayın ve kimin daha uzun süre ayakta kalabildiğine bakın.') WHERE id = '0dbea1ae-3808-4d99-b129-68ed1447a173';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Duygu ifadeleri". Çocuk artık üzgün, neşeli veya korkmuş olduğunu kelimelerle ifade edebilir: "Ben korktum" veya "Ben neşeliyim". Duyguları adlandırmak, çocuklarda duygusal zekânın temelini oluşturur. Duygusunu dile getirdiğinde onu dinleyin ve "Evet, seni anlıyorum" diyerek hislerini kabul edip doğrulayın.') WHERE id = '384f5938-24c1-4dc2-8691-403780565471';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Hayal gücünün etkisi: "Sembolik düşünme". Çocuk bir sopayı "at" olarak hayal edip dörtnala koşuyormuş gibi gezebilir. Bu, bir nesnenin başka bir şeyi temsil edebileceğini anlama becerisidir. Bu beceri, gelecekte okuma ve matematik (sembolleri anlama) açısından çok önemlidir. Siz harika bir rehbersiniz!') WHERE id = '94697180-1105-4fe0-9d68-ffdaab53705e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuk artık "ben", "sen" ve "biz" zamirlerini doğru şekilde kullanır. "Biz şimdi yemek mi yiyoruz?" diyerek kendini ailenin aktif bir üyesi gibi hisseder. Onunla konuşurken onu da planlarınıza dahil edin: "Hadi, sofrayı birlikte kuralım". Bu, aidiyet ve sorumluluk duygusunu güçlendirir.') WHERE id = '38010093-f42b-4818-a3db-81219f590eee';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Merdiven bağımsızlığı". Çocuk artık merdivenleri, her basamağa sırayla bir ayağını koyarak ve yalnızca bir elinden tutulduğunda güvenle çıkar. Bu, kaba motor becerilerinin büyük ölçüde olgunlaştığını gösterir. Sizin yalnızca yanında bulunmanız bile ona manevi destek verir.') WHERE id = '8503d4e9-2c78-4879-9d8c-ef7c6d2a467c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Hikâye oluşturma". Çocuk artık resimlere bakarak basit hikâyeler uydurur. "Kedi geldi, süt içti, uyudu" gibi birbiriyle bağlantılı cümleler, hafızasıyla hayal gücünün birleştiğini gösterir. Ona ilgi çekici resimleri olan kitaplar verin ve "Burada neler oluyor?" diye sorun. Bu, yaratıcı düşünme becerisini harekete geçirir.') WHERE id = 'ebe63eb5-d3b9-410d-8ddc-267b97751075';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Hassas yerleştirme". Çocuk artık küçük oyuncak figürlerini yerleştirmeyi veya boncukları ipe dizmeyi daha az hata yaparak başarır. Bu dönemde parmak uçlarının hassasiyeti artar. Ona farklı dokulara sahip küçük nesnelerle gözetiminiz altında oynayabileceği oyunlar sunun.') WHERE id = '9acc3fd3-37ec-4b80-9709-ac31444a2801';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız giyinme" ısrarı. Çocuğunuz artık düğmesiz tişörtlerini veya pantolonunu kendi başına giymekte ısrar ediyor. "Ben kendim!" dediği anlarda ona zaman tanıyın. Bu bağımsızlık çabaları, gelecekteki özgüveninin ve kişisel sorumluluk duygusunun en güçlü temelidir. Küçük başarılarını "Bak, tek başına başardın!" diyerek kutlayın.') WHERE id = '48d41fa6-6f48-4a84-a2b6-f82cae4ce209';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışlarda "Nezaket kuralları". Çocuğunuz artık "Lütfen", "Teşekkür ederim", "Rica ederim" gibi sözleri yalnızca tekrarlamıyor, bilinçli olarak kullanıyor. Sizin nazik davranışlarınız onun için en güçlü örnektir. Bu davranışlarını överek iletişim becerilerini pekiştirin.') WHERE id = 'fe3ec85d-8b47-408d-a0ad-870b3b58db94';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Zaman zarfları". Çocuğunuz "sonra", "birazdan", "şimdi" sözcüklerini doğru yerlerde kullanmaya başlıyor. "Birazdan geleceğim" dediğinizde zamanın geçeceğini anlıyor. Bu, çocuğun bekleme ve kendini düzenleme becerisini geliştirir. Günlük rutinlerinizde bu sözcükleri sık sık kullanın.') WHERE id = 'df8b2f32-9f00-4805-8e4c-c754c399be31';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topa vurma ve hedef". Çocuğunuz artık topa yalnızca vurmuyor, onu belirli bir yöne, örneğin iki oyuncağın arasından geçirmeye çalışıyor. Bu, el-göz ve ayak-göz koordinasyonunun eş zamanlı çalışmasıdır. Onunla evde bir "mini futbol" turnuvası düzenleyin.') WHERE id = '852439ac-fd00-4ba1-aa13-d519b9407d5f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Soyut sorular". Çocuğunuz "Bulut nereden geliyor?", "Ay nereye gitti?" gibi sorular sorabilir. Yanıt verirken hayal gücüyle gerçek bilgileri dengeleyin: "Bulutlar uzaklardan gelip bize yağmur getiriyor". Bu tür sohbetler onun dünyaya bakışını ve öğrenme isteğini inanılmaz ölçüde geliştirir.') WHERE id = 'fe4cb6a5-1e61-4aaa-9066-7165c1ab72dd';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal dayanıklılık: Çocuğunuz artık başarısızlıklara karşı daha dirençli. Blokları devrildiğinde hemen ağlamıyor, "Yeniden yapacağım" diyebiliyor. Bu mücadeleci ruhunu destekleyin. 1070 günü geride bıraktık, 3 yaşını doldurmasına çok az kaldı! Siz bu yolculukta hem öğretmeni hem de en yakın dostusunuz!') WHERE id = '39f0d5e2-0187-4785-9bb9-453ef9250d3e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık kendini diğer çocuklarla karşılaştırmaya başlıyor: "Ben ondan daha hızlı koşuyorum". Bu, rekabet duygusundan çok kendi yeteneklerinin farkına varmasının bir göstergesidir. Ona herkesin farklı becerileri olduğunu basit bir dille anlatın. Bu yaklaşım, hem öz saygı geliştirmesine hem de başkalarına karşı hoşgörülü olmasına yardımcı olur.') WHERE id = 'b9b4b281-d07d-4b24-8be3-a13d61d2de12';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Hızlı durma". Çocuğunuz koşarken sizin "Dur!" komutunuzla hemen durabilir. Bu, hem kaslarını fiziksel olarak kontrol edebildiğini hem de beynindeki dürtü kontrolünün (inhibitory control) geliştiğini gösterir. Parkta "Kırmızı ışık, yeşil ışık" oyununu oynamak için harika bir zaman.') WHERE id = '36d86d2b-43c1-4460-afbb-45a783701a53';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Karmaşık diyaloglar". Çocuğunuz artık size bir olayı sırasıyla anlatabilir. "Önce parka gittik, sonra dondurma yedik, sonra bir kedi gördük". Hikâye oluşturma becerisi, hafızası ile konuşma becerisinin birlikte geliştiğini gösterir. Ona "Peki, sonra ne oldu?" diye sorarak hikâyeyi genişletmeye teşvik edin.') WHERE id = '62cbc2dc-4d91-48c4-8b87-f71ac5555a0a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Geometrik şekilleri kopyalama". Çocuğunuz artık sizin çizdiğiniz daireyi veya çarpı işaretini taklit edebilir. Bu, gözüyle gördüğü şekli eliyle yeniden oluşturma (görsel-motor entegrasyon) becerisinin geliştiğini gösterir. Ona farklı renklerde kalemlerle şekiller çizmeyi öğretin.') WHERE id = 'c219d541-0794-4388-b19c-1b3296bc6f1a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız kararlar". Çocuğunuz artık hangi oyuncakla oynayacağını veya hangi kitabı okuyacağını kararlı bir şekilde seçiyor. Bu seçimleri yapmasına izin verin. Kendi seçimine saygı duyulduğunu görmek, çocuğun özgüvenini artırır ve iç dünyasının zenginleşmesine yardımcı olur.') WHERE id = '064446a8-f711-4f01-89fb-101964123929';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Sıra bekleme". Çocuğunuz artık herkesin aynı anda salıncağa binemeyeceğini anlıyor. "Şimdi o sallanıyor, sonra ben" diyebilmesi, sosyal zekâ gelişiminde büyük bir adımdır. Bu davranışın alışkanlığa dönüşmesi için gösterdiği sabrı mutlaka övün.') WHERE id = '9280edaf-2356-4dce-a273-2cd4a5d6fd57';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Sıralama ve kategorilere ayırma". Çocuğunuz artık nesneleri yalnızca renklerine göre değil, kullanım amaçlarına göre de gruplandırıyor: "Bunlar yiyecek, bunlar ise oyuncak". Ona karışık nesneler verin ve "Mutfağa ait olanları bul" deyin. Bu, zihnindeki bilgileri düzenlemesine yardımcı olur.') WHERE id = '55b33de4-6e1b-4815-985d-641594c12f05';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topu omuz üzerinden atma". Çocuğunuz artık topu yalnızca aşağıdan değil, omuz hizasından ileriye doğru da atabilir. Bu, kol ve omuz kaslarının güçlendiğini ve hareketin yönünü planlayabildiğini gösterir. Onunla parkta küçük "hedefe atış" oyunları oynayın.') WHERE id = 'eb04363a-ab4d-4a94-888d-e7e2e5211e9c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Zamirleri doğru kullanma". Çocuğunuz artık "ben", "sen", "o", "biz" zamirlerini neredeyse hiç karıştırmıyor. Bu, sosyal çevredeki yerini ve başkalarıyla ilişkisini tam olarak kavradığı anlamına gelir. Onunla konuşurken karmaşık cümleler kullanmaktan çekinmeyin.') WHERE id = '4705908e-12af-4329-ab11-ab69b76d1be9';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal dayanıklılık: "Hatalardan öğrenme". Çocuğunuz bir şeyi başaramadığında hemen ağlamak yerine size bakıp "Olmadı, yeniden deneyeyim mi?" diye sorabilir. Bu, duygusal dayanıklılığının arttığını gösterir. Ona "Herkes hata yapabilir, önemli olan yeniden denemek" diyerek cesaret verin. Siz harika bir rehbersiniz!') WHERE id = 'cb464c9f-f6c4-48c0-ab1a-62c435d01c32';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuk artık kendisini yalnızca "ben" olarak değil, "bir beceri sahibi" olarak görüyor. "Ben hızlı koşarım" veya "Ben resim yaparım" gibi tanımlamalar kullanıyor. Bu olumlu benlik algısını destekleyin. Kendisini nasıl tanımladığına dikkat edin; bu, gelecekteki öz güveninin sesidir.') WHERE id = '24b05457-5c55-4e7e-93bd-e8e2e24e7b8c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel cesarette "Yükseklik korkusunu yenmek". Çocuk artık parkta daha yüksek kaydırakları veya merdivenleri denemek istiyor. Fiziksel becerileri, zihnindeki "Ben yapabilirim" düşüncesiyle artık tamamen örtüşüyor. Siz yalnızca "görünmez bir güvence" olarak yanında durun.') WHERE id = 'a48cb007-600a-438e-b8fd-ac64a32480ba';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Neden?" sorusunun felsefesi. Artık yalnızca yanıt almak için değil, sizinle sohbeti sürdürmek için de "neden" diyor. Yanıtınız bittiğinde yine "neden?" derse sözü ona bırakın: "Peki, sen ne düşünüyorsun?" Hayal gücüne dayalı açıklamaları sizi hem güldürecek hem de şaşırtacak.') WHERE id = 'a7f2070c-4631-4744-b176-d7bba5b19ea6';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Sembollerin doğuşu". Çocuk artık kâğıda "kapalı şekiller" çiziyor. Çizdiği bir daire hem güneş, hem top hem de anne olabilir. Bu, soyut düşüncenin zirvesidir: Tek bir sembol her şeyi ifade edebilir. Bu ilk "sanat eserlerini" mutlaka tarihlerini yazarak saklayın.') WHERE id = '8291f627-bff8-4ae0-9fda-966d1f2e80ac';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Sınırları Sınayan Çocuk". Çocuk, yapmamasını söylediğiniz bir şeyi bilerek yapıp tepkinizi izleyebilir. Bu, onun "kötü" olduğu anlamına gelmez; duygusal sınırlarınızı ve kuralların değişmezliğini test eder. Sakin ve kararlı kalmanız, ona en güçlü güven mesajını verir: "Dünya hâlâ istikrarlı ve güvenli".') WHERE id = 'a9bf7bd3-b390-48c2-b220-67d40659de03';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal zekâda "Oyunun kuralları". Çocuk artık oyunun devam edebilmesi için kurallara uymak gerektiğini anlıyor. Örneğin, saklambaç oynarken gözlerini kapatmanın önemli olduğunu biliyor. Bunlar, toplum içindeki ilk "sosyal sözleşmeleridir". Onunla basit kuralları olan masa oyunları oynamaya başlayın.') WHERE id = '6de77e4c-02d9-4646-a638-e1f9881237a4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Zaman ritüelleri". Çocuk "dün", "bugün" ve "yarın" kavramlarını henüz tam olarak ayırt edemese de ritüelleri biliyor. "Yemekten sonra park" veya "Uyumadan önce masal". Bu sıralamalar, zihninde zaman çizgisini oluşturuyor. Olayları sırasıyla anlatarak ona yardımcı olun.') WHERE id = '3677e8d8-da75-4da9-b002-0343f54de7f8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyonda "Hassas manevralar". Çocuk artık sıvı dolu bir bardağı fazla dökmeden taşıyabiliyor veya dar bir yolda yürüyebiliyor. Bu, görsel-motor koordinasyonunun ne kadar geliştiğini gösteriyor. Ona evde "küçük garson" rolleri verin.') WHERE id = '24b745fb-d8d2-4191-b523-51bef737292f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Duygu Sözlüğü". Çocuk artık yalnızca "kötüyüm" veya "iyiyim" demiyor. "Sinirlendim", "özledim", "mutluyum" gibi sözcükleri yerinde kullanıyor. Onun duygularını doğrulayın: "Özlediğin için ağlaman normal". Bu, onun duygusal sağlığının en büyük güvencesidir.') WHERE id = 'e9c2314b-a8e3-4e87-93f6-fa6cd95e6e36';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '3 yaşın (1095 gün) eşiğinde. Çocuk artık "bebeklik" kıyısından uzaklaşıp "çocukluk" okyanusuna açılıyor. Artık yalnızca hareketlerinizi değil, duygusal durumunuzu da taklit ediyor. Siz onun için en büyük aynasınız. Kendinizle gurur duyun; 1090 gündür harika bir insan yetiştiriyorsunuz!') WHERE id = '6d3a16a2-1643-4f5c-be11-40251b29e16d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '3 yaşını doldurmasına (1095 gün) yalnızca 5 gün kaldı! Çocuk artık "Ben" kavramını tamamen benimsedi ve kendi sınırlarını ısrarla koruyor. Bu günlerde karşılaştığınız "hayır"lar size karşı olduğu anlamına gelmez; kendi kişiliğini ortaya koyma biçimidir. Ona seçenekler sunarak bu geçişi kolaylaştırın.') WHERE id = '1dacdad0-c90b-4399-810b-283d367d437c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel gelişimde "Tam Bağımsızlık". Çocuk artık iki ayağıyla aynı anda yukarı zıplayabilir, merdivenleri destek almadan inip çıkabilir ve üç tekerlekli bisiklet kullanabilir. Fiziksel enerjisi artık koordineli hareketlere dönüşmüştür.') WHERE id = '0788e284-3cae-46fe-a730-5b0adb5d2052';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Soyut Düşünme". Çocuk artık o anda orada bulunmayan nesneler veya geçmişte yaşanan olaylar hakkında uzun uzun konuşabilir. "Hatırlıyor musun, biz oraya gitmiştik?" gibi cümleler, uzun süreli belleği ile konuşma becerisinin mükemmel uyumunu gösterir. Onunla geçmiş anılarınızı sık sık paylaşın.') WHERE id = 'f3f07ee7-1804-4733-8e04-f58c824d1ef9';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor gelişiminde "Yazma Öncesi Beceriler". Çocuk artık kalemi avucuyla değil, parmaklarıyla tutuyor; kapalı daireler, artı işaretleri ve hatta bazı harflere benzeyen çizgiler çiziyor. Bu, gelecekteki yazma becerileri açısından en kritik fiziksel aşamadır.') WHERE id = '1e35d34e-147e-430a-a51b-7c615ecdd852';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'DOĞUM GÜNÜ KUTLU OLSUN! Tam 3 yıl, yani 1095 gün! Çocuk artık resmen "bebeklik" kıyısından ayrıldı. O artık konuşan, düşünen, şaka yapan ve kendine ait bir dünyası olan küçük bir insan. Bu 1095 gün boyunca onun zihninde sarsılmaz bir güven ve sevgi temeli oluşturdunuz. Aferin size, Anne!') WHERE id = '94af9664-3a01-40cf-b485-6d92b46dd312';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '4. yaşın ilk günü! Çocukta "Sorumluluk" duygusu uyanıyor. Artık oyuncaklarını toplamanın da oyunun bir parçası olduğunu anlayabilir. Ona küçük ev işleri verin (örneğin, masaya peçete koymak). Bu, ailenin faydalı bir üyesi olduğu hissini güçlendirir.') WHERE id = '8a58846e-740c-494e-b055-cca0e1dee700';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Empati Gelişimi". Çocuk artık yalnızca kendi duygularını değil, başkalarının da üzülebileceğini anlıyor. "O çocuk neden ağlıyor?" sorusu, dünyayı başkalarının gözünden görmeye başladığının bir göstergesidir.') WHERE id = '3be5dfbf-e6fa-4586-9735-23266743fb18';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Mantıksal Sıralama". Çocuk artık 3-4 aşamalı olayları doğru sıraya koyabiliyor: "Önce ellerimi yıkadım, sonra ekmek yedim, sonra oynadım". Ona gününüzü birlikte planlamayı teklif edin. Bu, zihnindeki "kaosu" düzenli bir "zaman çizelgesine" dönüştürür.') WHERE id = 'cce49adb-3f97-4be9-9435-40b81895ee05';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Hayal gücünde "Karmaşık Rol Oyunları". Artık oyunları daha ayrıntılıdır. Yalnızca "doktor" olmakla kalmaz, size "reçete yazar" ve "iğne yapar". Bu oyunlar, çocuğun stresle başa çıkma ve toplumu anlama yöntemidir. Onun oyun dünyasına saygıyla katılın.') WHERE id = '63c35556-85c7-4de4-956c-b06072fe14e8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '1100 günlük yolculuğun son durağı. Çocuk artık kendini "büyük" hissediyor. Bireyselliği, zevkleri ve karakteri artık tamamen şekillendi. Siz bu yolu sabırla, bilimle ve en önemlisi sonsuz sevgiyle katettiniz. "Anacan" uygulaması her zaman sizin ve küçük kahramanınızın yanında!') WHERE id = 'b3b1d154-d59c-44d1-8bf7-a6ef75357962';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '3 yaşın ilk on gününe hoş geldiniz! Bu dönemde çocuğun kelime dağarcığı yaklaşık 1000 kelimeden oluşur. Artık yalnızca ihtiyaçlarını değil, hayallerini de paylaşır. Onunla konuşurken sık sık "Sizce neden?" diye sorarak mantık yürütmesini teşvik edin.') WHERE id = 'a79f70f3-f350-4b22-984a-7f58dfd4b7fb';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel gelişimde "Hedefli Sıçrama". Çocuk artık bulunduğu yerden hem yukarıya hem de belirli bir hedefe doğru (örneğin yerdeki renkli halının üzerine) zıplayabiliyor. Bu, hem denge hem de mekânsal mesafeyi hesaplama becerisini gösterir. Parkta oynayacağınız "taştan taşa atlama" oyunu onun için harika bir egzersizdir.') WHERE id = '05ceca15-09f0-41f4-a54b-99db2b828cc8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Zamir ve Cinsiyet Kategorileri". Çocuk artık "ben", "sen" ve "o" zamirlerini doğru biçimde kullanır. Hâlâ bazen kendisinden üçüncü şahıs olarak söz ediyorsa (örneğin, "Ali su istiyor"), onu nazikçe düzeltin: "Evet, SEN su istiyorsun".') WHERE id = '03d396dd-e487-41b7-9885-73235271ea53';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor gelişiminde "Yapboz ve Yapı Kurma". Çocuk artık 8-12 parçalı yapbozları kendi başına tamamlayabilir ve küplerden karmaşık kuleler, köprüler yapabilir. Bu, hem görsel analiz becerisini hem de parmakların ince hareket kabiliyetini geliştirir. Yapamadığında ona hazır çözümü vermeyin, yalnızca ipucu verin.') WHERE id = 'ca591a5d-4734-459d-be9b-3eaadeddb81b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız giyinme: Fermuar ve Düğme". Çocuğunuz artık büyük düğmeleri açmaya veya fermuarı (siz başlattıktan sonra) yukarı çekmeye büyük ilgi gösterir. Ona "Haydi, kendin dene" diyerek sabırla bekleyin. Kendi kendine giyinebilmesi, çocuğunuzun "Ben yapabilirim" duygusunu ve özgüvenini inanılmaz ölçüde artırır.') WHERE id = '9a464aa6-3d95-421a-948d-be4bbc442bbe';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Paylaşmayı anlama". Çocuğunuz artık oyuncağını arkadaşına vermenin onu tamamen kaybetmek değil, yalnızca "sırayla oynamak" olduğunu anlar. Bunlar empatinin ilk tohumlarıdır. Bu davranışını mutlaka "Arkadaşınla paylaştığın için teşekkür ederim" diyerek pekiştirin.') WHERE id = '7f75fc5d-eb6e-4e7a-abdd-f9659116f406';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Sayı-Miktar ilişkisi". Çocuğunuz 1''den 10''a kadar ezbere saymanın yanı sıra nesneleri parmağıyla göstererek "bir, iki, üç" diye gerçek miktarları saymaya başlar. Ona "Sofraya 3 tane kaşık koyalım" gibi görevler verin. Bu, soyut sayıların gerçek dünyayla ilk kez güçlü bir bağ kurduğu aşamadır.') WHERE id = '6bc8719d-b139-4ea0-af7e-596754bfb254';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Geri geri yürüme". Çocuğunuz artık arkasına bakmadan güvenle birkaç adım geri gidebilir. Bu hareket, beden farkındalığını (propriosepsiyon) ve mekânsal yönelim becerisini güçlendirir. Onunla "Yengeç yarışı" oynayarak hem eğlenin hem de kaslarını çalıştırın.') WHERE id = '2fce926c-604e-40c3-aff1-959bf3574903';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Soyut sorular". Çocuğunuz artık "Neden?", "Nasıl?" sorularıyla dünyayı keşfeder. "Bulut nereye gidiyor?", "Karınca nereye koşuyor?" gibi sorular hem merakını hem de çevresiyle kurduğu mantıksal bağları gösterir. Yanıtlarınızın basit ve onun anlayabileceği bir dilde olması önemlidir.') WHERE id = '5eb5c186-69a6-483f-9ba1-b6f471501a76';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal Dayanıklılık: "Sabır testi". Çocuğunuz artık istediği bir şey için birkaç dakika beklemesi gerektiğini anlar. "Şimdi değil, birazdan" dediğinizde hemen ağlamıyorsa bu, duygularını düzenleme becerisinin geliştiğini gösterir. Sabrettiğini gördüğünüzde onu "Beklediğin için teşekkür ederim" diyerek teşvik edin.') WHERE id = '6751f01f-eb8d-4bf5-bdeb-fec3d11483e8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık renkleri ve şekilleri bir araya getirerek dünyayı tarif eder. "Bana şu sarı kare bloğu ver" diyorsa bu, beyninin aynı anda birden fazla özelliği işlediğini gösterir. Bu becerisini günlük yaşamda küçük görevlerle (örneğin, "mavi çoraplarını bul") destekleyin.') WHERE id = 'd8ae8173-4cc7-42b0-8737-2bedce267dcb';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel gelişimde "Dinamik denge". Çocuğunuz artık tek ayağının üzerinde 5 saniyeye kadar durabilir. Bu, vestibüler sistemin ve bacak kaslarının güçlendiğini gösterir. Onunla "Leylek" oyunu oynayarak kimin daha uzun süre durabildiğini görün.') WHERE id = '071b03c5-b7b5-42d1-a970-a44e8e806595';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Neden-sonuç ilişkileri". Çocuk artık "Eğer... o zaman..." türündeki cümleleri anlamaya başlar. "Eğer oyuncaklarını toplarsan çizgi film izleyebiliriz" dediğinizde koşulu anlar. Bu, hem mantıksal düşünmenin hem de öz disiplinin gelişmesi için önemli bir adımdır.') WHERE id = 'a7ceb34f-04f4-4303-a5f6-fca236e067db';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Makasla ilk deneyimler". Çocuk artık kağıdı (güvenli çocuk makasıyla) düz bir çizgi boyunca kesmeye ilgi gösterir. Bu hareket hem el-göz koordinasyonunu hem de parmakların ince motor becerilerini geliştirir. Onu gözetimsiz bırakmayın, ancak özgürce denemesine de engel olmayın.') WHERE id = '42cc6ea9-d4af-4873-a31f-be87ca7ae22d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışlarda "Hayali oyun arkadaşları". Çocuk artık tek başına oynarken de yüksek sesle konuşur ve oyuncaklarına roller verir. Bu, çocuğun kendi davranışlarını sözcüklerle düzenlemesine yardımcı olur. Bu "monologlarını" dinleyerek iç dünyasında neler olup bittiğini anlayabilirsiniz.') WHERE id = 'b9a0516e-a5fd-46ab-abb8-4e16e305575b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız seçim: Karar verme". Çocuk artık ne yemek istediğini veya hangi oyunu oynayacağını kesin olarak bilir. Ona her gün iki seçenek sunun: "Elma mı istersin, yoksa muz mu?". Bu, kendi hayatı üzerinde kontrol sahibi olduğunu hissetmesini sağlar ve öz güvenini artırır.') WHERE id = 'd2594413-54bc-4a0b-857c-1959a2b007b2';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Hacim ve miktarın korunumu". Çocuk, küçük ve uzun bir kaptaki suyun geniş bir kaptaki sudan daha fazla olduğunu düşünebilir. Bu, bu yaş için normaldir. Onunla su oyunları oynayarak suyu farklı kaplara boşaltın. Bu, deneyim yoluyla mantıksal kavrayışının gelişimini hızlandırır.') WHERE id = 'c2c7f4f2-7e4e-4f22-9785-bdddbd705503';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "İki ayakla ileri sıçrama". Çocuk artık engellerin (örneğin yerdeki bir ipin) üzerinden iki ayağıyla aynı anda atlayabilir. Bu, tüm vücudun koordinasyonunu gerektirir. Onun için güvenli alanlarda küçük engel parkurları oluşturun.') WHERE id = '3c4e0869-e516-493c-90a9-df3b2f2e738b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Soyut zaman kavramı". Çocuk artık "Sabah", "Öğle" ve "Akşam" arasındaki farkları rutinler aracılığıyla kavrar. "Akşam baban geldiğinde..." dediğinizde günün o zaman dilimini zihninde canlandırır. Günlük rutininize bağlı kalmanız, bu zaman kavramını güven duygusuyla ilişkilendirmesine yardımcı olur.') WHERE id = 'd719015d-011e-40f6-8ffa-5cdcb4302e71';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal Olgunluk: "Özür dilerim" sözünün anlamı. Çocuk artık bilerek veya bilmeyerek birini incittiğinde "Özür dilerim" demenin sosyal önemini anlar. Ona her zaman örnek olun; siz hata yaptığınızda ondan özür dileyin ki o da bu davranışı güçlü bir karakter özelliği olarak benimsesin.') WHERE id = 'c8c25e23-7ba2-4ee9-a363-3be20d076417';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık resimlere bakarak basit hikâyeler uydurabiliyor. "Ayı ormana gitti, acıktı ve bal yedi" gibi birbiriyle bağlantılı cümleler kurması, olayların mantıksal sırasını kavradığını gösterir. Ona ilgi çekici resimleri olan kitaplar verin ve "Sence bundan sonra ne olacak?" diye sorun. Bu, onun yaratıcı hayal gücünü en üst düzeye çıkarır.') WHERE id = 'd67be23e-c203-4809-a7a3-cbfd66266b55';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Merdiven bağımsızlığı". Çocuğunuz artık basamakları ayak değiştirerek, yalnızca bir elinden tutulduğunda (ya da hiç destek almadan) güvenle inebiliyor. Bu, kaba motor becerilerinin iyice geliştiğini gösterir. Sizin yalnızca yanında bulunarak ona manevi destek vermeniz yeterlidir.') WHERE id = '7b344d73-ef09-40bc-8962-14de04d0a9d1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Soru-Cevap zinciri". Çocuğunuz artık sorularınıza yalnızca "evet/hayır" şeklinde değil, tam cümlelerle yanıt veriyor. "Bugün parkta kiminle oynadın?" sorusuna ayrıntılı cevap verebilir. Onunla konuşurken "O ne renkti?", "Neler yaptınız?" gibi devam soruları sorarak konuşma gelişimini destekleyin.') WHERE id = '728c62de-e9bd-4825-a015-839c4ef09ac4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Daha özenli boyama". Çocuğunuz artık küçük şekillerin sınırlarını da fark ediyor ve boyama yaparken çizgilerin dışına fazla çıkmamaya çalışıyor. Bu, el kaslarının kontrolünde önemli bir ilerlemedir. Ona farklı kalınlıklarda boya kalemleri vererek denemeler yapmasına fırsat tanıyın.') WHERE id = '1e2db868-b348-4ed1-a7d7-4e1b235065d6';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız giyinme: Fermuar ve Düğme". Çocuğunuz artık büyük düğmeleri açabiliyor ve fermuarın ucu yerleştirildikten sonra fermuarı yukarı çekebiliyor. Ona "Haydi, kendin dene" deyip sabırla bekleyin. Kendi başına giyinebilmesi, çocukta "Ben yapabilirim" duygusunu ve özgüveni büyük ölçüde artırır.') WHERE id = 'd0289832-2e1f-4c80-bf6f-025f04fde8c3';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Paylaşmanın mantığı". Çocuğunuz artık başka bir çocuğun elindeki oyuncağı hemen almak yerine "ver" diyerek beklemeye çalışıyor. Bu, öz düzenleme (self-regulation) becerisinin güçlendiğini gösterir. Bu sabırlı davranışını gördüğünüzde onu mutlaka "Sıranı beklediğin için çok teşekkür ederim" diyerek takdir edin.') WHERE id = '8b0e05af-2727-418a-b763-3601d197e7d0';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Genel ve Özel". Çocuğunuz artık elma, armut ve muzun hepsinin "meyve" olduğunu anlıyor. Ona farklı nesneler gösterin ve "Bunların hepsine birden ne diyoruz?" diye sorun. Kategoriler hâlinde düşünmek, beynindeki bilgi depolama sisteminin daha düzenli olmasını sağlar.') WHERE id = 'cfa7be75-1286-4575-9a59-47547f98434d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topu omuz üzerinden atma". Çocuğunuz artık topu yalnızca yere bırakmıyor; omzunun üzerinden ileriye, belirli bir hedefe doğru atabiliyor. Bu hareket tüm vücut koordinasyonunu gerektirir. Onunla parkta "hedefe atma" oyunları oynayın.') WHERE id = '7ccd147e-b878-45ff-a8c8-f2d12fac2b06';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Mekân ve Yön". Çocuğunuz "sağ" ve "sol" kavramlarını henüz tam olarak ayırt edemese de "ileri", "geri", "yukarı" ve "aşağı" komutlarını eksiksiz yerine getirir. Onunla "Robot oyunu" oynayın: "İki adım ileri, bir adım geri!". Bu oyun hem eğlencelidir hem de mekânsal yön bulma becerisini güçlendirir.') WHERE id = 'd6a03598-2471-4b13-a839-fb2c51010318';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal Dayanıklılık: "Başarısızlıkla başa çıkma". Çocuğunuz artık küpleri devrildiğinde hemen ağlamıyor, "Yeniden yapacağım" diyebiliyor. Bu mücadeleci ruhunu destekleyin. 1130 günü geride bıraktık – çocuğunuz artık küçük bir kahraman!') WHERE id = 'b7ab015d-a4e4-4c1d-a9a5-7f26c5798a69';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık nesneleri aynı anda iki özelliğe göre (örneğin hem renklerine hem de şekillerine göre) ayırabilir. Ona "Bana bütün küçük kırmızı arabaları ver" dediğinizde bunu yapabiliyorsa, bu bilişsel gelişiminde yeni bir seviyeye ulaştığını gösterir. Günlük ev işlerinde ona bu tür küçük "seçme" görevleri verin.') WHERE id = 'ff1dcdb3-fd81-4345-80ce-058e6b7a0d6b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Hedefe atlama". Çocuğunuz artık yere çizilmiş bir dairenin veya renkli bir hedefin ortasına atlamaya çalışır. Bu, hem denge hem de mekânsal mesafeyi hesaplama becerisini geliştirir. Parkta onunla "taştan taşa atlama" oyunu oynayın.') WHERE id = '5d8b4009-8971-48b6-aa55-75a96a823d2d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Zıt anlamlı kelimelerin çeşitlenmesi". Çocuğunuz artık "erken-geç", "karanlık-aydınlık", "boş-dolu" gibi soyut karşıtlıkları anlar. Ona boş ve dolu birer bardak gösterip aralarındaki farkı sorun. Bu, çevresindeki dünyayı karşılaştırmalı olarak analiz etme becerisini güçlendirir.') WHERE id = '18232b0a-482a-40e1-90c7-8a04a56dc3b9';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Puzzle ustalığı". Çocuğunuz artık 10-12 parçalı karmaşık puzzle''ları (resmin kenar ve orta kısımlarını ayırt ederek) tamamlayabilir. Bu, hem görsel hafızayı hem de parmakların ince hareket becerisini geliştirir. Yapamadığında ona sakin bir ses tonuyla ipuçları verin.') WHERE id = '3045e148-b927-4872-8354-b9edb5116d18';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız temizlik ve yardım". Çocuğunuz artık sofrayı toplarken kendi tabağını götürmek ve kırıntıları silmek gibi işleri büyük bir hevesle yapar. Ona boyuna uygun temizlik malzemeleri verin. Bu, aile içinde sorumluluk ve aidiyet duygusunu güçlendirir. Kendi emeğinin sonucunu görmek onu çok mutlu eder.') WHERE id = '5fed215f-7140-471a-887f-855f666792ab';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Kurallar ve Sınırlar". Çocuğunuz artık "hayır" kelimesinin arkasındaki mantığı biraz daha iyi anlıyor, ancak yine de sınırları zorlamayı seviyor. Sizin sabırlı ve tutarlı olmanız ona güven duygusu verir. Kuralları her zaman aynı şekilde uygulamaya çalışın.') WHERE id = 'ad322e7c-2c29-48c7-ba0d-376889e0bc86';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Sıra sayıları". Çocuk artık "birinci", "ikinci", "sonuncu" kavramlarını anlıyor. Arabaları arka arkaya dizip "Hangi araba birinci?" diye sorun. Bu, sıralama becerisini ve matematiksel mantığını geliştirir. Yarışlarda "Birinci siz geldiniz!" demeniz onun için büyük bir motivasyon kaynağıdır.') WHERE id = 'ccdeb036-ba4e-49c8-960c-f4271e0fc740';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Geri geri ve yan yana yürüme". Çocuk artık farklı yönlerde çevik bir şekilde hareket edebiliyor. Onunla "Ayna oyunu" oynayın: Siz yana doğru bir adım atın, o da sizi taklit etsin. Bu hem eğlencelidir hem de vücut koordinasyonunu yeni bir seviyeye taşır.') WHERE id = '53f08fbe-8240-4c06-91f5-3a6645fa77af';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Dil gelişiminde "Soyut soruların derinleşmesi". Çocuk, "Bulutlar nereye gidiyor?", "Yıldızlar neden gece çıkıyor?" gibi sorularla sizi şaşırtabilir. Yanıt verirken onun hayal gücünü de harekete geçirin: "Sence yıldızlar şimdi ne yapıyor?". Bu, onun yaratıcı düşünme becerisini besler.') WHERE id = 'ca368c4f-966b-4846-b9ca-ff68822b1eca';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal Dayanıklılık: "Paylaşmanın sevinci". Çocuk artık oyuncağını veya şekerlemesini gönüllü olarak paylaştığında sizin sevincinizi görür ve bunu yeniden yapmak ister. "Arkadaşını sevindirdiğin için çok teşekkür ederim" diyerek onun bu cömertliğini özellikle vurgulayın. 1140 günü başarıyla tamamladık – siz harika bir annesiniz!') WHERE id = '706c863b-0328-4280-9ae2-b61f0dddff18';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '39. aya adım atıyoruz! Çocuk artık "iki aşamalı" düşünmeden "üç aşamalı" yönergeleri uygulamaya geçiyor. "Oyuncağı al, kutuya koy ve kapağını kapat" dediğinizde sıralamayı bozmadan yapabiliyorsa bu, çalışma belleği (working memory) açısından büyük bir başarıdır. Gün boyunca ona küçük ve mantıklı, birbirini takip eden görevler vererek bu becerisini geliştirin.') WHERE id = '0f30e0b2-fa18-4fe2-8164-072ae2911569';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Hızlı koşma ve manevra". Çocuk artık koşarken önündeki engeli gördüğünde hızını azaltmadan etrafından dolaşabiliyor. Bu, beden farkındalığının (proprioception) tamamen geliştiğini gösterir. Parkta "engelli koşu" yarışları düzenleyerek enerjisini faydalı bir yöne yönlendirin.') WHERE id = 'c69b10fa-3ecf-43fd-9d25-d70589994cb8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Dil gelişiminde "Karşılaştırma dereceleri". Çocuk artık "daha büyük", "en küçük", "çok lezzetli" gibi ifadeleri doğru yerlerde kullanıyor. Nesneleri karşılaştırarak onunla sohbet edin: "Bu elma mı daha tatlı, yoksa diğeri mi?". Sıfatların bu derecelerini öğrenmesi, betimleyici anlatımını zenginleştirir ve düşüncelerini daha net ifade etmesini sağlar.') WHERE id = '10874a8b-618a-44ed-9a23-9c2c3bcf6530';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Heykel yapımı". Çocuk artık oyun hamuru veya kinetik kumla oynarken bunları yalnızca sıkmakla kalmıyor, "top", "yılan" veya "ekmek" gibi tanınabilir şekiller de yapıyor. Bu, hem yaratıcı düşünme becerisi hem de parmak uçlarındaki küçük kasların güçlenmesi için harika bir egzersizdir.') WHERE id = '8ef81138-3a54-4c5e-ab33-5ab135be888d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız giyinme: Giysilerin önünü arkasını ayırt etme". Çocuğunuz artık tişörtün veya pantolonun önünü arkasını, ayakkabıların sağını solunu (bazen hata yapsa da) ayırt etmeye çalışır. Ona küçük ipuçları verin: "Bak, resimli taraf öne geliyor". Bu, ayrıntılara odaklanma ve öz bakım becerilerini geliştirir.') WHERE id = '0d252040-b7cf-42d1-8e5c-b4a1ea436608';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Takım ruhu". Çocuğunuz artık diğer çocuklarla ortak bir hedef doğrultusunda (örneğin büyük bir kale yapmak için) birlikte oynayabilir. Bu, "Paralel oyun"dan "İş birlikçi oyun"a geçiştir. Diğer çocuklarla nasıl iletişim kurduğunu gözlemleyin ve zorlandığı anlarda sosyal bir "köprü" kurmasına yardımcı olun.') WHERE id = 'b59f81d2-048d-48f5-8c51-231cd1498118';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Rakam ve miktar eşleştirmesi". Çocuğunuz 1''den 5''e kadar saymayı biliyor; artık "3" rakamını gördüğünde 3 oyuncağı ayırıp bir yere koyabilir. Bu, matematiksel düşünmenin en önemli aşamalarından biridir. Günlük yaşamda "Bana 2 kaşık ver" gibi görevlerle bu bağlantıyı güçlendirin.') WHERE id = '5b8b658c-3ba9-46dd-b7e1-a329bde32c59';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Yukarıdan atılan topu yakalama". Çocuğunuz artık kendisine doğru yavaşça atılan büyük bir topu iki eliyle yakalamaya çalışır. Bu hareket hem el-göz koordinasyonu hem de tepki hızı gerektirir. Onunla yakın mesafeden "at-tut" oyunu oynayın.') WHERE id = '9cbfafe8-e2d3-4b4c-a7dd-a7d50a0d73a4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Soyut soruların zirvesi". Çocuğunuz artık "Rüzgâr neden esiyor?", "Güneş uyumaya nereye gidiyor?" gibi yaşam ve doğa olaylarıyla ilgili sorular sorar. Yanıt verirken hayal gücünü de işin içine katın: "Güneş yoruldu, yarın bizi yeniden uyandırmak için dinlenmeye gidiyor". Bu, onun dünya görüşünü ve öğrenme isteğini besler.') WHERE id = 'be40f099-56c3-42b3-90d0-8aec32c8e2ca';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal olgunluk: "Başkasının duygularını kabul etme". Çocuğunuz artık sizin yorgun olduğunuzu veya başka bir çocuğun canının yandığını gördüğünde "Ne oldu?" diye sorar ve teselli etmeye çalışır. Bu, onun şefkatli bir birey olarak geliştiğini gösterir. Siz harika bir annesiniz!') WHERE id = '28850826-f8da-4cde-a0f3-c10d2981e7f4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık "ben" ve "benim" kavramlarını sosyal ortamda sınamaya başlar. Oyuncağını paylaşmak istememesi, bencillikten çok kendi sınırlarını belirleme çabasıdır. Ona "Bu senin oyuncağın, hazır olduğunda arkadaşına verebilirsin" diyerek sahiplik duygusuna saygı duyduğunuzu gösterin. Bu, gelecekte başkalarının sınırlarına da saygı gösterme becerisi kazanmasına yardımcı olur.') WHERE id = '3d0a961f-8311-4c15-82e4-3b93885267b5';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Yüksekten atlama". Çocuğunuz artık alçak bir basamaktan veya bir yükseltinin üzerinden iki ayağıyla aynı anda yere atlamayı sever. Bu hareket, vestibüler sisteminin gelişimi için önemlidir. Yere yumuşak bir minder koyarak bu cesaretini güvenli bir şekilde destekleyin.') WHERE id = '0680b361-8e77-46ad-a0ea-0e96e9759bdc';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Gelecek zamanın netleşmesi". Çocuk artık sadece "gideceğiz" demekle kalmaz, "Yarın büyükanneme gidip kediyle oynayacağız" gibi sıralı planlar kurar. Günün sonunda onunla ertesi günün planlarını konuşun. Bu, olayları önceden zihninde canlandırma ve planlama (yürütücü işlev) becerisini geliştirir.') WHERE id = 'e7723585-78f9-489b-95f6-9d306c6417b7';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerde "Daha karmaşık şekiller". Çocuk artık kalemi ustaca (üç parmak tutuşuyla) kavrar ve kağıda üçgen çizmeye veya kesişen çizgiler oluşturmaya çalışır. Bu, el kaslarının yazı yazmaya neredeyse hazır olduğunu gösterir. Ona "Haydi, noktaları birleştirelim" oyununu önerin.') WHERE id = '23c81011-ddf7-4cf3-aec3-f115d29c3f5e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız hijyen: Diş fırçalama". Çocuk artık dişlerini fırçalarken izlemesi gereken adımları bilir. Sonunda hâlâ "kontrol" etmeniz gerekse de bu işi kendi başına yapmasına izin verin. Bu alışkanlık, kendi bedenine özen gösterme sorumluluğunu geliştirir.') WHERE id = '94615e85-6da2-44c7-a201-6901c2a92ddf';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Hayali hikayeler ve Yalan". Çocuk bazen gerçek olmayan şeyler anlatabilir (örneğin, "Gökyüzünde uçtum"). Bu, kandırma amacı taşımaz; hayal gücünün konuşmayla bütünleşmesidir. Ona "Ne ilginç bir hikaye!" diyerek hayal gücünü takdir edin, ancak gerçek ile hayal arasındaki ince farkı da nazikçe açıklayın.') WHERE id = 'd70b5fda-77b6-4fb1-bc69-d894fe21ca89';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Kategorilerin ayrıntılanması". Çocuk artık nesneleri yalnızca "araba" olarak değil, "hızlı araba", "kamyon" gibi alt gruplara ayırır. Ona "Hangi nesneler suda yüzer, hangileri batar?" deneyini önerin. Bu, bilimsel gözlem becerisinin temelini oluşturur.') WHERE id = '164e0d4f-5849-466c-88ec-e6961c6d0680';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topu ayakla yönlendirme". Çocuk artık sadece topa vurmaz, ayağıyla biraz ileri iterek onu hareket ettirmeye çalışır. Bu, dinamik denge için harika bir egzersizdir. Onunla parkta küçük bir "futbol parkuru" oluşturun.') WHERE id = 'c019ed6e-efde-47c2-b2ac-37c3fbd433b5';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Sıfat çeşitliliği". Çocuk nesneleri tarif ederken "yumuşak", "dikenli", "pürüzsüz", "parlak" gibi kelimeler kullanmaya başlar. Onunla "Dokun ve bul" oyununu oynayın: Gözlerini kapatıp nesneye dokunduğunda nasıl hissettirdiğini anlatmasını isteyin.') WHERE id = '0b5835ed-17d3-46e9-b2cd-eb9c92154c53';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal dayanıklılık: "Başkalarına yardım etme". Çocuk artık bir işi yapmakta zorlandığınızı veya bir şey aradığınızı fark edip yardım önerebilir. Bu, benmerkezci dönemden çıkıp gerçek bir "sosyal partnere" dönüştüğünü gösterir. Yardımının önemini "Sen olmasaydın bunu bulamazdım" diyerek özellikle vurgulayın.') WHERE id = '95ef23e6-3a1e-4eb7-bed7-103fc452a1e2';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık "sonuç" odaklı düşünmeye başlıyor. Örneğin, "Şeker yersem dişlerim ağrıyabilir" gibi neden-sonuç ilişkilerini sizin hatırlatmanızla anlamaya çalışıyor. Bu dönemde ona kuralların nedenlerini açıklamak çok önemlidir. Bu, çocuğunuzun körü körüne itaat etmesini değil, içsel mantığa dayanan bir disiplin geliştirmesini sağlar.') WHERE id = '602eea29-96df-4d75-b3f3-a89b088efbe3';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Dinamik Denge". Çocuğunuz artık yere çizilmiş düz bir çizgi veya ip üzerinde dengesini kaybetmeden bir "cambaz" gibi yürüyebilir. Bu, vestibüler sisteminin tamamen olgunlaştığını gösterir. Parkta kaldırım kenarlarının üzerinde elinden tutarak yürümeniz, bu becerisini daha da geliştirmesine yardımcı olur.') WHERE id = '5465b5ac-4749-433f-99e1-222fda8c10bf';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Olayların ayrıntıları". Çocuğunuz artık gün içinde yaşadığı bir olayı 4-5 ardışık cümleyle anlatabilir. "Bugün parka gittik, Elcan''ı gördüm, kumda oynadık". Onun hikâyelerini dikkatle dinleyin ve "Sonra ne oldu?" diyerek diyaloğu genişletin. Bu, sözel hafızasını ve konuşma akıcılığını geliştirir.') WHERE id = '7607f78f-a199-4155-af72-552bbd09b140';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Dairelerden sembollere". Çocuğunuz artık kapalı daireler çizebilir ve bunları bir "insan" (çöp adam) olarak betimlemek için altlarına çizgiler ekleyebilir. Bu, görsel sembolizmin başlangıcıdır. Ona renkli kalemler verip "Bugün kimin resmini çiziyorsun?" diye sorarak hayal gücünü destekleyin.') WHERE id = 'ead2dac9-db7b-47ae-9b92-23aa29cddd39';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız giyinme: Düğme ve Fermuar". Çocuğunuz artık büyük düğmeleri iliklemeye ve fermuarını tek başına kapatmaya heveslidir. Bu, parmaklardaki küçük kasların koordinasyonunu gerektirir. Sabahları giyinirken bu süreci kendi başına tamamlayabilmesi için ona 5 dakika daha verin. Bunu kendi başına başardığında hissettiği gurur paha biçilemez.') WHERE id = '24f54158-6d74-423e-b96c-5270e549d121';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Sıra bekleme ve Sabır". Çocuğunuz artık salıncağa binmek için diğer çocuğun inmesini beklemesi gerektiğini anlıyor. "Sıra sende" ve "Sıra bende" kavramları, sosyal ortamlardaki anlaşmazlıkları azaltır. Gösterdiği sabrı mutlaka "Sıranı beklediğin için çok teşekkür ederim" diyerek takdir edin.') WHERE id = '97f18e0c-30d0-42a5-aa90-ac6015233d99';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Miktar algısı". Çocuğunuz 1''den 10''a kadar saymanın yanı sıra artık 3 veya 4 nesnenin sayısını saymadan, bir bakışta anlayabilir (subitizing). Ona "Burada kaç elma var?" diye sorun ve parmağıyla göstererek saymasını isteyin. Bu, gelecekteki matematiksel düşünme becerisinin temelidir.') WHERE id = '6e61f63b-18f2-4f84-b98e-0d07b524e3e9';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topu iki elle yakalama". Çocuğunuz artık kendisine doğru yavaşça atılan topu kollarını büküp ellerini göğsünde birleştirerek yakalamaya başlıyor. Bu, tepki hızının ve el-göz koordinasyonunun geliştiğini gösterir. Evde yumuşak bir topla kısa "at-yakala" etkinlikleri yapın.') WHERE id = 'eb5816aa-f53e-4699-abf2-d1ff0b98f5f9';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Yükseklik ve Uzunluk karşılaştırması". Çocuk artık nesneleri yüksekliklerine göre sıralayabilir. Ona 3-4 farklı boyutta oyuncak verin ve "En uzundan en kısaya doğru sırala" deyin. Bu, görsel algısını ve mantıksal sıralama becerisini geliştirir.') WHERE id = '3281647e-af83-48c8-9e0e-9deebd826a8f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Zaman ve Sıralama". Çocuk artık "Yarın anneanneme gideceğiz, sonra ben parka gideceğim" gibi geleceğe yönelik planlar kurar. Bu, zihninde olayları önceden canlandırma (görselleştirme) becerisinin geliştiğini gösterir. Günün sonunda onunla yarının planlarını bir "masal" gibi konuşarak uykuya dalın.') WHERE id = '533647bf-c77f-434e-8420-bd22239f3086';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal dayanıklılık: "Sabır ve Bekleme". Çocuk artık birkaç dakika sıra beklemenin "son" olmadığını, yalnızca geçici bir durum olduğunu anlar. Bu, öz yönetim (yürütücü işlev) becerisinin geliştiğini gösterir. 1180 gün – çocuğunuz artık dünyayı anlayan ve ona uyum sağlayan küçük bir birey. Siz harika bir yol arkadaşısınız!') WHERE id = 'fe96ce06-9654-4a3f-8b50-d93363f0cbca';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuk artık kendisini fiziksel özellikleriyle tanımlar: "Ben hızlı koşarım" veya "Ben uzunum". Bu, öz farkındalık sürecinin yeni bir aşamasıdır. Onun bu olumlu benlik algısını destekleyin. Kendisini nasıl gördüğü hakkında sorular sorun: "Sence, başka neleri iyi yapıyorsun?".') WHERE id = '4f2b9702-c295-43cf-9776-2d9fd4b98c79';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Dinamik sıçrama". Çocuk artık koşarken önüne çıkan küçük bir engelin (örneğin yerdeki bir ipin) üzerinden hızını azaltmadan atlayabilir. Bu, beyinde hareketi önceden planlama (motor planlama) becerisinin geliştiğini gösterir.') WHERE id = '63d363dc-9356-4fa8-bbd3-57a0c8ed1083';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Amaçlı sorular". Artık yalnızca "Bu nedir?" değil, "Bu nasıl çalışır?" diye de sorar. Nesnelerin iç mekanizmalarına ilgi gösterir. Cevap verirken konuyu çok karmaşıklaştırmayın, ancak mantıksal sırayı koruyun. Bu sorular, gelecekteki bilimsel düşüncenin ilk kıvılcımlarıdır.') WHERE id = 'fda8c637-494b-4891-b635-d2a91f4dbd7b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Şekil kombinasyonları". Çocuk artık yalnızca daire çizmekle kalmaz, daireleri birleştirerek "tırtıl" veya "kardan adam" yapar. Bu, görsel sembolleri birleştirerek yeni anlamlar oluşturma becerisini gösterir.') WHERE id = 'c2392a7c-85eb-4d9e-aff3-15371b541a80';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Soyut kavramlar: Zaman". Çocuk henüz "Saat kaç?" sorusunu anlamasa da "yarın", "dün", "sonra" gibi sözcükleri doğru yerde kullanmaya çalışır. Ona zamanı rutinlerle açıklayın: "Uyuyup uyandığında yarın olacak". Bu, dünyayı daha düzenli ve öngörülebilir görmesine yardımcı olur.') WHERE id = '6c159ac6-63d6-41de-9c9e-e48fdddeeaef';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal dayanıklılık: "Başarısızlıktan korkmama". Çocuk artık bir şeyi (örneğin küplerden kule yapmayı) başaramadığında hemen ağlamaz; size bakıp "Yeniden yapayım mı?" diyebilir. Sonucu değil, çabasını övün: "Çok uğraştın ve yeniden denedin, aferin!". Siz harika bir yol arkadaşısınız!') WHERE id = '487ce40e-d1a5-42bb-ab35-fd94c37e1b74';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuk artık duygularını daha karmaşık bir şekilde ifade eder: "Oyuncağım kırıldığı için üzgünüm". Bu, duygusal zekâ açısından büyük bir sıçramadır. Onun duygularını yalnızca kabul etmekle kalmayın, çözüm önermesine de fırsat verin: "Sence onu nasıl tamir edebiliriz?". Bu, çocuğun psikolojik dayanıklılığını (resilience) da geliştirir.') WHERE id = '72c6a670-175e-4e59-a40a-08a5b3924e43';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Yana sıçrama". Çocuk artık yalnızca ileriye değil, yana doğru da sıçrayabilir. Bu, kalça ve bacak kaslarının farklı yönlerde koordineli çalışmasını gerektirir. Onunla birlikte yere çizilmiş çizgilerin üzerinden "yana doğru sıçrama" yarışı yapın.') WHERE id = '7ad7a096-5914-4eed-80cb-8089f672c249';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Zamirlerin tamamen öğrenilmesi". Çocuk artık "benim", "senin", "onun" kavramlarını hiç karıştırmaz. "Bu benim oyuncağım, şu da senin" diyerek sosyal mülkiyet sınırlarını belirler. Bu dönem, ona ortak kullanılan eşyalarla (örneğin aile kitabı) kişisel eşyalar arasındaki farkı açıklamak için harika bir zamandır.') WHERE id = '2b8c7b62-f908-41ef-8972-07466c4a7bd0';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Simetri denemeleri". Çocuk kâğıdı katlamaya veya çizdiği resimdeki ayrıntıları simetrik biçimde yerleştirmeye çalışır. Örneğin çizdiği insanın iki tarafına da kulak veya el ekler. Bu, beynin iki yarım küresinin koordineli gelişiminin bir göstergesidir.') WHERE id = 'bd356611-73c3-4619-9883-1f920ac53fa9';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Bağımsız sofra alışkanlığı". Çocuk artık çatalı ustalıkla kullanır ve bıçakla (güvenli bir çocuk bıçağı) yumuşak yiyecekleri (örneğin muz veya omlet) kesmeye çalışır. Ona bu özgürlüğü tanıyın. Kendi ihtiyaçlarını karşılayabilme duygusu, özgüvenini içten güçlendirir.') WHERE id = 'a07fbd02-0c2f-49de-ba5e-43f31c0bcc20';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Kurallı Oyunlar". Çocuk artık "Saklambaç" veya "Kovalamaca" gibi basit kuralları olan oyunları kuralları bozmadan oynamaya ilgi gösterir. Bu, sosyal uyumun önemli bir aşamasıdır. Kurallara uyduğunda onu mutlaka "Dürüst oynadığın için aferin" diyerek övün.') WHERE id = 'e172dbdc-63ea-4b2b-afac-30588be411eb';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Siyasi" görüşmeler. Çocuğunuz artık sizinle "pazarlık" yapıyor: "Oyuncağımı toplarsam bana bir masal daha okur musun?". Bu, sosyal etkileme mekanizmalarını öğrenmeye başladığını gösterir. Bu "görüşmelerde" adil olun, ancak temel kurallarınızı koruyun.') WHERE id = '1c3607b2-8132-49bc-b9ba-d3f310a2378b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Hayali senaryolar". Artık oyunlar daha karmaşık: "Ben aşçıyım, sen de müşterisin, bana para vermelisin". Bu oyunlarda çocuk, toplumdaki rolleri ve ekonomik ilişkileri deneyimler. Onun senaryolarına uyum sağlayarak bu yaratıcı süreci destekleyin.') WHERE id = '74c3e2b6-b59d-47f7-ac39-b3a6571a3f4e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Nesnelerin işlevi". Çocuğunuz artık nesneleri yalnızca görünüşlerine göre değil, işlevlerine göre de gruplandırıyor. "Bunlar kesmeye yarayan araçlar (makas, bıçak)", "Bunlar ise yazmaya yarayan araçlar". Bu, zihnindeki bilgi birikiminin daha sistemli ve işlevsel hâle geldiğini gösterir.') WHERE id = '78693b6d-347d-4486-94dc-37e920221a4d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Merdivenlerde bağımsızlık". Çocuğunuz artık basamakları ayak değiştirerek ve neredeyse hiçbir yere tutunmadan güvenle çıkıyor. Bu, hem denge becerisinin hem de bacak kaslarının gücünün en üst düzeye ulaştığını gösterir.') WHERE id = 'cc0be0ea-ed32-4ad7-a00e-446a9d717d47';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Çünkü" dönemi. Çocuğunuz davranışlarını gerekçelendirmeye çalışıyor: "Bunu giymiyorum, çünkü bana batıyor". Onun bu "çünkü"lerini dinleyin. Bu, kendi ihtiyaçlarını ve rahatsızlıklarını mantıklı bir şekilde ifade etme becerisini güçlendirir.') WHERE id = '1172f061-c7e1-4517-8b34-e51a76cdf51e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal dayanıklılık: "Başkasının başarısına sevinmek". Çocuğunuz artık sizin veya bir arkadaşının başarısını (örneğin, oyunu kazanmasını) gördüğünde "Aferin!" diyebiliyor. Bu, benmerkezciliğin (yalnızca kendini düşünme) azalmasının ve başkalarının sevincini paylaşmanın başlangıcıdır. Siz harika bir birey yetiştiriyorsunuz!') WHERE id = 'e58983bd-cd78-4d0a-8590-e07b73fa9e05';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık "Neden?" sorularını yalnızca cevap almak için değil, neden-sonuç ilişkisini anlamak için soruyor. "Yapraklar neden yere düşüyor?" gibi doğa olaylarına ilgisi artıyor. Ona basit ve bilimsel gerçeklere dayanan cevaplar verin. Bu, çevresindeki dünyaya karşı analitik bir bakış geliştirmesini sağlar.') WHERE id = '8335f345-0d57-482d-b821-779e730295ca';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Usta Denge". Çocuğunuz artık dar bir patikada veya yere serilmiş bir ipin üzerinde dengesini koruyarak güvenle yürüyebiliyor. Bu, vestibüler sistem gelişiminin ileri bir aşamasıdır. Evde onunla "İp Cambazı" oyunu oynayarak hareketlerinin hassasiyetini artırın.') WHERE id = '00cce1f4-ca47-462d-b84a-6205502d4f13';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '41. aya hoş geldiniz! Bu dönemde çocuğun "niyet" kavramı şekillenir. Artık olayların kazara mı yoksa bilerek mi gerçekleştiğini ayırt etmeye başlar. Örneğin, biri ona dokunduğunda "Bunu bilerek mi yaptın?" diye sorabilir. Bu, sosyal ilişkilerde dürüstlüğü ve niyeti anlamak açısından önemli bir aşamadır.') WHERE id = 'be82050e-9ad6-486e-9d98-a2c2c31a243e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Tek ayak üzerinde zıplama". Çocuk artık tek ayağı üzerinde art arda birkaç kez zıplamayı dener. Bu, hem güç hem de ileri düzeyde denge gerektirir. Parkta onunla "tek ayak yarışı" oynayarak bu becerisini destekleyin.') WHERE id = '59f9bda8-ddf4-49be-ad49-7ae815287273';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Mantıksal bağlaçlar". Çocuk artık "ama", "çünkü", "eğer" bağlaçlarını cümlelerinde ustalıkla kullanır. "Parka gitmek istiyorum ama hava yağmurlu". Bu, zihnindeki çelişkili düşünceleri bir araya getirme becerisini gösterir. Onunla konuşurken bu bağlaçları kullanarak diyalogları uzatın.') WHERE id = 'b5dc9cdd-e5bc-4c21-ba9e-2e9fe7dbdaee';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Kâğıt kesme". Çocuk artık güvenli bir makasla kâğıdın üzerindeki düz çizgiyi takip ederek kesebilir. Bu, el-göz koordinasyonunun üst düzey bir göstergesidir. Kesip yapıştırma (aplikasyon) çalışmaları için ona renkli kâğıtlar ve şablonlar verin.') WHERE id = '93689350-75d1-4dc3-befa-2516fff9cb92';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Öz düzenleme (Self-regulation)". Çocuk artık öfkelendiğinde veya üzüldüğünde sakinleşmek için sizin önerdiğiniz yöntemleri (örneğin, derin nefes almak veya oyuncağına sarılmak) kullanabilir. Bu, duygusal zekânın en önemli yaşam becerilerinden biridir.') WHERE id = 'cad2a6f6-14d3-4ac8-a455-240edf668e56';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Kurallı Takım Oyunları". Çocuk artık grup içinde ortak kurallara göre oynamaya ilgi gösterir. "Şimdi hepimiz tavşan gibi zıplıyoruz" dediğinizde gruba uyum sağlar. Bu, okul ortamı için önemli olan "grup içinde hareket etme" becerisinin temelidir.') WHERE id = '6f7c2344-f4ee-4701-9810-594e0c930fc0';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Zamanın görselleştirilmesi". Çocuk artık "Dün ne yaptık?" sorusuna olayları sırasıyla anlatarak cevap verir. Ona gün içinde yaşanacakları resimlerle gösteren bir "günlük plan" hazırlayın. Bu, zaman kavramını soyutluktan çıkarıp somutlaştırır.') WHERE id = 'ecad2493-1c0b-4ab4-b089-7a992488d7c5';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topu hedefe atma". Çocuk artık topu yalnızca atmakla kalmaz, belirli bir kutuya veya hedefe isabet ettirmeye çalışır. Bu, mekânda mesafeyi ve kuvveti ayarlama (mekânsal tahmin) becerisini geliştirir.') WHERE id = '6f552613-227f-4085-940c-f293c42bd5f1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Geçmiş ve Geleceğin Birliği". Çocuk, "Dün parka gittim, yarın ise büyükanneme gideceğim" gibi zaman farklılıklarını cümle içinde doğru kullanır. Zaman kavramını pekiştirmek için ona günün rutinlerini "önce, şimdi, sonra" sıralamasıyla hatırlatmaya devam edin.') WHERE id = '10538e9b-c203-4dd2-8b24-d807c72fa3fb';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Detaylı İnsan Çizimi". Çocuk artık "çöp adam" çizerken parmak, saç veya göz gibi daha fazla ayrıntı ekler. Bu, görsel gözlem becerisinin ve el-beyin koordinasyonunun ne kadar geliştiğini gösterir.') WHERE id = 'e534e280-1b5b-4f3e-b1db-79a0cf64e3af';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Sınırların Korunması". Çocuk artık "Benim odam", "Benim masam" gibi ifadelerle kişisel alanını tanımlar. Onun bu alan algısına saygı gösterin. "Odana girebilir miyim?" diye sorarak ona kişisel sınırlara saygı duymayı ve gelecekte başkalarının sınırlarını da tanımayı öğretirsiniz.') WHERE id = '19704700-4f78-4a2f-8063-e34e01705522';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Adalet Duygusu". Çocuk artık oyunlarda kuralların ihlal edilmesine tepki verir: "O, sırasını beklemedi!". Bu, sosyal adalet ve kural anlayışının geliştiğini gösterir. Kuralların neden önemli olduğunu (örneğin, oyunun eğlenceli olması için) açıklayarak sosyal etik anlayışının temellerini atın.') WHERE id = 'bb50baca-3306-43e8-84f0-8ecfe4ce2ed7';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Miktar ve Sayı Sentezi". Çocuk 10''a kadar sayabilir, ancak artık sayıları miktarlarla ilişkilendirir. "Buraya 5 tane fındık koydum" dediğinizde miktarı görsel olarak değerlendirebilir. Günlük işler sırasında ona "Bana 4 tane kaşık ver" gibi görevler verin.') WHERE id = '3b180a00-84f2-4ef7-b180-bb007866d4c3';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Üç Tekerlekli Bisiklette Hız". Çocuk artık bisikleti daha hızlı kullanır ve engellerin arasından manevra yaparak geçer. Bu, hem alt vücut gücünün hem de görsel-motor koordinasyonunun ileri düzeyde olduğunu gösterir. Kendi hızını denemesi için parkta güvenli "sürüş parkurları" belirleyin.') WHERE id = 'cf35973e-cf99-454b-b4d7-5058e5466945';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Şaka ve Mizah". Çocuk artık kelimelerle oynamaya ve "tuhaf" cümleler kurarak sizi güldürmeye çalışır. Örneğin, "Köpek miyav dedi" deyip gülebilir. Bu, dilin kurallarını bildiğini ve mizah yaratmak için bu kuralları bilerek ihlal ettiğini gösterir. Onunla birlikte gülün ve mizah duygusunu geliştirin.') WHERE id = '7856919f-0f1f-4c55-9554-5d9226e933f6';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '1200 günlük büyük yolculuk! Çocuk artık 40 ayı geride bıraktı. O artık kendi düşünceleri, şakaları ve hayalleri olan başlı başına bir birey, küçük bir insan. Siz bu 1200 gün boyunca onun dünyasının mimarı oldunuz. Kendine güvenen bakışlarında sizin sevginizin imzası var. Siz muhteşem bir annesiniz!') WHERE id = '1104a81e-20a0-469a-b38d-bffb8442b875';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Miktarın Korunumu Deneyleri". Aynı miktarda suyu farklı şekillerdeki kaplara döktüğünüzde, çocuk hâlâ uzun olan kapta daha fazla su bulunduğunu düşünebilir. Onunla su veya kum oyunları oynayarak miktarın şekle bağlı olarak değişmediğini deneyimleyerek keşfetmesini sağlayın.') WHERE id = '13a54bb2-22dc-4956-ad40-80e7f13eda7c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Hızla Durma ve Dönme". Çocuk artık koşarken sizin "Dur!" komutunuzla hemen durabilir veya keskin bir dönüş yapabilir. Bu, hem kasların hem de sinir sisteminin birlikte çalışmasının sonucudur. Onunla parkta "Kırmızı Işık, Yeşil Işık" oyununu oynayın; bu oyun, öz denetim (inhibitory control) becerisini geliştirir.') WHERE id = '29ee5396-69c9-428e-9152-0052da7ababd';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Nezaket ve Nüanslar". Çocuk artık ses tonunu ve kullandığı sözcükleri konuştuğu kişiye göre ayarlamaya başlar (örneğin, bebekle daha yumuşak, yetişkinlerle daha ciddi konuşur). Bu, toplumdilbilim becerilerinin başlangıcıdır. Sizin konuşma biçiminiz, onun için en temel ve kusursuz modeldir.') WHERE id = '3eaa8096-e288-4159-9aa2-8223399dd023';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal Dayanıklılık: "Kendini Övme". Çocuk bir işi başardığında "Bak, bunu ne kadar güzel yaptım!" diyerek sizden onay bekler. İçten gelen bu gurur duygusuna "Evet, çok çaba gösterdin" diyerek karşılık verin. Sizin desteğiniz, gelecekteki öz güveninin mimarıdır!') WHERE id = '97ef6f09-4fed-4fcd-abbe-7756d8045e1e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuk artık nesneleri aynı anda birden fazla özelliğe göre gruplandırabilir: "hem büyük hem de mavi olan oyuncaklar". Bu, bilişsel esnekliğin (cognitive flexibility) göstergesidir. Ona "Haydi, tüm yumuşak ve kırmızı nesneleri bulalım" gibi eğlenceli arama görevleri verin.') WHERE id = '0d946fb4-d148-46c8-80fc-f0a7b324c07f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Serbestçe Koşma ve Durma". Çocuk artık tam hızla koşarken sizin "Dur!" komutunuzla dengesini kaybetmeden hemen durabilir. Bu, sinir-kas kontrolünün ne kadar geliştiğini gösterir. Parkta oynayacağınız "Kırmızı Işık, Yeşil Işık" oyunu hem eğlenceli hem de yararlı bir egzersizdir.') WHERE id = '824aa9f8-040c-4665-a6d8-64a894fd7261';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Zıt Anlamlı Sözcükler". Çocuk artık "sıcak-soğuk", "yüksek-alçak", "ağır-hafif" gibi karşıtlıkları yalnızca anlamakla kalmaz, konuşurken de kullanır. Ona zıtlıklarla ilgili bilmeceler sorun: "Fil büyüktür, peki ya fare?". Bu, sözcük dağarcığını zenginleştirir ve karşılaştırmalı düşünme becerisini geliştirir.') WHERE id = '56f799be-0231-4113-94ee-9fbaa18f177f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor gelişiminde "İnsan Resmindeki Ayrıntılar". Çocuk artık çizdiği insana kollar, bacaklar ve hatta parmaklar eklemeye çalışır. Bu resimler, kendi bedenini ve çevresindeki insanları nasıl algıladığının bir göstergesidir. Onun her "eserini" küçük bir hikâye gibi dinleyin.') WHERE id = '0006f22d-7d35-4a7c-abab-057194f6402c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Soruların Derinleşmesi". Çocuk, "Ölüm nedir?", "Biz nereden geldik?" gibi varoluşla ilgili zor sorular sorabilir. Cevap verirken her zaman dürüst olun, ancak yaşına uygun, basit ve sakinleştirici açıklamalar seçin. Bu sorular, onun dünyayı anlamlandırma çabasıdır.') WHERE id = '5eb1ed63-47a4-4170-b1fc-b58d4507160b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal Dayanıklılık: "Yaratıcılıkla kendini ifade etme". Çocuk artık keyfi olmadığında resim yaparak veya oyuncaklarıyla "dertleşerek" rahatlıyor. Yaptığı resimlere dikkat edin; renkler ve şekiller onun iç dünyasının aynasıdır. Siz onun en güvenli limanısınız; size duyduğu güven, onun en büyük gücüdür.') WHERE id = '48efdb3a-063c-40d5-837a-9373492693c6';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuk artık çevresindeki yazılara ilgi gösteriyor. Mağaza adlarında veya kitap başlıklarında tanıdığı harfleri (örneğin, adının ilk harfini) görünce sevinebilir. Bu, "erken okuryazarlık" aşamasıdır. Ona harfleri zorla öğretmeye çalışmayın; yalnızca merakını destekleyin.') WHERE id = '4c700caf-0287-4ea7-8bd0-73ca97292800';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel gelişimde "Dönüşümlü adımlarla inme". Çocuk artık merdivenlerden inerken her basamağa sırayla bir ayağını koyarak inmeye başlıyor. Bu, merdiven çıkmaktan daha zordur ve iyi bir denge gerektirir. Siz yalnızca yakınında durarak ona güven duygusu verin.') WHERE id = '970cfec9-666d-4324-ad8a-2d2689753b64';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Kelime oyunları ve Kafiye". Çocuk benzer seslere sahip kelimeler bulmaktan keyif alır: "top-pop", "elma-gelme". Bu, fonetik farkındalığın (sesleri ayırt etme becerisinin) geliştiğini gösterir. Onunla kafiyeli kısa şiirler okuyun veya kelime oyunları oynayın. Bu, gelecekteki okuma becerisi için sağlam bir temel oluşturur.') WHERE id = '2fa13e97-2173-4c5c-afa8-90f8eaedaa8a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Düğüm ve İlmek". Çocuk artık ayakkabı bağlarına veya iplere ilgi gösteriyor ve bunları birbirine dolamaya çalışıyor. Ona büyük delikli boncuklar veya özel "bağlama oyuncakları" verin. Bu, parmaklarındaki küçük kasları yazı yazmaya ve daha karmaşık işlere hazırlar.') WHERE id = '5b2e2766-e73a-4ec2-b386-7bdc27e2bf73';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Hayali Korkular". Bu dönemde çocuğun hayal gücü o kadar güçlüdür ki karanlıktan veya hayali "canavarlardan" korkabilir. Korkusuyla alay etmeyin ve "bu gerçek değil" demeyin. Bunun yerine, "Ben buradayım, seni koruyorum" diyerek ona duygusal bir sığınak olun. Bu, size olan güvenini sarsılmaz hâle getirir.') WHERE id = 'b420b26f-d658-40bc-93d9-fcbe9a159330';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Diplomasi girişimleri". Çocuk artık anlaşmazlıkları "Sen bana bunu ver, ben de sana onu vereyim" gibi önerilerle çözmeye çalışıyor. Bu, sosyal zekânın en belirgin göstergelerinden biridir. Onun bu "müzakereci" yönünü takdir edin ve adil çözüm yollarını destekleyin.') WHERE id = '4ee1a693-af27-4c8f-b294-06b8239d80b9';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Hayali oyun arkadaşı". Bazı çocuklar bu dönemde hayali arkadaşlar oluşturabilir. Bu, çocuğun yaratıcılığının ve duygusal dünyasının zenginliğini gösterir. Onu yargılamayın veya "bu bir yalan" demeyin. Çocuk, bu arkadaşı aracılığıyla kendi korkularını ya da isteklerini keşfeder. Sabırla ve ilgiyle gözlemleyin.') WHERE id = '9ce75a82-fd02-47a8-adbb-96eadd2b8653';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Liderlik ve Uyum Sağlama". Çocuk artık oyunlarda bazen kuralları kendisi belirler, bazen de başkasının kurallarına uyum sağlar. Bu, sosyal esnekliğin temelidir. Evde onunla rolleri değiştirerek oynayın: "Şimdi sen öğretmen ol, ben de öğrenci olayım".') WHERE id = 'd0b4ac9e-9bd0-4b78-83ac-e932a23bb3ff';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Neden-Sonuç Zinciri". Çocuk artık "Eğer yağmur yağarsa parka gidemeyeceğiz" gibi mantıklı çıkarımlarda bulunur. Onunla olayların sonuçları hakkında konuşun. Bu, çocuğun gelecekte davranışlarının sorumluluğunu kavrama becerisini (mantıksal sonuçları anlama) geliştirir.') WHERE id = '44001e8a-e9dc-4edd-96dc-e3baba2b5ba4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Üç tekerlekli bisiklette bağımsızlık". Çocuk artık gidonu kontrol ederken aynı anda pedalları ritmik biçimde çevirebilir ve gerektiğinde freni kullanabilir. Bu, alt ve üst vücut koordinasyonunun eş zamanlı çalışmasıdır. Parkta küçük bir "bisiklet yolu" belirleyin.') WHERE id = 'ec14848a-2298-473c-80f2-13859ca28476';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Kibarca Rica Etme". Çocuk artık istediğini elde etmek için "olur mu?", "lütfen" gibi ifadeleri bilinçli olarak kullanır. Sizin nazik tutumunuz, onun için en iyi örnektir. Kibar davrandığında bunu mutlaka vurgulayın: "Böyle güzel rica ettiğin için sana yardım etmek beni çok mutlu ediyor".') WHERE id = 'c89c5c28-c3bd-46e0-93e1-c16bc60a714b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal Dayanıklılık: "Öz Düzenleme". Çocuk bir şeyi başaramadığında (örneğin, oyuncağı parçalarına ayrıldığında) hemen ağlamaz; size bakıp yardım ister ya da yeniden dener. Bu, duygusal olgunluk yolunda büyük bir adımdır. Siz onun en güvenilir destekçisisiniz!') WHERE id = 'a0873db2-259d-4791-a8af-c5e115589858';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuk artık nesneleri yalnızca renklerine göre değil, işlevlerine göre de gruplandırır. "Bunlar yemek içindir", "Bunlar giyinmek içindir". Evde onunla "Hangisi farklı?" oyunu oynayın (örneğin, 3 meyve ve 1 oyuncak koyun). Bu, onun mantıksal ayırt etme becerisini geliştirir.') WHERE id = 'c4b0066e-1d1d-4a2d-b280-39f147e134fe';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Hızlı Manevra". Çocuk artık tüm hızıyla koşarken önündeki engeli görüp düşmeden etrafından dolaşabilir. Bu, beyindeki "motor planlama" becerisinin üst düzeye ulaştığını gösterir. Parkta onun için küçük bir engel parkuru oluşturun. Bu, hem vücut kontrolünü hem de çevikliğini artırır.') WHERE id = 'b1971b1f-63a0-40cf-bb46-3ba6bb8689b2';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuk artık nesneleri aynı anda hem renklerine hem de şekillerine göre gruplandırabiliyor. "Bu hem kırmızı hem de daire" diyerek ayrıntıları birleştiriyor. Bu, bilişsel esnekliğin önemli bir göstergesidir. Ona farklı geometrik şekillerle dolu oyunlar sunun.') WHERE id = '2b4289d9-5b1f-4994-a054-e4727135705c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Dinamik sıçrama". Çocuk artık koşarken karşısına çıkan küçük bir engelin üzerinden hızını azaltmadan atlayabiliyor. Bu, beyinde hareketi önceden planlama (motor planning) becerisinin geliştiğini gösterir. Parkta onun için küçük engeller oluşturabilirsiniz.') WHERE id = 'ae389307-05d6-4296-90e1-0a21e776e282';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Amaca yönelik sorular". Artık yalnızca "bu nedir?" diye değil, "bu nasıl çalışır?" diye de soruyor. Nesnelerin iç mekanizmalarına, saatlere ve oyuncakların tekerleklerine ilgi gösteriyor. Yanıt verirken mantıksal sırayı koruyun; bu sorular gelecekteki bilimsel düşüncenin ilk kıvılcımlarıdır.') WHERE id = 'd2e255d4-c4cb-4992-b207-917bc8c7e987';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Simetri denemeleri". Çocuk kâğıdı katlamaya veya çizdiği resimdeki ayrıntıları (örneğin insanın iki gözünü, iki kolunu) daha simetrik yerleştirmeye çalışıyor. Bu, görsel-uzamsal farkındalığının (visual-spatial awareness) ne kadar geliştiğini gösterir.') WHERE id = 'b4315b1b-9d62-41cc-a063-b3b09c4c589a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Diplomatik" görüşmeler. Çocuk artık sizinle "pazarlık" yapıyor: "Eğer sebze yersem, sonra parkta daha uzun kalabilir miyiz?". Bu, sosyal etkileme yollarını öğrendiğini gösterir. Bu "görüşmelerde" dürüst ve tutarlı olun; sınırları bu şekilde öğrenir.') WHERE id = '431cd610-a165-475a-8f4f-464196e237c1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Hayali senaryolar". Artık oyunlar daha karmaşık: "Ben satıcıyım, sen de gelip benden ekmek al". Bu oyunlarda toplumdaki rolleri deneyimliyor. Onun senaryolarına uyarak bu yaratıcı süreci destekleyin.') WHERE id = '81128f46-ecb8-47f0-aa0b-337c398b3230';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Zaman ritüelleri". Çocuk "dün", "bugün" ve "yarın" kavramlarını henüz tam olarak ayırt edemese de ritüelleri biliyor. "Yemekten sonra park" veya "Uyumadan önce masal". Bu sıralamalar, zihninde zaman çizgisinin oluşmasını sağlar.') WHERE id = '5cb6d50d-147c-44f7-91b0-1d67f401019b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyonda "Hassas manevralar". Çocuk artık sıvı dolu bir bardağı fazla dökmeden taşıyabiliyor veya dar bir patikada yürüyebiliyor. Bu, görsel-motor koordinasyonunun ne kadar geliştiğini gösterir. Evde ona "küçük yardımcı" rolleri vererek bu dikkat becerisini pekiştirin.') WHERE id = 'efc83589-a712-4c32-9e12-c9ee0f9cee01';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Geçmişin Ayrıntıları". Çocuk artık "Dün büyükanneme gittiğimizde dondurma yedik" gibi karmaşık anılarını paylaşır. Onunla geçen gün hakkında konuşmak, epizodik belleğini güçlendirir. "Başka ne hatırlıyorsun?" diye sorarak hikâyeyi genişletmesini sağlayın.') WHERE id = 'f5184b0f-58ef-4b72-af3f-546cec7ec971';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Şekil Kopyalama". Çocuk artık sizin çizdiğiniz artı (+), daire (O) veya bazı harfleri taklit etmeye çalışır. Bu, göz ve elin birlikte çalışmasıdır (görsel-motor entegrasyon). Ona renkli kalemler verin ve farklı geometrik şekiller çizmeye teşvik edin.') WHERE id = '5ee5e247-d8bd-4375-9669-ceda6b1b0a73';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Adalet ve Kurallar". Çocuk artık oyunlarda kuralların çiğnenmesine tepki verir: "O, sırasını beklemedi!". Bu, sosyal benliğinin geliştiğini gösterir. Kuralların herkes için aynı olduğunu açıklayarak içsel adalet duygusunu ve sosyal disiplinini güçlendirebilirsiniz.') WHERE id = 'd1358d5f-b48d-4121-a736-887203ecfc67';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Liderlik Girişimleri". Çocuk artık oyunun senaryosunu kendisi oluşturmak ister: "Ben doktor olacağım, sen de hasta". Bu rol yapma oyunları aracılığıyla dünyayı anlamlandırır ve karar vermeyi öğrenir. Bazen onun senaryosuna uyun; bu, liderlik ve sorumluluk duygusunu geliştirir.') WHERE id = 'd27742a4-8533-4759-aff4-185d7dbf081f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Miktar ve Rakam Eşleştirme". Çocuk 5''e kadar saymanın yanı sıra artık "3" rakamını gördüğünde 3 oyuncağı ayırıp bir kenara koyabilir. Bu, gelecekteki matematik okuryazarlığının temelidir. Günlük işler sırasında "Bana 4 elma ver" gibi görevler verin.') WHERE id = '0f53eb59-1dad-4d39-84e5-43e97150561c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "İki Ayakla Sıçrama". Çocuk artık engellerin üzerinden iki ayağıyla aynı anda rahatça atlayabilir. Bu, hem alt vücut gücü hem de eş zamanlı koordinasyon gerektirir. Evde yere bir ip koyun ve onunla birlikte ipin üzerinden atlayarak "Nehri Geçme" oyunu oynayın.') WHERE id = '080c3ee9-a0ea-4062-9f79-5fba44d2d0e4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Şaka ve Mizah". Çocuk artık kelimeleri bilerek yanlış söyleyerek veya komik sesler çıkararak sizi güldürmeye çalışır. Bu, dil kurallarını kavramanın bir biçimidir. Şakalarına gülün ve onunla birlikte mizah duygusunu geliştirin.') WHERE id = '9fb34927-219f-4b2d-bb9f-dda7da92c634';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal Dayanıklılık: "Hatasını Kabul Etmek". Çocuk artık bir şeyi kırdığında veya etrafı dağıttığında hemen gizlemeye çalışmaz ve "Ben yaptım" diyebilir. Bu dürüstlük anında onu cezalandırmayın; bunun yerine birlikte temizlemeyi önerin. Siz onun için güvenli bir sığınaksınız!') WHERE id = 'c4b6f5da-e09e-4e7a-8e0a-9a60747fa087';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Duygu sözlüğü". Çocuk artık sadece "kötüyüm" ya da "iyiyim" demiyor. "Sinirlendim", "özledim", "mutluyum" gibi ifadeleri yerinde kullanıyor. Duygularını kabul edip onaylayın: "Özlediğin için ağlaman normal". Bu, onun duygusal sağlığının en büyük güvencesidir.') WHERE id = 'e498f733-de85-4e45-8875-b886111a89f8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '3 buçuk yaşın zirvesinde! Çocuk artık bebeklik dönemini tamamen geride bıraktı ve "erken çocukluk" döneminin en hareketli evresinde. O artık hem fiziksel hem de duygusal açıdan başlı başına bir birey. Siz bu 1250 günde onun dünyasında sarsılmaz bir güven temeli oluşturdunuz. Kendinizle gurur duyun!') WHERE id = 'a45a87d4-253c-4fea-ac32-9cea3f5b1168';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuk artık çevresindeki yazılara ilgi gösteriyor. Mağaza adlarında veya kitap başlıklarında tanıdığı harfleri (örneğin, adının baş harfini) görünce sevinebilir. Bu, "erken okuryazarlık" evresidir. Ona harfleri zorla öğretmeyin; yalnızca ilgisini teşvik edin.') WHERE id = '0aedbd42-1452-4a3e-aa54-4adb1ad4a556';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel gelişimde "Dönüşümlü adımlarla inme". Çocuk artık merdivenlerden inerken her basamağa sırayla bir ayağını basarak inmeye başlıyor. Bu, merdiven çıkmaktan daha zordur ve iyi bir denge gerektirir. Siz yalnızca yakınında durarak ona güvende olduğunu hissettirin.') WHERE id = '4a1598de-455f-4bae-a8b3-0f5696c065c6';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Kelime oyunları ve Kafiye". Çocuk benzer seslere sahip kelimeler bulmaktan keyif alır: "top-pop", "alma-salma". Bu, fonolojik farkındalığın (sesleri ayırt etme becerisinin) geliştiğini gösterir. Onunla kafiyeli kısa şiirler okuyun veya kelime oyunları oynayın. Bu, gelecekteki okuma becerisi için sağlam bir temel oluşturur.') WHERE id = '3f6a6fa9-4e7a-4539-93e7-6da1070ea997';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor gelişiminde "Düğüm ve İlmek". Çocuk artık ayakkabı bağlarına veya iplere ilgi gösteriyor ve onları birbirine dolamaya çalışıyor. Ona büyük delikli boncuklar veya özel "bağlama oyuncakları" verin. Bu, parmaklardaki küçük kasları yazı yazmaya ve daha karmaşık işlere hazırlar.') WHERE id = 'cf6a8a3d-c742-40b0-a3c1-38fd2db89aec';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Hayali Korkular". Bu dönemde çocuğun hayal gücü o kadar kuvvetlidir ki karanlıktan veya hayali "canavarlardan" korkabilir. Korkusuna gülmeyin, "bu gerçek değil" demeyin. Bunun yerine, "Ben buradayım, seni koruyorum" diyerek ona duygusal bir sığınak olun. Bu, size duyduğu güveni sarsılmaz hâle getirir.') WHERE id = '09cee55c-899d-468c-bef9-66eb86e868c6';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Diplomasi girişimleri". Çocuk artık anlaşmazlıkları "Sen bana bunu ver, ben de sana şunu vereyim" gibi önerilerle çözmeye çalışıyor. Bu, sosyal zekânın en belirgin göstergelerinden biridir. Onun bu "müzakereci" yönünü takdir edin ve adil çözüm yollarını destekleyin.') WHERE id = '1f6c2927-0b20-482c-b17f-a447f8fef25d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Sınırlar ve Paylaşmak". Çocuk artık bazı eşyaların herkesin kullanımına açık olduğunu (örneğin parktaki salıncak), bazılarının ise yalnızca kendisine ait olduğunu anlar. Ona "Bu senin oyuncağın, paylaşmak senin seçimin" diyerek sahiplik duygusuna saygı gösterin. Kendi eşyalarına saygı gösterilen çocuk, başkalarının eşyalarına da daha kolay saygı duyar.') WHERE id = '9f384019-50a1-4540-baab-8643e931568a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Karmaşık rol oyunları". Artık oyunların bir olay örgüsü vardır: "Sen hastasın, ben doktorum, sana iğne yapacağım". Bu oyunlar sayesinde gerçek hayattaki korkularını (örneğin doktor korkusunu) işler. Onun senaryosuna aktif olarak katılın.') WHERE id = '9206ce15-0a76-4431-b07b-049bdcbed6b0';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Miktar ve sayı eşleştirmesi". Çocuk artık 5''e kadar sayabilir ve "3" dendiğinde 3 nesneyi görsel olarak ayırabilir. Ona "Bana 4 tane kaşık ver" gibi görevler verin. Bu, soyut sayıların gerçek dünyayla ilk kez ciddi biçimde ilişkilendirildiği aşamadır.') WHERE id = 'eaf2d09d-f792-4b9d-ab37-65dbbde32f39';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "İki ayakla sıçrama". Çocuk artık engellerin (örneğin yerdeki ipin) üzerinden iki ayağıyla aynı anda rahatça atlayabilir. Bu, hem alt vücut gücü hem de eş zamanlı koordinasyon gerektirir. Evde onunla "Nehri geçme" oyunu oynayarak hareketliliğini artırın.') WHERE id = '9a61025f-abc9-4c98-bf07-819847137992';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Şaka ve Mizah". Çocuk, kelimeleri bilerek yanlış söyleyerek veya komik sesler çıkararak sizi güldürmeye çalışır. Bu, dilin kurallarını bildiğini ve mizah yaratmak için bu kuralları bilinçli olarak bozduğunu gösterir. Şakalarına gülmeniz, özgüvenini ve sosyal zekâsını destekler.') WHERE id = 'b25c4c56-1f97-4223-b20b-689b5e94d1d3';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal dayanıklılık: "Başarısızlıkla başa çıkma". Çocuk artık bir şeyi (örneğin küplerden kule yapmayı) başaramadığında hemen ağlamaz; size bakıp "Yeniden yapayım mı?" diyebilir. Sonucu değil, çabasını övün: "Çok uğraştın, aferin!". Siz onun en büyük motivasyon kaynağısınız!') WHERE id = 'f9148bba-3642-4b13-ad48-62db8da7ed80';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuk artık nesneleri yalnızca görünüşlerine göre değil, yapıldıkları malzemeye göre de ayırt eder: "Bu plastik, bu ise demir". Ona farklı dokulara sahip nesneler verin ve aralarındaki farkları sorun. Bu, çevresindeki dünyayı daha ayrıntılı analiz etmesine ve fiziksel dünya hakkındaki bilgilerini düzenlemesine yardımcı olur.') WHERE id = '80e00e5a-2a93-4c1b-a710-db553822e4ae';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Tek ayak üzerinde denge". Çocuk artık tek ayağının üzerinde 5 saniyeden uzun süre durabilir. Bu, beyincik ve kas koordinasyonunun olgunlaştığını gösterir. Onunla "leylek oyunu" oynayarak kimin daha uzun süre durabildiğine bakın.') WHERE id = '18ab2c20-2470-41d2-b5e5-3121b8d7e0c1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Miktarın Korunumu Deneyleri". Aynı miktarda suyu farklı şekillerdeki kaplara döktüğünüzde çocuk hâlâ uzun kapta daha fazla su olduğunu düşünebilir. Onunla su veya kum oyunları oynayarak miktarın şekle bağlı olarak değişmediğini deneyimleyerek keşfetmesine fırsat verin.') WHERE id = '73557d3a-6c9c-4c6a-a67f-c5d4bc801f0d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Hızlı Durma ve Dönme". Çocuk artık koşarken sizin "Dur!" komutunuzla hemen durabilir veya keskin bir dönüş yapabilir. Bu, kas ve sinir sisteminin birlikte çalışmasının sonucudur. Onunla parkta "Kırmızı Işık, Yeşil Işık" oyununu oynayın; bu oyun, öz denetim becerisini geliştirir.') WHERE id = '2c94b5e7-3f3c-4f5a-97ae-e15891e8c592';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Nezaket ve Nüanslar". Çocuk artık ses tonunu ve kullandığı kelimeleri konuştuğu kişiye göre ayarlamaya başlar (örneğin, bebekle daha yumuşak, yetişkinlerle daha ciddi konuşur). Bu, toplumdilbilimsel farkındalığın başlangıcıdır. Sizin konuşma biçiminiz, onun için en temel ve kusursuz örnektir.') WHERE id = '708f00c5-3974-4a48-b57b-7ac187203dd5';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal Dayanıklılık: "Kendini Övme". Çocuk bir işi başardığında "Bak, bunu ne güzel yaptım!" diyerek sizden onay bekler. Onun bu içsel gurur duygusuna "Evet, çok çaba gösterdin" diyerek karşılık verin. Sizin desteğiniz, onun gelecekteki özgüveninin mimarıdır!') WHERE id = '1eae35d0-6f20-4979-87f2-c88eacf3b104';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuk artık "önce, şimdi, sonra" sıralamasını karmaşık olaylara uygulayabilir. "Önce ellerimi yıkayacağım, sonra yemek yiyeceğim, en son da oyun oynayacağım". Bu, beynindeki planlama becerisinin (yürütücü işlev) geliştiğini gösterir. Ondan gün içinde küçük planlar yapmasını isteyin. Bu, düzen ve disiplin duygusunu güçlendirir.') WHERE id = 'c4e864cd-f8ff-486c-994b-11d240e723ca';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Üç Tekerlekli Bisikletle Manevra". Çocuk artık bisiklet sürerken önüne çıkan engelleri görüp gidonu zamanında çevirebilir. Bu, hem pedalları çevirme (fiziksel) hem de yolu takip etme (görsel) becerilerinin kusursuz bir birleşimidir.') WHERE id = '63226ba2-0699-459a-be66-a4c9af97d876';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Neden-Sonuç Diyalogları". Çocuk artık verdiğiniz kararları sorgular: "Neden uyumalıyım?". Yanıt verirken mantıklı açıklamalar yapın: "Çünkü yarın yeniden enerjik bir şekilde oynayabilmen için vücudunun dinlenmesi gerekiyor". Bu yaklaşım, çocukta körü körüne itaat yerine mantığa dayalı bir disiplin geliştirir.') WHERE id = 'aba02008-e74d-4081-9df9-4e23bad078b6';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Kâğıt Kesme". Çocuk artık güvenli bir makasla kâğıdı düz bir çizgi boyunca (veya basit bir daire şeklinde) kesmeye çalışır. Bu, el-göz koordinasyonunun en önemli sınamalarından biridir. Ona renkli kâğıtlar ve kesebileceği şablonlar vererek kaslarını çalıştırmasını sağlayın.') WHERE id = 'd337c2b8-8f8a-4037-8a7a-e030f9920b04';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Sıfatların zenginliği". Çocuk artık eşyaları tarif ederken yalnızca renklerini söylemekle kalmaz, "yumuşak", "dikenli", "pürüzsüz" gibi sözcükler de kullanır. Onunla "Dokun ve bul" oyunu oynayın: Gözlerini kapatıp eşyanın nasıl hissettirdiğini anlatmasını isteyin.') WHERE id = '6a7056fe-a7e8-4d7e-91b2-4d5b5277e537';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Sembollerin keşfi". Çocuk artık bazı harfleri (özellikle adının ilk harfini) veya rakamları kopyalamaya çalışır. Bu, görsel sembollerle ses ve anlam arasındaki bağlantıyı kavradığını gösterir. Kum üzerinde veya renkli kalemlerle "yazı" alıştırmaları yapmasını sağlayın.') WHERE id = 'b57332a7-c381-44a7-bdb8-aef8d6820036';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Özdenetim ve Sabır". Çocuk artık istediği bir şey için 5-10 dakika beklemesi gerektiğini (örneğin yemek hazır olana kadar) daha sakin karşılar. Sizin "biraz bekle" demenizi ceza olarak değil, zamana bağlı bir gereklilik olarak kabul eder. Bu sabrını gördüğünüzde "Beklediğin için çok teşekkür ederim" diyerek onu mutlaka destekleyin.') WHERE id = '7374ce80-a74f-4d7f-bb0f-135ec7c6d431';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Empati ve Teselli". Çocuk artık sizin yorgun olduğunuzu veya bir arkadaşının üzüldüğünü fark ettiğinde ona oyuncağını getirebilir ya da şefkatle dokunabilir. Bu, iç dünyasının ne kadar zenginleştiğini ve "ben" odaklı düşünceden çıkıp "biz" bilincine yöneldiğini gösterir.') WHERE id = '62ab0290-ec13-4b50-86f2-b4a69aba6dda';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Hacim algısı". Artık büyük bir kutunun içine kaç küçük oyuncağın sığacağını tahmin etmeye çalışır. Ona farklı boyutlarda kaplar verin ve "Sence bu su o kaba sığar mı?" diye sorun. Bu deneyimler, gelecekteki matematik ve fizik kavramlarının temelini oluşturur.') WHERE id = 'd68476f5-47bc-4622-82c1-31e6c34eeecd';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Geri geri yürüme". Çocuk artık geriye doğru kendinden emin biçimde, dengesini kaybetmeden birkaç adım atabilir. Bu hareket, beden farkındalığını (propriyosepsiyon) güçlendirir. Onunla parkta "yengeç yarışı" oynayarak hem eğlenin hem de kaslarını çalıştırın.') WHERE id = 'ff4d4dbc-967a-48e5-b6f7-ae29e0a5390d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Nezaket ve İncelikler". Çocuk artık ses tonunu konuştuğu kişiye göre ayarlamaya başlar (örneğin bebekle daha yumuşak, yetişkinlerle daha ciddi konuşur). Bu, toplumdilbilimin başlangıcıdır. Sizin konuşma biçiminiz, onun için en temel ve en kusursuz örnektir.') WHERE id = '3f691af2-a53f-4e9e-bda8-73c25f9784e5';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '1280 günlük büyük gelişim! Çocuk artık "erken çocukluk" döneminin en verimli zamanındadır. O artık kendi zevkleri, korkuları ve bitmek bilmeyen sorularıyla başlı başına bir bireydir; küçük bir insan. Siz bu yolda bilim ve sevgiyle ilerlediniz. "Anacan" her zaman yanınızda!') WHERE id = 'cb9230b0-c04d-4749-92fd-37201aec8ecd';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuk artık nesneleri yalnızca bir değil, iki özelliğine göre gruplandırabilir: "hem kırmızı hem de küçük olan arabalar". Bu, bilişsel esnekliğin önemli bir aşamasıdır. Ona farklı oyuncakları karışık olarak verin ve "Yumuşak ve mavi olanların hepsini bul" diyerek zihnini çalıştırın.') WHERE id = '7f3f7af2-f05b-47b3-bb9a-bf661d551477';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Hedefe Yönelik Sıçrama". Çocuk artık bulunduğu yerden hem yukarıya hem de belirli bir hedefe doğru (örneğin yerdeki dairenin içine) sıçrayabilir. Bu, hem denge hem de mekânsal mesafeyi hesaplama becerisini gösterir. Parkta "taştan taşa atlama" oyunu onun için harika bir egzersizdir.') WHERE id = 'b66ed3bb-08b0-48a9-9270-0f8d21791b6b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Zaman Sıralaması". Artık "önce, şimdi, sonra" kavramlarını daha doğru kullanır: "Önce ellerimi yıkayacağım, sonra yemek yiyeceğim". Onunla günün planını konuşmanız, düzen ve güven duygusu geliştirmesine yardımcı olur. "Şimdi ne yapacağız?" sorularına her zaman sırasıyla yanıt verin.') WHERE id = '4a19271e-0252-465e-a5b6-220dfc833dfa';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Şekil Kopyalama: Üçgen ve Artı". Çocuk artık düz çizgileri kesiştirerek artı (+) çizebilir ve üçgene benzeyen şekiller oluşturmaya çalışır. Bunlar, yazı yazma becerisinin ilk temelleridir. Ona renkli kalemler ve boş kâğıtlar vererek bu "geometrik keşiflerini" destekleyin.') WHERE id = '5e0bb7b8-fe4c-40a9-87b2-d5ec3dff9314';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Öz Yönetim ve Duygular". Çocuk öfkelendiğinde veya üzüldüğünde bazen sakinleşmek için sizin önerdiğiniz yöntemleri (örneğin derin nefes almayı) kullanabilir. Bu, duygusal zekânın kazandırdığı en önemli yaşam becerilerinden biridir. Sakinleştiğinde gösterdiği bu çabayı mutlaka övün.') WHERE id = 'cab1e84e-d4d4-48e6-a7cb-8122f2485764';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Takım Oyunları". Çocuk artık başka bir çocukla ortak bir amaç için (örneğin büyük bir kumdan kale yapmak için) iş birliği yapabilir. Bu, "paralel oyun"dan "sosyal oyun"a tam geçiştir. Arkadaşlarıyla anlaşma çabalarını gözlemleyin ve destekleyin.') WHERE id = '35da39d6-0c56-4410-8592-5e1cbd4b1e03';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Sayı-Miktar Eşleştirmesi". Çocuk 10''a kadar sayabilir; artık "3" rakamını gördüğünde 3 oyuncağı ayırıp bir kenara koyabilir. Bu, matematiksel düşünmenin en önemli aşamalarından biridir. Günlük yaşamda "Bana 2 kaşık ver" gibi görevlerle bu bağlantıyı güçlendirin.') WHERE id = '4397b751-5eff-493f-b5d9-774c99d1ca07';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topu iki elle yakalama". Çocuk artık kendisine doğru yavaşça atılan büyük bir topu iki eliyle (bazen göğsüne bastırarak) yakalamaya çalışır. Bu hareket hem el-göz koordinasyonu hem de tepki hızı gerektirir. Onunla yakın mesafeden oynayın.') WHERE id = '416872cb-a02b-4d4e-ac74-f040d4ce096b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Nazik Ricalar". Çocuk artık istediğini elde etmek için "olur mu?", "lütfen" gibi ifadeleri bilinçli olarak kullanır. Sizin nazik tutumunuz onun en önemli örneğidir. Nazik davrandığında bunu mutlaka vurgulayın: "Böyle güzel rica ettiğin için sana yardım etmek beni çok mutlu ediyor".') WHERE id = 'eb838920-fe5c-415a-a9ba-0dabdeaffb4e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal Dayanıklılık: "Hatasını Kabul Etmek". Çocuk artık bir şeyi kırdığında hemen saklamaya çalışmaz ve "ben yaptım" diyebilir. Dürüst davrandığı bu anda onu cezalandırmayın; bunun yerine birlikte temizlemeyi önerin. Bu, onda sorumluluk duygusunun gelişmesini sağlar. 1290 günlük yolculuğun her anı değerlidir!') WHERE id = 'fba8e58a-849a-4502-b3b8-829b5d503078';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuk artık "eğer... o zaman..." mantığını tamamen kavrar. "Eğer oyuncağı kırarsam bir daha çalışmaz". Bu, geleceği öngörme becerisinin başlangıcıdır. Ona davranışlarının sonuçlarını önceden düşünmesini önerin: "Sence bardağı kenara koyarsak ne olur?". Bu, sorumluluk duygusunun gelişmesini sağlar.') WHERE id = '98264d01-8080-47ff-9743-5076f3c1e9fb';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Statik Denge Zirvesi". Çocuk artık hiçbir yere dokunmadan tek ayağının üzerinde 5-10 saniye durabilir. Bu, hem iç kulaktaki denge merkezinin hem de bel ve bacak kaslarının güçlendiğini gösterir. Onunla "donduk" oyunu oynayarak bu becerisini eğlenceye dönüştürün.') WHERE id = 'e5ea1656-41df-45ea-937c-07b3a21bce4f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Karmaşık Hikâye Oluşturma". Artık resimli bir kitaba baktığında yalnızca nesneleri değil, olaylar arasındaki bağlantıyı da açıklar: "Tavşan kaçıyor çünkü tilki geliyor". Hayal gücünü desteklemek için "Sence tilki ne söyleyecek?" gibi sorular sorun. Bu, bilişsel esnekliğini artırır.') WHERE id = '991395b5-cce5-4484-973b-52ea93850c86';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Parmakların Bağımsız Hareketi". Çocuk artık parmaklarını birbirine vurarak veya parmak uçlarıyla küçük boncukları ipe dizerek karmaşık işler yapar. Bu, beynin iki yarım küresi arasında koordinasyon gerektirir. Ona düğme ilikleme veya ilik açma oyunları önerin.') WHERE id = '7718afa5-181a-4995-b727-92bfdea228d9';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Hayali Korkuları Yönetmek". Bu yaştaki çocuklar bazen karanlıktan veya "canavarlardan" korkabilir. Onun korkusunu inkâr etmeyin; aksine "canavarı kovan sihirli fener" gibi oyunlar oluşturun. Duygusal desteğiniz, bu korkuların geçici olduğunu öğrenmesine yardımcı olur.') WHERE id = '5da5688a-9254-4a8e-94a4-a6cdb8624f11';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Sonuca Yönelik İş Birliği". Çocuk artık başka bir arkadaşıyla birlikte büyük bir kule yapmak için "taşları" paylaşabilir. Bu, artık yalnızca yan yana değil, ortak bir amaç için oynamaktır (iş birlikçi oyun). Onun bu sosyal ve uzlaşmacı yönünü "Çok güzel bir takım oldunuz!" diyerek alkışlayın.') WHERE id = '12a2b82c-6975-4312-a2f7-fbbdcf5d9909';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Miktarın Korunumu Testi". Çocuk hâlâ yassılaştırılmış oyun hamurunun, hamur topundan daha büyük olduğunu düşünebilir. Onunla bu tür deneyler yapın: Hamur topunu yassılaştırın, ardından yeniden top hâline getirin. Bu, fiziksel dünyanın değişmez kurallarını kavramasına yardımcı olur.') WHERE id = 'ae824ed0-4f75-4515-b7bf-83483a6c043d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyonda "Top Sürme". Çocuk artık topa yalnızca vurmakla kalmıyor, ayağıyla hafifçe ileri iterek (dribbling) hareket ettirmeye çalışıyor. Bu, dinamik denge ve ayak-göz koordinasyonu gerektirir. Parkta onun için küçük bir "futbol parkuru" hazırlayın ve topu hedefe doğru sürmesini isteyin.') WHERE id = '6f891729-8e3d-4c9f-bdb3-588b6de557c3';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Nezaket ve Görgü". Çocuk artık "özür dilerim", "lütfen" gibi ifadeleri yalnızca ezberden değil, amacına uygun şekilde kullanıyor. Sizin başkalarıyla konuşurken kullandığınız ton, onun en önemli rehberidir. Nazik davrandığında, bu davranışın çevresindeki kişiler üzerinde yarattığı olumlu etkiyi fark etmesini sağlayın.') WHERE id = '8553307b-a429-4fdd-a8d5-b4776f0fb3d5';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '1300 günlük muhteşem yolculuk! Çocuk artık bebeklik alışkanlıklarını tamamen geride bırakıp okul öncesi dönemin en aktif aşamasına geçiyor. Artık kendini bir "ben" olarak tanıyor ve dünyayı değiştirmeye hazır. Siz bu 1300 gün boyunca onun en güvenilir rehberi oldunuz. Sevginiz ve sabrınız için kendinize teşekkür edin!') WHERE id = '7883dc4b-dac2-42dc-8a35-51e8d5b489b1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '44. aya hoş geldiniz! Çocuk artık "ben büyüdüm" duygusunu derinden yaşıyor. Bu dönemde ona kendi kıyafetini seçmek veya sofrayı kurmak gibi küçük sorumluluklar verin. Bu, bağımsız olma isteğini olumlu yönde destekler ve öz güvenini artırır.') WHERE id = 'aad2ad75-5a11-4a2d-9c7c-2bc5d48aa312';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Akıcı Manevra". Çocuk artık tam hızla koşarken önündeki engeli fark edip düşmeden etrafından dolaşabiliyor. Bu, beyindeki "motor planlama" becerisinin en ileri düzeyidir. Parkta onun için küçük bir engel parkuru hazırlayın. Bu, hem beden kontrolünü hem de çevikliğini artırır.') WHERE id = '5ff72db7-e0be-4353-a758-f27d398fc0b7';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Soruların Niteliği". Artık yalnızca "bu nedir?" diye değil, "bu neden böyle?" diye soruyor. Olayların ardındaki mantığı anlamaya çalışıyor. Yanıt verirken hayal gücünü de harekete geçirin: "Sizce neden yağmur yağıyor?". Bu, yaratıcı ve bilimsel düşünme becerilerini destekler.') WHERE id = '104d37cc-f454-4cee-bc62-45a7dd638317';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor gelişiminde "Şekil Kopyalama: Kare ve Üçgen". Çocuk artık köşeleri olan şekiller çizmeye çalışıyor. Bu, daire çizmekten daha zordur; çünkü kalemi belirli bir noktada durdurup yönünü değiştirmeyi gerektirir. Ona köşeli şekilleri birleştirerek "ev" veya "araba" çizmeyi gösterin.') WHERE id = '72c3574b-2a9a-4755-8727-8d01b439e56e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Adalet ve Kurallar". Çocuğunuz artık oyunlarda kuralların ihlal edilmesine sert tepki veriyor: "O, sırasını bozdu!". Bu, sosyal benlik ve etik anlayışın geliştiğini gösterir. Kuralların herkes için aynı olduğunu açıklayarak içsel adalet duygusunu ve sosyal disiplinini güçlendirebilirsiniz.') WHERE id = '6e14d59c-92a1-4b52-9746-19ec45e3a240';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Diplomasi Girişimleri". Çocuğunuz anlaşmazlıkları "Sen bana bunu ver, ben de sana şunu vereyim" gibi tekliflerle çözmeye çalışıyor. Bu, sosyal zekânın en belirgin göstergelerinden biridir. Onun bu "müzakereci" yönünü takdir edin ve adil çözüm yollarını destekleyin.') WHERE id = '1bc59678-d965-4c53-ad57-e91ac3a6bece';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Miktarı Anında Tanıma (Subitizing)". Çocuğunuz artık 3 veya 4 nesneyi saymadan, yalnızca bakarak kaç tane olduğunu anlayabiliyor. Ona farklı sayıda noktalar bulunan kartlar gösterin ve kaç tane olduğunu hemen söylemesini isteyin. Bu, gelecekteki hızlı matematiksel hesaplama becerisinin temelidir.') WHERE id = '9268aa12-9e8f-498d-a13c-fd38e4e68957';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topu Omuz Üstünden Atma". Çocuğunuz artık topu yalnızca yere bırakmıyor; omuz hizasından uzağa ve belirli bir hedefe doğru atabiliyor. Bu, tüm vücudun koordinasyonunu ve gücünü ayarlamayı gerektirir. Onunla parkta hedefe top atma oyunları oynayın.') WHERE id = 'dbdc7993-c5ce-4ff8-a2f5-69daf1b98fea';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Şaka ve Mizahın Derinleşmesi". Çocuğunuz artık kelimelerin anlamlarını değiştirerek şakalar yapıyor. Örneğin, size "Baba" deyip gülebilir. Bu, dil kurallarını iyi bildiğini ve mizah yaratmak için onları kasıtlı olarak bozduğunu gösterir. Onunla birlikte eğlenin.') WHERE id = '8c83e3c0-4591-49c2-a059-525f584c28d3';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal Dayanıklılık: "Sabır Testi". Çocuğunuz artık istediği bir şey için birkaç dakika boyunca (örneğin, siz telefonla konuşurken) sessizce bekleyebiliyor. Bu, öz denetim becerisinin güçlendiğini gösterir. Bekledikten sonra ona mutlaka "Beni beklediğin için çok teşekkür ederim" diyerek teşekkür edin.') WHERE id = '75df2db1-9a5a-4048-99dc-80b484b6d396';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık çevresindeki logoları ve yazıları tanıyabiliyor. Örneğin, sevdiği dondurma markasını veya marketin logosunu gördüğünde adını söylüyor. Bu, sembolik düşüncenin geliştiğini gösterir. Ona farklı trafik işaretlerini veya basit piktogramları göstererek anlamlarını sorun. Bu, gelecekteki okuma becerisinin görsel temelidir.') WHERE id = 'bb1f5dc6-7300-4f63-9d44-40f2e54dfb71';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Geriye Doğru Sıçrama". Çocuğunuz artık geriye doğru küçük sıçramalar yapabiliyor. Bu, hem denge hem de bedenini mekân içinde kontrol etme becerisinde yeni bir seviyedir. Onunla "Yengeç ve Kurbağa" yarışı oynayarak hareketliliğini teşvik edin.') WHERE id = '2c74b1f3-a8fd-4086-88da-377857855b8c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Karşıtlıkları Karşılaştırma". Çocuk artık "en büyük", "daha küçük", "çok ağır" gibi karşılaştırma ifadelerini cümle içinde doğru yerde kullanıyor. Ona 3 farklı boyutta oyuncak verin ve "En büyüğü hangisi?" diye sorun. Bu, kelime dağarcığının hem nicelik hem de nitelik açısından zenginleştiğini gösterir.') WHERE id = 'f9bd7f70-01bc-46e8-8391-e80ede82d1cc';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "İnsan Figüründe Orantı". Çocuk artık insan resmi çizerken vücut bölümlerini daha mantıklı biçimde yerleştiriyor; gözler yüzün ortasında, kollar ise gövdenin yanlarında oluyor. Bu resimler, kendi bedenine ilişkin farkındalığının (beden algısının) geliştiğini yansıtır.') WHERE id = 'b857a3b6-e216-49cf-a9c0-e7adabf3fdba';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Kendini Tanımlama". Çocuk artık kendisini tanımlayabiliyor: "Ben sarışınım", "Ben hızlı koşarım". Bu, bireysel kimliğinin güçlendiğini gösterir. Ona "Başka neleri seviyorsun?" gibi sorular sorarak kendisini tanımasına yardımcı olun. Kendisi hakkında olumlu düşünmesi, gelecekteki özgüveninin temelidir.') WHERE id = '9ca9132e-1f05-4086-b977-373ac1739718';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Diplomasi ve Müzakere". Çocuk artık bir şeyi elde etmek için "Sen bana bunu verirsen ben de sana bunu veririm" gibi teklifler sunuyor. Bu, sosyal zekâsının ve problem çözme becerisinin ileri düzeyde geliştiğini gösterir. Onun bu adil "pazarlık" girişimlerini destekleyin ve olumlu karşılayın.') WHERE id = '68e14866-1913-4e48-a5b0-15a89d136783';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Zamanı Rutinlerle Anlamlandırma". Çocuk, "Sabah uyandığımda", "Akşam yatarken" gibi ifadelerle günün farklı zaman dilimlerini birbirinden ayırıyor. Onunla ertesi günün planlarını "önce, sonra, en son" sırasıyla konuşun. Bu, onda güven ve düzen duygusu oluşturur.') WHERE id = 'fc45f60c-b22c-4712-b519-43e1ec159d0a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topu Ayakla Kontrol Etme". Çocuk artık topa yalnızca vurmuyor, ayağıyla biraz ileri iterek topu sürmeye (dribbling) çalışıyor. Bu, dinamik denge ve dikkat gerektirir. Onun için parkta küçük bir "futbol parkuru" oluşturun ve topu hedefe doğru sürmesini isteyin.') WHERE id = '27b3b770-0010-4e27-a15b-7e39df48e572';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Nezaket ve Sosyal Görgü". Çocuk artık "özür dilerim", "izin verir misiniz?" gibi ifadeleri duruma uygun biçimde kullanıyor. Sizin başkalarıyla kurduğunuz iletişim, onun için en önemli örnektir. Nazik davrandığında, bu davranışının karşı tarafta yarattığı olumlu etkiyi fark etmesini sağlayın: "Böyle nazik olduğun için herkes sana gülümsüyor".') WHERE id = 'eddeff81-68cf-4451-8b49-9db4335c7821';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal Dayanıklılık: "Başarısızlığı Kabullenme". Çocuk artık bir şeyi başaramadığında (örneğin, yapbozu tamamlayamadığında) hemen öfkelenmiyor; yeniden deniyor veya yardım istiyor. Sonucu değil, gösterdiği çabayı övün: "Çok çabaladın ve pes etmedin, aferin!".') WHERE id = '3c009bb9-dfc9-4682-a20a-9afa3ba74f26';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuk artık nesneleri hem rengine hem de malzemesine göre aynı anda gruplandırabiliyor: "Bu hem mavi hem de yumuşak." Bu, bilişsel esnekliğin önemli bir göstergesidir. Ona ahşap, kumaş ve plastik gibi farklı dokulara sahip nesnelerle oynayabileceği oyunlar sunun.') WHERE id = 'b98d1c0b-fdd1-4aeb-a1f1-d636c58ba6b7';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Dinamik sıçrama". Çocuk artık koşarken karşısına çıkan küçük bir engelin üzerinden hızını azaltmadan atlayabiliyor. Bu, beyinde hareketi önceden planlama (motor planning) becerisinin geliştiğini gösterir. Parkta onun için küçük engeller oluşturabilirsiniz.') WHERE id = '60d3fdb2-caa2-4bc5-bc84-452616921b80';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Zaman ritüelleri". Çocuk "dün", "bugün" ve "yarın" kavramlarını henüz tam olarak ayırt edemese de rutinleri biliyor. "Yemekten sonra park" veya "Uyumadan önce masal". Bu sıralamalar, zihninde zaman çizgisinin oluşmasına yardımcı olur.') WHERE id = '95122e91-e077-4e38-a3b4-27a4e9e756f1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerde "Simetri denemeleri". Çocuk kâğıdı katlamaya veya çizdiği resimdeki ayrıntıları (örneğin bir insanın iki gözünü ve iki kolunu) daha simetrik yerleştirmeye çalışır. Bu, görsel-mekânsal algısının ne kadar geliştiğini gösterir.') WHERE id = '27b05f17-57a4-4b79-9091-f702b81309dd';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Siyasi" pazarlıklar. Çocuk artık sizinle "pazarlık" ediyor: "Sebzemi yersem sonra parkta daha uzun kalabilir miyiz?" Bu, sosyal etkileme yollarını öğrendiğini gösterir. Bu "pazarlıklarda" dürüst ve tutarlı olun; sınırları bu şekilde öğrenir.') WHERE id = '0875811d-7343-4ba3-a29e-c235cba78b04';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Hayalî senaryolar". Artık oyunlar daha karmaşık: "Ben satıcıyım, sen de gelip benden ekmek al." Bu oyunlarda çocuk, toplumdaki rolleri deneyimler. Onun senaryolarına eşlik ederek bu yaratıcı süreci destekleyin.') WHERE id = 'c35d44af-1b5b-4a3a-b44c-143278463e37';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Nesnelerin işlevi". Çocuk artık nesneleri yalnızca görünümlerine göre değil, işlevlerine göre de gruplandırıyor. "Bunlar kesmeye yarayan araçlar", "Bunlar ise yazmaya yarayan araçlar." Bu, zihnindeki bilgi birikiminin daha sistemli ve işlevsel hâle geldiğini gösterir.') WHERE id = '52b43fec-3fc9-4135-bc89-1ca56d2c89c9';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyonda "Hassas manevralar". Çocuk artık sıvı dolu bir bardağı fazla dökmeden taşıyabiliyor veya dar bir patikada yürüyebiliyor. Bu, görsel-motor koordinasyonunun ne kadar geliştiğini gösterir. Evde ona "küçük yardımcı" rolleri vererek dikkat becerisini güçlendirin.') WHERE id = 'b2a95188-79e5-4c80-963a-2302704140ca';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Duygu sözlüğü". Çocuğunuz artık yalnızca "kötüyüm" veya "iyiyim" demiyor. "Sinirlendim", "özledim", "mutluyum" gibi ifadeleri yerinde kullanıyor. Duygularını onaylayın: "Özlediğin için ağlaman normal". Bu, onun duygusal sağlığının en büyük güvencesidir.') WHERE id = '8d118e2f-9e48-4f84-bdd9-4688744f285c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '1330 Günlük Zirve! Çocuğunuz artık resmen "küçük çocukluk" döneminin en aktif ve bilinçli evresinde. O artık hem fiziksel hem de duygusal açıdan tam bir birey. Siz bu yolu bilim ve sevgiyle katettiniz. "Anacan" her zaman yanınızda!') WHERE id = 'ee7d4f4f-acca-4792-810c-9ebdc339da81';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '45. aya hoş geldiniz! Çocuğunuz artık çevresindeki yazılarda tanıdığı harfleri aramaya başlıyor. Özellikle adının ilk harfini her yerde tanıyabilir. Bu, okuma becerisinin ilk aşamasıdır. Ona harfleri zorla öğretmeyin; yalnızca gördüğü harflerin adını ve sesini oyun yoluyla söyleyin.') WHERE id = 'c1854d46-26a3-452c-9eb7-697ec5a92d6c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Üç tekerlekli bisiklette tam kontrol". Çocuğunuz artık pedal çevirmeyi bırakmadan gidonu çevirerek dar virajları dönebiliyor. Bu, hem alt vücut gücünün hem de görsel-mekânsal koordinasyonun zirvesidir.') WHERE id = 'ee3c0b22-95f2-4059-93bc-287ff0eb00cf';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Tahmin becerisi". Masal okurken çocuğunuz artık "Sence sonra ne olacak?" sorusuna mantıklı yanıtlar veriyor. Bu, olaylar arasındaki örtük bağlantıları (çıkarım) anlamaya başladığını gösterir. "Sen olsaydın ne yapardın?" diye sorarak hayal gücünü destekleyin.') WHERE id = '8651dfdb-b093-4f7c-b25e-9846200e12c4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Kâğıt kesme: Şekil çıkarma". Çocuğunuz artık güvenli bir makasla basit bir daireyi veya kareyi kenarlarından kesip çıkarmaya çalışıyor. Bu, elindeki küçük kasların ileri düzeyde kontrol edilmesini gerektirir.') WHERE id = '9727b126-febe-431d-a82a-db6a6416efff';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Adalet ve Kural bekçisi". Çocuğunuz artık yalnızca kendisi değil, başkaları da kuralları ihlal ettiğinde tepki veriyor: "Baba, sırayı bozdun!". Bu, içsel vicdanın ve sosyal adalet duygusunun geliştiğini gösterir. Kuralların neden herkes için eşit olduğunu ona açıklayın.') WHERE id = 'a0bdfa22-2c16-417c-bc41-62353716c069';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Diplomatik çözümler". Çocuğunuz artık anlaşmazlık sırasında "Hadi sırayla oynayalım" gibi öneriler sunabiliyor. Bu, sosyal zekânın en belirgin göstergelerinden biridir. Bu barışçıl yaklaşımını mutlaka "Çok güzel bir çözüm buldun" diyerek takdir edin.') WHERE id = '1c1d5af4-d669-4eee-8938-97dcf06fd2d8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Miktarın korunumu deneyleri". Onunla kum veya suyla oynayın. Aynı miktarda suyu farklı kaplara dökün. Hâlâ uzun kapta daha fazla su olduğunu düşünebilir. Bu deneyler, beynini fiziksel gerçekliği kavramaya hazırlar.') WHERE id = '32e16fdb-1a45-43a1-8bb5-fea77db311d2';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topu omuz üzerinden atma". Çocuğunuz artık topu hedefe doğru daha güçlü ve isabetli atabilir. Bu, kol ve omuz kaslarının koordineli çalışmasının bir sonucudur. Onunla parkta küçük "potaya top atma" oyunları oynayın. Bu hem eğlencelidir hem de beden kontrolünü güçlendirir.') WHERE id = '5eff2db7-b37a-4ebb-9335-292fea3a6331';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Dil gelişiminde "Soyut kavramlar: Sağ ve Sol". Çocuğunuz "sağ el" ve "sol ayak" kavramlarını öğrenmeye ilgi gösterir. Şimdilik bunları karıştırabilir, bu normaldir. Çoraplarını giydirirken "Şimdi sağ ayağını uzat" diyerek bu kavramları günlük yaşama dahil edin.') WHERE id = 'dcd74d19-3308-4446-89b6-05aecfc53aed';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal Dayanıklılık: "Öz Düzenleme (Self-regulation)". Çocuğunuz artık bir şeyi başaramadığında hemen öfkelenmek yerine size bakıp "Yeniden deneyeyim mi?" diyebilir. Bu, duygusal olgunluğun en önemli basamaklarından biridir. Sonucu değil, gösterdiği sabrı ve çabayı övün. Siz harika bir annesiniz!') WHERE id = 'b36ad394-fd9c-40bc-963f-954848c1c743';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık "önce, şimdi, sonra" sıralamasını karmaşık etkinliklere uygulayabilir. "Önce oyuncağı toplayacağım, sonra ellerimi yıkayıp yemek yiyeceğim". Bu, beyindeki stratejik planlama (yürütücü işlev) becerisinin gelişimidir. Günün planını oluştururken ona aktif bir rol verin; bu, iç disiplinini güçlendirir.') WHERE id = 'a41e3209-8dbf-44ce-98bb-5a5b64b4268c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Statik ve Dinamik Denge". Çocuğunuz artık tek ayağının üzerinde 5-10 saniye durabilir veya dar bir kaldırım kenarında dengesini kaybetmeden yürüyebilir. Bu, vestibüler sistemin tamamen olgunlaştığını gösterir. Onunla "Cambaz" oyunu oynamanın tam zamanı.') WHERE id = '696cb686-c625-440d-93fe-4e04eee0ca77';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Dil gelişiminde "Neden-Sonuç Zinciri". Artık koyduğunuz yasaklar için mantıklı bir açıklama arar: "Neden şimdi tatlı yiyemem?". Yanıt verirken "Çünkü ben öyle söylüyorum" demek yerine, "Çünkü şimdi tatlı yersen karnın doyar ve sağlıklı öğle yemeğini yiyemezsin" gibi açıklamalar yapın. Bu, onun mantıksal düşünme becerisini geliştirir.') WHERE id = '1bdc4f44-d5e0-42ee-9d67-dc1beca39c22';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor gelişiminde "İnsan çizimindeki ayrıntılar". Çocuğunuz artık insan çizerken parmaklar, kirpikler, düğmeler veya şapka gibi küçük ayrıntılar ekler. Bu resimler, çevresindeki dünyayı ne kadar dikkatle gözlemlediğinin ve el-göz koordinasyonunun bir sonucudur.') WHERE id = 'dd86234a-f54a-432f-bcb2-f0fc25c1a9f2';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Hayali Korkular ve Cesaret". Bu yaşta hayal gücü o kadar kuvvetlidir ki karanlıkta "canavarlar" görebilir. Korkusunu inkâr etmeyin; birlikte "korku kovucu" ritüeller (örneğin sihirli bir yastık veya fener) oluşturun. Bu, onun duygusal güvenlik hissini güçlendirir.') WHERE id = '30d373fa-79f5-41e2-b2ee-ce7f265298c1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Liderlik ve İş Birliği". Çocuk artık oyunun senaryosunu kurar ve arkadaşlarına roller dağıtır: "Sen kedi ol, ben de senin sahibin olayım". Bu, onun sosyal hiyerarşiyi ve rolleri kavradığını gösterir. Bazen onun senaryosuna uyarak bu yaratıcı liderlik girişimini destekleyin.') WHERE id = 'ec5ff997-3ed4-4645-be9c-2d361314cc2f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Miktar ve Sayı Sembolü". Çocuk artık "4" rakamının 4 elmayı, "1" rakamının ise tek bir nesneyi ifade ettiğini tamamen kavrar. Ona "Bana 5 kalem ver" gibi görevler vererek soyut sayılarla gerçek miktarlar arasındaki bağı güçlendirin.') WHERE id = 'c8eb9b80-1c81-4e02-86f3-e8fdf448ffb9';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topu İki Elle Yakalama". Çocuk artık kendisine doğru yavaşça atılan topu kollarını büküp ellerini göğsünde birleştirerek (bazen de doğrudan elleriyle) yakalamaya başlar. Bu, tepki hızının ve görsel takip becerisinin geliştiğini gösterir. Onunla yakın mesafeden yumuşak bir topla alıştırma yapın.') WHERE id = 'e3704303-d02a-47ea-9a47-f1164a3046e0';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Zaman Ritüelleri". Çocuk "dün", "bugün" ve "yarın" kavramlarını artık daha doğru kullanır. "Yarın anneanneme gideceğim" dediğinde zaman çizgisini zihninde canlandırır. Günün sonunda yarının planlarını onunla bir "masal" gibi konuşarak uykuya dalın. Bu, onun gelecek zaman kavramını da şekillendirir.') WHERE id = '58a4bd7b-b429-45cf-92c2-f503f4e7d474';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '1350 günlük büyük gelişim! Çocuk artık resmen "bebeklik" kıyısından uzaklaştı ve "küçük çocukluk" okyanusunda özgürce yüzüyor. Onun bireyselliği, mizah anlayışı ve karakteri artık sizin için en büyük merak kaynağı. Siz bu 1350 gün boyunca onun dünyasının en güvenli limanı oldunuz. Aferin size, Anne!') WHERE id = '647eb338-5057-4cf4-a29d-e4970189abc1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuk artık "ben" ve "biz" arasındaki farkı sosyal oyunlarda uygular. "Gel birlikte ev yapalım; sen tuğlaları getir, ben dizeyim" gibi bir iş bölümü yapıyorsa bu, iş birliği zekâsının zirvesidir. Grup çalışmalarında liderlik veya yardımcı rollerini denemesine fırsat tanıyın. Bu, gelecekteki takım çalışması becerilerini şekillendirir.') WHERE id = '56b16411-749d-48ab-a1c9-aec6ee4d3f2b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Hızlı Koşma ve Keskin Dönüş". Çocuk artık koşarken dengesini kaybetmeden keskin dönüşler yapabilir. Bu, beden farkındalığının (propriyosepsiyon) ve kas kontrolünün ne kadar geliştiğini gösterir. Parkta oynayacağınız "Zikzak koşusu" oyunu onun için harika bir egzersizdir.') WHERE id = '3acf9991-6e18-469c-8243-5255e3b47e73';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Neden?" sorularının mantıksal zinciri. Artık sizin cevabınızla yetinmiyor, "Peki o neden böyle?" diyerek peş peşe sorular soruyor. Cevap verirken onu da düşünmeye teşvik edin: "Sence güneş nereye gidiyor?". Bu, onun hayal gücünü bilimsel merakla birleştirir. Küçük ansiklopedilerle merak dünyasını genişletin.') WHERE id = '09e33fb1-46b4-4ad6-a2f6-bb3ee2d41636';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Kâğıt katlama (Origaminin temelleri)". Çocuk artık kâğıdı tam ortadan katlamaya ve köşeleri birleştirmeye çalışıyor. Bu hareket hem el kaslarını güçlendirir hem de geometrik simetri kavramını zihnine yerleştirir. Ona renkli kâğıtlarla basit şekiller yapmayı öğretin.') WHERE id = 'b9689a6f-2bcb-421e-acea-f03b1095905f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Öz Yönetim ve Duyguları İfade Etme". Çocuk öfkelendiğinde yalnızca bağırmak yerine, "Şu anda çok öfkeliyim!" diyerek duygusunu sözlerle ifade edebilir. Duygularını kabul edin (onaylayın): "Seni anlıyorum, öfkelenmen normal". Bu, onun duygusal olgunluğunu artırır.') WHERE id = '7a0c1e64-9ecb-47f6-83f4-aa32390210cd';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Diplomatik Müzakereler". Çocuk bir şeyi elde etmek için "Eğer sen bana bu arabayı verirsen, ben de sana çikolata veririm" gibi bir "takas" (pazarlık) yapar. Bu, sosyal etkileme ve diplomasi becerisinin başlangıcıdır. Onunla adil "pazarlık" kurallarını oyun yoluyla deneyin.') WHERE id = '2dd70517-4599-4775-b1e7-2b11f39244da';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Miktarın korunumu (Hacim)". Onunla mutfakta bir deney yapın: Aynı miktarda suyu biri geniş, diğeri uzun ve dar olan iki kaba dökün. Hâlâ uzun kapta daha fazla su olduğunu söyleyebilir. Bu tür deneyler, görsel algısı ile mantıksal düşünmesi arasındaki çelişkiyi çözme becerisini geliştirir.') WHERE id = 'eb9fac33-252a-4cde-bb98-95be1aaf831f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topu ayakla kontrol etme". Çocuk artık topa yalnızca vurmakla kalmıyor, ayağıyla biraz öne iterek top sürmeye (dribbling) çalışıyor. Bu, dinamik denge ve dikkat gerektirir. Onunla parkta küçük bir "futbol parkuru" kurun ve topu hedefe doğru sürmesini isteyin.') WHERE id = 'f40621db-c962-42bd-85b1-429800b2b4ef';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Nezaket ve Sosyal Normlar". Çocuk artık "özür dilerim", "izin verir misiniz?" gibi ifadeleri yalnızca ezberden değil, duruma uygun biçimde kullanıyor. Sizin başkalarıyla kurduğunuz iletişim, onun için en önemli örnektir. Nazik davrandığında, bu davranışın çevresindekiler üzerinde yarattığı olumlu etkiyi mutlaka fark etmesini sağlayın.') WHERE id = '3804d992-5f37-4fb4-bfb6-18ad143039e9';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '1360 günlük büyük yolculuk! Çocuk artık 45 ayı geride bıraktı. O artık kendi düşünceleri, şakaları ve hayalleri olan başlı başına bir birey, küçük bir insan. Siz bu 1360 gün boyunca onun dünyasının mimarı oldunuz. Onun özgüvenli bakışlarında sizin sevginizin imzası var. Siz harika bir annesiniz!') WHERE id = '333176ec-4bc6-4177-b76d-921996ec28d4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Nezaket ve Görgü Kuralları". Çocuk artık "özür dilerim", "lütfen" sözlerini yalnızca ezberden değil, amacına uygun şekilde kullanıyor. Sizin başkalarıyla konuşurken kullandığınız üslup, onun en önemli rehberidir. Nazik davrandığında, bu davranışın çevresindekiler üzerinde yarattığı olumlu etkiyi fark etmesini sağlayın.') WHERE id = '81b527f9-bc6c-4fa6-a384-bfac0dbe1b99';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '1370 günlük muhteşem bir yolculuk! Çocuk artık bebeklik alışkanlıklarını tamamen geride bırakarak okul öncesi dönemin en aktif aşamasına geçiyor. Artık kendisini bir "ben" olarak tanıyor ve dünyayı değiştirmeye hazır. Siz bu 1370 gün boyunca onun en güvenilir rehberi oldunuz. Sevginiz ve sabrınız için kendinize teşekkür edin!') WHERE id = '7f1e62d7-6f8c-466a-917b-3acd9000a197';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuk artık çevresindeki yazılarda tanıdığı harfleri (özellikle adının ilk harfini) aramaya başlıyor. Bu, "görsel okuma" aşamasıdır. Ona harfleri zorla öğretmeye çalışmayın; yalnızca gördüğü sembollerin hangi sesi temsil ettiğini ilgi çekici bir keşif gibi sunun.') WHERE id = '395ee563-1ee4-4a29-8a28-f145933f9a6e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Dinamik Manevra". Çocuk artık koşarken önündeki engelin yanından kolayca geçebiliyor veya aniden yön değiştirebiliyor. Bu, beyindeki motor planlama becerisinin geliştiğini gösterir. Parkta onunla "Zikzak yarışı" oynayarak çevikliğini artırın.') WHERE id = 'cad61f20-8263-4b3a-bfc8-ed14fb447f18';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Tahmin ve Mantık". Ona masal okurken "Sence sonra ne olacak?" diye sorun. Çocuk artık olayların akışına uygun, mantıklı tahminlerde bulunabiliyor. Bu, hem hayal gücünü hem de neden-sonuç ilişkilerini anlama becerisini geliştirir.') WHERE id = '9337ce82-dd36-4b6f-a92e-336053ee8590';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Şekil Kopyalama: Kare". Daireden farklı olarak kare çizmek, kalemi köşelerde durdurup yönünü değiştirmeyi gerektirir. Bu, yazı yazmaya geçiş için önemli bir fiziksel hazırlıktır. Ona farklı geometrik şekilleri birleştirerek ev veya araba çizmeyi gösterin.') WHERE id = '90518b08-497d-4de6-998e-df3fea30a1f5';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Öz Denetim ve Sabır". Çocuk artık sırasını beklemenin veya isteğinin hemen yerine getirilmemesinin bir "son" olmadığını anlıyor. Sizin "5 dakika bekle" demenizi daha sakin karşılıyor. Bekledikten sonra ona mutlaka "Sabırlı olduğun için teşekkür ederim" diyerek bu olumlu davranışını pekiştirin.') WHERE id = '24183c71-3661-48ff-a107-410bfbd38523';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Kurallı Takım Oyunları". Çocuk artık diğer çocuklarla birlikte kuralları olan oyunlar (örneğin, "Saklambaç") oynamaya ilgi gösteriyor. Bu, sosyal uyumun önemli bir basamağıdır. Kurallara uyduğunda onu "Dürüst oynadığın için aferin" diyerek övün.') WHERE id = '04f3027e-9e30-43e8-bafb-f6c237c97831';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuk artık nesneleri yalnızca görünüşlerine göre değil, yapıldıkları malzemeye göre de ayırt eder: "Bu plastik, bu ise demir". Ona farklı dokulara sahip nesneler verin ve aralarındaki farkları sorun. Bu, çevresindeki dünyayı daha ayrıntılı analiz etmesine ve fiziksel dünyaya ilişkin bilgilerini düzenlemesine yardımcı olur.') WHERE id = '657efc38-ed5e-4e3a-9572-7dbdb9184154';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Statik Denge Zirvesi". Çocuk artık tek ayağının üzerinde hiçbir yere tutunmadan 5-10 saniye durabilir. Bu, hem iç kulaktaki denge merkezinin geliştiğini hem de bel ve bacak kaslarının güçlendiğini gösterir. Onunla "donduk" oyunu oynayarak bu becerisini eğlenceli hâle getirin.') WHERE id = '2f039b11-24db-4020-90d7-1c5f7a16c171';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Neden-Sonuç Zinciri". Çocuğunuz artık koyduğunuz yasaklar için mantıklı bir açıklama arar: "Neden şimdi tatlı yiyemem?". Yanıt verirken "Çünkü ben öyle söylüyorum" demek yerine, "Çünkü şimdi tatlı yersen karnın doyar ve sağlıklı öğle yemeğini yiyemezsin" gibi açıklamalar yapın. Bu, onun mantıksal düşünme becerisini geliştirir.') WHERE id = 'c914eb21-6b42-48f0-8ec0-5b93a47ae392';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "İnsan Çizimindeki Ayrıntılar". Çocuk artık insan çizerken parmaklar, kirpikler, düğmeler veya şapka gibi küçük ayrıntılar ekler. Bu resimler, çevresini ne kadar dikkatli gözlemlediğinin ve el-göz koordinasyonunun bir sonucudur.') WHERE id = 'fdd8b340-0697-4aeb-8d02-8988eb7da642';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Hayalî Korkuları Yönetme". Bu yaştaki çocuklar bazen karanlıktan veya "canavarlardan" korkabilir. Onun korkusunu yok saymayın; bunun yerine "canavarı kovan sihirli fener" gibi oyunlar oluşturun. Duygusal desteğiniz, bu korkuların geçici olduğunu öğrenmesine yardımcı olur.') WHERE id = 'd0348641-27c7-4875-b24e-5d2722f25676';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Sonuca Yönelik İş Birliği". Çocuk artık başka bir arkadaşıyla birlikte büyük bir kule yapmak için "taşları" paylaşabilir. Bu, artık yalnızca yan yana değil, ortak bir amaç için oynamaktır (cooperative play). "Harika bir takım oldunuz!" diyerek onun bu sosyal ve uzlaşmacı yönünü takdir edin.') WHERE id = 'bd3e5f00-1925-4d9d-bea8-7fc43abbb171';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Miktarın Korunumu Testi". Çocuk hâlâ yassılaştırılmış oyun hamurunun top hâlindeki oyun hamurundan daha büyük olduğunu düşünebilir. Onunla bu tür deneyler yapın: Oyun hamurunu yayın, ardından yeniden top hâline getirin. Bu, fiziksel dünyanın değişmez kurallarını anlamasına yardımcı olur.') WHERE id = '34ed2954-3007-40b2-9228-8e5bbced6cd6';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topu Ayakla Kontrol Etme". Çocuk artık topa yalnızca vurmakla kalmaz, ayağıyla biraz ileri iterek (dribbling) hareket ettirmeye çalışır. Bu, dinamik denge ve ayak-göz koordinasyonu gerektirir. Parkta onun için küçük bir "futbol parkuru" oluşturun ve topu hedefe doğru sürmesini isteyin.') WHERE id = 'f67ac937-be10-4065-8ce0-71169b977a25';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Miktarı Tanıma (Subitizing)". Çocuk artık 4-5 nesnenin kaç tane olduğunu saymadan, yalnızca bakarak anlayabilir. Ona farklı sayıda noktalar bulunan kartlar gösterin ve "Burada kaç tane var?" diye sorun. Bu beceri, gelecekte hızlı matematiksel işlemler yapabilmenin temelini oluşturur.') WHERE id = '494bf11b-00d7-4571-8a96-04e2a73dc57c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyonda "Tek ayak üzerinde zıplama". Çocuk artık tek ayağı üzerinde art arda birkaç kez zıplamayı deniyor. Bu hareket hem güç hem de ileri düzey denge gerektirir. Onunla evde "Ayak izlerinde zıplama" oyunu oynayarak bacak kaslarını ve dengesini güçlendirin.') WHERE id = 'e519a6cc-28f9-4dbb-80e3-d4aaf6533df1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Dil gelişiminde "Zamanı görselleştirme". Çocuk artık günün bölümlerini ve olayların sırasını iyi biliyor. "Sabah uyandığımızda güneş doğar, akşam ise ay çıkar". Onunla ertesi günün planlarını "önce, sonra, en son" şeklinde konuşmanız, kendini güvende hissetmesine de yardımcı olur.') WHERE id = '22058766-30d2-4299-8138-dbe3e33f7a99';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal dayanıklılıkta "Uzlaşma ve çözüm yolları". Çocuk artık anlaşmazlık yaşadığında yalnızca ağlamak yerine "Hadi oyuncağı paylaşalım" veya "Sen bana bunu ver, ben de sana bunu vereyim" gibi öneriler sunuyor. Bu, sosyal zekânın en üst düzey göstergelerinden biridir. Onun bu barışçıl yaklaşımını her zaman destekleyin. Harika bir birey yetiştiriyorsunuz!') WHERE id = '29c7e41f-162a-440d-ad79-c662956e2e8e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuk artık nesneleri aynı anda hem renklerine hem de boyutlarına göre gruplandırabilir: "Bütün küçük ve yeşil küpleri buraya toplayalım". Bu, bilişsel esnekliğin önemli bir göstergesidir. Ona farklı ölçütler içeren "Ara-bul" oyunları sunarak dikkatini geliştirin.') WHERE id = '428720ac-8db6-44a9-825f-ab25eee4d54f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel gelişimde "İsabetli Atış". Çocuk artık topu veya küçük bir torbayı belirli bir hedefe (örneğin sepete) daha isabetli atabilir. Bu, uzamsal mesafe tahmini (spatial estimation) yapma ve uyguladığı gücü ayarlama becerisinin geliştiğini gösterir. Onunla evde "Hedefi vur" yarışması düzenleyin; bu oyun el-göz koordinasyonunu da güçlendirir.') WHERE id = '5a34a884-0d1a-4ecc-8aaf-0538071d5d58';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Dil gelişiminde "Neden"den "Nasıl"a geçiş. Çocuk artık olayların yalnızca nedenini değil, nasıl gerçekleştiğini de soruyor: "Araba nasıl gidiyor?", "Yağmur nasıl yağıyor?". Yanıt verirken basit fizik kurallarını (örneğin, "tekerlekler dönüyor") açıklayarak onun bilime olan merakını destekleyin.') WHERE id = '43f973d1-c670-48fb-b082-c963d974b2cb';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor gelişiminde "Kompozisyon oluşturma". Çocuk resim yaparken artık birbiriyle ilişkili birkaç nesneyi aynı kâğıt üzerinde bir araya getiriyor: "Bu bir ev, bu da yanındaki ağaç". Bu, görsel dünyayı bir bütün ve sistemli bir şekilde algılamaya başladığını gösterir.') WHERE id = '4fc62a39-6aec-4659-8e0d-de5a572b7f58';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Öz Düzenleme (Self-regulation)". Çocuk artık öfkelendiğinde "Öfkelendim!" diyerek fiziksel tepkinin (örneğin vurmanın) yerine sözcükleri kullanmaya çalışır. Bu, duygusal zekâ gelişimindeki en büyük sıçramalardan biridir. Duygularını ifade ettiğinde onu dinleyin ve "Duygularını sözcüklerle ifade ettiğin için seninle gurur duyuyorum" diyerek destekleyin.') WHERE id = '2e78bbc8-d3e0-46e9-b6f4-fd06f0ff0e92';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Rol Oyunlarında Diyalog". Çocuk artık oyunlarında uzun diyaloglar kurar: "Sen mağazaya geldin, benden ekmek istiyorsun...". Bu oyunlar aracılığıyla sosyal kuralları ve iletişim görgüsünü deneyimler. Onun senaryosuna uyarak bu yaratıcı sürece katılın.') WHERE id = 'c878d5a6-c839-4863-9ea6-c1e45caf4ee6';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Zıt Kavramları Sınıflandırma". Çocuk artık "sıcak-soğuk", "yüksek-alçak", "ağır-hafif" kavramlarını tamamen ayırt edebilir. Onunla "Zıddını bul" oyunu oynayın: Siz "büyük" deyin, o da "küçük" desin. Bu, hem sözcük dağarcığını hem de soyut ve karşılaştırmalı düşünme becerisini geliştirir.') WHERE id = '96a1b8b4-4a53-4821-8a70-36e9af7db4b1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Merdivende Hareket Becerisi". Çocuk artık merdivenleri güvenle inip çıkar ve bazen elinde oyuncak olsa bile dengesini koruyabilir. Bu, dinamik denge becerisinin ileri düzeyde olduğunu gösterir. Her zaman yakınında olun, ancak özgürce hareket edebilmesi için ona güven verin.') WHERE id = 'e31518b3-755f-43f6-a042-c5c881774776';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Hayal Gücü ve Hikâye". Çocuk size kendi uydurduğu kısa masalları anlatabilir. Bu masallarda gerçeklikle hayal iç içe geçer. Hikâyelerini "Gerçekten mi?" veya "Sonra ne oldu?" gibi merak uyandıran sorularla destekleyin. Bu, gelecekte akıcı ve etkileyici konuşmasına yardımcı olur.') WHERE id = '1285abea-7296-4d22-a83f-6877ea839c11';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal Dayanıklılık: "Kazanmak ve Kaybetmek". Çocuk artık oyunlarda kaybetmeyi (her zaman olmasa da) daha sakin karşılar. "Hadi bir daha oynayalım" diyerek yeniden denemesi, kararlılığının bir göstergesidir. Bu önemli yaşam becerisini her zaman "Önemli olan oynamaktır" diyerek vurgulayın.') WHERE id = 'ab47da7b-7dd4-423e-bf69-3500dd83cc2f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuk artık "eğer... o zaman..." mantığını karmaşık sosyal durumlara uygular: "Eğer ben ona oyuncağımı verirsem, o da bana verecek". Bu, karşılıklı ilişkilerin temelidir. Onunla "Sonuç ne olur?" oyunu oynayın (örneğin, "Çiçeği sulamazsak ne olur?"). Bu, ileriyi düşünme becerisini geliştirir.') WHERE id = 'd6bf3a90-b7f5-4d81-9101-4bd23f1bc25d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Kontrollü Atlama". Çocuk artık belirli bir yükseklikten (örneğin alçak bir basamaktan) dengesini kaybetmeden iki ayağının üzerine atlayabilir. Bu, diz ve ayak bileği eklemlerinin güçlendiğini gösterir. Ona dizlerini hafifçe bükerek "yumuşak iniş" yapmayı öğretin.') WHERE id = '2795a26f-4a85-42cd-9860-03afd8411f60';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Soyut Zaman Kavramları". Çocuğunuz artık "hafta sonu", "bayramda", "doğum gününde" gibi daha geniş zaman dilimlerini anlıyor. Onunla yaklaşan önemli bir olay (örneğin, bir gezi) hakkında konuşurken "3 gün sonra" gibi ifadeler kullanarak zaman algısını geliştirin.') WHERE id = '4dbdf376-fb0e-469f-bb2e-b3be32d8d1c8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Harfleri Kopyalama". Çocuğunuz artık bazı basit harfleri (örneğin, A, O, T) gördüğü şekilde kopyalamaya çalışıyor. Bu, sembollerin hem görsel hem de motor belleğe aktarılmasıdır. Ona kum tepsisi veya parmak boyasıyla harfleri "yazmayı" önerin.') WHERE id = '83f43947-4f06-425b-801a-dd053a64d6b1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Öz Yönetim: İsteği Erteleme". Çocuğunuz artık bir ödül için biraz daha beklemesi gerektiğini (örneğin, "yemekten sonra tatlı") kabul ediyor. Bu, irade gücünün ve öz denetimin gelişimidir. Gösterdiği bu sabrı mutlaka vurgulayın ve onu övün; bu beceri gelecekteki başarılı akademik yaşamın anahtarıdır.') WHERE id = '51891c5d-a6e3-40d4-8ba5-38112ce2f223';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Grup Dayanışması". Çocuğunuz artık bir arkadaşı ağladığında ona sadece bakmıyor, "Ne oldu?" diye soruyor veya size haber veriyor. Bu, empatinin aktif aşamasıdır. Onun bu duyarlı yönünü "Çok iyi kalpli bir arkadaşsın" diyerek destekleyin.') WHERE id = '9932ed27-e891-4fec-aac9-e64c5a418a49';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Toplamanın Temelleri". Çocuğunuz artık 2 oyuncağın yanına 1 tane daha koyduğunda toplamda 3 oyuncak olduğunu saymadan (veya hızlıca sayarak) anlayabiliyor. Günlük işler sırasında "Senin 2 elman vardı, ben de 1 tane verdim, şimdi kaç tane oldu?" gibi küçük matematik bilmeceleri hazırlayın.') WHERE id = '5f9e5aa3-02e0-4bd3-85bf-ad954730aed0';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Tek Ayak Üzerinde Zıplama (Hop-stop)". Çocuğunuz artık tek ayağı üzerinde art arda 2-3 kez zıplayabiliyor. Bu, hem iyi bir denge hem de güçlü bacak kasları gerektirir. Onunla evde "Ayak İzi" oyunu oynayarak koordinasyonunu daha da geliştirin.') WHERE id = '5d319604-f8fa-4e75-83e3-e78cf306cb47';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Betimleyici Hikâye". Çocuğunuz çizdiği bir resmi veya gördüğü bir olayı birbirini takip eden cümlelerle anlatıyor. "Burada bir köpek vardı, koştu, sonra ağaca çıktı...". Konuşmasındaki olay sıralamasına dikkat edin. Bu, beyninde olayların mantıksal düzenini nasıl kurduğunun bir göstergesidir.') WHERE id = '5e32473e-0836-4d23-8816-7e98014c394b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '1400 günlük büyük zafer! Çocuğunuz artık 46 ayını tamamladı. O artık kendisinin farkında olan, başkalarının duygularını paylaşan ve dünyayı mantıkla keşfeden küçük bir "bilim insanı". Siz bu 1400 gün boyunca çocuğunuz için en güvenli liman ve en iyi öğretmen oldunuz. Siz harika bir annesiniz!') WHERE id = 'af7c9867-8fc8-42cc-b62a-1044c801bdef';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Karmaşık Cümle Yapısı". Çocuk artık "eğer", "çünkü", "ancak" gibi bağlaçları kullanarak uzun ve mantıklı cümleler kuruyor. Sözünü kesmeden onu dinleyin ve "Yani, sen böyle düşünüyorsun..." diyerek düşüncesini genişletmesine yardımcı olun. Bu, kendini ifade etme becerisini ve kelime dağarcığını aktif biçimde kullanmasını geliştirir.') WHERE id = 'eaf98320-82a4-46ba-81fe-43fd023e6b82';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal Dayanıklılık: "Kendini Teselli Etme". Çocuk artık küçük bir düşme veya başarısızlık karşısında hemen ağlamayabilir; kendi kendine "Bir şey olmadı" deyip ayağa kalkabilir. Bu, duygusal dayanıklılığın önemli bir göstergesidir. Siz de onun bu cesaretini her zaman "Çok güçlüsün!" diyerek destekleyin.') WHERE id = 'c0cb0b02-4a51-4012-b51b-53868aad0bf0';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuk artık "saat" kavramına ilgi gösteriyor. "Saat kaç?" diye sorabilir. Ona zamanı dakikalarla değil, olaylarla açıklayın: "Yelkovan buraya geldiğinde gezmeye gideceğiz". Bu, zamanın ölçülebilen bir kavram olduğunu anlamasına yardımcı olur.') WHERE id = '3a58737c-1dc5-47f3-86ee-31c959892712';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Çapraz Koordinasyon". Çocuk artık olduğu yerde adım atarken sağ elini sol dizine (ve tersini) dokundurabiliyor. Bu hareket, beynin her iki yarım küresinin aynı anda çalışmasını gerektirir ve ileride okuma-yazma sürecini kolaylaştırır.') WHERE id = '86960e2f-7035-4c14-a9a6-baeb23c3ea3d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Geçmişi Ayrıntılarıyla Anlatma". Çocuk, birkaç gün önce yaşanan bir olayı sırasıyla anlatabiliyor. "Anneanneme gittiğimizde orada bir kedi görmüştük, ağaca çıkmıştı". Bu "epizodik hafızasını" güçlendirmek için günün sonunda ona "Bugün en ilginç ne oldu?" diye sorun.') WHERE id = '6caf0def-6055-4b83-9a80-442193cfb9e1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Kağıt Kesme: Karmaşık Şekiller". Çocuk artık makasla yalnızca düz bir çizgiyi değil, dalgalı çizgileri veya büyük bir daireyi de kesip çıkarmaya çalışıyor. Bu, el-göz koordinasyonunun oldukça ileri düzeyde geliştiğini gösterir.') WHERE id = '64c3b0ce-8c21-4147-b606-f32ae65475bf';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Sağ ve Sol Kavramı". Çocuk artık sağ ve sol elini (henüz tamamen doğru olmasa da) ayırt edebiliyor. Ona "Kaşığı sağ elinle tut" veya "Çorabını sol ayağına giy" diyerek mekânsal yönelimini güçlendirin. Bu beceri, ileride harflerin yönlerini karıştırmaması açısından önemlidir.') WHERE id = '51c70f08-e08e-4a17-97ca-6373b3c435eb';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Grup İçinde Liderlik". Çocuk artık oyun sırasında diğer çocuklara "Sen buraya geç, sen bunu yap" diyerek roller dağıtıyor. Bu, sosyal hiyerarşiyi ve organizasyon becerisini deneyimleme biçimidir. Liderlik girişimlerini gözlemleyin ve adil davranmasına yardımcı olun.') WHERE id = 'ed221959-c928-4692-880d-29170d62352e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '47. aya hoş geldiniz! Çocuğunuz artık "sorumluluk" kavramını daha iyi anlıyor. Ona evde küçük "görevler" verin (örneğin bitkileri sulamak veya sofraya peçete koymak). Bu, kendisini ailenin önemli ve faydalı bir üyesi olarak hissetmesine yardımcı olur. Gösterdiği çabayı mutlaka fark edin ve ona teşekkür edin.') WHERE id = '13b68bb4-0e80-4802-bd12-f626258d3f54';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Dönüşümlü adımlarla koşma". Çocuğunuz artık koşarken basamakları veya engelleri ritmik biçimde, her birine tek ayağıyla basarak aşabiliyor. Bu, hem alt vücut gücünün hem de görsel-motor planlama becerisinin ne kadar geliştiğini gösterir.') WHERE id = '8fba68a9-4860-41c9-9d6a-0aabd4a4dc7d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Ses Bilgisi ve Harfler". Çocuğunuz artık sözcüklerin hangi sesle başladığını ayırt edebiliyor: "Armut ''A'' ile başlar". Onunla "Ses avı" oyunu oynayın; odada belirli bir sesle başlayan eşyaları bulmasını isteyin. Bu, gelecekteki okuma ve yazma becerileri için en önemli temeldir.') WHERE id = '4c5fdac9-9874-4896-80d4-6960b6675b1b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerde "Doğru kalem tutuşu (Tripod)". Çocuğunuz artık kalemi baş, işaret ve orta parmaklarıyla ("üç noktalı" tutuş) daha güvenli biçimde tutabiliyor. Bu, daha ayrıntılı resimler çizmesine ve harfleri kopyalamasına olanak tanır. Ona farklı kalınlıklarda kalemler vererek parmak kaslarını çalıştırın.') WHERE id = '01cf8b7d-9668-4ab1-a360-d6968cb99749';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Öz Yönetim: Kuralların Mantığı". Çocuğunuz artık kurallara yalnızca siz söylediğiniz için değil, kuralların mantığını anladığı için uymaya çalışıyor. "Yolda yürürken elini tutuyorum, çünkü arabalar var". Kuralların güvenlik ve düzen açısından önemli olduğunu ona anlatmaya devam edin; bu, iç disiplinin temelidir.') WHERE id = 'd91c45ef-c67b-4312-9a1e-572e86ed0a0e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Adil Paylaşım". Çocuğunuz artık oyuncakları veya tatlıları arkadaşları arasında eşit biçimde paylaştırmaya ilgi gösteriyor: "Bir sana, bir bana". Bu, hem sosyal empatinin hem de temel matematiksel (bölme) kavramların birleşimidir.') WHERE id = '2a9fd489-5479-4444-9ad0-d9ca9e6d37c8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Nesneleri Sınıflandırma". Çocuğunuz artık nesneleri hem türlerine hem de kullanıldıkları yere göre gruplandırabiliyor: "Bunlar mutfak için, bunlar yatak odası için". Bu, beynindeki bilgi birikiminin ne kadar sistemli ve hiyerarşik biçimde yapılandığını gösterir.') WHERE id = 'b49a3e45-1e44-429c-b3ab-7432f30a4a37';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topu Yakalama ve Atma (Bütünleştirme)". Çocuğunuz artık topu yakaladıktan hemen sonra hedefe atabiliyor. Bu, ardışık hareketler arasında akıcı bir geçiş yapabildiğini gösterir. Parkta onunla "At-yakala" oyunu oynayarak tepki hızını ve çevikliğini geliştirin.') WHERE id = 'b2cee277-0949-412e-af09-df96b2fd9cfd';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Miktarın korunması: Sayı". Aynı sayıdaki taşları bir tarafta birbirine yakın, diğer tarafta ise aralıklı şekilde dizdiğinizde, artık her iki taraftaki taş sayısının aynı olduğunu anlamaya başlar. Bu, görsel yanılsamadan mantıksal çıkarıma geçiş aşamasıdır.') WHERE id = '55c3f5e4-d3a4-465e-b035-b83e41b450d4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Tek ayak üzerinde sıçrama". Çocuğunuz artık tek ayağı üzerinde birkaç kez ileri doğru sıçrayabilir. Bu, hem denge hem de ani bacak gücü gerektirir. Onunla evde "Seksek" oynamak için harika bir zamandır.') WHERE id = 'ddfca79d-8eb7-4cbd-84fd-61e54d7153db';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Sözcüklerin içindeki sesler". Çocuğunuz artık sözcüklerin sonundaki sesleri de ayırt edebilir (örneğin, "elma" sözcüğünün ''a'' ile bittiğini söyleyebilir). Bu, fonemik işitmenin en ileri aşamasıdır. Onunla "Son harfle sözcük bulma" (sözcük zinciri) oyunu oynayarak sözcük dağarcığını ve işitsel dikkatini geliştirin.') WHERE id = '3863c552-322d-4dc8-a917-02d61270f313';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal dayanıklılık: "Başarısızlık ve Strateji". Çocuğunuz bir işi başaramadığında hemen ağlamak yerine, "Başka türlü denesem?" diye düşünür. Bu, "gelişim odaklı düşünce yapısının" (growth mindset) temelidir. Onu sonuç için değil, yeni bir yol aradığı için mutlaka övün.') WHERE id = 'da0d4f8a-08c6-45ad-9022-933f9025eb01';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık nesneleri yalnızca görünüşlerine göre değil, malzemelerine göre de ayırt edebilir: "Bu plastik, bu ise demir". Ona farklı dokulara sahip nesneler verin ve aralarındaki farkları sorun. Bu, çevresindeki dünyayı daha ayrıntılı analiz etmesine ve fiziksel dünyaya ilişkin bilgilerini düzenlemesine yardımcı olur.') WHERE id = 'ec9b72ac-4600-4d72-8d5e-3a0bc232d29c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Hedefe Sıçrama". Çocuğunuz artık belirli bir hedefe doğru (örneğin, yerdeki bir dairenin içine) sıçrayabilir. Bu, hem denge hem de uzamsal mesafeyi hesaplama becerisini gösterir. Parkta "taştan taşa atlama" oyunu onun için harika bir egzersizdir.') WHERE id = 'f6611b06-b8bc-42ff-84b4-2e17ea2e10d6';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Zıt Kavramları Sınıflandırma". Çocuğunuz artık "sıcak-soğuk", "yüksek-alçak", "ağır-hafif" kavramlarını tamamen ayırt edebilir. Onunla "Zıddını bul" oyunu oynayın: Siz "büyük" deyin, o da "küçük" desin. Bu, hem sözcük dağarcığını hem de soyut karşılaştırmalı düşünme becerisini geliştirir.') WHERE id = '00735398-0d89-4428-a943-f4a27fc19021';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Şekil kopyalama: Üçgen ve Artı". Çocuğunuz artık düz çizgileri kesiştirerek artı (+) çizebilir ve üçgene benzeyen şekiller oluşturmaya çalışır. Bunlar, yazı yazma becerisinin ilk temelleridir. Ona renkli kalemler ve boş kâğıtlar vererek bu "geometrik keşiflerini" destekleyin.') WHERE id = '1b117df4-43a4-4780-a2e3-365c2acc3518';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Ses Analizi". Artık kelimelerin yalnızca başındaki değil, sonundaki sesleri de ayırt etmeye başlar: "Masa, ''A'' ile biter". Bu, fonemik işitmenin geliştiğini gösterir. Onunla "Son sesle başlayan yeni bir kelime bul" oyunu oynayarak dil farkındalığını geliştirin.') WHERE id = 'e258838d-b844-4e68-840e-2eb0ef520682';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Kağıt Kesme: Ayrıntılı Şekiller". Çocuk artık makasla karmaşık şekilleri (örneğin bir yıldız veya küçük bir hayvan siluetini) kenarlarından kesip çıkarmaya çalışır. Bu, el-göz koordinasyonunun ne kadar geliştiğini gösterir. Ona farklı renklerde kağıtlar verin.') WHERE id = '619d1623-d881-46f6-a718-4a537172efc7';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Öz Yönetim: Duygusal Diplomasi". Çocuk istediği olmadığında artık bağırmak yerine size gerekçesini açıklayabilir: "Ama ben bunu çok istiyordum, çünkü...". Diyalog kurma çabasını takdir edin. Duygularını anladığınızı gösterin (onaylayın), ancak kuralların neden değişmediğini de sabırla açıklayın.') WHERE id = 'd8f54a1a-d4b0-4c91-b361-1e6376bfa2db';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Kurallara Bağlılık". Çocuk artık masa oyunlarında (örneğin domino veya basit sayı oyunları) kuralları çiğnemeden oynamaya özellikle önem verir. Bu, sosyal uyumun önemli bir aşamasıdır. Kurallara uyduğunda "Çok dürüst ve sabırlı oynadın" diyerek onu teşvik edin.') WHERE id = '111e7db0-d36d-44a0-97d8-10b28cd566ca';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Miktarın Korunumu: Hacim Deneyi". Aynı miktardaki oyun hamurunun birini topak, diğerini ise uzun bir "yılan" şekline getirirseniz, miktarın aynı kaldığını artık anlamaya başlar. Bu, görsel yanılsamadan mantıksal çıkarıma geçiş aşamasıdır. Bu deneyleri birlikte yapın.') WHERE id = '0655a03a-60b9-48e1-b285-1d3c83082836';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Tek Ayak Üzerinde Sıçrama". Çocuk artık tek ayağı üzerinde birkaç kez ileri doğru sıçrayabilir. Bu, hem denge hem de ani bacak gücü gerektirir. Onunla evde "Seksek" oynamak için harika bir zamandır; bu oyun mekânsal yönelim becerisini de geliştirir.') WHERE id = 'c5a0358e-6841-4ba2-8c21-cb976413e324';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Hayal Gücü ve Mantık Sentezi". Çocuk size kendi uydurduğu ancak mantıksal bir akışa sahip masallar anlatabilir. "Bir gün bir robot varmış, pili bittiği için durmuş...". Hikâyelerini "Peki sonra ne oldu?" gibi sorularla destekleyin. Bu, ileride akıcı ve etkileyici konuşmasına yardımcı olur.') WHERE id = '5fe788e8-9a0a-4448-9455-65cf7a8679b1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duygusal Dayanıklılık: "Başarısızlık karşısında yeni strateji". Çocuk bir işi (örneğin puzzle yapmayı) başaramadığında hemen öfkelenmek yerine "Belki bunu böyle yerleştirebilirim?" diyerek yeni yollar arar. Bu, "gelişim odaklı düşünce yapısının" (growth mindset) temelidir. Sonucu değil, yeni bir yol bulmak için gösterdiği çabayı mutlaka övün.') WHERE id = '19cb7d19-f480-4e1f-805a-267dba1df2a8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Öz Yönetim: İsteği Erteleme". Çocuk artık bir ödül için biraz daha beklemesi gerektiğini (örneğin, "yemekten sonra tatlı") kabul ediyor. Bu, irade gücünün ve öz denetimin (hazzı erteleme) geliştiğini gösterir. Gösterdiği bu sabrı mutlaka takdir edin; bu beceri, gelecekte başarılı bir akademik yaşamın anahtarıdır.') WHERE id = '93c7b1b4-9941-4328-bd03-c48ffc7f605f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Grup Dayanışması". Çocuk artık bir arkadaşı ağladığında yalnızca ona bakmakla kalmıyor, "Ne oldu?" diye soruyor veya size haber veriyor. Bu, empatinin aktif aşamasıdır. Onun bu duyarlı yönünü "Çok iyi kalpli bir arkadaşsın" diyerek destekleyin.') WHERE id = 'e9a7f349-2186-4929-ba3f-64f7d951af57';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Toplamanın Temelleri". Çocuk artık 2 oyuncağın yanına 1 oyuncak daha koyduğunda, toplamda 3 oyuncak olduğunu saymadan (veya hızla sayarak) anlayabiliyor. Günlük işler sırasında "Senin 2 elman vardı, ben de 1 tane verdim; şimdi kaç elman oldu?" gibi küçük matematik bulmacaları hazırlayın.') WHERE id = '6d1eeaa2-0164-4cca-94b4-9c14e8d79d60';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Merdivende Manevra". Çocuk artık merdivenleri güvenle inip çıkıyor ve bazen elinde oyuncak olsa bile dengesini koruyabiliyor. Bu, dinamik dengenin ileri düzeyde geliştiğini gösterir. Her zaman yakınında olun, ancak özgürce hareket edebilmesi için ona güven verin.') WHERE id = '28cfd5f7-ecbc-4133-9e9d-cc5c82140054';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Hayal Gücü ve Hikâye". Çocuk size kendi uydurduğu küçük masalları anlatabilir. Bu masallarda gerçekler ve hayaller iç içe geçer. Hikâyelerini "Gerçekten mi?" veya "Sonra ne oldu?" gibi merak uyandıran sorularla destekleyin. Bu, gelecekte akıcı ve etkileyici konuşmasına yardımcı olur.') WHERE id = 'c414dc79-8944-48c3-a5d5-e50145e600bc';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '1430 Günlük Zafer! Çocuk artık 47 ayını tamamladı. O artık kendisinin farkında olan, başkalarının duygularını paylaşan ve dünyayı mantık yoluyla keşfeden küçük bir "bilim insanı". Siz bu 1430 gün boyunca çocuğunuz için en güvenli liman ve en iyi öğretmen oldunuz. Siz harika bir annesiniz!') WHERE id = '8f2e9299-bb7b-4d28-9fbc-c07c7ba2a262';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '48. aya (4 yaşa) geri sayım başladı! Çocuk artık "ben" ve "biz" arasındaki farkı sosyal oyunlarda tam olarak uyguluyor. "Haydi birlikte bir gemi yapalım; sen yelkeni tut, ben de dümeni" gibi bir iş bölümü yapıyorsa bu, iş birliği zekâsının zirvesidir. Onun bu takım ruhunu takdir edin; bu beceri, gelecekteki okul yaşamı için önemlidir.') WHERE id = 'b940be7d-ee82-4c09-8760-e2ce9294193f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Hassas Dönüşler". Çocuk artık tüm hızıyla koşarken aniden durabiliyor veya dengesini kaybetmeden keskin bir dönüş yapabiliyor. Bu, vestibüler sistem ile kas kontrolünün tam bir koordinasyon içinde çalıştığını gösterir. Parkta onun için küçük bir "engel parkuru" kurun.') WHERE id = 'ce453995-5119-4943-ace6-1439bc5d5820';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuk artık nesneleri yalnızca görünüşlerine göre değil, yapıldıkları malzemeye göre de ayırt ediyor: "Bu plastik, bu ise demir". Ona farklı dokulara sahip nesneler verin ve aralarındaki farkları sorun. Bu, çevresini daha ayrıntılı analiz etmesine ve fiziksel dünyaya ilişkin bilgilerini düzenlemesine yardımcı olur.') WHERE id = '0ec14802-bab2-45c4-8cbf-788bdfa85e13';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Hedefe İsabetli Atlama". Çocuk artık belirli bir hedefe doğru (örneğin, yerdeki dairenin içine) atlayabiliyor. Bu, hem denge hem de mekânsal mesafeyi hesaplama becerisini gösterir. Parkta "taştan taşa atlama" oyunu onun için harika bir egzersizdir.') WHERE id = '0ddedeb7-e832-48ca-923d-05838885cdc1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Dil gelişiminde "Zıt Kavramları Sınıflandırma". Çocuk artık "sıcak-soğuk", "yüksek-alçak", "ağır-hafif" kavramlarını tamamen ayırt edebiliyor. Onunla "Zıddını bul" oyunu oynayın: Siz "büyük" deyin, o da "küçük" desin. Bu, hem kelime dağarcığını hem de soyut ve karşılaştırmalı düşünme becerisini geliştirir.') WHERE id = '3810cfc8-49ab-40fa-b90d-2edf9dc84fae';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Şekil Kopyalama: Üçgen ve Artı". Çocuk artık düz çizgileri kesiştirerek artı (+) çizebiliyor ve üçgene benzeyen şekiller oluşturmaya çalışıyor. Bunlar, yazı yazma becerisinin ilk temelleridir. Ona renkli kalemler ve boş kâğıtlar vererek bu "geometrik keşiflerini" destekleyin.') WHERE id = 'dfeb7b05-cea8-4a6f-b41b-005f3d3c488e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Öz Denetim: İsteği Erteleme". Çocuk artık bir ödül için biraz daha beklemesi gerektiğini (örneğin, "yemekten sonra tatlı") kabul ediyor. Bu, irade gücünün ve öz denetimin (hazzı erteleme) geliştiğini gösterir. Gösterdiği sabrı mutlaka takdir edin; bu beceri, gelecekte başarılı bir akademik yaşamın anahtarlarından biridir.') WHERE id = '988ae101-5f2f-4a86-a365-28a27e843965';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Grup Dayanışması". Çocuk artık bir arkadaşı ağladığında yalnızca bakmakla kalmıyor, "Ne oldu?" diye soruyor veya size haber veriyor. Bu, empatinin etkin aşamasıdır. Onun bu ilgili ve şefkatli yönünü "Çok iyi kalpli bir arkadaşsın" diyerek destekleyin.') WHERE id = 'ed4539aa-f1cf-4dd1-97f9-a5cf3f6b499d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Toplamanın Temelleri". Çocuk artık 2 oyuncağın yanına 1 oyuncak daha koyulduğunda toplamda 3 oyuncak olduğunu saymadan (veya hızla sayarak) anlayabiliyor. Günlük işler sırasında "Senin 2 elman vardı, ben de 1 tane verdim; şimdi kaç elman oldu?" gibi küçük matematik soruları hazırlayın.') WHERE id = '321e201a-5cd6-485a-a700-1c1f11885a2b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyonda "Merdivende Hareket Becerisi". Çocuk artık merdivenleri güvenle inip çıkıyor ve bazen elinde oyuncak olsa bile dengesini koruyabiliyor. Bu, dinamik dengenin ileri düzeyde olduğunu gösterir. Her zaman yakınında olun, ancak özgürce hareket edebilmesi için ona güven verin.') WHERE id = '26b9ae52-0022-4e15-934b-ad179ba90589';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bilişsel gelişimde "Zaman Takvimi". Çocuğunuz artık "3 gün kaldı" veya "Hafta sonu gideceğiz" gibi ifadeleri anlıyor. Doğum günü yaklaşırken bir "geri sayım takvimi" hazırlayın. Geçen her günü işaretlemek, zamanın akışını onun için somutlaştırır.') WHERE id = 'e9a169de-bc44-43dd-b6f0-9adaff7e3796';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Topu Ayakla Hedefe Vurma". Çocuğunuz artık topa sadece tekme atmakla kalmıyor, onu belirli bir hedefe (örneğin iki taşın arasına) sokmaya çalışıyor. Bu, mesafeyi algılamayı ve bacak kaslarını kontrollü kullanmayı gerektirir.') WHERE id = '1c5a132d-9357-46a5-b5fe-17d6baae9cac';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Karmaşık Hikâye Oluşturma". Çocuğunuz artık uydurduğu masallarda "çünkü", "ancak", "bu nedenle" gibi bağlaçları kullanarak bir olay örgüsü oluşturuyor. Hikâyelerini dikkatle dinleyin ve "Sence kahraman daha sonra ne yaptı?" gibi sorularla onu yeni ayrıntılar eklemeye teşvik edin.') WHERE id = '24dad4d0-2c9d-4d1c-bb0a-41d9b402e0e7';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '4 yaşına yalnızca 20 gün kaldı! Çocuğunuz artık bebeklik alışkanlıklarını tamamen geride bırakarak kendine özgü karakteri olan küçük bir bireye dönüştü. Siz bu 1460 gün boyunca onun gelişim yolundaki en büyük ışık oldunuz. Onun başarıları sizin sevginizin bir sonucudur. Harikasınız!') WHERE id = 'd76fe554-fd7b-4db0-9296-a5ba3be690d0';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Hayal Gücü ve Hikâye". Çocuğunuz size kendi uydurduğu küçük masallar anlatabilir. Bu masallarda gerçekler ile hayaller iç içe geçer. Hikâyelerini "Gerçekten mi?" veya "Sonra ne oldu?" gibi merak uyandıran sorularla destekleyin. Bu, gelecekte akıcı ve etkileyici bir şekilde konuşmasına yardımcı olur.') WHERE id = 'e96b1dc7-ba0c-47d3-b15a-cb6918e2bc9b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '4 yaşına yalnızca 30 gün kaldı! Çocuğunuz artık okul öncesi dönemin en verimli zamanında. O artık kendi zevkleri, korkuları ve bitmek bilmeyen soruları olan, başlı başına bir birey; küçük bir insan. Siz bu yolda bilim ve sevgiyle ilerlediniz. "Anacan" her zaman yanınızdadır!') WHERE id = '34fd4a41-2c8b-49b5-b2b0-6911f5bb04ab';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çocuğunuz artık nesneleri yalnızca dış görünüşlerine göre değil, ait oldukları gruba göre de sınıflandırıyor. "Bunlar deniz hayvanları, bunlar ise orman hayvanları". Bu, zihnindeki bilgilerin artık bilimsel kategorilere ayrıldığını gösterir. Onunla "Kim nerede yaşıyor?" oyunu oynayın.') WHERE id = 'bacec645-5384-4fc1-94d1-94b2914a27a1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel hareketlilikte "Hızlı Koşma ve Koordineli Durma". Çocuğunuz artık tam hızla koşarken sizin "Dur!" komutunuzla düşmeden veya öne doğru sendelemeden hemen durabiliyor. Bu, hem kas kontrolünün hem de işitsel-motor tepkinin üst düzeye ulaştığını gösterir. Bu oyunu parkta düzenli olarak tekrarlayın.') WHERE id = 'ea737131-3977-4085-b4c4-94dd4ae125f1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Konuşmada "Nazikçe İkna Etme". Çocuğunuz artık istediğini elde etmek için "Lütfen, olur mu?" demekle kalmıyor, bir neden de sunuyor: "Çünkü onu çok seviyorum". Sizin nazik yanıtınız, onun sosyal iletişim dilini şekillendirir. Her nazik isteğini "Böyle güzel söylediğin için sana cevap vermek çok hoş" diyerek takdir edin.') WHERE id = '0bfff590-18d1-438c-bef2-c5dac59fc7e3';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İnce motor becerilerinde "Harfleri ve Rakamları Görsel Olarak Kopyalama". Çocuğunuz artık adındaki harfleri veya "1, 2, 3" gibi rakamları kâğıda çizmeye çalışıyor. Bu, hareket ile görsel belleğin birleşimidir. Ona farklı renklerde kalemler verin ve "yazılarını" evin görünür bir yerine asın.') WHERE id = '65fb665a-a079-4bde-be1e-8536275e5fd6';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Öz Yönetim: Duygusal Bağımsızlık". Çocuğunuz artık küçük bir sorun yaşadığında (örneğin, oyuncağı dağıldığında) hemen size koşmuyor, önce kendi başına düzeltmeye çalışıyor. Bu, "Ben yapabilirim" duygusunun güçlendiğini gösterir. Bu bağımsız girişimlerini gözlemleyin ve yalnızca ihtiyaç duyduğunda müdahale edin.') WHERE id = '5a2e55ce-3f97-41a9-965d-b857b33a020f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Sosyal davranışta "Kuralları Açıklama". Çocuğunuz artık kendisinden küçük çocuklara veya oyuncaklarına oyunun kurallarını açıklıyor: "Önce ben, sonra sen". Bu, iç disiplinin ve liderlik becerisinin bir göstergesidir. Onun bu "öğretmenlik" yönünü destekleyin.') WHERE id = '1e4b1da3-fa3d-4b83-9554-7fdd901b9dfb';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Fiziksel koordinasyon: "Üç tekerlekli bisikletle manevra". Çocuğunuz artık bisiklet sürerken önündeki engeli görüp gidonu çevirerek engelden kaçabilir. Bu, hem pedal çevirme (fiziksel) hem de yolu takip etme (görsel) becerilerinin birleşimidir. Parkta onun için güvenli bir "sürüş parkuru" hazırlayarak bu becerisini destekleyin.') WHERE id = 'cccc4e73-bd8f-49ce-ac37-8b06ba255913';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Hoş geldiniz, sevgili anne! Hayatınızın en yeni ve belki de en heyecan verici sayfası bugün açılıyor. Şu an sizin için en önemli tek şey dinlenmek ve bebeğinizle ilk fiziksel teması kurmak; ev işleri, telefon aramaları ve misafirler bekleyebilir. Bilmelisiniz ki ilk gün gelen o koyu, sarımsı süt (kolostrum) miktar olarak az olsa da içeriği mucizevidir ve bebeğiniz için ilk aşı görevi görür. Sütünüzün az olduğundan korkmayın; bebeğinizin midesi henüz bir kiraz büyüklüğündedir ve o damlalar ona fazlasıyla yeter. Kahraman gibi davranmaya çalışmayın; ağrı ve yorgunluk yaşamanız tamamen doğaldır. Sadece uzanın, bebeğinizi koklayın, sıcaklığını hissedin ve bu anın tadını çıkarın; çünkü bu bağın temeli şimdi atılıyor.') WHERE id = 'ced035b3-8303-4f5d-95fd-7e29e2539509';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bedeniniz 9 ay boyunca muhteşem bir iş çıkardı ve şimdi iç organlarınız yavaş yavaş yerine dönmeye başlıyor. Özellikle emzirme sırasında karnınızın alt kısmında kramplar hissedebilirsiniz; endişelenmeyin, bu, rahminizin kasılarak eski boyutuna dönmesinin olumlu bir işaretidir. Toplumdaki "sütüm az, bebek doymuyor, o yüzden ağlıyor" gibi yanlış inanışlara kapılmayın. Bebeğiniz yalnızca acıktığı için değil; kokunuzu duymak, kalp atışınızı dinlemek ve güvende olduğunu hissetmek için de sık sık meme isteyebilir. Ona bu güveni verin, kucağınıza alın ve sık sık emzirin; unutmayın, bebek emdikçe sütünüz artacaktır.') WHERE id = 'f5dc2c0a-cfb4-4205-ad61-5a643545c576';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bu günlerde göğüsleriniz dolmaya (sütün gelmesi) başlayabilir; bu da göğüste ağırlık ve sıcaklık hissi yaratabilir. Aynı zamanda vücudunuzdaki hormon seviyeleri hızla değiştiği için kendinizi sebepsiz yere hüzünlü, ağlamaklı veya sinirli hissedebilirsiniz; tıpta buna "Baby blues" denir. Bu duygular "kötü bir anne" ya da yetersiz olduğunuzu göstermez; sadece fizyolojik bir süreçtir ve geçicidir. Gözyaşlarınızı tutmayın; ağlamak istiyorsanız içinizi dökün ve bunu yakınlarınızla konuşmaktan çekinmeyin. Yalnız değilsiniz; bu geçiş dönemini binlerce anne sizin gibi yaşıyor. Derin bir nefes alın ve kendinizi zamanın akışına bırakın.') WHERE id = '04d25f7c-e375-4514-ac39-dc2728da56e3';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Enerjinizi toparlamak için beslenmenize özellikle dikkat etmelisiniz; ama "üşütürsün", "meyve yeme", "su içme" gibi eskimiş yasakları bir kenara bırakın. Renkli, vitamin dolu beslenmeniz ve bol sıvı almanız, sütün kalitesinden çok sizin fiziksel gücünüzü toplamanız ve ruhsal zindeliğiniz için önemlidir. Bebeğinizin göbek bağına gelince: onu alkolle dağlamaya ya da sarmaya gerek yoktur. Sadece kuru ve temiz kalmasına dikkat edin; bezini bağlarken göbek kısmını açık bırakın ki hava alsın. Hava teması, iyileşmeyi hızlandıran en iyi yöntemdir.') WHERE id = '5cdec801-b16c-449e-bf65-9a37a9e133f1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Gece ile gündüzün yer değiştirdiği, uykusuzluğun kendini gösterdiği günlere hoş geldiniz, güçlü anne! Çevreden "bebeği kucağa alıştırma" diyenler olabilir; ama bilin ki ilk aylarda bebeği "şımartmak" mümkün değildir. Onun size ihtiyacı var; kucağınızda taşımak ve ten tene temas, hem beyin gelişimi hem de sütünüzün artması için en etkili yoldur. Ev işleri kaçmıyor, bulaşıklar yıkanmasa da olur; ama sizin uykunuz ve dinlenmeniz her şeyden önemli. Bebeğiniz uyur uyumaz siz de gözlerinizi kapatıp dinlenmeye çalışın; 15 dakikalık bir uyku bile size enerji verecektir.') WHERE id = '726dd7ee-a857-41fc-aad0-622f7b5ddf29';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Her şeyi tek başınıza yapmak, "süper anne" imajı çizmek zorunda değilsiniz; yardım istemek zayıflık değil, aksine güçlü olmak demektir. Eşinizden, annenizden veya yakınlarınızdan somut konularda yardım isteyin; örneğin yemek getirmelerini ya da siz duş alırken bebeğe göz kulak olmalarını rica edin. Kendinize bakmak, temizlenmek ve bir fincan sıcak çay içmek bencillik değil; annelik görevlerinizi daha iyi yerine getirmeniz için bir gerekliliktir. Unutmayın: mutlu ve dinlenmiş anne, mutlu bebek demektir; bu yüzden yükünüzü paylaşmaktan çekinmeyin.') WHERE id = '1ddced84-3654-418b-9996-21c50802a72f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Tebrikler, bir haftadır annesiniz ve zorluklara rağmen bu günleri başarıyla geride bıraktınız! Aynaya baktığınızda belki karnınızın hâlâ tam toparlanmadığını, saçlarınızın dağınık olduğunu görebilirsiniz; ama siz bir mucize büyütüyorsunuz ve bu hâlinizle de çok güzelsiniz. Bugünden itibaren bebeğinizi uyanıkken, gözetiminiz altında kısa süreli (1-2 dakika) yüzüstü yatırmaya (tummy time) başlayabilirsiniz. Bu küçük egzersiz boyun ve sırt kaslarını güçlendirecek, gaz sancılarına iyi gelecek ve gelecekteki fiziksel gelişimi için zemin hazırlayacaktır.') WHERE id = '33d098f8-b80c-478c-bb61-a7d57cd72e57';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğinizin cildinde veya göz aklarında hafif bir sararma fark edebilirsiniz; bu fizyolojik sarılıktır ve çoğu durumda sık emzirmeyle vücuttan atılır. Ancak sarılık bacaklara doğru iniyorsa ve bebek çok halsizleştiyse mutlaka doktorunuza danışın. Aynı zamanda odanın havasını değiştirmekten korkmayın; "kırkı çıkmadan hava olmaz" düşüncesi sadece bir efsanedir, temiz oksijen hem sizin hem de bebeğinizin beyni için önemlidir. Pencereyi açın, odayı havalandırın ya da mümkünse bebeğinizi havaya uygun giydirip kısa süreliğine temiz havaya çıkarın (doktorunuz izin verdiyse).') WHERE id = '55de4073-ef7d-4cff-84f4-bf2b8f830118';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Büyüklerimiz "bacakları düz olsun" diye sıkı kundaklamayı sevebilir; ama modern tıp, kalça ekleminin sağlıklı gelişimi için bebeğin bacaklarının serbestçe hareket etmesi gerektiğini kanıtlamıştır. Bebek kendi el-kol hareketlerinden irkilip uyanıyorsa yalnızca kollarını hafifçe kundaklayabilirsiniz (yarım kundak); ama bacaklarının "kurbağa" pozisyonunda serbest kalmasını mutlaka sağlayın. Bebeği sıkıp hareketsiz bırakmak kan dolaşımını ve kas gelişimini olumsuz etkileyebilir. Onu serbest bırakın; elleri ve ayaklarıyla dünyayı keşfetsin.') WHERE id = '94a133da-1fcc-4ffe-a24b-b9755a414c0b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Artık 10 gündür tüm dikkatiniz ve düşünceleriniz bebeğinizde; ama bugün en az 15-20 dakikayı sadece kendinize ayırmaya çalışın. Ilık bir duş alın, sevdiğiniz müziği dinleyin, cildinize bakım yapın ya da sadece pencereden bakıp hayallere dalın. Toparlanma sürecinizi hızlandırmak için pelvik taban kaslarınızı yavaş yavaş hissetmeye çalışın (Kegel egzersizlerinin en hafif biçimi); ama ağır spor için henüz çok erken. Bedeninizi dinleyin, ona saygı gösterin ve unutmayın: siz çocuğunuzun en büyük dayanağısınız; sağlıklı ve ruhen güçlü olmanız ona verebileceğiniz en büyük hediyedir.') WHERE id = '4ba69869-3aaa-471c-bba8-3e9678c5f231';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğinizin göbek bağı kuruyup düşmüş ya da düşmek üzere olabilir; bu tamamen doğal bir süreçtir ve göbek yerinde az miktarda kan lekesi görmekten korkmayın. Göbek düştükten sonra o bölgeyi kuru ve temiz tutmaya devam etmek önemlidir; çünkü nemli ortam bakterilerin çoğalması için elverişlidir. Bazen anneler göbeğin "dışa çıkık" kalmasından endişelenir; ama karın kasları güçlendikçe göbek çoğu zaman yerine oturur. Bu yüzden göbeğe bozuk para bağlamak ya da sıkıca sarmak gibi eski usullerden kaçının. Göbek çevresinde kızarıklık, kötü koku veya iltihap fark ederseniz hemen doktorunuza haber verin; bunun dışında doğanın işini yapmasına izin verin.') WHERE id = '4412d0c9-03dd-43c8-bb46-87b4fecadda2';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bu günlerde bebeğinizin sanki hiç doymuyormuş gibi sürekli, bazen her saat başı emmek istediğini gözlemleyebilirsiniz; tıpta buna "büyüme atağı" (growth spurt) denir. Anneler bu durumu çoğu zaman "sütüm azaldı, bebek aç kaldı" diye yorumlayıp telaşa kapılır ve mamaya geçmekte acele eder; oysa bu, bebeğin artan ihtiyacını karşılamak için vücudunuza "daha çok süt üret" sinyali verme yöntemidir. Sabırlı olun; bu geçici bir durumdur ve genellikle bir-iki gün sürer. Bebeğinizin isteğine uyun ve onu sık sık göğsünüze bastırın. Bu dönemde bol su içmek ve dinlenmek size güç verecek; unutmayın, sütünüz bebeğin ihtiyacına göre doğal olarak artacaktır.') WHERE id = '8aab5133-1153-4e9f-bfa1-1ddc76290148';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Akşam saatlerinde bebeğinizin sebepsiz yere ağlaması, bacaklarını karnına çekmesi ve kızarması gaz sancılarının (kolik) başladığını gösterebilir; bu, sindirim sisteminin henüz tam olgunlaşmadığı anlamına gelir. Telaşlanmayın; bu ağrılar bebeğin sağlığında bir sorun olduğunu göstermez, ona sadece biraz yardım gerekir. Karnını saat yönünde yavaşça ovmak ya da "bisiklet" hareketleri yaptırmak rahatlamasına yardımcı olacaktır. Bebeği yüzüstü, kolunuzun üzerine yatırıp gezdirmek (kaplan tutuşu) da sancıları hafifletebilir. Sabırlı olun; bu "bitmeyen geceler" gibi görünebilir ama 3-4 ay sonra bu sancılar tamamen kaybolacak.') WHERE id = 'bcbaede0-1b13-4f10-af2e-89c520ee8eac';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Tebrikler, bebeğiniz tam 2 haftalık! Bu dönemde doktorlar bebeklere genellikle D vitamini damlası verir; çünkü anne sütü mükemmel olsa da içindeki D vitamini miktarı genellikle yeterli değildir ve güneş ışığı da her zaman yetmeyebilir. Kemiklerin doğru gelişimi ve raşitizmin önlenmesi için doktorunuzun belirlediği dozda vitamini vermeyi unutmayın. Ayrıca bu, ilk doktor kontrolü için iyi bir zamandır; bebeğin kilo alımını kontrol ettirmek ve gelişimiyle ilgili sorularınızı sormak için çocuk doktoruyla bir görüşme planlayabilirsiniz. Harika gidiyorsunuz; ilk zorlu aşamayı geride bıraktınız!') WHERE id = '6f0bc18f-ecc7-4ad9-915b-db7cdf9694f7';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bugün dikkatimizi biraz yeniden kendi bedeninize çevirelim: doğum sonrası akıntılar (loşia) renk değiştirerek daha açık, sarımsı ya da beyaza dönmeye başlamalıdır. Kanama aniden artarsa ya da kötü koku gelirse bu, bedeninizin "çok yoruluyorsunuz" veya "enfeksiyon var" mesajı olabilir; bu yüzden ağır eşya kaldırmaktan kesinlikle kaçının. Hijyeninize özel önem verin; sık duş almak hem fiziksel temizlik hem de moral için önemlidir. Unutmayın, tam iyileşmeniz birkaç hafta daha sürecek; bu yüzden kendinizi henüz tam zinde hissetmeseniz bile bedeninize zaman ve şefkat gösterin.') WHERE id = '924b5e58-de0f-4e99-ae9e-3a1b97775596';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Güvenli uyku kuralları bebeğinizin hayatı için hayati önem taşır: bebeği her zaman sırtüstü ve sert bir yatakta yatırmalısınız. Büyüklerin tavsiye ettiği yumuşak yastıklar, kalın yorganlar veya yataktaki oyuncaklar boğulma riski yaratabilir; bu yüzden beşiği olabildiğince sade ve boş tutun. "Başı düz olsun" diye kullanılan özel ortopedik yastıklara çoğu zaman gerek yoktur; çünkü bebek başını serbestçe hareket ettirebilmelidir. Oda sıcaklığını kontrol altında tutun (20-22 derece idealdir) ve bebeği aşırı kalın giydirmekten kaçının; aşırı ısınma da uyku için risklidir.') WHERE id = '00815f0c-e81b-4156-a3e1-eda10e9b02f3';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğinizi uyanıkken yüzüstü yatırmanın (tummy time) öneminden mutlaka haberdarsınız; ama bebeğiniz bundan hiç hoşlanmayabilir ve hemen ağlayabilir. Bu normaldir, ama pes etmeyin; günde birkaç kez, her seferinde yalnızca 1-2 dakikalık denemeler boyun, omuz ve kol kaslarını güçlendirmek için paha biçilmezdir. Bu, aynı zamanda başın arka kısmının düzleşmesini (plajiosefali) önlemenin en doğal yoludur. Eğlenceli hâle getirmek için karşısına bir ayna ya da siyah-beyaz kartlar koyabilir, hatta siz de onunla birlikte yere uzanıp göz teması kurabilirsiniz.') WHERE id = '442f3095-2fe9-4071-b81b-22bb923583fd';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Kırkı çıkmadan bebek dışarı çıkmaz" sözü sadece eskimiş bir efsanedir; hava koşulları uygunsa ve bebek sağlıklıysa temiz hava ikinize de ilaç gibi gelecektir. Evdeki kapalı hava, toz ve bakteriler dışarıdaki temiz havadan daha zararlı olabilir; sadece insanların yoğun olduğu alışveriş merkezlerinden ve kapalı mekânlardan uzak durun. Bebeği giydirirken kendi giydiğinizden yalnızca bir kat fazla giydirmek yeterlidir; onu "lahana gibi" sarmak terlemesine ve hastalanmasına yol açabilir. Kısa bir yürüyüş sizin moralinizi yükseltecek, bebeğin ise daha derin uyumasına yardımcı olacaktır.') WHERE id = '0f0e26dc-de3c-4b42-ba38-4351bd00e821';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğinizin tırnakları kâğıt gibi ince ama jilet gibi keskin olabilir ve istemsiz hareketlerle yüzünü çizerek kendine zarar verebilir. Tırnak kesmek çok stresli görünebilir; en kolay yolu, bebek derin uykudayken özel bebek makasıyla dikkatlice kesmektir. Bazı anneler eldiven kullanmayı tercih eder; ama bebek dünyayı elleriyle hissederek öğrenir ve ellerinin kapalı kalması gelişimini yavaşlatabilir, kendini sakinleştirme mekanizmasını bozabilir. Korkmayın; yanlışlıkla küçük bir kesik olsa bile temiz bir pamukla bastırmak yeterlidir, hızla iyileşir. Cesur olun!') WHERE id = '3eb8e784-2dc2-4db5-bcf8-7391a821ce01';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Doğum sonrası bu dönemde kendinizi bazen dünyadan soyutlanmış, yalnızca süt veren ve bez değiştiren bir "robot" gibi hissetmeniz mümkündür. Ama unutmayın: siz yalnızca bir anne değilsiniz; aynı zamanda bir dost, bir eş ve ilgi alanları olan bir bireysiniz. Bugün bebek uyurken bir arkadaşınızı arayın, sosyal medyada ilginç bir şeyler okuyun ya da sadece pencereden bakıp "buradayım ve her şey yolunda" deyin. Ruh sağlığınız en az fiziksel sağlığınız kadar önemlidir; kendinizi sıkışmış hissediyorsanız bu duyguları yakınlarınızla paylaşın; konuşmak yükünüzü hafifletecektir.') WHERE id = 'e0cd0853-270f-4ca4-a662-76294120406b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğinizin bu günlerde süte hiç doymuyormuş gibi davranması, sürekli meme istemesi ve uykusunun bozulması sizi korkutmasın; bu büyük olasılıkla "3. hafta büyüme atağı"dır (growth spurt). Bu dönemde bebeğin organizması hızla büyür ve daha fazla enerjiye ihtiyaç duyar; sizin bedeniniz de bu talebe uyum sağlamak için daha çok süt üretmeye çalışır. Annelerin bu aşamadaki en büyük hatası "sütüm kesildi" deyip mamaya geçmeleridir; oysa bu geçici bir krizdir ve tek çözüm, bebeği istediği kadar, saate bakmadan emzirmektir. Sabırlı olun; bu gerginlik genellikle 24-48 saat içinde geçer ve süt miktarınız yeniden dengelenir.') WHERE id = '2fdd98da-1e6c-412b-96b1-b850d42327b4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğinizin o pürüzsüz, ipek gibi yüzünde aniden küçük kırmızı döküntüler ya da sivilceler görebilirsiniz; hemen "ben ne yedim ki çocuk böyle oldu?" diye kendinizi suçlamaya başlamayın. Buna "yenidoğan aknesi" denir ve hamilelikte bebeğe aktardığınız hormonların onun vücudundan temizlenme sürecidir. Bu döküntüler alerji değildir; bu yüzden onları sıkmak, alkolle silmek veya çeşitli kremler sürmek kesinlikle yasaktır, bu yalnızca cildine zarar verir. Yüzünü her gün sadece ılık kaynatılmış suyla silmek yeterlidir; döküntüler birkaç hafta içinde kendiliğinden kaybolacaktır.') WHERE id = 'c3f99f3b-1467-413f-94c0-72c3e11f5099';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Akşam saatlerinde başlayıp saatlerce süren o meşhur ağlama krizleri (kolik) bu dönemde zirveye ulaşabilir; bebeği sakinleştirmek için "beyaz gürültü"yü (white noise) denemeyi unutmayın. Anne karnında bebek sürekli kan dolaşımının ve organların sesini duyuyordu; bu yüzden fön makinesi, elektrikli süpürge sesi veya telefondaki "beyaz gürültü" uygulamaları ona tanıdık gelir ve güven hissi verir. Bebeği sıkıca kucaklayıp ritmik şekilde sallayarak bu sesleri dinletmek sinir sistemini sakinleştirebilir. Unutmayın; bu ağlamalar sizin suçunuz değil, sadece bebeğin henüz tam gelişmemiş sindirim sisteminin verdiği bir tepkidir.') WHERE id = '401736ab-8891-41f0-a7a6-17ce6782e7e4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğinizin görme yeteneği artık gelişmeye başlıyor; ancak renkleri henüz tam seçemiyor ve dünyayı daha çok bulanık gölgeler hâlinde görüyor. Dikkatini çekmek ve beyin gelişimini desteklemek için siyah-beyaz kartlar veya yüksek kontrastlı oyuncaklar kullanabilirsiniz; bunları yüzünden yaklaşık 20-30 cm uzaklıkta tutmak gerekir. Bebeğin bakışlarını bu kartlara dikip dikkatle izlediğini göreceksiniz. Bu basit oyun hem göz kaslarını çalıştırır hem de beyin hücreleri (nöronlar) arasında yeni bağlantıların kurulmasını sağlar.') WHERE id = '6acb903b-f503-4e0a-bf5a-5cedae1d83e4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Toplumumuzda yaygın olan "domates yeme, bebeğin cildi döker", "mercimek yeme, bebek gaz olur" gibi yiyecek yasakları sizi yorduysa bilin ki modern tıp bu görüşleri doğrulamıyor. Yediğiniz yiyecekteki gaz doğrudan süte geçmez; süt kandan oluşur, midedeki gazdan değil. Belirli bir yiyeceği yedikten sonra bebekte gerçekten bir rahatsızlık gözlemlemiyorsanız (bu çok nadir görülür, inek sütü proteini alerjisinde olur), kendinizi gereksiz yere diyete sokmayın. Vitaminli, proteinli ve çeşitli beslenmeniz hem sütün kalitesi hem de ruh sağlığınız için aç kalmaktan kat kat daha faydalıdır.') WHERE id = '0f643a6c-2b94-498e-845b-b4547838a7e6';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeği sürekli kucakta taşımak belinizi ağrıtabilir; bu yüzden doğru seçilmiş bir sling veya ergonomik bebek taşıyıcısı (kanguru değil!) en iyi yardımcınız olabilir. "Çocuk alışır", "omurgası eğrilir" gibi sözlere aldırmayın; aksine, bebeğin bacaklarının "M" harfi biçiminde (kurbağa gibi) durduğu ergonomik taşıyıcılar kalça ekleminin gelişimi için çok faydalıdır. Bu yöntem bebeğe anne karnındaki sarmalanmayı hatırlatır ve onu sakinleştirir; sizin ise iki eliniz boş kalır, ev işlerinizi yapabilir ya da rahatça bir çay içebilirsiniz. Yakınlık hissi ikinize de serotonin (mutluluk hormonu) armağan edecek.') WHERE id = 'a2fbf383-d8f0-4347-a3ef-d35f626ab799';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Eve gelen misafirlerin bebeği öpmek istemesi, elden ele dolaştırması sizi rahatsız ediyorsa "hayır" demekten ve sınır koymaktan kesinlikle çekinmeyin. Bebeğin bağışıklığı henüz çok zayıftır ve büyükler için sıradan olan bir uçuk virüsü (herpes) bebek için hayati tehlike oluşturabilir. Misafirlerden kibarca ellerini yıkamalarını, hastaysalar gelmemelerini ve bebeğin yüzünden/ellerinden öpmemelerini rica etmek en doğal hakkınızdır. Birisi buna alınıyorsa bu onun sorunudur; sizin asıl göreviniz bebeği korumaktır, başkalarını kırmamak değil.') WHERE id = '7b5d5e0e-5e56-4eb3-b899-1d95dce7cd83';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Tebrikler, muhteşem anne! Bugün bebeğiniz tam 1 aylık oldu! Bu bir ay boyunca ne kadar zorluk çektiğinizi, uykusuz kaldığınızı ama ne kadar güçlü durduğunuzu hatırlayıp kendinizle gurur duyun. Bu, aynı zamanda bebeğin aylık doktor kontrolü (kilo ve boy ölçümü) zamanıdır; aldığı her gram sizin emeğinizin meyvesidir. Bugün bebeğinizin bir aylık hatıra fotoğrafını çekin, tarihleri not edin ve bu küçük yıl dönümünü, sadece bir dilim pastayla bile olsa, mutlaka kutlayın. Zaman çok hızlı akıyor; bu anları kayda geçirmek gelecekte en güzel hatıra olacak.') WHERE id = '520fba19-0b3a-4361-9ce1-dac3a718ebb0';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeği yıkarken kulağına su kaçmasından korkuyorsanız endişelenmeyin; kulak zarı iç kulağı sudan korur ve su kaçması genellikle ciddi bir sorun yaratmaz (zarda hasar yoksa). Banyo bebek için sadece temizlik değil, aynı zamanda eğlence ve rahatlama aracıdır; suyu seviyorsa onu her akşam aynı saatte, uyumadan önce yıkamak harika bir uyku ritüeli olabilir. Sıcak su kasları gevşetir, sakinleştirici etki yapar ve bebeğe "artık gece oldu, uyku vakti" sinyalini verir. Banyodan sonra onu sıcak bir havluya sarıp hafif bir masaj yapmak uykuya geçişi kolaylaştıracaktır.') WHERE id = 'd1cd229a-65ce-4753-a5dc-ce53e13d2100';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Doğumdan sonraki ilk ayın ardından "Baby blues" denen o hüzünlü, hassas dönem genellikle bitmiş olmalıdır; hâlâ kendinizi sürekli üzgün, umutsuz, yorgun ya da bebeğe karşı ilgisiz hissediyorsanız dikkatli olun. Bu, Doğum Sonrası Depresyon olabilir ve bu kesinlikle sizin suçunuz, şımarıklığınız ya da zayıflığınız değil; hormonal ve kimyasal bir dengesizliktir. "Anneyim, dayanmalıyım" deyip kendinizi suçlamayın; içinizdeki boşluk hissi geçmiyorsa mutlaka doktorunuzla veya bir psikologla konuşun. Ruh sağlığınız, bebeğin fiziksel sağlığı kadar, belki ondan da önemlidir.') WHERE id = '792d4a29-1f99-4846-89d2-54738a980f78';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'İkinci aya hoş geldiniz! Artık bebeğinizle birbirinizi daha iyi tanıyorsunuz ve hayatınızda belli bir "ritim" oluşmaya başlıyor. Dikkat edin, "düzen" demiyoruz, "ritim" diyoruz; çünkü bebek henüz saate göre yaşamaya hazır değil, ama uyku, beslenme ve uyanık kalma sıralaması şekilleniyor. Bu dönemde katı programlar kurmaya çalışmayın; sadece bebeğin uyku sinyallerini (esneme, gözlerini ovuşturma) izleyin ve onu aşırı yorulmadan uyutmaya çalışın. Her şey hâlâ kaos gibi görünüyorsa endişelenmeyin; bu kaosun içinde bile büyük bir düzen var ve siz harika idare ediyorsunuz.') WHERE id = '014f9c15-8f59-4b13-b689-2c5db7a165c4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeği yüzüstü yatırdığınızda (tummy time) artık başını birkaç saniyeliğine de olsa kaldırmaya çalıştığını görebilirsiniz; bu, boyun kaslarının güçlendiğinin ilk işaretidir. Bu egzersizleri daha ilginç hâle getirmek için karşısına renkli bir oyuncak koyun ya da sadece yüz yüze uzanıp onunla konuşun. Başını henüz kaldıramıyorsa telaşlanmayın; her çocuk farklı hızda gelişir. Sadece sabırla devam edin; bu küçük denemeler ileride emeklemesi ve yürümesi için temel taşlarıdır.') WHERE id = 'edef290e-ee82-45c6-adef-de36a35e9688';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Şimdiye kadar bebeğinizin uykusunda gülümsediğini görmüşsünüzdür; halk arasında buna "meleklerle oynuyor" denir (aslında bir reflekstir), ama artık "sosyal gülümseme" dönemi yaklaşıyor. Bebeğiniz size bakıp sesinize veya yüz ifadenize bilinçli olarak gülümseyebilir; bu sadece bir mimik değil, size "seni tanıyorum ve seviyorum" demesinin ilk yoludur. Onunla konuşurken gözlerinin içine bakın ve gülümseyin; o da size karşılık vermeye çalışacaktır. Bu karşılıklı etkileşim, duygusal zekâsının gelişimi için en güçlü uyarandır.') WHERE id = '33d46eab-d81b-465a-acf9-3431f678ba0a';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bazen odaya girip "ben buraya niye gelmiştim?" diye düşünüyor ya da en basit kelimeleri hatırlayamıyor musunuz? Buna şakayla "anne beyni" (Mom brain) denir ve bu tamamen gerçek, fizyolojik bir durumdur. Uykusuzluk ve hormonal değişimler beynin dikkat odağını değiştirir; beyin sanki tüm kaynaklarını bebeğe yönlendirir ve diğer "önemsiz" şeyleri siler. Kendinizi "aptallaşmış" gibi hissetmeyin; bu geçici bir sistir. Önemli işleri not defterine veya telefona yazarak bu dönemi daha rahat geçirebilirsiniz; beyniniz yakında eski keskinliğine dönecek.') WHERE id = 'd8c08c2a-72db-44c1-9834-75d63110369c';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğin görme yeteneği gelişiyor ve artık hareket eden nesneleri gözleriyle izlemeye (takip etme) başlayabilir. Parmağınızı veya renkli bir oyuncağı yüzünden 20-30 cm uzaklıkta tutup yavaşça sağa-sola hareket ettirin; bakışlarıyla sizi izlemeye çalışacaktır. Bu basit oyun göz kaslarını ve beyin-göz koordinasyonunu geliştirir. Hemen tepki vermezse yorgun olabilir; onu zorlamayın ve başka bir zaman yeniden deneyin.') WHERE id = '8bc192a0-eebe-4dd4-8ce3-ca56d11958b8';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğiniz henüz konuşamasa da mükemmel bir dinleyicidir; gün boyunca yaptığınız her şeyi ona anlatmak ("şimdi bezini değiştiriyoruz", "bak, bu pencere") gelecekteki konuşma gelişimi için belirleyicidir. Araştırmalar, ebeveynleri kendileriyle çok konuşan çocukların kelime dağarcığının ileride daha zengin olduğunu gösteriyor. Ona sorular sorun ve sanki cevap veriyormuş gibi biraz susup bekleyin (örneğin: "Sütünü içtin mi? Aferin!"). Bu "diyalog" ona iletişim kurallarını öğretir ve aranızdaki bağı güçlendirir.') WHERE id = '99451123-a037-4f29-a96e-5e981ce03fe5';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebek masajı hem gaz sancılarını azaltmak hem de onu sakinleştirmek için mucizevi bir yöntemdir. Ellerinize biraz doğal bebek yağı sürün, odanın sıcak olduğundan emin olun ve bebeğin ayaklarından başlayarak yukarıya doğru nazik hareketlerle masaj yapın. Dokunma sırasında salgılanan oksitosin hormonu hem sizi hem de bebeği sakinleştirecektir. Bu ritüeli her akşam banyodan sonra tekrarlamak, gece uykusuna daha rahat dalmasına yardımcı olabilir.') WHERE id = '030269db-0cd6-4191-b990-5149723f7ac1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Tüm dikkat bebekte olduğu için eşinizle ilişkiniz arka plana atılmış gibi görünebilir ve bu çok normaldir. Ancak "ebeveyn" olurken "çift" olduğunuzu unutmamaya çalışın; bebek uyurken birlikte çay içmek, sarılmak ya da sadece 10 dakika günün nasıl geçtiğini konuşmak aranızdaki soğukluğu eritebilir. Babanın da bebekle bağ kurmasına imkân tanıyın (örneğin gazını çıkarmak ya da yıkamak onun görevi olabilir). Bir takım olduğunuzu hissetmek, bu zorlu günlerde ikinize de güç verecektir.') WHERE id = '7b078d0d-8755-48b3-a240-4b2c014cdd7f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebek henüz emeklemese de istemsiz hareketlerle dönmeye (yuvarlanmaya) çalışabilir; bu da güvenlik konusunu gündeme getirir. Altın kural: Bebeği asla, bir saniyeliğine bile, yüksek bir yerde (koltuk, yatak, alt değiştirme masası) yalnız bırakmayın. "Daha kımıldamıyor" deyip rahatlamayın; ilk yuvarlanma genellikle en beklenmedik anda gerçekleşir. Onu yalnızca yere serilmiş bir halının veya özel oyun matının üzerinde yalnız bırakabilirsiniz (elbette gözetim altında). Güvenlik alışkanlıklarını şimdiden kazanmak gelecekteki kazaların önüne geçecektir.') WHERE id = '0720bc24-8ac8-43a4-b347-e7e20231713d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Ve işte halk arasında büyük önem verilen o gün geldi: "Bebeğin kırkı çıktı"! Tebrikler! Eski geleneklere göre bu gün özel bir yıkanma ritüeli ("kırk suyu") yapılır ve anne ile bebek artık rahatça topluma karışabilir. Tıbbi açıdan ise bu, 6 haftalık toparlanma döneminin (loşianın bitmesi, rahmin toparlanması) tamamlanması demektir. Bu günü bir bayram gibi kutlayın; süslenin, kendinize bakım yapın ve belki de bebeğinizle ilk uzun "resmî" yürüyüşe çıkın. "Kırk" sadece bir sayı değil; "yeni anne" statüsünden "deneyimli anne" statüsüne geçişinizin simgesidir. Başardınız!') WHERE id = '1ce90c4b-f9a4-402a-a99b-4457322248d1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Kırkın çıkması" toplumumuzda sanki bir bitiş çizgisi gibi algılanır; ama aslında bu, maratonun sadece başlangıcıdır. "Artık her şeyi yapabilmeliyim", "Evim tertemiz olmalı" gibi baskılara boyun eğmeyin. Toparlanma süreci hâlâ devam ediyor; özellikle emziriyorsanız hormonların (prolaktin) etkisiyle eklemlerinizde gevşeme ya da bel ağrıları hissedebilirsiniz. Bu "yeni özgürlük" döneminde kendinizi birdenbire yüklemeyin; eski temponuza yavaş yavaş, adım adım dönün.') WHERE id = '0928cbd6-fa37-455a-a682-9515f253a752';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğiniz artık renkleri daha iyi seçmeye başlıyor; kırmızı ve turuncu, dikkatini çeken ilk parlak renkler olabilir. Beşiğinin üzerine asılan o dönen oyuncakların (dönence/mobil) artık sadece müziği değil, hareketi de ilgisini çekiyor. Henüz almadıysanız, basit geometrik şekillerden oluşan ve yavaş hareket eden bir dönence, dikkatini toplama becerisini geliştirecektir. Ama dikkat: onu uyuturken bu oyuncakları kaldırın ki uykusu kaçmasın.') WHERE id = 'c21766cd-a78b-4676-9247-d0b2e0b3de2f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '6-8. haftalar (yani şu anki dönem) bebeklerin ağlamasının zirveye ulaştığı zaman olabilir. Bazen hiçbir sebep yokken, karnı tok, altı temiz olsa bile ağlayabilir. Bu, sinir sisteminin çevredeki seslere, ışıklara ve uyaranlara karşı aşırı yüklenmesidir. Kendinizi suçlamayın; bunun "kötü anne" olmakla ilgisi yok, bu gelişimin doğal bir parçasıdır. Sadece yanında olun, sarılın ve "bu da geçecek" deyin. Gerçekten de birkaç hafta içinde bu ağlamalar hızla azalacak.') WHERE id = 'c94543e8-f599-4ccd-918b-88ff573157bb';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğiniz artık "agu" demeye ya da gırtlak sesleri çıkarmaya başladı mı? Bu, konuşma gelişiminin ilk aşamasıdır! O ses çıkardığında siz de ona aynı sesle karşılık verin; sanki "sohbet ediyorsunuz". Araştırmalar, ebeveynin bebeğin seslerini taklit etmesinin ona "seni duyuyorum ve anlıyorum" mesajı verdiğini gösteriyor. Bu basit oyun özgüvenini artırır ve ileride daha erken konuşmasına zemin hazırlar.') WHERE id = '045f5830-2fde-4a82-b369-03b2e1dcea23';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Aynaya baktığınızda hamilelikten kalan fazla kiloları ya da sarkmış karnı görüp üzülebilirsiniz. Unutmayın, o karın 9 ay boyunca genişledi; tamamen toparlanması için de en az o kadar zaman gerekir. Sert diyetler (özellikle emziren anneler için) sütün azalmasına ve saç dökülmesine yol açabilir. Şimdi zayıflamayı değil, sağlıklı beslenmeyi düşünün. Bol su, sebze ve protein en iyi dostunuzdur. Bedeninizden nefret etmeyin; o size dünyanın en güzel hediyesini verdi.') WHERE id = '772a8327-4bbe-46b7-9c90-09e5deaa584b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Yüzüstü zamanı" (tummy time) daha eğlenceli hâle getirmek için "uçak" oyununu deneyin. Sırtüstü uzanın, dizlerinizi bükün ve bebeği (yüzüstü olacak şekilde) bacaklarınızın üzerine koyup yavaşça sallayın (elbette ellerinizle tutarak). Bu ona hem farklı bir bakış açısı kazandırır, hem sizinle göz teması kurmasını sağlar, hem de denge duyusunu (vestibüler sistem) geliştirir. Bebekler yerde yalnız kalmaktansa annelerinin bedeni üzerinde egzersiz yapmayı çok daha fazla severler.') WHERE id = 'f63c5890-33d1-4cec-a07d-853961a0ca97';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Gece uykusu henüz tam düzene girmese de gündüz uykuları (şekerleme) kısalmaya başlayabilir. Bebeğiniz gündüzleri yalnızca 20-30 dakika uyuyup uyanıyorsa bunu "uyudu, bitti" olarak kabul etmeyin. Bebekler bazen uyku döngüleri arasında (her 40-45 dakikada bir) uyanır; ama aslında henüz uykularını almamışlardır. Uyanır uyanmaz hemen ışığı açıp oynamaya başlamayın; yanına uzanın, "şşş" diyerek sakinleştirin ya da emzirerek uykusunu uzatmaya çalışın.') WHERE id = '2c5835b8-b6ba-41d1-b215-505864265cfb';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Yaklaşan 2 aylık aşılar hakkında doktorunuzla konuşmanın zamanı geldi. Azerbaycan''daki Ulusal Aşı Takvimi''ne göre bu dönemde boğmaca, difteri, tetanos, hepatit B vb. hastalıklara karşı (Hexaxim veya benzeri) aşılar ile Rotavirüs ve Pnömokok aşıları öngörülüyor. Çevredeki "aşı zararlıdır", "çocuk konuşamaz" gibi bilimsel dayanağı olmayan korkutucu söylentilere inanmayın. Aşı, bebeği gelecekteki ölümcül hastalıklardan koruyan en güçlü kalkandır. Sorularınızı "komşu teyzeye" değil, çocuk doktorunuza sorun.') WHERE id = '28360eb0-4c71-4798-a428-29239685c45f';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Doğum sonrası cinsel yaşam konusu çoğu zaman tabu sayılır; ama bu konuda bilgi sahibi olmalısınız. Doktorunuz izin verdikten sonra (genellikle 6 haftadan sonra) cinsel birliktelik mümkündür; ancak isteksizlik (libido düşüklüğü) ya da kuruluk hissetmeniz tamamen normaldir. Bu, emzirme hormonlarının ve yorgunluğun etkisidir. Eşinizle bu konuda açıkça konuşun, birbirinize zaman verin ve acele etmeyin. Yakınlık yalnızca cinsel birliktelik değildir; sadece sarılmak ve dokunmak da bu dönemde çok önemlidir.') WHERE id = 'a59bf56c-999f-4547-b139-eaa70223118e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Artık bebeğin ellerini keşfettiği dönem; ellerini ağzına götürebilir, parmaklarını emebilir. Bu "acıktı" demek değildir (açlık işareti de olabilse de); bu onun kendini sakinleştirme mekanizması ve dünyayı tanıma yoludur. Ellerini ağzından çekmeye ya da eldiven giydirmeye çalışmayın. Bırakın kendi bedenini keşfetsin. Sadece ellerinin temiz ve tırnaklarının kesilmiş olduğundan emin olun.') WHERE id = '15366f98-572a-4b0c-8fda-af7cf85e56b4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Artık 2 aylık aşıların zamanı geldi (henüz yaptırmadıysanız). Azerbaycan''da uygulanan aşı takvimine göre bu dönemde bebeğe genellikle 5''li veya 6''lı karma aşı (boğmaca, difteri, tetanos vb.) ve Pnömokok aşısı yapılır. Aşıdan sonra bebeğin ateşi biraz yükselebilir ya da huzursuz olabilir; bu korkutucu değildir, aksine bağışıklığın "devreye girdiğini" ve organizmanın korunmaya başladığını gösterir. Doktorunuzun önerisiyle evde mutlaka bebekler için parasetamol içeren fitil veya şurup bulundurun; ancak ateş 38 dereceyi geçmeden ilaç vermekte acele etmeyin.') WHERE id = '947283f7-9c09-4c76-a0bb-7ff92f24aad4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğin ağzından salya akmaya başladı ve ellerini kemiriyor mu? Büyükler hemen "diş çıkarıyor" diyebilir; ama 2 ay diş için genellikle erkendir (istisnalar olsa da). Bu dönemde tükürük bezleri aktif çalışmaya başlar; ancak bebek salyayı yutmayı henüz tam öğrenmediği için dışarı akıtır. Aynı zamanda bu enzimler sindirim sistemini (ileride) katı gıdaya hazırlar. Sadece önlüğünü sık sık değiştirin ki boynu nemli kalıp pişik olmasın.') WHERE id = '99be53c6-0b63-4846-ac0b-fd476ca9e54e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Duş alırken elinize tutam tutam saç geliyorsa korkmayın, kel kalmıyorsunuz! Buna "doğum sonrası saç dökülmesi" denir ve tamamen hormonal bir süreçtir. Hamilelikte artan östrojen hormonu saçlarınızın dökülmesini engellemişti; şimdi bu hormonlar azalıyor ve zamanında dökülmeyen saçların hepsi birden dökülüyor. Bu geçicidir ve yaklaşık 6-12 ay içinde eski hâline dönecektir. Pahalı şampuanlara para harcamak yerine beslenmenize ve demir seviyenize dikkat edin; zamanla her şey düzelecek.') WHERE id = 'f657e712-ddb7-463c-a1f6-51d68e963ec9';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğiniz artık gece ile gündüzü biraz ayırt etmeye başlıyor; bu yüzden bir "uyku ritüeli" oluşturmak için mükemmel bir zaman. Bu katı bir program değil, sadece bir sıralamadır: Ilık banyo -> Pijamaların giyilmesi -> Loş ışık -> Ninni veya beyaz gürültü -> Uyku. Her gün aynı sıralamayı tekrarlamak bebeğin beynine "artık uyku vakti" sinyali gönderir. Bu alışkanlık bugün sonuç vermese de birkaç hafta sonra kurtarıcınız olacak.') WHERE id = '2614d60b-6450-43ee-a569-f20e3ea56045';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğin görme dünyası daha da renkleniyor; artık sadece kırmızı ve turuncuyu değil, yeşil ve sarıyı da seçmeye başlıyor. Gelişimini desteklemek için onu evin farklı odalarında gezdirin, aynada kendi yansımasını gösterin (bebekler kendi yansımalarını çok sever; henüz kendileri olduğunu anlamasalar da). "Bakalım burada kim var?" diyerek onunla konuşun. Bu sosyal oyunlar beynindeki nöronları hızla geliştirir.') WHERE id = '34645ca6-b752-434e-a340-59af7488ff61';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bazen anneler emzirir ama kiloları düşmez, aksine artar. Bu, uykusuzluk ve stres nedeniyle yükselen kortizol hormonuyla ilgili olabilir; organizma kendini "tehlikede" hisseder ve yağ depolar. "Süt olsun" diye şekerli çaylar, helva ve hamur işleri yemek bir efsanedir; sütü artıran tek şey bol su ve bebeğin sık sık emmesidir. Şekeri azaltmak ve bol sebzeye geçmek hem enerjinizi artıracak hem de kilonuzun yavaş yavaş normale dönmesine yardımcı olacaktır.') WHERE id = '70fa5f2d-ef18-4d50-b156-41acde57d635';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Yüzüstü yatırdığınızda (tummy time) artık sadece başını değil, göğsünü de yerden kaldırmaya çalışıyor mu? Bu bir "mini jimnastik" hareketidir! Kolları ve sırt kasları güçleniyor. Henüz yapamıyorsa ona yardım edin: küçük bir havluyu rulo yapıp koltuk altlarına koyun, bu ona destek olacaktır. Sevdiği oyuncağı önüne koyun ki ona ulaşmaya çalışsın. Bu hareketler ileride emeklemek ve oturmak için önemlidir.') WHERE id = '8cfe7b98-ab62-49f4-b9ea-ef363b224769';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bu dönemde bebeklerde "besleyici olmayan emme" refleksi güçlüdür; yani aç değildir, sadece sakinleşmek için bir şey emmek ister. Parmaklarını emiyorsa ve siz emzik vermek istiyorsanız "ortodontik" biçimli olanları seçmeye çalışın. Emzik kötü bir alışkanlık değildir; ani bebek ölümü sendromunu (SIDS) önlemede yardımcı bir araç sayılır. Ancak emziği her ağladığında "susturucu" olarak kullanmayın; önce sorununun ne olduğunu anlamaya çalışın.') WHERE id = '4ec5ed37-79da-4c46-9571-b8e74147be8d';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğin başının bir tarafının düzleştiğini mi fark ediyorsunuz? Buna "pozisyonel plajiosefali" denir ve bebeğin sürekli aynı tarafa yatmasından kaynaklanır. Kafatası kemikleri henüz yumuşaktır ve bu kolayca düzelir. Basit çözüm: Onu beşiğe koyarken başının yönünü her gece değiştirin (bir gün sağa, bir gün sola). Uyanıkken ise mümkün olduğunca çok yüzüstü tutun ki başının arkasına baskı binmesin.') WHERE id = '248e6415-444f-4d09-8609-b540277d00d1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Tebrikler! Bugün bebeğiniz 2 aylık oldu! Artık "yenidoğan" (newborn) dönemini resmen geride bıraktınız; o artık "bebek" (infant) sayılıyor. İlk günlerdeki o küçük, çaresiz canlıyla şimdi size gülümseyen, sesler çıkaran çocuğu karşılaştırın. Zor günler yine olacak; diş çıkarma, uyku gerilemesi vb. gelecek, ama siz artık deneyimli bir annesiniz ve her zorluğun üstesinden geleceksiniz. Kendinize kocaman sarılın; muhteşem bir iş çıkarıyorsunuz!') WHERE id = 'd3b345c6-e91a-402d-9918-ceed5b8d37b4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Hoş geldin 3. ay! Bebek gelişiminde "Dördüncü Trimester" denilen o ilk 3 aylık uyum döneminin sonuna yaklaşıyorsunuz. Bebeğiniz artık sadece yiyip uyuyan bir canlı değil; çevresini algılayan, seslere tepki veren sosyal bir bireye dönüşüyor. Bu aydan itibaren uyanık kalma süresi artacak, uykuları ise (umarız!) biraz daha düzenli hâle gelecek. Bu yeni aşamada sizinle daha çok "sohbet etmek" isteyecek; bu yüzden bol bol konuşmaya ve şarkı söylemeye hazır olun.') WHERE id = '8828f855-f7c6-48a8-aae1-636ec24ccff1';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğiniz ellerini yüzünün önünde tutup hayretle onlara mı bakıyor? Bu, ilk "oyuncağını" keşfetmesidir! Buna "el-göz koordinasyonu" denir. Ellerinin kendisine ait olduğunu ve onları yönetebildiğini anlıyor. Bu sürece engel olmayın, ellerini saklamayın. Aksine, bileklerine renkli veya ses çıkaran (çıngıraklı) bileklikler takarak bu keşfi daha ilginç hâle getirebilirsiniz. Bu, beyin gelişimi için muhteşem bir egzersizdir.') WHERE id = 'c44f54e6-bd35-4121-9f0f-f6748ef02647';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Uyku konusu hâlâ sancılı olsa da iyi bir haber var: Bebeğin beyni artık "melatonin" (uyku hormonu) salgılamaya başlıyor ve sirkadiyen ritmi (biyolojik saati) şekilleniyor. Artık gece ile gündüzü karıştırma olasılığı azalıyor. Ona yardımcı olmak için sabahları odayı güneş ışığıyla doldurun; akşamları ise ışıkları erken kapatın ve sessizlik yaratın. Bu doğal ışık düzeni, beynine "şimdi uyanık kalma zamanı" ve "şimdi uyku zamanı" sinyallerini iletecektir.') WHERE id = 'f3bdc990-29cc-452b-b018-a1508cec7d80';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Boyun kasları artık epey güçlendi; yüzüstü yatarken başını 45-90 derece kaldırıp etrafa bakabiliyor. Hatta bazen "uçak" gibi kollarını ve bacaklarını havaya kaldırıp sallanabilir. Bu, sırt kaslarını gelecekteki emekleme ve oturma aşamalarına hazırlar. Başını henüz tam tutamıyorsa endişelenmeyin, her çocuğun kendi temposu vardır; sadece yüzüstü zamanını (tummy time) günlük rutinden eksik etmeyin.') WHERE id = '72ecbac3-10ef-45d2-898d-f50326e4aca5';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğin başında, özellikle bıngıldak bölgesinde sarımsı, yağlı kabuklar (konak) mı gördünüz? Halk arasında buna "konak", tıpta ise "seboreik dermatit" denir. Korkmayın; bu bir hijyen eksikliği değildir ve bulaşıcı değildir. Anneden geçen hormonların etkisiyle yağ bezlerinin fazla çalışmasından kaynaklanır. Koparmaya çalışmayın; banyodan önce zeytinyağı veya badem yağı sürüp yumuşatın, sonra yumuşak bir fırçayla tarayarak yıkayın. Zamanla kendiliğinden geçecektir.') WHERE id = 'ebf4f9a7-c423-4f9b-a35f-e6aea203cbf5';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Artık bebeğinizin gülüşleri refleks değil, tamamen bilinçli! Ona gülümsediğinizde, gıdıkladığınızda veya "cee-e" (saklambaç) oynadığınızda sesli gülmeye başlayabilir. Bu ses dünyanın en güzel müziği, öyle değil mi? Mizah duygusu şekilleniyor. Tuhaf sesler çıkarmanız, yüzünüzü komik şekillere sokmanız çok hoşuna gidecek. Gülmek aynı zamanda akciğerlerini geliştirir ve stres hormonlarını azaltır.') WHERE id = '1fddfb5f-0320-4827-b223-17100c2c0495';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Yastığı veya kıyafetleri sık sık ıslanıyor mu? 3. ayda salyanın artması çok normaldir. Bu, mutlaka diş çıkaracağı anlamına gelmez (diş etleri kaşınabilse de). Bu durum, sindirim sisteminin geliştiğini ve ağız içindeki bakterilere karşı doğal bir koruma oluşturduğunu gösterir. Sadece boynuna bir önlük (salya önlüğü) takın ve ağız çevresini kuru tutun ki döküntü oluşmasın.') WHERE id = '65b4b1d4-9f03-4890-8a26-60e163757dc4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, '"Su vermek gerekir mi?" sorusu bu aylarda anneleri çok düşündürür. Özellikle büyükanneler "yazık, susuz kaldı" diyebilir. Oysa Dünya Sağlık Örgütü (DSÖ) ilk 6 ay boyunca bebeğe anne sütü veya mama dışında HİÇBİR ŞEY (su bile) verilmemesini önerir. Anne sütünün %88''i sudur ve bebeğin su ihtiyacını tamamen karşılar. Midesi henüz çok küçüktür; onu suyla doldurmak süt alımını azaltabilir ve gelişimini yavaşlatabilir.') WHERE id = 'daa57941-307c-46d4-ad44-8c2b7828cf2e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Günlük hayatınıza bir "mola" düğmesi ekleyin. Bebek uyuduğunda hemen ev temizlemeye koşmayın. Sizin de "pilinizin" dolmaya ihtiyacı var. 20 dakikalık bir uyku, kitap okumak ya da sadece boş boş tavana bakmak sizin hakkınız. "Mükemmel ev hanımı" olmak zorunda değilsiniz; ama "sağlıklı anne" olmak zorundasınız. Tozlar bekleyebilir, ama ruh sağlığınız beklemez.') WHERE id = '8ae3c3ee-3ed1-4cce-8f50-41530ca784cb';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bu aydan itibaren "Beslenme - Aktivite - Uyku" döngüsü oluşturmaya başlayabilirsiniz. Yani: Bebek uyanır -> Süt içer -> Oynar -> Uyur. Anneler çoğu zaman bebeği emzirerek uyutur (bu yanlış değildir ama alışkanlık yaratabilir). "Yeyip-oynayıp-uyumak" sıralamasını uygularsanız, bebek beslenmeyi uykuyla ilişkilendirmeyi azaltır ve ileride kendi kendine uykuya dalması kolaylaşır. Elbette bu katı bir kural değil; sadece denemeye değer bir yöntemdir.') WHERE id = '2c9372ab-3791-4b09-9ac2-4545b2a50eba';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğin elleri artık "başına buyruk" değil; bilinçli olarak nesnelere uzanıyor ve onları tutmaya çalışıyor. Önceden parmağınızı avucuna koyduğunuzda refleks olarak sıkıyorduysa, şimdi oyuncağı görüp ona doğru elini uzatıyor. Bu gelişme harika; ama dikkatli olun: kucağınızdayken saçınızı, kolyenizi veya gözlüğünüzü çekmek isteyecek. Ayrıca sıcak çay fincanlarını ondan uzak tutun; çünkü ani bir hareketle üzerine dökebilir. Güvenlik mesafesini korumak artık önemli.') WHERE id = '851b7601-c8f0-43b8-a2e5-3708104c42ba';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Geceleri uykusuzluk hâlâ devam ediyorsa "rüya beslemesi" (Dream Feed) yöntemini deneyebilirsiniz. Bu, bebeği tam uyandırmadan, uykulu hâldeyken (örneğin siz yatmadan önce saat 23:00''te) emzirip yeniden yerine koymaktır. Bu yöntem bazen bebeğin gece yarısı uyanmasını önler ve size biraz daha uzun, kesintisiz bir uyku kazandırır. Bu yöntem işe yaramıyorsa ve bebek uyanıp ağlıyorsa zorlamayın; her çocuğun biyoritmi farklıdır.') WHERE id = '1a681284-0141-4b15-bc3b-3b5a269a1b94';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeği yüzüstü yatırdığınızda (tummy time) yana yuvarlanmaya çalıştığını görebilirsiniz. Bazı çevik bebekler bu dönemde yüzüstünden sırtüstüne (başlarının ağırlığıyla, kazara) dönebilir. Bu büyük bir sevinçtir ama aynı zamanda bir uyarı sinyalidir: Artık onu alt değiştirme masasında, koltukta veya yüksek bir yerde bir saniye bile gözetimsiz bırakmak olmaz. Düşme riski bu aydan itibaren hızla artıyor; en güvenli yer zemindir (halı veya oyun matı).') WHERE id = '51999bec-e90a-4151-af89-e280275c886e';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğin çıkardığı sesler artık sadece ağlamaktan ibaret değil; ünlü sesleri ("a", "o", "u") uzatabiliyor ya da "cıvıldıyor". Bu, ses tellerinin egzersizidir. Siz mutfakta çalışırken o odada ses çıkarıyorsa mutlaka sesle karşılık verin ("Evet, seni duyuyorum, geliyorum"). Bu "uzaktan iletişim" ona güven duygusu verir: "Annemi görmesem de sesi geliyor, demek ki yalnız değilim". Bu, ayrılık kaygısını (separation anxiety) azaltmaya yardımcı olur.') WHERE id = '4b396ede-815b-4edd-bee5-1ab95bd630c3';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğin kilosu arttıkça belinizde ve kollarınızda ağrılar (özellikle "anne bileği" sendromu) ortaya çıkabilir. Onu kucağınıza alırken veya emzirirken duruşunuza dikkat edin; omuzlarınızı kulaklarınıza doğru kaldırmayın, dik oturun ve mutlaka belinizi destekleyen yastıklar kullanın. Bebeği yerden kaldırırken belinizi değil, dizlerinizi bükerek kaldırın. Omurganız daha uzun yıllar size lazım olacak; onu şimdiden koruyun.') WHERE id = 'dc8afbc6-14c7-4301-94dd-c5e5a4b2292b';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Çevrenizden "çocuk 3 aylık oldu, artık yemeğin suyundan tattır", "biraz ekmek içi ver, alışsın" gibi baskılar duyabilirsiniz. Kararlı olun ve "HAYIR" deyin. Dünya Sağlık Örgütü (DSÖ) açıkça bildiriyor: İlk 6 ay YALNIZCA anne sütü (veya mama). Bebeğin mide-bağırsak sistemi nişastayı veya diğer gıdaları sindirmeye henüz hazır değildir; erken başlamak alerjiye, gaza ve ileride obeziteye yol açabilir. Acele etmeyin; yemek yemek için önünde koca bir ömür var.') WHERE id = '0739a3ba-203e-453e-b9ac-6bd4bfdbcdf4';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bu dönemin en ilginç oyuncağı aynadır! Güvenli (kırılmaz) bir aynayı bebeğin karşısına koyun. Oradaki "diğer bebeğe" gülümseyecek, ona dokunmaya çalışacak ve şaşıracaktır. Şimdilik onun kendisi olduğunu anlamıyor (bu yaklaşık 18. ayda olur); ama yüz ifadelerini ve hareketleri izlemek sosyal gelişimi için muhteşemdir. Bu oyun aynı zamanda yüzüstü kalma süresini uzatmak için harika bir hiledir.') WHERE id = 'd5f46289-84de-4aa8-8cc6-e208423016ca';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğin çevresine ilgisi arttıkça emzirmek zorlaşabilir. Her sese, her harekete başını çevirip bakmak istiyor ve memeyi bırakıyor. Buna "meraklı bebek sendromu" denir. Sinirlenmeyin; emzirmek için daha sakin, karanlık ve sıkıcı bir oda seçin. Boynunuzdaki parlak kolyeyi veya dikkat çeken eşyaları çıkarın. Geceleri ya da uykulu zamanlarında daha iyi emdiğini göreceksiniz; bu normaldir.') WHERE id = '9cc144a8-c429-4c7c-b711-108cf929ab92';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Bebeğin ellerini keşfetmesi bazen tırnaklarının yüzünü çizmesiyle sonuçlanır. Tırnak kesmekten korkuyorsanız bunu o uyurken yapın ya da tırnakların biraz yumuşaması için banyo sonrasına bırakın. Eldiven takmak artık önerilmiyor; çünkü bebek elleriyle dokunarak, ağzına götürerek dünyayı tanır. Küçük bir çizik çabuk iyileşir; ama ellerinin dokunma duyusunu engellemek gelişimini yavaşlatabilir.') WHERE id = '4516cd0b-d8f9-4d0b-92cb-3f43fabc6642';
UPDATE public.mommy_daily_messages SET message_tr = COALESCE(message_tr, 'Tebrikler, "Dördüncü Trimester" denilen o ilk 3 aylık uyum dönemi neredeyse bitiyor! Bebeğiniz artık "dış dünyaya" tamamen alıştı. Uyanık olduğu zamanlarda onu sadece yatakta tutmayın; evi gezdirin, birlikte pencereden bakın, farklı odalara götürün. O artık bir gözlemci. Bu dönemde onunla ne kadar çok görsel ve sesli temas kurarsanız, beynindeki nöron bağlantıları o kadar güçlü olur. Siz onun ilk ve en iyi öğretmenisiniz.') WHERE id = 'ef4c7b42-edd4-4ffb-87e6-5505b04254f6';

-- ── baby_daily_info → tr (1457 sətir) ──
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Uzun bir hamilelik döneminin ardından sonunda bebeğinize kavuştunuz. Anacan ailesi olarak bebeğinizle geçireceğiniz her mutlu günde yanınızda olacağız! 😊 Muhtemelen bebeğinizin doğduğu andan itibaren gününün neredeyse tamamını uykuda geçirdiğini fark etmişsinizdir. Hatta bu konuda zaman zaman bazı endişeler de yaşayabilirsiniz. Bilmelisiniz ki uyku, yenidoğan bebeğin sağlığı, büyümesi ve gelişimi için vazgeçilmez bir ihtiyaçtır. Beslenme ve bez değişimi dışında bebeğiniz zamanının neredeyse tamamını uykuya ayırır. Uyku sırasında vücudunda salgılanan melatonin hormonu, bağışıklık sisteminin güçlenmesini ve hipofiz bezinin daha fazla büyüme hormonu salgılamasını sağlar. Ancak bebeğiniz büyüdükçe uyku süresi kısalacak. Bu yüzden bu günleri olabildiğince dinlenerek geçirmenizde fayda var.') WHERE id = '31cd50a4-c6f5-4862-b0ff-2fa89b11b67b';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Doğumla birlikte bebeğinizin cildinde kremsi, beyaz ve yağlı bir tabaka fark etmiş olmalısınız. Verniks kazeoza denilen bu tabaka, %80''i su olmak üzere bol lipit ve protein içeren koruyucu, ince bir maddedir. Bu yağlı tabakanın cilt yüzeyindeki dağılımı, doğumun gerçekleştiği gebelik haftasına ve doğum şekline göre farklılık gösterebilir. Genellikle geç doğan bebeklerde bu tabakanın bir kısmı cilt tarafından emilmiş olur. 37 haftadan önce doğan bebeklerin cildinde ise bu tabakanın daha yoğun olduğu gözlemlenir. Verniksin içinde mikropları yok etme özelliğine sahip savunma hücreleri ve bebeğin vücudunda doğal bağışıklığı destekleyen 40''a yakın farklı protein bulunur. Bu nedenle bebeğinizi doğumdan sonra en az 24 saat yıkamamalı ve cildinin bu tabakayı iyice emmesini beklemelisiniz.') WHERE id = '01b8c794-e427-40d5-a912-edbb2df87798';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz dünyaya geldiği andan itibaren güçlü reflekslere sahiptir. Bu reflekslerin en önemlisi elbette beslenmesini sağlayacak olan emme refleksidir. Bebeğin yanaklarına ve ağız kenarlarına dokunulduğunda hemen o yöne dönme eğilimi gösterir ve besin kaynağını arar. Emme refleksi, bebeğin beslenme ve duygusal ihtiyaçlarını karşılayacağı mekanik bir hareketten oluşur. Henüz karnınızdayken, gelişiminin 14. haftasında oluşmaya başlayan bu refleks, ağız boşluğu ve damak kemiğinin tamamlanmasıyla şekillenen yanaklardaki vakum oluşturan kas yapısı sayesinde gerçekleşir. Gebeliğin oldukça erken evrelerinde ortaya çıkan bu refleks, bebeğin karnınızda olduğu süre boyunca alıştırma yapmasına imkân tanır. Bu sayede bebeğiniz doğduğu ilk andan itibaren beslenmek için gerekli deneyime ve beceriye sahip olur.') WHERE id = '4db7f0d9-f7be-435d-a305-5bea20ce135c';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz doğduktan sonra sizi birçok insan arasından içgüdüsel olarak tanır. Bu içgüdünün oluşmasına yardımcı olan etkenlerin kokunuz ve sesiniz olduğu düşünülüyor. Bebeğinizle kavuştuğunuz bu ilk günlerde bol bol emzirme alıştırması yapmalı, onunla göz teması kurarak konuşmalı ve ona nazikçe dokunmalısınız. Bebeğinizle temasta olacağınız her an, vücudunuzda oksitosin hormonunun salgılanmasını tetikler. Oksitosin hormonu, sütü süt bezinin ucuna doğru ulaştıran kas hücrelerinin kasılmasını sağlar. Bebeğinizi beslemenizi sağlayan diğer bir hormon ise beyninizdeki hipofiz bezi tarafından salgılanan prolaktin hormonudur. Bu iki hormon birlikte, uyum içinde çalışarak bebeğin emmesiyle birlikte sütün salgılanmasını ve süt ucuna ulaşmasını sağlar.') WHERE id = 'a25dea37-57a2-46fc-889c-23e73ad36d76';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz doğduktan hemen sonra doktor tarafından sağlık kontrolleri yapılır. Aynı zamanda doktor, doğumdan sonraki dakikalar içinde bebeğin ilk aşısı olan Hepatit B aşısını bacağına yapar. Eğer sizde Hepatit B taşıyıcılığı varsa, bebeğinize aşıyla birlikte immünoglobulin takviyesi de yapılır. Bunların dışında, ilk 1 ay içinde Hepatit B haricinde bebeğe yapılan başka bir aşı yoktur. Daha sonra bebeğiniz hastaneden çıkmadan bir çocuk doktoru tarafından ayrıntılı bir sağlık muayenesinden geçirilir. Ayrıca hastanenin görevlendirdiği hemşire, bebeğe ilk günlerde nasıl bakacağınızı ve nelere dikkat etmeniz gerektiğini anlatan bir eğitim verir. Verilen tüm bu bilgiler, bebeğinize nasıl bakacağınız konusunda size çok değerli ipuçları kazandırır.') WHERE id = '0d9fa9e8-940a-4ec4-b501-2f30433e0030';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin boyu ve kilosu bize genel sağlığı hakkında bilgi verir. Baş çevresinin ölçülmesi ise beyin fonksiyonlarını değerlendirmek için çok önemlidir. İlk ölçümlerde bebeğin baş çevresi genellikle 32 cm ile 37 cm arasındadır. Bu rakamlar beynin sağlıklı geliştiğini gösterir. Baş çevresinin büyümesi beyin gelişiminin göstergesi olduğu için buna dikkat etmek gerekir. Bebeğin boyunu, kilosunu ve baş ölçülerini düzenli olarak izlemek şarttır. Bu yüzden iyi bir çocuk doktoru bulmalı ve onunla birlikte bir takip takvimi oluşturmalısınız. Gelişimi izlemek için doğumdan sonra ortalama 5., 14. ve 30. günlerde rutin muayeneler için doktora gitmeniz önerilir.') WHERE id = '8c627179-a029-49ba-9226-4fa26ffce0a7';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğinizi yatırırken sürekli kıvrılmış hâlde kaldığını fark etmişsinizdir. 9 ay boyunca anne karnında cenin pozisyonunda kaldığı için bu alışkanlık bir süre daha devam edecek. Bu durum yaklaşık 2. ayda azalmaya başlayacak ve 3. ayda tamamen geçecek. Anne karnındaki o güvenli ve kapalı ortamdan sonra dış dünya ona korkutucu ve karmaşık gelebilir. Bu yüzden sürekli sizinle temasta olmak ister. Bu süreçte ona zaman verin, alışacaktır. Unutmayın; kokunuzu aldığı kucağınız onun için en güvenli yerdir. Anne ile bebek arasındaki o sağlam bağ, işte bu ilk günlerde oluşur. Acıktığında ya da temizliğe ihtiyacı olduğunda onu bekletmeyin, hemen ihtiyacını karşılayın. Bir süre dış dünyayı unutun ve sadece bebeğinizle ilgilenin.') WHERE id = '990edf71-6742-4577-9d2f-dadba792cf8a';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğinizle birlikte bir haftayı geride bıraktınız bile. Zaman ne kadar hızlı geçiyor, değil mi? 😊 Hamilelik boyunca bebeğin bağırsakları sterildir ve orada hiçbir zararlı organizma bulunmaz. Doğum sezaryenle gerçekleştiyse, sindirime yardımcı olan bakteriler bebeğin bağırsak florasında işte bugünden itibaren oluşmaya başlar. Normal doğumda ise bu süreç 4. günden itibaren başlamıştır. Bu bakterilerin bir kısmı faydalı, bir kısmı zararlıdır. Her iki türün varlığı sindirim sisteminde bir denge oluşturur ve birbirlerinin aşırı çoğalmasını engeller. Yani bu organizmalar bebeğin bağırsak florasının dengesi için önemlidir.') WHERE id = 'ea7ac5e6-2b68-47b7-9578-f87a52623334';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, '"Sütüm az" diye düşünüp kendinizi üzmeyin, sevgili anne. Bebek doğduğunda mide kapasitesi yalnızca bir kiraz kadardır. Bu yüzden sütünüzün yetmediğini düşünüp endişelenmeyin. Doğumdan sonraki günlerde büyüyen mide, bu günlerde artık bir kayısı büyüklüğünde, yani yaklaşık 50 ml hacmindedir. Dolayısıyla size az gelen o süt, aslında onun doyması için tamamen yeterlidir. Midesi henüz küçük olduğu için bebeğiniz az az ama sık sık emmek isteyecektir. Emzirdikten sonra kusuyorsa, bu genellikle mide kapasitesinden fazla yediğinde olur. Yani halk arasında söylenen "sütün yaramaması" hikâyesi sadece bir efsanedir, buna inanmayın.') WHERE id = 'f7f368ac-9bca-4520-b0e3-f83cfbd455a4';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Doğumdan hemen sonra gelen süte ağız sütü (kolostrum) denir. Bu, koyu kıvamlı, sarımsı renkte, bebeği enfeksiyonlardan koruyan antikorlarla zengin, protein değeri yüksek çok kıymetli bir besindir. Doğumdan yaklaşık 5-7 gün sonra yerini geçiş sütü alır. Geçiş sütünde yağ ve laktoz kolostruma göre daha fazladır, yani daha kalorilidir. Bu süt türü yaklaşık 14. güne kadar devam eder. Doğumdan 2 hafta sonra ise artık olgun süt gelmeye başlar. Bu süt hem su, hem protein, hem de yağ bakımından çok zengindir.') WHERE id = '4794b2b1-e590-4e29-b9bf-54af8c8dcab5';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebek bakımı, özellikle ilk kez anne oluyorsanız, başta size korkutucu gelebilir. Yapamayacağınızı düşünüyorsanız yanılıyorsunuz. 😊 Klasik bir söz gibi görünse de zamanla bebeğinizin bakımını çok rahat şekilde yapacaksınız. Bu bakım işlemlerinden biri de düşmek üzere olan ve kurumaya başlayan göbek bağı bakımıdır. Göbek bağı, hamilelik boyunca bebeğin beslenmesi ve gelişimi için gereken oksijen ve besin maddelerinin taşındığı yerdir. Yaklaşık 50 cm olan göbek bağı, doğumdan sonra doktor tarafından 2 cm kalacak şekilde kesilir. Bebeğin göbek kalıntısı 5. gün ile 15. gün arasında düşer. Düşmeden önce ve düştükten sonra göbek bakımını yapmazsanız, buradan enfeksiyon kapma olasılığı artabilir. Bu risk nedeniyle doktorunuzun önerdiği %70''lik alkol solüsyonuyla günde iki veya üç kez göbek bölgesini silmek ve havalandırmak gerekir.') WHERE id = '403ffca4-6096-4cf2-9210-17a6a3a59df5';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin başının vücuduna oranla daha büyük olması tamamen normaldir ve herhangi bir sağlık sorunu olduğu anlamına gelmez. Ayrıca başında bazı orantısızlıklar ve eğrilikler olabilir. Bunun nedeni, bebeğin başındaki kemiklerin doğumu tamamlayabilmek için henüz sertleşmemiş olmasıdır. Henüz sertleşmemiş kafatası kemikleri bol lifli kıkırdak dokusundan oluşur. Bununla birlikte, bebeğin beyin gelişiminin devam edebilmesi için bu açık alanlara ihtiyacı vardır. Ortalama olarak, doğduğu ayın sonuna kadar bebeğin başı alması gereken yuvarlak biçimini alır. 6 adet bıngıldakla doğan bebeğin, 2. ayın sonuna gelindiğinde ön üstteki hariç tüm bıngıldakları kapanır. Ön üstte yer alan büyük bıngıldak ise bebeğin 7. ayında sertleşmeye başlar ve 2 yaşına gelmeden kapanmış olur.') WHERE id = '878511ba-a575-4d79-8fa5-80ca329e838e';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Süt bezlerinde üretilen anne sütü, bebeğinize verebileceğiniz en değerli şeydir. Süt; iki tür protein, yağ, karbonhidrat, çeşitli vitaminler ve bebeğin virüs ve bakterilerle savaşmasına yardımcı olan antikorlar içerir. Sütünüzdeki yağlar; bebeğin beyin gelişimi, enerji kaynağı oluşturması ve yağda çözünen vitaminlerin emilip vücuda kazandırılması için gereklidir. Tüm bu özellikleri sayesinde, bebeğin ihtiyaç duyduğu bütün besin maddelerini ilk 6 ay boyunca başka hiçbir besine gerek kalmadan tek başına sağlayabilen en iyi besindir. Mama denilen formüller ise sütünüzün yetersiz kaldığı durumlarda bebeğin beslenmesi için tek alternatiftir. Çoğunun ana maddesi inek sütü olan bu karışımlar, doğal sütlere bazı eklemeler yapılarak veya bazı maddeler çıkarılarak üretilir. Ancak anne sütüne göre daha fazla kazein proteini içerdiğinden, bebeğiniz tarafından sindirimi daha yavaş gerçekleşir.') WHERE id = 'a9c4f35f-77e6-4302-9bda-fc0e36e3f3da';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin doğum kilosu ilk günlerde %10 oranında azalabilir. Bu azalmanın ardından en geç 10. güne kadar doğum kilosuna ulaşması beklenir. Yenidoğan dönemi, bebeğin tüm hayatı boyunca gelişiminin en hızlı olduğu dönemdir. Bebeğiniz ilk aylarında 2 cm ile 6 cm arasında uzayabilir ve 700 gram ile 1500 gram arasında kilo alabilir. Bu değerlerin bebeğin cinsiyetine göre farklılık gösterebileceğini, ayrıca erken doğan bebeklerde bir süre daha yavaş ilerleyeceğini unutmamalısınız. Bebeğin kasları, refleksleri ve fiziksel becerileri de ilk aylarda bu bedensel büyümeye paralel olarak oldukça hızlı gelişir. Bu nedenle bu dönemde bebeğin gelişimini destekleyecek doğru uyaranları sağlamalı ve doktorunuzla düzenli olarak görüşmelisiniz.') WHERE id = '379e34a9-be36-4930-a59c-af93a24eb449';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin altını temizlemek, yeni anne olmuş bir kadına başta oldukça korkutucu gelebilir. Bebeğin bezini değiştirirken gereken her şeyin elinizin altında olmasını sağlamalı ve işe ellerinizi yıkayarak başlamalısınız. Alışma aşamasında hemşirelerden, yakın çevrenizden ve akrabalarınızdan yardım alabilirsiniz. Bebeğiniz doğumdan sonraki birkaç ay boyunca sık bez değişimine ihtiyaç duyacak. Yine de bebeğiniz uyurken, altı çok ıslak olmadığı sürece sadece bezini değiştirmek için onu uyandırmanıza gerek yok. Bu yüzden gece beslenmeleri sırasında bir rahatsızlık hissetmediğini düşünüyorsanız, gece boyunca bez değişimi yapmamalısınız. Uyuyan bebeği rahatsız etmek uykusunu böleceği için yeniden uykuya dalması zorlaşabilir.') WHERE id = 'd0704bed-eb75-4a28-b892-e481bca3aba6';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz dünyaya geldikten sonra göbek bağı yaklaşık 10-14 gün içinde tamamen kuruyup düşer. Ancak bazı durumlarda bu süre uzayabilir. Bebeğin göbek bağı hâlâ düşmediyse mutlaka en yakın çocuk doktoruna başvurmalısınız. Göbek bağının 20 gün dolduğu hâlde düşmemesi, bebeğin bağışıklık sisteminde bazı sorunlar olduğuna işaret edebilir. Bebeği yıkarken göbek bölgesini ıslatmamaya çalışmalı, ıslandığında ise mutlaka kurulamalısınız. Nemli kalan göbek bağı hem zamanında düşmez hem de çeşitli enfeksiyonlara yol açabilir. Ayrıca göbek bağının hızlı ve sağlıklı düşmesi için, doktorunuz önermedikçe herhangi bir ilaç veya losyon kullanmamalısınız.') WHERE id = '46a30d17-6906-4dd1-9f3a-fa10b39a15db';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Gün içinde bebeğinizle sık sık temas kurarak onu emzirmeniz, yeni dünyaya uyum sağlamasını epey kolaylaştırır. En modern kuvözün bile bebeklere anne kucağı kadar güçlü bir bakım sağlayamadığı uzun zamandır bilinen bir gerçektir. Temas kurmanızla birlikte dokunuş, sıcaklık ve koku gibi duyular bebeğinizle aranızdaki duygusal bağı güçlendirir. Ayrıca bu temas, başarılı emzirmenin sürmesi için önemli bir etken sayılır. Bebeğin bu aşamada kurduğu güçlü duyusal bağ, ruhsal ve fiziksel gelişimini hızlandırır. Çocukluk hayatının sonraki dönemlerinde güven duygusunu kazanması için de son derece önemlidir. O hâlde tüm işlerinizi erteleyin ve bebeğinizle bol bol ten tene temasta olun! 😊') WHERE id = 'd3f6fa0e-5b44-4a86-8dac-648c5ea0fb9f';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Doğum sonrası dönem (lohusalık), kadının doğumdan sonra yaşadığı yaklaşık 6 haftalık süreyi kapsar. Özellikle bebeğinize ve yeni hayata alışmaya çalıştığınız bu dönemde zaman zaman duygusal iniş çıkışlar yaşayabilirsiniz. Bu dönem, hamilelik boyunca metabolizmanızda ve üreme sisteminizde oluşan değişikliklerin geri döndüğü bir süreçtir. Hormon seviyeleri ve rahmin boyutları hızla hamilelik öncesi hâline döner. Yaklaşık 9 ay boyunca yavaş yavaş geçirdiğiniz fizyolojik ve hormonal değişikliklerin 6 hafta gibi kısa bir sürede geri dönmesi sizi psikolojik olarak etkileyebilir. Zor bir doğum hikâyeniz varsa bu dönemi normalden daha ağır geçirebilirsiniz. Bu zorlu sürecin geçici olduğunu kabul etmeli ve kendinizi iyi hissetmiyorsanız yakınlarınızdan ya da bir uzmandan yardım istemekten çekinmemelisiniz.') WHERE id = 'ee31cac0-139c-4b54-962e-0e0cfd50ac5a';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Doğum sonrası dönemde genital bölgenin temizliğine daha çok dikkat etmelisiniz. Unutmayın, doğumdan sonra bu bölge enfeksiyona yol açan bakterilere karşı oldukça hassaslaşır. Özellikle normal doğumda epizyotomi (kesi) uygulandıysa, doktorunuzun önerdiği antiseptik kremlerle bakım yapmanız gerekebilir. Sezaryen ameliyatından sonraki ilk haftalarda ise dikişin olduğu bölgeye özel önem göstermelisiniz. Ameliyatı yapan doktorun önerilerini dikkate almalı ve kontrollerinizi aksatmamalısınız. Duş alırken suyun aşırı sıcak olmamasına dikkat etmeli ve mutlaka yanınızda biri varken duşa girmelisiniz. Sezaryenle doğum yaptıysanız duş sırasında dikiş yerlerini korumalı ve o bölgenin enfeksiyon kapmamasına özen göstermelisiniz.') WHERE id = '146cc0cd-e1d3-412a-82e1-01fb76131db8';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz gün içinde sık sık ağlayabilir; hatta bu ağlamalar bazen katılma nöbetleri şeklinde olabilir. Ağlama krizleri, özellikle onu sakinleştiremediğiniz anlarda sizi oldukça çaresiz hissettirebilir. Sakin kalmalı ve bebeğin sizinle kurabileceği tek iletişim aracının ağlamak olduğunu unutmamalısınız. Bebeğin ağlamasının pek çok farklı nedeni olabilir. Bu nedenlerden biri kıyafetlerinin onu rahatsız etmesi, üşümesi ya da terlemesi olabilir. Özellikle ilk kez anne olanlar, hastalanır korkusuyla bebeklerini gereğinden kalın giydirebiliyor. Bu dengeyi korumak için bebeğinize kendi giydiklerinizden yalnızca bir kat fazla giydirmeniz yeterli olacaktır.') WHERE id = '92bf1f12-3409-4d88-8829-221346b3ee91';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Temas, bebeğinizle aranızdaki bağın gelişmesi ve güçlenmesi için son derece önemlidir. Sizinle fiziksel temas kuran bebeğiniz, karnınızdayken duyduğu ilk ses olan kalp atışlarınızla sakinleşir. Ayrıca bu yöntem, daha derin ve rahat uyumasına yardımcı olur. Dünyanın pek çok kültüründe bebekler doğar doğmaz çıplak hâlde annenin göğsüne konur. Bilimsel araştırmalara göre bu ilk fiziksel temas, bebeğin temel biyolojik ihtiyaçlarının karşılanmasını sağlar. Bu temas, bebeğin gelecekteki psikolojisinin ve davranışlarının şekillenmesinde çok hassas bir dönemi kapsar. Yapılan araştırmalar, annesiyle sık temas kuran bebeklerde 3. ve 6. aylarda yalnızca anne sütüyle beslenme oranının 2 kat daha yüksek olduğunu gösteriyor. Aynı araştırmada bu yöntem sayesinde bebeklerin 2 yaşına gelene kadar diğer bebeklere göre 12 kat daha az ağladığı da belirtilmiştir.') WHERE id = 'c9ec86c3-ffa1-4c34-8c50-574a23ddec68';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Doğumdan sonraki ilk günlerde lohusalık dönemine özgü, parlak kırmızı renkli, âdet kanamasına yakın miktarda akıntılar yaşamanız normaldir. Loşia denilen bu akıntılar 1-2 hafta içinde bitebileceği gibi 6 haftaya kadar da sürebilir. Akıntının miktarı günler geçtikçe azalır ve renginde bazı değişiklikler olur. Lohusalık döneminin sonlarına doğru ise beyaza çalan bir akıntıya dönüşür. Bu dönemde genital bölge bakımı için günlük hijyenik pedinizi sık sık değiştirmeli ve genital bölgeye özel temizleyiciler kullanmalısınız. Lohusalık döneminde aşırı ve uzun süren kanamalar, rahim içinde plasenta dokusu kalmasına ya da enfeksiyon oluşumuna işaret edebilir. Bu durum nadir görülse de belirtiler varsa ihmal etmemeli ve mutlaka doktorunuza danışmalısınız.') WHERE id = '8438f645-667d-4bb4-ad8d-04104669e5fa';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Yenidoğan bebekler anneye çok muhtaçtır ve sahip oldukları en gelişmiş duyu dokunmadır. Bebeğin bu temas ihtiyacını en iyi karşılayabileceği anlar ise kokunuzu aldığı emzirme zamanlarıdır. Bebeğiniz dünyaya geldiği ilk aylarda yalnızca karnı acıktığında emmek istemez. Kendini güvende hissettiği tek yer kokunuzu alabildiği yer olduğundan, emerek uyumak isteyebilir. Bu yüzden emme isteği karnını doyurmanın yanı sıra duygusal açıdan da son derece önemlidir. Bebekler ancak üç aydan sonra sosyal temasa geçer. O yüzden toplumda yanlış bilinen "kucağa alışır" düşüncesiyle bebeğinizden uzak durmamalısınız. İlk aylarda bebeğinizle bol bol kucaklaşmanız, dış dünyaya uyum sürecini kolaylaştırır ve güven duygusunu pekiştirir.') WHERE id = 'a82a92d2-bea2-44d6-bcce-77b7bcd63519';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Rahminiz doğumdan sonra hâlâ hamilelik öncesi normal boyutuna göre epey büyüktür. Şu anda rahminizi genellikle göbek hizasında veya biraz yukarısında hissedebilirsiniz. Yaklaşık 1 ay içinde rahminiz tamamen eski boyutlarına dönecek. Doğum sırasında yaklaşık 1500 gram olan rahim kütlesi her gün biraz daha küçülerek hamilelik öncesindeki gibi yeniden 60 grama iner. Zaman zaman, özellikle emzirme sırasında, oksitosin hormonunun etkisiyle rahim bölgesinde kasılmalara bağlı ağrılar olabilir. Doğumu izleyen ilk günlerde şiddeti biraz fazla olan bu sancılar günler geçtikçe hafiflemeye başlar. Bu kasılmaların normal olduğu, hatta rahmin iç tabakasının temizlenmesine yardımcı olduğu düşünülmektedir.') WHERE id = '79a8c317-465e-48a5-8158-982eb6d5f890';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Yenidoğan bebekler acıkmaya başladıklarında ağlamak yerine önce kıpırdanmaya başlar. Bu hareketlerin ardından yavaş yavaş huzursuzluk hissedebilirler. Bu tepkilerin sonunda hâlâ karınları doymadıysa ağlamaya başlarlar ve aç kaldıkları süre uzadıkça ağlamanın şiddeti de artar. Bebeği bu aşamada doğrudan doyurmaya çalışmanız, bazı durumlarda memeyi veya biberonu reddetmesine yol açabilir. Bu yüzden ağlayan bebeği önce kucağınıza alıp sakinleştirmeli, sonra karnını doyurmalısınız. Kucağınıza almanıza rağmen bebeğiniz sakinleşmiyorsa ayakta emzirmek bir alternatif olabilir. Henüz bebeğinizle birbirinize alışma sürecinde olduğunuz için onun tepkilerini gözlemlemeli ve ne istediğini anlamaya çalışmalısınız.') WHERE id = '9e7fdf66-075d-494d-b199-11e006ca39c4';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Doğumdan itibaren bebeğin en önemli ihtiyacı olan anne sütü göğsünüzden salgılanmaya başlar. Bu yüzden ilk haftalarda bol sıvı almalı ve elinizden geldiğince stresten uzak durmalısınız. Bu haftadan itibaren hem sizde hem de bebeğinizde gaz şikâyetleri başlayabilir. Bebeğin gaz sancılarını hafifletmek için doktorun önereceği gaz damlaları genellikle 1. aydan sonra verilir. Bu nedenle gaz yapan yiyeceklerden uzak durmaya çalışmalı; şekersiz komposto, taze sıkılmış meyve suları ve sebze çorbalarını beslenme programınıza eklemelisiniz. Süt ve süt ürünleri, baklagiller, portakal ve mandalina gibi ekşi meyveler gaz sancılarına yol açabilir. Bu yüzden bu yiyecekleri deneyerek menünüze eklemelisiniz. Süt ürünleri gaz yapıyorsa laktozsuz süt kullanabilirsiniz.') WHERE id = 'bbfc25e1-805a-4de5-a48e-49b8bc100ff1';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin uyku düzeninin oluşması biraz zaman alabilir. İlk aylarda genellikle tüm gün uyuyup uyanan bebeğin gece ile gündüzü ayırt edememesi de uyku düzeninin oturmasını geciktiren etkenlerdendir. Bebeğin aşırı yorgun ve uykusuz olması ağlamasına neden olur. İlk aylarda günde 15-16 saate kadar uyuması beklenen bebeğiniz uyuyamadığında çok huzursuz olur. Ayrıca bebeğin çok gürültülü ortama ve görsel uyaranlara maruz kalması da uykuya dalmasını engelleyip ağlamasıyla sonuçlanabilir. Bebeğin uyku düzeni 8-12. haftalar arasında yavaş yavaş şekillenmeye başlar. Emzirme aralıklarının uzaması da bu düzene yardımcı olur. Ancak her bebek farklı olduğu için bazılarının uyku düzenine daha geç uyum sağlaması normal kabul edilir.') WHERE id = 'a4331c8d-b2a0-435c-af06-870f5fad8fab';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz doğduğu ilk andan itibaren insan seslerine karşı çok duyarlıdır. Bunun nedeninin frekans aralıklarıyla ilgili olduğu düşünülüyor. Bununla birlikte, 9 aylık süre boyunca karnınızda en çok duyduğu sesler organlarınızın çalışırken çıkardığı sesler ve konuşurken duyduğu sizin sesinizdir. Bebeği sakinleştirmek için bu fırsatı değerlendirip onunla bol bol konuşmalısınız. Sesinizi duyan ve kucağınıza aldığınızda kalp atışlarınızı hisseden bebek kendini çok rahat ve güvende hisseder. Ayrıca bebeğiniz duygularını ve ihtiyaçlarını ifade etmek için bazı sesler çıkarmaya başlamış olabilir. Bebeğinizle etkili iletişim kurmak için onun çıkardığı seslere benzer seslerle karşılık vermeniz önemlidir. Böylece bebeğiniz iletişim kurmak amacıyla konuşmayı ve sesleri kullanmayı öğrenmeye başlar.') WHERE id = '1ec6d652-1eca-417a-9067-3ad2a20a5f4b';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeklerin yaklaşık %20''si sağlıklı olmalarına rağmen durmaksızın ağlama krizlerine girebilir. Kolik sancıları denilen bu durum genellikle akşam saatlerinde başlar ve bebeği saatlerce sakinleştirmek mümkün olmaz. Kolik sancılarının nedeni henüz tam bilinmese de sindirim sisteminin tam gelişmemesinden, bazı alerjik reaksiyonlardan ya da sinir sisteminden kaynaklandığı düşünülüyor. Doktor bebeğinize kolik teşhisi koyduysa endişelenmeniz normaldir. Öncelikle bu durumun geçici olduğunu bilmelisiniz. Genellikle 3. ayın sonunda bu ağlama krizleri azalmaya başlar ve kısa sürede düzelir. Bebeğin ağlama krizleri sırasında onu rahatlatmak için farklı yöntemler deneyerek hangisinin işe yaradığını bulmalısınız. Genel olarak denenmiş yöntemler: ılık banyo yaptırmak, karnına ılık havlu koymak ya da fön makinesi gibi tekrarlayan sesli cihazları çalıştırmak olabilir.') WHERE id = 'd6246f09-676f-479b-ac15-8f1e83a043b1';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğinizle birlikte 1 ayı daha geride bırakıyorsunuz! Bebeğin aşı takviminin 1. ayında, ilk dozu doğumdan hemen sonra yapılan Hepatit B aşısının ikinci dozu uygulanır. Aşının yapıldığı bacakta kızarıklık ve şişlik oluşabilir. Bu durumda endişelenmemelisiniz. Ayrıca bebeğinizde kısa süreli ateş yükselmesi ve aşı sonrası huzursuzluk gözlemleyebilirsiniz. Bu etkiler sık görülen ve zararsız yan etkilerdir. Özellikle huzursuzluk belirtisi, aşı olan bebeklerin neredeyse tamamında görülebilir. Aşıdan sonra ateş genellikle 38 dereceyi geçmez. Doktorunuzun önerisiyle kısa sürede düşmeyen ateş için şurup veya fitil kullanabilirsiniz. Nadir görülse de bebeğinizde olağan dışı belirtiler olduğunu düşünüyorsanız doktorunuzla iletişime geçmeyi unutmayın.') WHERE id = '418e11ce-7ef6-4382-bb9b-0ee9fe10e295';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'İlk zamanlarda bebeğinizin emzirme sırasında uykuya daldığını gözlemleyebilirsiniz. Bu durum birçok anne gibi sizin de hoşunuza gidebilir. Ancak dikkatli olun; bu bir alışkanlığa dönüşürse bebeğiniz emmeden uykuya dalmakta zorlanabilir. Bebeğiniz bu düzene alıştığında, emmeden uyumak istemeyecek. Bu yüzden uykusunun geldiğini ve huzursuzlandığını hisseder hissetmez onu beşiğine koyarak farklı uyutma yöntemleri denemelisiniz. Bebeğiniz yeni yöntemlere alışırken önce ağlayabilir. Ama pes etmeden devam ederseniz zamanla alıştığını göreceksiniz. Bu denemeler sırasında bebeğiniz uykuya çok direnirse onu sakinleştirmeli ve sonra yeniden kendi hâline bırakmalısınız.') WHERE id = '9210140f-4b86-4445-aa81-e541ebeace13';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Rahminiz 9 ay boyunca bebeğiniz için son derece sıcak ve rahat bir ortam sağladı. Doğumla birlikte ani gürültü ve ışıkla dolu dış dünyaya gelmek bebeğiniz için küçük bir şok yaratabilir. Bu yüzden yeni ortama alışması biraz zaman alabilir. Bebeğinizi yatırırken hâlâ karnınızdaki gibi kıvrılıp yattığını (cenin pozisyonu) görüyorsanız nedeni tam da budur. Yaklaşık 1 ay içinde bu alışkanlığın azaldığını gözlemleyeceksiniz. Bu uyum döneminde size her zamankinden daha çok ihtiyacı var. Onu kucağınıza almanız, öpmeniz, onunla konuşmanız, kısacası onunla ilgilenmeniz çok hoşuna gider ve bu, vücudunda mutluluk hormonlarının salgılanmasını sağlar.') WHERE id = 'd3c1171d-ec50-4947-af33-82084d44686e';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Günler hızla geçiyor ve siz her gün anneliğe biraz daha alışıyorsunuz. Bebeğinizle aranızdaki bağ belki de tarifsiz bir sevgi ve güçlü bir koruma duygusu şeklinde çoktan oluştu. Ancak bu duygunun her kadında hemen ve aynı şekilde oluşması gerektiği düşüncesi doğru değildir. Her insanın duyguları farklı olduğu gibi, doğum stresi ve lohusalık gibi nedenlerle bazı kadınların bebeklerine bağlanması zaman alabilir. Ara sıra bebeğinize karşı yabancılık hissediyorsanız bunun için kendinizi suçlamayın. 9 ay boyunca kanınızda giderek artan hormonların doğumdan sonra kısa sürede hızla değişmesi psikolojinizi etkileyebilir. Haftalar geçmesine rağmen hâlâ bebeğinize karşı yabancılık hissediyorsanız doğum sonrası depresyon yaşıyor olabilirsiniz. Bu durumda mutlaka doktorunuza danışmanızı ve psikolojik destek almanızı öneririz.') WHERE id = '08ca900e-fc32-45d6-bd75-a4633391d4f9';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebekler doğduktan sonra belirli haftalarda hızlı büyüme ve gelişme dönemleri (atak dönemleri) yaşar. İçinde bulunduğunuz 5. hafta da bu büyüme sıçramalarının gerçekleştiği ilk haftadır. Bu yüzden bu günlerde bebeğin normalden fazla ağlaması, huysuzlanması, uyku sorunları yaşaması ya da iştahının değişmesi tamamen normaldir. İştahının artması hem büyümek için daha fazla enerjiye ihtiyaç duyması hem de bu ihtiyacı karşılamak için daha çok emerek süt üretimini artıran hormonları devreye sokma isteğidir. Bu 5. hafta atağında bebeğiniz duyu organlarını aktif şekilde kullanarak çevresindeki her şeyin farkına varmaya başlar. Kısacası bebeğiniz artık sadece beslenme ve uykudan ibaret bir dünyada olmadığını keşfediyor. Sonuç olarak daha fazla uyarana maruz kaldığı için bazen huzursuzluğu artabilir. Yalnızca birkaç gün sürecek bu dönemi elinizden geldiğince sabırla karşılayın ve geçici olduğunu unutmayın.') WHERE id = '3c3db532-5b9a-41a9-8a5e-67563130c5c0';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğinizin dış dünyadaki ilk ayının tamamlanmasıyla birlikte artık çevresine karşı daha meraklı olduğunu fark etmişsinizdir. Bebeğiniz özellikle çevresindeki ilginç nesnelere, büyük şekillere, parlak ve kontrast renklere ilgi göstermeye başlar. Doğumdan sonraki ilk günlerde gözlerini kısa süreliğine açan bebeğiniz artık daha uzun süre uyanık kalıyor. Bu da demek oluyor ki çevreyi keşfetmek için gerekli duyularını kullanmaya başladı. Uyanık olduğu kısa zamanlarda bebeğinize renkli kumaşlar gösterebilir veya dokundurarak çeşitli etkinlikler yapabilirsiniz. Bu tür oyunların çok hoşuna gittiğini göreceksiniz. Ayrıca görme yeteneği henüz tam gelişmediği için, sizi daha iyi tanıması adına yüzünüzü ona yaklaştırarak sizi incelemesine imkân tanımalısınız. 😊') WHERE id = '676e6646-3ff2-4bc0-82e0-4614c3d8096a';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeklerde beşik şapkası olarak bilinen ve saçlı deride kabuklu, pullu lekelere yol açan konak, ilk aylarda sık görülen bir cilt durumudur. Kırmızı ve pullu bu döküntüler alına, kulak arkasına, boyuna ve koltuk altına kadar yayılabilir. Bebeğinizde konak oluştuysa endişelenmeye gerek yok. Bu genellikle kaşıntı yapmaz ve bebeği rahatsız etmez. Bazen bezini değiştirirken konağın oraya da yayıldığını görebilirsiniz. Nadir durumlarda bez bölgesinde bu durum mantar enfeksiyonuyla birlikte görülebilir. Konağın kesin nedeni bilinmese de genetik yatkınlık, ciltte doğal olarak yaşayan mayalar, tahriş edici maddeler, kuru ve soğuk hava gibi etkenler buna yol açabilir.') WHERE id = 'dc08af3a-ac5d-4bd3-9ab0-537157d76301';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz, her bebek gibi ilk aylarında çok hassastır. Bağışıklık sistemi henüz tam olgunlaşmadığı için bazı hastalıklara karşı savunmasız olabilir. Aylardır beklediğiniz yavrunuza kavuşmanın mutluluğunu yaşasanız da onun rahatsızlığı sırasında üzüntü ve hassasiyet hissetmeniz doğaldır. Özellikle bebeğinizde herhangi bir sağlık sorunu ortaya çıkarsa buna daha çok üzülebilirsiniz. Ama bu aşamada kendinizi suçlu hissetmemeli, zorlukların üstesinden gelmek için tüm enerjinizi bebeğinize ve kendinize yöneltmelisiniz. Kısacası endişelenmeyin, mutlu olmaya çalışın. Unutmayın; bebeğiniz hissettiğiniz her duyguyu anlar ve onun ruh hâli doğrudan size bağlıdır.') WHERE id = '90453aab-3c85-45f7-a53b-d1654064425e';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin yatış pozisyonunu ayarlarken kusma ve boğulma tehlikesine karşı dikkatli olmalısınız. Bebeği başı yana çevrilmiş hâlde yüzüstü, sırtüstü veya yan yatırmakta bir sorun yoktur. Ancak uzun süre aynı pozisyonda yatması, henüz yumuşak olan kafatası kemiklerinde şekil değişikliğine yol açabilir. Bu yüzden uyku sırasında bebeğin pozisyonunu ara sıra değiştirmelisiniz. Bebeği yan yatırdığınızda sırtını küçük bir yastıkla destekleyip denge sağlamanız gerekebilir. Uykuda boğulma riskine karşı doktorunuzun önerisiyle eğimli yatakları seçmek iyi bir fikir olabilir. Ayrıca düz bir baş yastığı kullanarak bebeğin başının arka kısmının düzleşmesini önleyebilir ve yuvarlak biçimini koruyabilirsiniz.') WHERE id = '82ca4410-dc4b-42c9-8de1-8024396fe373';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Rahminizde 9 ay boyunca tamamen steril bir ortamda yaşayan bebeğinizin bağışıklık sistemi dış dünya için henüz tam hazır değildir. Doğumdan önce bağışıklığın tam gelişmemesinin nedeni, sizin bağışıklık sisteminizle karşılıklı olarak birbirlerine zarar vermemeleridir. Doğumla birlikte hormonların yardımıyla salgılanan sütünüz, bebeğiniz için geçici bir bağışıklık oluşturur. Vücudunuzdan süt yoluyla bebeğinize geçen antikorlar, özellikle hastalık sırasında artarak bebeğin vücudunu korur. Bu yüzden aksi bir durum yoksa ve doktor önerisi olmadan ek besin takviyeleri vermemelisiniz. İlk aylarda emzirme sıklığıyla ilgili kesin bir kural yoktur; buradaki temel etken bebeğin iştahıdır. Emzirdikten sonra bebeğin doymadığını düşünüyorsanız bilmelisiniz ki ilk aylarda emme isteği bir refleksin sonucudur ve bu her zaman bebeğin aç olduğu anlamına gelmez.') WHERE id = '376e500c-ed21-4d44-817e-05fcffb83c34';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz için bu ay içinde polikliniklerden ücretsiz alabileceğiniz veya doktorunuzun önerdiği D vitamini damlasına başlamalısınız. D vitamininin ana kaynağı güneş ışınlarıdır ve belirli bir süre güneşlenmek vücudun bu ihtiyacının %90''ını karşılar. Ancak bilimsel araştırmalara göre D vitamini eksikliği yaygın sağlık sorunları arasındadır. D vitamini, bebeğin gelişmekte olan bağışıklık sisteminin düzenleyicisidir. Özellikle otoimmün hastalıklarda vücuttaki D vitamini deposu önemlidir. Hayatının ilk gününden itibaren anne sütü veya mamayla beslenen bebeğiniz, D vitamini dışındaki tüm vitaminleri yeterince alır. Ancak D vitamini besin yoluyla bebeğin vücuduna yeterli miktarda giremez. Bu yüzden bu eksiklik mutlaka doktorunuzun belirleyeceği D vitamini takviyesiyle tamamlanmalıdır.') WHERE id = '4c2feb95-7f80-4a6f-9d8b-18f61f673c70';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Hamilelik boyunca vücudunuzda oluşan değişikliklerin doğumdan sonra eski hâline dönmesi sürecine lohusalık dönemi denir. Ancak lohusalık yalnızca doğumdan sonraki 40 günü veya 6 haftalık süreyi kapsar. Doğum sonrası dönem ise her kadında farklı olmakla birlikte lohusalıktan daha uzun sürer. 9 aydır hayalini kurduğunuz o mucizeyi artık kollarınızda tutuyorsunuz. Ancak uykusuzluk, yorgunluk, fiziksel ağrılar, kendinize ve ev işlerine zaman ayıramamak hâlâ devam edebilir ve bu, sizde "yetişemiyorum" hissi yaratabilir. Bazen sebepsiz yere sinirlenebilir ve çevrenize sert tepkiler verebilirsiniz. Kısacası doğum sonrası psikoloji karmaşıktır ve bunu sadece 40 günle sınırlamak doğru değildir. Ailenize duygularınızı anlatmalı ve onlardan anlayış beklemelisiniz. Unutmayın, tüm bu süreç geçicidir. Her kadın kendi bebeği için mükemmel bir annedir. Yaşayacağınız her zorlukta yanınızda olacağız. 😊') WHERE id = 'bad42002-8275-46dc-b1ad-174066cad7e7';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğinizi taşımak veya uyutmak için ana kucağı gibi destekleyici araçlar kullanıyorsanız, üst kısmına bebeğe zarar vermeyecek şekilde dikkat çekici oyuncaklar yerleştirebilirsiniz. Bu nesneler bebeğin dikkatini çekerek görme ve algılama yeteneğinin gelişimine katkıda bulunur, anlama becerisini güçlendirir. Işıklı, sesli ve hareket ettirebileceği oyuncaklar bebeğinizin çok hoşuna gidecek. Yeni şeyler keşfetmek bebeği hem heyecanlandırır hem de eğlendirir. Aynı zamanda çevredeki rengârenk uyaranlarla karşılaşmak, kendini keşfetmesine yardımcı olur. Ancak bu seçimleri yaparken dikkatli olmalısınız. Televizyon gibi çok hareketli, renkli ve sesli cihazlar bebeğin dikkatini çekse de bunun gelişime olumsuz etki edeceği kaçınılmaz bir gerçektir.') WHERE id = '3ad7f64e-f78d-46bd-a402-26a3f15d1d22';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Doğru emzirme pozisyonunu bulmak hem bebeğin sütten en üst düzeyde yararlanması hem de sizin beden sağlığınız için çok önemlidir. Emzirirken rahat bir pozisyon almalı, sırtınızı ve belinizi yastıkla desteklemelisiniz. Ayrıca emzirdiğiniz taraftaki kolunuzun altına yükseklik koyarak süreç boyunca kolunuzu havada tutmaktan kaçınmalısınız. Emzirme sırasında bebeği olabildiğince kendinize yakın ve yüzü size dönük şekilde tutmalısınız. Bebeğin bedenini kolunuzun iç yüzeyine, başını ise dirsek boşluğunuza yerleştirmeniz en idealidir. Doğru pozisyon seçmek bebeğin gelişimi için de belirleyicidir. Çünkü bebeği yanlış pozisyonda tutup emzirmeye devam ederseniz boynu çabuk ağrımaya başlar ve emmeyi daha erken bırakır.') WHERE id = '4be7fa1f-7739-407d-aa85-d7577ebd4d3a';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin gaz sancıları artık kendini can sıkıcı şekilde hissettirmeye başlamış olabilir. Bebeğin beden dilini izlerseniz; özellikle bacaklarını karnına doğru çekiyor, kızarıyor, ağlıyor ve bisiklet sürer gibi hareketler yapıyorsa büyük olasılıkla gaz sancısı yaşıyordur. Bu belirtiler emzirme veya beslenme sonrası ortaya çıkıyor ve bebek sakinleşmiyorsa neden muhtemelen gazdır. Bunu anlamak zor değildir; gaz sancısı olan bebek huzursuz olur, emmek ister ama kısa süre sonra yeniden ağlamaya başlar. Ayrıca gazı olan bebeklerin karnı sert ve şiş görünür. Onu hareket ettirmek bağırsaklarındaki havayı dağıtacağı için rahatlamasına yardımcı olabilir. Gaz ve kolik sancıları çok rahatsız edici olsa da geçici bir dönemdir. Bu yüzden sakin kalmalı ve bunun geçeceğini bilmelisiniz. Bu anlarda bebeği rahatlatmak için sakin bir odaya geçmek, onunla yumuşak bir sesle konuşmak, ışıkları kapatmak ve karnına masaj yapmak çok iyi gelecektir.') WHERE id = '16924675-e88b-458a-9fb7-e716fc169d02';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeği düzenli yıkamak hem bağışıklığı hem de cilt sağlığı için çok önemlidir. Ancak banyo rutinlerinde dikkat etmeniz gereken bazı noktalar var. Bunların en önemlisi suyun sıcaklığıdır. Bebek banyosu için su yaklaşık 37 derece olmalıdır. Bundan soğuk veya sıcak su bebeğin cildine zarar verebileceği gibi hastalanmasına da yol açabilir. Oda sıcaklığını ise 22-24 derece arasında tutmalısınız. Diğer önemli konu küvetteki suyun seviyesidir. Bir anlık dikkatsizlikte bebek elinizden kayabilir; bu yüzden suyun derinliği 15 cm''yi geçmemelidir. Yıkama sırasında bebeğin başını ve vücudunu aynı anda ıslatmamaya çalışın. Baş bölgesinden ısı kaybı çok hızlı olur. Bebeğin üşümesini önlemek için önce vücudunu yıkamalı, vücutla işiniz tamamen bittikten sonra başını yıkayarak banyoyu tamamlamalısınız.') WHERE id = '9a3356cb-31bb-4c91-8c4b-755f5e18597d';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz ağırlıklı olarak anne sütüyle besleniyorsa dışkısının kıvamı oldukça sıvı olabilir. Ancak bazen bebeğinizde kabızlık veya ishal sorunlarıyla da karşılaşabilirsiniz. Bebeklerde sindirim sorunları sık görülür; çünkü bağırsakları çok hassastır. Bu nedenle kabızlık, ishal ve gaz gibi durumlar fizyolojik olarak normal kabul edilir. Özellikle mamaların sindirimi görece zor olduğu ve anne sütüne göre sindirim sisteminde daha uzun kaldığı için zaman zaman kabızlığa yol açması sık rastlanan bir durumdur. Her bebekte olduğu gibi sizin bebeğinizin de bağırsak çalışması ve tuvalet sıklığı farklıdır. Bazı bebekler günde birkaç kez, bazıları ise 5 günde bir kaka yapabilir. Dışkı yumuşaksa, aşırı ıkınma yoksa, kilo alımı yolundaysa ve bebeğin genel durumu iyiyse endişelenmeye gerek yoktur.') WHERE id = '315efeec-966c-4318-a08f-5aee7f235a22';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Havanın güzel olduğu günlerde bebeği dışarı çıkarmak hem sizi rahatlatır hem de bebeğin gelişimine destek olursunuz. Dışarıdaki hava ve ses değişimleri, çevrenin etkisi bebeğiniz için farklı bir sakinleşme yöntemi olabilir. Bebekle dışarı çıkmak birçok anneye zor gelebilir. Aslında bu sadece bir alışkanlık meselesidir. Bebeğinizle ne kadar çok dışarı çıkarsanız zamanla o kadar rahat olursunuz. Dışarıda rahat ve keyifli vakit geçirmek için gereken eşyaları yanınıza almayı unutmayın. Bunların en önemlisi elbette bebek bakımında sürekli gereken bez, alt açma örtüsü ve ıslak mendildir. Ayrıca bebeğin kusma ihtimaline karşı yedek önlük ve bir takım kıyafet almak çok işinize yarayabilir. O zaman tüm işlerinizi erteleyin ve bebeğinizle birlikte temiz havanın tadını çıkarın! 😊') WHERE id = '1dffb4b0-c92d-41f6-b1a5-adde26593736';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Sütünüzün besleyiciliğini ve miktarını artıran en önemli etken aldığınız su miktarıdır. Sütünüzün azalmaması ve devamlılığını sağlamak için günde en az 2-3 litre sıvı almalı ve her emzirmeden sonra kaybettiğiniz sıvıyı yerine koymalısınız. Ayrıca yeterince su içmek, hamilelikte aldığınız kiloları hızla vermek için çok etkili bir yöntemdir. Vücudunuzun ihtiyaç duyduğu tüm besin maddelerini yeterince almanız hem süt miktarını artıracak hem de fazla kilolardan kurtulmanıza yardımcı olacaktır. Günlük protein ihtiyacınızı karşılarken hem bitkisel hem de hayvansal protein kaynaklarından yararlanabilirsiniz. Ancak bebeğin gaz sorunlarını yoğun yaşadığı bir dönemde olduğunuz için tükettiğiniz besinlerin içeriğine dikkat etmenizde fayda var. Ayrıca unutmayın; bebeği ne kadar çok emzirirseniz sütünüz o kadar artar ve devamlılığı sağlanır.') WHERE id = '8b7bb2b5-f77d-4347-879b-67f02bacb220';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bu aşamada epey gelişen işitme duyusu sayesinde bebeğiniz sesinize ve sakinleştirici müziklere gülümseyerek tepki verebilir. Bununla birlikte, özellikle aniden gelen yüksek seslere karşı yüz ifadesini değiştirerek, bedenini gererek, kollarını yana açıp sonra göğsüne çekerek ve ağlayarak rahatsızlığını belli edebilir. Bebeğiniz henüz karnınızdayken kalp atışlarınızı, hem sizin hem de babasının sesini ve çevreden gelen çeşitli sesleri hissedip belleğine kaydetmeye başlar. Doğduktan sonra ise belleğinde sakladığı sesleri duymak onda sakinleştirici bir etki yaratabilir. Özellikle huzursuz olduğu saatlerde sakinleştirici müzikler açmanız ve ince bir ses tonuyla bebeğe yaklaşmanız onu rahatlatır. Ayrıca bu sakinleştirici etkiden yararlanmak için özellikle uykuya geçişte ninni söylemeniz, bebeğin bilişsel gelişimi açısından da faydalı olacaktır. Bu arada, bebeklerin tekrarlanan sözleri olan ninnileri daha çok sevdiğini de hatırlatmak isteriz. 😊') WHERE id = '187e9ca9-650d-40db-aa1f-2e28314ee7e9';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğinizde gaz sorunlarının ortaya çıkmasının birçok farklı nedeni olabilir. Bu nedenleri bilmeniz gaz sancılarıyla mücadelede size çok yardımcı olacak. Gaz sancılarının en bilinen nedenleri gereğinden sık ve düzensiz beslenmedir. Bağırsak florası henüz oluşum aşamasında olan bebeğiniz için beslenme düzeni kurmanız, bağırsaklardaki bakterilerin en uygun koşullarda çalışmasını sağlar. Bu da bebeğin gaz sancılarını daha hafif geçirmesine yardımcı olur. Bebeklerin midesinde ilk 6 ay yalnızca sütü sindiren enzimler salgılanır. Bu yüzden sadece anne sütü veya anne sütüne en yakın içerikli mamalar kullanmalısınız. Süt ve süt içerikli besinler dışında verilen şekerli su, pekmez, bal ve reçel gibi besinler bebeğin sindirim sistemini fazladan yormaktan başka bir işe yaramaz. Ayrıca kullanılan bazı ilaçların da gaz sancılarını artırıcı etkisi olabileceğinden, doktorunuzun önerisi olmadan ilaç kullanmaktan kaçınmalısınız.') WHERE id = 'a098a0a5-9cf9-4830-b539-70c7b71e29f4';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Günler ne kadar hızlı geçiyor, değil mi? Bebeğiniz artık o ilk yenidoğan hâlinden çıktı ve çevresini daha iyi algılamaya başladı. Bu aşamada dokunulmaktan, sevilmekten ve kucağa alınmaktan çok hoşlanır. Hamilelik boyunca bedeninizde yaşayan bebeğiniz için kucağınız muhtemelen en sevdiği yerdir. Özellikle korktuğunda ya da huzursuz olduğunda onu en hızlı sakinleştiren yer, kollarınızın arasındaki o güvenli limandır. Sizin veya babasının kucağında uyurken bedeninizin şeklini alıp kendine âdeta bir yuva kurar. Önümüzdeki 1-2 ay içinde ise özgürlük arayışına çıkacak ve kucağınıza sığmak yerine kendi alanını genişletmeye çalışacak. Bu yüzden bazen zor olsa da kucak kucağa geçirdiğiniz bu günlerin tadını çıkarmaya çalışın. :)') WHERE id = '3ff154d9-4a5e-4705-b55a-c139a97509b8';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Gündüzleri daha sık uyanan bebeğiniz, geceleri artık daha uzun süre uyumaya başlıyor. Bebeğin uyku düzenini sağlıklı şekilde oluşturmak ve kendi kendine uykuya dalmasına yardımcı olmak için, uykusu gelmiş bebeği henüz uyanıkken yavaşça beşiğine koymalısınız. Uykudaki bu olumlu değişiklikler, artık gece ile gündüzü ayırt edebilmesinden kaynaklanıyor. Bu alışkanlığı pekiştirmek için size birkaç önerimiz var. En önemlisi, gün boyunca bebeğin bulunduğu odayı aydınlık ve canlı tutmaktır. Akşam saatlerinde ise odaları ve bebeğin bulunduğu yerleri loş ışıkla aydınlatmalı, daha sakin davranmalı ve fısıltıyla konuşmalısınız. Bu küçük değişiklikler, bebeğin düzenli ve kaliteli uyumasını sağlayan en önemli etkenlerdir.') WHERE id = '854dcb61-ea42-4d37-9176-c3af87b58986';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Doğum sonrası lohusalık dönemi artık bittiği için yaşadığınız duygusal dalgalanmalar, kaygılar ve kendinizi yetersiz hissetme duygusu yavaş yavaş azalmaya başlamalıdır. Doğumun verdiği yorgunluk ve tükenmişlik hissi azalıyor, ailenize katılan bebeğe giderek daha çok alışıyorsunuz. Normal doğum yaptıysanız epizyotomi dikişlerinde veya tuvalet ihtiyacınızı giderirken hâlâ zaman zaman rahatsızlık hissedebilirsiniz; ama mesane ve bağırsak kontrolünüz epey iyileşti. Bununla birlikte, vajinal kuruluk ve hormonal değişikliklere bağlı cinsel isteksizlik bir süre daha devam edebilir. Hormonlarınız büyük ölçüde eski hâline dönse de, yeni anne olma psikolojisine ve değişen hayatınıza tam uyum sağlamak için hâlâ zamana ihtiyacınız var. Bu değişikliklerle baş etmekte zorlandığınızı düşünüyorsanız mutlaka doktorunuzdan destek isteyin.') WHERE id = '56bf65a1-60b7-4dfd-848c-0b69df37fbad';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Şimdi hem bebeğiniz hem de kendiniz için sağlığınıza dikkat etmeniz çok önemli. Enfeksiyonlarla savaşabilecek güçlü bir bağışıklık sistemine sahip olmanın temel şartı dengeli beslenmektir. Doğumdan sonra kalan kilolardan kurtulmak için kesinlikle şok diyetler yapmamalısınız. Doktorunuz, hamilelikte kullandığınız vitaminlere bir süre daha devam etmenizi isteyebilir. Vücudunuzun A, C, D ve E vitamini ihtiyaçlarını karşılamanın yanı sıra, sütünüzün kalitesi için çinko, omega ve demir gibi mineralleri de almalısınız. Bu ihtiyaçları karşılamak için meyve ve sebzeleri mevsiminde ve taze tüketmek çok önemlidir. Özellikle beslenme programınızda çinko ve selenyum açısından zengin besinlere yer vererek bağışıklık sisteminizi her mevsim güçlü tutabilirsiniz.') WHERE id = '8b8bfabb-ad49-47f5-ad53-ea528bf3b3c1';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin göz kasları henüz tam gelişmediği için gözlerindeki kayma bir süre daha devam edebilir. Bazen tek gözü, bazen de iki gözü birden dışa doğru kayabilir. Bir nesneyi izlemek istediğinde iki gözü birbirine paralel hareket etmeyebilir. Bu göz kaymalarına yalancı şaşılık denir. Yalancı şaşılık, göz kapaklarının fizyolojik olarak geniş olmasından da kaynaklanır. Bebeğin bu durumu, sanılanın aksine görme yeteneğini ve göz gelişimini etkilemez. Büyüdükçe burun kemiğinin şekillenmesi ve göz kapaklarının yerine oturmasıyla bu görünüm düzelir. Bazı bebekler ise yüz yapıları nedeniyle şaşı gibi görünür; oysa gözleri aynı yöndedir. Bu durum sizi endişelendiriyorsa emin olmak için bebeği bir çocuk göz doktoruna muayene ettirebilirsiniz.') WHERE id = 'f12655d4-4f11-4cf4-949d-d3c74399a9bf';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeklerde görülen besin alerjileri arasında en yaygını süt alerjisi, yani inek sütü alerjisidir. Bu durum, bebeğin organizmasının inek sütündeki beta-laktalbumin proteinlerine verdiği alerjik tepkiden kaynaklanır. Hazır mamaların çoğunun içeriğinde bu protein bulunduğu için mamayla beslenen bebeklerde buna sık rastlanır. Ancak bu sorun sadece mamayla sınırlı değildir; anne sütüyle beslenen bebeklerde de annenin süt ürünleri tüketmesi sonucu süt yoluyla bebeğe geçebilir. Ayrıca bu alerjisi olan bebeklerin çoğunda keçi sütüne ve soya içerikli sütlere karşı da hassasiyet gelişebilir. İnek sütü alerjisinin en belirgin işaretleri: ilk aylarda aşırı ağlama ve şiddetli gaz sancısı, beslenme sonrası kusma, kilo alamama, dışkıda kan pıhtıları ve kabızlıktır. Bebeğinizde bu belirtileri görüyor ve inek sütü alerjisinden şüpheleniyorsanız mutlaka doktorunuza danışmalısınız.') WHERE id = '06a7caf5-4128-4600-83b6-7c3d296c2485';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğinizde gaz sancısını önlemek veya bu ağrıları hafifletmek için bazı yöntemler vardır. Bebeği olabildiğince anne sütüyle beslemeniz, sindirim sistemi için en uygun besin olduğundan rahat bir sindirim süreci sağlar. Bu sayede bebeğin bağırsaklarında en az düzeyde gaz birikir ve gazı parçalayan bakteriler daha iyi çalışabilir. Emzirme aralığını en az 2 saat olacak şekilde ayarlamalısınız. Bu hem sütünüzün yağlanmasını sağlayarak bebeğin gelişimini destekler hem de alınan sütün daha rahat sindirilmesine yardımcı olur. Bebeği aşırı sıcak veya soğuk ortamlarda tutmamaya, dar kıyafetleri üst üste giydirmemeye çalışmalısınız. Bu durumlar bebeğin sindirim ve kan dolaşımı işlevlerini olumsuz etkileyerek bağırsaklarda gaz birikmesine yol açabilir. Ayrıca her beslenmeden sonra bebeğin gazını çıkararak midesinde hava kalmadığından emin olmalısınız.') WHERE id = '37fe650b-ff02-444b-9514-314d6f5df25d';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Uyku saatleri düzene girmeye başlayan bebeğiniz artık epey hareketlendi ve size tepkiler vermeye başladı. Sizinle birlikte babasına ve sık gördüğü insanlara karşı da onları tanıdığını gösteren hareketler yapabilir. Bunun en büyük nedenlerinden biri gözlerinin artık daha iyi görmesidir; bu sayede çevresini incelemeye ve gördüklerine tepki vermeye başlıyor. Bebeğin 2. ayını tamamlamasıyla birlikte, aldığı kiloya bağlı olarak yavaş yavaş yanakları, kolları ve bacakları dolgunlaşıyor. Kısacası artık yenidoğan bebek görünümünden çıktı. Yine de bilmelisiniz ki her sağlıklı bebek farklı boy ve kiloda gelişebilir. Uyku düzeninin oturması ve kaliteli uyku için artık geceleri onu zorla uyandırıp emzirmenize gerek yok. Bebeğiniz acıkmadığı sürece emzirmek ya da rahatsız olmadığı hâlde altını değiştirmek için onu uyandırmanız uyku kalitesini düşürebilir.') WHERE id = '6bb455df-6ea4-41c3-8194-cb7bda47e257';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeği doğru pozisyonda emzirmediğinizde sadece bebekte değil, sizin bedeninizde de bazı sorunlar ortaya çıkabilir. Bu sorunların en sık görüleni mastittir. Mastit; ateş, hâlsizlik, yorgunluk, göğüslerde ağrı ve kızarıklık gibi belirtileri olan, süt kanallarının tıkanmasından kaynaklanan bir sağlık sorunudur. Genellikle enfeksiyonla birlikte görülen bu durumda, süt kanalları tamamen dolduğunda boşaltılmazsa tıkanıklık oluşur. Böyle bir durumla karşılaşırsanız doktorunuzun önerisiyle emzirmeye uygun bir ağrı kesici kullanabilirsiniz. Aynı zamanda mastit oluşan göğsün, ağrıya rağmen boşaltılması son derece önemlidir. Mastit doğru tedaviyle kısa sürede geçer ve bebeğinizi sağlıklı şekilde emzirmeye devam edebilirsiniz. Ancak gerekli tedavi yapılmazsa göğüslerinizdeki tıkanıklık, vücudunuzun süt üretimini durdurmasına yol açabilir.') WHERE id = '68a7f9bc-02a4-47e7-80eb-cfc071e562a7';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğinizle birlikte iki ayı geride bıraktınız. 3. ayın geçen aylara göre daha rahat ve deneyimli geçeceğinden emin olabilirsiniz. Bebeğiniz dış dünyaya adım attığı ilk aylarında oldukça hızlı gelişir ve aylık kilosu 700 gram ile 1500 gram arasında artabilir. Başka bir deyişle, bebeğin haftada en az 150-200 gram kilo alması beklenir. Bu hesaplara göre bu haftanın sonu itibarıyla bebeğin ortalama kilosu 4 ile 6 kg aralığındadır. Bebeğin günde ortalama 5 kez bezini ıslatması, yeterince doyduğunu ve ek besine ihtiyacı olmadığını gösterir. Ayrıca boyunun her ay ortalama 1,5-2 cm uzadığı düşünülürse şu anda 57-62 cm aralığında olabilir. Tüm bunların ortalama değerler olduğunu ve her bebekte değişebileceğini unutmamalı, bu konudaki tek ölçütünüzün doktorunuzun görüşü olduğunu bilmelisiniz.') WHERE id = 'c4b87e12-4678-4aea-8944-a0c3b90a105f';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin el-göz koordinasyonu ve gelişimi için artık eldivenleri bir kenara bırakmanın zamanı geldi. Eldivenlerin uzun süre kullanımı bebeğin dış dünyayla kurduğu ilişkiyi ve gelişimini olumsuz etkileyebilir. Ellerini iyice keşfetmeye ve incelemeye başlayan bebeğiniz, verdiğiniz nesneyi tutup ağzına götürmeye başlayabilir. Ellerini yumruk yapan ve eline geçen her şeyi ağzına götürmeye çalışan bebek, bu yolla nesneleri tanımaya çalışır. Bebeğin bu deneyimleri zekâ gelişiminde çok önemli rol oynar. Zekâ büyük ölçüde bebeğin aktif hareketleri ve davranışlarıyla kazandığı deneyimlerle şekillenir. Eller, bebeğin çevresini keşfettiği, zihnini şekillendirecek bilgileri topladığı ilk araçlardır. Bu yüzden bebeği bu konuda cesaretlendirmeniz çok önemlidir. Dikkatini çekecek ve tutabileceği oyuncaklar, renkli kumaşlar ve ses çıkaran çıngırak gibi nesnelerle bebeğin gelişimine destek olmalısınız.') WHERE id = '42c11358-bbe1-48ad-b54d-e26f562016b7';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz ninniye, şarkıya, müziğe, hatta dışarıdan gelen seslere bile tepki verebilecek bir beyin gelişimine sahiptir. Beyin gelişiminin sağlıklı ve doğru ilerlemesi için günlük hayatınızda müziğe de yer vermelisiniz. Ayrıca bebeğe şarkı veya ninni söylemeniz aranızdaki bağın güçlenmesini de sağlayacak. Yapılan araştırmalara göre erken dönemde müzik dinletilen bebeklerde beyin ve dil gelişimi diğer bebeklere göre daha hızlı ilerliyor. Bu çocukların gelecekte müzik aletlerine ilgi gösterme olasılığının arttığı da gözlemlenmiş. Bebeğiniz henüz karnınızdayken sizi diğer insanların sesinden ayırt edebildiği için ona şarkılar ve ninniler söylemek hem birlikte kaliteli ve eğlenceli vakit geçirmenizi sağlar hem de kelime dağarcığının ve dil becerisinin oluşumunu hızlandırır. Özellikle zor uykuya dalan bir bebeğiniz varsa klasik veya sakin tempolu müzikler onu sakinleştirerek uykuya dalmasını kolaylaştıracaktır.') WHERE id = '161206e9-2801-48d5-bf23-ba2c2a393a9f';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz sebepsiz yere ağlıyor ve son günlerde huzursuzluğu daha da mı arttı? Bebeğin geçirdiği ikinci atak, yani gelişim sıçraması dönemine hoş geldiniz. 😊 8. hafta atağı, bittikten sonra bebeğin yeni beceriler kazanacağı eğlenceli bir dönemdir. Bu büyüme sıçramasında bebeğiniz bedenini daha iyi tanımaya, ellerini ve ayaklarını keşfetmeye başlayacak. Yani artık bebeğin ellerini ve parmaklarını emmeye çalıştığını, eline bir nesne verdiğinizde tutabilmek için parmaklarını rahatça kullandığını görebilirsiniz. 😊 Yenidoğan hâlinden sıyrılıp biraz daha hareketlenen bebeğiniz, kucağınızdan yere koyduğunuzda kendi kendini oyalamaya başlayabilir. Uzağı henüz net göremese de canlı renkli nesneler, figürlü oyuncaklar ve ışıklar dikkatini çekmeye başlar. Bebek için dış dünyada daha aktif bir dönem başladığından kısa süreli dikkat dağınıklığı yaşayabilir ve bunun sonucunda daha az emmek isteyebilir. Bu durumda bebeği daha sakin ve karanlık bir odada emzirmek ya da uykuya geçiş sırasında emzirmek onun için daha faydalı olabilir.') WHERE id = 'ba812bc8-8097-4c97-a28f-220a769e0dd9';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz artık size bilinçli ve gerçek sosyal gülümsemelerle karşılık vermeye başlıyor. Bu dönemde boyun kasları hızla geliştiği için her gün gözetim altında kısa yüzüstü egzersizleri yaptırmanız, omurgasının doğru şekillenmesi için çok önemlidir. Aynı zamanda algısı gelişen bebeğiniz artık renkli nesneleri gözüyle izleyebilir ve çıkardığı küçük seslerle sizinle ilk iletişim denemelerini yapabilir. Bu günlerde olabilecek 2 aylık rutin aşılarından sonra bebekte oluşan hafif huzursuzluğu ve iştahsızlığı ise onu sık sık emzirerek ve kucaklayarak yatıştırabilirsiniz.') WHERE id = '3c33ef6c-ad69-4a43-8495-e0ff0a641f32';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeklerin kel ya da saçlı doğması normaldir. Bebeğiniz saçlı doğduysa, özellikle bu dönemde hızla dökülmeye başlayan saç telleri sizi biraz endişelendirebilir. Bebeğinizdeki bu durum, ''telogen effluvium'' denilen, hormonal değişikliklere bağlı saç dökülmesidir. Hamilelik döneminde bebeğin saç kökleri sürekli uzama ve gelişme evresindedir. Doğumdan itibaren ise saç kökleri, hormonların da etkisiyle belirli bir süreliğine dinlenme evresine geçer. Hatta bazı bebeklerde kelliğe varan saç dökülmeleri olabilir. Özellikle bebeği sürekli aynı pozisyonda yatırıyorsanız, başının yastıkla temas ettiği bölgelerde bu kelliğin daha fazla olduğunu görebilirsiniz. Fizyolojik olan ve herhangi bir besin eksikliğiyle ilgisi olmayan bu saç dökülmeleri, bebeğiniz yaklaşık 6 aylık olduğunda azalmaya ve dökülen saçların yerine yenileri gelmeye başlar.') WHERE id = '902d6d84-5a76-4be3-852e-11ae4442029d';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bu günlerde bebeğinizde sürekli bir huzursuzluk hâli, kendini sakinleştirmek için sık sık emme isteği, hatta memeden ayrılmak istememe gibi durumlar gözlemleyebilirsiniz. Bu belirtiler bebeğinizdeki gaz sorunlarını gösterir. Fizyolojik olarak yaşanması normal olan bu durum bazı bebeklerde hafif geçerken bazılarında kolik sancılara yol açabilir. Özellikle 8. hafta sıçramasının tamamlanması ve beyin gelişiminin hızlanmasıyla bebeğin beyni, vücudundaki kas, eklem ve sinirleri algılamaya başlar. Bu algılama sürecinden önce bebeğin gaz çıkarması istemsiz ve rahat gerçekleşiyordu. Ama şimdi bebek bu kasları bilinçli olarak yönetmeye çalışıyor. Gaz çıkarmak için gereken kasların nasıl kasılıp gevşeyeceğini öğrenmesi için ona biraz zaman gerekiyor. Bebek ilk aylarda bu kasları tam yönetemediği ve sürekli gergin tuttuğu için gazını rahat çıkaramaz ve sonuçta gaz sancıları oluşur. Bu sıkıntılı anlarda bebeği rahatlatmalı ve bunun geçici bir dönem olduğunu kabul etmelisiniz. İlerleyen haftalarda beyin gelişimi arttıkça bebeğiniz bu kaslara hükmetmeyi öğrenecek ve gazını çok daha kolay çıkarabilecek.') WHERE id = 'f2315e81-cb4e-4e16-ad43-3687f3cbaef0';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz gün içinde çeşitli nedenlerle farklı şekillerde ağlayabilir. Peki ağlarken gözlerinden yaş gelmediğine hiç dikkat ettiniz mi? Bebeğin gözyaşı kanalları ve bezleri çalışsa da şimdilik yalnızca gözlerini koruyup nemli tutacak kadar gözyaşı üretebiliyor. Bebeğin gözyaşı bezleri doğumdan hemen sonra hızlı bir gelişim evresine girer ve ortalama 2-3 aylık olduğunda gözyaşı akıtacak kadar gelişir. Bazı durumlarda, bebeklerin yaklaşık %5-6''sında gözyaşı kanallarında tıkanıklık görülebilir. Bu tıkanıklık; gözlerde çapaklanma, sulanma, kirpiklerde yapışkanlık, iltihaplı akıntı ve göz çevresinde şişlikle kendini gösterebilir. Gözyaşı kanalı tıkanıklığının nedeni, gözyaşı kesesinin buruna açılan kısmındaki zarın açılmamasıdır. Bu durum tedavi edilmezse bebeğin gözleri mikroplara karşı savunmasız hâle gelir. Bu yüzden bebeğinizde bu belirtileri görüyorsanız vakit kaybetmeden bir göz doktoruna danışmalısınız.') WHERE id = 'e03b8fab-73de-4cff-bd15-34280044bd83';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğe emzik verip vermemek konusunda aklınızda bazı sorular olabilir. Bebeğiniz dünyaya güçlü bir emme refleksiyle gelir. Buna "oral dönem" denir ve yaklaşık 2 yaşına kadar sürer. Amerikan Pediatri Akademisi, ani bebek ölümü sendromunu önlediğine inandığı için 1 yaşına kadar emzik kullanımını önerir. Bu dönemde bebekte görülen güçlü emme refleksi, hem beslenme hem de duygusal ihtiyaçlarını karşılayan bir işlevdir. Emzik kullanımı; bebeğin fiziksel olarak emme ihtiyacını karşılaması, duygusal olarak kendini güvende hissetmesi, sakinleşmesi ve annenin göğsünün beslenme dışında kullanımını sınırlamak amacıyla tercih edilebilir. Bununla birlikte emzik kullanımı uzun vadede alışkanlığa dönüşebilir. Kullanım süresi sınırlanmazsa bebeğin beslenmesi etkilenebilir ve sonuçta gelişim geriliği oluşabilir. Ayrıca uzun süreli emzik kullanımı diş yapısının bozulmasına ve konuşmanın gecikmesine yol açabilir.') WHERE id = '9bf80a49-be8d-491a-9e0b-6671644690ad';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğinizi emziriyorsanız âdet döneminiz henüz başlamamış olabilir. Emziren anneler için âdet dönemi doğumdan yaklaşık altı-sekiz hafta sonra geri dönebileceği gibi, bu süre 24 aya kadar da uzayabilir. Âdet döneminin yeniden başlayacağı zaman her kadında farklı olabilir. Bunun nedeni, vücudunuzda süt üretimini ve salgılanmasını sağlayan prolaktin ve oksitosin hormonlarının varlığıdır. Kanınızda yüksek miktarda bulunan ve sütünüzün oluşmasını sağlayan prolaktin hormonu, yumurta hücrelerinin gelişimini sağlayacak üreme hormonlarının salgılanmasını baskılar. Yumurtalıklar yumurta hücresi olgunlaştırmadığı sürece ise âdet döneminden söz etmek mümkün değildir. Bu yüzden bebeğini kendi sütüyle besleyen anneler için âdet döneminin tam olarak ne zaman döneceği belirsizdir.') WHERE id = 'ed5d9752-70a1-4d4a-938d-22777462f998';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Özellikle emzirme döneminde ilaç kullanımıyla ilgili endişeleriniz olabilir. Hamilelikte olduğu gibi emzirme döneminde de vücudunuz bebeği korumak için çeşitli özelliklere sahiptir. Anne sütü, vücudunuzda bebeğin tüm ihtiyaçlarına uygun olarak hazırlanan mucizevi bir besindir. Fizyolojinizde, kanınızdaki bazı zararlı maddelerin süt kanallarına geçmesine izin vermeyen koruyucu sistemler vardır. Bu geçişe izin vermeyen fizyolojik özelliğe kan-süt bariyeri denir. Kullanılan ilaçların bazıları bu bariyeri geçebilse de bazıları bariyerden içeri giremez ve süte karışmaz. Doktorların bir kısmı emzirme döneminde ilaç kullanımına kesin bir tavırla yaklaşsa da bazı doktorlar fayda-zarar oranını hesaplar. Bu yüzden mutlaka doktorunuza danışmalı, kullanacağınız ilaçların içeriğini sorgulamalı ve ilacın emzirmeyle uyumlu olup olmadığını öğrenmelisiniz.') WHERE id = '23d4091f-e3fa-4f6e-82ab-2f668868b04f';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Ağlamak bebeğin en önemli iletişim aracıdır. Bebeğiniz gaz sancısı olduğunda, acıktığında, uykusu geldiğinde, üşüdüğünde, terlediğinde, kucak istediğinde ve daha birçok nedenle ağlayabilir. Bebeğin ihtiyacına göre ağlama tarzı da farklı olur. Muhtemelen artık gözlemleyerek bebeğin hangi ihtiyacı için ağladığını anlamaya başlamışsınızdır. Aç olduğu için ağlayan bebek, beslediğinizde susar. Beslenmenin bebeğin isteğine göre düzenlenmesi son derece önemlidir. Bebeğiniz uykuda irkilip uyanarak ağlayabilir. Bu durumda yarım kundak denilen yöntemle kollarını ince bir battaniyeyle çok sıkı olmayacak şekilde sarmak onu sakinleştirir. Bazı durumlarda tüm ihtiyaçlarını karşılamanıza rağmen kucağınıza alır almaz sakinleşip yere koyduğunuzda yeniden ağlaması, fiziksel temas arayışından kaynaklanır. 9 ay karnınızda yaşayan bebeğin doğumdan sonraki ilk aylarda bu fiziksel teması araması doğaldır. Bebeğin kucağa alışacağıyla ilgili endişe yaşamamalısınız. Bebeğin kendini güvende hissedeceği, kokunuzu ve sıcaklığınızı alacağı tek yer sizin kucağınızdır.') WHERE id = 'd2ed38a5-2867-473a-a048-a7488c8a0f81';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin ter bezleri henüz tam gelişmediği için vücut ısısını düzenlemek amacıyla terlemesi mümkün olmaz. Bu yüzden onu aşırı sıcak ortamda tutmaktan ve gereğinden fazla giydirmekten kaçınmalısınız. Bebeğiniz için yaklaşık 22-24 derece oda sıcaklığı yeterlidir. Evin içinde yelek, hırka, çorap üstüne patik gibi kat kat giydirmeye gerek yoktur. Body veya ince bir iç çamaşırı üzerine tulum giydirmeniz ve ayaklarına bir çift çorap giydirmeniz yeterli olacaktır. Ancak bebeğiniz erken doğduysa vücut ısısını tam koruyamadığı için bir kat fazla giydirilmesi gerekebilir. Kıyafetlerinin yeterli olup olmadığını anlamak için ensesine veya karnına dokunabilirsiniz. Bebeklerin genellikle el ve ayakları soğuk olur; bu yüzden üşüyüp üşümediğini anlamaya çalışırken sizi yanıltabilir. Bebeğin vücudunda temel ısı kaybı baştan olur. Bunu önlemek için evde çok kalın olmayan bir şapka takabilirsiniz. Ancak gece uyurken nefessiz kalmasına ve boğulmasına yol açabileceği için mutlaka şapkasız yatırmanız gerektiğini unutmayın.') WHERE id = '48c1b6b4-184f-478a-85ac-ef677c12d146';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin hâlâ en gelişmiş duyusu dokunmadır. Bu yüzden bebeğinizle sürekli ten teması içinde olmanız aranızdaki bağı güçlendirir. Bebeğin ilk aylarında büyük önem taşıyan dokunma duyusu, çevresiyle ilişki kurabilmesinde ve çevresini algılamasında ona yardımcı olan en önemli etkenlerden biridir. Bu açıdan bebeğe masaj yapmak, onu okşamak, ten tene temas sağlamak gibi etkinlikler, aranızdaki bağın gelişmesinde en etkili ve doğal yöntemler sayılır. Bebeğin çevresiyle iletişimi ona dokunulduğunda, okşandığında ve kucağa alındığında başlar; bu sayede psikososyal gelişimi de desteklenir. Halk arasında yaygın olan "alışır" korkusuyla bebeği kucağa almamak düşüncesi son derece yanlıştır ve anneyle bebek arasındaki ilişkiyi zedeler. Bebeğin dokunma duyusunu uyandırmak ve beden temasını sürdürmek hem güven duygusunun gelişmesini hem de süt üretimini artırarak emzirme başarısını destekler. Ayrıca araştırmalara göre fiziksel temas kurulan ve sık masaj yapılan bebeklerin, diğerlerine göre kilo alımının ve boy uzamasının daha fazla olduğu gözlemlenmiştir.') WHERE id = 'aa7f3500-7164-43a7-9fa5-208e7d522806';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeklerde kötü kokulu ishal, durmayan kusma ve ateşle kendini gösteren Rota virüsü enfeksiyonu, özellikle ilk aylarda bebeğiniz için oldukça tehlikeli olabilir. Yapı olarak yuvarlak biçimde olduğu için "rota" adını alan bu virüs, mide asidine dayanıklıdır. Mideden geçip ince bağırsağa ulaşan Rota virüsü buradaki hücreleri enfekte eder ve çoğalmaya başlar. Virüs saldırısına uğrayan bağışıklık sistemi ateşi 39°C''ye kadar yükseltebilir. Rota virüsü enfeksiyonunun belirtileri, virüs bulaştıktan sonraki 48 saat içinde başlar. Kendiliğinden geçen sulu ishal şeklinde olabileceği gibi, tehlikeli düzeyde ateş ve kusmanın eşlik ettiği, vücutta ciddi sıvı kaybı yaratan ishal şeklinde de görülebilir. Bu enfeksiyon ciddi sıvı kayıplarına yol açabildiğinden, özellikle bebeklerde hastane yatışı ve damar içi tedavi gerektirebilir. Rota virüsünden korunmak için yapılacak aşı bebeği %100 korumasa da hastalığı çok hafif geçirmesini sağladığı için yapılması çok önemlidir. Doktorların neredeyse tamamı bu aşıyı şiddetle önerir.') WHERE id = '1b640d9c-64b4-46e3-adef-12469bcc8075';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğinizde ara sıra görülen, ağız dolusu kusmalar sizi endişelendirebilir. Bu kusmalar genellikle ilk aylarda, beslenmeden kısa süre sonra olur. Doğumdan sonraki birkaç gün içinde başlayan kusma sorunu, mide ile yemek borusu arasındaki sfinkter (kapakçık) denilen bölümün henüz tam olgunlaşmamasından kaynaklanır. Bu kusmalar gelişime bağlı olarak 3-4 ay içinde bitebileceği gibi, bebeğiniz iki yaşına gelene kadar da sürebilir. Beslenme sırasında havayla karışan süt veya mama yemek borusundan yukarı çıkabilir; bu da kusma olasılığını artırır. Bebeğinizde buna benzer bir durumla karşılaşıyorsanız besleme şeklinizi gözden geçirmenizde fayda var. Emzirirken veya mamasını verirken bebeğin tamamen yatar pozisyonda olması, hava yutması, çok yavaş ya da hızlı emmesi gibi durumlar kusmanın şiddetini artırabilir. Bununla birlikte, bebeğin karnını doyurduktan sonra gazını çıkarmanız kusma durumlarını büyük ölçüde azaltacaktır.') WHERE id = '5fefb883-23f7-42f1-b985-be875f76a7d5';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin enfeksiyonlara karşı en güçlü savunması sizin sütünüz ve yaptırdığınız aşılardır. Doğduğu andan itibaren sütünüzden aldığı antikorlar sayesinde bağışıklık sisteminin temeli atılır ve hastalıklardan korunur. Ancak unutmayın; bu doğal koruma kısa süre sonra etkisini yitirir. Bu aşamada bebek aşılanmazsa mikrop ve virüslerle karşılaştığında vücudu onlarla savaşacak kadar güçlü olmayabilir. Dünyada her yıl aşıyla önlenebilir hastalıklar yüzünden milyonlarca insan hayatını kaybediyor. Bebeklik ve çocukluk dönemi hastalıklarının büyük bölümü tam da bulaşıcı hastalıklardır. Bunların bazıları ciddi salgınlara ve komplikasyonlara yol açabilir. Bu yüzden bebeğin aşı takvimine titizlikle uymanız, ömür boyu güçlü bir bağışıklığa sahip olması için çok önemlidir, sevgili anne.') WHERE id = '9a1ea20d-ced6-455d-9f64-c58e6cf75bea';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz dünyaya geldikten sonra, özellikle ilk bir yıl içinde inanılmaz bir hızla gelişir. Bazen sanki bir günde, hatta bir gecede büyüdüğünü hissedebilirsiniz. Ancak bu büyüme süreci çoğu zaman sessiz sedasız geçmez. Hızlı büyüme evresinin bazı fizyolojik etkileri olur. Bebeğinizde zaman zaman uyku sorunları, ağlama krizleri veya beslenme düzeninde bozulmalar görebilir; nedenini bulamadığınız durumlarla karşılaşabilirsiniz. Çoğu kişinin ebeveyn olana kadar habersiz olduğu ama neredeyse her bebekte görülen bu durumlara büyüme atakları (sıçramaları) denir. Her bebek gibi sizin yavrunuzda da yaşanan bu ataklar tamamen normal ve olması gereken bir süreçtir. Atak dönemlerinde bebeğiniz hem fiziksel olarak hızla gelişir hem de aynı zamanda dış dünyayla ilgili yeni keşifler yapar ya da yeni beceriler kazanır.') WHERE id = 'bf8343fd-c467-4ff0-b59e-adf0ca316a49';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin cildi büyüklere göre daha ince, son derece narin ve dış etkenlere karşı daha hassastır. Ayrıca yağ tabakası bizden daha az olduğu için soğuğa karşı da daha dayanıksızdır. Bu yüzden özellikle ilk aylarda onu giydirirken dikkatli olmalı ve kıyafetlerin içeriğine önem vermelisiniz. Bebeğin cildine doğrudan temas ettiği için pamuktan üretilmiş, yumuşak ve doğal kumaşları tercih etmelisiniz. Seçtiğiniz kıyafetler rahat hareket edebileceği kadar bol olmalı, kol ve bacak hareketlerini kısıtlamamalıdır. Kan dolaşımının bozulmaması için çorap seçiminde de yumuşak ve lastiği çok sıkmayan modelleri tercih etmelisiniz. Alışveriş yaparken kıyafetlerin kol, yaka ve bel kısımlarının sert olmamasına, ayrıca çıtçıt ve düğme gibi detayların kalitesine mutlaka dikkat etmenizi öneririz.') WHERE id = '03d19ce6-58a4-42e4-a4c9-562747272e51';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Renklerin bebeğin psikolojisi, enerjisi ve gelişimi üzerindeki etkisi bilimsel olarak kanıtlanmış bir gerçektir. Özellikle artık renkleri ayırt etmeye başlayan bebeğiniz, bu dönemden itibaren çevresindeki tonlara karşı daha duyarlı olur. Renklerin etkisi yalnızca ruh hâliyle sınırlı değildir. Odasında, kıyafetlerinde ve hatta oyuncaklarında kullanacağınız bazı renkler beynini aktifleştirir, uyku alışkanlıklarını etkiler ve hafızasını güçlendirir. Bu yüzden renklerin dilini bilmek çok önemlidir. Örneğin mavinin koyu tonları kasvetli bir görüntü yaratabilirken, açık tonları bebeğinizde sakinleştirici etki yapar ve sinir sistemini dinlendirir. Kiremit ve toprak tonları bebeğin kendini huzurlu hissetmesini sağlar; koyu kırmızı ise onda gerginlik yaratabilir. Genel olarak sıcak renkler bebeğiniz için enerjik bir ortam yaratırken, soğuk renkler daha çok sakinleştirici ve dinlendirici bir etkiye sahiptir.') WHERE id = '1a3eb5d8-5f3e-4a88-8c08-5b1025f3faf7';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Âdet döneminiz başladıysa sütünüzün miktarında ve bebeğin anne sütüne tepkisinde bazı değişiklikler hissedebilirsiniz. Bunun nedeni, vücudunuzda âdet döngüsünü düzenleyen hormonal değişikliklerin süt üretimini ve içeriğini bir miktar etkilemesidir. Ancak bu değişiklikler sizi emzirmekten alıkoymamalıdır. Âdet dönemine girmeniz bebeği sütten kesmeniz gerektiği anlamına gelmez; bu dönemde emzirmek tamamen güvenlidir. Özellikle yumurtlama günlerinde sütünüzdeki sodyum ve klorür miktarı artar, buna karşılık potasyum ve laktoz azalır. Bu da sütünüzün tadının biraz daha tuzlu ya da az tatlı olmasına yol açabilir. Ayrıca yumurtlama döneminde ve kanama başlamadan önce östrojen ve progesteron hormonlarının seviyesi değiştiğinden göğüslerde dolgunluk ve hassasiyet hissedebilirsiniz.') WHERE id = '94e7a1fa-9551-4f9b-be28-3651b7e35a86';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bu dönemde tüm dikkatiniz bebeğinizde olduğu için yeni bir hamilelik düşüncesi size korkutucu gelebilir. Emzirme döneminde doğurganlığınız azalsa da tamamen yok olmaz. Doğumdan sonraki ilk aylarda yumurtlama süreci, hamilelikte olduğu gibi bir süre durur. Ancak halk arasında yaygın olan "süt korur" düşüncesine tamamen güvenmek ve korunmamak doğru değildir. Bebeğiniz yalnızca anne sütüyle besleniyorsa âdet döneminiz 6-8 ay gecikebilir. Ama bebek mama alıyorsa doğumdan 3 hafta sonra yumurtlama ve âdet geri dönebilir. Unutmayın; âdet görmeseniz bile hamile kalma riskiniz %1-2 civarındadır ve ilk kanamadan önce de yumurtlama gerçekleşebilir. Bu yüzden yeni bir hamilelik planlamıyorsanız her cinsel ilişkide korunma yöntemleri kullanmanız önemlidir.') WHERE id = 'a67e120d-50f6-40f7-8148-f8a30d4ac88d';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin sırtını okşarken elinize gelen sertlik veya tüylenme sizi endişelendirebilir. Halk arasında "diken" olarak adlandırılsa da büyüklerdeki topuk dikeniyle karıştırılmamalıdır ve genellikle korkulacak bir şey değildir. Bebeklerde sık görülen ama çoğu zaman göze çarpmayan bu tüylenme, kız bebeklerde daha fazla gözlemlenir ve genellikle banyo sırasında fark edilir. Tıbbi açıdan zararı kanıtlanmamış olsa da bu durum sizi rahatsız ediyorsa ya da bebeğin rahatsız olduğunu düşünüyorsanız rahatlatmak için masaj yapabilirsiniz. Masaj sırasında bebeğin narin cildini tahriş etmeyen, kimyasal katkısız doğal yağlar kullanmalısınız. Bu yağlarla yapılan masaj hem bebeği rahatlatır hem de o tüylerin dökülmesine yardımcı olur. Önerilen yağlar ve bakım için doktorunuzdan da görüş alabilirsiniz.') WHERE id = 'd55543a0-5e2c-48fc-9829-ce7e9fdddd6c';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Her bebekte olduğu gibi, sizin de bebeğinizi giydirmeniz gerçek bir maceraya dönüşebilir. Miniğiniz yerinde durmadığı ve sürekli el kol hareketleri yaptığı için özellikle kış aylarında üstünü değiştirmek epey vaktinizi alabilir. Bu yüzden size zaman kazandıracak, giydirilmesi kolay pratik kıyafetler seçmenizde fayda var. Alışveriş yaparken bebeğin başının rahat geçeceği, geniş yakalı kıyafetleri tercih edin. Bebeğin cildi yetişkinlere göre çok hassas olduğu için mutlaka pamuklu ve alerjik olmayan ürünler seçmelisiniz. Güvenlik de çok önemlidir: bebeğin yutabileceği iri düğmelerden ve ucu kumaşla kaplanmamış sert fermuarlardan uzak durmalısınız. Bebekler merak edip bu düğmeleri koparıp ağızlarına götürebilir. Ayrıca fazla kurdeleler, fiyonklar ve danteller de bu dönem için pek uygun bir seçim değildir.') WHERE id = 'b8aa2eab-ff56-4ab9-8b20-121fbd2d3ec4';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Ülkemizde en sık görülen kansızlık türü demir eksikliği anemisidir. Demir, insan organizması için çok önemli bir elementtir. Özellikle büyümenin hızlı olduğu dönemlerde hücre ve dokuların demire ihtiyacı artar. Bu yüzden bebeklerin en hızlı büyüdüğü 6-24. aylar arasında demir eksikliğine sık rastlanır. Bebeğiniz 6 aylık olana kadar, anne sütü alıyorsa, kendi beslenmenize demir içeren gıdaları eklemeniz önemlidir. Mamayla beslenen bebeklerde ise mamanın içeriğindeki demir miktarına dikkat edilmelidir; bu konuda doktorunuzdan görüş alabilirsiniz. 6. aydan sonra anne sütü tek başına yeterli olmadığı için ek gıdaya geçerken demir açısından zengin bir menü hazırlamalısınız. Kahvaltılarda vereceğiniz yumurta sarısı demir bakımından çok zengindir. Ayrıca bebeğiniz için hazırladığınız sebze çorbalarına kuzu veya dana eti eklemeyi unutmayın.') WHERE id = 'd050305e-c358-4c29-9151-2db694755a43';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Her bebek için en doğru besin kendi annesinin sütüdür; çünkü bu süt tam da onun ihtiyaçlarına göre oluşur. Ancak bazen sağlık veya kişisel nedenlerle anneler emziremez. Böyle durumlarda en iyi alternatif, bebekler için özel hazırlanmış mamalardır. Bu karışımlar; inek veya keçi sütünün içeriğinin modern teknolojiyle değiştirilerek anne sütüne benzetilmesiyle elde edilir. Doğal inek sütü yapıca anne sütüne benzese de araştırmalar sindiriminin zor olduğunu ve içeriğinin bebekler için uygun olmadığını gösteriyor. Bu yüzden doktorlar 1 yaşından önce inek sütü verilmesini önermez. İlk bir yıl için tasarlanan mamaların piyasada inek sütü bazlı, soya bazlı veya proteini parçalanmış gibi çeşitli türleri vardır. İnek sütü bazlı mamalar bebeğin ihtiyaç duyduğu maddelerle zenginleştirilir; soya bazlı olanlar ise genellikle inek sütü proteinine alerjisi olan bebekler için önerilir.') WHERE id = '54371049-7cba-412e-931d-3ce67181ed5e';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz artık daha hareketli! 😊 Bunun en büyük nedenlerinden biri elbette gelişen kasları. 3 aylığa yaklaşan bebeğinizin artık daha aktif olduğunu şimdiden hissetmişsinizdir. Bu aşamada başını dik tutmaya başlayan ve yattığı yerden yaklaşık 45 dereceye kadar kalkabilen bebeğiniz hızlı bir gelişim dönemine adım attı. Hareketliliğin bir diğer nedeni ise çevreyi keşfetme isteğidir. Artık renkleri daha iyi ayırt ediyor ve gelişen görme yeteneğiyle ortamı tanımak istiyor. Keşif ayı olarak bilinen bu dönemde; ellerini incelemek, gösterdiğiniz nesneleri tutma isteği ve sizi izleyebilme gibi beceriler beklenir. Sizi ve babasını iyice ayırt etmeye başlayan bebeğiniz, sizinle kurduğu göz temasını da artırabilir. İşitme ve görme dikkati geliştiği için siz konuşurken sizi anlıyormuş gibi bakışlarını bu ay görebilirsiniz. Tüm bunların sonuçları da var elbette. Örneğin bebeğiniz çevreyi keşfetmeyi tercih ettiği için artık daha az uyuyabilir. Ayrıca bitmek bilmeyen mutluluk çığlıklarına da hazır olmalısınız! 😊') WHERE id = '5ea89e0c-0d1c-402a-8337-a40bace39e26';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Anne sütü muhteşem bir besindir. Bu mucizevi besin, bebeğiniz büyüdükçe onun ihtiyaçlarına yanıt verecek şekilde artar ve değişir. Süt üretimi için süt kanallarının oluşumu hamileliğin ilk anlarından itibaren başlar. İlk trimester boyunca gelişen süt bezleriniz, özellikle doğuma yakın günlerde sütle dolar ve bebeğin gelişine hazırlanır. Doğum gerçekleşene kadar sütün kanala inmemesi ve ek süt üretiminin durdurulması, plasentanın salgıladığı hormonlarla düzenlenir. Emzirme döneminde ise vücudunuzdan salgılanan oksitosin ve prolaktin hormonları sütün devamlılığını ve emzirme sürecini sağlar. Sütünüz, bebeğin ilk 6 ay ihtiyaç duyduğu protein, yağ, demir, vitamin gibi tüm besin değerlerini karşılar; 6 aydan sonra ise gelişimi için yavaş yavaş ek gıdaya geçmeniz gerekir. Bebeğin mide kapasitesi ve kalori ihtiyacı arttıkça sütünüzün miktarı ve içeriğindeki besin değerlerinin yoğunluğu da artar. Böylece bebeğiniz emzirme dönemi bitene kadar sütünüzden en üst düzeyde yararlanmış olur.') WHERE id = 'e67478e1-350c-4cf1-9917-9b4bd3ed801c';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Modern teknoloji ve tıbbi bilgiler sayesinde, yeni bir hamilelik düşünmeyen kadınlar için birçok farklı korunma yöntemi vardır. Bunlardan en çok tercih edilen doğum kontrol hapları, östrojen içerdikleri için, emziriyorsanız sütünüzün miktarını azaltabileceğinden önerilmez. Östrojen içermeyen haplar ise doğumdan 6 hafta sonra güvenle kullanılabilir. Üç aylık iğne olarak bilinen korunma yöntemi progesteron içerir ve emzirme dönemi için herhangi bir tehlikesi yoktur. Üç aylık iğneden farklı olarak aylık iğnelerde östrojen bulunduğu için emzirme döneminde kullanımı önerilmez. İmplant ise deri altına yerleştirilen, üç yıl koruyuculuğu olan ve hormon içeren bir yöntemdir. İmplantın içindeki hormon sütünüze geçse de bebeğinizi etkilemez. Doktorların en çok önerdiği yöntem ise koruyuculuğu oldukça yüksek olan ve spiral denilen rahim içi araçtır. Hormonlu ve hormonsuz seçenekleri olan spiral, doğumdan 6 hafta sonra takılabilir.') WHERE id = 'e001d0c5-46e0-40b1-82c7-a4a7f2a5f692';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz için kıyafet seçimi, her işte olduğu gibi incelikleri olan hassas bir konudur. Giyim konusundaki temel noktalardan biri güvenliktir. Bebeğin kıyafetlerinde güvenlik açısından düğmeli veya uzun ipli kıyafetler yerine çıtçıtlı ve sade olanları tercih etmeniz çok önemlidir. Ayrıca seçim yaparken, vücutta toksik madde olarak birikebilecek ve kanserojen etki yaratabilecek boya bırakmayan kaliteli ürünler kullanmalısınız. Bebeğin vücudu, ona zarar verebilecek her tür maddeye karşı savunma mekanizması geliştirir. Alerjiler de tam olarak bu savunma mekanizmasının çalışması sonucu ortaya çıkar. Kıyafetlerde kullanılan boya maddelerinin bebeğinizde alerji yaratma olasılığı olduğundan standart sertifikalı ürünleri tercih etmelisiniz. Bu belgeye sahip ürünler, bebeğin vücuduna zarar verme potansiyeli olan şüpheli maddelerin analizlerini içerir ve güvenlik normları çerçevesinde üretilir. Bu yüzden bu standartlara uyan kıyafetleri gönül rahatlığıyla bebeğinize giydirebilirsiniz.') WHERE id = '8bcfa34a-ab3b-47cd-8082-d8d412e4c0f8';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğinizle birlikte geçirdiğiniz 3. ayınız! Bebeğinizle yeni bir döneme adım attığınız bu ayda, sizi çok mutlu edecek sürprizlerle karşılaşmaya hazır olmalısınız. Bebeğiniz artık eline verdiğiniz nesneleri kısa süreliğine de olsa tutabilecek kadar gelişmiş motor becerilere sahip. Üstelik bu artık bir refleks değil, iradeli bir davranışa dönüşüyor. Ellerindeki tutma refleksinin kaybolmaya başlamasıyla birlikte, bebeğin ayaklarındaki tutma refleksi için henüz birkaç aya ihtiyaç var. Refleksten bilinçli davranışa geçişte karşılaşacağınız bir diğer nokta ise bebeğin beslenmesiyle ilgilidir. Yenidoğan refleksi olan, bebeğin yanaklarına dokunulduğunda ağzını açma hareketi, bu ayla birlikte yavaş yavaş iradeli davranışa dönüşmeye başlar. Yani bebeğin karnı aç değilse artık ağzını açmayacak. Bu davranış değişiklikleri elbette bebeğin hızla gelişen beyni sayesinde gerçekleşiyor.') WHERE id = '327fd5ec-447f-4d93-a81c-c3fdb4d5f652';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin bu ayki rutin muayenelerinde doktorunuz bazı gelişim göstergelerini kontrol edecek. Bunların ilki ve en önemlisi bebeğin başını tutabilmesidir. Çünkü 3. ayını tamamlamış bebekler bu dönemde başlarını rahatça yönetmeli, dik tutmalı ve 45 dereceye kadar kaldırabilmelidir. Bıngıldağın ise henüz sertleşmemiş ve kapanmamış olması gerekir. Bu açıklık, bebeğin beyin gelişiminin etkili şekilde sürmesi için son derece önemlidir. Beyin gelişiminin bir diğer göstergesi baş çevresidir. Bu aydan itibaren bebeğin baş çevresi ortalama 37-43 cm aralığında olmalıdır. Doktorun düzenli izleyeceği diğer ölçüler ise boy ve kilodur. Bebeğin kilosu bu ay 4200-7500 gram, boyu ise 55-65 cm aralığında değişebilir. Unutmayın; bu rakamlar ortalama değerlerdir ve her bebekte farklılık gösterebilir. Alt ve üst sınırlar içinde kaldığı sürece bebeğin gelişimi için endişelenmeye gerek yoktur.') WHERE id = '76c150ee-bf0f-46cc-b728-a8452683e29c';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin üçüncü sıçraması, yani büyüme dönemi bu günlerde başlamış olmalı. Bu yüzden huzursuzluk, uyku bozuklukları ve iştah değişiklikleri yaşarsanız sakın telaşlanmayın. Üçüncü sıçrama dönemi, bebeğin doğduğu tarihle doğması gereken tarih arasında farklar olsa da ortalama 12. hafta civarında gerçekleşir. Bu sıçramadan sonra bebeğiniz artık seslere daha çok ilgi göstermeye başlar ve hassaslaşan işitme yeteneği sayesinde ses tonundaki değişiklikleri bile fark edebilir. Ayrıca bebeğin beyin sapında işitmeden sorumlu hücreler, gelen seslerin hangi yönden geldiğini belirleyip buna tepki verecek şekilde çalışmaya başlar. Bu, bebeğin artık sesin geldiği tarafı ayırt edebileceği ve o yöne dönebileceği anlamına gelir. Bu dönemde yaşanan bir diğer değişiklik ise bebeğin kendi sesini keşfetmeye başlamasıdır. Kendi sesini tanıyan bebeğiniz farklı biçim ve şiddette sesler çıkararak sizi şaşırtabilir. İyi eğlenceler! 😊') WHERE id = '7157ab6b-c70f-4177-b181-d8ea3a2d459e';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğinizi mamayla besliyorsanız veya sütünüz yetmediği için ek besin kullanıyorsanız, en önemli konulardan biri biberon seçimidir. Biberon seçimi, bebeğin sağlığı için asla ihmal edilmemesi gereken bir konudur. Doğru biberonlar hem bebeğin beslenmesinde büyük rol oynar hem de kullanımı rahat olduğu için işinizi epey kolaylaştırır. Seçim yaparken bebeğin ağzını tıpkı emzirme sırasındaki gibi geniş açarak beslenmesini sağlayacak modelleri tercih etmelisiniz. Ayrıca seçtiğiniz biberonun sindirim sistemini yormadığı ve kolik gaz sancılarını azalttığı klinik olarak kanıtlanmış olmalıdır. Biberonun malzemesi, boyutu, şekli, anti-kolik özelliği, emziğinin biçimi ve delik sayısı dikkat etmeniz gereken noktalardandır. Bu aşamada bebeğiniz için 240-260 ml hacimli, orta akış hızına sahip ve hava alma özelliği olan emzikli biberonları seçmeniz önerilir.') WHERE id = '20a065b0-2b51-4884-b57e-e72acfd3836c';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin büyüme ve gelişme hızı yaşına göre farklılık gösterir. Bazı dönemlerde daha yavaş büyüse de özellikle sıçrama, yani hızlı gelişim dönemine girdiğinde büyüme hızı artar. Büyüme hızının yavaşladığı zamanlarda bebekte iştah azalması bilimsel olarak normal kabul edilir. Bebek hayatının ilk yılında oldukça hızlı büyür; bu yüzden müdahale gerektirecek ciddi bir iştahsızlık sorunu genellikle yaşanmaz. Yine de diş çıkarma ve çevreyi keşfetmeye başladığı dönemlerde kısa süreli iştah kaybıyla karşılaşabilirsiniz. Neredeyse her bebek için diş çıkarma süreci zorlu bir dönemdir. Bu sırada keyifsiz olan ve fiziksel ağrı hisseden bebeğin beslenmesinin düzensizleşmesi ve azalması normaldir. Ancak burada dikkat etmeniz gereken nokta, az yemeyi iştahsızlıkla karıştırmamanızdır. Yeni anne olmuş bir kadın için bu durum endişe yaratsa da aslında telaşa gerek yoktur. Ayrıca ek gıdaya erken başlayan bebeklerde sindirim sisteminin hazır olmamasından kaynaklanan alerjik reaksiyonlar da iştahsızlığa yol açabilir.') WHERE id = '87f56862-dda9-454a-a541-34481c8ca235';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğinizle birlikte pek çok farklı etkinlik yapabilirsiniz. Artık çevresiyle aktif iletişim kurmaya başlayan bebeğinizle ilgilenmek, onun geleceği için yapabileceğiniz en güzel yatırımdır. Koku duyusu son derece keskin olan bebeğinize, beyin hücrelerinin daha etkili çalışması için birbirinden farklı kokular koklatabilirsiniz. Bebeğin konuşma gelişimi için onunla sık sık konuşmanız ve iletişimde olmanız gerekir. Mümkün olduğunca farklı kelimeler duymasını sağlamak önemlidir. Bebeğinizle sürekli konuşun, ona sık sık adıyla seslenerek ismini tanımasına yardımcı olun, ona dokunun ve öpün. Sevildiğini ve ilgi odağı olduğunu hisseden bebek hem fiziksel hem de ruhsal açıdan daha sağlıklı büyüyecektir. Bebeğinizle kendinizi eve kapatıp yalnızca fizyolojik ihtiyaçlarını karşılamak yerine, ona yeni deneyimler için fırsatlar yaratmalısınız. Dışarı çıkın ve açık havada güneşi hissetmesini sağlayın. Dışarı çıkamadığınız zamanlarda ise birlikte balkondan veya pencereden dışarıyı izleyebilirsiniz. Buradaki temel amaç; bebeğin hareketlerle algısını açmak, duyu organlarını aktif kullanmasını sağlamak ve hafızasını çalıştırmaktır.') WHERE id = 'd229dd79-f389-4db8-9b5a-34c760b0f5c0';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin altını değiştirirken cildinde pullanma, kızarıklık ve iltihap görürseniz miniğiniz mantar enfeksiyonu kapmış olabilir. Bu reaksiyonlara yol açan mantarlar, nemli ortamda hızla çoğalan mikroskobik organizmalardır. Çoğalmaları için sıcaklık ve nem gerekir. Uygun koşulları bulur bulmaz kolayca yayılırlar. Bebeğin genital bölgesi gibi suyla temas edip nemli kalan yerlerde mantar oluşma olasılığı yüksektir. Bu yüzden bebeğin altını temizledikten sonra nemli bırakmamalı, iyice kurulamalısınız. Bebeğin cildindeki mantarı ve pişiği birbirinden ayırmak için doktor muayenesi önemlidir. Gözlem açısından, mantar olan bölgelerde ciltte pullanma görülür. Pişiği olan bebeklerde, özellikle doktor kontrolü olmadan antibiyotik kullanıldığında mantar oluşma riski çok yüksektir. Bu nedenle bebeğin cildinde oluşan pişiklere karşı dikkatli ve özenli yaklaşmalısınız.') WHERE id = 'b63be385-2a69-41af-ad23-38c2f405d961';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğinizde beslenme sonrası kusma durumuyla karşılaşmanız fizyolojik olarak çoğu zaman normal kabul edilir. Yine de gözlem yapmanız önemlidir. Bebeğiniz özellikle ilk aylarda, beslendikten kısa süre sonra hiçbir zorlanma olmadan ağız dolusu kusabilir. Bu durum büyüdükçe azalır ve genellikle sekiz aylık olduğunda beslenme sonrası kusmalar ortadan kalkar. Bebeğin beslenme sırasında hava yutması, çok hızlı veya çok yavaş emmesi, beslendikten sonra gazının çıkarılmaması kusmaya yol açabilir. Beslenme tekniğindeki bu hatalar düzeltilirse bebeğinizdeki bu kusmalar da duracaktır. Kusma genellikle yemekten sonra olur; çünkü yemek borusunun alt kısmında yer alan ve mide içeriğinin geri dönmesini engelleyen kas fizyolojik olarak henüz tam gelişmemiştir. Kusmalar doğumdan itibaren görülebilse de yaklaşık 4. ay civarında sıklığı artar ve neredeyse her 4 bebekten 3''ünü etkiler. 6. aydan sonra genellikle azalan bu kusmalar, katı gıdalara geçişle birlikte tamamen kaybolur.') WHERE id = '94ce13b4-bc4e-480c-a364-11de1e4c0330';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğinizde oluşan gaz sancısı sorunlarının iki temel nedeni vardır. Bunlardan biri, bebeğin midesindeki faydalı bakterilerin anne sütü veya mamadaki sindirilmemiş besin maddelerini parçalarken ortaya çıkardıkları gazdır. Diğer neden ise bebeğin ağlarken, yutkunurken, emerken veya biberonla beslenirken yuttuğu havadır. Ayrıca bebeğinizi emziriyorsanız, sizin sindirim sisteminizde gaza yol açabilecek besinlerle beslenmeniz de bebeğinizde gaz sorununa neden olabilir. Bu yüzden beslenmenizde bu tür gıdaları azaltmanız faydalı olur. Bebeğinizdeki gaz sancılarına karşı alabileceğiniz birçok önlem var. Bunlardan biri, bebeğin aşırı acıkmasını beklememektir. İhtiyacından fazla acıkan bebekler sütü hızlıca içecekleri için epey hava yutarlar. Bebeğinizi biberonla besliyorsanız, biberonun ucundaki deliklerin çok küçük veya çok büyük olmamasına dikkat ederek gaz şikâyetini en aza indirebilirsiniz.') WHERE id = '14cce317-1232-45b9-96bd-2281d87ef8be';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin beslenmesinde yapacağınız birkaç değişiklik reflüsünü önleyecek ve ileride sorun yaşama riskini en aza indirecektir. Bunların en önemlisi beslenme sıklığı ve düzenidir. Bebeği beslerken olabildiğince dik pozisyonda olmasını sağlamalısınız. Daha sık ama az miktarda beslenme programı kurmanız bebeğin reflüsünü azaltır ve sindirim sürecinin rahat geçmesini sağlar. Öğün aralarında ve beslenmeden sonra bebeği hoplatmak veya yuvarlamak gibi sarsıcı hareketlerden kaçınmalı; aksine her beslenmeden sonra onu yaklaşık 20 dakika dik tutmalısınız. Ayrıca bebeğin altını değiştirirken bezinin çok sıkı olmamasına dikkat etmelisiniz. Bezin çok sıkı bağlanması bebeğin karnındaki basıncı artırarak kusmalara yol açabilir. Bebeğiniz uyurken başını biraz yüksekte tutmak için ince bir yastık kullanmanız gaz çıkışını rahatlatır ve olası boğulmaların önüne geçer. Bebeğin sigara dumanı solumak zorunda kalması, diğer zararlı etkilerinin yanı sıra reflüye de yol açtığı için kaçınmanız gereken bir diğer önemli konudur.') WHERE id = '4db7b0e8-8a13-4223-9f1c-396106b58bfc';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz büyürken en çok gelişmesini istediğiniz özelliği elbette zekâsı ve beyin gelişimidir. Bu gelişimi sağlamanın son derece etkili yollarından biri de ona kitap okumanızdır. Bu aşamada bebeği kitaplarla tanıştırmak ve sevdirmek; okul çağına geldiğinde akademik başarılarına, temel konuşma becerilerine, dil bilgisi ve muhakeme yeteneklerine zemin hazırlayacaktır. Ayrıca okul çağından önce kitaplarla ilgilenen çocukların akademik başarılarının daha yüksek olduğu bilimsel olarak kanıtlanmış bir gerçektir. Siz bebeğinize kitap okurken o, konuşma için gerekli temel sesleri sizden öğrendiği için konuşma becerilerinin temelini atmış olursunuz. Üstelik aktif iletişimde olduğunuzda bebeğiniz sizinle kurduğu bağ sayesinde doğru iletişim yollarını okul döneminden çok daha önce öğrenecektir. Kitaplardan doğru cümle yapılarını düzenli ve sürekli duydukça, bebeğin konuşma döneminde dil bilgisi kurallarına yatkınlığı da okul öncesi dönemden itibaren gelişecektir. Bu yüzden o kendi başına okumaya başlamadan önce sizin ona şimdiden kitap okumanız son derece önemlidir.') WHERE id = '847c3222-1e8f-4ee7-af36-660c53f7b72c';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz gözünüzün önünde inanılmaz bir hızla büyüyor. Her gün yeni beceriler öğreniyor ve bunları size gösteriyor. 😊 Yeni beceriler kazanmasına, yaratıcılığını ve beyin gelişimini desteklemek için alacağınız oyuncakların büyük önemi var. Bu dönemde çevresine ilgisi artan bebeğiniz için yeni ve farklı oyuncaklar alabilir ya da mevcut oyuncaklarla farklı oynama yolları düşünebilirsiniz. Oyuncak seçerken yaşına uygun olup olmadığına ve kişilik özelliklerine nasıl etki edeceğine dikkat etmelisiniz. Bilimsel araştırmalar, bebeklerin oynadığı oyuncakların gelişimlerinde büyük rol oynadığını gösteriyor. Okul öncesi döneme kadar oynadığı her oyuncak, dünyayla bağ kurması ve kişilik gelişimi için önemlidir. Bu yüzden oyuncak seçerken tüm duyularına hitap etmesine, motor becerilerini geliştirmesine, hayal gücünü artırmasına ve sosyal becerilerini desteklemesine dikkat etmelisiniz.') WHERE id = '86e946c1-ab86-4301-9ac4-7f795adc1bfa';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz gelişmiş duyu organlarına ve işlenmeyi bekleyen milyonlarca beyin hücresine sahip olduğu için doğduğu andan itibaren her bilgiyi kaydetmeye başlar. Dünyaya geldiğinde yalnızca hayatta kalmasına yardımcı olan birkaç reflekse sahip olan bebeğiniz, kısa sürede emeklemek, konuşmak ve yürümek gibi birçok beceri kazanacak. Araştırmalara göre bebeğin bu mucizevi becerileri hızla öğrenmesinin temel nedenlerinden biri de gündüz uykularıdır. Gündüz uykuları bebeğin dinlenmesine ve yeni şeyler öğrenmesine imkân tanır; aynı zamanda yaşadıklarını hafızasına kazımasına yardımcı olur. Uyku saatlerinin düzenli olması; yürüme, konuşma gibi önemli becerileri zamanında kazanmasını sağlar. Zamanla uyku süresi azalır ve çevreyi keşfetmeye başlayan bebek bazen uykuya direnebilir. Bu aylarda bebeğiniz alışkanlıkları kolayca kazanabilir; bu yüzden uyku düzenini şimdiden oturtmanızı öneririz. 😊') WHERE id = '12adf52f-ce6e-45aa-88f8-a01f2005b356';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz saatlerce ellerini baş hizasında kaldırıp hayranlıkla mı izliyor? Sanki "Evet!" dediğinizi duyuyoruz. 😊 Bu haftalarda neredeyse her anne, bebeğinin ellerini keşfetmek için izlediğini ve ağzına götürdüğünü gözlemliyor. Bebeğin gelişim aşamalarında bu davranışı sergilemesi tamamen normaldir ve buna engel olmamalısınız. Bırakın ellerini istediği kadar ağzına götürsün. 😊 El ve parmaklarına ilgisi artan bebek, özellikle sırtüstü yatarken ellerini kaldırıp oynatarak onlara bakar. Hatta ellerini hızla hareket ettirerek gözleri ve başıyla kendi hareketlerini izleyebilir. Bebeğiniz bu aşamaları geçtikçe ellerini işlevsel bir araç olarak yönetmeyi öğrenecek ve çevresindeki nesneleri keşfetmek için onları kullanacak. Dikkat etmeniz gereken tek şey, ellerinin temizliğinden emin olmak ve ağzının içini yaralamaması için tırnaklarının uzunluğunu ayarlamaktır. Keyifli keşifler! 😊') WHERE id = 'caffa322-fe7d-4bfd-9362-04360cd00a6c';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, '3. ayındaki bebeğinizin beyninde artık anılar ve deneyimler yer etmeye başladı. İlk aşamada bunlar sürekli tekrarlanan hareketlerle şekillenir. Bebeğiniz daha önce gördüğü insanları, nesneleri ve ifadeleri hatırlamaya ve ayırt etmeye başladığı için ağladığında dikkat çekeceğini biliyor. Bu ayın en güzel gelişmelerinden biri ise siz gülümsediğinizde onun da gülerek karşılık vereceğini öğrenmesidir. Gülüşlere hazır olun. 😊 Aslında bu hafıza oluşumu, bebeğiniz henüz karnınızdayken başlar. İşitme duyusu geliştiği andan itibaren sesleri alıp hafızasına kaydeden bebek, bu sayede doğduğunda sesinizi diğerlerinden kolayca ayırt edebilir. Şimdi ise hızla gelişen beyni sayesinde hafızasında tuttuğu bilgileri anlamlandırıp tepki verebiliyor. Örneğin 3 aylık bir bebek, annesinin gösterdiği bir nesnenin görüntüsünü 7 güne kadar hafızasında tutabilir ve yeniden gösterildiğinde onu tanıdığını belli eden bir tepki verebilir.') WHERE id = 'a7c25396-4991-4496-8a65-64211f7dd866';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz hızla gelişen sinir sistemi ve duyu organları sayesinde çevresiyle daha çok iletişim kurmaya başladı. Bu yüzden yerinde durmak istememesi, yalnız kaldığında ağlaması ve sürekli kucakta gezmek istemesi normaldir. Zaman zaman sizi yorabilecek bu durumu elinizden geldiğince anlayışla karşılamalı ve bebeğin çevreyi keşfetmesine yardımcı olmalısınız. Bebeği gezdirirken onu farklı şekillerde tutmanız kaslarını geliştirir ve bu ona çok iyi gelir. Ayrıca bu sayede sizinle ve çevresiyle sağlıklı bir sosyalleşme dönemi geçirecek. Bebeğin bu ay içinde uykusu, oyunu ve beslenmesi gibi etkinlikleri artık belli bir düzene oturdu. Bu yüzden 3. ay hem sizin hem de bebeğiniz için bir dönüm noktası sayılır. Bebeğinizle oyunlar oynamaya, onunla vakit geçirmeye ve sık sık gülümsemeye devam etmelisiniz. Onunla geçireceğiniz kaliteli zaman, onunla ilgilendiğinizi gösterir ve sağlıklı ruhsal gelişimi için son derece önemlidir.') WHERE id = 'c7c7ac0c-0d6e-4513-8d30-65a89768a3af';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğinizin kaka sayısının azaldığını muhtemelen bir süredir fark ediyorsunuz. Bebeklerde dışkılama alışkanlıkları çok değişken olabilir ve bunların çoğu normal kabul edilir. Bebeğiniz yalnızca anne sütüyle besleniyorsa haftada bir kez kaka yapması normal sayıldığı gibi, günde 5-6 kez yapması da tamamen normaldir. Anne sütü alan bebeğin kakası genellikle sarı renkli, sulu ve hafif tanelidir. Bebeğiniz mamayla besleniyorsa, kabız olmadığı sürece 3-4 günde bir ya da günde 5 keze kadar yumuşak kıvamlı kaka yapması da normaldir. Mama alan bebeğin kakası hem sarı hem de yeşil renkte olabilir. Beslenme tarzının yanı sıra kullandığınız mamanın markasını değiştirdiğinizde ya da antibiyotik kullanımında kaka sayısında bazı değişiklikler olabilir. Burada dikkat etmeniz gereken asıl nokta kakanın kıvamıdır. Kaka sert, kuru ve parça parçaysa bebeğiniz büyük olasılıkla kabız olmuştur. Bebeğin bu durumdan rahatsız ve huzursuz olduğunu hissederseniz en kısa sürede doktorunuzla iletişime geçmeniz uygun olur.') WHERE id = '0aa04f59-8956-4168-94d6-7cbf1b5d04b5';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bu aşamada bebeğin el-göz koordinasyonu epey gelişti. Tutma becerisi sayesinde oyuncakları ve nesneleri eliyle kavrayabildiğini keşfeden bebek, dikkatini bu hareketlerin üzerinde toplamaya başlayacak. Örneğin tuttuğu çıngırağı artık kendisi istemedikçe kolay kolay bırakmaz. Hatta ses çıkardığını anlarsa onu sallamayı da deneyebilir. Bu tür davranışlar, sebep-sonuç ilişkisi kurma açısından bebeğin zihinsel gelişiminde attığı ilk adımlardandır. Bebeğin kurduğu tüm bu bağlantılar yakında daha işlevsel hâle gelecek ve tuttuğu nesneleri ağzına götürme isteği başlayacak. "Oral dönem" denilen bu aşamada, bebeğin ilk reflekslerinden biri olan emme refleksiyle, merak ettiği ve keşfetmek istediği her şeyi ağzına götürmesi gözlemlenir. Bu dönem bebeğin bir yaşına kadar olan süreyi kapsar. Bu zaman diliminde bebek dış dünyayla bağını tüm beden yüzeyiyle, özellikle de ağız yoluyla kurar. Bu yüzden bebeğin yutabileceği her tür küçük nesneyi ortadan kaldırmalı ve onu uzun süre yalnız bırakmamalısınız.') WHERE id = '60021b19-b43c-4324-8e67-4e9b5d399b4d';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Emzirme veya biberonla beslenme sırasında bebeğiniz kendini geri çekip ağlıyorsa büyük olasılıkla meme reddi ya da beslenme reddi yaşıyorsunuz. Bu durumda bebek aç olsa bile çeşitli nedenlerle emmek istemeyebilir. Bunun en sık görülen nedenlerinden biri burun tıkanıklığıdır. Burun tıkanıklığı yüzünden bebek ağzından nefes almaya çalıştığı için aç olsa bile memeyi sık sık bırakabilir ya da reddedebilir. Bebeğin burnu tıkalıysa emzirmeden önce aspiratörle burnunu temizlemeli ya da doktorun önerdiği burun damlasıyla rahat nefes almasını sağlamalısınız. Ayrıca bebeğin alıştığı düzenin bozulması ve emzirme saatlerinde yapılan değişiklikler huzursuzlanmasına ve emmeye tepki göstermesine yol açabilir. Yanlış emzirme tekniği kullanmanız da memeyi kavramasını zorlaştırabilir. Doğru emzirme teknikleri hakkında bilgi alıp bebeğin memeyi rahat kavrayabileceği farklı pozisyonlar deneyerek yeniden emmesini sağlayabilirsiniz.') WHERE id = '923618b2-185f-4d48-8595-207ec8b1f1d7';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeklerin saç köklerinin gelişimi henüz anne karnında, yaklaşık ilk trimesterde başlar. Doğacağı güne kadar lanugo denilen tüyler, ısı kaybını önlemek için bebeğin baş bölgesinde yoğunlaşır. Bu tüylerin yoğunluğu ve uzama süresi genetik etkenlere göre değişebildiği için bebeklerin doğumda gür saçlı, seyrek saçlı ya da saçsız olması tamamen normaldir. Aslında bebeğin az ya da gür saçla doğması herhangi bir sağlık sorununun göstergesi değildir. Bebeğin saçları özellikle bu aylarda yoğun şekilde dökülebilir. Hatta başının arka, ense kısmında bir miktar açılma da görülebilir. Bu açılmanın nedeni bebeğin sürekli aynı pozisyonda yatması olabileceği gibi, doğumdan itibaren 6. aya kadar dinlenme evresine geçen saç kökleriyle de ilgili olabilir. Bebeğin saçlarını kesmeye kıyamasanız da uzmanlar, zamanı geldiğinde, ister gür ister seyrek olsun, bebeklerin saçlarının kesilmesini öneriyor.') WHERE id = '1a637264-ed95-4fa6-842a-a26e3ce3729a';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin beyni henüz siz hamileyken durmaksızın gelişir. Bu gelişim doğumdan itibaren daha da hızlanarak sürer. Beyin gelişiminin en hızlı olduğu dönem ise 0-48 ay aralığıdır. Bebeğiniz bu dönemde çevresindeki dünyayı kavrayabilmek için deneyimlere ihtiyaç duyar ve bu deneyimler aracılığıyla öğrenir. Bu deneyimlerin en önemli parçalarından biri de bebeğin ilgisini çeken ve gelişimini destekleyen oyuncaklardır. Renkli, farklı biçimli ve ilginç oyuncaklar, beynindeki nöronları harekete geçirip bağlantılar kurarak çevreyi anlamlandırmasına yardımcı olur. Günlük kullandığınız eşyaların aksine oyuncaklar yaratıcılık becerilerini artırır ve yeni şekillenen hayal dünyasının gelişiminde çok faydalıdır. Bu aşamada bebeğin işitme duyusu, görme duyusuna göre daha baskındır. Bu yüzden ilk 6 ayda bebek için sesli detayları olan oyuncaklar daha faydalıdır. Bunlara örnek olarak hafif ve farklı sesler çıkaran oyuncakları, yatağına ve oyun matına asılan müzikli oyuncakları ve tutabileceği çıngırakları gösterebiliriz.') WHERE id = '341dbb77-f89b-4786-ae5e-27fe6c263105';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'İlk 1-2 ayda bebeğin ellerinin genellikle yumruk gibi sıkılı olduğunu, şimdi ise açıldığını fark ettiniz mi? 3. ayda kendi elleri dikkatini çekmeye başlar. Ellerini daha sık hareket ettirir; onları izlemek ve oynatmak en sevdiği uğraşlardan birine dönüşür. Ellerini keşfederken bir yandan da görme yeteneği gelişir. Bu dönemi daha ilginç hâle getirebilirsiniz! Bileklerine takılan sesli oyuncaklar alarak keşif yolculuğuna destek olabilirsiniz. Ama bunu mutlaka gözetim altında yapmalısınız; küçük eller çok hızlı hareket edebiliyor.') WHERE id = 'ad6180ec-951a-4399-9c9f-0798090c6244';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz bu aşamada doğuştan gelen birçok refleksini hâlâ kullanmaya devam edebilir. İçgüdüsel hareketler denilen bu refleksler bebek büyüdükçe kaybolur ve yerini daha karmaşık motor becerilere, istemli hareketlere bırakır. Bebek için önemli refleksler şunlardır: emme ve arama refleksi, Moro refleksi, tonik boyun refleksi, adımlama refleksi, tutma refleksi, Babinski refleksi, bükülme refleksi, yutma ve öğürme refleksleri. Bu reflekslerin bazıları bu aşamada kaybolmuş, bazıları da azalmaya başlamış olabilir. Örneğin arama ve emme refleksi bebeğin doğumuyla ortaya çıkar ve hayatta kalmak için beslenme içgüdüsünden doğar. Gelişimin yaklaşık 2. ve 4. ayları arasında, özellikle gündüzleri bu refleksin yerini istemli davranışlar almaya başlar. Yani artık bebeğin yanağına dokunduğunuzda ağzını açmadığını ama mamasını yaklaştırdığınızda ağzını açtığını gözlemleyebilirsiniz.') WHERE id = 'f9a31ada-1c4c-4cc8-a19f-e08982dace02';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğinizle kaliteli vakit geçirmek; süreye değil, içeriğin faydasına odaklanarak onunla yapacağınız etkileşimli, yani karşılıklı etkinliklerdir. Bu açıdan bebeğinizle aynı odayı paylaşsanız bile ortada bir etkinlik ve ilgi yoksa bu, kaliteli vakit sayılmayabilir. Bebeğin gelişimi için kaliteli vaktin temel şartlarından biri, doğduğu andan itibaren onunla huzurlu, şefkatli ve yumuşak bir ses tonuyla tane tane konuşmanız ve yaptığınız hareketi anlatıp bilgi vermenizdir. Bebeğiniz henüz konuşacak ve söylediklerinizi kavrayacak fiziksel ve zihinsel gelişime sahip olmasa da bu aşamada duyduğu farklı kelimeleri hafızasına kodlamaya başlar. Onunla sık sık konuşmanız ve konuşurken çeşitli kelimeler kullanmanız; ileride şekillenecek dil gelişimi, konuşma becerisi ve zihinsel gelişimi açısından son derece önemlidir. Örneğin bebeğin altını değiştirirken susmak yerine ona adım adım ne yaptığınızı anlatmalısınız. Bu yöntemi günlük hayatınızın her anına uygulamanız, bebeğinizde zengin bir kelime hazinesi oluşmasını sağlayacak ve zekâ gelişimini ateşleyen bir etken olacaktır.') WHERE id = 'b5b55ba0-7239-4a48-97b0-39887b3f6198';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin beyin hücreleri yeni deneyimler kazandıkça gelişir. Siz de bu gelişimi desteklemek için bebeğinize sık sık yeni deneyimler yaşatmalısınız. Örneğin onunla oynayacağınız yeni oyunlar, etkinliklerinize farklı oyuncaklar ya da hareketler eklemek beyin hücreleri arasındaki bağlantıları hızlandıracaktır. Mevcut oyuncaklarıyla oynamanın başka bir yolunu göstermek ya da alışık olduğundan farklı fiziksel yapıdaki nesneleri tanıtmak bile gelişimi için oldukça etkili bir yöntem olabilir. Bu etkinlikler sırasında bebeğinize sunduğunuz yeni deneyimleri sık sık tekrarlamasını sağlamalısınız. Bebek bir olayı tekrarladıkça, yeni kazandığı bu deneyim hafızasında daha da pekişecek. Bebeğiniz aktif öğrenme aşamasına girdiği için ona olumlu yaklaşmalı ve belli bir düzen oluşturmaya çalışmalısınız. Bebeklerin genellikle mutlu anları ve bu anları hatırlatan her tür uyaranı beyinlerinde saklamaya daha yatkın olduğu gözlemlenmiştir. Bebeğiniz sizin duygusal durumunuzdan ciddi şekilde etkilendiği için, onunla vakit geçirirken neşeli ve mutlu olmanız ona olumlu yansıyacaktır.') WHERE id = '6974552e-5545-418f-9e3a-c5909451e194';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Her bebek kendine özgü bir hızla büyür ve gelişim aşamalarını farklı zamanlarda tamamlar. Bu yüzden bebeğin gelişimi için karşılaştırmalar yapmanın hiçbir anlamı yoktur. Bebeğiniz konuşmasını sağlayacak organlarını henüz zihinsel ya da fiziksel olarak yönetemese de vaktinin çoğunu sesinizi dinleyerek geçiriyor. Sizi dinleyen bebek, dille ilgili her tür bilgiyi hafızasına yazıyor. Bu yüzden konuşması için henüz zamana ihtiyacı olsa da farklı istekleri için değişik ağlama tonları, gülüş ve "agulama" gibi tepkiler gösterebilir. Bebeğiniz sevgisini ve kendisine gösterilen ilgiye karşılık vermek amacıyla, beslenme ya da alt değiştirme sırasında size tekme atarak ya da sesler çıkararak tepki verebilir. Bu noktada bazı bireysel farklılıklar olabilir. Bazı bebekler anlamlı sesler çıkarmak için sürekli çabalarken, bazıları buna tam hazır olana kadar bekleyebilir. Araştırmalara göre bebeklerle iletişim kurma tarzı, onların dil gelişimiyle ilişkilidir. Bebeğin gelişimini desteklemek için onunla sık sık konuşmanızı, oyunlar oynamanızı, kitap okumanızı ve konuşurken daha sade, anlaşılır bir dil kullanmanızı öneririz. 😊') WHERE id = '51f1030e-fc36-4b12-b1d7-a64348ea081b';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bu aşamada bebeğinizle birlikte vakit geçireceğiniz ve gelişimini destekleyecek pek çok farklı etkinlik var. Örneğin çeşitli sesleri duyması için ona ortam yaratabilirsiniz. Ses çıkaran oyuncakları veya çıngırakları bebeğin sağında ve solunda sallayarak sesin geldiği tarafa bakmasını teşvik edebilirsiniz. Özellikle keyfi yerindeyken, banyodan ya da emzirmeden sonra ona çeşitli hayvan sesleri dinletebilirsiniz. Önce kedi ve köpek gibi daha tanıdık sesleri, sonra at, arı, eşek gibi farklı hayvanların seslerini dinletebilirsiniz. Bunun için internetten ve eğitici kitaplardan yararlanabilirsiniz. Hatta bu sesleri kendiniz de çıkarabilirsiniz. Bebeğin farklı seslere verdiği tepkileri gözlemleyin. Birlikte vakit geçirdiğiniz bu etkinlikte çok eğlendiğini göreceksiniz. 😊') WHERE id = 'e2c4c53d-e6ae-41f3-83d4-6473c78c7fb7';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz muhtemelen artık dönmeye başladı. Hatta bazı bebekler daha erken de dönebilir. Ama bebeğiniz henüz dönmüyorsa bu, endişelenecek bir konu değildir. Her bebek benzersizdir ve gelişimleri oldukça farklı olabilir. Bebeğin rahatça dönebilmesi, baş ve boyun kaslarının gelişimine bağlıdır. Bu kontrol sağlandığında bebek; oturma, emekleme ve yürüme gibi motor becerilerin de temelini atmış olur. Dönmesini teşvik etmek için onu yumuşak bir yüzeyde yüzüstü yatırarak alıştırma yapmasını sağlayabilirsiniz. Erken doğan bebeklerin kas ve sinir sistemi diğerleri gibi çalışmadığı için baş-boyun kontrolünü daha geç sağlayabilirler. Bebeğiniz erken doğduysa dönmek için 9. aya kadar vakti var. Hem kim bilir? Belki dönme aşamasını atlayıp doğrudan oturmaya başlayacak? 😊') WHERE id = '4f657a4a-e832-4fda-9834-e8fa08bd9d44';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin ağzından akan salyalar, her şeyi ağzına götürme çabaları... Muhtemelen bunların nedenini siz de biliyorsunuz. Bu aydan itibaren bebeğiniz için diş çıkarma dönemi başlıyor. Güldüğünde kahkahalarına yakışan dişlerini görmek elbette çok tatlı. Ama diş çıkarma dönemi çoğu bebek için ağrılıdır. Bu durum bebeğinizde huzursuzluğa, diş etlerinin şişmesi sonucunda ağrılara yol açabilir. Diş çıkarma belirtilerinin en bilineni elbette salya artışıdır. Ayrıca eline geçen her şeyi ısırmaya çalışması, hafif ateş, memeyi veya yemeği reddetme diğer belirtilerdir. Bu belirtiler aylar öncesinden görülebilir ya da kalıtıma bağlı olarak hiçbir belirti olmadan bu ay içinde dişleri çıkabilir. Diş çıkarma sırasında bebeğin ateşinin 37 dereceye kadar yükselmesi doktorlarca normal kabul edilir ve müdahale gerekmez. Ancak ateşi 38 derece ve üzerine çıkarsa bu, diş çıkarma belirtisi değildir ve doktorunuza danışmanızı gerektirir.') WHERE id = 'fd702e8d-6a0f-4f31-a1a0-b330e1d04288';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin saçını evde kesmeye karar verirseniz dikkat etmeniz gereken bazı noktalar var. Öncelikle kesime başlamadan önce bebeğin karnının tok olduğundan ve gaz sancısı gibi bir rahatsızlığı olmadığından emin olmalısınız. Çünkü kendini rahatsız hisseden bebek huzursuzlanıp ani hareketler yapabilir; bu da tehlikeli yaralanmalara ya da saçın yanlış kesilmesine yol açar. Bebeğiniz oturabiliyorsa onu mama sandalyesi gibi rahat bir yere koyarak ya da kucağınızda destekleyerek sabit tutabilirsiniz. Kesim için ucu sivri olmayan küçük makaslar kullanmalısınız. Ayrıca oyalanması için sevdiği bir oyuncağı vermeniz ve kesim sırasında onunla sürekli konuşmanız sakin kalmasına yardımcı olacaktır. Saçları keserken kulak, boyun ve alın bölgelerinde özellikle dikkatli olmalı, gerekirse size yardım eden kişiden bebeğin başını sabit tutmasını isteyebilirsiniz. İş bitmeden bebeği makasla yalnız bırakıp yanından ayrılmamalısınız. Bu yüzden başlamadan önce havlu, tarak gibi malzemeleri önceden hazırlamalısınız.') WHERE id = '4c05c1b9-816f-4b3a-9570-73a5e8523f06';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğinizi kucağınıza aldığınız ilk günü muhtemelen daha dün gibi hatırlıyorsunuz. Zaman ne kadar hızlı geçiyor, değil mi? 😊 4. aya ulaşan bebeğiniz artık büyümeye başladığını size hissettiriyor. Onunla sürekli ilgilenmenizi istiyor ve bir oyun çocuğu olduğunu her fırsatta hatırlatıyor. Yüzüstü yatarken elleri ve dirsekleriyle destek alarak kalkan bebek, göğsüne kadar doğrulabiliyor ve yüzükoyun yatarken başını 90 derece kaldırabiliyor. Yüksek sesle gülmeler ve dikkat çekmek için atılan çığlıklar da bu dönemde epey artıyor. Hatta bebeğin oturmak için büyük bir mücadele verdiğini görebilirsiniz. Bazı uzmanlar bebeklerin 6. aydan önce oturtulmasına sıcak bakmasa da bazı doktorlar her bebeğin gelişiminin farklı olduğunu savunuyor. Bu yüzden bebeğinizi gözlemlemeniz ve ne istediğini anlamaya çalışmanız çok önemli. Oturmak için can atan bebeği destekli şekilde çok kısa süreliğine oturtmak onu epey mutlu edebilir. Yine de her bebek kendine özgü bir gelişim gösterdiğinden bu konuda doktorunuzun görüşünü almak daha doğru olur. 😊') WHERE id = '2ec8f436-2faa-47d9-bf8d-3c7a85cda289';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Önümüzdeki haftalar hem sizin hem de bebeğiniz için biraz zorlu geçebilir. 14-19. haftaları kapsayan dördüncü sıçrama dönemi (atak dönemi), en uzun süren gelişim aşamalarından biridir. Bebeklerin çoğu bu büyüme arifesinde memeyi veya mamayı reddedebilir. Tam "uyku düzeni oturdu" derken uykuya dalmada direnç oluşabilir. Ayrıca sürekli kucakta kalmak isteyen ve huzursuz olan bebeğiniz sizi biraz yorabilir. Ancak bu zorlu dönemin sonunda bebeğiniz için tamamen yeni bir aşama başlayacak. Artık olayların sırasını keşfetmeye başlıyor. Örneğin bir nesne gördüğünde dikkatini çekebilir, onu sıkıca tutup incelemek ister. Bir süre elinde tuttuktan sonra o nesneyi yakından tanımak için ağzına götürebilir. Bu büyüme sıçramasının sonunda bebeğin aynaya baktığında kendini tanıdığını ve kendine gülümsediğini görebilirsiniz. Artık doyduğunu anlayan bebek, yeterince süt aldıktan sonra geri çekilebilir; bu da kusma sorununu en aza indirmeye yardımcı olur.') WHERE id = '57457675-a7c5-476e-b444-66d0b8d0364f';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, '4. ay doktor kontrolünde bebeğin gelişimini değerlendirmek için boyu, kilosu, baş çevresi, göz muayenesi, sırt ve boyun kasları kontrol edilir. Bu aşamada bebeğin kilosu 4800-9100 gram, boyu ise 58-69 cm aralığında olmalıdır. Bu değerlerin alt ya da üst sınırına yakın olması, bebeğinizde bir gelişim sorunu olduğu anlamına gelmez. Baş çevresi ise bu dönemde 39-45 cm aralığındadır. Sağlıklı beyin gelişiminin göstergesi olduğu için baş çevresinin bu aralıkta olması çok önemlidir. Görme yeteneği artık tam olgunlaştığı için bebek bundan sonra nesneleri gerçek renkleriyle görebiliyor. Bu da dış dünyayı daha ilginç kılıyor; bebek uykuya ve emmeye ayırdığı zamanı azaltıp çevresiyle daha çok ilgilenebilir. Bununla birlikte 4. ay uzun bir büyüme sıçramasını kapsadığından, tüm bu gelişmelerin gölgesinde uyku gerilemesi (regresyon) yaşanabilir. Bu yüzden bebeğinizle her zamankinden daha çok ilgilenmeniz gerekebilir. Birlikte geçireceğiniz vaktin tadını çıkarmaya çalışın. Eğlenceli zamanlar! 😊') WHERE id = '3e04c60c-ae8b-4665-9ca2-95ef5bdb8192';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin 4. ay kontrolünde yapılması gereken aşılar; 2. ayda yapılan verem aşısı dışında, diğer iki aşının ikinci dozlarıdır. Bunlar pnömokok (menenjit) ve beşli karma denilen difteri, boğmaca, tetanos, hib ve çocuk felci aşılarıdır. Bebeğin rotavirüs aşısı 2. ayında yapıldıysa ikinci dozu bu ay yapılmalıdır. 4. ay aşılarından sonra bebeğinizde ateş ve huzursuzluk olursa doktorunuzun önerdiği ateş düşürücüyü verebilirsiniz. Her bebekte farklı olsa da genellikle aşıdan 2-4 saat sonra ateş yükselebilir. Ateş bazen 2-3 gün kadar sürebilir. Ayrıca iğne yapılan yerde ağrı, şişlik ve kızarıklık olması tüm aşılardan sonra görülebilir. Bebeğin huzursuzluğunu ve şikâyetlerini azaltmak için iğne yerine soğuk kompres uygulayabilir ve ağrı kesici olarak doktor önerisiyle parasetamol içeren ilaçlar kullanabilirsiniz.') WHERE id = 'ecec54a9-6b16-4860-9c1c-01c24cd2eac2';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz artık aktif öğrenme aşamasında ve tüm yeni deneyimlere merakla tepki verdiğini gözlemleyebilirsiniz. Bu gelişim aşamalarından biri de konuşma becerisinin temelleridir. Artık sesinize tepki veriyor ve duyduğu sesleri taklit etmeyi seviyor. Özellikle mutlu olduğunda ince seslerle çığlık atabilir, yüksek sesle gülebilir ve "a-gu" gibi sesler çıkarabilir. Bebeğin konuşma yeteneğini geliştirmek için onunla sık sık sohbet etmenizi öneririz. 😊 Dördüncü ayındaki bebek dış etkenlere karşı çok meraklı olduğundan dikkati sık sık dağılabilir. Örneğin yemek yerken dikkatini başka bir şey çekerse emmeye ara verebilir. Zaman zaman uykuyu reddetmesinin nedeni de bu olabilir. Sabırlı olmalısınız; çünkü dünya onun için çok büyük ve keşfedilecek çok şey var! 😊') WHERE id = '0479afbe-b14f-457d-b226-70e3d4f9bf7b';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz bu günlerde size sürpriz yaparak yüzüstü yatarken yan tarafa, hatta sırtüstü dönebilir. Gelişen sırt ve boyun kasları sayesinde bu dönme denemeleri çoğu zaman başarıyla sonuçlanır. Hatta bu aydan itibaren bebeğiniz oturmaya bile başlayabilir. Bazı doktorlar 6 aydan önce oturtmayı önermese de her bebeğin gelişiminin farklı olduğunu unutmamak gerekir. Bebeğin beyni ve bedeni hazır olduğunda, yani kas ve denge kontrolü yeterli seviyeye ulaştığında kendini oturma pozisyonuna getirecektir. Bebeğiniz kendini kaldırıp oturmaya çalışıyorsa, çok uzun süre olmamak şartıyla ona izin verebilirsiniz. Başarabildiğini görmek onu mutlu edecek ve heveslendirecek. Yine de sırtını desteklemeyi unutmamalısınız. Bazı bebekler bu ayda oturmaya başlasa da henüz desteksiz oturacak kadar güçlü sırt kaslarına sahip olmadıklarını akılda tutmak gerekir.') WHERE id = '3e15f79b-7870-4c1b-9ff8-0d7695190d48';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz doğum kilosunu ortalama olarak ikiye katladı ve onu emziriyorsanız bazen sütünüzün yetmediğini düşünebilirsiniz. 4. ve 5. aylar bebeğin hızlı fiziksel gelişim dönemi olduğu için enerji ihtiyacı artıyor. Bu artan ihtiyacı karşılamak için ek gıdaya başlamayı düşünebilirsiniz. Ancak unutmayın; bu aşamada bebeğin bağırsak florası katı gıdalar için henüz hazır değil. Ek gıda, bebeği katı gıdalara alıştırmak amacıyla çok küçük miktarlarda verilir ve sağlıklı bağırsak gelişimi için bu sürece 6. aydan sonra başlanmalıdır. Dünya Sağlık Örgütü (DSÖ), ilk 6 ay tamamlanana kadar bebeğe yalnızca anne sütü, yoksa tek alternatif olan mama verilmesini önerir. Herhangi bir ek gıdaya 6 aydan erken başlamak bebeğinizde kansızlık, hazımsızlık, gaz sancıları, mide ve bağırsak sorunları yaratabilir. Bu yüzden ek gıdaya başlama konusunda acele etmemelisiniz, sevgili anne.') WHERE id = '63dc3b2b-9b88-4480-8d80-226d9607b848';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin tükürük bezleri artık daha aktif çalıştığı için ağzının sulanması ve bunu henüz yönetemediği için salyasının akması tamamen normaldir. Bu belirtiler aynı zamanda diş çıkarma döneminin habercisidir; damakları kaşınan bebek ellerini sık sık ağzına götürebilir. Uzmanlar bu konuda bebeklere engel olmamayı, aksine ellerini keşfetmesi için ona imkân tanımayı öneriyor. Ancak eline geçen her şeyi ağzına götürmeye çalışan bebeğin küçük nesneleri yutabileceğini unutmamalısınız. Özellikle kolay kırılan ve parçalara ayrılan oyuncaklardan uzak durmalı, oynadığı her nesnenin temiz ve steril olduğundan emin olmalısınız. Damakları kaşındığı için her şeyi kemirmek isteyen bebek, siz görmediğiniz bir anda tehlikeli nesneleri ağzına sokabilir. Olası boğulma tehlikesine karşı oyuncak seçimine dikkat etmeli ve güvenlik önlemlerini artırmalısınız.') WHERE id = 'ff292524-4cb1-4b4f-9235-43064f330adc';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz artık yuvarlanmak, kendi çevresinde dönmek, yatarken başını 45 dereceye kadar kaldırmak, başını ve bedenini sağa sola sallamak gibi becerilere sahip. Bu hareketler gelişimin normal seyridir. Hatta onu yüzüstü yatırdığınızda ileriye doğru sürünüyormuş gibi hareket ettiğini de görebilirsiniz. Bebeğiniz, her çocuk gibi yeni beceriler öğrenmeye ve öğrendiklerini sık sık tekrarlamaya çok hevesli. Ancak unutmayın; her bebeğin gelişimi kendine özgüdür. Bebeğiniz bu becerilerin bazılarını henüz kazanmadıysa endişelenmeyin. Ayrıca gelişimini doğru desteklemek için bazı ayrıntılara dikkat etmelisiniz. Bunlardan biri de yürüteç kullanımıdır. Sürekli gezmek ve çevreyi keşfetmek isteyen bebeğiniz sizi bazen yorsa da çareyi yürüteçte aramamalısınız. 6 aydan küçük ve henüz oturmaya hazır olmayan bebeği buna zorlamak ya da yürütece koymak; ileride emekleme ve sürünme gibi önemli beceriler için gereken kas gelişimini engelleyebilir.') WHERE id = 'ea44cd71-5051-4dfc-bbf3-dac92612f0a6';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'En çok tereddüt ettiğiniz konulardan biri de muhtemelen bebeği gece uykusundan önce nasıl giydireceğinizdir. Bebeğiniz artık epey hareketli olduğu için üzerine örttüğünüz yorganı ya da battaniyeyi sık sık açabilir. Bebeklerin neredeyse hepsi gereğinden fazla sıcağı sevmez ve sıcakta huzursuz olur. Bebeği yatırdığınız odanın sıcaklığını 22-24 derece, nemini ise %40-60 arasında tutmanız idealdir. Onu gece uykusuna hazırlarken pamuklu uyku tulumu ve mevsime göre içine ince pamuklu pijama giydirebilirsiniz. Giydirdiklerinizin yeterli olup olmadığını anlamak için koltuk altından vücut sıcaklığını ölçebilirsiniz. Sıcaklık 36,2 ile 37,2 derece arasındaysa bebeğiniz üşümüyor demektir. Bu değerlerin altında olması üşüdüğünü gösterir; bu durumda bir kat fazla giydirebilirsiniz.') WHERE id = '3719fbec-0855-4e9e-bd59-1324c629c2ce';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz artık tanıdık yüzleri seçebiliyor ve çevresindekilere ilgi gösteriyor. Özellikle tanıdığı insanlara gülümseyerek karşılık verirse şaşırmayın. 😊 4. ayda bebek birçok yeni beceri kazanır. Bu beceriler hem fiziksel hem de zihinsel gelişimi kapsar. El-göz koordinasyonu epey gelişen bebek artık iletişimden daha çok keyif alıyor. Ellerini dakikalarca hayranlıkla izlemesi, saçlarınızı çekmesi, bulduğu her şeyi ağzına götürmesi de bundan kaynaklanıyor. Yardımınızla nesnelere uzanabilen ve dokunduğu oyuncakları kavrayan bebeğinizle birçok basit oyun oynayabilirsiniz. Bunun yanı sıra aylık gelişimine uygun hazırlanmış aktivite oyuncakları kullanmanız hem fiziksel hem de zihinsel gelişimini destekleyecek. Oyuncak seçerken sebep-sonuç ilişkisini kavrayabileceği türden oyuncakları tercih etmenizi öneririz.') WHERE id = 'aeb00407-e412-4f78-961f-30f7b120bf0d';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz için dış dünya, ucu bucağı görünmeyen bir keşif alanıdır ve sizin de bunu anlayışla karşılamanızın zamanı çoktan geldi. Sürekli kucakta kalmak istemesi, uyumayı ya da emmeyi reddetmesi, bir yerde durmaması, sık sık oynamak istemesi tamamen normaldir. Bununla birlikte bebeğiniz için egzersiz yapmak ve hareket hâlinde olmak, fizyolojik gelişimi açısından çok önemlidir. Bebeğinize egzersiz yaptırmak için ayak bileklerinden tutup bacaklarını nazikçe katlayarak yukarı aşağı hareketler yaptırabilirsiniz. Ayrıca iki kolunu tutup göğsünde birleştirebilir, çapraz şekilde açıp kapatabilirsiniz. Bu hareketler sırasında bebeğin kendini daha rahat hissetmesi için onunla konuşmayı ve sık sık gülümsemeyi unutmayın. Birlikte geçireceğiniz bu anlar, bebeğiniz için sosyalleşmenin en sağlıklı yollarından biridir.') WHERE id = '77bdf252-33eb-455c-b59d-8af7012e078c';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Zamanında doğan bebeklerin birçoğu henüz üç aylıkken bile katı gıdalara hazır hâle gelebilir. Ancak katı gıdaya geçişi engelleyen "dil itme" refleksi genellikle dördüncü aydan itibaren kaybolmaya başlar. Aslında emme işlevinde önemli rol oynayan bu refleks, bebeğin verdiğiniz yiyecekleri diliyle itmesine yol açar. Bu aydan itibaren bebeğiniz besinlerin bir kısmını sindirebilecek bir sisteme sahip. Ancak bu, gelişimin aşamalı bir parçasıdır ve katı gıdalara tamamen hazır olduğunu göstermez. Bu konuda Dünya Sağlık Örgütü''nün önerisi şöyledir: bebek kilo kaybetmeden sağlıklı büyüyorsa 6. aya kadar yalnızca anne sütüyle devam edilmelidir. 6. aya kadar sütün az olduğu ve bebeğin ayda 500 gramdan az kilo aldığı durumlarda ise devam sütlerinin (formül mamaların) beslenmede temel yer tutması gerektiğini unutmamalısınız. 6 ay dolduktan sonra bile temel besin maddesi yine anne sütü olmalıdır. Dünya Sağlık Örgütü, 9 aylık bir bebek için beslenmenin %70''inin anne sütünden oluşmasını öneriyor.') WHERE id = '8360a204-f867-4fb6-bb2c-9a237526ca1c';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz bu günlerde ilk kez yuvarlanabilir. Bebekler bu hareketi genellikle 4. ay civarında, yüzükoyun pozisyondan dışa doğru dönerek gerçekleştirir. Neredeyse tüm bebekler bunu başardıklarını anladıkları anda tekrarlamak ister ve böylece bitmek bilmeyen yuvarlanmalar başlar. Bununla birlikte bazı bebekler döndükten sonra korkabilir ve bir süre yeniden denemekten çekinir. Bebeğin karnının yuvarlak ve esnek yapısı, bu hareketi kolayca yapmasına epey yardımcı olur. Yuvarlanmayı teşvik etmek ve sırt kaslarını güçlendirmek için bebeği uzanma hareketlerine özendirebilirsiniz. Örneğin bir oyuncağa ya da nesneye ulaşmaya çalışması, yuvarlanmasına zemin hazırlar. Ancak yuvarlanırken yüzüstü, nefes alamayacağı bir pozisyonda kalmamasına ya da düşebileceği bir yerde olmamasına çok dikkat etmeli, bu alıştırmalar sırasında onu yalnız bırakmamalısınız.') WHERE id = '74e1e965-f81e-44cc-a407-7883c6451cc2';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'İlk ayların aksine bebeğin daha az beslendiğini düşünebilirsiniz. Bu endişe yaratsa da aslında doğal bir süreçtir. Bunun temel nedeni, bebeğin işini nasıl kolayca halledeceğini artık öğrenmesidir. Artık daha kısa sürede daha çok süt emebiliyor. Bu da karnını hızla doyurması demektir. Bu yüzden bebek gün içindeki beslenme sayısını 4-5 keze kadar azaltabilir. Ayrıca bu ayda yaşayacağı büyüme sıçraması, beslenmesinde kısa süreli de olsa bazı değişikliklere yol açabilir. Artık bebeğin hareketlerini gözlemleyerek acıktığını rahatça anlayabileceğiniz için beslenme saatlerini düzenleyebilirsiniz. Örneğin 4. aydan itibaren bebeği emzirmek için uykusundan uyandırmak zorunda değilsiniz. Ayrıca bir sonraki emzirmeye kadar yaklaşık 4 saat ara vermeniz, bebeğin sütünüzdeki besin değerlerinden daha çok yararlanmasını sağlayacaktır.') WHERE id = 'ea6d6e3a-c957-436f-ac9c-f0c52e449526';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz sizi, yüzünüzü, ifadelerinizi; kısacası onunla iletişimde olduğunuz her anı gözlemlemeye devam ediyor. Bu gözlem ve izlemenin sürekliliği, dünyadaki keşiflerini zenginleştirip çeşitlendirmesine yardımcı olur. Bebeğin her yeni keşfi, beynindeki sinir hücreleri arasında bağlantı kurmasını sağlar ve bunun sonucunda çok daha hızlı kavramaya ve öğrenmeye başlar. Bu bağlantıların kurulması için eline verdiğiniz çıngırağın ses çıkarması, oyuncaklarının şeklini incelemesi, hatta sizi gözleriyle izlemesi bile yeterlidir. Bebeğiniz mimiklerinizi, ses tonunuzu, hatta davranışlarınızı bile daha dikkatle gözlemlemeye çalışıyor. Bu da sizi artık daha iyi anladığı anlamına geliyor. Bu yüzden ona gösterdiğiniz ilginin karşılığını tam da bu aylardan itibaren görmeye başlayabilirsiniz. Birlikte iletişimde olduğunuz ve onunla ilgilendiğiniz her an, aranızdaki bağı daha da güçlendirecek.') WHERE id = '170aa164-55dd-45ac-8848-491ec6187f44';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz soğuk algınlığı, mevsim değişikliği, grip ya da alerji nedeniyle sık sık burun tıkanıklığı yaşayabilir. Burnunun tıkanması nefes almasını zorlaştırmanın yanı sıra beslenme ve uyku düzenini de olumsuz etkileyebilir. Hatta meme reddinin en büyük nedenlerinden biri tam da burun tıkanıklığıdır; çünkü bebek nefes almak için ağzını kullanmak zorunda kalır ve doğal olarak emmek istemez. Bebeği epey rahatsız eden bu durumu gidermek için doktorunuzun önerdiği bebeklere özel burun spreyleri, serum fizyolojik ve oda nemlendiricisi kullanabilirsiniz. Tuzlu su olarak bilinen ve içinde kimyasal madde olmayan serum fizyolojik (izotonik sodyum klorür), bebeğin burnunu kısa sürede açacaktır. Özellikle ilk kez anne olduysanız bunu uygulamak size zor gelebilir. Serum fizyolojik yeterli olmazsa bebekler için özel üretilmiş burun aspiratörlerinden de yararlanabilirsiniz.') WHERE id = '9c8572cd-a48b-4b37-a542-edfc74817a74';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin fiziksel gelişimi, sürünme ve emekleme aşamasına hazırlanması için uzmanların önerdiği bir egzersiz var. Tummy time (yüzüstü zaman) denilen bu etkinliği bebeği yüzüstü yatırarak yapabilirsiniz. Bu, genellikle az kullandığı sırt kaslarını geliştirir; aynı zamanda bacak, boyun, omuz ve karın kaslarını güçlendirir. Motor becerileri geliştiren bu hareketler, başında oluşabilecek şekil bozukluklarının (düz kafa sendromu) da önüne geçer. Bu sırada çevresine dizeceğiniz oyuncaklar sayesinde beyninin çok yönlü bağlantılar kurmasına yardımcı olabilirsiniz. Bebeğiniz yüzüstü kalmaktan çabuk sıkılabilir ya da dikkati dağılabilir; bu yüzden yanında kalıp ilgisini farklı yönlere çekmelisiniz. Onunla konuşmanız, şiirler söylemeniz, sevdiği oyuncakları göstermeniz ve rahatlatıcı bir müzik açmanız işinizi epey kolaylaştıracak. İyi eğlenceler! 😊') WHERE id = '3d1db687-2705-4040-8e81-a914b3ab0052';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin beynindeki milyarlarca sinir hücresi sayesinde öğrenmeye en açık olduğu dönem, doğumdan 48. aya kadar olan zamandır. Bu yüzden bu aralıkta bebeğinizle kurduğunuz kaliteli ve planlı iletişim, gelişimine büyük ivme kazandıracak. Araştırmalara göre bebeklik döneminde doğru gelişim geçiren çocuklar okul çağında daha başarılı eğitim göstergelerine sahip oluyor ve bu, hayatlarında fark yaratıyor. Doğumdan itibaren bebeğinizle geçirdiğiniz zaman ve bu zaman dilimindeki kaliteli etkileşim; beyin ve duygusal gelişimine pek çok olumlu etki yapar. Bebeğinizle ilgilenmeniz ve birlikte geçirdiğiniz verimli vakit, merkezî sinir sisteminin gelişimini destekler. Bu; benlik duygusunu güçlendirir, diğer insanlarla güvenli bağ kurmasına yardımcı olur, özgüvenini artırır ve kendini değerli hissetmesini sağlar. Öyleyse işlerinizi biraz erteleyip bebeğinizle vakit geçirmeye ne dersiniz? 😊') WHERE id = '4e220ec0-af8b-4430-ab5f-7ff3954ffb65';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bir kızınız varsa kulaklarını ne zaman deldirmenin daha doğru olduğu konusunda aklınızda sorular olabilir. Bebeklerde kulak deldirmek için kesin bir ay aralığı yoktur. Bu daha çok kişisel bir tercih olsa da doktorunuzdan görüş alabilirsiniz. Bebeklerin kıkırdakları henüz çok yumuşak olduğu için bu aylarda küpe takmak daha az ağrılı olur. Ancak dünyaca ünlü bazı pediatri kuruluşları, aşı takviminin tamamlanması ve bakım sürecinin zorluğu nedeniyle bu aylarda kulak deldirmeyi önermiyor. Bununla birlikte kulak delme işlemi ve sonrasındaki bakım doğru yapılırsa bebeğinizde sağlık sorunu oluşma olasılığı oldukça düşüktür. Bebeğin kulaklarını deldirmeye karar verirseniz, iltihabı önlemek için takılan küpelerin paslanmaz çelik ya da mümkünse altın olmasına dikkat etmenizi öneririz.') WHERE id = '622d780e-3a5e-48fd-b009-10a81d465be2';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin sürekli emmek istemesi özellikle yenidoğan döneminde sık görülse de bu durumla her zaman karşılaşabileceğinizi unutmamalısınız. Uzmanlara göre 2 yaşına kadar sürdürülmesi önerilen emzirme süreci, sizinle bebeğiniz arasında özel bir bağ oluşturur. Bu yüzden bebeğiniz size yakın olma içgüdüsüyle sık sık emmek isteyebilir, emerek uykuya dalmayı seçebilir ve gün boyu memeden ayrılmak istemeyebilir. 4. aydan itibaren gaz sorunu azalsa da bazı bebeklerde bu durum 6. aya kadar sürebilir. Bebeğiniz gaz sancısı yaşadığında kendini güvende hissetmek için size en yakın olduğu yerde, yani kucağınızda ve süt emerek sakinleşmek isteyebilir. Ayrıca hareketlenmesiyle birlikte enerji ihtiyacının artması da emme isteğini artıracaktır. Gün içinde sık sık emen bebeğinizle kurduğunuz fiziksel temas, size olan bağlılığını güçlendirir. Yani bebeğin hiçbir sorunu olmasa bile sürekli emme isteği, bu ten temasına daha çok ihtiyaç duyduğu anlamına gelebilir.') WHERE id = '15a9163c-c7da-40c2-a76c-38c778e04718';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğinizin cildinde çeşitli biçimlerde döküntüler oluşuyorsa bu, alerjik egzama olabilir. Alerji; aslında zararsız olan bir maddenin bebeğin organizması tarafından yabancı ve tehlikeli olarak algılanıp tepki verilmesidir. Unutmayın; alerjiye yol açan etkenler illa yiyecek olmak zorunda değildir. Masanın üzerindeki toz, mevsim geçişlerinde oluşan polenler, hatta sigara dumanı bile bebeğinizde alerjik reaksiyon yaratabilir. Bebeğinizde döküntü, kızarıklık, kakada kan noktacıkları gibi durumlar gözlemliyorsanız doktorunuza danışmanızda fayda var. Çünkü çoğu bebek için sağlıklı olan bir besin ya da madde, alerjisi olan bir bebek için önlem alınmadığında ciddi sorunlar yaratabilir. Alerjiler genellikle bağışıklık sistemindeki bazı bozukluklar nedeniyle oluşur ve genetik özellik de taşıyabilir. Yani sizde olan bir alerjinin bebeğinizde de görülme olasılığı vardır.') WHERE id = 'e82d9ae2-ed27-40cb-9366-8cbbd0962327';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin sağlıklı büyümesi ve gelişmesi için beslenmesi çok önemlidir. Ancak bazen memeyi veya mamayı reddetme durumları görülebilir. Özellikle emziren bir anneyseniz bebeği sabırla ve sık sık emzirmenizi öneririz. Reddin nedenleri arasında diş çıkarma, kriz (sıçrama) dönemine girme ya da burnunun tıkanması gibi pek çok etken olabilir. Gelecek aylarda bebeğin ihtiyaçlarına uygun beslenme değişiklikleri yapabilirsiniz; ama şu an tam bir düzen oturtmak için onu zorlamamalısınız. Yemek reddi yaşandığında bilin ki bu sorun bir süre sonra düzelecek ve her şey yoluna girecek. Böyle durumlarda "aç kalacak" endişesiyle katı gıdaya erken geçmemenizi öneririz. Bebeğin 180 günü doldurduktan sonra ek gıdaya başladığından emin olun ve mutlaka verdiği sinyalleri izleyerek hazır olmasını bekleyin. Bu yüzden süreç boyunca bebeğinize sabırla yaklaşmalı, onu anlamalı ve ihtiyaçlarına yanıt vermelisiniz.') WHERE id = '63e83115-0a58-4fb8-af8e-8058860fc7f2';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğinizin içinde olduğu 0-12 aylık dönem, sağlıklı beyin gelişimi için son derece kritiktir. Bu dönemde nasıl bir ortamda büyüdüğü, çevresindeki insanlarla, özellikle de sizinle nasıl bir iletişimde olduğu, beyninin şekillenmesinin temellerini atar. Bu açıdan bebeğin maruz kaldığı uyaranların ne kadar uygun ve çeşitli olması; bilişsel, duygusal, sosyal ve fiziksel gelişimini etkilemeye devam eder. Sizinle bebeğiniz arasındaki iletişim, onun duyuları tarafından bir uyaran olarak algılanır. Bu uyaranlar ne kadar çok verilirse bebek o kadar çok gelişir. Gelişimi açısından bu uyaranları eksik etmemeli ve onunla sürekli etkileşimde olmalısınız. Bazı bilimsel araştırmalara göre bebeklerin beynini geliştiren en önemli etken insan sesidir. Öyleyse bugün hafif bir müzik açıp bebeğinize masaj yapın ve bu sırada ona gününüzün nasıl geçtiğini, yaşadıklarınızı ve onu ne kadar çok sevdiğinizi anlatın. İyi eğlenceler! 😊') WHERE id = 'b51f395b-32bc-4a20-bb23-ec95e7590add';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeklik ve çocukluk çağında en sık görülen cilt hastalıklarından biri de atopik dermatit egzamasıdır. Bu cilt rahatsızlığının tetikleyicileri; bakteriler, deterjanlar, mevsim geçişleri ve çeşitli alerjen maddelerdir. Bebeğinizde bu durumun oluşmasını önlemek için bazı önlemler almalısınız. Cildinin çok hassas olduğu bu dönemlerde onu yün giysilerden, toz ve kumdan, sabundan, içeriği temiz olmayan kozmetik ürünlerden ve deterjanlardan uzak tutmanız gerekir. Aldığınız giysiler yıkanmadan giydirildiğinde de bu cilt rahatsızlığı ortaya çıkabilir. Bu yüzden bebeğin hassas cildi için pamuklu giysileri tercih etmeli, yıkarken tahrişe yol açacak ovma hareketlerinden kaçınmalısınız. Bebeklikte egzamayla kendini gösteren bu cilt hastalığı, önlem alınmaz ve ortaya çıktığında tedavi edilmezse ileride solunum alerjilerine, astıma ve el egzamasına dönüşebilir.') WHERE id = '31c813fe-83a6-475d-b451-c6545ed0cadd';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Mamayı bebeğin beslenmesinde tek başına kullanabileceğiniz gibi, sütünüzün yetersiz olduğu durumlarda doktorunuzun önerisiyle ek olarak da verebilirsiniz. Ancak bebeğiniz için herhangi bir şekilde mama kullanıyorsanız dikkat etmeniz gereken önemli noktalar var. Bunların başında elbette içerik olarak anne sütüne en yakın mamanın seçilmesi gelir. Bu açıdan doktorunuzun önerisine kulak vermeli ve içerikleri iyi araştırmalısınız. Özellikle daha önce duymadığınız ya da doktorunuzun önermediği markaları kullanmaktan kaçınmalı, mamayı üreten firmanın etik kurallara uymasına önem vermelisiniz. Bu aşamada hâlâ farklı marka mamalar deneyebilirsiniz. Zamanla onun en sevdiği ve bağırsak sorunlarına yol açmayan mamayı mutlaka bulacaksınız. Bağışıklık sisteminin gelişimi ve bağırsak florasının sağlığı açısından, aldığınız mamanın içeriğinde laktobasil ve bifidobakteri gibi faydalı mikroorganizmalar içeren probiyotiklerin olduğundan emin olmalısınız. Ayrıca kullandığınız mamada bir yağ asidi olan LC-PUFA''nın bulunması, sitokin üretimini artırarak bağışıklık sisteminin düzenlenmesini sağlayacaktır.') WHERE id = '20390cc9-8cbc-4417-abec-6230f65f2f2f';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz için hem çok eğlenceli hem de gelişimi açısından son derece önemli bir etkinlik var: Aynaya bakmak! 😊 Büyüklerimiz bebekleri aynaya baktırmaktan çekinse de doktorlar bunu şiddetle öneriyor. Bebeğin aynaya bakması, kendini görüp keşfetmesine, dolayısıyla beyin gelişimine büyük katkı sağlar. Bu etkinliği ilk kez yapacağınız zamanı doğru seçmelisiniz. Bebeğin huzursuz ve keyifsiz olması, aynadan korkmasına yol açabilir. Bu yüzden keyfinin yerinde olduğu, karnının tok (ama çok dolu olmadığı) zamanlar bu oyun için idealdir. Aynanın karşısına geçin; bebeğe gözlerini, ellerini, ayaklarını, kollarını ve ağzını göstererek bu organlarını tanıtın. Tanıttıktan sonra sırayla dokunun ve bunu tekrarlayın. Bebeğiniz için çok ilginç bir oyun olacağına eminiz. İyi eğlenceler! 😊') WHERE id = 'b0d88192-6e24-4e64-b343-6477a77e7840';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeği emzirirken ağzını doğru kullanamadığını, beslenmenin uzun sürdüğünü, sık sık ara verdiğini, telaşlı olduğunu ve beklenen kiloyu alamadığını mı düşünüyorsunuz? Cevabınız evetse bebeğinizde dil bağı olabilir. Kontrol ettirmenizi öneririz. Dil bağı nedeniyle bebekler emerken memeyi tam kavrayamaz, yeterince beslenemez ve buna bağlı olarak kilo kaybedebilir. Ayrıca sütü veya biberonla aldığı besini dilleriyle geri itemedikleri için bazı beslenme bozuklukları da oluşabilir. Dil bağı; dilin ağız tabanına tutunmasını sağlayan bir doku parçasıdır. Dilin rahat hareket edebilmesi için bu dokunun dilden bir miktar ayrılması gerekir. Bazen, özellikle kalıtsal olarak bu ayrılma gerçekleşmez ve dilin hareketleri kısıtlanır. Doktorlar bunu her zaman kontrol etmeyebilir ve fark etmek de her zaman kolay olmaz. Ancak bebeğin doktoru tanıyı geç koysa bile bu, tedavi edilebilir bir durumdur.') WHERE id = '2904fd26-1eca-4d37-8e98-2e316a3eec9b';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin dişlerinin çıkmasına çok az kaldı; belki de henüz birkaç ay var. Diş çıkarma süreci boyunca bebeğin damakları inanılmaz derecede kaşınabilir, salyası akar, ellerini sürekli ağzına götürür ve bulduğu her şeyi çiğnemek ister. Kaşıntılara karşı diş kaşıyıcı, ağrılara karşı doktor önerisiyle diş jeli, akan salyalar için ise önlük kullanabilirsiniz. Ayrıca hem sizin hem de bebeğiniz için zorlu olan bu dönemi evdeki araçlarla kolaylaştırabilirsiniz. Nasıl mı? Evdeki temiz ağız bezlerini kullanarak! Bezi biraz nemlendirin, sonra soğuması için bir süre buzdolabında bekletin. Soğuk ve sertçe olması bebeğin ağrılarına çok iyi gelecek. Bunu bebeğin eline verirken mutlaka gözetim altında tutmanızı öneririz.') WHERE id = '8cafc042-a915-4258-a3c2-d05a6d6f4956';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz anne sütü veya mamayla beslense de aklınıza "acaba vücudunun suya ihtiyacı var mı?" sorusu gelebilir. Genel görüş, ek gıdaya geçmeden önce bebeklerin ek suya ihtiyacı olmadığıdır. Nedeni şudur: İlk 6 ayda temel beslenmeye ek olarak su verilirse bebeğin açlık-susuzluk hissi azalır. Susuzluk hissi azalan bebek anne sütünü veya mamayı daha az alır; bu da enerji eksikliğine ve gelişim geriliğine yol açabilir. Bu yüzden bebeğe düzenli su vermeye başlayacağınız dönem, ek gıdaya geçiş dönemidir. Yenilen besinlerin miktarı artıp kıvamı koyulaştıkça bebeğin vücudunun sıvı ihtiyacı da artacak. Bu noktada sıvı ihtiyacını karşılamanın en sağlıklı yolu sudur. Vereceğiniz su miktarı konusunda doktorunuza danışmayı unutmayın.') WHERE id = '8768c9bb-7bc9-40eb-8d2e-760fead026b4';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Birlikte geçen dopdolu 5 ay... Zaman ne kadar hızlı akıyor, değil mi? 😊 Günden güne gelişen ve sizi her gün şaşırtan bebeğinizin beşinci ayı da eşsiz ve çok ilginç geçecek. Bu aşamada bebeğin duyguları neredeyse bir yetişkin kadar gelişmiş durumda. Bu sayede iletişim becerisi ve kendini ifade etme yeteneği hızla ilerliyor. Yani artık bebeğin duygularını eskisine göre çok daha rahat ve kolay anlayabilirsiniz. 5. aydan itibaren bebeğiniz mutluluğunu, neyi beğenip beğenmediğini, huzursuzluğunu, sevgisini ve ilgi isteğini size açıkça göstermeye başlar. Örneğin sizi veya (mama alıyorsa) biberonunu görünce yemek vaktinin geldiğini anlayıp heyecanlanabilir, mutlu olduğunu çığlık atarak anlatmaya çalışabilir. Ayrıca hafızasının ve duygularının gelişmesinin bir sonucu olarak artık yabancılara karşı tedirginlik hissedebilir ve onlara daha temkinli yaklaşabilir.') WHERE id = '12aa96ec-7101-441e-a8b6-16b0a453ee5a';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz ilk 4 aya kıyasla bu ay daha hareketli olduğu için daha az kilo alması normaldir. Bu yüzden ilk aylardaki gibi ayda 800-1200 gramlık artış beklememelisiniz. 5. ayındaki bir bebek için 450-750 gramlık artış yeterli sayılır ve istisnalar dışında ek desteğe gerek olmadığını gösterir. 5. aydan itibaren bebeğin kilosu 5100-9000 gram, boyu ise 58-70 cm aralığında değişebilir. Unutmayın; erkek ve kız bebeklerin boy-kilo gelişiminde küçük farklar olur ve her bebeğin gelişimi kendine özgüdür. Bu değerlere göre bebeğinizde eksiklik ya da fazlalık olduğunu düşünüyorsanız doktorunuza danışmanızı öneririz. Ayrıca bebeğin doğum haftasının, doğduğu boy ve kilonun da bu göstergeleri etkileyebileceğini aklınızdan çıkarmayın.') WHERE id = '57b48e89-533e-4812-870a-767029538ffe';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz artık dikkatini çeken ve görüş alanındaki nesneleri almak için daha çok çaba gösteriyor. Yani ilgisini çeken bir nesneye karşı heyecanlanması, gülmesi, uzanmaya çalışması, el çırpması gibi davranışlar sergilemesi mümkün. Görme ve algılama yeteneği epey geliştiği için gördüğü renk ve şekil çeşitliliği, zihinsel bağlantılar kurmasına ve kavramasına yardımcı oluyor. Ayrıca bu ay bebeğin daha çok sosyalleştiğini göreceksiniz. Önceki aylarda kahkaha duymadıysanız bu ay duyma olasılığınız çok yüksek. Sosyalleşen bebek artık gıdıklanınca gülebilir ve çığlık atabilir. Mutlu anlarında kendi kendine cıvıl cıvıl sesler çıkarabilir. Bebeği güldürmenin bir başka yolu da gülümsemesine gülerek karşılık vermenizdir. Bu ayda bebekler karşılıklı gülmekten çok hoşlanır. Biberonunu emerken, siz başkasıyla konuşurken, şarkı açtığınızda ya da herhangi bir ses duyduğunda bunlar onu eğlendirir. "Agu"lamalar, çığlıklar ve kıkırdamalar bebeğiniz için konuşmanın ilk adımlarıdır. 😊') WHERE id = '57cd3a11-aa81-4f90-bfb2-f69a0e71ee24';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bu dönemde çevrede olup bitene dikkati biraz daha artan bebek, sesleri ayırt etmeye ve çevredeki seslere tepki vermeye başlıyor. Bu aydan itibaren bebeğin psikolojisi, özel önem vermeniz gereken konulardan biri. Bebeğiniz artık ilgi beklediğinde, canı sıkıldığında ya da sizinle temas kurmak istediğinde dikkat çekmek için ani çığlıklar veya bağırma şeklinde ağlama sesleri çıkarabilir. Dikkat çekmek için gösterdiği bu çabalar, sebep-sonuç ilişkisini başarıyla kurabildiğini gösteriyor. Bu açıdan bebeğinizle sakin konuşup onunla ilgilenmeye başladığınızda aniden ağlamayı kesip size gülümseyebilir. Bu, bir huysuzluk değildir ve endişelenmenize gerek yok. Henüz konuşma becerisine tam sahip olmadığı için rahatsız olduğu durumlarda bu şekilde dikkat çekerek derdini anlatmaya çalışıyor.') WHERE id = 'c9b55f11-f202-4070-8d6a-fc7359809c90';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeklerde boy ve kilo takibi kadar baş çevresinin izlenmesi de önemlidir. Baş çevresinin ölçülmesi, bebeğin beyin gelişimi hakkında fikir veren rutin bir işlemdir. Bebeğin baş çevresi bu aydan itibaren 39 cm ile 45 cm aralığında olmalıdır. Baş çevresinin gereken değer aralıklarında büyümesi, sağlıklı beyin gelişiminin göstergesidir. Bebeklerde beyin gelişimindeki bazı sorunlar çoğu zaman baş çevresinin normalden farklı ölçüleri sayesinde fark edilir. Ancak bebeğinizde baş çevresi gelişiminin az ya da fazla olması sizi hemen telaşlandırmasın. Bu durum beslenmeyle ilişkilendirilemeyebileceği gibi, belirtilen rakamların da kesin kural olmadığını söylemek isteriz. Her bebekte olduğu gibi sizin bebeğinizin de farklı bir büyüme potansiyeli var. Genetik olarak minyon olan bebeklerin baş ölçüleri sağlıklı olmalarına rağmen geriden gelebildiği gibi; iri yapılı bebeklerin baş ölçüleri kemik yapısına bağlı olarak daha önde olabilir.') WHERE id = '7475597a-0083-4ac8-af52-e9ec4b5f2395';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz artık sırtüstü yatarken bacaklarını havaya kaldırıyor ve onları hayranlıkla izliyor! Ayaklarını keşfetmeye çalışan bebek, çok yakında onları tutmaya başlayacak. Bizden söylemesi 😊 Bu aşamada bebeğin duyu organlarını uyaran oyunlar seçmek, gelişimini desteklemek açısından çok önemli. Bunun yanında bebeğin kendi bedenini tanımasına yardımcı olan oyunlar da bu dönemde çok işinize yarayacak. Bebeğin çoraplarını çıkarın ve ayak tabanlarını hafifçe gıdıklayın. Size gülümseyerek karşılık verdiğini göreceksiniz. 😊 Gıdıklama ve bunun sonucunda birbirinize gülmeniz; bebeğinizle aranızdaki iletişimi ve sıcaklığı güçlendiren sosyal bir bağlanma mekanizması oluşturur. Ayrıca bebeği gıdıklarken kahkahayla karşılık almanız, aranızdaki duygusal bağı da besleyecek. Ama her şeyin fazlasının zararlı olduğunu da hatırlatalım! :)') WHERE id = '85434c2c-c541-44d1-bc15-24301977fe06';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin gece beslenmesi ilk aylardaki gibi şimdi de önemlidir. Bebeğiniz geceleri uyanıyorsa ihtiyacına göre onu 3-4 saatte bir emzirmeli ya da biberonla beslemelisiniz. Ancak bebek uyuyorsa ve herhangi bir sağlık sorunu yoksa, onu sadece beslemek için uykudan uyandırmanızı önermiyoruz. Acıktığında bunu size zaten hissettirecek. İleride sağlıklı bir uyku düzeni kazanması için beslenmeyi uykudan hemen önce ya da hemen sonra yapmaktan kaçınmak gerekebilir. Bu yüzden bebeğin kendi kendine uykuya dalmasını teşvik etmeli ve ona destek olmalısınız. Bebeği emzirerek uyutmaya alıştırdıysanız ona biraz zaman tanıyın ve sabırlı olun. Kısa sürede her şeyin yoluna gireceğinden emin olabilirsiniz! :)') WHERE id = '25c161ab-8831-4065-a3ec-22240c22edb0';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz ses çıkarmayı artık iyice keşfetti. Eline geçen her şeyi sallayarak ses çıkarmaya çalışabilir; bu keşfinde ona yardımcı olabilirsiniz. Bebeklerin ses çıkarmaktan en çok hoşlandığı oyuncak çıngıraklardır. Mağazalarda çeşitli renk ve biçimlerde çıngıraklar bulabilirsiniz. Bunun yanında evdeki eşyalarla da kolayca kendi oyuncağınızı yapabilirsiniz. Bunun için iki plastik bardak yeterli. Bardakların içine evdeki kuru bakliyatlardan (pirinç, mercimek vb.) koyabilirsiniz. İçindekiler dökülmesin diye bardakların ağzını şeffaf bantla sıkıca kapatın. Farklı sesler elde etmek için iri ve küçük taneler kullanabilirsiniz. Örneğin pirinç taneleri daha ince, fasulye taneleri ise daha kalın ses çıkaracaktır.') WHERE id = 'c96c4837-c392-4247-ae1b-3dcef1d0e562';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Sizce de bebeğiniz son günlerde epey hareketli değil mi? Bu dönemde kol ve bacak kasları epey güçlendi. Sürünmeyi, dönmeyi ve nesnelerden tutunarak hareket etmeyi öğrenen bebek, hareket ettikçe kasları daha da gelişecek. Artık çok hareketli olduğu için güvenlik açısından onu belirli sınırlar içinde tutmalısınız. Örneğin onu yüksek bir yerde yalnız bırakmayın, çevresindeki sivri ve kesici eşyaları kaldırın. Bebeğiniz ilgisini çeken her şeyi başparmağı ve diğer parmaklarıyla kıskaç gibi tutabilir. Tuttuğu nesneleri tanımak amacıyla ağzına götürmek isteyecek. Bu yüzden boğulma tehlikesi yaratabilecek küçük oyuncakları, bozuk paraları ve boncuk gibi nesneleri ortalıkta bırakmamanızı öneririz.') WHERE id = '5d03d27f-629c-43d8-acc3-6fa2f69ef287';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz dokunuşlarınıza ve sizinle kurduğu temasa karşı çok duyarlıdır. Cildinde dokunma duyusunun uyanması sonucunda beynini ve sinir sistemini uyaran milyonlarca küçük sinir ucu bulunur. Bu sinir uçları; koltuk altı, ayak tabanı, karnı ve boynu gibi daha hassas bölgelerinde daha yoğundur. Bebeğin tam da bu bölgelerine dokunduğunuzda sinir uçları uyanır; sonuçta beyin tarafından gıdıklanma, ürperme ve gülme gibi tepkiler oluşur. Bu sırada bebeğin kan basıncı artar, kalp atışları hızlanır ve beyni daha aktif hâle gelir. Örneğin bebeği gıdıklamanız hem eğlencelidir hem de dokunma duyusunu daha iyi kavramasına yardımcı olur. Unutmayın; gülmek, bebeğin mizah duygusunun gelişiminde ilk adımdır. 😊') WHERE id = '541bc5b2-12fd-4d41-9d69-7d5b93ee3f92';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz bu aylarda genellikle oturur pozisyonda durmayı seviyor. Henüz oturmak için denemiyorsa bile bu an meselesi! 😊 Otururken dengesini korumak ve kendine destek olmak için ellerini kullanan bebek, sırt kasları tam gelişmediği için biraz kambur durabilir. Bazı doktorlar oturma alıştırmalarına 6 aydan önce başlamayı önermiyor. Buna rağmen bazı uzmanlar bebeğin isteğine ve gelişimine göre daha esnek yaklaşabiliyor. Yine de bebeğin güvenliği için oturma denemelerini kısa tutmakta ve kucağınızda oturtmakta fayda var. Bebeğiniz her gün güçlense de onu şimdilik desteksiz oturtmaya çalışmak bazı sorunlar yaratabilir. Gelişimle ilgili en doğru bilgiyi doktorunuz verecektir. Bu yüzden oturma, ek gıda ve vitaminler gibi konularda doktorunuza danışarak hareket etmelisiniz. 😊') WHERE id = '3d5e88a5-68ba-47fd-b5a0-88c276587011';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin sağlıklı büyümesi ve gelişmesi için doğru beslenme çok önemlidir. Doğduğu andan itibaren protein, karbonhidrat, yağ, vitamin ve mineralleri dengeli şekilde ve ayına uygun miktarda almalıdır. 0-12 ay arası en hızlı büyüme dönemi olduğu için enerjiye olan ihtiyacı daha fazladır. Bu dönemde bebeğin vücudunda yeni dokuların oluşması ve kasların gelişmesi nedeniyle protein, mineral ve vitaminlere talebi artar. Vücut dokularının büyümesi sürekli protein sentezi gerektirdiğinden, bebeğiniz için kaliteli protein alımı şarttır. Sütünüz bebeğiniz için muhteşem bir protein kaynağıdır ve sütünüzdeki proteinlerin sindirilme oranı %95''e ulaşabilir. Bu yüzden emzirme döneminde sizin de sağlıklı ve dengeli bir beslenme planına bağlı kalmanız, bebeğin gelişiminin sürekliliği açısından büyük önem taşır.') WHERE id = '896cbb45-0cf7-4486-ad2b-a52c32d44051';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Şu anda herhangi bir sıçrama döneminde olmasanız bile bebeğiniz uykuya dalmakta zorlanabilir. 5 aylık bebeğin uyku düzeni, her gün yeni hareket becerileri kazanması nedeniyle biraz bozulabilir. Bebek yeni kazandığı bu becerileri denemek için uykuyu ve beslenmeyi reddedebilir, sizi sabahları erken uyandırabilir. Bebeğiniz uykudan uyandığında ağlamıyor, yatağında kendi kendine oynayıp vakit geçiriyorsa, akşam onu yatırırken yanına bir uyku arkadaşı koyabilirsiniz. Bir süre sonra bebek, yanına koyduğunuz bu oyuncağı her gördüğünde uyku refleksi göstermeye başlayacak. Bu alışkanlığın doğru oturması için uyku arkadaşını yataktan çıkarmamalı, yalnızca uyku vakti gelince yanına koymalısınız. Uyku arkadaşı seçerken oyuncağın organik ip ya da kumaştan olmasına, zararlı boya veya yutabileceği küçük parçalar içermemesine dikkat etmelisiniz.') WHERE id = '1fa3a9be-2b21-41b0-8e90-923545dc6c0e';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeklerde diş çıkarma dönemi genellikle 5. aydan itibaren başlar. Bebeğiniz henüz diş çıkarmadıysa bu ay içinde diş sancılarıyla karşılaşabilirsiniz. Diş çıkarma doğal bir süreçtir; ancak bu süre boyunca bebek oldukça huzursuz olabilir. Bu huzursuzluk diş etlerinin kaşınmasından kaynaklanır ve zaman zaman ağrılara yol açabilir. Bebeğin ağzında ilk dişleri genellikle 5-9. aylar arasında görmek mümkündür. Bazı bebekler ilk dişlerini 3. ayda çıkarabilirken, bazıları için bu süreç 13-14. aya kadar uzayabilir. Bebeğin sağlığında bir sorun yoksa diş çıkarma hızının büyüme ve gelişmesiyle doğrudan bir ilişkisi yoktur. Bu durum daha çok genetiktir ve muhtemelen anne-baba olarak sizin bebekliğinize benzer şekilde ilerleyecektir.') WHERE id = '2b63b86d-359a-4b54-8d2d-d3bc2859ca20';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin saçları çok hassas ve naziktir; bu yüzden saç bakımı günlük temizliğin önemli bir parçası olmalıdır. Bebeğiniz gür saçlı ya da seyrek saçlı doğmuş olabilir. Hatta saçsız doğmuş ve saçları yeni çıkmaya başlamış da olabilir. Her hâlükârda bebeğin saçları ve saç derisi özel bakım ister. Bebeği yaz aylarında her gün, kış aylarında ise iki-üç günde bir yıkayabilirsiniz. Alerji, kızarıklık ya da kaşıntıyı önlemek için kimyasal içerikli market ürünlerinden uzak durmalısınız. Paraben, sülfat, sentetik kokular ve bebeğin cildini tahriş edebilecek zararlı maddeler içermeyen ürünler kullanmalısınız. Temiz içerikli ürün bulmakta zorlanıyorsanız kaliteli doğal kalıp sabunları ya da sıvı kastil sabunlarını da tercih edebilirsiniz.') WHERE id = '9f4a8a9d-785a-42f3-bcb2-0880d1571c96';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin ek gıdaya geçiş zamanı, doğması beklenen tarihten 180 gün sonrasına denk gelir. Bu da 6. ayın sonunun ek gıdayla tanışmak için en uygun zaman olduğu anlamına gelir. Bazı durumlarda doktorların önerisiyle ek gıdaya daha erken geçilebilir; çünkü bebekler yutma refleksini artık öğrenmiş olur. Yine de bağırsak florasının sağlığı için, gelişiminde bir gecikme yoksa biraz daha beklemek daha doğru olur. 5. ayda bebeğinize verebileceğiniz ek gıdalar mutlaka sıvı hâlde olmalıdır; püre için biraz daha beklemelisiniz. Doğal hazırlanmış sebze çorbalarının suyu ve alerjik olmayan meyve suları bebeğiniz için uygun olabilir. Besin alerjisi riski nedeniyle, bebeğin ilk kez tadacağı besini 1 çay kaşığı gibi çok az miktarda vermeniz önerilir.') WHERE id = '57b7991c-272a-4ed5-898c-f9700be1db2a';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğinize masaj yapmanız kan dolaşımının hızlanmasına, kas ve kemiklerinin daha iyi gelişmesine zemin hazırlar. Ayrıca oluşabilecek gaz ve sancı (kolik) sorununun çözümüne yardımcı olarak onu sakinleştirir. Bebek masajında temel amaç; doğru teknikle bebeği rahatlatmak ve düzenli uygulayarak büyümesine, zihinsel ve motor gelişimine olumlu katkı sağlamaktır. Özellikle 4. aydan sonra yapılacak basit egzersiz hareketleri bebeğin gelişimi için çok önemlidir. Masajı her gün, bebeğin aç olmadığı, sakin ve masaja hazır olduğu zamanlarda yapmalısınız. Bunun için en uygun zaman beslenmeden 1-1,5 saat sonrasıdır. Masaja başlamadan önce ellerinizdeki takıları çıkarmayı unutmamalı, tırnaklarınızın uzun olmamasına dikkat etmeli; elleriniz temiz ve ılık olmalıdır. Ayrıca masaj sırasında oda sıcaklığını iyi ayarlamalı ve bebeği asla yalnız bırakmamalısınız. İyi eğlenceler! 😊') WHERE id = '98edcdb5-d642-4617-8cc5-e7bd1fc8f734';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeklerin diş çıkarma dönemini rahat geçirmesi için diş jelleri sık kullanılan bir yöntemdir. Ancak ağrı kesicilere ve jellere başvurmadan diş belirtilerini azaltmanın birçok etkili yolu var. Diş kaşıyıcılar, bebeğin çok seveceği ve işine yarayacak yardımcılardır. Buzdolabında soğutulduklarında daha etkili olduklarını unutmamak gerek. 😊 Ayrıca bu kaşıyıcıların diş etine teması, masaj etkisi ve serinlik yaratarak bebeğin ağrılarını hafifletebilir. Başka bir yöntem olarak bebeğin ağız bezini nemli ya da kuru hâlde buzdolabında yarım saat beklettikten sonra çiğnemesi için ona verebilirsiniz. Soğuk bir nesnenin diş etine teması; ağrıyı, şişliği ve hissettiği basıncı azaltabilir. Ancak her iki yöntemde de mikrop bulaşma olasılığını düşünerek ciddi bir sterilizasyon yapmanızı öneririz. 😊') WHERE id = '61a39689-4f67-40ed-b7d3-3829e2076603';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz bu ay boyunca vaktinin ortalama 15 saatini uykuda geçiriyor. Bunun genellikle 10 saati gece, 5 saati gündüz uykusudur. Ancak bazı nedenlerle bebek daha az uyuyabilir, uykuya dalmakta zorlanabilir ya da uyku sırasında sık sık uyanabilir. Uykudan önce bebeği yıkamak, uykuya geçişini kolaylaştıran en güzel rutinlerden biridir. Ayrıca uyku öncesi rahatlatıcı masaj yapmak, masal okumak ya da birlikte renkli bir kitabın resimlerine bakmak da uyku rutinine eklenebilir. Uykuya hazırlık sırasında odadaki ışığın loş olması bebeğin uykuya dalmasını epey kolaylaştırır. Normal şartlarda bebek gece uykusundayken acıkırsa beslenmek için uyanabilir. Gece beslenmesi bebeğin gelişimi için hâlâ çok önemlidir. Bu yüzden endişelenmemeli, bebeğin hâlâ hızlı büyüme döneminde olduğunu bilmelisiniz.') WHERE id = '388b1d4a-2870-47fb-8a38-2987cb7bbaf9';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz için oyun ve oyun oynayarak geçirdiği zaman; hem çok eğlenceli bir etkinlik hem de gelişimi için son derece önemli bir süreçtir. Bu açıdan oyuna sadece bebeğinizle eğlenceli vakit geçirdiğiniz bir uğraş olarak bakmamalısınız. Oyun oynayarak geçirdiğiniz zaman, paha biçilmez bir eğitim ve öğrenme sürecidir. Üstelik bebeğin duyguları artık iyi şekillendiği için oyun sayesinde hem enerjisini en doğru biçimde harcıyor hem de dış dünyayı tanıyor. Oyunun bir diğer işlevi de nesneleri, kavramları, nesneler arasındaki benzerlik ve farklılıkları öğrenmesine yardımcı olmasıdır. Bu yüzden bebek oyun oynarken aynı zamanda bazı beceriler kazanıyor ve öğreniyor. Ayına uygun olarak renkleri, şekilleri, adları ve boyutları doğru kavrayabilmesi; ileriki yıllarda ilişkileri, sosyal rolleri ve taklitleri öğrenerek kişiliğinin gelişmesine yardımcı olur.') WHERE id = '64ce3005-26f0-4a9c-b4db-77907d346329';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğinizde hafif ateş, eline geçen her nesneyi ağzına götürüp çiğneme isteği, kulağını ovuşturması, iştah azalması ve bol miktarda salya akması gibi durumlar var mı? Cevabınız evetse tebrikler! Bir çift inci dişe kavuşmaya çok yakınsınız. 😊 Bu belirtiler diş çıkarma belirtileridir ve bebeğin 5. ayına girmesiyle birlikte dişlerinin çıkması an meselesidir. İlk dişler çıkmadan önce bebeğin ağrılı, kızarmış ve şişmiş diş eti onu rahatsız edebilir. Bu semptomlar, çıkmaya hazırlanan dişin diş etini yardığı ve diş patlaması denilen durumdan yaklaşık 3-7 gün önce ortaya çıkar. İyi haber şu ki diş, diş etinden ilk göründüğü anda bu rahatsız edici belirtiler hemen sona erer. Unutmamanız gereken nokta ise şudur: bebeğinizde gördüğünüz bu belirtilerin dişle ilgili olduğundan emin değilseniz mutlaka doktorunuza danışmalısınız.') WHERE id = 'd5ac321f-14e0-45ad-ab92-652807702fa6';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz kısa sürede hızla gelişse de vücudunu zararlı etkilerden koruyan faydalı mikroorganizmalar, yani cilt florası henüz tam oluşmadı. Cildinin pH değeri hâlâ yüksektir ve cildi örten koruyucu keratin tabakası tam gelişmemiştir. Bu durum, asitliği düşük ve koruyucu bariyeri henüz tam oluşmamış bebek cildinin mikroplara ve kimyasal maddelere karşı daha hassas olmasına yol açar. Bu yüzden bebeğin cildine temas eden giysilerin yıkama sıcaklığına, deterjan ve yumuşatıcı seçimine özel dikkat göstermelisiniz. Örneğin giysileri yıkarken bebeğin hassas cildinde kızarıklık ve kaşıntı olmaması için doğal içerikli deterjanları tercih etmeniz önemlidir. Ayrıca içinde parfüm gibi birçok kimyasal madde bulunduğu için çamaşır yumuşatıcılarından uzak durmalısınız. Bebeğin giysilerindeki mikropları tamamen temizlemek için yıkandıktan sonra onları mutlaka ütülemeyi unutmayın.') WHERE id = 'd86eb88e-f066-48c6-be2d-d43e207dbd2c';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bir oğlunuz varsa muhtemelen ne zaman sünnet olacağıyla ilgili aklınızda bazı sorular var. Sünnet, dünyada en eski çağlardan beri uygulanan işlemlerden biridir. Bu işlem, idrar kanalının ucunu örten deri tabakasının kesilip alınmasıdır. İstatistiklere göre dünyada her üç erkekten biri sünnetlidir. Sünnetin ne zaman, nasıl ve kim tarafından yapılması çok önemlidir. Bebekler doğduğu andan itibaren gündeme gelen bu konu için ideal yaş hakkında farklı görüşler vardır. En uygun yaş aralığıyla ilgili kesin bilimsel kanıt olmasa da bazı uzmanlar, özellikle psikolojik travma yaşanmaması için bunun erken yaşlarda yapılmasını öneriyor.') WHERE id = '05f311d5-ad4e-4d35-963b-6bea5a4bcff4';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin başında yer alan bıngıldak nedeniyle o bölgeye dokunmaktan çekiniyor olabilirsiniz. Başta toplam 6 adet olan bıngıldak bölgesi diğer yerler gibi sert olmadığı için anneler genellikle oraya dokunmaktan korkar. Oysa bıngıldak, sağlam bağ dokusundan oluşur ve bebeğin beynini güvenle korur. Bu yüzden bebeği yıkarken, saçlarını tararken ya da başını tutarken endişelenmeye ve dokunmaktan kaçınmaya hiç gerek yok. Bıngıldak, bebeğin güvenliği için önemli olmasının yanı sıra kafa travmalarına karşı koruyucu kask görevi de görür. Bıngıldağın kapanması genellikle 9-18 ay arasında, müdahaleye gerek kalmadan kendiliğinden gerçekleşir. Bu süre 24 aya kadar uzayabilir ya da daha erken kapanabilir. Bu tür durumlar genellikle sorun yaratmaz; ama her ihtimale karşı doktorunuza danışmanızda fayda var.') WHERE id = '8c311ff4-c1cb-4399-88d9-4dbb31f984b6';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin beyin hücreleri arasında bağlantıların kurulması sonucunda algısı epey gelişti. Bu sayede artık yeni beceriler kazanıyor. Bunların en ilginci ise adının söylendiğini ve ona seslenildiğini artık anlaması! 😊 Doğduğu andan itibaren ona adıyla hitap edilmesi, bebeğin bu sesleri beynine yazıp hatırlamasına yardımcı olur. Aynı sesleri sık sık duyan bebek artık kendi adını tanıyabiliyor. Gelişimin bir başka sonucu olarak aile üyeleriyle yabancıları birbirinden ayırt edebiliyor. Bu yüzden bebek bir yabancı gördüğünde yadırgayabilir, durumu anlamaya çalışırken dudaklarını büzebilir ve ağlayabilir. Hatta ortalığı birbirine katabilir. Hazırlıklı olun, bizden söylemesi! 😊') WHERE id = '2af2018e-44d1-408e-a2eb-5673d76e91c6';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bu aralar bebeği uyutmakta zorlandığınızı biliyoruz. Yenidoğan döneminde karnını doyurmak ve altını temiz tutmak, iyi uyuması için yeterliydi. Ama artık dış dünyayı daha iyi anlayan ve duyguları gelişen bebeği uykuya hazırlamak biraz zor olabilir. Bu açıdan yalnızca fiziksel ihtiyaçlarını karşılamak, kendi kendine uykuya dalması için artık yetmiyor. Beyni çok aktif çalışan bebeği uykuya hazırlarken onu her tür gürültüden uzak tutmalısınız. Televizyon sesi ya da konuşma sesleri onu uyanık tutabilir. Rahat uykuya geçebilmesi için bu etkenleri ortadan kaldırmak gerekir. Ayrıca odanın çok sıcak ya da çok soğuk olması uykuya geçişi geciktirebilir ve uyku kalitesini düşürebilir. Bebeğin uyuduğu odanın sıcaklığının 22-24°C olması idealdir. Tatlı rüyalar! 😊') WHERE id = '1a8c9918-d018-4b4c-8f7f-c8a0898c2b43';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bu ay boyunca bebeğin gelişimine uygun olarak birlikte yapabileceğiniz birçok etkinlik var. Şimdiden iyi eğlenceler! 😊 Öncelikle, aynalara büyük ilgi gösteren bebeğiniz için aynalı oyunlara ne dersiniz? Bir aynayı elinize alın ve aynanın karşısında dururken bebeğin ellerine sırayla oyuncak top verin. Böylece bir süre sonra bebek, oyuncağı bir elinden diğerine geçirmeyi öğrenecek. Başka bir etkinlik olarak, dikkatini çekecek renkli bir topu yerde aşağı yukarı zıplatın. Bebek, ilgisini çeken topu gözleriyle izlemeyi kısa sürede öğrenecek. Devamında elinizdeki topu duvara doğru yuvarlayın ve duvara çarpıp geri gelmesini sağlayın. Bebeğiniz topun duvardan sektiğini gözlemleyerek öğrenecek.') WHERE id = 'd9644453-95a5-4346-bbea-e0599b06e143';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Ek gıdaya geçiş dönemine epey yaklaştığınız bu günlerde dikkat etmeniz gereken en önemli konulardan biri de bebeğin yeterince prebiyotik alıp almadığıdır. Prebiyotikler bebeğin organizmasında bağışıklık işlevlerini geliştirir, hastalıklara karşı direncini artırır ve sindirim sistemine de iyi gelir. Ayrıca ek gıdayla birlikte alınan prebiyotikler, en güçlü prebiyotik kaynağı olan anne sütünün işlevlerini de destekler. Bu açıdan prebiyotik ve probiyotik bakımından zengin besinlerin başında yoğurt gelir. Yoğurt, sütün mayalanmasıyla oluşan, beyaz ve koyu kıvamlı bir süt ürünüdür. Süt şekeri olan laktozun, yoğurt mayasının etkisiyle kısmen laktik aside dönüşmesiyle oluşan pıhtılaşmış süttür. Kalsiyum, protein, B12 ve B6 vitaminleri açısından zengin olması sayesinde yoğurt, anne sütüyle birlikte bebeğin vücut direncini sağlayacak en önemli besinlerden biridir.') WHERE id = '67e55468-7559-4a60-ab60-67f55f552e34';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğin giysilerinin yıkanmasında dikkat etmeniz gereken bazı noktalar var. Bunların en önemlisi, yıkamada kullanacağınız deterjanların özellikleri ve seçimidir. Piyasadaki bazı deterjan ve sabunların yetişkinler için bile alerjik olabildiğini düşünürsek, söz konusu bebeğin hassas cildi olduğunda bu risk daha da artıyor. Uzmanlar, bebeklik döneminde kullanılan bazı kimyasal maddelerin yıllar sonra bile alerjik reaksiyona yol açtığını özellikle vurguluyor. Bu yüzden bebeğin giysilerini yıkarken yumuşatıcılardan, çamaşır suyundan ve cildi tahriş eden parfümlü ürünlerden uzak durmalısınız. Piyasada bebekler için özel üretilmiş çok sayıda deterjan ya da granül sabun bulunuyor. Bunlar arasında kokusuz olanları tercih etmeniz, olası cilt tahrişlerinin önüne geçecektir.') WHERE id = 'abaadbfc-c35e-4cb0-b8bc-31d98a9f8ecf';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz için gündüz uykusu son derece önemlidir ve bu aşamada gününün 4-5 saatini gündüz uykusuna ayırmalıdır. Araştırmalara göre, yaşına uygun şekilde yeterli gündüz uykusu alan bir bebeğin geceleri çok daha uzun uyuyabildiği belirlenmiştir. Uzmanlara göre özellikle günün ilk iki gündüz uykusu en verimli uykulardandır. Bu ilk iki uyku, bebek için daha güçlendirici ve vücudu yenileyici bir etkiye sahiptir. Ayrıca bebekler günün ilk uykusuna, diğer gündüz uykularına göre daha kolay dalabilir. Bu yüzden günün ilk saatlerindeki bu verimli uyku dalgasını kaçırmamalı, bebek uyku sinyalleri verdiği anda uyumasına yardımcı olmalısınız. Ancak unutmayın; ihtiyacından fazla gündüz uykusu, gece uykularını olumsuz etkileyebilir.') WHERE id = '59732708-2d13-4639-9614-435d122c79cb';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, '6. ay, bebeğin hayatındaki en önemli dönüm noktalarından biridir. Artık bağımsız bir varlık olduğunun farkında olan bebek, başkalarıyla iletişim kurmanın inceliklerini de öğrenmeye başlıyor. Bu açıdan bebek ilk kez kendi kişiliğiyle ilgili ipuçları ediniyor. Bu, son derece önemli bir zihinsel gelişimdir. 😊 Duyularını aktif kullanmasının yanı sıra, artık hafızasında biriktirdiği deneyimlerden kendine özgü sonuçlar çıkarmaya başlıyor. Örneğin oyuncaklarının arasından en sevdiğini seçebilir ve bunu sizin de anlamanızı sağlayabilir. Ayrıca bebek bir süredir net görmeye başlamış olsa da bu aydan itibaren oldukça karmaşık görüntüleri bile algılayabiliyor. Bu sayede yeni şekil ve dokuları da etkili biçimde ayırt edebilecek.') WHERE id = 'b6d7faf8-f7c6-4e9e-a7ff-43facd4aa9db';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bu ay sizi ve bebeğinizi yeni deneyimler ve değişiklikler bekliyor. Bebeği hastalıklardan korumak için doğumdan itibaren aşılarını zamanında yaptırmak çok önemlidir. Aşı yoluyla bebeğin organizmasına, korunması hedeflenen hastalığın zayıflatılmış bakteri ya da virüs formu verilir. Bu işlem bağışıklık oluşturmayı amaçlar ve bebeğin vücudu o hastalıklara karşı antikor üretmeye başlar. Böylece ileride bebek bu mikroplarla karşılaştığında vücudu artık güçlü bir savunma mekanizmasına sahip olur. 6. ayın aşı takviminde Hepatit B''nin üçüncü dozu, beşli karma aşının üçüncü dozu ve OPA (ağızdan çocuk felci) aşısının birinci dozu yer alır. Ayrıca bebeğin ilk kez karşılaşacağı çocuk felci (poliomiyelit) aşısı da buna eklenmiştir. Tüm bunlarla birlikte bebeğin ilk 6 aylık aşı takvimi tamamlanmış olur.') WHERE id = '95f9ad1b-63d6-45ba-b708-bf282b104620';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Aşılar bazen huzursuzluk, kusma, ateş ya da ağlamaya yol açsa da bebeği aşağıda bahsedeceğimiz ciddi hastalıklardan korumak için son derece gereklidir. Öncelikle çocuk felcine (poliomiyelit) "polio" virüsü neden olur. Bu virüs sinir sistemine zarar vererek kalıcı felce, hatta ölüme yol açabilir. Her yaşta görülse de özellikle bağışıklığı tam gelişmemiş 3 yaş altı çocuklar risk altındadır. Sağlık kurumlarının bu alandaki sıkı denetimi ve aşı kampanyaları sayesinde bu hastalığın önüne neyse ki büyük ölçüde geçilmiştir. Difteri ise solunum yollarına, sindirim sistemine ve kalbe zarar veren, ölümle sonuçlanabilen ciddi bir hastalıktır. Tetanoz; paslı metal, kirli toprak ve delici aletlerle yaralanmalarda ortaya çıkan ve doğrudan sinir sistemini etkileyen tehlikeli bir hastalıktır. Menenjit ise yüksek ölüm riskinin yanı sıra engellilik, zihinsel gerilik, sağırlık ve körlük gibi ağır sonuçlara yol açabilir. Bu yüzden aşı, bebeğin sağlıklı geleceği için en güvenilir kalkandır.') WHERE id = '2ec370c7-9d55-4f76-86f5-a1d0c2080600';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Her gün yeni hareketleriyle sizi şaşırtan bebeğiniz, gelişen sırt kasları sayesinde artık desteksiz oturmaya hazırlanıyor. Oturmaya hazır olduğunu hissediyorsanız ve bundan eminseniz ona biraz yardım edebilirsiniz. Önce onu kucağınızda oturtun ve ellerinden tutarak başını dik tutmasını kontrol edin. Daha sonra koltuğa oturtup çevresine yastıklar dizerek dengede kalmasına destek olabilirsiniz. Bu alıştırmalar sırasında bebek bazen yorulup yana devrilse de endişelenmeyin. Kasları güçlendikçe ve denge duygusu geliştikçe oturma süresi de uzayacak. Bir süre sonra dengesini kendi başına koruduğunu ve desteksiz oturduğunu göreceksiniz. İşte o zaman yastıklara gerek kalmayacak! 😊') WHERE id = '4613232a-c667-47df-9951-c91586b62ee3';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, '6. ay hem sizin hem de bebeğiniz için yeniliklerle dolu, sürprizli bir dönüm noktasıdır. Artık bebeği ek gıdayla tanıştıracağınız için çok heyecanlı olduğunuzu biliyoruz! Dünya Sağlık Örgütü ve sağlık uzmanları, bebeklerin 180 günü doldurduktan sonra sindirim sisteminin ek gıdaya hazır olduğunu bildiriyor. İlk 6 ay boyunca bebeği yalnızca anne sütü veya mamayla beslediniz. Şimdi ise organizması farklı içerikli besinlerle tanışacak; bu yüzden bazı alerjik reaksiyonlar olabilir. Bu nedenle ek gıdaya geçerken yumuşak bir geçiş yapmanızı, sindirim sistemini yormamak için acele etmemenizi öneririz. "Tarifler" bölümümüz bu lezzetli macerada size çok yardımcı olacak. Afiyet olsun! 😊') WHERE id = '1057a1b2-3687-4581-b2fe-6f0fca8b4778';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz ve sizin için oldukça heyecan verici olan ek gıda dönemi geldi! Peki, her şey hazır mı? Bebeğinizin ek gıdaya hazır olduğunun en önemli göstergelerinden biri, elbette artık oturabiliyor olmasıdır. Bu nedenle iyi bir mama sandalyesine ihtiyacınız olacak. Mama sandalyesi deyip geçmemelisiniz; burası bebeğiniz için yalnızca yemek yenen bir yer değildir. Bebeğinizi mama sandalyesinde yemek yemeye alıştırmanızın birçok önemli nedeni vardır. Bu sandalyeler, her şeyden önce bebeğinizin sizinle aynı masada oturmasını sağlar. Aile üyeleriyle aynı sofrada olmak, bebeğinizle daha fazla iletişim kurmanıza ve aranızdaki bağın güçlenmesine yardımcı olur. Mama sandalyesi seçerken güvenli, rahat, hafif ve kaliteli malzemeden üretilmiş olmasına mutlaka dikkat edin.') WHERE id = 'f8f5f75d-b030-4498-b7d5-7b4bc417016c';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bu aydan itibaren bebeğinizin günlük uyku süresi yaklaşık 13 saattir. Gündüzleri iki kez uyuması beklenir. Geceleri ise 6-7 saat kesintisiz uyuyabilir. Bebeğiniz büyüdükçe uyku ihtiyacı bir miktar azalacaktır. Bunun nedeni, büyümeyi sağlayan hormonların özellikle gece uykusu sırasında salgılanmasıdır. Bu aşamada bebeğinizin kendi kendine uyumaya alışması da beklenir. Yani hâlâ onu sallayarak, emzirerek veya gezdirerek uyutuyorsanız, bunları kısa süre içinde azaltmanızı ve bırakmanızı öneririz. Bazı uzmanlar, bebeklerin sağlıklı bir gece uykusu düzeni oluşturabilmesi için her ağladıklarında müdahale edilmemesini tavsiye eder. Bu nedenle bebeğinizin karnının tok, altının temiz olduğundan ve herhangi bir sorunu bulunmadığından eminseniz, her ağladığında hemen müdahale etmemelisiniz. Her ağladığında kucağa alınan bebek, kendi kendine uyuması gerektiğini öğrenemeyecektir.') WHERE id = '790745e1-b64b-4611-b8ea-ced2bd5bd141';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz artık daha dik oturabildiği için görüş alanı genişler ve çevresiyle daha aktif iletişim kurabilir. Bu durum, duyusal ve motor becerilerinin gelişmesine de yardımcı olur. Gelişimi devam ettikçe eğlenme ve keşfetme fırsatı sunan her şeye ilgisi artar. Örneğin, ince motor becerileri gelişmeye başlayan bebeğiniz artık küçük nesneleri parmaklarıyla veya başparmağıyla kavrayabilir. Ayrıca elindeki nesneleri bir elinden diğerine geçirebilir. Yanında olmayan ancak görüş alanındaki oyuncaklara uzanarak onları almaya çalışabilir. Düşürdüğü veya bıraktığı oyuncağı kendisi alamadığında size işaret ederek oyuncağını vermenizi isteyebilir. Ancak bebeğinizde bu gelişim aşamalarından bazılarını henüz gözlemlemeyebilirsiniz. Bunun nedeni her bebeğin gelişim sürecinin farklı olmasıdır ve endişelenmenize gerek yoktur.') WHERE id = '6730fee9-c4d4-4db1-af73-50d999349b75';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bu ay içinde doktorunuzun önerisiyle veya sağlık ocağından temin edeceğiniz demir takviyesini bebeğinize vermeye başlamanız gerekir. Dünyada en sık görülen besin eksikliği olan demir eksikliği, özellikle gelişmekte olan ülkelerde önemli bir sağlık sorunudur. Demir eksikliğinin aneminin yanı sıra yol açtığı en önemli sorunlardan biri, bebeklerin zihinsel gelişimini olumsuz etkilemesidir. Beynin hızla büyüdüğü ve temel psikomotor becerilerin kazanıldığı bebeklik döneminde ortaya çıkan demir eksikliği, zihinsel gelişimi yavaşlatabilir. Yapılan araştırmalara göre IQ seviyesi kalıcı olarak olması gereken düzeyin yaklaşık 5 puan altına düşebilir. Bu nedenle DSÖ, 6-12 aylık bebeklere demir takviyesi verilmesini önerir. Amerikan Pediatri Akademisi de bebeklerin 9-12 ay arasında bir kez kan tahlili yaptırarak demir seviyelerinin kontrol edilmesini tavsiye eder.') WHERE id = 'da861e51-ae52-40b6-a6f0-c4e0e3afd9bf';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Özellikle kolay sindirilen anne sütü veya formül mamayla beslenen bebeklerde ek gıdaya geçiş sırasında kabızlık sorunu sık görülebilir. Bebeğinizde kabızlıktan şüpheleniyorsanız bu noktaları dikkatle okumanızı öneririz. Öncelikle her bebeğin sindirim sistemi aynı hızda gelişmez. 6. ay tamamlandığında ek gıdaya başlamanıza rağmen kabızlık sorunu ortaya çıkabilir. Bu nedenle ek gıdaya bir süre ara verip daha sonra yeniden deneyebilirsiniz. Bu süre içinde bebeğinize sulu çorbalar veya meyve suları verebilirsiniz. Ek gıdaya başladığınız dönemde muz ve patates gibi kabızlığa yol açma olasılığı bulunan gıdalara dikkat etmelisiniz. Bu gıdaları verdikten sonra kabızlık geliştiğini düşünüyorsanız ilgili gıdaları bir süre vermemeniz gerekir. Ayrıca bebeğinizde kabızlık ve dışkılama sırasında zorlanma fark ediyorsanız makat bölgesinde çatlak olabilir. Böyle durumlarda doktorunuzla iletişime geçmeniz önemlidir.') WHERE id = '9037133c-00b1-4728-bfa8-d12451129dad';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğinizin mikrobiyota olarak adlandırılan bağırsak florası oluşumunu tamamlamak üzeredir. Bu dengenin devamlılığı için dikkat etmeniz gereken bazı noktalar vardır. Doğum sezaryenle gerçekleştiyse 8. günden, normal doğumla gerçekleştiyse 4. günden itibaren bebeğinizin bağırsak florasında sindirime yardımcı olan bakteriler oluşmaya başlar. Bağırsak florasındaki bu organizmaların bir kısmı yararlı, bir kısmı ise zararlı bakterilerden oluşur. Her iki bakteri türünün de bulunması, birbirlerinin aşırı çoğalmasını önleyerek sindirim sisteminde denge oluşturur. Bebeğinizin bağırsak florasını desteklemek için probiyotiklerden ve prebiyotiklerden yararlanabilirsiniz. Bu takviyeler, mutluluk hormonu olarak da bilinen serotoninin salgılanmasını da uyarır. Bebeğinizin beslenmesinde bu yararlı bakterileri içeren gıdalara yer verebilir veya paket hâlinde satılan probiyotikler hakkında doktorunuzdan bilgi alabilirsiniz.') WHERE id = '9e82ffd7-d409-49b6-a002-4b2672efef01';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğinizin aşı takviminde yer alan aşılar, vücudunda yapay olarak bağışıklık oluşturur. Bu bağışıklık, hastalığa neden olan mikroorganizmaların bebeğinizin vücuduna verilmesi ve bağışıklık sisteminin uyarılarak harekete geçirilmesiyle sağlanır. Bu nedenle bebeğinizin ilk kez karşılaştığı mikroorganizmalar vücuduna girdiğinde hafif bir rahatsızlık yaşayabilir; ancak aynı zamanda vücudu söz konusu hastalığa karşı bağışıklık kazanır. Hafıza hücreleri sayesinde aynı mikroorganizmayla tekrar karşılaştığında bağışıklık sistemi onu tanır. Aşılama yoluyla zayıflatılmış veya öldürülmüş mikroorganizmalar bebeğinizin vücuduna verilir. Bağışıklık sistemi bu şekilde uyarılır ve bebeğiniz gelecekte gerçek mikroorganizmayla karşılaştığında vücudu aktif biçimde savunma yapmaya hazır olur. Aşılar bebeğinizi hastalıklardan 100% korumasa da vücudunda hazır antikorlar bulunduğu için hastalıkları çok daha hafif geçirmesini sağlar.') WHERE id = '6a597987-e8b8-4f14-a6ec-55936a1409ea';
UPDATE public.baby_daily_info SET info_tr = COALESCE(info_tr, 'Bebeğiniz 6 aylık gelişim döneminde günde yaklaşık 11 saat uyuyabilir. Bu ortalama uyku süresi, bebeğinizin yalnızca geceleri uyuyacağı anlamına gelmez; gündüz uykusu da onun için hâlâ oldukça önemlidir. Amerikan Pediatri Akademisine göre bebeğin kendi odasına geçmesi ve sizden ayrı uyuyabilmesi için ideal dönem bu aydan itibaren başlar. Bunun nedeni, ek gıdaya geçen bebeğin anne sütüne bağımlılığının ilk aylara kıyasla nispeten azalmasıdır. Ancak bu geçişi çok hızlı yapmak bebeğin duygusal gelişiminde bazı sorunlara yol açabilir. Özellikle gece uyanan bebeğin korkması ve ağlaması sık görülen durumlardandır. Bebeğinizin bu yeni duruma alışabilmesi için ona zaman tanımalı ve süreci yavaş yavaş, sabırla yönetmelisiniz.') WHERE id = '68a677bc-c6fd-496b-bd7c-d65d75f316ae';